insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي يشتغل نظام Null Safety في Dart؟', 'النوع غير القابل لـ null مثل String لا يقبل null، ولما القيمة تكون اختيارية بنكتب String? ونفحصها قبل الاستخدام.', 'Null Safety يخلّي المترجم يكتشف أغلب أخطاء null قبل التشغيل. استخدم ? للنوع القابل لـ null، وخلّي التحويل إلى نوع غير قابل لـ null بعد شرط واضح. عامل ! يجبر المترجم على الثقة فيك، لكنه يرمي خطأ وقت التشغيل لو القيمة كانت null بالفعل.', 'String? nickname;
