insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما trade-offs استخدام GlobalKey في Flutter؟', 'GlobalKey تعطي وصولًا وهوية فريدة عبر الشجرة، لكنها أغلى وأشد coupling من local keys ويجب ألا تُنشأ داخل build.', 'استخدم GlobalKey عند حاجة حقيقية مثل الوصول إلى FormState أو نقل subtree، وثبّت instance في State أو owner مناسب. في القوائم استخدم ValueKey غالبًا، لأن GlobalKey كثيرة تصعّب المطابقة وتؤثر على الأداء.', null, '["إنشاء GlobalKey جديدة في كل build.","استخدامها كبديل لتمرير callback أو state بطريقة واضحة."]'::jsonb, '["كيف تستبدل GlobalKey بواجهة أبسط في نموذج صغير؟"]'::jsonb, '[{"title":"Flutter API — GlobalKey","url":"https://api.flutter.dev/flutter/widgets/GlobalKey-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'widgets-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'widgets-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما trade-offs استخدام GlobalKey في Flutter؟' or l.short_answer is distinct from 'GlobalKey تعطي وصولًا وهوية فريدة عبر الشجرة، لكنها أغلى وأشد coupling من local keys ويجب ألا تُنشأ داخل build.' or l.explanation is distinct from 'استخدم GlobalKey عند حاجة حقيقية مثل الوصول إلى FormState أو نقل subtree، وثبّت instance في State أو owner مناسب. في القوائم استخدم ValueKey غالبًا، لأن GlobalKey كثيرة تصعّب المطابقة وتؤثر على الأداء.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إنشاء GlobalKey جديدة في كل build.","استخدامها كبديل لتمرير callback أو state بطريقة واضحة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستبدل GlobalKey بواجهة أبسط في نموذج صغير؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter API — GlobalKey","url":"https://api.flutter.dev/flutter/widgets/GlobalKey-class.html"}]'::jsonb)) then raise exception 'Question widgets-010 ar content changed; create a new revision before seeding'; end if; end $$;
