insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('state-001', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه الفرق بين local state وshared state في Flutter؟', 'local state تخص Widget أو feature صغيرة، أما shared state فتحتاجها أجزاء متعددة أو شاشات مختلفة وتتطلب مالكًا ونطاقًا أوضح.', 'ابدأ بأقرب owner للحالة؛ لا ترفع قيمة لا يحتاجها غير child واحد. اجعل shared state صريحة في حدود feature، واحتفظ بالحالة المؤقتة مثل اختيار tab محلية ما لم يوجد سبب حقيقي لمشاركتها.', null, '["وضع كل state في singleton عالمي.","اعتبار كل قيمة داخل الشاشة app state."]'::jsonb, '["ما العلامة التي تقول إن local state يجب أن تصبح shared؟"]'::jsonb, '[{"title":"Flutter docs — Ephemeral vs app state","url":"https://docs.flutter.dev/data-and-backend/state-mgmt/ephemeral-vs-app"}]'::jsonb from public.question_revisions r where r.question_id = 'state-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'state-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إيه الفرق بين local state وshared state في Flutter؟' or l.short_answer is distinct from 'local state تخص Widget أو feature صغيرة، أما shared state فتحتاجها أجزاء متعددة أو شاشات مختلفة وتتطلب مالكًا ونطاقًا أوضح.' or l.explanation is distinct from 'ابدأ بأقرب owner للحالة؛ لا ترفع قيمة لا يحتاجها غير child واحد. اجعل shared state صريحة في حدود feature، واحتفظ بالحالة المؤقتة مثل اختيار tab محلية ما لم يوجد سبب حقيقي لمشاركتها.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع كل state في singleton عالمي.","اعتبار كل قيمة داخل الشاشة app state."]'::jsonb or l.follow_up_questions is distinct from '["ما العلامة التي تقول إن local state يجب أن تصبح shared؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Ephemeral vs app state","url":"https://docs.flutter.dev/data-and-backend/state-mgmt/ephemeral-vs-app"}]'::jsonb)) then raise exception 'Question state-001 ar content changed; create a new revision before seeding'; end if; end $$;
