insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ليه نعمل JSON serialization إلى typed models؟', 'typed model يضع contract للبيانات ويعزل parsing عن UI، فيكشف الحقول المفقودة أو المتغيرة قبل انتشارها في التطبيق.', 'تحقق من nullability والأنواع عند boundary الشبكة، واحتفظ بتحويل JSON في data layer. generator أو parsing يدوي كلاهما خيار؛ القرار يعتمد على حجم schema وتكرارها وليس على package واحدة.', 'factory User.fromJson(Map<String, Object?> json) => User(
  id: json["id"]! as String,
  name: json["name"]! as String,
);', '["تمرير Map<String, dynamic> إلى كل طبقات التطبيق.","افتراض أن API schema ثابتة بلا versioning أو validation."]'::jsonb, '["كيف تتعامل مع field جديد لا يعرفه إصدار التطبيق؟"]'::jsonb, '[{"title":"Flutter docs — JSON serialization","url":"https://docs.flutter.dev/data-and-backend/serialization/json"}]'::jsonb from public.question_revisions r where r.question_id = 'net-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'net-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ليه نعمل JSON serialization إلى typed models؟' or l.short_answer is distinct from 'typed model يضع contract للبيانات ويعزل parsing عن UI، فيكشف الحقول المفقودة أو المتغيرة قبل انتشارها في التطبيق.' or l.explanation is distinct from 'تحقق من nullability والأنواع عند boundary الشبكة، واحتفظ بتحويل JSON في data layer. generator أو parsing يدوي كلاهما خيار؛ القرار يعتمد على حجم schema وتكرارها وليس على package واحدة.' or l.code_example is distinct from 'factory User.fromJson(Map<String, Object?> json) => User(
  id: json["id"]! as String,
  name: json["name"]! as String,
);' or l.common_mistakes is distinct from '["تمرير Map<String, dynamic> إلى كل طبقات التطبيق.","افتراض أن API schema ثابتة بلا versioning أو validation."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتعامل مع field جديد لا يعرفه إصدار التطبيق؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — JSON serialization","url":"https://docs.flutter.dev/data-and-backend/serialization/json"}]'::jsonb)) then raise exception 'Question net-002 ar content changed; create a new revision before seeding'; end if; end $$;
