do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'net-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'فين تحط timeout وretry في network client؟' or l.short_answer is distinct from 'ضع timeout عند boundary الخارجية، واجعل retry محدودًا ومشروطًا بأخطاء مؤقتة مع backoff وبدون تكرار side effects خطرة.' or l.explanation is distinct from 'حدّد budget زمنيًا للمحاولة، وسجّل سبب الانقطاع، ولا تعيد POST غير idempotent بلا idempotency key أو عقد واضح. لا تجعل كل UI يقرر سياسة retry الخاصة به.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["retry فوري بلا حد فيزيد الحمل.","إخفاء timeout كأنه response فارغ."]'::jsonb or l.follow_up_questions is distinct from '["كيف تختار retryable status codes؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart API — Future.timeout","url":"https://api.dart.dev/dart-async/Future/timeout.html"},{"title":"RFC 9110 — HTTP Semantics","url":"https://www.rfc-editor.org/rfc/rfc9110#name-retry-after"}]'::jsonb)) then raise exception 'Question net-004 ar content changed; create a new revision before seeding'; end if; end $$;
