do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'arch-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تختار architecture seams التي تجعل الاختبار أعلى قيمة؟' or l.short_answer is distinct from 'افصل boundary حول قواعد أو I/O يتغير أو يفشل، ثم اختبر السلوك من خلال contract بدل تفاصيل implementation.' or l.explanation is distinct from 'اختبار unit للـuse case أو repository fake قد يعطي feedback أسرع، مع widget أو integration tests للتكامل الحقيقي. لا تبنِ seam فقط لإرضاء coverage رقمية؛ اختبر المخاطر التي تهم المستخدم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اختبار private methods بدل observable behavior.","ربط كل test بـmock كثيف ينهار مع refactor بسيط."]'::jsonb or l.follow_up_questions is distinct from '["متى تكون integration test أفضل من fake؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Testing architecture","url":"https://docs.flutter.dev/app-architecture/case-study/testing"}]'::jsonb)) then raise exception 'Question arch-007 ar content changed; create a new revision before seeding'; end if; end $$;
