insert into public.interview_questions (id, slug, track_id, difficulty) values ('fanim-001', 'flutter-implicit-vs-explicit-animations', 'flutter', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fanim-001', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الأساسي بين الـ Implicit Animations والـ Explicit Animations في Flutter ومتى تختار كلاً منهما؟', 'الـ Implicit Animations تدير الـ Controller تلقائياً بمجرد تغيير قيمة الـ Property (مثل AnimatedContainer)، بينما الـ Explicit تمنحك تحكماً كاملاً عبر AnimationController لبدء الحركة، إيقافها، عكسها، أو تكرارها.', 'تعتمد الـ Implicit Animations على ويدجتس جاهزة ترث من ImplicitlyAnimatedWidget، حيث تتولى إدارة مدة الحركة (Duration) والمنحنى (Curve) داخلياً بمجرد عمل rebuild بقيمة جديدة. أما الـ Explicit Animations فتتطلب TickerProviderStateMixin وإدارة يدوية لدورة حياة الـ AnimationController، وتُستخدم عند الحاجة لحركات معقدة، متزامنة، متكررة بلا نهاية (Looping)، أو مقيدة بإيماءات سحب المستخدم (Gesture-driven).', '// مثال Implicit Animation:
AnimatedContainer(
  duration: const Duration(milliseconds: 300),
  curve: Curves.easeInOut,
  width: isExpanded ? 200.0 : 100.0,
  height: 50.0,
  color: isExpanded ? Colors.blue : Colors.grey,
)', '["بناء AnimationController مخصص ومعقد لحركة بسيطة جداً كتحريك العرض أو الشفافية، بينما يكفي استخدام AnimatedContainer أو AnimatedOpacity.","نسيان استدعاء dispose() على الـ AnimationController في Explicit Animations مما يسبب تسريباً في الذاكرة (Memory Leak)."]'::jsonb, '["كيف يعمل TweenAnimationBuilder لعمل حركة Implicit لأي قيمة مخصصة غير متوفرة في الويدجتس الجاهزة؟"]'::jsonb, '[{"title":"Flutter Animations Overview","url":"https://docs.flutter.dev/ui/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'fanim-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fanim-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الأساسي بين الـ Implicit Animations والـ Explicit Animations في Flutter ومتى تختار كلاً منهما؟' or l.short_answer is distinct from 'الـ Implicit Animations تدير الـ Controller تلقائياً بمجرد تغيير قيمة الـ Property (مثل AnimatedContainer)، بينما الـ Explicit تمنحك تحكماً كاملاً عبر AnimationController لبدء الحركة، إيقافها، عكسها، أو تكرارها.' or l.explanation is distinct from 'تعتمد الـ Implicit Animations على ويدجتس جاهزة ترث من ImplicitlyAnimatedWidget، حيث تتولى إدارة مدة الحركة (Duration) والمنحنى (Curve) داخلياً بمجرد عمل rebuild بقيمة جديدة. أما الـ Explicit Animations فتتطلب TickerProviderStateMixin وإدارة يدوية لدورة حياة الـ AnimationController، وتُستخدم عند الحاجة لحركات معقدة، متزامنة، متكررة بلا نهاية (Looping)، أو مقيدة بإيماءات سحب المستخدم (Gesture-driven).' or l.code_example is distinct from '// مثال Implicit Animation:
