insert into public.interview_questions (id, slug, track_id, difficulty) values ('fanim-006', 'flutter-custom-painter-canvas-should-repaint', 'flutter', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fanim-006', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي اعتبارات الأداء القصوى عند استخدام CustomPainter وما الذي يتحكم به shouldRepaint()؟', 'يحدد shouldRepaint() ما إذا كانت هناك حاجة لإعادة تنفيذ أوامر الرسم على الـ Canvas عند إعادة البناء؛ وعدم التحقق الدقيق من الحقول يؤدي لإعادة رسم فادحة وغير مبررة تستهلك الـ GPU.', 'ينفذ CustomPainter أوامر رسم منخفضة المستوى عبر RenderCustomPaint. دالة paint() تستقبل Canvas و Size. للوصول لأعلى أداء: (1) يجب إنشاء كائنات Paint ومسارات Path خارج دالة paint() وتفادي إنشاء كائنات جديدة في كل فريم. (2) يجب أن تقارن shouldRepaint() القيم الحقيقية المؤثرة على الرسم وترجع false إذا لم تتغير. (3) وضع الـ CustomPaint داخل RepaintBoundary لعزل الطبقة الرسومية عن شجرة الواجهة المحيطة.', 'class CircleProgressPainter extends CustomPainter {
  final double progress;
  final Color color;
  CircleProgressPainter({required this.progress, required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = color..strokeWidth = 4.0..style = PaintingStyle.stroke;
    canvas.drawCircle(size.center(Offset.zero), size.width / 2, paint);
  }

  @override
  bool shouldRepaint(covariant CircleProgressPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.color != color;
  }
}', '["إرجاع true دائماً من shouldRepaint() ظناً أنها ممارسة آمنة، مما يجبر المحرك على إعادة استهلاك الموارد الرسومية مع كل rebuild.","تخصيص ذاكرة وإنشاء مصفوفات ومسارات ضخمة داخل دالة paint() المكررة في كل فريم."]'::jsonb, '["متى نحتاج لتنفيذ دالة shouldRebuildSemantics في الـ CustomPainter لتسهيل إمكانية الوصول؟"]'::jsonb, '[{"title":"CustomPainter class API","url":"https://api.flutter.dev/flutter/rendering/CustomPainter-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'fanim-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fanim-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي اعتبارات الأداء القصوى عند استخدام CustomPainter وما الذي يتحكم به shouldRepaint()؟' or l.short_answer is distinct from 'يحدد shouldRepaint() ما إذا كانت هناك حاجة لإعادة تنفيذ أوامر الرسم على الـ Canvas عند إعادة البناء؛ وعدم التحقق الدقيق من الحقول يؤدي لإعادة رسم فادحة وغير مبررة تستهلك الـ GPU.' or l.explanation is distinct from 'ينفذ CustomPainter أوامر رسم منخفضة المستوى عبر RenderCustomPaint. دالة paint() تستقبل Canvas و Size. للوصول لأعلى أداء: (1) يجب إنشاء كائنات Paint ومسارات Path خارج دالة paint() وتفادي إنشاء كائنات جديدة في كل فريم. (2) يجب أن تقارن shouldRepaint() القيم الحقيقية المؤثرة على الرسم وترجع false إذا لم تتغير. (3) وضع الـ CustomPaint داخل RepaintBoundary لعزل الطبقة الرسومية عن شجرة الواجهة المحيطة.' or l.code_example is distinct from 'class CircleProgressPainter extends CustomPainter {
  final double progress;
  final Color color;
  CircleProgressPainter({required this.progress, required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = color..strokeWidth = 4.0..style = PaintingStyle.stroke;
    canvas.drawCircle(size.center(Offset.zero), size.width / 2, paint);
  }

  @override
  bool shouldRepaint(covariant CircleProgressPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.color != color;
  }
}' or l.common_mistakes is distinct from '["إرجاع true دائماً من shouldRepaint() ظناً أنها ممارسة آمنة، مما يجبر المحرك على إعادة استهلاك الموارد الرسومية مع كل rebuild.","تخصيص ذاكرة وإنشاء مصفوفات ومسارات ضخمة داخل دالة paint() المكررة في كل فريم."]'::jsonb or l.follow_up_questions is distinct from '["متى نحتاج لتنفيذ دالة shouldRebuildSemantics في الـ CustomPainter لتسهيل إمكانية الوصول؟"]'::jsonb or l.sources is distinct from '[{"title":"CustomPainter class API","url":"https://api.flutter.dev/flutter/rendering/CustomPainter-class.html"}]'::jsonb)) then raise exception 'Question fanim-006 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Flutter developer know about Flutter Custom Painter Canvas Should Repaint?', 'This question checks the core Flutter Custom Painter Canvas Should Repaint concept and how to use it safely in Dart and Flutter.', 'Explain Flutter Custom Painter Canvas Should Repaint with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'class CircleProgressPainter extends CustomPainter {
  final double progress;
  final Color color;
  CircleProgressPainter({required this.progress, required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = color..strokeWidth = 4.0..style = PaintingStyle.stroke;
    canvas.drawCircle(size.center(Offset.zero), size.width / 2, paint);
  }

  @override
  bool shouldRepaint(covariant CircleProgressPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.color != color;
  }
}', '["Missing the key trade-off in Flutter Custom Painter Canvas Should Repaint (point 1).","Missing the key trade-off in Flutter Custom Painter Canvas Should Repaint (point 2)."]'::jsonb, '["How would you apply Flutter Custom Painter Canvas Should Repaint in a production Flutter app (follow-up 1)?"]'::jsonb, '[{"title":"CustomPainter class API","url":"https://api.flutter.dev/flutter/rendering/CustomPainter-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'fanim-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
