  final double progress;
  final Color color;
  CircleProgressPainter({required this.progress, required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = color..strokeWidth = 4.0..style = PaintingStyle.stroke;
    canvas.drawCircle(size.center(Offset.zero), size.width / 2, paint);
  }

  @override
  bool shouldRepaint(covariant CircleProgressPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.color != color;
  }
}' or l.common_mistakes is distinct from '["Missing the key trade-off in Flutter Custom Painter Canvas Should Repaint (point 1).","Missing the key trade-off in Flutter Custom Painter Canvas Should Repaint (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Flutter Custom Painter Canvas Should Repaint in a production Flutter app (follow-up 1)?"]'::jsonb or l.sources is distinct from '[{"title":"CustomPainter class API","url":"https://api.flutter.dev/flutter/rendering/CustomPainter-class.html"}]'::jsonb)) then raise exception 'Question fanim-006 en content changed; create a new revision before seeding'; end if; end $$;
