insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح المعمارية الداخلية للأشجار الثلاثة في Flutter (Widget, Element, RenderObject) وكيف تتزامن دورة حياتها؟', 'الـ Widget هو توصيف تصريحي ثابت خفيف وغير قابل للتعديل (Immutable Configuration)، والـ Element يدير الهوية وشجرة البناء وموقع الحالة في الذاكرة، والـ RenderObject يتولى حساب الحجم والـ Layout والرسم واللمس الفعلي على الشاشة.', 'عند تشغيل التطبيق، يُنشئ كل Widget عنصراً نظيراً Element عبر createElement(). يحتفظ الـ Element بمرجع للـ Widget والـ RenderObject. عندما يتغير الـ Widget أثناء الـ Rebuild، يتحقق الـ Element عبر دالة Widget.canUpdate() من مطابقة runtimeType والـ Key. إذا تطابقا، يقوم الـ Element بتحديث مرجعه فقط وتحديث خصائص الـ RenderObject دون إعادة بناء الشجرة من الصفر، محققاً سرعة فائقة في الأداء (O(N) reconciliation).', '// مبدأ المطابقة الداخلي في فئة Widget:
// static bool canUpdate(Widget oldWidget, Widget newWidget) {
//   return oldWidget.runtimeType == newWidget.runtimeType && oldWidget.key == newWidget.key;
// }', '["الاعتقاد بأن إنشاء كائنات Widget جديدة مع كل build مكلف للذاكرة، متجاهلين أن الـ Widgets خفيفة جداً ويتم تدميرها وجمعها فورياً بواسطة Dart Garbage Collector بينما تبقى كائنات الـ Elements والـ RenderObjects حية."]'::jsonb, '["متى يتم استدعاء mount() و unmount() و deactivate() على كائن الـ Element؟"]'::jsonb, '[{"title":"Flutter architectural overview","url":"https://docs.flutter.dev/resources/architectural-overview"}]'::jsonb from public.question_revisions r where r.question_id = 'fint-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fint-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'اشرح المعمارية الداخلية للأشجار الثلاثة في Flutter (Widget, Element, RenderObject) وكيف تتزامن دورة حياتها؟' or l.short_answer is distinct from 'الـ Widget هو توصيف تصريحي ثابت خفيف وغير قابل للتعديل (Immutable Configuration)، والـ Element يدير الهوية وشجرة البناء وموقع الحالة في الذاكرة، والـ RenderObject يتولى حساب الحجم والـ Layout والرسم واللمس الفعلي على الشاشة.' or l.explanation is distinct from 'عند تشغيل التطبيق، يُنشئ كل Widget عنصراً نظيراً Element عبر createElement(). يحتفظ الـ Element بمرجع للـ Widget والـ RenderObject. عندما يتغير الـ Widget أثناء الـ Rebuild، يتحقق الـ Element عبر دالة Widget.canUpdate() من مطابقة runtimeType والـ Key. إذا تطابقا، يقوم الـ Element بتحديث مرجعه فقط وتحديث خصائص الـ RenderObject دون إعادة بناء الشجرة من الصفر، محققاً سرعة فائقة في الأداء (O(N) reconciliation).' or l.code_example is distinct from '// مبدأ المطابقة الداخلي في فئة Widget:
// static bool canUpdate(Widget oldWidget, Widget newWidget) {
//   return oldWidget.runtimeType == newWidget.runtimeType && oldWidget.key == newWidget.key;
// }' or l.common_mistakes is distinct from '["الاعتقاد بأن إنشاء كائنات Widget جديدة مع كل build مكلف للذاكرة، متجاهلين أن الـ Widgets خفيفة جداً ويتم تدميرها وجمعها فورياً بواسطة Dart Garbage Collector بينما تبقى كائنات الـ Elements والـ RenderObjects حية."]'::jsonb or l.follow_up_questions is distinct from '["متى يتم استدعاء mount() و unmount() و deactivate() على كائن الـ Element؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter architectural overview","url":"https://docs.flutter.dev/resources/architectural-overview"}]'::jsonb)) then raise exception 'Question fint-001 ar content changed; create a new revision before seeding'; end if; end $$;
