insert into public.interview_questions (id, slug, track_id, difficulty) values ('fint-005', 'flutter-gesture-arena-and-hit-testing', 'flutter', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fint-005', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يكتشف Flutter تفاعلات اللمس عبر Hit Testing وكيف تحسم الـ GestureArena النزاع بين الإيماءات المتنافسة؟', 'يقوم الـ Hit Testing بالبحث بعمق الشجرة لتجميع كائنات RenderObject التي تقع تحت موضع اللمس، ثم تتنافس الـ GestureRecognizers في حلبة (GestureArena) لتحديد الفائز بناءً على حركة المستخدم أو سحب الإيماءات الأخرى.', 'عند لمس الشاشة، يرسل المحرك PointerDownEvent ويبدأ استدعاء hitTest() نزولاً من RenderView إلى أعمق أوراق الشجرة، وكل عنصر يقبل اللمس يسجل نفسه في HitTestResult. بعد ذلك، تشترك الـ GestureRecognizers المربوطة (مثل TapGestureRecognizer و HorizontalDragGestureRecognizer) في GestureArena. ترسل الحلبة أحداث الحركة، وإذا سحب المستخدم أفقياً لمسافة تتجاوز عتبة الـ Drag، يقبل الـ Drag الإيماءة ويقوم الـ Arena بحل النزاع ورفض الـ Tap (Sweep).', '// تخصيص سلوك فحص اللمس عبر HitTestBehavior:
Listener(
  behavior: HitTestBehavior.opaque, // يلتقط اللمس حتى في المساحات الفارغة الشفافة
  onPointerDown: (event) => print(''Touch at ${event.position}''),
  child: Container(height: 100),
)', '["عدم ضبط HitTestBehavior.opaque على الحاويات ذات الخلفيات الشفافة، مما يؤدي لتمرير أحداث اللمس للعناصر الخلفية وتجاهل الـ GestureDetector."]'::jsonb, '["ما الفرق بين HitTestBehavior.deferToChild و opaque و translucent؟"]'::jsonb, '[{"title":"Gestures in Flutter overview","url":"https://docs.flutter.dev/ui/interactivity/gestures"}]'::jsonb from public.question_revisions r where r.question_id = 'fint-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
