insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا طورت Google محرك الرسم الجديد Impeller كبديل لـ Skia في Flutter وما هي مشكلة الـ Shader Compilation Jank؟', 'طور Impeller للتخلص التام من تقطيع الفريمات (Jank) الناتج عن ترجمة الـ Shaders وقت التشغيل لأول مرة في Skia، وذلك عبر ترجمة وتجميع جميع الـ Shaders مسبقاً في وقت بناء التطبيق (AOT).', 'في محرك Skia التقليدي، عندما يواجه التطبيق تأثيراً بصرياً أو حركة لأول مرة (مثل ظل جديد أو تدرج لوني معقد)، يتوقف خيط الرسم لترجمة كود الـ Shader إلى كود لغة الآلة لبطاقة الرسوميات (GPU Driver compilation)، مما يستغرق أحياناً مئات المللي ثواني ويسقط الفريمات. يحل Impeller هذه المشكلة بالكامل عن طريق تجميع كل الـ Shaders والـ pipelines مسبقاً في وقت الترجمة (AOT compilation)، مع استخدام مباشر لـ Metal على iOS و Vulkan على Android، واستخدام أفضل للـ concurrency وتعدد خيوط المعالجة.', '// في Flutter 3.10+ على iOS و 3.16+ على Android:
// يعمل Impeller افتراضياً بدون أي تدخل برمجي، محققاً 60/120 FPS مستقرة تماماً', '["الاعتقاد بأن حل مشكلة تقطيع الـ Shaders في Skia كان عبر زيادة قوة الهاتف، بينما المشكلة بنيوية في طريقة الترجمة اللحظية للـ GPU Pipelines."]'::jsonb, '["كيف يتعامل Impeller مع الـ Custom Shaders المكتوبة بلغة GLSL والمدعومة عبر FragmentProgram؟"]'::jsonb, '[{"title":"Impeller rendering engine documentation","url":"https://docs.flutter.dev/perf/impeller"}]'::jsonb from public.question_revisions r where r.question_id = 'fint-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fint-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا طورت Google محرك الرسم الجديد Impeller كبديل لـ Skia في Flutter وما هي مشكلة الـ Shader Compilation Jank؟' or l.short_answer is distinct from 'طور Impeller للتخلص التام من تقطيع الفريمات (Jank) الناتج عن ترجمة الـ Shaders وقت التشغيل لأول مرة في Skia، وذلك عبر ترجمة وتجميع جميع الـ Shaders مسبقاً في وقت بناء التطبيق (AOT).' or l.explanation is distinct from 'في محرك Skia التقليدي، عندما يواجه التطبيق تأثيراً بصرياً أو حركة لأول مرة (مثل ظل جديد أو تدرج لوني معقد)، يتوقف خيط الرسم لترجمة كود الـ Shader إلى كود لغة الآلة لبطاقة الرسوميات (GPU Driver compilation)، مما يستغرق أحياناً مئات المللي ثواني ويسقط الفريمات. يحل Impeller هذه المشكلة بالكامل عن طريق تجميع كل الـ Shaders والـ pipelines مسبقاً في وقت الترجمة (AOT compilation)، مع استخدام مباشر لـ Metal على iOS و Vulkan على Android، واستخدام أفضل للـ concurrency وتعدد خيوط المعالجة.' or l.code_example is distinct from '// في Flutter 3.10+ على iOS و 3.16+ على Android:
// يعمل Impeller افتراضياً بدون أي تدخل برمجي، محققاً 60/120 FPS مستقرة تماماً' or l.common_mistakes is distinct from '["الاعتقاد بأن حل مشكلة تقطيع الـ Shaders في Skia كان عبر زيادة قوة الهاتف، بينما المشكلة بنيوية في طريقة الترجمة اللحظية للـ GPU Pipelines."]'::jsonb or l.follow_up_questions is distinct from '["كيف يتعامل Impeller مع الـ Custom Shaders المكتوبة بلغة GLSL والمدعومة عبر FragmentProgram؟"]'::jsonb or l.sources is distinct from '[{"title":"Impeller rendering engine documentation","url":"https://docs.flutter.dev/perf/impeller"}]'::jsonb)) then raise exception 'Question fint-008 ar content changed; create a new revision before seeding'; end if; end $$;
