insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين معمارية Platform Channels التقليدية و Dart FFI في الاتصال بالطبقة الأصلية (Native) وما الفرق في الأداء؟', 'تعتمد Platform Channels على نقل الرسائل غير المتزامن وتسلسل الـ Binary عبر خيط المنصة، بينما يتصل Dart FFI مباشرة بدوال C/C++ في الذاكرة المشتركة بشكل متزامن وبسرعة الكود المترجم الأصلي.', 'في MethodChannel، يمر كل استدعاء عبر: تشفير المعاملات بواسطة StandardMessageCodec، الإرسال عبر Flutter Engine إلى الـ Platform Thread، فك التشفير، تنفيذ الكود في Java/Kotlin أو Obj-C/Swift، وتكرار نفس الدورة في رحلة العودة غير المتزامنة. هذا يسبب اختناقاً إذا كان معدل نقل البيانات ضخماً (مثل معالجة الكاميرا أو تدفقات البلوتوث). في المقابل، يتيح Dart FFI (Foreign Function Interface) توجيه المؤشرات في الذاكرة واستدعاء دوال المكتبات المجمعة مباشرة دون أي وسيط أو تسلسل، مما يجعله مثالياً لمعالجة الإشارات وخوارزميات التشفير والصور.', '// مثال اتصال فوري متزامن عبر FFI بدون أي Platform Channel:
// typedef NativeAdd = Int32 Function(Int32, Int32);
// typedef DartAdd = int Function(int, int);
// final add = dylib.lookupFunction<NativeAdd, DartAdd>(''native_add'');
// final result = add(20, 22); // استدعاء مباشر في الذاكرة النانو-ثانية!', '["استخدام MethodChannel لنقل بيانات فيديو خام (Raw Video Frames) بدقة عالية، مما يتسبب في إجهاد شديد للـ Memory Bandwidth وتقطيع الواجهة."]'::jsonb, '["متى نستخدم Pigeon لتوليد كود Platform Channels آمن الأنواع (Type-safe) بدلاً من كتابة القنوات يدوياً؟"]'::jsonb, '[{"title":"C interop using dart:ffi","url":"https://dart.dev/interop/c-interop"}]'::jsonb from public.question_revisions r where r.question_id = 'fint-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fint-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين معمارية Platform Channels التقليدية و Dart FFI في الاتصال بالطبقة الأصلية (Native) وما الفرق في الأداء؟' or l.short_answer is distinct from 'تعتمد Platform Channels على نقل الرسائل غير المتزامن وتسلسل الـ Binary عبر خيط المنصة، بينما يتصل Dart FFI مباشرة بدوال C/C++ في الذاكرة المشتركة بشكل متزامن وبسرعة الكود المترجم الأصلي.' or l.explanation is distinct from 'في MethodChannel، يمر كل استدعاء عبر: تشفير المعاملات بواسطة StandardMessageCodec، الإرسال عبر Flutter Engine إلى الـ Platform Thread، فك التشفير، تنفيذ الكود في Java/Kotlin أو Obj-C/Swift، وتكرار نفس الدورة في رحلة العودة غير المتزامنة. هذا يسبب اختناقاً إذا كان معدل نقل البيانات ضخماً (مثل معالجة الكاميرا أو تدفقات البلوتوث). في المقابل، يتيح Dart FFI (Foreign Function Interface) توجيه المؤشرات في الذاكرة واستدعاء دوال المكتبات المجمعة مباشرة دون أي وسيط أو تسلسل، مما يجعله مثالياً لمعالجة الإشارات وخوارزميات التشفير والصور.' or l.code_example is distinct from '// مثال اتصال فوري متزامن عبر FFI بدون أي Platform Channel:
// typedef NativeAdd = Int32 Function(Int32, Int32);
// typedef DartAdd = int Function(int, int);
// final add = dylib.lookupFunction<NativeAdd, DartAdd>(''native_add'');
// final result = add(20, 22); // استدعاء مباشر في الذاكرة النانو-ثانية!' or l.common_mistakes is distinct from '["استخدام MethodChannel لنقل بيانات فيديو خام (Raw Video Frames) بدقة عالية، مما يتسبب في إجهاد شديد للـ Memory Bandwidth وتقطيع الواجهة."]'::jsonb or l.follow_up_questions is distinct from '["متى نستخدم Pigeon لتوليد كود Platform Channels آمن الأنواع (Type-safe) بدلاً من كتابة القنوات يدوياً؟"]'::jsonb or l.sources is distinct from '[{"title":"C interop using dart:ffi","url":"https://dart.dev/interop/c-interop"}]'::jsonb)) then raise exception 'Question fint-009 ar content changed; create a new revision before seeding'; end if; end $$;
