insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تتحول شجرة الرسوم إلى شجرة طبقات (Layer Tree) وكيف يتم إرسالها إلى الـ Rasterizer؟', 'تقوم الـ RenderObjects بتسجيل أوامر الرسم في طبقات هندسية (ContainerLayer, PictureLayer)، ثم يقوم الـ SceneBuilder بدمجها في Scene موحد يُرسل عبر RenderView إلى خيط الـ Rasterizer لمعالجته على الـ GPU.', 'لا يتم رسم الـ RenderObjects مباشرة على الشاشة، بل تودع مخرجاتها في شجرة طبقات (Layer Tree). تحتوي هذه الشجرة على PictureLayers التي تسجل أوامر الرسم كـ Display List، وطبقات ContainerLayer للقص (ClipLayer) والتعتيم (OpacityLayer) والتحويل الهندسي (TransformLayer). في نهاية مرحلة الرسم، تستدعي RenderView دالة compositeFrame() التي تستخدم SceneBuilder لتجميع هذه الطبقات في كائن Scene واحد. يُسلّم هذا المشهد لمحرك الرسم في خيط الـ Rasterizer حيث يقوم الـ GPU بتلوين البيكسلات وعرضها على الشاشة.', '// مفهوم إنشاء Scene وإرساله للمحرك في RenderView:
// final SceneBuilder builder = SceneBuilder();
// layer!.buildScene(builder);
// final Scene scene = builder.build();
// window.render(scene);', '["الخلط بين خيط واجهة المستخدم (UI Thread) الذي ينفذ كود Dart وينشئ الـ Layer Tree، وخيط التصيير (Raster Thread) الذي يوجه الأوامر للـ GPU."]'::jsonb, '["كيف تكتشف ما إذا كان سبب بطء التطبيق يرجع لاختناق في خيط الـ UI أم في خيط الـ Raster عبر أدوات DevTools؟"]'::jsonb, '[{"title":"Flutter architectural overview - The engine","url":"https://docs.flutter.dev/resources/architectural-overview#the-engine"}]'::jsonb from public.question_revisions r where r.question_id = 'fint-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fint-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تتحول شجرة الرسوم إلى شجرة طبقات (Layer Tree) وكيف يتم إرسالها إلى الـ Rasterizer؟' or l.short_answer is distinct from 'تقوم الـ RenderObjects بتسجيل أوامر الرسم في طبقات هندسية (ContainerLayer, PictureLayer)، ثم يقوم الـ SceneBuilder بدمجها في Scene موحد يُرسل عبر RenderView إلى خيط الـ Rasterizer لمعالجته على الـ GPU.' or l.explanation is distinct from 'لا يتم رسم الـ RenderObjects مباشرة على الشاشة، بل تودع مخرجاتها في شجرة طبقات (Layer Tree). تحتوي هذه الشجرة على PictureLayers التي تسجل أوامر الرسم كـ Display List، وطبقات ContainerLayer للقص (ClipLayer) والتعتيم (OpacityLayer) والتحويل الهندسي (TransformLayer). في نهاية مرحلة الرسم، تستدعي RenderView دالة compositeFrame() التي تستخدم SceneBuilder لتجميع هذه الطبقات في كائن Scene واحد. يُسلّم هذا المشهد لمحرك الرسم في خيط الـ Rasterizer حيث يقوم الـ GPU بتلوين البيكسلات وعرضها على الشاشة.' or l.code_example is distinct from '// مفهوم إنشاء Scene وإرساله للمحرك في RenderView:
// final SceneBuilder builder = SceneBuilder();
// layer!.buildScene(builder);
// final Scene scene = builder.build();
// window.render(scene);' or l.common_mistakes is distinct from '["الخلط بين خيط واجهة المستخدم (UI Thread) الذي ينفذ كود Dart وينشئ الـ Layer Tree، وخيط التصيير (Raster Thread) الذي يوجه الأوامر للـ GPU."]'::jsonb or l.follow_up_questions is distinct from '["كيف تكتشف ما إذا كان سبب بطء التطبيق يرجع لاختناق في خيط الـ UI أم في خيط الـ Raster عبر أدوات DevTools؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter architectural overview - The engine","url":"https://docs.flutter.dev/resources/architectural-overview#the-engine"}]'::jsonb)) then raise exception 'Question fint-010 ar content changed; create a new revision before seeding'; end if; end $$;
