insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المراحل الأساسية للـ Event Loop في Node.js وكيف تعالج المهام المختلفة؟', 'يمر الـ Event Loop بمراحل متتالية: Timers، Pending callbacks، Idle/Prepare، Poll، Check، وClose callbacks، مع معالجة microtasks بين المراحل.', 'يدير الـ Event Loop بواسطة مكتبة libuv؛ تبدأ دورته بمرحلة Timers (تنفيذ callbacks الخاصة بـ setTimeout وsetInterval)، تليها Pending callbacks لأخطاء الـ I/O المؤجلة، ثم Poll لانتظار أحداث الـ I/O الجديدة، ثم Check لتنفيذ callbacks الخاصة بـ setImmediate، وأخيراً Close callbacks لإغلاق المقابس والـ handles. يتم تفريغ طابور الـ microtasks (مثل process.nextTick والـ Promises) فور انتهاء كل عملية أو مرحلة قبل الانتقال للمرحلة التالية.', 'setTimeout(() => console.log("Timer"), 0);
setImmediate(() => console.log("Immediate"));
process.nextTick(() => console.log("Next Tick"));', '["الاعتقاد بأن setTimeout(fn, 0) تنفذ فوراً في نفس اللحظة دون انتظار دورة الـ event loop.","تجاهل أولوية process.nextTick على الـ microtasks الأخرى للـ Promise."]'::jsonb, '["كيف يؤثر تنفيذ عملية متزامنة ثقيلة داخل مرحلة Poll على الـ Timers؟","ما الفرق الدقيق بين تنفيذ الـ microtasks في Node.js 11+ مقارنة بالإصدارات السابقة؟"]'::jsonb, '[{"title":"Node.js docs — The Node.js Event Loop, Timers, and process.nextTick()","url":"https://nodejs.org/docs/latest/api/timers.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ncore-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ncore-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المراحل الأساسية للـ Event Loop في Node.js وكيف تعالج المهام المختلفة؟' or l.short_answer is distinct from 'يمر الـ Event Loop بمراحل متتالية: Timers، Pending callbacks، Idle/Prepare، Poll، Check، وClose callbacks، مع معالجة microtasks بين المراحل.' or l.explanation is distinct from 'يدير الـ Event Loop بواسطة مكتبة libuv؛ تبدأ دورته بمرحلة Timers (تنفيذ callbacks الخاصة بـ setTimeout وsetInterval)، تليها Pending callbacks لأخطاء الـ I/O المؤجلة، ثم Poll لانتظار أحداث الـ I/O الجديدة، ثم Check لتنفيذ callbacks الخاصة بـ setImmediate، وأخيراً Close callbacks لإغلاق المقابس والـ handles. يتم تفريغ طابور الـ microtasks (مثل process.nextTick والـ Promises) فور انتهاء كل عملية أو مرحلة قبل الانتقال للمرحلة التالية.' or l.code_example is distinct from 'setTimeout(() => console.log("Timer"), 0);
setImmediate(() => console.log("Immediate"));
process.nextTick(() => console.log("Next Tick"));' or l.common_mistakes is distinct from '["الاعتقاد بأن setTimeout(fn, 0) تنفذ فوراً في نفس اللحظة دون انتظار دورة الـ event loop.","تجاهل أولوية process.nextTick على الـ microtasks الأخرى للـ Promise."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر تنفيذ عملية متزامنة ثقيلة داخل مرحلة Poll على الـ Timers؟","ما الفرق الدقيق بين تنفيذ الـ microtasks في Node.js 11+ مقارنة بالإصدارات السابقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — The Node.js Event Loop, Timers, and process.nextTick()","url":"https://nodejs.org/docs/latest/api/timers.html"}]'::jsonb)) then raise exception 'Question ncore-001 ar content changed; create a new revision before seeding'; end if; end $$;
