insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو دور مكتبة libuv والـ Thread Pool الداخلي في Node.js ومتى يتم استخدامه؟', 'توفر libuv حلقة الـ Event Loop وتدير التفاعل مع نظام التشغيل بطريقة non-blocking، وتستخدم Thread Pool (افتراضياً 4 threads) للمهام التي لا يدعم نظام التشغيل إجابتها asynchronous بشكل أصيل.', 'تعتمد Node.js على libuv كطبقة تجريد بين JavaScript ونظام التشغيل. عمليات الشبكة على Linux/macOS مثل epoll وkqueue هي asynchronous بالفعل ولا تحتاج threads إضافية. ولكن عمليات نظام الملفات (fs)، واستدعاءات DNS (عبر getaddrinfo)، وبعض العمليات التشفيرية (crypto)، وضغط البيانات (zlib) تتطلب thread pool منفصل لتفادي حظر الـ main thread.', 'process.env.UV_THREADPOOL_SIZE = "8";', '["الاعتقاد بأن كل طلبات الشبكة تستهلك threads من الـ libuv thread pool."]'::jsonb, '["كيف تراقب تشبع الـ thread pool واختناق عمليات الـ I/O في بيئة الإنتاج؟"]'::jsonb, '[{"title":"Node.js docs — Dependencies: libuv","url":"https://nodejs.org/docs/latest/api/process.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ncore-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ncore-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو دور مكتبة libuv والـ Thread Pool الداخلي في Node.js ومتى يتم استخدامه؟' or l.short_answer is distinct from 'توفر libuv حلقة الـ Event Loop وتدير التفاعل مع نظام التشغيل بطريقة non-blocking، وتستخدم Thread Pool (افتراضياً 4 threads) للمهام التي لا يدعم نظام التشغيل إجابتها asynchronous بشكل أصيل.' or l.explanation is distinct from 'تعتمد Node.js على libuv كطبقة تجريد بين JavaScript ونظام التشغيل. عمليات الشبكة على Linux/macOS مثل epoll وkqueue هي asynchronous بالفعل ولا تحتاج threads إضافية. ولكن عمليات نظام الملفات (fs)، واستدعاءات DNS (عبر getaddrinfo)، وبعض العمليات التشفيرية (crypto)، وضغط البيانات (zlib) تتطلب thread pool منفصل لتفادي حظر الـ main thread.' or l.code_example is distinct from 'process.env.UV_THREADPOOL_SIZE = "8";' or l.common_mistakes is distinct from '["الاعتقاد بأن كل طلبات الشبكة تستهلك threads من الـ libuv thread pool."]'::jsonb or l.follow_up_questions is distinct from '["كيف تراقب تشبع الـ thread pool واختناق عمليات الـ I/O في بيئة الإنتاج؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Dependencies: libuv","url":"https://nodejs.org/docs/latest/api/process.html"}]'::jsonb)) then raise exception 'Question ncore-003 ar content changed; create a new revision before seeding'; end if; end $$;
