insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين uncaughtException و unhandledRejection في Node.js وما التصرف الصحيح عند حدوثهما؟', 'تحدث uncaughtException عند خطأ متزامن لم يلتقطه try/catch ويجب عندها إنهاء العملية، بينما تحدث unhandledRejection عند فشل Promise بدون catch handler.', 'عند إطلاق استثناء متزامن غير معالج، تصبح حالة تطبيق Node.js غير مستقرة وغير مضمونة؛ التصرف الموصى به رسمياً هو تسجيل الخطأ، إغلاق الاتصالات الحالية بلباقة، ثم إنهاء العملية (process.exit(1)) وترك مشغل العمليات يعيد تشغيلها.', 'process.on("uncaughtException", (err) => {
  console.error("Critical error:", err);
  process.exit(1);
});', '["محاولة استكمال عمل السيرفر بعد uncaughtException مما يؤدي إلى تلف البيانات أو تسريب الذاكرة."]'::jsonb, '["لماذا يعتبر الإبقاء على العملية حية بعد uncaughtException سلوكاً خطيراً؟"]'::jsonb, '[{"title":"Node.js docs — process events","url":"https://nodejs.org/docs/latest/api/process.html#event-uncaughtexception"}]'::jsonb from public.question_revisions r where r.question_id = 'ncore-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ncore-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين uncaughtException و unhandledRejection في Node.js وما التصرف الصحيح عند حدوثهما؟' or l.short_answer is distinct from 'تحدث uncaughtException عند خطأ متزامن لم يلتقطه try/catch ويجب عندها إنهاء العملية، بينما تحدث unhandledRejection عند فشل Promise بدون catch handler.' or l.explanation is distinct from 'عند إطلاق استثناء متزامن غير معالج، تصبح حالة تطبيق Node.js غير مستقرة وغير مضمونة؛ التصرف الموصى به رسمياً هو تسجيل الخطأ، إغلاق الاتصالات الحالية بلباقة، ثم إنهاء العملية (process.exit(1)) وترك مشغل العمليات يعيد تشغيلها.' or l.code_example is distinct from 'process.on("uncaughtException", (err) => {
