insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الـ Native Addons وNode-API (N-API) ومتى يلجأ المطور لبنائها؟', 'هي إضافات ديناميكية مكتوبة بـ C/C++ يتم ربطها بـ Node.js وتوفر واجهة ABI مستقرة (Node-API) لتنفيذ مهام فائقة السرعة أو استخدام مكتبات النظام الأصلية.', 'تستخدم الـ Native Addons عندما تكون كفاءة JavaScript غير كافية لمهام معينة مثل معالجة الصور والفيديو عالية الدقة، أو التشفير المتخصص، أو التواصل المباشر مع عتاد الأجهزة ومكتبات C القائمة مع استقرار الـ ABI عبر إصدارات Node.js المختلفة.', '// استخدام C/C++ Addon عبر N-API', '["الافتراض بأن كتابة الكود بـ C++ ستكون أسرع دائماً مع تجاهل تكلفة نقل البيانات وتجاوز حدود V8."]'::jsonb, '["ما هو دور node-addon-api في تبسيط كتابة الـ Addons باستخدام C++؟"]'::jsonb, '[{"title":"Node.js docs — C/C++ addons","url":"https://nodejs.org/docs/latest/api/addons.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ncore-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ncore-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الـ Native Addons وNode-API (N-API) ومتى يلجأ المطور لبنائها؟' or l.short_answer is distinct from 'هي إضافات ديناميكية مكتوبة بـ C/C++ يتم ربطها بـ Node.js وتوفر واجهة ABI مستقرة (Node-API) لتنفيذ مهام فائقة السرعة أو استخدام مكتبات النظام الأصلية.' or l.explanation is distinct from 'تستخدم الـ Native Addons عندما تكون كفاءة JavaScript غير كافية لمهام معينة مثل معالجة الصور والفيديو عالية الدقة، أو التشفير المتخصص، أو التواصل المباشر مع عتاد الأجهزة ومكتبات C القائمة مع استقرار الـ ABI عبر إصدارات Node.js المختلفة.' or l.code_example is distinct from '// استخدام C/C++ Addon عبر N-API' or l.common_mistakes is distinct from '["الافتراض بأن كتابة الكود بـ C++ ستكون أسرع دائماً مع تجاهل تكلفة نقل البيانات وتجاوز حدود V8."]'::jsonb or l.follow_up_questions is distinct from '["ما هو دور node-addon-api في تبسيط كتابة الـ Addons باستخدام C++؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — C/C++ addons","url":"https://nodejs.org/docs/latest/api/addons.html"}]'::jsonb)) then raise exception 'Question ncore-010 ar content changed; create a new revision before seeding'; end if; end $$;
