insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق العملي بين استخدام async/await والتعامل المباشر مع Promises في Node.js؟', 'async/await هي مجرد Syntactic Sugar مبنية فوق الـ Promises تجعل الكود يبدو ككود متزامن وتتيح معالجة الأخطاء بـ try/catch وتحسن قراءة الـ stack traces.', 'الميزة الجوهرية لـ async/await تكمن في سهولة القراءة ومنع تداخل الـ then/catch المتسلسل، وتوحيد معالجة الأخطاء المتزامنة وغير المتزامنة في كتلة try/catch واحدة، بالإضافة إلى إتاحة خاصية async stack traces.', 'try {
  const user = await getUser(id);
} catch (err) {
  handleError(err);
}', '["نسيان إضافة كلمة await مما يعيد كائن Promise بدلاً من القيمة المطلوبة وينتج أخطاء صامتة."]'::jsonb, '["ما هو التأثير الأدائي لاستخدام await المتسلسلة لعمليات غير معتمدة على بعضها؟"]'::jsonb, '[{"title":"Node.js docs — Asynchronous activity","url":"https://nodejs.org/docs/latest/api/async_context.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nasync-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasync-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق العملي بين استخدام async/await والتعامل المباشر مع Promises في Node.js؟' or l.short_answer is distinct from 'async/await هي مجرد Syntactic Sugar مبنية فوق الـ Promises تجعل الكود يبدو ككود متزامن وتتيح معالجة الأخطاء بـ try/catch وتحسن قراءة الـ stack traces.' or l.explanation is distinct from 'الميزة الجوهرية لـ async/await تكمن في سهولة القراءة ومنع تداخل الـ then/catch المتسلسل، وتوحيد معالجة الأخطاء المتزامنة وغير المتزامنة في كتلة try/catch واحدة، بالإضافة إلى إتاحة خاصية async stack traces.' or l.code_example is distinct from 'try {
  const user = await getUser(id);
} catch (err) {
  handleError(err);
}' or l.common_mistakes is distinct from '["نسيان إضافة كلمة await مما يعيد كائن Promise بدلاً من القيمة المطلوبة وينتج أخطاء صامتة."]'::jsonb or l.follow_up_questions is distinct from '["ما هو التأثير الأدائي لاستخدام await المتسلسلة لعمليات غير معتمدة على بعضها؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Asynchronous activity","url":"https://nodejs.org/docs/latest/api/async_context.html"}]'::jsonb)) then raise exception 'Question nasync-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Node.js developer know about Async Await Vs Promises In Node?', 'This question checks the core Async Await Vs Promises In Node concept and how to use it safely in Node.js, TypeScript, and backend architectures.', 'Explain Async Await Vs Promises In Node with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'try {
