insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي ظاهرة تجويع الـ Event Loop (Starvation) بسبب مهام الـ CPU المكثفة وكيف تتجنبها؟', 'تحدث عندما يحتكر حساب متزامن طويل الخيط الرئيسي، مما يمنع معالجة الـ I/O والمؤقتات، ويمكن تفاديها بتجزئة الحساب (Chunking) أو تفويضه لـ Worker Threads.', 'نظراً لأن الـ Event Loop أحادي الخيط، فإن أي حلقة تكرارية طويلة تجعل السيرفر غير قادر على استقبال طلبات HTTP جديدة أو إرسال استجابات. الحل إما بتقطيع المهمة باستخدام setImmediate لإرجاع التحكم للـ loop دورياً، أو عزل العمليات الحسابية في خيوط عمل مستقلة.', '// تقطيع المهمة دورياً بـ setImmediate', '["الاعتماد على process.nextTick لتقطيع المهام، حيث يظل الطابور محتكراً للخيط ويمنع معالجة أحداث الـ I/O."]'::jsonb, '["متى يكون استخدام Worker Threads أفضل من تقطيع المهمة داخل الـ main thread؟"]'::jsonb, '[{"title":"Node.js docs — Don''t Block the Event Loop","url":"https://nodejs.org/docs/latest/api/perf_hooks.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nasync-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasync-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي ظاهرة تجويع الـ Event Loop (Starvation) بسبب مهام الـ CPU المكثفة وكيف تتجنبها؟' or l.short_answer is distinct from 'تحدث عندما يحتكر حساب متزامن طويل الخيط الرئيسي، مما يمنع معالجة الـ I/O والمؤقتات، ويمكن تفاديها بتجزئة الحساب (Chunking) أو تفويضه لـ Worker Threads.' or l.explanation is distinct from 'نظراً لأن الـ Event Loop أحادي الخيط، فإن أي حلقة تكرارية طويلة تجعل السيرفر غير قادر على استقبال طلبات HTTP جديدة أو إرسال استجابات. الحل إما بتقطيع المهمة باستخدام setImmediate لإرجاع التحكم للـ loop دورياً، أو عزل العمليات الحسابية في خيوط عمل مستقلة.' or l.code_example is distinct from '// تقطيع المهمة دورياً بـ setImmediate' or l.common_mistakes is distinct from '["الاعتماد على process.nextTick لتقطيع المهام، حيث يظل الطابور محتكراً للخيط ويمنع معالجة أحداث الـ I/O."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون استخدام Worker Threads أفضل من تقطيع المهمة داخل الـ main thread؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Don''t Block the Event Loop","url":"https://nodejs.org/docs/latest/api/perf_hooks.html"}]'::jsonb)) then raise exception 'Question nasync-007 ar content changed; create a new revision before seeding'; end if; end $$;
