insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي ظاهرة الـ Backpressure في Node.js Streams وكيف تتم معالجتها هندسياً؟', 'تحدث عندما ينتج الـ Readable بيانات بمعدل أسرع من قدرة الـ Writable على استهلاكها، وتعالج بإيقاف القراءة مؤقتاً عند امتلاء الـ buffer ثم استئنافها عند حدث drain.', 'إذا كانت سرعة قراءة ملف أسرع بكثير من سرعة كتابته، ستتراكم البيانات في ذاكرة الـ Writable حتى تنفد الـ RAM. تعالج Node.js ذلك بإعادة write(chunk) لـ false عند امتلاء الـ buffer، حيث يوقف المنتج القراءة وينتظر حدث drain.', 'if (!writer.write(data)) {
  reader.pause();
  writer.once("drain", () => reader.resume());
}', '["تجاهل القيمة المعادة من writer.write() ومواصلة ضخ البيانات مما يؤدي لزيادة استهلاك الذاكرة."]'::jsonb, '["كيف تقوم utility مثل stream.pipeline بإدارة الـ backpressure تلقائياً بين عدة streams؟"]'::jsonb, '[{"title":"Node.js docs — Backpressuring in Streams","url":"https://nodejs.org/docs/latest/api/stream.html#backpressuring-in-streams"}]'::jsonb from public.question_revisions r where r.question_id = 'nstream-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nstream-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي ظاهرة الـ Backpressure في Node.js Streams وكيف تتم معالجتها هندسياً؟' or l.short_answer is distinct from 'تحدث عندما ينتج الـ Readable بيانات بمعدل أسرع من قدرة الـ Writable على استهلاكها، وتعالج بإيقاف القراءة مؤقتاً عند امتلاء الـ buffer ثم استئنافها عند حدث drain.' or l.explanation is distinct from 'إذا كانت سرعة قراءة ملف أسرع بكثير من سرعة كتابته، ستتراكم البيانات في ذاكرة الـ Writable حتى تنفد الـ RAM. تعالج Node.js ذلك بإعادة write(chunk) لـ false عند امتلاء الـ buffer، حيث يوقف المنتج القراءة وينتظر حدث drain.' or l.code_example is distinct from 'if (!writer.write(data)) {
  reader.pause();
  writer.once("drain", () => reader.resume());
}' or l.common_mistakes is distinct from '["تجاهل القيمة المعادة من writer.write() ومواصلة ضخ البيانات مما يؤدي لزيادة استهلاك الذاكرة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تقوم utility مثل stream.pipeline بإدارة الـ backpressure تلقائياً بين عدة streams؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Backpressuring in Streams","url":"https://nodejs.org/docs/latest/api/stream.html#backpressuring-in-streams"}]'::jsonb)) then raise exception 'Question nstream-002 ar content changed; create a new revision before seeding'; end if; end $$;
