insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو كائن Buffer في Node.js وكيف يختلف تخصيص Buffer.alloc عن Buffer.allocUnsafe؟', 'Buffer هو مساحة ذاكرة ثنائية خام؛ Buffer.alloc يصفر الذاكرة لضمان الأمان، بينما allocUnsafe يحجز مساحة غير مصفورة بسرعة أعلى ولكن مع خطر كشف بيانات قديمة.', 'صُممت فئة Buffer للتعامل مع البيانات الثنائية في بروتوكولات الشبكة والملفات. Buffer.alloc(size) يملأ الذاكرة بأصفار لمنع تسريب بيانات قديمة كانت في الـ RAM، بينما يتخطى allocUnsafe التصفير لأداء أقصى عندما تكون على يقين من كتابة البيانات فوق المساحة فوراً.', 'const safe = Buffer.alloc(1024);
const fast = Buffer.allocUnsafe(1024);', '["إرسال Buffer.allocUnsafe عبر الشبكة دون الكتابة فوقه بالكامل، مما قد يسرب بيانات حساسة."]'::jsonb, '["كيف يرتبط كائن Buffer بـ Uint8Array المعياري في JavaScript الحديثة؟"]'::jsonb, '[{"title":"Node.js docs — Buffer","url":"https://nodejs.org/docs/latest/api/buffer.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nstream-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nstream-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو كائن Buffer في Node.js وكيف يختلف تخصيص Buffer.alloc عن Buffer.allocUnsafe؟' or l.short_answer is distinct from 'Buffer هو مساحة ذاكرة ثنائية خام؛ Buffer.alloc يصفر الذاكرة لضمان الأمان، بينما allocUnsafe يحجز مساحة غير مصفورة بسرعة أعلى ولكن مع خطر كشف بيانات قديمة.' or l.explanation is distinct from 'صُممت فئة Buffer للتعامل مع البيانات الثنائية في بروتوكولات الشبكة والملفات. Buffer.alloc(size) يملأ الذاكرة بأصفار لمنع تسريب بيانات قديمة كانت في الـ RAM، بينما يتخطى allocUnsafe التصفير لأداء أقصى عندما تكون على يقين من كتابة البيانات فوق المساحة فوراً.' or l.code_example is distinct from 'const safe = Buffer.alloc(1024);
const fast = Buffer.allocUnsafe(1024);' or l.common_mistakes is distinct from '["إرسال Buffer.allocUnsafe عبر الشبكة دون الكتابة فوقه بالكامل، مما قد يسرب بيانات حساسة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يرتبط كائن Buffer بـ Uint8Array المعياري في JavaScript الحديثة؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Buffer","url":"https://nodejs.org/docs/latest/api/buffer.html"}]'::jsonb)) then raise exception 'Question nstream-004 ar content changed; create a new revision before seeding'; end if; end $$;
