insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم معالجة رفع الملفات الضخمة (Streaming Uploads) في خادم HTTP دون تخزينها في الذاكرة؟', 'يتم توجيه تدفق طلب HTTP (req) مباشرة عبر pipeline إلى ملف على القرص أو خدمة سحابية (S3) كـ multipart stream فور وصول أجزائه.', 'تحميل الملف كاملاً في الذاكرة يؤدي لانهيار الخادم بمجرد رفع ملفات كبيرة. الحل المعماري الصحيح هو معاملة جسم الطلب req كـ Readable Stream وتمريره لأداة تحليل multipart وتوجيهه مباشرة للمخزن النهائي.', 'await pipeline(req, fs.createWriteStream("file.bin"));', '["حفظ محتويات الملف في متغيرات داخلية في الذاكرة قبل كتابتها على القرص."]'::jsonb, '["كيف تحسب بصمة التشفير (SHA-256) للملف أثناء تدفقه دون إعادة قراءته من جديد؟"]'::jsonb, '[{"title":"Node.js docs — HTTP Request and Streams","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nstream-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nstream-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم معالجة رفع الملفات الضخمة (Streaming Uploads) في خادم HTTP دون تخزينها في الذاكرة؟' or l.short_answer is distinct from 'يتم توجيه تدفق طلب HTTP (req) مباشرة عبر pipeline إلى ملف على القرص أو خدمة سحابية (S3) كـ multipart stream فور وصول أجزائه.' or l.explanation is distinct from 'تحميل الملف كاملاً في الذاكرة يؤدي لانهيار الخادم بمجرد رفع ملفات كبيرة. الحل المعماري الصحيح هو معاملة جسم الطلب req كـ Readable Stream وتمريره لأداة تحليل multipart وتوجيهه مباشرة للمخزن النهائي.' or l.code_example is distinct from 'await pipeline(req, fs.createWriteStream("file.bin"));' or l.common_mistakes is distinct from '["حفظ محتويات الملف في متغيرات داخلية في الذاكرة قبل كتابتها على القرص."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحسب بصمة التشفير (SHA-256) للملف أثناء تدفقه دون إعادة قراءته من جديد؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — HTTP Request and Streams","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb)) then raise exception 'Question nstream-006 ar content changed; create a new revision before seeding'; end if; end $$;
