insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يتم إغلاق الـ Streams يدوياً عبر .destroy() وما أهمية التقاط أحداث الـ error؟', 'استدعاء .destroy([error]) يغلق المقابض ويحرر الموارد فوراً لمنع تسرب مآخذ الشبكة أو الملفات المفتوحة.', 'إذا توقف العميل عن الاستماع أو ألغيت العملية، يجب استدعاء stream.destroy() لتحرير مقابض الملفات أو مآخذ الشبكة فوراً وحماية النظام من استنزاف الـ file descriptors.', 'stream.destroy(new Error("Canceled"));', '["افتراض أن انتهاء الدالة يغلق الـ stream تلقائياً دون الحاجة لتدميره في كتلة catch."]'::jsonb, '["ما الفرق بين حدث ''finish'' وحدث ''close'' في الـ Writable streams؟"]'::jsonb, '[{"title":"Node.js docs — stream.destroy","url":"https://nodejs.org/docs/latest/api/stream.html#writabledestroyerror"}]'::jsonb from public.question_revisions r where r.question_id = 'nstream-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nstream-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يتم إغلاق الـ Streams يدوياً عبر .destroy() وما أهمية التقاط أحداث الـ error؟' or l.short_answer is distinct from 'استدعاء .destroy([error]) يغلق المقابض ويحرر الموارد فوراً لمنع تسرب مآخذ الشبكة أو الملفات المفتوحة.' or l.explanation is distinct from 'إذا توقف العميل عن الاستماع أو ألغيت العملية، يجب استدعاء stream.destroy() لتحرير مقابض الملفات أو مآخذ الشبكة فوراً وحماية النظام من استنزاف الـ file descriptors.' or l.code_example is distinct from 'stream.destroy(new Error("Canceled"));' or l.common_mistakes is distinct from '["افتراض أن انتهاء الدالة يغلق الـ stream تلقائياً دون الحاجة لتدميره في كتلة catch."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين حدث ''finish'' وحدث ''close'' في الـ Writable streams؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — stream.destroy","url":"https://nodejs.org/docs/latest/api/stream.html#writabledestroyerror"}]'::jsonb)) then raise exception 'Question nstream-010 ar content changed; create a new revision before seeding'; end if; end $$;
