insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل خادم HTTP الأصيل (node:http) وما هي دورة حياة كائن IncomingMessage و ServerResponse؟', 'يعتمد node:http على خادم أحداث؛ حيث يمثل req تدفق قراءة (Readable) لبيانات الطلب، ويمثل res تدفق كتابة (Writable) لإرسال الترويسات وجسم الاستجابة.', 'تعد وحدة node:http الأساس الذي تبنى عليه أطر عمل مثل Express وFastify. عند اتصال عميل، ينشئ الخادم كائن IncomingMessage يحمل الـ headers وquery params، ويعمل كـ stream لقراءة الـ payload عبر أحداث data وend. في المقابل، يتيح كائن ServerResponse كتابة الترويسات بـ setHeader() وإرسال الـ body عبر .write() وإنهاء الاتصال بـ .end().', 'import http from "node:http";
const server = http.createServer((req, res) => {
  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ status: "ok" }));
});
server.listen(3000);', '["محاولة إرسال res.setHeader() بعد أن تم إرسال الترويسات بالفعل بـ res.write() أو res.end() مما يسبب خطأ Headers already sent."]'::jsonb, '["ما هو الفرق الدقيق بين res.write() و res.end() في node:http؟"]'::jsonb, '[{"title":"Node.js docs — HTTP","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nweb-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nweb-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل خادم HTTP الأصيل (node:http) وما هي دورة حياة كائن IncomingMessage و ServerResponse؟' or l.short_answer is distinct from 'يعتمد node:http على خادم أحداث؛ حيث يمثل req تدفق قراءة (Readable) لبيانات الطلب، ويمثل res تدفق كتابة (Writable) لإرسال الترويسات وجسم الاستجابة.' or l.explanation is distinct from 'تعد وحدة node:http الأساس الذي تبنى عليه أطر عمل مثل Express وFastify. عند اتصال عميل، ينشئ الخادم كائن IncomingMessage يحمل الـ headers وquery params، ويعمل كـ stream لقراءة الـ payload عبر أحداث data وend. في المقابل، يتيح كائن ServerResponse كتابة الترويسات بـ setHeader() وإرسال الـ body عبر .write() وإنهاء الاتصال بـ .end().' or l.code_example is distinct from 'import http from "node:http";
const server = http.createServer((req, res) => {
  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ status: "ok" }));
});
server.listen(3000);' or l.common_mistakes is distinct from '["محاولة إرسال res.setHeader() بعد أن تم إرسال الترويسات بالفعل بـ res.write() أو res.end() مما يسبب خطأ Headers already sent."]'::jsonb or l.follow_up_questions is distinct from '["ما هو الفرق الدقيق بين res.write() و res.end() في node:http؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — HTTP","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb)) then raise exception 'Question nweb-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Node.js developer know about Native Http Server In Node?', 'This question checks the core Native Http Server In Node concept and how to use it safely in Node.js, TypeScript, and backend architectures.', 'Explain Native Http Server In Node with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'import http from "node:http";
