insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('nweb-002', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل الـ Middlewares في Express وما الفرق بين الـ Regular Middleware والـ Error-Handling Middleware؟', 'تنفذ الـ Middlewares بالتتابع عبر استدعاء next()؛ والـ Error Middleware يتميز بقبول 4 معاملات (err, req, res, next) ولا يُستدعى إلا عند تمرير خطأ إلى next(err).', 'الـ Middleware هو دالة تمتلك صلاحية الوصول لكائنات req وres ودالة next(). إذا لم تستدعِ الدالة next() أو تنهِ الاستجابة بـ res.send()، سيعلق الطلب دون رد. للتعامل مع الأخطاء، يُعرف Express دوالاً تحتوي بالضبط 4 معاملات؛ يقوم Express بفحص .length الخاص بالدالة، وعندما تستدعي أي middleware سابقة next(error)، يتخطى Express كل الـ middlewares العادية ويتوجه مباشرة لأول Error Handler.', '// Error handler middleware
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  console.error(err.stack);
  res.status(500).json({ error: "Internal Server Error" });
});', '["حذف المعامل الرابع next من تعريف الـ error handler مما يجعل Express يعامله كـ regular middleware ويتجاهله عند وقوع خطأ."]'::jsonb, '["كيف يتعامل Express 5 مع الـ asynchronous errors مقارنة بـ Express 4؟"]'::jsonb, '[{"title":"Node.js docs — HTTP Server response","url":"https://nodejs.org/docs/latest/api/http.html#class-httpserverresponse"}]'::jsonb from public.question_revisions r where r.question_id = 'nweb-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nweb-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل الـ Middlewares في Express وما الفرق بين الـ Regular Middleware والـ Error-Handling Middleware؟' or l.short_answer is distinct from 'تنفذ الـ Middlewares بالتتابع عبر استدعاء next()؛ والـ Error Middleware يتميز بقبول 4 معاملات (err, req, res, next) ولا يُستدعى إلا عند تمرير خطأ إلى next(err).' or l.explanation is distinct from 'الـ Middleware هو دالة تمتلك صلاحية الوصول لكائنات req وres ودالة next(). إذا لم تستدعِ الدالة next() أو تنهِ الاستجابة بـ res.send()، سيعلق الطلب دون رد. للتعامل مع الأخطاء، يُعرف Express دوالاً تحتوي بالضبط 4 معاملات؛ يقوم Express بفحص .length الخاص بالدالة، وعندما تستدعي أي middleware سابقة next(error)، يتخطى Express كل الـ middlewares العادية ويتوجه مباشرة لأول Error Handler.' or l.code_example is distinct from '// Error handler middleware
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  console.error(err.stack);
  res.status(500).json({ error: "Internal Server Error" });
});' or l.common_mistakes is distinct from '["حذف المعامل الرابع next من تعريف الـ error handler مما يجعل Express يعامله كـ regular middleware ويتجاهله عند وقوع خطأ."]'::jsonb or l.follow_up_questions is distinct from '["كيف يتعامل Express 5 مع الـ asynchronous errors مقارنة بـ Express 4؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — HTTP Server response","url":"https://nodejs.org/docs/latest/api/http.html#class-httpserverresponse"}]'::jsonb)) then raise exception 'Question nweb-002 ar content changed; create a new revision before seeding'; end if; end $$;
