        type: "object",
        properties: { id: { type: "number" }, name: { type: "string" } }
      }
    }
  }
}, async () => ({ id: 1, name: "Fast" }));', '["عدم تعريف schemas في Fastify مما يفقده أبرز مزاياه الأدائية والتحقق التلقائي."]'::jsonb, '["كيف يضمن نظام الـ Encapsulation والـ Plugins في Fastify عزل النطاقات وسرعة الإقلاع؟"]'::jsonb, '[{"title":"Node.js docs — HTTP Benchmarking and Optimization","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nweb-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
