  res.setHeader("Content-Type", "application/json");
  res.end(JSON.stringify(data));
}', '["تجاهل فحص ترويسة Content-Type للطلب ومحاولة تحليل جسم الطلب كـ JSON وهو نص عادي أو multipart."]'::jsonb, '["كيف تساعد مكتبات مثل accepts في التعامل مع ترويسات التفاوض المعقدة؟"]'::jsonb, '[{"title":"Node.js docs — HTTP Headers","url":"https://nodejs.org/docs/latest/api/http.html#messageheaders"}]'::jsonb from public.question_revisions r where r.question_id = 'nweb-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
