insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم خادم WebSockets عالي الكفاءة باستخدام مكتبة ws وكيف تطبق آلية الـ Heartbeat (Ping/Pong)؟', 'تتم ترقية اتصال HTTP الأصلي إلى مقبس ثنائي الاتجاه، ويتم إرسال إشارات Ping دورية للتأكد من حيوية الاتصال وإغلاق المقابس الميتة (Zombie Connections).', 'تبدأ اتصالات WebSockets بطلب HTTP عادي مع ترويسة Upgrade: websocket. بمجرد الترقية، يتحول الاتصال إلى TCP stream ثنائي الاتجاه. نظراً لأن انقطاع اتصال العميل المفاجئ (كإغلاق الواي فاي) قد لا يرسل حزمة TCP FIN، يجب على الخادم إرسال رسائل Ping كل 30 ثانية؛ إذا لم يرد العميل بـ Pong، يُعد الاتصال ميتاً ويستدعى socket.terminate() لتحرير الموارد.', 'import { WebSocketServer } from "ws";
const wss = new WebSocketServer({ port: 8080 });
setInterval(() => {
  wss.clients.forEach(ws => {
    if (!ws.isAlive) return ws.terminate();
    ws.isAlive = false;
    ws.ping();
  });
}, 30000);', '["إغفال تطبيق الـ Ping/Pong مما يتسبب في بقاء آلاف المقابس الميتة مفتوحة في السيرفر وتآكل الذاكرة."]'::jsonb, '["كيف توزع اتصالات WebSockets عبر عدة خوادم باستخدام Redis Pub/Sub؟"]'::jsonb, '[{"title":"Node.js docs — HTTP Upgrade Event","url":"https://nodejs.org/docs/latest/api/http.html#event-upgrade"}]'::jsonb from public.question_revisions r where r.question_id = 'nweb-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nweb-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم خادم WebSockets عالي الكفاءة باستخدام مكتبة ws وكيف تطبق آلية الـ Heartbeat (Ping/Pong)؟' or l.short_answer is distinct from 'تتم ترقية اتصال HTTP الأصلي إلى مقبس ثنائي الاتجاه، ويتم إرسال إشارات Ping دورية للتأكد من حيوية الاتصال وإغلاق المقابس الميتة (Zombie Connections).' or l.explanation is distinct from 'تبدأ اتصالات WebSockets بطلب HTTP عادي مع ترويسة Upgrade: websocket. بمجرد الترقية، يتحول الاتصال إلى TCP stream ثنائي الاتجاه. نظراً لأن انقطاع اتصال العميل المفاجئ (كإغلاق الواي فاي) قد لا يرسل حزمة TCP FIN، يجب على الخادم إرسال رسائل Ping كل 30 ثانية؛ إذا لم يرد العميل بـ Pong، يُعد الاتصال ميتاً ويستدعى socket.terminate() لتحرير الموارد.' or l.code_example is distinct from 'import { WebSocketServer } from "ws";
const wss = new WebSocketServer({ port: 8080 });
setInterval(() => {
  wss.clients.forEach(ws => {
    if (!ws.isAlive) return ws.terminate();
    ws.isAlive = false;
    ws.ping();
  });
}, 30000);' or l.common_mistakes is distinct from '["إغفال تطبيق الـ Ping/Pong مما يتسبب في بقاء آلاف المقابس الميتة مفتوحة في السيرفر وتآكل الذاكرة."]'::jsonb or l.follow_up_questions is distinct from '["كيف توزع اتصالات WebSockets عبر عدة خوادم باستخدام Redis Pub/Sub؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — HTTP Upgrade Event","url":"https://nodejs.org/docs/latest/api/http.html#event-upgrade"}]'::jsonb)) then raise exception 'Question nweb-007 ar content changed; create a new revision before seeding'; end if; end $$;
