insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل حمامات الاتصال (Connection Pools) في قواعد البيانات وما مخاطر تشبعها في Node.js؟', 'تدير حمامات الاتصال مجموعة اتصالات مفتوحة مسبقاً وتشاركها بين الطلبات؛ وتشبعها يؤدي لتراكم الطلبات في طابور الانتظار وزيادة زمن الاستجابة والـ timeouts.', 'إنشاء اتصال جديد بقاعدة البيانات (TCP Handshake + TLS + Authentication) مكلف للغاية ويستغرق عشرات المللي ثوانٍ. يوفر الـ Pool (مثل pg.Pool) عدداً ثابتاً من الاتصالات (مثلاً 20 اتصالاً) يتم استعارتها عبر client = await pool.connect() وإرجاعها بـ client.release(). إذا استغرقت الاستعلامات وقتاً طويلاً أو حدث تسريب اتصالات (نسيان release)، سيعلق السيرفر في انتظار اتصال متاح.', 'const client = await pool.connect();
try {
  const res = await client.query("SELECT * FROM users WHERE id = $1", [id]);
} finally {
  client.release(); // ضروري دائماً في finally
}', '["نسيان استدعاء client.release() داخل كتلة finally مما يفرغ الـ pool بسرعة ويسقط السيرفر."]'::jsonb, '["كيف تحدد الحجم الأمثل لحمام الاتصالات بناءً على عدد أنوية قاعدة البيانات وتطبيقات السيرفر؟"]'::jsonb, '[{"title":"Node.js docs — Database Best Practices and Net Sockets","url":"https://nodejs.org/docs/latest/api/net.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ndb-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ndb-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل حمامات الاتصال (Connection Pools) في قواعد البيانات وما مخاطر تشبعها في Node.js؟' or l.short_answer is distinct from 'تدير حمامات الاتصال مجموعة اتصالات مفتوحة مسبقاً وتشاركها بين الطلبات؛ وتشبعها يؤدي لتراكم الطلبات في طابور الانتظار وزيادة زمن الاستجابة والـ timeouts.' or l.explanation is distinct from 'إنشاء اتصال جديد بقاعدة البيانات (TCP Handshake + TLS + Authentication) مكلف للغاية ويستغرق عشرات المللي ثوانٍ. يوفر الـ Pool (مثل pg.Pool) عدداً ثابتاً من الاتصالات (مثلاً 20 اتصالاً) يتم استعارتها عبر client = await pool.connect() وإرجاعها بـ client.release(). إذا استغرقت الاستعلامات وقتاً طويلاً أو حدث تسريب اتصالات (نسيان release)، سيعلق السيرفر في انتظار اتصال متاح.' or l.code_example is distinct from 'const client = await pool.connect();
try {
  const res = await client.query("SELECT * FROM users WHERE id = $1", [id]);
} finally {
  client.release(); // ضروري دائماً في finally
}' or l.common_mistakes is distinct from '["نسيان استدعاء client.release() داخل كتلة finally مما يفرغ الـ pool بسرعة ويسقط السيرفر."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحدد الحجم الأمثل لحمام الاتصالات بناءً على عدد أنوية قاعدة البيانات وتطبيقات السيرفر؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Database Best Practices and Net Sockets","url":"https://nodejs.org/docs/latest/api/net.html"}]'::jsonb)) then raise exception 'Question ndb-001 ar content changed; create a new revision before seeding'; end if; end $$;
