insert into public.interview_questions (id, slug, track_id, difficulty) values ('ndb-002', 'prisma-orm-query-engine-and-migrations-in-node', 'node', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
