await db.query("SELECT * FROM users WHERE email = $1 AND role = $2", [email, role]);', '["استخدام الـ string interpolation مع مكتبات قواعد البيانات بحجة أن المدخلات مفحوصة."]'::jsonb, '["كيف تتعامل مع الأسماء الديناميكية للأعمدة والجداول التي لا تقبل الـ Parameterized values؟"]'::jsonb, '[{"title":"Node.js docs — Security Best Practices","url":"https://nodejs.org/docs/latest/api/crypto.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ndb-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
