insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تنفذ المعاملات المترابطة (Database Transactions) ومستويات العزل بأمان في Node.js؟', 'تنفذ بحجز عميل محدد من الـ pool، وتشغيل BEGIN، وتنفيذ العمليات، ثم COMMIT في حال النجاح أو ROLLBACK في كتلة catch.', 'المعاملة تضمن مبدأ الذرية (Atomicity) في ACID؛ فإما أن تنجح كل التعديلات معاً أو تُلغى بالكامل. من الضروري جداً استخدام نفس الاتصال (Dedicated Client) لكل عمليات المعاملة الواحدة، لأن استدعاء pool.query() يوزع العمليات عشوائياً عبر اتصالات مختلفة مما يفسد المعاملة تماماً.', 'const client = await pool.connect();
try {
  await client.query("BEGIN");
  await client.query("UPDATE accounts SET balance = balance - 100 WHERE id = $1", [from]);
  await client.query("UPDATE accounts SET balance = balance + 100 WHERE id = $2", [to]);
  await client.query("COMMIT");
} catch (e) {
  await client.query("ROLLBACK");
  throw e;
} finally {
  client.release();
}', '["تنفيذ أوامر BEGIN و COMMIT عبر pool.query المباشر بدلاً من عميل مخصص محجوز."]'::jsonb, '["ما الفرق بين مستويات العزل Read Committed و Serializable ومتى تحتاج الأخير؟"]'::jsonb, '[{"title":"Node.js docs — Client Pool Interactions","url":"https://nodejs.org/docs/latest/api/net.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ndb-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ndb-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تنفذ المعاملات المترابطة (Database Transactions) ومستويات العزل بأمان في Node.js؟' or l.short_answer is distinct from 'تنفذ بحجز عميل محدد من الـ pool، وتشغيل BEGIN، وتنفيذ العمليات، ثم COMMIT في حال النجاح أو ROLLBACK في كتلة catch.' or l.explanation is distinct from 'المعاملة تضمن مبدأ الذرية (Atomicity) في ACID؛ فإما أن تنجح كل التعديلات معاً أو تُلغى بالكامل. من الضروري جداً استخدام نفس الاتصال (Dedicated Client) لكل عمليات المعاملة الواحدة، لأن استدعاء pool.query() يوزع العمليات عشوائياً عبر اتصالات مختلفة مما يفسد المعاملة تماماً.' or l.code_example is distinct from 'const client = await pool.connect();
try {
  await client.query("BEGIN");
  await client.query("UPDATE accounts SET balance = balance - 100 WHERE id = $1", [from]);
  await client.query("UPDATE accounts SET balance = balance + 100 WHERE id = $2", [to]);
  await client.query("COMMIT");
} catch (e) {
  await client.query("ROLLBACK");
  throw e;
} finally {
  client.release();
}' or l.common_mistakes is distinct from '["تنفيذ أوامر BEGIN و COMMIT عبر pool.query المباشر بدلاً من عميل مخصص محجوز."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين مستويات العزل Read Committed و Serializable ومتى تحتاج الأخير؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Client Pool Interactions","url":"https://nodejs.org/docs/latest/api/net.html"}]'::jsonb)) then raise exception 'Question ndb-006 ar content changed; create a new revision before seeding'; end if; end $$;
