const userLoader = new DataLoader(async (ids) => {
  const users = await db.query("SELECT * FROM users WHERE id = ANY($1)", [ids]);
  return ids.map(id => users.find(u => u.id === id));
});' or l.common_mistakes is distinct from '["إعادة استخدام نفس كائن DataLoader عبر طلبات مستخدمين مختلفين مما يسرب البيانات المخزنة مؤقتاً."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يجب إنشاء كائن DataLoader جديد لكل طلب HTTP مستقل؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Event loop tick batching","url":"https://nodejs.org/docs/latest/api/process.html#processnexttickcallback-args"}]'::jsonb)) then raise exception 'Question ndb-007 ar content changed; create a new revision before seeding'; end if; end $$;
