insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق الأقفال الموزعة (Distributed Locks) باستخدام Redis في بيئة خوادم Node.js متعددة؟', 'تطبق عبر أمر SET مع خيارات NX وPX لتسجيل رمز عشوائي بمهلة زمنية، وتحرير القفل بواسطة Lua script يتحقق من مطابقة الرمز.', 'عند تشغيل عدة نسخ من خادم Node.js ووجود عملية حرجة (مثل خصم رصيد أو حجز مقعد وحيد)، لا تجدي متغيرات الذاكرة نفعاً. يتم الحصول على القفل الذري عبر Redis: SET lock_key my_unique_token NX PX 30000. التحرير يجب أن يكون حصرياً عبر Lua Script لضمان عدم حذف قفل انتهت مدته وأخذه خادم آخر.', '// Lua script لتحرير القفل الذري
const releaseScript = `
  if redis.call("get", KEYS[1]) == ARGV[1] then
    return redis.call("del", KEYS[1])
  else
    return 0
  end
`;', '["تحرير القفل بأمر DEL البسيط دون التحقق من أن الـ token لا يزال يخص العملية الحالية."]'::jsonb, '["متى تحتاج لاستخدام خوارزمية Redlock مع مجموعات Redis المتعددة؟"]'::jsonb, '[{"title":"Node.js docs — Crypto randomBytes for lock tokens","url":"https://nodejs.org/docs/latest/api/crypto.html#cryptorandombytesize-callback"}]'::jsonb from public.question_revisions r where r.question_id = 'ndb-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ndb-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق الأقفال الموزعة (Distributed Locks) باستخدام Redis في بيئة خوادم Node.js متعددة؟' or l.short_answer is distinct from 'تطبق عبر أمر SET مع خيارات NX وPX لتسجيل رمز عشوائي بمهلة زمنية، وتحرير القفل بواسطة Lua script يتحقق من مطابقة الرمز.' or l.explanation is distinct from 'عند تشغيل عدة نسخ من خادم Node.js ووجود عملية حرجة (مثل خصم رصيد أو حجز مقعد وحيد)، لا تجدي متغيرات الذاكرة نفعاً. يتم الحصول على القفل الذري عبر Redis: SET lock_key my_unique_token NX PX 30000. التحرير يجب أن يكون حصرياً عبر Lua Script لضمان عدم حذف قفل انتهت مدته وأخذه خادم آخر.' or l.code_example is distinct from '// Lua script لتحرير القفل الذري
const releaseScript = `
