insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين خوارزميات التوقيع المتناظرة (HS256) وغير المتناظرة (RS256) في رموز JWT بـ Node.js؟', 'HS256 تستخدم نفس المفتاح السري المشترك للتوقيع والتحقق، بينما RS256 تستخدم مفتاحاً خاصاً للتوقيع ومفتاحاً عاماً متاحاً للجميع للتحقق.', 'في المعماريات البسيطة، تعد HS256 كافية وممتازة لأن خادماً واحداً يقوم بالتوليد والتحقق. أما في معمارية الـ Microservices وتطبيقات الـ SSO، تفضل RS256؛ حيث تحتفظ خدمة المصادقة (Auth Service) بالمفتاح الخاص لتوليد التوكن، وتستطيع كل الخدمات الأخرى التحقق من صحة التوكن باستقلالية تامة باستخدام المفتاح العام دون إمكانية تزويره.', 'import jwt from "jsonwebtoken";
// RS256: توقيع بالمفتاح الخاص
const token = jwt.sign({ sub: userId }, privateKey, { algorithm: "RS256", expiresIn: "15m" });
// تحقق بالمفتاح العام
const payload = jwt.verify(token, publicKey, { algorithms: ["RS256"] });', '["عدم تحديد قائمة الخوارزميات المسموحة في خيارات verify مما يعرض التطبيق لثغرة None Algorithm."]'::jsonb, '["كيف تحمي الخادم من هجمات التراجع (Algorithm Confusion Attack) بين HMAC و RSA؟"]'::jsonb, '[{"title":"Node.js docs — Crypto module and key pairs","url":"https://nodejs.org/docs/latest/api/crypto.html#cryptogeneratekeypairsynctype-options"}]'::jsonb from public.question_revisions r where r.question_id = 'nsec-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsec-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين خوارزميات التوقيع المتناظرة (HS256) وغير المتناظرة (RS256) في رموز JWT بـ Node.js؟' or l.short_answer is distinct from 'HS256 تستخدم نفس المفتاح السري المشترك للتوقيع والتحقق، بينما RS256 تستخدم مفتاحاً خاصاً للتوقيع ومفتاحاً عاماً متاحاً للجميع للتحقق.' or l.explanation is distinct from 'في المعماريات البسيطة، تعد HS256 كافية وممتازة لأن خادماً واحداً يقوم بالتوليد والتحقق. أما في معمارية الـ Microservices وتطبيقات الـ SSO، تفضل RS256؛ حيث تحتفظ خدمة المصادقة (Auth Service) بالمفتاح الخاص لتوليد التوكن، وتستطيع كل الخدمات الأخرى التحقق من صحة التوكن باستقلالية تامة باستخدام المفتاح العام دون إمكانية تزويره.' or l.code_example is distinct from 'import jwt from "jsonwebtoken";
// RS256: توقيع بالمفتاح الخاص
const token = jwt.sign({ sub: userId }, privateKey, { algorithm: "RS256", expiresIn: "15m" });
// تحقق بالمفتاح العام
const payload = jwt.verify(token, publicKey, { algorithms: ["RS256"] });' or l.common_mistakes is distinct from '["عدم تحديد قائمة الخوارزميات المسموحة في خيارات verify مما يعرض التطبيق لثغرة None Algorithm."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحمي الخادم من هجمات التراجع (Algorithm Confusion Attack) بين HMAC و RSA؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Crypto module and key pairs","url":"https://nodejs.org/docs/latest/api/crypto.html#cryptogeneratekeypairsynctype-options"}]'::jsonb)) then raise exception 'Question nsec-001 ar content changed; create a new revision before seeding'; end if; end $$;
