insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي سياسة تقاسم الموارد عبر الأصول (CORS) وما هي طلبات الفحص المسبق (Preflight Requests)؟', 'CORS هي آلية أمان تطبقها المتصفحات لمنع المواقع الخارجية من قراءة بياناتك؛ وطلب الـ Preflight هو طلب OPTIONS يرسله المتصفح قبل الطلب الفعلي للتحقق من السماح بالعملية.', 'تطلب المتصفحات موافقة صريحة من الخادم عندما يحاول تطبيق جافاسكريبت قراءة استجابة من نطاق مختلف. إذا احتوى الطلب على ترويسات غير قياسية (مثل Authorization) أو أساليب غير بسيطة (مثل PUT أو DELETE أو POST مع JSON)، يرسل المتصفح أولاً طلب OPTIONS (Preflight). يجب على الخادم الرد بترويسات Access-Control-Allow-Origin وAccess-Control-Allow-Methods المناسبة.', 'import cors from "cors";
app.use(cors({
  origin: "https://my-frontend.com",
  methods: ["GET", "POST", "PUT", "DELETE"],
  credentials: true
}));', '["تعيين Access-Control-Allow-Origin: * مع تفعيل credentials: true وهو ما ترفضه المتصفحات أمنياً."]'::jsonb, '["لماذا لا تحمي سياسة CORS خوادم الـ Backend من طلبات أدوات مثل Postman أو curl؟"]'::jsonb, '[{"title":"Node.js docs — HTTP Headers and Options requests","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nsec-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsec-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي سياسة تقاسم الموارد عبر الأصول (CORS) وما هي طلبات الفحص المسبق (Preflight Requests)؟' or l.short_answer is distinct from 'CORS هي آلية أمان تطبقها المتصفحات لمنع المواقع الخارجية من قراءة بياناتك؛ وطلب الـ Preflight هو طلب OPTIONS يرسله المتصفح قبل الطلب الفعلي للتحقق من السماح بالعملية.' or l.explanation is distinct from 'تطلب المتصفحات موافقة صريحة من الخادم عندما يحاول تطبيق جافاسكريبت قراءة استجابة من نطاق مختلف. إذا احتوى الطلب على ترويسات غير قياسية (مثل Authorization) أو أساليب غير بسيطة (مثل PUT أو DELETE أو POST مع JSON)، يرسل المتصفح أولاً طلب OPTIONS (Preflight). يجب على الخادم الرد بترويسات Access-Control-Allow-Origin وAccess-Control-Allow-Methods المناسبة.' or l.code_example is distinct from 'import cors from "cors";
app.use(cors({
  origin: "https://my-frontend.com",
  methods: ["GET", "POST", "PUT", "DELETE"],
  credentials: true
}));' or l.common_mistakes is distinct from '["تعيين Access-Control-Allow-Origin: * مع تفعيل credentials: true وهو ما ترفضه المتصفحات أمنياً."]'::jsonb or l.follow_up_questions is distinct from '["لماذا لا تحمي سياسة CORS خوادم الـ Backend من طلبات أدوات مثل Postman أو curl؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — HTTP Headers and Options requests","url":"https://nodejs.org/docs/latest/api/http.html"}]'::jsonb)) then raise exception 'Question nsec-005 ar content changed; create a new revision before seeding'; end if; end $$;
