insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي ثغرة تلوث النموذج الأولي (Prototype Pollution) في JavaScript وكيف تتجنبها في Node.js؟', 'ثغرة تسمح للمهاجم بحقن خصائص خبيثة في كائن Object.prototype العام عبر كائنات مدمجة بعمق تحتوي على __proto__ مما يفسد سلوك التطبيق بالكامل.', 'عند دمج كائنات JSON عشوائية دون تصفية دقيقة (كما في دوال الـ recursive merge أو lodash القديمة)، إذا أرسل المهاجم {''__proto__'': {''admin'': true}}، ستضاف هذه الخاصية لكل كائن يتم إنشاؤه في التطبيق. الوقاية تتم باستخدام Object.create(null) للكائنات القاموسية، وتجميد النموذج الأساسي بـ Object.freeze(Object.prototype)، أو تفعيل خيار Map بدلاً من الكائنات العادية.', '// كائن آمن تماماً لا يملك prototype
const safeDict = Object.create(null);
// أو استخدام Map المعياري
const safeMap = new Map();', '["استخدام دوال دمج الكائنات (Object deep merge) غير الموثوقة لمدخلات المستخدمين المباشرة."]'::jsonb, '["كيف تحظر Node.js معالجة __proto__ عبر راية التشغيل --disable-proto=delete؟"]'::jsonb, '[{"title":"Node.js docs — Command-line options: disable-proto","url":"https://nodejs.org/docs/latest/api/cli.html#--disable-protomode"}]'::jsonb from public.question_revisions r where r.question_id = 'nsec-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsec-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي ثغرة تلوث النموذج الأولي (Prototype Pollution) في JavaScript وكيف تتجنبها في Node.js؟' or l.short_answer is distinct from 'ثغرة تسمح للمهاجم بحقن خصائص خبيثة في كائن Object.prototype العام عبر كائنات مدمجة بعمق تحتوي على __proto__ مما يفسد سلوك التطبيق بالكامل.' or l.explanation is distinct from 'عند دمج كائنات JSON عشوائية دون تصفية دقيقة (كما في دوال الـ recursive merge أو lodash القديمة)، إذا أرسل المهاجم {''__proto__'': {''admin'': true}}، ستضاف هذه الخاصية لكل كائن يتم إنشاؤه في التطبيق. الوقاية تتم باستخدام Object.create(null) للكائنات القاموسية، وتجميد النموذج الأساسي بـ Object.freeze(Object.prototype)، أو تفعيل خيار Map بدلاً من الكائنات العادية.' or l.code_example is distinct from '// كائن آمن تماماً لا يملك prototype
const safeDict = Object.create(null);
// أو استخدام Map المعياري
const safeMap = new Map();' or l.common_mistakes is distinct from '["استخدام دوال دمج الكائنات (Object deep merge) غير الموثوقة لمدخلات المستخدمين المباشرة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحظر Node.js معالجة __proto__ عبر راية التشغيل --disable-proto=delete؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Command-line options: disable-proto","url":"https://nodejs.org/docs/latest/api/cli.html#--disable-protomode"}]'::jsonb)) then raise exception 'Question nsec-007 ar content changed; create a new revision before seeding'; end if; end $$;
