insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق نمط Cache-Aside واستراتيجيات إبطال التخزين المؤقت (Cache Invalidation)؟', 'يفحص السيرفر الـ Cache أولاً؛ فإن وجد البيانات أعادها، وإلا جلبها من قاعدة البيانات وحفظها في الـ Cache مع تعيين مدة صلاحية (TTL)، ويتم إبطالها عند التعديل.', 'في نمط Cache-Aside (Lazy Loading)، يتحكم تطبيق Node.js مباشرة في القراءة والكتابة للـ Cache (غالباً Redis). لضمان عدم تقديم بيانات قديمة، يجب تعيين مهلة صلاحية مدروسة (TTL)، مع تطبيق إبطال فوري للمفتاح عند تنفيذ أي عملية تحديث أو حذف، أو استخدام استراتيجيات مثل Write-Through في الأنظمة الحرجة.', 'const cached = await redis.get(key);
if (cached) return JSON.parse(cached);
const data = await db.fetch(id);
await redis.set(key, JSON.stringify(data), "EX", 300);
return data;', '["تخزين الكائنات في الـ Cache دون تعيين TTL مما يسبب تضخم الذاكرة وتقديم بيانات غير متزامنة للأبد."]'::jsonb, '["ما هي ظاهرة الـ Cache Stampede (Dog-piling) وكيف تحمي قاعدة البيانات منها؟"]'::jsonb, '[{"title":"Node.js docs — Performance and caching concepts","url":"https://nodejs.org/docs/latest/api/perf_hooks.html"}]'::jsonb from public.question_revisions r where r.question_id = 'nperf-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nperf-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق نمط Cache-Aside واستراتيجيات إبطال التخزين المؤقت (Cache Invalidation)؟' or l.short_answer is distinct from 'يفحص السيرفر الـ Cache أولاً؛ فإن وجد البيانات أعادها، وإلا جلبها من قاعدة البيانات وحفظها في الـ Cache مع تعيين مدة صلاحية (TTL)، ويتم إبطالها عند التعديل.' or l.explanation is distinct from 'في نمط Cache-Aside (Lazy Loading)، يتحكم تطبيق Node.js مباشرة في القراءة والكتابة للـ Cache (غالباً Redis). لضمان عدم تقديم بيانات قديمة، يجب تعيين مهلة صلاحية مدروسة (TTL)، مع تطبيق إبطال فوري للمفتاح عند تنفيذ أي عملية تحديث أو حذف، أو استخدام استراتيجيات مثل Write-Through في الأنظمة الحرجة.' or l.code_example is distinct from 'const cached = await redis.get(key);
if (cached) return JSON.parse(cached);
const data = await db.fetch(id);
await redis.set(key, JSON.stringify(data), "EX", 300);
return data;' or l.common_mistakes is distinct from '["تخزين الكائنات في الـ Cache دون تعيين TTL مما يسبب تضخم الذاكرة وتقديم بيانات غير متزامنة للأبد."]'::jsonb or l.follow_up_questions is distinct from '["ما هي ظاهرة الـ Cache Stampede (Dog-piling) وكيف تحمي قاعدة البيانات منها؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Performance and caching concepts","url":"https://nodejs.org/docs/latest/api/perf_hooks.html"}]'::jsonb)) then raise exception 'Question nperf-006 ar content changed; create a new revision before seeding'; end if; end $$;
