insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تضبط راية --max-old-space-size ومتى يلزم تعديل خيارات الـ Garbage Collector لمحرك V8؟', 'تحدد الراية الحد الأقصى لذاكرة الـ Heap بالميجابايت قبل إطلاق الـ Out of Memory، ويلزم تعديلها عند معالجة بيانات ضخمة مع مراعاة حدود حاوية Docker.', 'افتراضياً، تحدد Node.js حداً أقصى للذاكرة بناءً على حجم الرام المتوفر للنظام (غالباً بين 2GB إلى 4GB على أنظمة 64-bit). في بيئات الحاويات، إذا تم تعيين max-old-space-size بقيمة تفوق حد ذاكرة الحاوية (Container Memory Limit)، سيقوم نظام التشغيل (OOM Killer) بإنهاء الحاوية قسرياً دون أن يحصل V8 على فرصة لتنظيف الذاكرة.', '// تشغيل: node --max-old-space-size=4096 app.js', '["تعيين الحد بقيمة مساوية لذاكرة الحاوية تماماً مع نسيان استهلاك الذاكرة خارج الـ Heap (مثل Buffers وخيوط الـ C++)."]'::jsonb, '["كيف تراقب توقفات الـ Garbage Collection عبر PerformanceObserver و node:perf_hooks؟"]'::jsonb, '[{"title":"Node.js docs — Command-line options: max-old-space-size","url":"https://nodejs.org/docs/latest/api/cli.html#--max-old-space-sizesize-in-megabytes"}]'::jsonb from public.question_revisions r where r.question_id = 'nperf-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nperf-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تضبط راية --max-old-space-size ومتى يلزم تعديل خيارات الـ Garbage Collector لمحرك V8؟' or l.short_answer is distinct from 'تحدد الراية الحد الأقصى لذاكرة الـ Heap بالميجابايت قبل إطلاق الـ Out of Memory، ويلزم تعديلها عند معالجة بيانات ضخمة مع مراعاة حدود حاوية Docker.' or l.explanation is distinct from 'افتراضياً، تحدد Node.js حداً أقصى للذاكرة بناءً على حجم الرام المتوفر للنظام (غالباً بين 2GB إلى 4GB على أنظمة 64-bit). في بيئات الحاويات، إذا تم تعيين max-old-space-size بقيمة تفوق حد ذاكرة الحاوية (Container Memory Limit)، سيقوم نظام التشغيل (OOM Killer) بإنهاء الحاوية قسرياً دون أن يحصل V8 على فرصة لتنظيف الذاكرة.' or l.code_example is distinct from '// تشغيل: node --max-old-space-size=4096 app.js' or l.common_mistakes is distinct from '["تعيين الحد بقيمة مساوية لذاكرة الحاوية تماماً مع نسيان استهلاك الذاكرة خارج الـ Heap (مثل Buffers وخيوط الـ C++)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تراقب توقفات الـ Garbage Collection عبر PerformanceObserver و node:perf_hooks؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Command-line options: max-old-space-size","url":"https://nodejs.org/docs/latest/api/cli.html#--max-old-space-sizesize-in-megabytes"}]'::jsonb)) then raise exception 'Question nperf-007 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Node.js developer know about V8 Gc Flags And Heap Limits In Node?', 'This question checks the core V8 Gc Flags And Heap Limits In Node concept and how to use it safely in Node.js, TypeScript, and backend architectures.', 'Explain V8 Gc Flags And Heap Limits In Node with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// تشغيل: node --max-old-space-size=4096 app.js', '["Missing the key trade-off in V8 Gc Flags And Heap Limits In Node (point 1)."]'::jsonb, '["How would you apply V8 Gc Flags And Heap Limits In Node in a production Node.js app (follow-up 1)?"]'::jsonb, '[{"title":"Node.js docs — Command-line options: max-old-space-size","url":"https://nodejs.org/docs/latest/api/cli.html#--max-old-space-sizesize-in-megabytes"}]'::jsonb from public.question_revisions r where r.question_id = 'nperf-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
