const container = await new PostgreSqlContainer().start();
const dbUri = container.getConnectionUri();
// إجراء الاختبارات ثم إيقاف الحاوية
await container.stop();', '["إعادة إنشاء حاوية Docker جديدة لكل اختبار فردي مما يرفع زمن تنفيذ الـ suite لعشرات الدقائق بدلاً من مشاركتها."]'::jsonb, '["كيف تشارك حاوية واحدة عبر جميع الاختبارات مع مسح البيانات (Truncate) بين الاختبارات؟"]'::jsonb, '[{"title":"Node.js docs — Child process and container orchestration","url":"https://nodejs.org/docs/latest/api/child_process.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ntest-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
