insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي أسباب الاختبارات المتقلبة (Flaky Tests) وكيف تحقق الحتمية (Determinism) في الاختبارات؟', 'أسبابها هي الاعتماد على توقيتات غير مضمونة (Timeouts عشوائية)، أو ترتيب الاختبارات، أو الوقت الحالي للنظام، أو بقايا بيانات سابقة، وتعالج بتجميد الوقت وتنظيف البيئة.', 'الاختبار المتقلب هو اختبار ينجح تارة ويفشل تارة أخرى لنفس الكود. للقضاء عليها: 1) لا تستخدم setTimeout لانتظار أحداث غير متزامنة، بل استمع للأحداث الحقيقية، 2) استخدم مكتبات تجميد الوقت (Mocking Timers) للتحكم في new Date()، 3) عزل قواعد البيانات وتوليد معرفات وبيانات مستقلة لكل اختبار على حدة.', '// استخدام mock timers الأصلية في node:test
test.mock.timers.enable();
test.mock.timers.tick(5000);', '["وضع setTimeout(..., 2000) في الاختبار بافتراض أن العملية ستنتهي حتماً في ثانيتين، وهو ما يفشل على خوادم الـ CI البطيئة."]'::jsonb, '["كيف تستخدم ميزة test.mock.timers المدمجة في Node.js لاختبار الفواصل الزمنية بدقة؟"]'::jsonb, '[{"title":"Node.js docs — Mocking Timers","url":"https://nodejs.org/docs/latest/api/test.html#mock-timers"}]'::jsonb from public.question_revisions r where r.question_id = 'ntest-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ntest-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي أسباب الاختبارات المتقلبة (Flaky Tests) وكيف تحقق الحتمية (Determinism) في الاختبارات؟' or l.short_answer is distinct from 'أسبابها هي الاعتماد على توقيتات غير مضمونة (Timeouts عشوائية)، أو ترتيب الاختبارات، أو الوقت الحالي للنظام، أو بقايا بيانات سابقة، وتعالج بتجميد الوقت وتنظيف البيئة.' or l.explanation is distinct from 'الاختبار المتقلب هو اختبار ينجح تارة ويفشل تارة أخرى لنفس الكود. للقضاء عليها: 1) لا تستخدم setTimeout لانتظار أحداث غير متزامنة، بل استمع للأحداث الحقيقية، 2) استخدم مكتبات تجميد الوقت (Mocking Timers) للتحكم في new Date()، 3) عزل قواعد البيانات وتوليد معرفات وبيانات مستقلة لكل اختبار على حدة.' or l.code_example is distinct from '// استخدام mock timers الأصلية في node:test
test.mock.timers.enable();
test.mock.timers.tick(5000);' or l.common_mistakes is distinct from '["وضع setTimeout(..., 2000) في الاختبار بافتراض أن العملية ستنتهي حتماً في ثانيتين، وهو ما يفشل على خوادم الـ CI البطيئة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستخدم ميزة test.mock.timers المدمجة في Node.js لاختبار الفواصل الزمنية بدقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Mocking Timers","url":"https://nodejs.org/docs/latest/api/test.html#mock-timers"}]'::jsonb)) then raise exception 'Question ntest-010 ar content changed; create a new revision before seeding'; end if; end $$;
