insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق مبادئ المعمارية النظيفة (Clean Architecture) وفصل الاهتمامات في تطبيق Node.js؟', 'بتقسيم النظام إلى طبقات متحدة المركز: Entities، Use Cases، Controllers/Presenters، وInfrastructure، بحيث تشير التبعيات دائماً للداخل نحو منطق الأعمال المجرد.', 'الهدف هو جعل منطق الأعمال الأساسي (Domain & Use Cases) مستقلاً تماماً عن أي تفاصيل تقنية مثل إطار العمل (Express/Fastify) أو نوع قاعدة البيانات (PostgreSQL/MongoDB). يتم ذلك عبر مبدأ عكس التبعيات (Dependency Inversion)؛ حيث تعرّف طبقة الـ Use Cases واجهات برمجية (Interfaces/Ports)، وتقوم طبقة الـ Infrastructure بتنفيذها وتزويدها عبر الـ Dependency Injection.', '// Use Case مستقلة عن قاعدة البيانات
export class RegisterUserUseCase {
  constructor(private readonly userRepo: UserRepositoryPort) {}
  async execute(dto: RegisterUserDto) {
    // منطق العمل النقي
  }
}', '["استيراد نماذج قواعد البيانات (مثل نماذج Mongoose أو TypeORM) مباشرة داخل طبقة الـ Use Cases."]'::jsonb, '["كيف تسهل المعمارية النظيفة استبدال إطار عمل السيرفر دون لمس منطق الأعمال؟"]'::jsonb, '[{"title":"Node.js docs — Architectural Design Patterns","url":"https://nodejs.org/docs/latest/api/modules.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق مبادئ المعمارية النظيفة (Clean Architecture) وفصل الاهتمامات في تطبيق Node.js؟' or l.short_answer is distinct from 'بتقسيم النظام إلى طبقات متحدة المركز: Entities، Use Cases، Controllers/Presenters، وInfrastructure، بحيث تشير التبعيات دائماً للداخل نحو منطق الأعمال المجرد.' or l.explanation is distinct from 'الهدف هو جعل منطق الأعمال الأساسي (Domain & Use Cases) مستقلاً تماماً عن أي تفاصيل تقنية مثل إطار العمل (Express/Fastify) أو نوع قاعدة البيانات (PostgreSQL/MongoDB). يتم ذلك عبر مبدأ عكس التبعيات (Dependency Inversion)؛ حيث تعرّف طبقة الـ Use Cases واجهات برمجية (Interfaces/Ports)، وتقوم طبقة الـ Infrastructure بتنفيذها وتزويدها عبر الـ Dependency Injection.' or l.code_example is distinct from '// Use Case مستقلة عن قاعدة البيانات
export class RegisterUserUseCase {
  constructor(private readonly userRepo: UserRepositoryPort) {}
  async execute(dto: RegisterUserDto) {
    // منطق العمل النقي
  }
}' or l.common_mistakes is distinct from '["استيراد نماذج قواعد البيانات (مثل نماذج Mongoose أو TypeORM) مباشرة داخل طبقة الـ Use Cases."]'::jsonb or l.follow_up_questions is distinct from '["كيف تسهل المعمارية النظيفة استبدال إطار عمل السيرفر دون لمس منطق الأعمال؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Architectural Design Patterns","url":"https://nodejs.org/docs/latest/api/modules.html"}]'::jsonb)) then raise exception 'Question narch-001 ar content changed; create a new revision before seeding'; end if; end $$;
