insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تساعد طوابير الرسائل (Message Queues) مثل BullMQ في معالجة المهام الخلفية المعقدة؟', 'تفصل استقبال الطلب عن معالجته الثقيلة، حيث يُسجل الطلب في طابور سريع بـ Redis ويرد على المستخدم فوراً، وتقوم خوادم عمال (Workers) بمعالجة المهمة في الخلفية.', 'في عمليات مثل إرسال الإيميلات، أو معالجة الصور، أو توليد تقارير PDF، لا يجب حظر المستخدم لعدة ثوانٍ. توفر مكتبة BullMQ المبنية فوق Redis طابور مهام موثوقاً يدعم إعادة المحاولة التلقائية عند الفشل (Retries مع Exponential Backoff)، وتأجيل المهام (Delayed Jobs)، والتحكم في معدل المعالجة، والعمل عبر خوادم متعددة.', 'import { Queue, Worker } from "bullmq";
const emailQueue = new Queue("emails", { connection: redisConfig });
await emailQueue.add("welcome", { to: "user@test.com" });

const worker = new Worker("emails", async job => {
  await sendEmail(job.data);
}, { connection: redisConfig });', '["معالجة مهام طويلة ومعقدة مباشرة داخل مسار الـ HTTP Request بدلاً من ترحيلها لطابور مهام."]'::jsonb, '["كيف تتعامل مع مشكلة الـ Dead Letter Queue (DLQ) للمهام التي تفشل باستمرار؟"]'::jsonb, '[{"title":"Node.js docs — Events and Streams in Background Processing","url":"https://nodejs.org/docs/latest/api/events.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تساعد طوابير الرسائل (Message Queues) مثل BullMQ في معالجة المهام الخلفية المعقدة؟' or l.short_answer is distinct from 'تفصل استقبال الطلب عن معالجته الثقيلة، حيث يُسجل الطلب في طابور سريع بـ Redis ويرد على المستخدم فوراً، وتقوم خوادم عمال (Workers) بمعالجة المهمة في الخلفية.' or l.explanation is distinct from 'في عمليات مثل إرسال الإيميلات، أو معالجة الصور، أو توليد تقارير PDF، لا يجب حظر المستخدم لعدة ثوانٍ. توفر مكتبة BullMQ المبنية فوق Redis طابور مهام موثوقاً يدعم إعادة المحاولة التلقائية عند الفشل (Retries مع Exponential Backoff)، وتأجيل المهام (Delayed Jobs)، والتحكم في معدل المعالجة، والعمل عبر خوادم متعددة.' or l.code_example is distinct from 'import { Queue, Worker } from "bullmq";
const emailQueue = new Queue("emails", { connection: redisConfig });
await emailQueue.add("welcome", { to: "user@test.com" });

const worker = new Worker("emails", async job => {
  await sendEmail(job.data);
}, { connection: redisConfig });' or l.common_mistakes is distinct from '["معالجة مهام طويلة ومعقدة مباشرة داخل مسار الـ HTTP Request بدلاً من ترحيلها لطابور مهام."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتعامل مع مشكلة الـ Dead Letter Queue (DLQ) للمهام التي تفشل باستمرار؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Events and Streams in Background Processing","url":"https://nodejs.org/docs/latest/api/events.html"}]'::jsonb)) then raise exception 'Question narch-002 ar content changed; create a new revision before seeding'; end if; end $$;
