insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل مجموعات المستهلكين (Consumer Groups) في Apache Kafka مع خوادم Node.js؟', 'تسمح بتوزيع قراءة الرسائل من أقسام الـ Topic (Partitions) بين عدة نسخ متوازية من تطبيق Node.js لضمان المعالجة الأفقية السريعة مع الحفاظ على الترتيب.', 'في Kafka، يتم تقسيم الـ Topic إلى Partitions متعددة. عندما تنضم عدة عمليات Node.js إلى نفس الـ Consumer Group، يقوم Kafka بتعيين أقسام محددة لكل نسخة بالتساوي. تضمن هذه المعمارية قراءة الرسائل بالترتيب الدقيق داخل كل Partition، مع إمكانية زيادة حجم المعالجة ببساطة عبر زيادة عدد الـ Workers ليطابق عدد الأقسام.', '// استخدام KafkaJS لإعداد Consumer Group موزع', '["إضافة عدد مستهلكين في نفس المجموعة يفوق عدد الـ Partitions، مما يترك الخوادم الإضافية في حالة خمول."]'::jsonb, '["ما هو دور الـ Consumer Rebalancing وكيف يؤثر على زمن معالجة الأحداث؟"]'::jsonb, '[{"title":"Node.js docs — Stream consumers and networking","url":"https://nodejs.org/docs/latest/api/stream.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل مجموعات المستهلكين (Consumer Groups) في Apache Kafka مع خوادم Node.js؟' or l.short_answer is distinct from 'تسمح بتوزيع قراءة الرسائل من أقسام الـ Topic (Partitions) بين عدة نسخ متوازية من تطبيق Node.js لضمان المعالجة الأفقية السريعة مع الحفاظ على الترتيب.' or l.explanation is distinct from 'في Kafka، يتم تقسيم الـ Topic إلى Partitions متعددة. عندما تنضم عدة عمليات Node.js إلى نفس الـ Consumer Group، يقوم Kafka بتعيين أقسام محددة لكل نسخة بالتساوي. تضمن هذه المعمارية قراءة الرسائل بالترتيب الدقيق داخل كل Partition، مع إمكانية زيادة حجم المعالجة ببساطة عبر زيادة عدد الـ Workers ليطابق عدد الأقسام.' or l.code_example is distinct from '// استخدام KafkaJS لإعداد Consumer Group موزع' or l.common_mistakes is distinct from '["إضافة عدد مستهلكين في نفس المجموعة يفوق عدد الـ Partitions، مما يترك الخوادم الإضافية في حالة خمول."]'::jsonb or l.follow_up_questions is distinct from '["ما هو دور الـ Consumer Rebalancing وكيف يؤثر على زمن معالجة الأحداث؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Stream consumers and networking","url":"https://nodejs.org/docs/latest/api/stream.html"}]'::jsonb)) then raise exception 'Question narch-003 ar content changed; create a new revision before seeding'; end if; end $$;
