insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين استخدام gRPC و REST في التواصل الداخلي بين خدمات Node.js الدقيقة (Microservices).', 'يعتمد gRPC على بروتوكول HTTP/2 وتسلسل Protocol Buffers الثنائي السريع والمحدد بأنواع صارمة، مما يجعله أسرع وأقل استهلاكاً للشبكة من REST/JSON.', 'في الاتصالات الداخلية الكثيفة بين مئات الخدمات الخلفية، يسبب تسلسل ونقل نصوص JSON عبر HTTP/1.1 عبئاً هائلاً. يوفر gRPC تواصلاً ثنائياً فائق السرعة، مع عقود برمجية صارمة وموحدة عبر ملفات .proto، ودعم التدفق ثنائي الاتجاه (Streaming)، وتوليد كود العميل والخادم تلقائياً لمختلف لغات البرمجة.', '// استدعاء خدمة gRPC عبر عميل مولد من ملف proto', '["استخدام gRPC للواجهات العامة الموجهة للمتصفحات العادية التي تفتقر للدعم الأصيل لـ HTTP/2 gRPC."]'::jsonb, '["كيف يدعم gRPC ميزة الـ Multiplexing الموروثة من بروتوكول HTTP/2؟"]'::jsonb, '[{"title":"Node.js docs — HTTP/2 Module","url":"https://nodejs.org/docs/latest/api/http2.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين استخدام gRPC و REST في التواصل الداخلي بين خدمات Node.js الدقيقة (Microservices).' or l.short_answer is distinct from 'يعتمد gRPC على بروتوكول HTTP/2 وتسلسل Protocol Buffers الثنائي السريع والمحدد بأنواع صارمة، مما يجعله أسرع وأقل استهلاكاً للشبكة من REST/JSON.' or l.explanation is distinct from 'في الاتصالات الداخلية الكثيفة بين مئات الخدمات الخلفية، يسبب تسلسل ونقل نصوص JSON عبر HTTP/1.1 عبئاً هائلاً. يوفر gRPC تواصلاً ثنائياً فائق السرعة، مع عقود برمجية صارمة وموحدة عبر ملفات .proto، ودعم التدفق ثنائي الاتجاه (Streaming)، وتوليد كود العميل والخادم تلقائياً لمختلف لغات البرمجة.' or l.code_example is distinct from '// استدعاء خدمة gRPC عبر عميل مولد من ملف proto' or l.common_mistakes is distinct from '["استخدام gRPC للواجهات العامة الموجهة للمتصفحات العادية التي تفتقر للدعم الأصيل لـ HTTP/2 gRPC."]'::jsonb or l.follow_up_questions is distinct from '["كيف يدعم gRPC ميزة الـ Multiplexing الموروثة من بروتوكول HTTP/2؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — HTTP/2 Module","url":"https://nodejs.org/docs/latest/api/http2.html"}]'::jsonb)) then raise exception 'Question narch-004 ar content changed; create a new revision before seeding'; end if; end $$;
