insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو نمط قاطع الدائرة (Circuit Breaker) وكيف يمنع الانهيارات المتتالية (Cascading Failures)؟', 'يراقب فشل الاتصال بالخدمات الخارجية؛ فإذا تجاوزت الأخطاء حداً معيناً يفتح الدائرة ويفشل الطلبات فوراً دون إرسالها، مانعاً استنزاف موارد السيرفر.', 'إذا توقفت خدمة خارجية (كخدمة مدفوعات)، فإن محاولة مئات الطلبات الاتصال بها وانتظار الـ timeouts سيؤدي لاستنزاف كامل اتصالات وذاكرة تطبيقك وانهياره بالكامل. يمر نمط قاطع الدائرة (باستخدام مكتبات مثل opossum) بثلاث حالات: Closed (طبيعي)، Open (يرد فوراً بفشل أو Fallback دون اتصال)، وHalf-Open (يختبر عودة الخدمة بطلبات تجريبية قليلة).', 'import CircuitBreaker from "opossum";
const breaker = new CircuitBreaker(callExternalApi, { timeout: 3000, errorThresholdPercentage: 50 });
breaker.fallback(() => ({ status: "cached_fallback" }));
const result = await breaker.fire();', '["عدم توفير مسار استجابة بديل (Fallback) واضح عند فتح الدائرة."]'::jsonb, '["كيف يحدد قاطع الدائرة الانتقال من حالة Open إلى Half-Open؟"]'::jsonb, '[{"title":"Node.js docs — Error boundaries and resilience","url":"https://nodejs.org/docs/latest/api/errors.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو نمط قاطع الدائرة (Circuit Breaker) وكيف يمنع الانهيارات المتتالية (Cascading Failures)؟' or l.short_answer is distinct from 'يراقب فشل الاتصال بالخدمات الخارجية؛ فإذا تجاوزت الأخطاء حداً معيناً يفتح الدائرة ويفشل الطلبات فوراً دون إرسالها، مانعاً استنزاف موارد السيرفر.' or l.explanation is distinct from 'إذا توقفت خدمة خارجية (كخدمة مدفوعات)، فإن محاولة مئات الطلبات الاتصال بها وانتظار الـ timeouts سيؤدي لاستنزاف كامل اتصالات وذاكرة تطبيقك وانهياره بالكامل. يمر نمط قاطع الدائرة (باستخدام مكتبات مثل opossum) بثلاث حالات: Closed (طبيعي)، Open (يرد فوراً بفشل أو Fallback دون اتصال)، وHalf-Open (يختبر عودة الخدمة بطلبات تجريبية قليلة).' or l.code_example is distinct from 'import CircuitBreaker from "opossum";
const breaker = new CircuitBreaker(callExternalApi, { timeout: 3000, errorThresholdPercentage: 50 });
breaker.fallback(() => ({ status: "cached_fallback" }));
const result = await breaker.fire();' or l.common_mistakes is distinct from '["عدم توفير مسار استجابة بديل (Fallback) واضح عند فتح الدائرة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يحدد قاطع الدائرة الانتقال من حالة Open إلى Half-Open؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Error boundaries and resilience","url":"https://nodejs.org/docs/latest/api/errors.html"}]'::jsonb)) then raise exception 'Question narch-005 ar content changed; create a new revision before seeding'; end if; end $$;
