insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق التتبع الموزع (Distributed Tracing) باستخدام معيار OpenTelemetry في Node.js؟', 'يقوم بتوليد Trace ID موحد وتمريره عبر ترويسات الطلبات (W3C Trace Context)، لربط مسار الطلب وسجلاته عبر كل الخوادم وقواعد البيانات المشاركة.', 'عندما يمر طلب مستخدم بخمس خدمات دقيقة مختلفة وقاعدة بيانات، يصبح من المستحيل تشخيص سبب البطء بالسجلات التقليدية المنفصلة. توفر أدوات OpenTelemetry لـ Node.js تتبعاً تلقائياً لمكتبات الـ HTTP وقواعد البيانات، حيث تقيس زمن تنفيذ كل عملية فرعية (Span) وتربطها في مخطط زمني موحد يُعرض على أدوات مثل Jaeger أو Datadog.', '// تهيئة OpenTelemetry SDK قبل بدء التطبيق', '["فقدان تمرير ترويسة traceparent عند استدعاء الخدمات الخارجية عبر عميل الـ HTTP."]'::jsonb, '["كيف يرتبط OpenTelemetry مع فئة AsyncLocalStorage لنقل سياق الـ Tracing داخل الخادم الواحد؟"]'::jsonb, '[{"title":"Node.js docs — Async Context Tracing","url":"https://nodejs.org/docs/latest/api/async_context.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق التتبع الموزع (Distributed Tracing) باستخدام معيار OpenTelemetry في Node.js؟' or l.short_answer is distinct from 'يقوم بتوليد Trace ID موحد وتمريره عبر ترويسات الطلبات (W3C Trace Context)، لربط مسار الطلب وسجلاته عبر كل الخوادم وقواعد البيانات المشاركة.' or l.explanation is distinct from 'عندما يمر طلب مستخدم بخمس خدمات دقيقة مختلفة وقاعدة بيانات، يصبح من المستحيل تشخيص سبب البطء بالسجلات التقليدية المنفصلة. توفر أدوات OpenTelemetry لـ Node.js تتبعاً تلقائياً لمكتبات الـ HTTP وقواعد البيانات، حيث تقيس زمن تنفيذ كل عملية فرعية (Span) وتربطها في مخطط زمني موحد يُعرض على أدوات مثل Jaeger أو Datadog.' or l.code_example is distinct from '// تهيئة OpenTelemetry SDK قبل بدء التطبيق' or l.common_mistakes is distinct from '["فقدان تمرير ترويسة traceparent عند استدعاء الخدمات الخارجية عبر عميل الـ HTTP."]'::jsonb or l.follow_up_questions is distinct from '["كيف يرتبط OpenTelemetry مع فئة AsyncLocalStorage لنقل سياق الـ Tracing داخل الخادم الواحد؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Async Context Tracing","url":"https://nodejs.org/docs/latest/api/async_context.html"}]'::jsonb)) then raise exception 'Question narch-006 ar content changed; create a new revision before seeding'; end if; end $$;
