insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين Liveness Probe و Readiness Probe في Kubernetes لتطبيقات Node.js؟', 'تتحقق الـ Liveness من أن العملية ما زالت حية وغير متجمدة (وإلا أعيد تشغيلها)، بينما تتحقق الـ Readiness من جاهزية التطبيق لاستقبال الطلبات (مثل اكتمال الاتصال بقاعدة البيانات).', 'إذا فشل فحص الـ Liveness (مثلاً حدث Deadlock جمد الـ Event Loop)، يقوم Kubernetes بإعادة تشغيل الحاوية فوراً. أما إذا فشل فحص الـ Readiness (مثلاً أثناء تحميل بيانات أولية ضخمة أو تعطل قاعدة البيانات مؤقتاً)، يقوم Kubernetes بعزل الحاوية والتوقف عن توجيه الزيارات إليها دون قتل العملية، حتى تعود للجاهزية وتستأنف الخدمة.', '// مسار الجاهزية يفحص اتصال قاعدة البيانات
app.get("/health/ready", async (req, res) => {
  const isDbOk = await db.ping();
  if (isDbOk) res.status(200).send("READY");
  else res.status(503).send("DB_DOWN");
});', '["ربط فحص الـ Liveness بقاعدة بيانات خارجية؛ فإذا سقطت قاعدة البيانات، سيعيد Kubernetes قتل وإعادة تشغيل كل خوادم Node.js عبثاً."]'::jsonb, '["كيف تصمم مسار Startup Probe لحماية تطبيقات Node.js التي تستغرق وقتاً طويلاً في التحميل الأولي؟"]'::jsonb, '[{"title":"Node.js docs — Process health and signals","url":"https://nodejs.org/docs/latest/api/process.html"}]'::jsonb from public.question_revisions r where r.question_id = 'narch-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narch-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الجوهري بين Liveness Probe و Readiness Probe في Kubernetes لتطبيقات Node.js؟' or l.short_answer is distinct from 'تتحقق الـ Liveness من أن العملية ما زالت حية وغير متجمدة (وإلا أعيد تشغيلها)، بينما تتحقق الـ Readiness من جاهزية التطبيق لاستقبال الطلبات (مثل اكتمال الاتصال بقاعدة البيانات).' or l.explanation is distinct from 'إذا فشل فحص الـ Liveness (مثلاً حدث Deadlock جمد الـ Event Loop)، يقوم Kubernetes بإعادة تشغيل الحاوية فوراً. أما إذا فشل فحص الـ Readiness (مثلاً أثناء تحميل بيانات أولية ضخمة أو تعطل قاعدة البيانات مؤقتاً)، يقوم Kubernetes بعزل الحاوية والتوقف عن توجيه الزيارات إليها دون قتل العملية، حتى تعود للجاهزية وتستأنف الخدمة.' or l.code_example is distinct from '// مسار الجاهزية يفحص اتصال قاعدة البيانات
app.get("/health/ready", async (req, res) => {
  const isDbOk = await db.ping();
  if (isDbOk) res.status(200).send("READY");
  else res.status(503).send("DB_DOWN");
});' or l.common_mistakes is distinct from '["ربط فحص الـ Liveness بقاعدة بيانات خارجية؛ فإذا سقطت قاعدة البيانات، سيعيد Kubernetes قتل وإعادة تشغيل كل خوادم Node.js عبثاً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم مسار Startup Probe لحماية تطبيقات Node.js التي تستغرق وقتاً طويلاً في التحميل الأولي؟"]'::jsonb or l.sources is distinct from '[{"title":"Node.js docs — Process health and signals","url":"https://nodejs.org/docs/latest/api/process.html"}]'::jsonb)) then raise exception 'Question narch-008 ar content changed; create a new revision before seeding'; end if; end $$;
