insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل OPcache وما دور مجمع JIT (Just-In-Time) الذي أضيف في PHP 8؟', 'يقوم OPcache بتخزين الـ Opcode المجمع مسبقاً في الذاكرة لتفادي إعادة قراءة الملفات، بينما يقوم JIT بترجمة مقاطع الـ Opcode المتكررة مباشرة إلى تعليمات الآلة الأصلية (Machine Code).', 'في دورة حياة PHP التقليدية، يتم قراءة الكود وتحليله (Tokenization & Parsing) وتجميعه إلى Opcodes مع كل طلب. يلغي OPcache هذه الخطوة بتخزين الـ Opcodes في الذاكرة المشتركة. أما JIT (المبني بنظام DynASM) فيأخذ المقاطع الأكثر استخداماً (Hot Spots) ويترجمها إلى تعليمات المعالج المباشرة، مما يفيد المهام الحسابية والرياضية الثقيلة أكثر من تطبيقات الويب المقيدة بالـ I/O.', '// إعدادات opcache.ini
opcache.enable=1
opcache.jit=tracing
opcache.jit_buffer_size=100M', '["توقع أن يضاعف JIT سرعة تطبيقات الويب العادية (مثل Laravel)، متناسين أن عنق الزجاجة فيها هو استعلامات قواعد البيانات والشبكة."]'::jsonb, '["ما الفرق بين tracing JIT و function JIT في إعدادات PHP؟"]'::jsonb, '[{"title":"PHP docs — OPcache and JIT","url":"https://www.php.net/manual/en/book.opcache.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pcore-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcore-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل OPcache وما دور مجمع JIT (Just-In-Time) الذي أضيف في PHP 8؟' or l.short_answer is distinct from 'يقوم OPcache بتخزين الـ Opcode المجمع مسبقاً في الذاكرة لتفادي إعادة قراءة الملفات، بينما يقوم JIT بترجمة مقاطع الـ Opcode المتكررة مباشرة إلى تعليمات الآلة الأصلية (Machine Code).' or l.explanation is distinct from 'في دورة حياة PHP التقليدية، يتم قراءة الكود وتحليله (Tokenization & Parsing) وتجميعه إلى Opcodes مع كل طلب. يلغي OPcache هذه الخطوة بتخزين الـ Opcodes في الذاكرة المشتركة. أما JIT (المبني بنظام DynASM) فيأخذ المقاطع الأكثر استخداماً (Hot Spots) ويترجمها إلى تعليمات المعالج المباشرة، مما يفيد المهام الحسابية والرياضية الثقيلة أكثر من تطبيقات الويب المقيدة بالـ I/O.' or l.code_example is distinct from '// إعدادات opcache.ini
opcache.enable=1
opcache.jit=tracing
opcache.jit_buffer_size=100M' or l.common_mistakes is distinct from '["توقع أن يضاعف JIT سرعة تطبيقات الويب العادية (مثل Laravel)، متناسين أن عنق الزجاجة فيها هو استعلامات قواعد البيانات والشبكة."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين tracing JIT و function JIT في إعدادات PHP؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — OPcache and JIT","url":"https://www.php.net/manual/en/book.opcache.php"}]'::jsonb)) then raise exception 'Question pcore-003 ar content changed; create a new revision before seeding'; end if; end $$;
