insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير PHP الذاكرة باستخدام عد المراجع (Reference Counting) ونظام جمع الدورات (Cycles Collection)؟', 'تخزن المتغيرات في كائنات zval تحتوي على refcount؛ وعندما يصل العداد لصفر تُحرر الذاكرة، ويدير Cycle Collector استرجاع الكائنات ذات المراجع الدائرية المغلقة.', 'كل متغير في محرك Zend يمثله هيكل zval. عند إسناد متغير لآخر، لا يتم نسخ القيمة في الذاكرة فوراً بل يُطبق نمط Copy-On-Write (COW) ويزداد الـ refcount. إذا كان كائنان يشيران لبعضهما البعض وحُذفت المتغيرات الأصلية (Circular Reference)، يظل refcount=1 ولا يستطيع النظام العادي تحريرهما، وهنا يتدخل Cycle Garbage Collector لفحص جذور المراجع وتصفية الحلقات المغلقة.', '// Copy-on-write
$a = range(1, 1000000);
$b = $a; // لا يتم استهلاك ذاكرة جديدة هنا
$b[0] = 99; // يتم نسخ المصفوفة فعلياً في الذاكرة الآن فقط', '["الاعتقاد بأن إسناد المتغيرات الكبيرة في PHP يضاعف استهلاك الذاكرة دائماً، وتجاهل آلية Copy-On-Write."]'::jsonb, '["كيف تستدعي دالة gc_collect_cycles() يدوياً أثناء تشغيل سكريبتات المعالجة الطويلة للـ CLI؟"]'::jsonb, '[{"title":"PHP docs — Reference Counting Basics","url":"https://www.php.net/manual/en/features.gc.refcounting-basics.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pcore-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcore-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير PHP الذاكرة باستخدام عد المراجع (Reference Counting) ونظام جمع الدورات (Cycles Collection)؟' or l.short_answer is distinct from 'تخزن المتغيرات في كائنات zval تحتوي على refcount؛ وعندما يصل العداد لصفر تُحرر الذاكرة، ويدير Cycle Collector استرجاع الكائنات ذات المراجع الدائرية المغلقة.' or l.explanation is distinct from 'كل متغير في محرك Zend يمثله هيكل zval. عند إسناد متغير لآخر، لا يتم نسخ القيمة في الذاكرة فوراً بل يُطبق نمط Copy-On-Write (COW) ويزداد الـ refcount. إذا كان كائنان يشيران لبعضهما البعض وحُذفت المتغيرات الأصلية (Circular Reference)، يظل refcount=1 ولا يستطيع النظام العادي تحريرهما، وهنا يتدخل Cycle Garbage Collector لفحص جذور المراجع وتصفية الحلقات المغلقة.' or l.code_example is distinct from '// Copy-on-write
$a = range(1, 1000000);
$b = $a; // لا يتم استهلاك ذاكرة جديدة هنا
$b[0] = 99; // يتم نسخ المصفوفة فعلياً في الذاكرة الآن فقط' or l.common_mistakes is distinct from '["الاعتقاد بأن إسناد المتغيرات الكبيرة في PHP يضاعف استهلاك الذاكرة دائماً، وتجاهل آلية Copy-On-Write."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستدعي دالة gc_collect_cycles() يدوياً أثناء تشغيل سكريبتات المعالجة الطويلة للـ CLI؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — Reference Counting Basics","url":"https://www.php.net/manual/en/features.gc.refcounting-basics.php"}]'::jsonb)) then raise exception 'Question pcore-004 ar content changed; create a new revision before seeding'; end if; end $$;
