insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطور التسلسل الهرمي للأخطاء والاستثناءات تحت واجهة Throwable في PHP الحديثة؟', 'ترث فئات Exception و Error من الواجهة العامة Throwable، مما يتيح التقاط أخطاء المحرك الجسيمة (Fatal Errors) بكتلة try/catch.', 'قبل PHP 7، كانت الأخطاء الفادحة (Fatal Errors) مثل استدعاء دالة غير موجودة أو انتهاء الذاكرة توقف السكريبت فوراً دون إمكانية التقاطها برمجياً. في الأنظمة الحديثة، تحولت معظم الأخطاء إلى فئات ترث من Error (مثل TypeError وParseError). بالتقاط Throwable، تستطيع حماية التطبيق من الانهيار وتسجيل الخطأ وإعادة استجابة منسقة للمستخدم.', 'try {
    nonExistentFunction();
} catch (Throwable $e) {
    // يلتقط الاستثناءات والأخطاء الفادحة معاً
    error_log($e->getMessage());
}', '["كتابة فئات مخصصة تنفذ واجهة Throwable مباشرة؛ المحرك يمنع ذلك ويشترط الوراثة من Exception أو Error."]'::jsonb, '["ما الفرق بين ParseError و CompileError في تسلسل الوراثة؟"]'::jsonb, '[{"title":"PHP docs — The Throwable interface","url":"https://www.php.net/manual/en/class.throwable.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pcore-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcore-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطور التسلسل الهرمي للأخطاء والاستثناءات تحت واجهة Throwable في PHP الحديثة؟' or l.short_answer is distinct from 'ترث فئات Exception و Error من الواجهة العامة Throwable، مما يتيح التقاط أخطاء المحرك الجسيمة (Fatal Errors) بكتلة try/catch.' or l.explanation is distinct from 'قبل PHP 7، كانت الأخطاء الفادحة (Fatal Errors) مثل استدعاء دالة غير موجودة أو انتهاء الذاكرة توقف السكريبت فوراً دون إمكانية التقاطها برمجياً. في الأنظمة الحديثة، تحولت معظم الأخطاء إلى فئات ترث من Error (مثل TypeError وParseError). بالتقاط Throwable، تستطيع حماية التطبيق من الانهيار وتسجيل الخطأ وإعادة استجابة منسقة للمستخدم.' or l.code_example is distinct from 'try {
    nonExistentFunction();
} catch (Throwable $e) {
    // يلتقط الاستثناءات والأخطاء الفادحة معاً
    error_log($e->getMessage());
}' or l.common_mistakes is distinct from '["كتابة فئات مخصصة تنفذ واجهة Throwable مباشرة؛ المحرك يمنع ذلك ويشترط الوراثة من Exception أو Error."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين ParseError و CompileError في تسلسل الوراثة؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — The Throwable interface","url":"https://www.php.net/manual/en/class.throwable.php"}]'::jsonb)) then raise exception 'Question pcore-007 ar content changed; create a new revision before seeding'; end if; end $$;
