insert into public.interview_questions (id, slug, track_id, difficulty) values ('pcore-008', 'php-sessions-and-session-locking', 'php', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('pcore-008', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل الجلسات (Sessions) في PHP وما هي مشكلة قفل الجلسة (Session Locking) وكيف تحلها؟', 'تقفل PHP ملف الجلسة للمستخدم حصرياً طوال فترة تنفيذ الطلب لمنع تضارب البيانات؛ وتحل المشكلة باستدعاء session_write_close() فور الانتهاء من قراءة وتعديل الجلسة.', 'عند استدعاء session_start()، تحجز PHP قفلاً حصرياً (Exclusive Lock) على ملف الجلسة الخاص بذلك المستخدم. إذا فتح المستخدم عدة تبويبات أو أرسل عدة طلبات AJAX متزامنة، ستعلق كل الطلبات اللاحقة في طابور انتظار حتى ينتهي الطلب الأول من التنفيذ تماماً. استدعاء session_write_close() يحرر القفل فوراً ويسمح للطلبات المتزامنة بالعمل بالتوازي.', 'session_start();
$userId = $_SESSION[''user_id''];
// تحرير القفل فوراً حتى لا تعطل الطلبات المتزامنة الأخرى
session_write_close();
// تنفيذ عمليات الـ I/O الطويلة بأمان', '["ترك الجلسة مقفلة أثناء تنفيذ عمليات خارجية طويلة مثل استدعاءات الـ APIs الخارجية."]'::jsonb, '["كيف يؤثر استخدام Redis كمخزن للجلسات على سلوك الـ Session Locking؟"]'::jsonb, '[{"title":"PHP docs — session_write_close","url":"https://www.php.net/manual/en/function.session-write-close.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pcore-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
