insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين الدوال المجهولة (Closures) ودوال الأسهم (Arrow Functions fn()) في PHP؟', 'الـ Closures العادية تتطلب استخدام كلمة use لتمرير المتغيرات الخارجية، بينما الـ Arrow Functions تلتقط المتغيرات من النطاق الخارجي ضمنياً عبر القيمة (By-Value).', 'أضيفت Arrow Functions في PHP 7.4 لصياغة الدوال السريعة بسطر واحد fn($x) => $x * $multiplier. تتميز بالتقاطها التلقائي للمتغيرات في النطاق المحيط دون الحاجة لكتابة use ($multiplier). في المقابل، تتيح الـ Closures الكلاسيكية تعديل المتغيرات الخارجية عند تمريرها بالمرجع use (&$count) وتدعم كتل كود متعددة الأسطر.', '$factor = 2;
// Arrow function: التقاط تلقائي
$nums = array_map(fn($n) => $n * $factor, [1, 2, 3]);

// Traditional closure
$double = function($n) use ($factor) {
    return $n * $factor;
};', '["محاولة كتابة عدة أسطر برمجية داخل fn()؛ دوال الأسهم في PHP تدعم حصراً تعبيراً واحداً يُعاد تلقائياً."]'::jsonb, '["هل يمكن للدوال السهمية fn() تعديل قيمة المتغير الخارجي الملتقط؟"]'::jsonb, '[{"title":"PHP docs — Arrow Functions","url":"https://www.php.net/manual/en/functions.arrow.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pcore-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcore-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين الدوال المجهولة (Closures) ودوال الأسهم (Arrow Functions fn()) في PHP؟' or l.short_answer is distinct from 'الـ Closures العادية تتطلب استخدام كلمة use لتمرير المتغيرات الخارجية، بينما الـ Arrow Functions تلتقط المتغيرات من النطاق الخارجي ضمنياً عبر القيمة (By-Value).' or l.explanation is distinct from 'أضيفت Arrow Functions في PHP 7.4 لصياغة الدوال السريعة بسطر واحد fn($x) => $x * $multiplier. تتميز بالتقاطها التلقائي للمتغيرات في النطاق المحيط دون الحاجة لكتابة use ($multiplier). في المقابل، تتيح الـ Closures الكلاسيكية تعديل المتغيرات الخارجية عند تمريرها بالمرجع use (&$count) وتدعم كتل كود متعددة الأسطر.' or l.code_example is distinct from '$factor = 2;
// Arrow function: التقاط تلقائي
$nums = array_map(fn($n) => $n * $factor, [1, 2, 3]);

// Traditional closure
$double = function($n) use ($factor) {
    return $n * $factor;
};' or l.common_mistakes is distinct from '["محاولة كتابة عدة أسطر برمجية داخل fn()؛ دوال الأسهم في PHP تدعم حصراً تعبيراً واحداً يُعاد تلقائياً."]'::jsonb or l.follow_up_questions is distinct from '["هل يمكن للدوال السهمية fn() تعديل قيمة المتغير الخارجي الملتقط؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — Arrow Functions","url":"https://www.php.net/manual/en/functions.arrow.php"}]'::jsonb)) then raise exception 'Question pcore-009 ar content changed; create a new revision before seeding'; end if; end $$;
