insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل بنية PHP-FPM وما الفرق بين أوضاع إدارة العمليات: static و dynamic و ondemand؟', 'PHP-FPM هو مدير عمليات FastCGI؛ وضع static يحافظ على عدد ثابت من العمليات لأقصى أداء، بينما dynamic يغير العدد بناءً على الحمل، وondemand ينشئ العمليات فقط عند وصول الطلب لتوفير الرام.', 'يتواصل خادم الويب (Nginx) مع PHP-FPM عبر مقبس شبكة أو UNIX Socket. في الخوادم عالية الزيارات المخصصة لتطبيق واحد، يعد وضع static الأفضل لأنه يلغي تكلفة إنشاء وإغلاق العمليات المستمرة. بينما يفيد dynamic في الخوادم متوسطة الموارد، ويفيد ondemand في الاستضافات المشتركة لتوفير استهلاك الذاكرة للمواقع الخاملة.', '// php-fpm.d/www.conf
pm = dynamic
pm.max_children = 50
pm.start_servers = 10
pm.min_spare_servers = 5
pm.max_spare_servers = 20
pm.max_requests = 1000', '["عدم تحديد pm.max_requests مما يسبب تراكم تسريبات الذاكرة في عمليات PHP-FPM طويلة العمر."]'::jsonb, '["كيف تحسب القيمة المثلى لمعامل pm.max_children بناءً على حجم الرام ومتوسط استهلاك العملية؟"]'::jsonb, '[{"title":"PHP docs — FastCGI Process Manager (FPM)","url":"https://www.php.net/manual/en/install.fpm.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pcore-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcore-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل بنية PHP-FPM وما الفرق بين أوضاع إدارة العمليات: static و dynamic و ondemand؟' or l.short_answer is distinct from 'PHP-FPM هو مدير عمليات FastCGI؛ وضع static يحافظ على عدد ثابت من العمليات لأقصى أداء، بينما dynamic يغير العدد بناءً على الحمل، وondemand ينشئ العمليات فقط عند وصول الطلب لتوفير الرام.' or l.explanation is distinct from 'يتواصل خادم الويب (Nginx) مع PHP-FPM عبر مقبس شبكة أو UNIX Socket. في الخوادم عالية الزيارات المخصصة لتطبيق واحد، يعد وضع static الأفضل لأنه يلغي تكلفة إنشاء وإغلاق العمليات المستمرة. بينما يفيد dynamic في الخوادم متوسطة الموارد، ويفيد ondemand في الاستضافات المشتركة لتوفير استهلاك الذاكرة للمواقع الخاملة.' or l.code_example is distinct from '// php-fpm.d/www.conf
pm = dynamic
pm.max_children = 50
pm.start_servers = 10
pm.min_spare_servers = 5
pm.max_spare_servers = 20
pm.max_requests = 1000' or l.common_mistakes is distinct from '["عدم تحديد pm.max_requests مما يسبب تراكم تسريبات الذاكرة في عمليات PHP-FPM طويلة العمر."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحسب القيمة المثلى لمعامل pm.max_children بناءً على حجم الرام ومتوسط استهلاك العملية؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — FastCGI Process Manager (FPM)","url":"https://www.php.net/manual/en/install.fpm.php"}]'::jsonb)) then raise exception 'Question pcore-010 ar content changed; create a new revision before seeding'; end if; end $$;
