insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحل تعارض أسماء الدوال عند استخدام سمات Traits متعددة في PHP؟', 'تستخدم كلمة insteadof لتحديد الدالة الفائزة من السمة المحددة، وكلمة as لإعطاء اسم بديل (Alias) أو تغيير مستوى الرؤية للدالة الأخرى.', 'الـ Traits هي آلية لإعادة استخدام الكود الأفقي في لغات الوراثة الأحادية. إذا اشتركت سمتان A و B في دالة بنفس الاسم doWork()، سيرمي المحرك Fatal Error عند استخدامها. الحل هو إعلان التفضيل الصريح داخل الفئة عبر insteadof واستخدام as لحفظ الدالة الأخرى باسم بديل.', 'class App {
    use TraitA, TraitB {
        TraitA::doWork insteadof TraitB;
        TraitB::doWork as doWorkFromB;
    }
}', '["استخدام Traits كبديل عشوائي للوراثة وحقن التبعيات مما يخلق كائنات ضخمة غير قابلة للاختبار."]'::jsonb, '["ما هو ترتيب الأسبقية (Precedence) لتنفيذ الدوال بين الفئة الحالية والـ Trait والفئة الأب؟"]'::jsonb, '[{"title":"PHP docs — Traits","url":"https://www.php.net/manual/en/language.oop5.traits.php"}]'::jsonb from public.question_revisions r where r.question_id = 'poop-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
