insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى تختار واجهة برمجة (Interface) ومتى تختار فئة مجردة (Abstract Class) في تصميم كود PHP؟', 'تختار Interface لتعريف عقد سلوكي مجرد وتطبيقه عبر فئات غير مترابطة، وتختار Abstract Class عندما تريد مشاركة كود وتنفيذ حقيقي بين فئات تنتمي لنفس العائلة الهرمية.', 'تتيح PHP تطبيق عدة Interfaces لنفس الفئة (Multiple Interfaces)، مما يدعم مبدأ Interface Segregation. أما الفئات المجردة فتوفر وراثة أحادية (Single Inheritance) وتسمح بتعريف متغيرات حالة (State) ودوال كاملة التنفيذ مع إجبار الفئات المشتقة على تنفيذ الدوال المجردة فقط.', 'interface PaymentGateway {
    public function charge(int $amount): bool;
}

abstract class BaseGateway implements PaymentGateway {
    protected function logTransaction(int $amount): void {
        // كود مشترك
    }
}', '["إنشاء Abstract Class لا يحتوي على أي كود تنفيذي مشترك، وكان الأولى تحويله إلى Interface."]'::jsonb, '["هل يمكن للواجهات في PHP أن ترث من واجهات متعددة أخرى؟"]'::jsonb, '[{"title":"PHP docs — Object Interfaces","url":"https://www.php.net/manual/en/language.oop5.interfaces.php"}]'::jsonb from public.question_revisions r where r.question_id = 'poop-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'poop-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'متى تختار واجهة برمجة (Interface) ومتى تختار فئة مجردة (Abstract Class) في تصميم كود PHP؟' or l.short_answer is distinct from 'تختار Interface لتعريف عقد سلوكي مجرد وتطبيقه عبر فئات غير مترابطة، وتختار Abstract Class عندما تريد مشاركة كود وتنفيذ حقيقي بين فئات تنتمي لنفس العائلة الهرمية.' or l.explanation is distinct from 'تتيح PHP تطبيق عدة Interfaces لنفس الفئة (Multiple Interfaces)، مما يدعم مبدأ Interface Segregation. أما الفئات المجردة فتوفر وراثة أحادية (Single Inheritance) وتسمح بتعريف متغيرات حالة (State) ودوال كاملة التنفيذ مع إجبار الفئات المشتقة على تنفيذ الدوال المجردة فقط.' or l.code_example is distinct from 'interface PaymentGateway {
    public function charge(int $amount): bool;
}

abstract class BaseGateway implements PaymentGateway {
    protected function logTransaction(int $amount): void {
        // كود مشترك
    }
}' or l.common_mistakes is distinct from '["إنشاء Abstract Class لا يحتوي على أي كود تنفيذي مشترك، وكان الأولى تحويله إلى Interface."]'::jsonb or l.follow_up_questions is distinct from '["هل يمكن للواجهات في PHP أن ترث من واجهات متعددة أخرى؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — Object Interfaces","url":"https://www.php.net/manual/en/language.oop5.interfaces.php"}]'::jsonb)) then raise exception 'Question poop-005 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a PHP & Laravel developer know about Php Interfaces Vs Abstract Classes?', 'This question checks the core Php Interfaces Vs Abstract Classes concept and how to use it safely in PHP 8, Laravel, and web services.', 'Explain Php Interfaces Vs Abstract Classes with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'interface PaymentGateway {
