}

abstract class BaseGateway implements PaymentGateway {
    protected function logTransaction(int $amount): void {
        // كود مشترك
    }
}', '["Missing the key trade-off in Php Interfaces Vs Abstract Classes (point 1)."]'::jsonb, '["How would you apply Php Interfaces Vs Abstract Classes in a production PHP/Laravel app (follow-up 1)?"]'::jsonb, '[{"title":"PHP docs — Object Interfaces","url":"https://www.php.net/manual/en/language.oop5.interfaces.php"}]'::jsonb from public.question_revisions r where r.question_id = 'poop-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'poop-005' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a PHP & Laravel developer know about Php Interfaces Vs Abstract Classes?' or l.short_answer is distinct from 'This question checks the core Php Interfaces Vs Abstract Classes concept and how to use it safely in PHP 8, Laravel, and web services.' or l.explanation is distinct from 'Explain Php Interfaces Vs Abstract Classes with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from 'interface PaymentGateway {
    public function charge(int $amount): bool;
}

abstract class BaseGateway implements PaymentGateway {
    protected function logTransaction(int $amount): void {
        // كود مشترك
    }
