insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين كلمة self وكلمة static في استدعاءات الـ Late Static Binding بـ PHP؟', 'تشير self إلى الفئة التي كُتب فيها الكود أثناء زمن الترجمة، بينما تشير static إلى الفئة التي تم استدعاء الدالة منها فعلياً وقت التشغيل.', 'في الوراثة، إذا كانت الفئة الأب تحتوي على دالة static تنشئ نسخة جديدة عبر new self()، وقامت فئة ابن باستدعاء الدالة، ستنشئ self نسخة من الأب دائماً. إدخال مفهوم Late Static Binding عبر new static() يوجه المحرك لحل الفئة بناءً على الفئة المستدعية وقت التشغيل، وهو الأساس المعتمد في نمط Model::create() بـ Laravel.', 'class Model {
    public static function make() {
        return new static(); // ينشئ نسخة من الفئة الفرعية المستدعية
    }
}
class User extends Model {}
User::make(); // ينشئ User وليس Model', '["استخدام self::class في مصانع الفئات الموروثة مما يعيد اسم الفئة الأساسية دائماً."]'::jsonb, '["كيف تعمل دالة get_called_class() بالتوازي مع مفهوم static Late Binding؟"]'::jsonb, '[{"title":"PHP docs — Late Static Bindings","url":"https://www.php.net/manual/en/language.oop5.late-static-bindings.php"}]'::jsonb from public.question_revisions r where r.question_id = 'poop-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'poop-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الجوهري بين كلمة self وكلمة static في استدعاءات الـ Late Static Binding بـ PHP؟' or l.short_answer is distinct from 'تشير self إلى الفئة التي كُتب فيها الكود أثناء زمن الترجمة، بينما تشير static إلى الفئة التي تم استدعاء الدالة منها فعلياً وقت التشغيل.' or l.explanation is distinct from 'في الوراثة، إذا كانت الفئة الأب تحتوي على دالة static تنشئ نسخة جديدة عبر new self()، وقامت فئة ابن باستدعاء الدالة، ستنشئ self نسخة من الأب دائماً. إدخال مفهوم Late Static Binding عبر new static() يوجه المحرك لحل الفئة بناءً على الفئة المستدعية وقت التشغيل، وهو الأساس المعتمد في نمط Model::create() بـ Laravel.' or l.code_example is distinct from 'class Model {
    public static function make() {
        return new static(); // ينشئ نسخة من الفئة الفرعية المستدعية
    }
}
class User extends Model {}
User::make(); // ينشئ User وليس Model' or l.common_mistakes is distinct from '["استخدام self::class في مصانع الفئات الموروثة مما يعيد اسم الفئة الأساسية دائماً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل دالة get_called_class() بالتوازي مع مفهوم static Late Binding؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — Late Static Bindings","url":"https://www.php.net/manual/en/language.oop5.late-static-bindings.php"}]'::jsonb)) then raise exception 'Question poop-006 ar content changed; create a new revision before seeding'; end if; end $$;
