insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تختلف معاملات الكائنات (Objects by Reference) عن المتغيرات العادية في تمرير دوال PHP؟', 'تُمرر الكائنات بمعرف الكائن (Object Identifier)؛ لذا فإن تعديل خصائص الكائن داخل دالة ينعكس على الكائن الأصلي دون الحاجة لعلامة &.', 'في PHP، المتغيرات البدائية تُمرر بالقيمة (Copy-On-Write). أما الكائنات، فإن المتغير يحمل مجرد معرف يشير إلى الكائن الفعلي في ذاكرة الـ Zend Engine. عند تمرير الكائن لدالة، يحصل المعامل على نسخة من المعرف تشير لنفس الكائن في الذاكرة. التمييز الدقيق هو أن استبدال الكائن بالكامل داخل الدالة بـ $obj = new Other() لا يغير الأصل، ولكن $obj->prop = 5 يغير الأصل فوراً.', 'function modify(stdClass $o) {
    $o->name = "Updated"; // ينعكس على الكائن الأصلي خارج الدالة
}
$user = (object)[''name'' => ''Original''];
modify($user);
echo $user->name; // Updated', '["إضافة علامة & قبل معاملات الكائنات دون حاجة ظناً أنها ضرورية لتعديل خصائص الكائن."]'::jsonb, '["متى تكون علامة & ضرورية فعلاً مع الكائنات (مثلاً لإعادة توجيه المتغير نفسه لكائن آخر)؟"]'::jsonb, '[{"title":"PHP docs — Objects and references","url":"https://www.php.net/manual/en/language.oop5.references.php"}]'::jsonb from public.question_revisions r where r.question_id = 'poop-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'poop-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تختلف معاملات الكائنات (Objects by Reference) عن المتغيرات العادية في تمرير دوال PHP؟' or l.short_answer is distinct from 'تُمرر الكائنات بمعرف الكائن (Object Identifier)؛ لذا فإن تعديل خصائص الكائن داخل دالة ينعكس على الكائن الأصلي دون الحاجة لعلامة &.' or l.explanation is distinct from 'في PHP، المتغيرات البدائية تُمرر بالقيمة (Copy-On-Write). أما الكائنات، فإن المتغير يحمل مجرد معرف يشير إلى الكائن الفعلي في ذاكرة الـ Zend Engine. عند تمرير الكائن لدالة، يحصل المعامل على نسخة من المعرف تشير لنفس الكائن في الذاكرة. التمييز الدقيق هو أن استبدال الكائن بالكامل داخل الدالة بـ $obj = new Other() لا يغير الأصل، ولكن $obj->prop = 5 يغير الأصل فوراً.' or l.code_example is distinct from 'function modify(stdClass $o) {
