insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو FrankenPHP وكيف يغير نمط تشغيل تطبيقات PHP التقليدي عبر وضع Worker Mode؟', 'خادم ويب حديث مبني بـ Go (Caddy) ومحرك PHP مدمج؛ ووضع Worker Mode يبقي التطبيق محملاً في الذاكرة بين الطلبات مما يضاعف الأداء عشرات المرات.', 'النمط التاريخي لـ PHP يقوم على ''Share Nothing''؛ حيث تُبنى البيئة وتُفرغ بالكامل مع كل طلب HTTP. يتيح خادم FrankenPHP وضع Worker Mode؛ حيث يتم إقلاع إطار العمل (مثل Laravel) وتحميل الحزم وقواعد البيانات لمرة واحدة فقط في الذاكرة، ثم يخدم الخادم آلاف الطلبات المتتالية دون إعادة بناء البيئة، محققاً أزمنة استجابة بالمللي ثوانٍ الفردية.', '// وضع Worker في FrankenPHP
// frankenphp run --worker public/index.php', '["تخزين حالات المستخدمين في متغيرات static في وضع الـ Worker مما يسبب تسريب بيانات بين طلبات المستخدمين."]'::jsonb, '["كيف تنظف حاويات الـ Dependency Injection وحالات الـ Singletons بين الطلبات في بيئات الـ Long-Running PHP؟"]'::jsonb, '[{"title":"PHP docs — FastCGI and SAPI architecture","url":"https://www.php.net/manual/en/internals2.structure.modstruct.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pmod-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pmod-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو FrankenPHP وكيف يغير نمط تشغيل تطبيقات PHP التقليدي عبر وضع Worker Mode؟' or l.short_answer is distinct from 'خادم ويب حديث مبني بـ Go (Caddy) ومحرك PHP مدمج؛ ووضع Worker Mode يبقي التطبيق محملاً في الذاكرة بين الطلبات مما يضاعف الأداء عشرات المرات.' or l.explanation is distinct from 'النمط التاريخي لـ PHP يقوم على ''Share Nothing''؛ حيث تُبنى البيئة وتُفرغ بالكامل مع كل طلب HTTP. يتيح خادم FrankenPHP وضع Worker Mode؛ حيث يتم إقلاع إطار العمل (مثل Laravel) وتحميل الحزم وقواعد البيانات لمرة واحدة فقط في الذاكرة، ثم يخدم الخادم آلاف الطلبات المتتالية دون إعادة بناء البيئة، محققاً أزمنة استجابة بالمللي ثوانٍ الفردية.' or l.code_example is distinct from '// وضع Worker في FrankenPHP
// frankenphp run --worker public/index.php' or l.common_mistakes is distinct from '["تخزين حالات المستخدمين في متغيرات static في وضع الـ Worker مما يسبب تسريب بيانات بين طلبات المستخدمين."]'::jsonb or l.follow_up_questions is distinct from '["كيف تنظف حاويات الـ Dependency Injection وحالات الـ Singletons بين الطلبات في بيئات الـ Long-Running PHP؟"]'::jsonb or l.sources is distinct from '[{"title":"PHP docs — FastCGI and SAPI architecture","url":"https://www.php.net/manual/en/internals2.structure.modstruct.php"}]'::jsonb)) then raise exception 'Question pmod-009 ar content changed; create a new revision before seeding'; end if; end $$;
