insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي سمة #[\Override] المضافة في PHP 8.3 وما أهميتها في حماية الوراثة؟', 'سمة توضع على الدوال المشتقة لتأكيد أنها تعيد كتابة دالة موجودة بالفعل في الفئة الأب أو الواجهة؛ ويرمي المحرك خطأ وقت الترجمة إذا تغيرت الدالة الأصلية.', 'في المشاريع الكبيرة، إذا قمت بإعادة كتابة دالة في الفئة الابن، ثم قام مطور آخر بتعديل اسم الدالة أو حذفها في الفئة الأب، ستتحول دالتك المشتقة إلى دالة جديدة صامتة ولن يتم استدعاؤها، مما يخلق ثغرات خفية. إضافة السمة #[\Override] تجعل محرك PHP يتحقق بنفسه من وجود الدالة في الأب ويرمي Compile Error فوراً إذا لم يجدها.', 'class ChildClass extends ParentClass {
    #[Override]
    public function execute(): void {
        // يضمن المحرك وجود execute() في ParentClass
    }
}', '["وضع #[\\Override] على دالة جديدة كلياً لا تطبق واجهة ولا تعيد كتابة دالة في فئة أب."]'::jsonb, '["كيف تساهم سمة Override في تسهيل مهام الـ Refactoring وتحديث الحزم الخارجية؟"]'::jsonb, '[{"title":"PHP docs — Override Attribute","url":"https://www.php.net/manual/en/class.override.php"}]'::jsonb from public.question_revisions r where r.question_id = 'pmod-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pmod-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي سمة #[\Override] المضافة في PHP 8.3 وما أهميتها في حماية الوراثة؟' or l.short_answer is distinct from 'سمة توضع على الدوال المشتقة لتأكيد أنها تعيد كتابة دالة موجودة بالفعل في الفئة الأب أو الواجهة؛ ويرمي المحرك خطأ وقت الترجمة إذا تغيرت الدالة الأصلية.' or l.explanation is distinct from 'في المشاريع الكبيرة، إذا قمت بإعادة كتابة دالة في الفئة الابن، ثم قام مطور آخر بتعديل اسم الدالة أو حذفها في الفئة الأب، ستتحول دالتك المشتقة إلى دالة جديدة صامتة ولن يتم استدعاؤها، مما يخلق ثغرات خفية. إضافة السمة #[\Override] تجعل محرك PHP يتحقق بنفسه من وجود الدالة في الأب ويرمي Compile Error فوراً إذا لم يجدها.' or l.code_example is distinct from 'class ChildClass extends ParentClass {
    #[Override]
