insert into public.interview_questions (id, slug, track_id, difficulty) values ('plaracore-001', 'laravel-request-lifecycle-from-index-to-response', 'php', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
