$this->app->bind(Transactor::class, StripeTransactor::class);

// نسخة واحدة للأبد
$this->app->singleton(DatabaseConnection::class, fn() => new DatabaseConnection());

// نسخة واحدة لكل طلب HTTP
$this->app->scoped(CurrentTenant::class, fn() => new CurrentTenant());' or l.common_mistakes is distinct from '["استخدام singleton مع كائنات تحتفظ ببيانات مستخدم محدد في بيئات Laravel Octane."]'::jsonb or l.follow_up_questions is distinct from '["كيف يعمل الـ Contextual Binding عند الحاجة لحقن تطبيقات مختلفة لنفس الواجهة في متحكمين مختلفين؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Service Container","url":"https://laravel.com/docs/master/container"}]'::jsonb)) then raise exception 'Question plaracore-002 ar content changed; create a new revision before seeding'; end if; end $$;
