    public function creating(User $user): void {
        $user->uuid = (string) Str::uuid();
    }
}' or l.common_mistakes is distinct from '["استدعاء دالة $model->save() داخل حدث updating أو saved في الـ Observer دون احتراز مما يسبب حلقة تكرارية لا نهائية (Infinite Loop)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتفادى إطلاق أحداث الـ Observer أثناء تنفيذ عمليات معينة باستخدام Model::withoutEvents()؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Eloquent: Observers","url":"https://laravel.com/docs/master/eloquent#observers"}]'::jsonb)) then raise exception 'Question peloq-007 ar content changed; create a new revision before seeding'; end if; end $$;
