insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل ميزة الحذف اللين (Soft Deletes) في Laravel وما هو أثرها على فهارس قواعد البيانات؟', 'تضيف عمود deleted_at وتستبعد السجلات المحذوفة تلقائياً بـ Global Scope؛ ويجب تضمين deleted_at في الفهارس المركبة للحفاظ على سرعة الاستعلامات.', 'عند استخدام SoftDeletes، لا يتم حذف الصف من القرص بل يُسجل وقت الحذف في deleted_at. يقوم Eloquent تلقائياً بحقن WHERE deleted_at IS NULL في كل استعلام. في الجداول المليونية، إذا كانت فهارسك لا تتضمن عمود deleted_at، ستتدهور كفاءة الفهارس وقد تجبر المحرك على فحص كامل للجدول (Full Table Scan).', '// استخدام الحذف اللين
use SoftDeletes;
// استعادة المحذوفات
User::withTrashed()->where(''id'', 1)->restore();', '["عدم مراعاة قيد التفرد (Unique Constraint) مع الحذف اللين، حيث يفشل إنشاء مستخدم بنفس البريد إذا كان هناك مستخدم سابق محذوف ليناً ما لم يُدمج deleted_at في القيد."]'::jsonb, '["كيف تصمم Unique Index مركب يتعامل مع Soft Deletes في PostgreSQL باستخدام Partial Indexes؟"]'::jsonb, '[{"title":"Laravel docs — Eloquent: Soft Deleting","url":"https://laravel.com/docs/master/eloquent#soft-deleting"}]'::jsonb from public.question_revisions r where r.question_id = 'peloq-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'peloq-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل ميزة الحذف اللين (Soft Deletes) في Laravel وما هو أثرها على فهارس قواعد البيانات؟' or l.short_answer is distinct from 'تضيف عمود deleted_at وتستبعد السجلات المحذوفة تلقائياً بـ Global Scope؛ ويجب تضمين deleted_at في الفهارس المركبة للحفاظ على سرعة الاستعلامات.' or l.explanation is distinct from 'عند استخدام SoftDeletes، لا يتم حذف الصف من القرص بل يُسجل وقت الحذف في deleted_at. يقوم Eloquent تلقائياً بحقن WHERE deleted_at IS NULL في كل استعلام. في الجداول المليونية، إذا كانت فهارسك لا تتضمن عمود deleted_at، ستتدهور كفاءة الفهارس وقد تجبر المحرك على فحص كامل للجدول (Full Table Scan).' or l.code_example is distinct from '// استخدام الحذف اللين
use SoftDeletes;
// استعادة المحذوفات
User::withTrashed()->where(''id'', 1)->restore();' or l.common_mistakes is distinct from '["عدم مراعاة قيد التفرد (Unique Constraint) مع الحذف اللين، حيث يفشل إنشاء مستخدم بنفس البريد إذا كان هناك مستخدم سابق محذوف ليناً ما لم يُدمج deleted_at في القيد."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم Unique Index مركب يتعامل مع Soft Deletes في PostgreSQL باستخدام Partial Indexes؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Eloquent: Soft Deleting","url":"https://laravel.com/docs/master/eloquent#soft-deleting"}]'::jsonb)) then raise exception 'Question peloq-008 ar content changed; create a new revision before seeding'; end if; end $$;
