insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير معاملات قواعد البيانات بـ DB::transaction وكيف تتعامل مع أخطاء الأقفال الميتة (Deadlocks)؟', 'تنفذ العمليات ذرية وتلغيها عند الفشل؛ وتقبل دالة DB::transaction معاملاً يحدد عدد مرات إعادة المحاولة التلقائية عند حدوث Deadlock.', 'في العمليات المالية والحجوزات، تضمن المعاملات عدم وقوع أخطاء جزئية. عند تشغيل معاملات متزامنة، قد تقفل العمليات صفوفاً بترتيب متعارض مما يسبب Deadlock في قاعدة البيانات. توفر دالة DB::transaction(callback, attempts: 5) إعادة محاولة تلقائية ذكية لمعالجة الـ Deadlocks العابرة دون إشعار العميل بالخطأ.', 'DB::transaction(function () use ($from, $to, $amount) {
    $from->decrement(''balance'', $amount);
    $to->increment(''balance'', $amount);
}, 5); // 5 محاولات عند حدوث Deadlock', '["إرسال إيميلات أو طلبات HTTP لجهات خارجية داخل دالة DB::transaction، حيث إنها ستتكرر مع كل محاولة ولا يمكن التراجع عنها عند الـ Rollback."]'::jsonb, '["لماذا يجب تأجيل إطلاق الأحداث والإشعارات حتى اكتمال المعاملة باستخدام DB::afterCommit()؟"]'::jsonb, '[{"title":"Laravel docs — Database Transactions","url":"https://laravel.com/docs/master/database#database-transactions"}]'::jsonb from public.question_revisions r where r.question_id = 'peloq-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'peloq-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير معاملات قواعد البيانات بـ DB::transaction وكيف تتعامل مع أخطاء الأقفال الميتة (Deadlocks)؟' or l.short_answer is distinct from 'تنفذ العمليات ذرية وتلغيها عند الفشل؛ وتقبل دالة DB::transaction معاملاً يحدد عدد مرات إعادة المحاولة التلقائية عند حدوث Deadlock.' or l.explanation is distinct from 'في العمليات المالية والحجوزات، تضمن المعاملات عدم وقوع أخطاء جزئية. عند تشغيل معاملات متزامنة، قد تقفل العمليات صفوفاً بترتيب متعارض مما يسبب Deadlock في قاعدة البيانات. توفر دالة DB::transaction(callback, attempts: 5) إعادة محاولة تلقائية ذكية لمعالجة الـ Deadlocks العابرة دون إشعار العميل بالخطأ.' or l.code_example is distinct from 'DB::transaction(function () use ($from, $to, $amount) {
    $from->decrement(''balance'', $amount);
    $to->increment(''balance'', $amount);
}, 5); // 5 محاولات عند حدوث Deadlock' or l.common_mistakes is distinct from '["إرسال إيميلات أو طلبات HTTP لجهات خارجية داخل دالة DB::transaction، حيث إنها ستتكرر مع كل محاولة ولا يمكن التراجع عنها عند الـ Rollback."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يجب تأجيل إطلاق الأحداث والإشعارات حتى اكتمال المعاملة باستخدام DB::afterCommit()؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Database Transactions","url":"https://laravel.com/docs/master/database#database-transactions"}]'::jsonb)) then raise exception 'Question peloq-009 ar content changed; create a new revision before seeding'; end if; end $$;
