            ''posts'' => PostResource::collection($this->whenLoaded(''posts'')),
        ];
    }
}' or l.common_mistakes is distinct from '["تحميل العلاقات داخل الـ Resource مباشرة مما يعيد خلق مشكلة N+1، بدلاً من استخدام $this->whenLoaded()."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتحكم في المفتاح المغلف للبيانات (Data Wrapping) عبر JsonResource::withoutWrapping()؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Eloquent: API Resources","url":"https://laravel.com/docs/master/eloquent-resources"}]'::jsonb)) then raise exception 'Question papi-001 ar content changed; create a new revision before seeding'; end if; end $$;
