}' or l.common_mistakes is distinct from '["ترك دالة authorize() تعيد false افتراضياً دون تعديل مما يمنع جميع المستخدمين برمز 403."]'::jsonb or l.follow_up_questions is distinct from '["كيف تجهز أو تعدل المدخلات قبل تطبيق قواعد التحقق باستخدام دالة prepareForValidation()؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Form Request Validation","url":"https://laravel.com/docs/master/validation#form-request-validation"}]'::jsonb)) then raise exception 'Question papi-002 ar content changed; create a new revision before seeding'; end if; end $$;
