insert into public.interview_questions (id, slug, track_id, difficulty) values ('papi-003', 'laravel-api-versioning-strategies', 'php', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
