insert into public.interview_questions (id, slug, track_id, difficulty) values ('papi-006', 'laravel-cursor-pagination-vs-length-aware', 'php', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('papi-006', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين LengthAwarePagination و CursorPagination في واجهات برمجة التطبيقات؟', 'الـ LengthAware تعتمد على OFFSET وتستعلم COUNT() الإجمالي (وهي بطيئة في الجداول الكبيرة)، بينما الـ Cursor تعتمد على مؤشر مشفر (WHERE id > X) وسريعة وتناسب الـ Infinite Scroll.', 'في الجداول المليونية، استعلام COUNT(*) لحساب إجمالي الصفحات مكلف للغاية، كما أن التنقل بـ OFFSET 100000 يجعل قاعدة البيانات تفحص 100 ألف صف قبل إرجاع 15 صفاً. الـ Cursor Pagination تلغي استعلام العد، وتستعلم بدقة بناءً على مؤشر مشفر للسجل الأخير، مما يوفر أداءً ثابتاً وفائق السرعة ويمنع تكرار العناصر عند إضافة سجلات جديدة أثناء التمرير.', '// Pagination عادي (بطيء مع البيانات الضخمة)
$posts = Post::paginate(20);

// Cursor pagination (فائق السرعة ولا يتأثر بحجم الجدول)
$posts = Post::orderBy(''id'')->cursorPaginate(20);', '["استخدام Cursor Pagination عندما تتطلب الواجهة أرقام صفحات صريحة للتنقل المباشر (Jump to page 5)."]'::jsonb, '["لماذا تشترط الـ Cursor Pagination ترتيب الاستعلام بعمود فريد وغير قابل للقيم الفارغة؟"]'::jsonb, '[{"title":"Laravel docs — Database: Pagination","url":"https://laravel.com/docs/master/pagination#cursor-pagination"}]'::jsonb from public.question_revisions r where r.question_id = 'papi-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
