insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يحمي محرك Blade من هجمات XSS وما الفرق بين {{ $data }} و {!! $data !!}؟', 'يقوم {{ $data }} بتمرير النص عبر htmlspecialchars() تلقائياً لمنع تشغيل السكريبتات الخبيثة، بينما {!! $data !!} يخرج النص الخام دون أي حماية.', 'هجمات البرمجة عبر المواقع (Cross-Site Scripting) تحدث عندما يتمكن المهاجم من حقن سكريبت جافاسكريبت يتم تنفيذه في متصفح مستخدم آخر. يحمي محرك Blade التطبيق افتراضياً بتحويل الرموز الخاصة مثل < و > إلى كيانات نصية آمنة &lt; و &gt;. لا يجب استخدام علامة التعجب {!! !!} إلا لمحتوى HTML نظيف وموثوق تماماً تم تطهيره بمكتبات مثل HTMLPurifier.', '{{ "<script>alert(1)</script>" }}
{{-- يطبع كنص آمن ولا ينفذ --}}', '["استخدام {!! !!} لعرض مدخلات المستخدمين المباشرة كتعليقات أو أسماء في الصفحة."]'::jsonb, '["كيف تطهر مدخلات محررات النصوص الغنية (WYSIWYG Editors) قبل حفظها أو عرضها بـ {!! !!}؟"]'::jsonb, '[{"title":"Laravel docs — Blade Templates: Displaying Data","url":"https://laravel.com/docs/master/blade#displaying-data"}]'::jsonb from public.question_revisions r where r.question_id = 'psec-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
