insert into public.interview_questions (id, slug, track_id, difficulty) values ('pqueue-002', 'laravel-queue-workers-queue-work-vs-queue-listen', 'php', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
