    public int $tries = 3;
    public array $backoff = [30, 60, 120];

    public function failed(Throwable $exception): void {
        Log::critical("Payment job failed permanently: " . $exception->getMessage());
    }
}' or l.common_mistakes is distinct from '["تحديد عدد محاولات لانهائي لمهمة تفشل بسبب أخطاء منطقية ثابتة (Logic Errors) مما يجمد الـ Queue Workers."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعيد تشغيل كل المهام الفاشلة دفعة واحدة باستخدام php artisan queue:retry all؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Dealing With Failed Jobs","url":"https://laravel.com/docs/master/queues#dealing-with-failed-jobs"}]'::jsonb)) then raise exception 'Question pqueue-003 ar content changed; create a new revision before seeding'; end if; end $$;
