insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين تسلسل المهام (Job Chaining) وحزم المهام (Job Batching) في Laravel؟', 'الـ Chaining ينفذ المهام متسلسلة بالتتابع (إذا فشلت واحدة تتوقف البقية)، بينما الـ Batching ينفذ مجموعة مهام متوازية ويراقب نسبة إنجازها ويوفر callbacks للنجاح والفشل.', 'استخدم Bus::chain([new TaskA, new TaskB]) عندما تعتمد الخطوة التالية حتماً على اكتمال سابقتها. أما Bus::batch([new ImportCsvPart1, new ImportCsvPart2]) فيستخدم لتوزيع عمل ضخم عبر عدة عمال بالتوازي؛ حيث يوفر كائن Batch نسبة الإنجاز المئوية ويدعم دوال then(callback) عند اكتمال الجميع بنجاح، وcatch() عند فشل أي مهمة، وfinally() عند انتهاء الحزمة.', 'Bus::batch([
    new ProcessImage($img1),
    new ProcessImage($img2),
])->then(function (Batch $batch) {
    // اكتملت كل الصور بنجاح
})->catch(function (Batch $batch, Throwable $e) {
    // فشل جزء
})->dispatch();', '["نسيان إضافة سمة Illuminate\\Bus\\Batchable إلى الفئات المراد استخدامها داخل الـ Batches."]'::jsonb, '["كيف تسمح ميزة allowFailures() للـ Batch بمواصلة معالجة باقي المهام حتى لو فشلت إحداها؟"]'::jsonb, '[{"title":"Laravel docs — Job Batching","url":"https://laravel.com/docs/master/queues#job-batching"}]'::jsonb from public.question_revisions r where r.question_id = 'pqueue-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pqueue-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين تسلسل المهام (Job Chaining) وحزم المهام (Job Batching) في Laravel؟' or l.short_answer is distinct from 'الـ Chaining ينفذ المهام متسلسلة بالتتابع (إذا فشلت واحدة تتوقف البقية)، بينما الـ Batching ينفذ مجموعة مهام متوازية ويراقب نسبة إنجازها ويوفر callbacks للنجاح والفشل.' or l.explanation is distinct from 'استخدم Bus::chain([new TaskA, new TaskB]) عندما تعتمد الخطوة التالية حتماً على اكتمال سابقتها. أما Bus::batch([new ImportCsvPart1, new ImportCsvPart2]) فيستخدم لتوزيع عمل ضخم عبر عدة عمال بالتوازي؛ حيث يوفر كائن Batch نسبة الإنجاز المئوية ويدعم دوال then(callback) عند اكتمال الجميع بنجاح، وcatch() عند فشل أي مهمة، وfinally() عند انتهاء الحزمة.' or l.code_example is distinct from 'Bus::batch([
    new ProcessImage($img1),
    new ProcessImage($img2),
])->then(function (Batch $batch) {
    // اكتملت كل الصور بنجاح
})->catch(function (Batch $batch, Throwable $e) {
    // فشل جزء
})->dispatch();' or l.common_mistakes is distinct from '["نسيان إضافة سمة Illuminate\\Bus\\Batchable إلى الفئات المراد استخدامها داخل الـ Batches."]'::jsonb or l.follow_up_questions is distinct from '["كيف تسمح ميزة allowFailures() للـ Batch بمواصلة معالجة باقي المهام حتى لو فشلت إحداها؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Job Batching","url":"https://laravel.com/docs/master/queues#job-batching"}]'::jsonb)) then raise exception 'Question pqueue-004 ar content changed; create a new revision before seeding'; end if; end $$;
