insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المخاطر المعمارية لتخزين نتائج استعلامات قواعد البيانات في الكاش وكيف تدير الـ Invalidation؟', 'المخاطر هي تقديم بيانات قديمة متناقضة (Stale Data)؛ وتدار إما بربط مفاتيح الكاش بمعرف وتوقيت تحديث السجل (Cache-Busting عبر updated_at) أو بإبطالها في الـ Observers.', 'تخزين البيانات في الكاش يسرع القراءة ولكنه يعقد الكتابة. أفضل نمط هو الرشاقة المستندة للتاريخ (Russian Doll Caching): حيث يحتوي مفتاح الكاش على وقت التحديث: ''user.'' . $user->id . ''.'' . $user->updated_at->timestamp. عند تحديث أي سجل، يتغير الـ timestamp تلقائياً ويصبح المفتاح القديم مهملاً دون الحاجة للبحث عنه وحذفه يدوياً.', '$key = "user:{$user->id}:{$user->updated_at->timestamp}";
return Cache::remember($key, 86400, fn() => $user->load(''profile''));', '["الاعتماد على إبطال الكاش اليدوي المنتشر في عشرات الـ Controllers مما يؤدي لنسيان مسار معين وظهور بيانات متضاربة."]'::jsonb, '["كيف تستخدم أحداث النماذج saved و deleted لمسح مفاتيح الكاش تلقائياً؟"]'::jsonb, '[{"title":"Laravel docs — Cache Usage and Keys","url":"https://laravel.com/docs/master/cache"}]'::jsonb from public.question_revisions r where r.question_id = 'pcache-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcache-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المخاطر المعمارية لتخزين نتائج استعلامات قواعد البيانات في الكاش وكيف تدير الـ Invalidation؟' or l.short_answer is distinct from 'المخاطر هي تقديم بيانات قديمة متناقضة (Stale Data)؛ وتدار إما بربط مفاتيح الكاش بمعرف وتوقيت تحديث السجل (Cache-Busting عبر updated_at) أو بإبطالها في الـ Observers.' or l.explanation is distinct from 'تخزين البيانات في الكاش يسرع القراءة ولكنه يعقد الكتابة. أفضل نمط هو الرشاقة المستندة للتاريخ (Russian Doll Caching): حيث يحتوي مفتاح الكاش على وقت التحديث: ''user.'' . $user->id . ''.'' . $user->updated_at->timestamp. عند تحديث أي سجل، يتغير الـ timestamp تلقائياً ويصبح المفتاح القديم مهملاً دون الحاجة للبحث عنه وحذفه يدوياً.' or l.code_example is distinct from '$key = "user:{$user->id}:{$user->updated_at->timestamp}";
return Cache::remember($key, 86400, fn() => $user->load(''profile''));' or l.common_mistakes is distinct from '["الاعتماد على إبطال الكاش اليدوي المنتشر في عشرات الـ Controllers مما يؤدي لنسيان مسار معين وظهور بيانات متضاربة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستخدم أحداث النماذج saved و deleted لمسح مفاتيح الكاش تلقائياً؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Cache Usage and Keys","url":"https://laravel.com/docs/master/cache"}]'::jsonb)) then raise exception 'Question pcache-006 ar content changed; create a new revision before seeding'; end if; end $$;
