insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي خوارزمية انتهاء الصلاحية المبكر الاحتمالي (Probabilistic Early Expiration) لمقاومة تدافع الكاش؟', 'خوارزمية تعيد حساب وتحديث الكاش في الخلفية بنسبة احتمالية تتصاعد كلما اقترب المفتاح من انتهاء صلاحيته، لضمان عدم وصول الكاش للصفر مطلقاً.', 'عندما ينتهي كاش عنصر عالي الطلب (مثل الصفحة الرئيسية)، فإن مئات الطلبات ستجد الكاش مفقوداً وتنقض على قاعدة البيانات معاً (Cache Stampede / Dog-piling). بدلاً من القفل الصارم، تقوم هذه الخوارزمية (المعروفة بـ XFetch) بحساب قيمة عشوائية كلما قرأ طلب المفتاح في دقائقه الأخيرة؛ فإذا تحققت النسبة، يقوم هذا الطلب بتحديث الكاش بينما يحصل الجميع على نسخة سريعة دون أي توقف.', '// تطبيق منطق التحديث المبكر في الخلفية عند اقتراب TTL من الانتهاء', '["الاعتماد على TTL ثابت فقط في المواقع الضخمة دون معالجة سيناريو لحظة الفناء المفاجئ للمفتاح."]'::jsonb, '["كيف يدعم مشغل Memcached ميزة Anti-Stampede التلقائية؟"]'::jsonb, '[{"title":"Laravel docs — Cache Atomic Locks and Stampede","url":"https://laravel.com/docs/master/cache#atomic-locks"}]'::jsonb from public.question_revisions r where r.question_id = 'pcache-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcache-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي خوارزمية انتهاء الصلاحية المبكر الاحتمالي (Probabilistic Early Expiration) لمقاومة تدافع الكاش؟' or l.short_answer is distinct from 'خوارزمية تعيد حساب وتحديث الكاش في الخلفية بنسبة احتمالية تتصاعد كلما اقترب المفتاح من انتهاء صلاحيته، لضمان عدم وصول الكاش للصفر مطلقاً.' or l.explanation is distinct from 'عندما ينتهي كاش عنصر عالي الطلب (مثل الصفحة الرئيسية)، فإن مئات الطلبات ستجد الكاش مفقوداً وتنقض على قاعدة البيانات معاً (Cache Stampede / Dog-piling). بدلاً من القفل الصارم، تقوم هذه الخوارزمية (المعروفة بـ XFetch) بحساب قيمة عشوائية كلما قرأ طلب المفتاح في دقائقه الأخيرة؛ فإذا تحققت النسبة، يقوم هذا الطلب بتحديث الكاش بينما يحصل الجميع على نسخة سريعة دون أي توقف.' or l.code_example is distinct from '// تطبيق منطق التحديث المبكر في الخلفية عند اقتراب TTL من الانتهاء' or l.common_mistakes is distinct from '["الاعتماد على TTL ثابت فقط في المواقع الضخمة دون معالجة سيناريو لحظة الفناء المفاجئ للمفتاح."]'::jsonb or l.follow_up_questions is distinct from '["كيف يدعم مشغل Memcached ميزة Anti-Stampede التلقائية؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Cache Atomic Locks and Stampede","url":"https://laravel.com/docs/master/cache#atomic-locks"}]'::jsonb)) then raise exception 'Question pcache-009 ar content changed; create a new revision before seeding'; end if; end $$;
