insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل حزم التخزين المؤقت التلقائي لنماذج Eloquent (مثل laravel-model-caching) وما سلبياتها؟', 'تعترض استعلامات Eloquent وتحفظ النتائج في الكاش تلقائياً وتبطلها عبر أحداث النماذج؛ وسلبيتها هي تعقيد تعقب العلاقات المتداخلة واستهلاك الذاكرة المفرط.', 'توفر هذه الحزم كاش فوري بمجرد إضافة Trait إلى النموذج. تقوم باعتراض دالة get() وتوليد مفتاح بناءً على كود الـ SQL ومعاملاته. على الرغم من جاذبيتها في البداية، إلا أنها تعاني في المشاريع الكبيرة من صعوبة التنبؤ بما هو مخزن وما هو مبطل، وقد تسبب إبطالاً كلياً للكاش عند تحديث عمود غير ذي صلة، لذا يفضل معظم مهندسي البرمجيات التخزين المؤقت الصريح والمقصود (Explicit Caching).', '// التخزين الصريح المحدد أفضل وأسهل في التتبع دائماً من الحزم الآلية السحرية', '["الاعتماد على حزم التخزين التلقائي كبديل عن كتابة استعلامات SQL مفهرسة ومحسنة في الأصل."]'::jsonb, '["لماذا تفشل حزم الكاش التلقائي للنماذج في اعتراض الاستعلامات المنفذة عبر DB::table المباشر؟"]'::jsonb, '[{"title":"Laravel docs — Eloquent Caching Considerations","url":"https://laravel.com/docs/master/cache"}]'::jsonb from public.question_revisions r where r.question_id = 'pcache-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'pcache-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل حزم التخزين المؤقت التلقائي لنماذج Eloquent (مثل laravel-model-caching) وما سلبياتها؟' or l.short_answer is distinct from 'تعترض استعلامات Eloquent وتحفظ النتائج في الكاش تلقائياً وتبطلها عبر أحداث النماذج؛ وسلبيتها هي تعقيد تعقب العلاقات المتداخلة واستهلاك الذاكرة المفرط.' or l.explanation is distinct from 'توفر هذه الحزم كاش فوري بمجرد إضافة Trait إلى النموذج. تقوم باعتراض دالة get() وتوليد مفتاح بناءً على كود الـ SQL ومعاملاته. على الرغم من جاذبيتها في البداية، إلا أنها تعاني في المشاريع الكبيرة من صعوبة التنبؤ بما هو مخزن وما هو مبطل، وقد تسبب إبطالاً كلياً للكاش عند تحديث عمود غير ذي صلة، لذا يفضل معظم مهندسي البرمجيات التخزين المؤقت الصريح والمقصود (Explicit Caching).' or l.code_example is distinct from '// التخزين الصريح المحدد أفضل وأسهل في التتبع دائماً من الحزم الآلية السحرية' or l.common_mistakes is distinct from '["الاعتماد على حزم التخزين التلقائي كبديل عن كتابة استعلامات SQL مفهرسة ومحسنة في الأصل."]'::jsonb or l.follow_up_questions is distinct from '["لماذا تفشل حزم الكاش التلقائي للنماذج في اعتراض الاستعلامات المنفذة عبر DB::table المباشر؟"]'::jsonb or l.sources is distinct from '[{"title":"Laravel docs — Eloquent Caching Considerations","url":"https://laravel.com/docs/master/cache"}]'::jsonb)) then raise exception 'Question pcache-010 ar content changed; create a new revision before seeding'; end if; end $$;
