insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو إطار عمل Pest PHP ولماذا أصبح الخيار المفضل لاختبارات Laravel الحديثة على حساب PHPUnit؟', 'Pest هو إطار اختبارات أنيق مبني فوق PHPUnit يوفر صياغة وظيفية موجزة (Expectation API)، وقراءة بديهية جداً للأخطاء، مع الحفاظ على التوافق التام مع ميزات واختبارات PHPUnit.', 'بدلاً من كتابة فئات اختبارات كلاسيكية معقدة وطويلة في PHPUnit، يتيح Pest كتابة الاختبارات كدوال مباشرة مثل test(''user can login'', function () { ... }) واستخدام سلاسل توكيدات طبيعية مثل expect($user->name)->toBe(''Ali'')->not->toBeEmpty(). كما يوفر ميزات متقدمة مثل مراقبة البنية المعمارية (Arch Testing) وتوليد طفرات الاختبار بنقرة واحدة.', '// Pest PHP
test(''calculates total with tax'', function () {
    $order = new Order(price: 100);
    expect($order->totalWithTax(0.15))->toBe(115.0);
});', '["الظن بأن الانتقال إلى Pest يتطلب إعادة كتابة اختبارات PHPUnit السابقة؛ Pest يدعم تشغيل كود واختبارات PHPUnit الكلاسيكية جنباً إلى جنب."]'::jsonb, '["كيف تختبر بنية الكود والمجلدات عبر ميزة Arch Testing في Pest (مثلاً التأكد من عدم استخدام dd() في الكود)؟"]'::jsonb, '[{"title":"Laravel docs — Testing: Getting Started","url":"https://laravel.com/docs/master/testing"}]'::jsonb from public.question_revisions r where r.question_id = 'ptest-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
