insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل ميزة Nullable Reference Types في C# وما دور التحليل الثابت لمسار الكود (Flow Analysis)؟', 'تميز المراجع التي تقبل null (مثل string?) عن التي لا تقبله (string)، ويقوم المترجم بالتحليل الثابت لتحذيرك قبل الوقوع في NullReferenceException وقت التشغيل.', 'منذ C# 8، أصبح بإمكان المطورين تفعيل <Nullable>enable</Nullable>. في هذا الوضع، يفترض المترجم أن كل مراجع الكائنات غير قابلة للقيم الفارغة ما لم تُحدد بعلامة الاستفهام صراحة. يقوم المحرك بتحليل مسار الكود (Static Flow Analysis)؛ فإذا قمت بفحص if (user != null)، يدرك المترجم داخل الكتلة أن المتغير آمن ويسمح باستدعاء خصائصه دون تحذيرات.', 'string nonNull = "Hello"; // لا يقبل null
string? canBeNull = null; // مسموح

// Console.WriteLine(canBeNull.Length); // تحذير من المترجم!
if (canBeNull != null) {
    Console.WriteLine(canBeNull.Length); // آمن بعد فحص التدفق
}', '["استخدام عامل القمع القسري (Null-forgiving operator !) مثل user!.Name لتجاوز تحذير المترجم دون فحص حقيقي مما يسبب انهيار وقت التشغيل."]'::jsonb, '["ما هو دور سمات الفحص المتقدمة مثل [NotNullWhen(true)] في دوال TryParse؟"]'::jsonb, '[{"title":"Microsoft Learn — Nullable reference types","url":"https://learn.microsoft.com/en-us/dotnet/csharp/nullable-references"}]'::jsonb from public.question_revisions r where r.question_id = 'ncsharp-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
