insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين Delegate و Action و Func وما دور كلمة event في حماية التغليف؟', 'الـ Delegate هو مؤشر دالة آمن للأنواع؛ Func تعيد قيمة وAction لا تعيد شيئاً، وكلمة event تمنع المشتركين الخارجيين من استدعاء أو مسح قائمة المستمعين باستثناء += و -=.', 'الـ Delegate هو نوع يمثل توقيع دالة. بدلاً من تعريف delegate مخصص لكل حالة، وفرت مايكروسوفت Func<T, TResult> للدوال ذات المخرجات، و Action<T> للدوال void. استخدام كلمة event مع الـ delegate يضيف حماية للمغلف (Encapsulation)؛ بحيث لا يستطيع كود خارج الفئة إطلاق الحدث مباشرة (invoke) أو مسح مستمعي الآخرين عبر = null، ويقتصر على الاشتراك += وإلغاء الاشتراك -=.', 'public class OrderProcessor {
    public event Action<Order>? OrderCompleted;
    public void Process(Order order) {
        OrderCompleted?.Invoke(order); // يطلق من داخل الفئة فقط
    }
}', '["عدم إلغاء الاشتراك من الأحداث (-=) في الكائنات طويلة العمر مما يمنع الـ Garbage Collector من تحرير الكائنات المستمعة ويسبب تسريب ذاكرة."]'::jsonb, '["كيف يساعد نمط WeakEventManager في منع تسريبات الذاكرة عند الاشتراك في الأحداث؟"]'::jsonb, '[{"title":"Microsoft Learn — Events overview","url":"https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/events/"}]'::jsonb from public.question_revisions r where r.question_id = 'ncsharp-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ncsharp-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين Delegate و Action و Func وما دور كلمة event في حماية التغليف؟' or l.short_answer is distinct from 'الـ Delegate هو مؤشر دالة آمن للأنواع؛ Func تعيد قيمة وAction لا تعيد شيئاً، وكلمة event تمنع المشتركين الخارجيين من استدعاء أو مسح قائمة المستمعين باستثناء += و -=.' or l.explanation is distinct from 'الـ Delegate هو نوع يمثل توقيع دالة. بدلاً من تعريف delegate مخصص لكل حالة، وفرت مايكروسوفت Func<T, TResult> للدوال ذات المخرجات، و Action<T> للدوال void. استخدام كلمة event مع الـ delegate يضيف حماية للمغلف (Encapsulation)؛ بحيث لا يستطيع كود خارج الفئة إطلاق الحدث مباشرة (invoke) أو مسح مستمعي الآخرين عبر = null، ويقتصر على الاشتراك += وإلغاء الاشتراك -=.' or l.code_example is distinct from 'public class OrderProcessor {
    public event Action<Order>? OrderCompleted;
    public void Process(Order order) {
        OrderCompleted?.Invoke(order); // يطلق من داخل الفئة فقط
    }
}' or l.common_mistakes is distinct from '["عدم إلغاء الاشتراك من الأحداث (-=) في الكائنات طويلة العمر مما يمنع الـ Garbage Collector من تحرير الكائنات المستمعة ويسبب تسريب ذاكرة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يساعد نمط WeakEventManager في منع تسريبات الذاكرة عند الاشتراك في الأحداث؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Events overview","url":"https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/events/"}]'::jsonb)) then raise exception 'Question ncsharp-006 ar content changed; create a new revision before seeding'; end if; end $$;
