insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يطبق نمط التخلص القياسي (IDisposable Pattern) وما الفرق بين الموارد المدارة وغير المدارة (Managed vs Unmanaged)؟', 'الموارد المدارة يتحكم بها الـ CLR تلقائياً، بينما غير المدارة (مثل مقابض ملفات نظام التشغيل ومقابس الشبكة) تتطلب تحريراً صريحاً عبر IDisposable ودالة Dispose().', 'الـ Garbage Collector لا يعلم متى وكيف يغلق مقبض ملف لنظام التشغيل أو اتصال قاعدة بيانات مغلق. تطبيق واجهة IDisposable يتيح استخدام كتلة using (أو using declaration) لضمان استدعاء Dispose() فور الخروج من النطاق. نمط Dispose(bool disposing) المتقدم يحمي الموارد غير المدارة عبر Finalizer (~Class()) كملاذ أخير في حال نسيان المطور استدعاء Dispose().', 'public class ResourceHolder : IDisposable {
    private bool _disposed;
    public void Dispose() {
        Dispose(true);
        GC.SuppressFinalize(this); // إلغاء الـ Finalizer لتوفير موارد الـ GC
    }
    protected virtual void Dispose(bool disposing) {
        if (!_disposed) {
            if (disposing) { /* تحرير الموارد المدارة */ }
            /* تحرير الموارد غير المدارة */
            _disposed = true;
        }
    }
}', '["نسيان استدعاء GC.SuppressFinalize(this) داخل Dispose() مما يجبر الـ GC على إبقاء الكائن لدورة تنظيف إضافية غير ضرورية."]'::jsonb, '["كيف تعمل واجهة IAsyncDisposable وعبارة await using للموارد التي تتطلب تحريراً غير متزامن؟"]'::jsonb, '[{"title":"Microsoft Learn — Implement a Dispose method","url":"https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/implementing-dispose"}]'::jsonb from public.question_revisions r where r.question_id = 'ncsharp-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ncsharp-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يطبق نمط التخلص القياسي (IDisposable Pattern) وما الفرق بين الموارد المدارة وغير المدارة (Managed vs Unmanaged)؟' or l.short_answer is distinct from 'الموارد المدارة يتحكم بها الـ CLR تلقائياً، بينما غير المدارة (مثل مقابض ملفات نظام التشغيل ومقابس الشبكة) تتطلب تحريراً صريحاً عبر IDisposable ودالة Dispose().' or l.explanation is distinct from 'الـ Garbage Collector لا يعلم متى وكيف يغلق مقبض ملف لنظام التشغيل أو اتصال قاعدة بيانات مغلق. تطبيق واجهة IDisposable يتيح استخدام كتلة using (أو using declaration) لضمان استدعاء Dispose() فور الخروج من النطاق. نمط Dispose(bool disposing) المتقدم يحمي الموارد غير المدارة عبر Finalizer (~Class()) كملاذ أخير في حال نسيان المطور استدعاء Dispose().' or l.code_example is distinct from 'public class ResourceHolder : IDisposable {
    private bool _disposed;
    public void Dispose() {
        Dispose(true);
        GC.SuppressFinalize(this); // إلغاء الـ Finalizer لتوفير موارد الـ GC
    }
    protected virtual void Dispose(bool disposing) {
        if (!_disposed) {
            if (disposing) { /* تحرير الموارد المدارة */ }
            /* تحرير الموارد غير المدارة */
            _disposed = true;
        }
    }
}' or l.common_mistakes is distinct from '["نسيان استدعاء GC.SuppressFinalize(this) داخل Dispose() مما يجبر الـ GC على إبقاء الكائن لدورة تنظيف إضافية غير ضرورية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل واجهة IAsyncDisposable وعبارة await using للموارد التي تتطلب تحريراً غير متزامن؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Implement a Dispose method","url":"https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/implementing-dispose"}]'::jsonb)) then raise exception 'Question ncsharp-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a .NET developer know about Csharp Idisposable And Finalizers?', 'This question checks the core Csharp Idisposable And Finalizers concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.', 'Explain Csharp Idisposable And Finalizers with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'public class ResourceHolder : IDisposable {
