insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل مجمع المهملات (Garbage Collector) في .NET وما هي الأجيال الثلاثة (Gen 0, Gen 1, Gen 2)؟', 'يقسم الـ Heap إلى 3 أجيال بناءً على عمر الكائنات: Gen 0 للكائنات حديثة الإنشاء، Gen 1 كمنطقة وسيطة، وGen 2 للكائنات طويلة العمر، مما يسرع التنظيف ويركز على الأكثر موتاً.', 'يعتمد الـ GC على فرضية أن معظم الكائنات تموت بعد وقت قصير جداً من إنشائها. يتم تخصيص الكائنات في Gen 0؛ وعند امتلائه، يُنفذ تنظيف سريع جداً لا يتطلب فحص كامل الذاكرة. الكائنات التي تنجو من التنظيف تُرقّى إلى Gen 1 ثم Gen 2. تنظيف Gen 2 يسمى Full GC وهو الأكثر استهلاكاً لوقت المعالج ويتطلب تجميد خيوط التطبيق في الأنماط غير المتزامنة.', 'Console.WriteLine("User gen: " + GC.GetGeneration(user));
Console.WriteLine("Total Memory: " + GC.GetTotalMemory(false));', '["استدعاء GC.Collect() يدوياً في الكود الإنتاجي مما يربك خوارزميات الـ CLR الذكية ويفسد توازن الأجيال."]'::jsonb, '["ما هو جيل Large Object Heap (LOH) وما الحد الأدنى لحجم الكائن ليدخل فيه؟"]'::jsonb, '[{"title":"Microsoft Learn — Fundamentals of garbage collection","url":"https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/fundamentals"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل مجمع المهملات (Garbage Collector) في .NET وما هي الأجيال الثلاثة (Gen 0, Gen 1, Gen 2)؟' or l.short_answer is distinct from 'يقسم الـ Heap إلى 3 أجيال بناءً على عمر الكائنات: Gen 0 للكائنات حديثة الإنشاء، Gen 1 كمنطقة وسيطة، وGen 2 للكائنات طويلة العمر، مما يسرع التنظيف ويركز على الأكثر موتاً.' or l.explanation is distinct from 'يعتمد الـ GC على فرضية أن معظم الكائنات تموت بعد وقت قصير جداً من إنشائها. يتم تخصيص الكائنات في Gen 0؛ وعند امتلائه، يُنفذ تنظيف سريع جداً لا يتطلب فحص كامل الذاكرة. الكائنات التي تنجو من التنظيف تُرقّى إلى Gen 1 ثم Gen 2. تنظيف Gen 2 يسمى Full GC وهو الأكثر استهلاكاً لوقت المعالج ويتطلب تجميد خيوط التطبيق في الأنماط غير المتزامنة.' or l.code_example is distinct from 'Console.WriteLine("User gen: " + GC.GetGeneration(user));
Console.WriteLine("Total Memory: " + GC.GetTotalMemory(false));' or l.common_mistakes is distinct from '["استدعاء GC.Collect() يدوياً في الكود الإنتاجي مما يربك خوارزميات الـ CLR الذكية ويفسد توازن الأجيال."]'::jsonb or l.follow_up_questions is distinct from '["ما هو جيل Large Object Heap (LOH) وما الحد الأدنى لحجم الكائن ليدخل فيه؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Fundamentals of garbage collection","url":"https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/fundamentals"}]'::jsonb)) then raise exception 'Question nruntime-001 ar content changed; create a new revision before seeding'; end if; end $$;
