insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('nruntime-002', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الـ Large Object Heap (LOH) في .NET ولماذا يعد عرضة لتفتت الذاكرة (Memory Fragmentation)؟', 'منطقة مخصصة للكائنات التي تتجاوز 85,000 بايت (مثل المصفوفات الضخمة)؛ ولا يتم ضغطها افتراضياً لتوفير كلفة نقل البيانات الكبيرة، مما يخلق فجوات ذاكرة تؤدي للـ OOM.', 'نظراً لأن نسخ كائنات الـ 85KB+ في الذاكرة أثناء الـ Garbage Collection يستهلك وقتاً ضخماً، كان الـ GC ينظفها دون ضغط (Compaction)، تاركاً فراغات بين المساحات المحررة. مع تكرار تخصيص وحذف مصفوفات ضخمة، تتفتت الذاكرة ويعجز السيرفر عن إيجاد مساحة متصلة لكائن جديد فينهار التطبيق بـ OutOfMemoryException. الحل هو استخدام ArrayPool<T> لإعادة تدوير المصفوفات الكبيرة.', '// استخدام ArrayPool لتجنب تخصيص الـ LOH والتفتت
var pool = ArrayPool<byte>.Shared;
byte[] buffer = pool.Rent(100_000); // استعارة من الـ Pool
try {
    // معالجة البيانات
} finally {
    pool.Return(buffer); // إرجاع للـ Pool
}', '["حجز مصفوفات بايتات مؤقتة كبيرة في كل طلب معالجة ملفات بدلاً من استعارتها من ArrayPool."]'::jsonb, '["كيف تفعل ضغط الـ LOH عند الضرورة عبر GCSettings.LargeObjectHeapCompactionMode؟"]'::jsonb, '[{"title":"Microsoft Learn — The large object heap on Windows systems","url":"https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/large-object-heap"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الـ Large Object Heap (LOH) في .NET ولماذا يعد عرضة لتفتت الذاكرة (Memory Fragmentation)؟' or l.short_answer is distinct from 'منطقة مخصصة للكائنات التي تتجاوز 85,000 بايت (مثل المصفوفات الضخمة)؛ ولا يتم ضغطها افتراضياً لتوفير كلفة نقل البيانات الكبيرة، مما يخلق فجوات ذاكرة تؤدي للـ OOM.' or l.explanation is distinct from 'نظراً لأن نسخ كائنات الـ 85KB+ في الذاكرة أثناء الـ Garbage Collection يستهلك وقتاً ضخماً، كان الـ GC ينظفها دون ضغط (Compaction)، تاركاً فراغات بين المساحات المحررة. مع تكرار تخصيص وحذف مصفوفات ضخمة، تتفتت الذاكرة ويعجز السيرفر عن إيجاد مساحة متصلة لكائن جديد فينهار التطبيق بـ OutOfMemoryException. الحل هو استخدام ArrayPool<T> لإعادة تدوير المصفوفات الكبيرة.' or l.code_example is distinct from '// استخدام ArrayPool لتجنب تخصيص الـ LOH والتفتت
var pool = ArrayPool<byte>.Shared;
byte[] buffer = pool.Rent(100_000); // استعارة من الـ Pool
try {
    // معالجة البيانات
} finally {
    pool.Return(buffer); // إرجاع للـ Pool
}' or l.common_mistakes is distinct from '["حجز مصفوفات بايتات مؤقتة كبيرة في كل طلب معالجة ملفات بدلاً من استعارتها من ArrayPool."]'::jsonb or l.follow_up_questions is distinct from '["كيف تفعل ضغط الـ LOH عند الضرورة عبر GCSettings.LargeObjectHeapCompactionMode؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — The large object heap on Windows systems","url":"https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/large-object-heap"}]'::jsonb)) then raise exception 'Question nruntime-002 ar content changed; create a new revision before seeding'; end if; end $$;
