insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف ينفذ الـ CLR كود C# وما هي اللغة الوسيطة (CIL/IL) ودور مجمع الـ JIT؟', 'يترجم مترجم Roslyn كود C# إلى لغة وسيطة (IL) مستقلة عن المنصة؛ وعند تشغيل البرنامج، يقوم الـ JIT Compiler بترجمة الـ IL إلى تعليمات المعالج الأصلية (Machine Code).', 'يضمن هذا النموذج مبدأ ''Build Once, Run Anywhere''. ملفات .dll في .NET لا تحتوي كود آلة خالصاً بل بايتات CIL وبيانات وصفية (Metadata). عند استدعاء دالة لأول مرة، يتدخل مجمع Just-In-Time (JIT) لترجمتها لتعليمات المعالج الدقيقة (x64 أو ARM64) وحفظ العنوان في الذاكرة لتنفيذه مباشرة في الاستدعاءات التالية بسرعة فائقة.', '// C# -> Roslyn -> IL (.dll) -> CLR JIT -> Machine Code (Native)', '["الاعتقاد بأن ملفات .dll في .NET هي ملفات ثنائية أصلية خاصة بنظام Windows فقط."]'::jsonb, '["ما هي ميزة Tiered Compilation وكيف توازن بين سرعة بدء التشغيل وجودة تحسين الكود؟"]'::jsonb, '[{"title":"Microsoft Learn — Common Language Runtime (CLR) overview","url":"https://learn.microsoft.com/en-us/dotnet/standard/clr"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف ينفذ الـ CLR كود C# وما هي اللغة الوسيطة (CIL/IL) ودور مجمع الـ JIT؟' or l.short_answer is distinct from 'يترجم مترجم Roslyn كود C# إلى لغة وسيطة (IL) مستقلة عن المنصة؛ وعند تشغيل البرنامج، يقوم الـ JIT Compiler بترجمة الـ IL إلى تعليمات المعالج الأصلية (Machine Code).' or l.explanation is distinct from 'يضمن هذا النموذج مبدأ ''Build Once, Run Anywhere''. ملفات .dll في .NET لا تحتوي كود آلة خالصاً بل بايتات CIL وبيانات وصفية (Metadata). عند استدعاء دالة لأول مرة، يتدخل مجمع Just-In-Time (JIT) لترجمتها لتعليمات المعالج الدقيقة (x64 أو ARM64) وحفظ العنوان في الذاكرة لتنفيذه مباشرة في الاستدعاءات التالية بسرعة فائقة.' or l.code_example is distinct from '// C# -> Roslyn -> IL (.dll) -> CLR JIT -> Machine Code (Native)' or l.common_mistakes is distinct from '["الاعتقاد بأن ملفات .dll في .NET هي ملفات ثنائية أصلية خاصة بنظام Windows فقط."]'::jsonb or l.follow_up_questions is distinct from '["ما هي ميزة Tiered Compilation وكيف توازن بين سرعة بدء التشغيل وجودة تحسين الكود؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Common Language Runtime (CLR) overview","url":"https://learn.microsoft.com/en-us/dotnet/standard/clr"}]'::jsonb)) then raise exception 'Question nruntime-004 ar content changed; create a new revision before seeding'; end if; end $$;
