insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي ميزة Native AOT في .NET 8+ وما هي المكاسب والقيود المرتبطة بها؟', 'تترجم الكود مباشرة إلى ملف تنفيذي أصلي للآلة دون الحاجة لوجود مجمع JIT أو تثبيت .NET Runtime، مما يقلل زمن البدء واستهلاك الذاكرة ولكن مع قيود على Reflection.', 'في Native Ahead-Of-Time (AOT)، يتم تقليم الأكواد غير المستخدمة (Trimming) وتجميع كامل التطبيق إلى ملف تنفيذي ذاتي مستقل بحجم صغير جداً. المكاسب هائلة لوظائف الـ Serverless والحاويات المصغرة حيث يقل زمن الإقلاع لعشرات المللي ثوانٍ ويقل استهلاك الرام للنصف. القيد الأبرز هو حظر توليد الأكواد الديناميكية وReflection غير المتوافق مع التحليل الساكن.', '<PropertyGroup>
  <PublishAot>true</PublishAot>
</PropertyGroup>', '["محاولة نشر تطبيق يعتمد على مكتبات قديمة تستخدم Reflection كثيف كـ Native AOT دون استبدالها بـ Source Generators."]'::jsonb, '["كيف تنبهك تحذيرات Trimming Warnings وقت البناء إلى الأكواد غير المتوافقة مع AOT؟"]'::jsonb, '[{"title":"Microsoft Learn — Native AOT deployment overview","url":"https://learn.microsoft.com/en-us/dotnet/core/deploying/native-aot/"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
