insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل الترجمة المتدرجة (Tiered Compilation) والتحسين المستند للملف الشخصي (Dynamic PGO)؟', 'يبدأ JIT بترجمة سريعة دون تحسينات (Tier 0) لسرعة الإقلاع، ثم يراقب الدوال الأكثر استخداماً ويعيد تجميعها بأعلى تحسينات مخصصة للمعالج (Tier 1 و PGO).', 'يجمع Tiered Compilation بين ميزتي الإقلاع الفوري والأداء الأقصى. دالة Tier 0 تترجم بسرعة وبلا تحسينات لمساعدة التطبيق على الاستجابة فوراً. إذا رصد المحرك استدعاء الدالة مئات المرات (Hot Method)، يقوم في الخلفية بتسجيل أنماط بياناتها واستدعاءاتها عبر Dynamic PGO (Profile-Guided Optimization)، ثم يعيد ترجمتها بحسابات متقدمة وفرد للحلقات (Loop Unrolling) لسرعة خارقة.', '// مفعل تلقائياً في .NET 8+
<PropertyGroup>
  <TieredPGO>true</TieredPGO>
</PropertyGroup>', '["إجراء اختبارات قياس الأداء (Benchmarks) في الدقائق الأولى لتشغيل السيرفر قبل أن ينتهي الـ JIT من مرحلة ترقية Tier 1 PGO."]'::jsonb, '["كيف تساعد أداة BenchmarkDotNet في عزل فترات الإحماء (Warmup) لضمان قياس أداء كود Tier 1 بدقة؟"]'::jsonb, '[{"title":"Microsoft Learn — Tiered compilation","url":"https://learn.microsoft.com/en-us/dotnet/core/whats-new/dotnet-core-3-0#tiered-compilation"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل الترجمة المتدرجة (Tiered Compilation) والتحسين المستند للملف الشخصي (Dynamic PGO)؟' or l.short_answer is distinct from 'يبدأ JIT بترجمة سريعة دون تحسينات (Tier 0) لسرعة الإقلاع، ثم يراقب الدوال الأكثر استخداماً ويعيد تجميعها بأعلى تحسينات مخصصة للمعالج (Tier 1 و PGO).' or l.explanation is distinct from 'يجمع Tiered Compilation بين ميزتي الإقلاع الفوري والأداء الأقصى. دالة Tier 0 تترجم بسرعة وبلا تحسينات لمساعدة التطبيق على الاستجابة فوراً. إذا رصد المحرك استدعاء الدالة مئات المرات (Hot Method)، يقوم في الخلفية بتسجيل أنماط بياناتها واستدعاءاتها عبر Dynamic PGO (Profile-Guided Optimization)، ثم يعيد ترجمتها بحسابات متقدمة وفرد للحلقات (Loop Unrolling) لسرعة خارقة.' or l.code_example is distinct from '// مفعل تلقائياً في .NET 8+
<PropertyGroup>
  <TieredPGO>true</TieredPGO>
</PropertyGroup>' or l.common_mistakes is distinct from '["إجراء اختبارات قياس الأداء (Benchmarks) في الدقائق الأولى لتشغيل السيرفر قبل أن ينتهي الـ JIT من مرحلة ترقية Tier 1 PGO."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساعد أداة BenchmarkDotNet في عزل فترات الإحماء (Warmup) لضمان قياس أداء كود Tier 1 بدقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Tiered compilation","url":"https://learn.microsoft.com/en-us/dotnet/core/whats-new/dotnet-core-3-0#tiered-compilation"}]'::jsonb)) then raise exception 'Question nruntime-006 ar content changed; create a new revision before seeding'; end if; end $$;
