insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تستخدم فئة AssemblyLoadContext لعزل وتفريغ الإضافات (Plugins) من الذاكرة ديناميكياً؟', 'توفر نطاق عزل لتحميل ملفات .dll مستقلة مع إمكانية تفريغها بالكامل من الذاكرة (Collectibility) عند الانتهاء دون إيقاف العملية الرئيسية.', 'افتراضياً في .NET، لا يمكن تفريغ أي تجميعة (Assembly) يتم تحميلها في الـ Default Context حتى تموت العملية بأكملها. باستخدام فئة مشتقة من AssemblyLoadContext محددة بـ isCollectible: true، يمكنك تحميل إضافات برمجية خارجية، وتشغيلها، ثم استدعاء alc.Unload() والتأكد من إزالة كل المراجع ليقوم الـ GC بمسح التجميعة بالكامل من الرام.', 'var alc = new AssemblyLoadContext("PluginContext", isCollectible: true);
var assembly = alc.LoadFromAssemblyPath(pluginPath);
// تنفيذ الكود ثم التفريغ
alc.Unload();', '["الاحتفاظ بمراجع غير مباشرة لكائنات أو أنواع قادمة من الـ Plugin في الـ Host الرئيسي مما يمنع تفريغ الـ Context."]'::jsonb, '["كيف تتحقق من اكتمال تفريغ الـ AssemblyLoadContext باستخدام WeakReference؟"]'::jsonb, '[{"title":"Microsoft Learn — Understanding AssemblyLoadContext","url":"https://learn.microsoft.com/en-us/dotnet/core/dependency-loading/understanding-assemblyloadcontext"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تستخدم فئة AssemblyLoadContext لعزل وتفريغ الإضافات (Plugins) من الذاكرة ديناميكياً؟' or l.short_answer is distinct from 'توفر نطاق عزل لتحميل ملفات .dll مستقلة مع إمكانية تفريغها بالكامل من الذاكرة (Collectibility) عند الانتهاء دون إيقاف العملية الرئيسية.' or l.explanation is distinct from 'افتراضياً في .NET، لا يمكن تفريغ أي تجميعة (Assembly) يتم تحميلها في الـ Default Context حتى تموت العملية بأكملها. باستخدام فئة مشتقة من AssemblyLoadContext محددة بـ isCollectible: true، يمكنك تحميل إضافات برمجية خارجية، وتشغيلها، ثم استدعاء alc.Unload() والتأكد من إزالة كل المراجع ليقوم الـ GC بمسح التجميعة بالكامل من الرام.' or l.code_example is distinct from 'var alc = new AssemblyLoadContext("PluginContext", isCollectible: true);
var assembly = alc.LoadFromAssemblyPath(pluginPath);
// تنفيذ الكود ثم التفريغ
alc.Unload();' or l.common_mistakes is distinct from '["الاحتفاظ بمراجع غير مباشرة لكائنات أو أنواع قادمة من الـ Plugin في الـ Host الرئيسي مما يمنع تفريغ الـ Context."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتحقق من اكتمال تفريغ الـ AssemblyLoadContext باستخدام WeakReference؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Understanding AssemblyLoadContext","url":"https://learn.microsoft.com/en-us/dotnet/core/dependency-loading/understanding-assemblyloadcontext"}]'::jsonb)) then raise exception 'Question nruntime-007 ar content changed; create a new revision before seeding'; end if; end $$;
