insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو تثبيت الذاكرة (Memory Pinning) وعبارة fixed وما مخاطرها على الـ Garbage Collector؟', 'تثبيت الكائن في موقع محدد بالـ RAM لمنع الـ GC من تحريكه أثناء تمريره لكود غير مدار (C/C++)؛ ومخاطره إعاقة ضغط الذاكرة وخلق تفتت حاد في الـ Heap.', 'يقوم الـ GC عادة بضغط الذاكرة ونقل الكائنات لتوفير مساحات متصلة. إذا كنت تتعامل مع دالة C أصلية عبر P/Invoke تتوقع مؤشراً ثابتاً لعنوان الذاكرة، فإن عبارة fixed تضع علامة تثبيت (Pinning) على الكائن تمنع الـ GC من تحريكه طوال مدة الكتلة. الإفراط في تثبيت كائنات في Gen 0/1 يعيق حركة الـ GC ويجبره على القفز فوقها مسبباً تفتت الذاكرة.', 'unsafe {
    byte[] buffer = new byte[100];
    fixed (byte* p = buffer) {
        // المؤشر p ثابت ولا يمكن للـ GC تحريكه هنا
        NativeMethods.FillBuffer(p, 100);
    }
}', '["تثبيت الكائنات لفترات طويلة جداً مما يمنع ضغط الـ Heap ويؤدي للـ Memory Fragmentation."]'::jsonb, '["كيف توفر ميزة GCHandle.Alloc(obj, GCHandleType.Pinned) تثبيتاً يدوياً خارج نطاق الكتل غير الآمنة؟"]'::jsonb, '[{"title":"Microsoft Learn — fixed statement (C# reference)","url":"https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/statements/fixed"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو تثبيت الذاكرة (Memory Pinning) وعبارة fixed وما مخاطرها على الـ Garbage Collector؟' or l.short_answer is distinct from 'تثبيت الكائن في موقع محدد بالـ RAM لمنع الـ GC من تحريكه أثناء تمريره لكود غير مدار (C/C++)؛ ومخاطره إعاقة ضغط الذاكرة وخلق تفتت حاد في الـ Heap.' or l.explanation is distinct from 'يقوم الـ GC عادة بضغط الذاكرة ونقل الكائنات لتوفير مساحات متصلة. إذا كنت تتعامل مع دالة C أصلية عبر P/Invoke تتوقع مؤشراً ثابتاً لعنوان الذاكرة، فإن عبارة fixed تضع علامة تثبيت (Pinning) على الكائن تمنع الـ GC من تحريكه طوال مدة الكتلة. الإفراط في تثبيت كائنات في Gen 0/1 يعيق حركة الـ GC ويجبره على القفز فوقها مسبباً تفتت الذاكرة.' or l.code_example is distinct from 'unsafe {
    byte[] buffer = new byte[100];
    fixed (byte* p = buffer) {
        // المؤشر p ثابت ولا يمكن للـ GC تحريكه هنا
        NativeMethods.FillBuffer(p, 100);
    }
}' or l.common_mistakes is distinct from '["تثبيت الكائنات لفترات طويلة جداً مما يمنع ضغط الـ Heap ويؤدي للـ Memory Fragmentation."]'::jsonb or l.follow_up_questions is distinct from '["كيف توفر ميزة GCHandle.Alloc(obj, GCHandleType.Pinned) تثبيتاً يدوياً خارج نطاق الكتل غير الآمنة؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — fixed statement (C# reference)","url":"https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/statements/fixed"}]'::jsonb)) then raise exception 'Question nruntime-008 ar content changed; create a new revision before seeding'; end if; end $$;
