insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي كارثة تجويع الـ ThreadPool (Starvation) الناتجة عن ممارسة Sync-over-Async (.Result / .Wait())؟', 'تحدث عندما يحجب خيط من الـ ThreadPool بانتظار نتيجة Task غير مكتملة، مما يستنزف خيوط المسبح ويجعل التطبيق عاجزاً عن خدمة أي طلبات جديدة حتى الموت.', 'يحتوي الـ ThreadPool على عدد أولي من الخيوط ويزيدها ببطء شديد (حوالي خيط أو اثنين في الثانية). إذا استدعى كود متزامن task.Result أو task.Wait()، يُقفل الخيط الحالي في حالة خمول بانتظار انتهاء المهمة التي تحتاج هي الأخرى لخيط من نفس المسبح لتكتمل. في حالة وصول عشرات الطلبات المتزامنة، تتجمد كل الخيوط في انتظار بعضها وتحدث الوفاة التامة للخادم (Deadlock / Starvation).', '// خطأ مميت يدمر الخادم:
public IActionResult GetData() {
    var data = _service.GetDataAsync().Result; // حظر خيط الـ ThreadPool!
    return Ok(data);
}

// الطريقة الصحيحة دائماً:
public async Task<IActionResult> GetData() {
    var data = await _service.GetDataAsync();
    return Ok(data);
}', '["استدعاء .GetAwaiter().GetResult() كبديل ظناً أنه آمن؛ هو يحجب الخيط تماماً مثل .Result."]'::jsonb, '["كيف تراقب عدد خيوط الـ ThreadPool النشطة ومعدل نموها باستخدام عدادات الـ dotnet-counters؟"]'::jsonb, '[{"title":"Microsoft Learn — Asynchronous programming scenarios","url":"https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي كارثة تجويع الـ ThreadPool (Starvation) الناتجة عن ممارسة Sync-over-Async (.Result / .Wait())؟' or l.short_answer is distinct from 'تحدث عندما يحجب خيط من الـ ThreadPool بانتظار نتيجة Task غير مكتملة، مما يستنزف خيوط المسبح ويجعل التطبيق عاجزاً عن خدمة أي طلبات جديدة حتى الموت.' or l.explanation is distinct from 'يحتوي الـ ThreadPool على عدد أولي من الخيوط ويزيدها ببطء شديد (حوالي خيط أو اثنين في الثانية). إذا استدعى كود متزامن task.Result أو task.Wait()، يُقفل الخيط الحالي في حالة خمول بانتظار انتهاء المهمة التي تحتاج هي الأخرى لخيط من نفس المسبح لتكتمل. في حالة وصول عشرات الطلبات المتزامنة، تتجمد كل الخيوط في انتظار بعضها وتحدث الوفاة التامة للخادم (Deadlock / Starvation).' or l.code_example is distinct from '// خطأ مميت يدمر الخادم:
public IActionResult GetData() {
    var data = _service.GetDataAsync().Result; // حظر خيط الـ ThreadPool!
    return Ok(data);
}

// الطريقة الصحيحة دائماً:
public async Task<IActionResult> GetData() {
    var data = await _service.GetDataAsync();
    return Ok(data);
}' or l.common_mistakes is distinct from '["استدعاء .GetAwaiter().GetResult() كبديل ظناً أنه آمن؛ هو يحجب الخيط تماماً مثل .Result."]'::jsonb or l.follow_up_questions is distinct from '["كيف تراقب عدد خيوط الـ ThreadPool النشطة ومعدل نموها باستخدام عدادات الـ dotnet-counters؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Asynchronous programming scenarios","url":"https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/"}]'::jsonb)) then raise exception 'Question nruntime-009 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a .NET developer know about Dotnet Threadpool Starvation And Sync Over Async?', 'This question checks the core Dotnet Threadpool Starvation And Sync Over Async concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.', 'Explain Dotnet Threadpool Starvation And Sync Over Async with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// خطأ مميت يدمر الخادم:
public IActionResult GetData() {
    var data = _service.GetDataAsync().Result; // حظر خيط الـ ThreadPool!
    return Ok(data);
}

// الطريقة الصحيحة دائماً:
public async Task<IActionResult> GetData() {
    var data = await _service.GetDataAsync();
    return Ok(data);
}', '["Missing the key trade-off in Dotnet Threadpool Starvation And Sync Over Async (point 1)."]'::jsonb, '["How would you apply Dotnet Threadpool Starvation And Sync Over Async in a production .NET app (follow-up 1)?"]'::jsonb, '[{"title":"Microsoft Learn — Asynchronous programming scenarios","url":"https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-009' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a .NET developer know about Dotnet Threadpool Starvation And Sync Over Async?' or l.short_answer is distinct from 'This question checks the core Dotnet Threadpool Starvation And Sync Over Async concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.' or l.explanation is distinct from 'Explain Dotnet Threadpool Starvation And Sync Over Async with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from '// خطأ مميت يدمر الخادم:
public IActionResult GetData() {
    var data = _service.GetDataAsync().Result; // حظر خيط الـ ThreadPool!
    return Ok(data);
}

// الطريقة الصحيحة دائماً:
public async Task<IActionResult> GetData() {
    var data = await _service.GetDataAsync();
    return Ok(data);
}' or l.common_mistakes is distinct from '["Missing the key trade-off in Dotnet Threadpool Starvation And Sync Over Async (point 1)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Dotnet Threadpool Starvation And Sync Over Async in a production .NET app (follow-up 1)?"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Asynchronous programming scenarios","url":"https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/"}]'::jsonb)) then raise exception 'Question nruntime-009 en content changed; create a new revision before seeding'; end if; end $$;
