insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تشخص أعطال الذاكرة والـ Deadlocks في بيئات الإنتاج بـ Linux باستخدام dotnet-dump و dotnet-trace؟', 'تجمع ملف تفريغ الذاكرة (Memory Dump) بـ dotnet-dump دون إيقاف السيرفر، وتحلله بأوامر SOS مثل dumpheap -stat لتحديد تسريبات الكائنات وأقفال الخيوط.', 'في بيئات الحاويات وLinux السحابية، لا يمكنك تشغيل Visual Studio المباشر. توفر مايكروسوفت أدوات تشخيص عالمية عبر مقبس EventPipe. باستخدام dotnet-dump collect -p <pid>، يتم التقاط لقطة ذاكرة كاملة للحاوية، ثم استخدام dotnet-dump analyze لفحص كائنات الـ Managed Heap، ومعرفة الخيوط العالقة في sync-blocks، ومسارات الجذور المسببة للـ Memory Leaks بدقة.', '// جمع لقطة تفريغ في بيئة الإنتاج:
// dotnet-dump collect -p 1234
// dotnet-dump analyze core_dump
// > dumpheap -stat
// > clrstack -all', '["أخذ ملفات تفريغ ذاكرة كاملة (Full Dumps) في سيرفرات تمتلك مساحات رام هائلة ومساحة قرص محدودة مما يملأ القرص."]'::jsonb, '["كيف تسجل مقاييس الأداء الحية للـ GC ومعدلات الاستجابة عبر dotnet-counters monitor؟"]'::jsonb, '[{"title":"Microsoft Learn — Diagnostic tools in .NET","url":"https://learn.microsoft.com/en-us/dotnet/core/diagnostics/"}]'::jsonb from public.question_revisions r where r.question_id = 'nruntime-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nruntime-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تشخص أعطال الذاكرة والـ Deadlocks في بيئات الإنتاج بـ Linux باستخدام dotnet-dump و dotnet-trace؟' or l.short_answer is distinct from 'تجمع ملف تفريغ الذاكرة (Memory Dump) بـ dotnet-dump دون إيقاف السيرفر، وتحلله بأوامر SOS مثل dumpheap -stat لتحديد تسريبات الكائنات وأقفال الخيوط.' or l.explanation is distinct from 'في بيئات الحاويات وLinux السحابية، لا يمكنك تشغيل Visual Studio المباشر. توفر مايكروسوفت أدوات تشخيص عالمية عبر مقبس EventPipe. باستخدام dotnet-dump collect -p <pid>، يتم التقاط لقطة ذاكرة كاملة للحاوية، ثم استخدام dotnet-dump analyze لفحص كائنات الـ Managed Heap، ومعرفة الخيوط العالقة في sync-blocks، ومسارات الجذور المسببة للـ Memory Leaks بدقة.' or l.code_example is distinct from '// جمع لقطة تفريغ في بيئة الإنتاج:
// dotnet-dump collect -p 1234
// dotnet-dump analyze core_dump
// > dumpheap -stat
// > clrstack -all' or l.common_mistakes is distinct from '["أخذ ملفات تفريغ ذاكرة كاملة (Full Dumps) في سيرفرات تمتلك مساحات رام هائلة ومساحة قرص محدودة مما يملأ القرص."]'::jsonb or l.follow_up_questions is distinct from '["كيف تسجل مقاييس الأداء الحية للـ GC ومعدلات الاستجابة عبر dotnet-counters monitor؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Diagnostic tools in .NET","url":"https://learn.microsoft.com/en-us/dotnet/core/diagnostics/"}]'::jsonb)) then raise exception 'Question nruntime-010 ar content changed; create a new revision before seeding'; end if; end $$;
