insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل خط أنابيب الـ Middlewares في ASP.NET Core ولماذا يعد ترتيب التسجيل حرجاً للغاية؟', 'ينفذ كل وسيط الكود قبل استدعاء next() ثم ينتظر عودة الاستجابة؛ والترتيب حرج لأن وسيط المصادقة UseAuthentication يجب أن يسبق التفويض UseAuthorization.', 'يتم بناء الـ Pipeline كحلقات دائرية متداخلة من دوال RequestDelegate. إذا عكست الترتيب وجعلت UseAuthorization تسبق UseAuthentication، ستفحص الصلاحيات قبل التحقق من هوية المستخدم وستفشل كل الطلبات برمز 401 أو 403. القاعدة الذهبية هي: معالجة الأخطاء أولاً (UseExceptionHandler)، تليها التوجيه والـ CORS، ثم المصادقة، ثم الصلاحيات، وأخيراً الـ Endpoints.', 'app.UseExceptionHandler("/error");
app.UseRouting();
app.UseCors();
app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();', '["وضع app.UseCors() في نهاية الـ pipeline بعد التوجيه والمصادقة مما يمنع إرسال ترويسات CORS في حالات أخطاء المصادقة."]'::jsonb, '["ما الفرق بين app.Use() و app.Run() في تسجيل الـ Middlewares؟"]'::jsonb, '[{"title":"Microsoft Learn — ASP.NET Core Middleware","url":"https://learn.microsoft.com/en-us/aspnet/core/fundamentals/middleware/"}]'::jsonb from public.question_revisions r where r.question_id = 'nasp-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasp-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل خط أنابيب الـ Middlewares في ASP.NET Core ولماذا يعد ترتيب التسجيل حرجاً للغاية؟' or l.short_answer is distinct from 'ينفذ كل وسيط الكود قبل استدعاء next() ثم ينتظر عودة الاستجابة؛ والترتيب حرج لأن وسيط المصادقة UseAuthentication يجب أن يسبق التفويض UseAuthorization.' or l.explanation is distinct from 'يتم بناء الـ Pipeline كحلقات دائرية متداخلة من دوال RequestDelegate. إذا عكست الترتيب وجعلت UseAuthorization تسبق UseAuthentication، ستفحص الصلاحيات قبل التحقق من هوية المستخدم وستفشل كل الطلبات برمز 401 أو 403. القاعدة الذهبية هي: معالجة الأخطاء أولاً (UseExceptionHandler)، تليها التوجيه والـ CORS، ثم المصادقة، ثم الصلاحيات، وأخيراً الـ Endpoints.' or l.code_example is distinct from 'app.UseExceptionHandler("/error");
app.UseRouting();
app.UseCors();
app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();' or l.common_mistakes is distinct from '["وضع app.UseCors() في نهاية الـ pipeline بعد التوجيه والمصادقة مما يمنع إرسال ترويسات CORS في حالات أخطاء المصادقة."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين app.Use() و app.Run() في تسجيل الـ Middlewares؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — ASP.NET Core Middleware","url":"https://learn.microsoft.com/en-us/aspnet/core/fundamentals/middleware/"}]'::jsonb)) then raise exception 'Question nasp-002 ar content changed; create a new revision before seeding'; end if; end $$;
