insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف صُمم خادم Kestrel ليصبح أحد أسرع خوادم الويب في العالم وما هو الـ Reverse Proxy؟', 'صُمم Kestrel بنظام I/O غير حاجب مبني فوق مسبار المقابس (Socket Pipelines) وذاكرة MemoryPools؛ ويوضع خلف Reverse Proxy (كـ Nginx أو IIS) للحماية وإدارة الـ SSL.', 'يعتمد Kestrel على واجهة System.IO.Pipelines التي تقرأ البيانات مباشرة من مقابس الشبكة إلى كتل ذاكرة مشتركة بدون تخصيص متكرر في الـ Heap. في بنية الإنتاج، يفضل وضع خادم Reverse Proxy أمامه للتعامل مع شهادات SSL، والتحكم في مهل الاتصال البطيئة (Slowloris)، وموازنة الحمل بين نسخ Kestrel المتعددة.', '// تكوين حدود Kestrel في Program.cs
builder.WebHost.ConfigureKestrel(options => {
    options.Limits.MaxConcurrentConnections = 1000;
    options.Limits.MaxRequestBodySize = 10 * 1024 * 1024; // 10MB
});', '["كشف Kestrel مباشرة للإنترنت دون ضبط حدود حجم الطلبات ومهل الاتصالات الأمنية."]'::jsonb, '["ما أهمية استخدام app.UseForwardedHeaders() عند تشغيل Kestrel خلف Nginx أو AWS ALB؟"]'::jsonb, '[{"title":"Microsoft Learn — Kestrel web server implementation in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/fundamentals/servers/kestrel"}]'::jsonb from public.question_revisions r where r.question_id = 'nasp-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasp-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف صُمم خادم Kestrel ليصبح أحد أسرع خوادم الويب في العالم وما هو الـ Reverse Proxy؟' or l.short_answer is distinct from 'صُمم Kestrel بنظام I/O غير حاجب مبني فوق مسبار المقابس (Socket Pipelines) وذاكرة MemoryPools؛ ويوضع خلف Reverse Proxy (كـ Nginx أو IIS) للحماية وإدارة الـ SSL.' or l.explanation is distinct from 'يعتمد Kestrel على واجهة System.IO.Pipelines التي تقرأ البيانات مباشرة من مقابس الشبكة إلى كتل ذاكرة مشتركة بدون تخصيص متكرر في الـ Heap. في بنية الإنتاج، يفضل وضع خادم Reverse Proxy أمامه للتعامل مع شهادات SSL، والتحكم في مهل الاتصال البطيئة (Slowloris)، وموازنة الحمل بين نسخ Kestrel المتعددة.' or l.code_example is distinct from '// تكوين حدود Kestrel في Program.cs
builder.WebHost.ConfigureKestrel(options => {
    options.Limits.MaxConcurrentConnections = 1000;
    options.Limits.MaxRequestBodySize = 10 * 1024 * 1024; // 10MB
});' or l.common_mistakes is distinct from '["كشف Kestrel مباشرة للإنترنت دون ضبط حدود حجم الطلبات ومهل الاتصالات الأمنية."]'::jsonb or l.follow_up_questions is distinct from '["ما أهمية استخدام app.UseForwardedHeaders() عند تشغيل Kestrel خلف Nginx أو AWS ALB؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Kestrel web server implementation in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/fundamentals/servers/kestrel"}]'::jsonb)) then raise exception 'Question nasp-003 ar content changed; create a new revision before seeding'; end if; end $$;
