insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق وسيط تحديد معدل الطلبات المدمج (Rate Limiting Middleware) في .NET 7+؟', 'باستخدام builder.Services.AddRateLimiter وضبط خوارزميات مثل FixedWindow أو SlidingWindow أو TokenBucket وتطبيقها بـ [EnableRateLimiting].', 'أضافت .NET وسيطاً أصيلاً شديد القوة لتحديد معدل الطلبات دون الحاجة لمكتبات طرف ثالث. يدعم خوارزميات متعددة: Fixed Window لنافذة ثابتة، Sliding Window لنافذة متحركة تمنع الهجمات عند حواف الدقائق، Token Bucket للسماح بدفقات سريعة من الطلبات (Bursts)، وConcurrency Limiter لقصر عدد الاتصالات المفتوحة في نفس اللحظة.', 'builder.Services.AddRateLimiter(options => {
    options.AddFixedWindowLimiter("fixed", opt => {
        opt.PermitLimit = 100;
        opt.Window = TimeSpan.FromMinutes(1);
    });
});
app.UseRateLimiter();', '["عدم تخصيص OnRejected Handler لإرجاع استجابة JSON مهيكلة وترويسة Retry-After واضحة عند حظر العميل برمز 429."]'::jsonb, '["كيف تبني PartitionedRateLimiter يقيد الطلبات بحسب معرّف المستخدم أو عنوان IP العميل؟"]'::jsonb, '[{"title":"Microsoft Learn — Rate limiting middleware in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/performance/rate-limit"}]'::jsonb from public.question_revisions r where r.question_id = 'nasp-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
