insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يتفوق وسيط Output Caching في .NET 7+ على وسيط Response Caching القديم؟', 'يخزن الاستجابات بالكامل في ذاكرة الخادم أو Redis ويدعم إبطال الكاش بالوسوم (Tags) والتأمين بقفل لمنع الـ Stampede، بينما القديم يقتصر على ترويسات العميل فقط.', 'وسيط ResponseCaching القديم كان يعتمد حصراً على ترويسات المتصفح ولا يوفر أي وسيلة للمطور لإبطال الكاش برمجياً عند تعديل البيانات. وسيط OutputCaching الحديث يوفر تحكماً خادومياً مطلقاً؛ فيمكنك وسوم المسار بـ Tag(''products'') وعند تحديث أي منتج تستدعي IOutputCacheStore.EvictByTagAsync(''products'') لإبطال كل الاستجابات المخزنة فوراً مع دعم ميزة Locking التلقائية لمنع تدافع الطلبات.', 'app.MapGet("/products", async (IProductService s) => await s.GetAllAsync())
   .CacheOutput(p => p.Expire(TimeSpan.FromHours(1)).Tag("products"));', '["تفعيل Output Caching على مسارات تتطلب مصادقة المستخدم دون تضمين الـ User ID في مفتاح التخزين عبر VaryByValue."]'::jsonb, '["كيف توجه Output Caching لاستخدام مخزن Redis موزع لمشاركة الاستجابات عبر خوادم متعددة؟"]'::jsonb, '[{"title":"Microsoft Learn — Output caching middleware in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/performance/caching/output"}]'::jsonb from public.question_revisions r where r.question_id = 'nasp-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasp-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يتفوق وسيط Output Caching في .NET 7+ على وسيط Response Caching القديم؟' or l.short_answer is distinct from 'يخزن الاستجابات بالكامل في ذاكرة الخادم أو Redis ويدعم إبطال الكاش بالوسوم (Tags) والتأمين بقفل لمنع الـ Stampede، بينما القديم يقتصر على ترويسات العميل فقط.' or l.explanation is distinct from 'وسيط ResponseCaching القديم كان يعتمد حصراً على ترويسات المتصفح ولا يوفر أي وسيلة للمطور لإبطال الكاش برمجياً عند تعديل البيانات. وسيط OutputCaching الحديث يوفر تحكماً خادومياً مطلقاً؛ فيمكنك وسوم المسار بـ Tag(''products'') وعند تحديث أي منتج تستدعي IOutputCacheStore.EvictByTagAsync(''products'') لإبطال كل الاستجابات المخزنة فوراً مع دعم ميزة Locking التلقائية لمنع تدافع الطلبات.' or l.code_example is distinct from 'app.MapGet("/products", async (IProductService s) => await s.GetAllAsync())
   .CacheOutput(p => p.Expire(TimeSpan.FromHours(1)).Tag("products"));' or l.common_mistakes is distinct from '["تفعيل Output Caching على مسارات تتطلب مصادقة المستخدم دون تضمين الـ User ID في مفتاح التخزين عبر VaryByValue."]'::jsonb or l.follow_up_questions is distinct from '["كيف توجه Output Caching لاستخدام مخزن Redis موزع لمشاركة الاستجابات عبر خوادم متعددة؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Output caching middleware in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/performance/caching/output"}]'::jsonb)) then raise exception 'Question nasp-009 ar content changed; create a new revision before seeding'; end if; end $$;
