insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تنفذ المهام الخلفية المستمرة باستخدام فئة BackgroundService وما مخاطر حقن الخدمات الـ Scoped بداخلها؟', 'تنفذ بالوراثة من BackgroundService وكتابة المنطق داخل ExecuteAsync()؛ ولا يمكن حقن الخدمات الـ Scoped فيها مباشرة لأنها Singleton ويجب إنشاء نطاق يدوياً عبر IServiceScopeFactory.', 'فئة BackgroundService هي الطريقة القياسية لتشغيل مهام طويلة الأمد (مثل سحب رسائل من طابور أو معالجة دورية). نظراً لأن الـ BackgroundService تسجل كـ Singleton طوال عمر التطبيق، فإن حقن DbContext (وهو Scoped) في الباني سيرمي خطأ InvalidOperationException. الحل الصحيح هو حقن IServiceScopeFactory وإنشاء نطاق يدوي using (var scope = _scopeFactory.CreateScope()) داخل كل دورة.', 'public class QueueConsumer(IServiceScopeFactory scopeFactory) : BackgroundService {
    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            using var scope = scopeFactory.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            await db.ProcessPendingOrdersAsync(stoppingToken);
            await Task.Delay(5000, stoppingToken);
        }
    }
}', '["تجاهل CancellationToken stoppingToken مما يمنع التطبيق من إتمام عملية الإغلاق النظيف (Graceful Shutdown) عند استلام إشارة التوقف."]'::jsonb, '["ما الفرق بين واجهة IHostedService الأساسية والفئة المجردة BackgroundService؟"]'::jsonb, '[{"title":"Microsoft Learn — Background tasks with hosted services in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/fundamentals/host/hosted-services"}]'::jsonb from public.question_revisions r where r.question_id = 'nasp-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasp-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تنفذ المهام الخلفية المستمرة باستخدام فئة BackgroundService وما مخاطر حقن الخدمات الـ Scoped بداخلها؟' or l.short_answer is distinct from 'تنفذ بالوراثة من BackgroundService وكتابة المنطق داخل ExecuteAsync()؛ ولا يمكن حقن الخدمات الـ Scoped فيها مباشرة لأنها Singleton ويجب إنشاء نطاق يدوياً عبر IServiceScopeFactory.' or l.explanation is distinct from 'فئة BackgroundService هي الطريقة القياسية لتشغيل مهام طويلة الأمد (مثل سحب رسائل من طابور أو معالجة دورية). نظراً لأن الـ BackgroundService تسجل كـ Singleton طوال عمر التطبيق، فإن حقن DbContext (وهو Scoped) في الباني سيرمي خطأ InvalidOperationException. الحل الصحيح هو حقن IServiceScopeFactory وإنشاء نطاق يدوي using (var scope = _scopeFactory.CreateScope()) داخل كل دورة.' or l.code_example is distinct from 'public class QueueConsumer(IServiceScopeFactory scopeFactory) : BackgroundService {
    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            using var scope = scopeFactory.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            await db.ProcessPendingOrdersAsync(stoppingToken);
            await Task.Delay(5000, stoppingToken);
        }
    }
}' or l.common_mistakes is distinct from '["تجاهل CancellationToken stoppingToken مما يمنع التطبيق من إتمام عملية الإغلاق النظيف (Graceful Shutdown) عند استلام إشارة التوقف."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين واجهة IHostedService الأساسية والفئة المجردة BackgroundService؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Background tasks with hosted services in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/fundamentals/host/hosted-services"}]'::jsonb)) then raise exception 'Question nasp-010 ar content changed; create a new revision before seeding'; end if; end $$;
