insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين فترات حياة الخدمات (Lifetimes): Transient و Scoped و Singleton في .NET؟', 'Transient تنشئ نسخة جديدة مع كل طلب حقن، وScoped تنشئ نسخة واحدة لكل طلب HTTP تشترك فيها كل المكونات، وSingleton تنشئ نسخة واحدة للأبد تشاركها كامل العملية.', 'تعد إدارة فترات الحياة الركيزة الأساسية للـ Dependency Injection. استخدم Transient للخدمات الخفيفة عديمة الحالة. استخدم Scoped للخدمات التي تحتفظ بحالة الطلب الحالي أو تتشارك سياقاً مثل Entity Framework DbContext. استخدم Singleton للخدمات باهظة الإنشاء التي تحتفظ بذاكرة كاش مشتركة أو تدير مقابس شبكة دائمة.', 'builder.Services.AddTransient<IEmailSender, EmailSender>();
builder.Services.AddScoped<IOrderService, OrderService>();
builder.Services.AddSingleton<ICacheManager, MemoryCacheManager>();', '["حقن خدمة Scoped داخل خدمة Singleton مما يخلق خطأ Captive Dependency الكارثي."]'::jsonb, '["ما هو خطأ Captive Dependency وكيف تفعله .NET تلقائياً في بيئة التطوير عبر ValidateScopes؟"]'::jsonb, '[{"title":"Microsoft Learn — Dependency injection in .NET","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection"}]'::jsonb from public.question_revisions r where r.question_id = 'ndi-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ndi-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الجوهري بين فترات حياة الخدمات (Lifetimes): Transient و Scoped و Singleton في .NET؟' or l.short_answer is distinct from 'Transient تنشئ نسخة جديدة مع كل طلب حقن، وScoped تنشئ نسخة واحدة لكل طلب HTTP تشترك فيها كل المكونات، وSingleton تنشئ نسخة واحدة للأبد تشاركها كامل العملية.' or l.explanation is distinct from 'تعد إدارة فترات الحياة الركيزة الأساسية للـ Dependency Injection. استخدم Transient للخدمات الخفيفة عديمة الحالة. استخدم Scoped للخدمات التي تحتفظ بحالة الطلب الحالي أو تتشارك سياقاً مثل Entity Framework DbContext. استخدم Singleton للخدمات باهظة الإنشاء التي تحتفظ بذاكرة كاش مشتركة أو تدير مقابس شبكة دائمة.' or l.code_example is distinct from 'builder.Services.AddTransient<IEmailSender, EmailSender>();
builder.Services.AddScoped<IOrderService, OrderService>();
builder.Services.AddSingleton<ICacheManager, MemoryCacheManager>();' or l.common_mistakes is distinct from '["حقن خدمة Scoped داخل خدمة Singleton مما يخلق خطأ Captive Dependency الكارثي."]'::jsonb or l.follow_up_questions is distinct from '["ما هو خطأ Captive Dependency وكيف تفعله .NET تلقائياً في بيئة التطوير عبر ValidateScopes؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Dependency injection in .NET","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection"}]'::jsonb)) then raise exception 'Question ndi-001 ar content changed; create a new revision before seeding'; end if; end $$;
