insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي تبعية الأسير (Captive Dependency) في حاوية الـ DI بـ .NET وكيف تكتشفها وتمنعها؟', 'تحدث عندما تُحقن خدمة ذات نطاق أقصر (مثل Scoped) داخل خدمة ذات نطاق أطول (مثل Singleton)، مما يحبس النسخة الـ Scoped في الذاكرة للأبد ويمنع تنظيفها.', 'إذا قمت بحقن DbContext (وهو Scoped) داخل فئة CacheService (وهي Singleton)، سيظل نفس كائن الـ DbContext حياً طوال عمر التطبيق ولن يتم استدعاء Dispose عليه مطلقاً. هذا يؤدي لتضخم الذاكرة (Memory Leak) ومحاولة استخدام نفس الاتصال عبر خيوط متزامنة مما يرمي أخطاء Concurrency. توفر .NET خيار ValidateScopes الذي يرمي استثناء فورياً عند الإقلاع في بيئة Development إذا وجد هذه التبعية.', '// مفعل تلقائياً في Development:
builder.Host.UseDefaultServiceProvider(options => {
    options.ValidateScopes = true;
    options.ValidateOnBuild = true;
});', '["تعطيل ValidateScopes في بيئة التطوير لتجاوز الخطأ بدلاً من إصلاح التبعيات."]'::jsonb, '["كيف تحل الحاجة لاستخدام خدمة Scoped داخل Singleton بأمان باستخدام IServiceScopeFactory؟"]'::jsonb, '[{"title":"Microsoft Learn — Dependency injection guidelines: Captive dependencies","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection-guidelines#captive-dependency"}]'::jsonb from public.question_revisions r where r.question_id = 'ndi-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ndi-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي تبعية الأسير (Captive Dependency) في حاوية الـ DI بـ .NET وكيف تكتشفها وتمنعها؟' or l.short_answer is distinct from 'تحدث عندما تُحقن خدمة ذات نطاق أقصر (مثل Scoped) داخل خدمة ذات نطاق أطول (مثل Singleton)، مما يحبس النسخة الـ Scoped في الذاكرة للأبد ويمنع تنظيفها.' or l.explanation is distinct from 'إذا قمت بحقن DbContext (وهو Scoped) داخل فئة CacheService (وهي Singleton)، سيظل نفس كائن الـ DbContext حياً طوال عمر التطبيق ولن يتم استدعاء Dispose عليه مطلقاً. هذا يؤدي لتضخم الذاكرة (Memory Leak) ومحاولة استخدام نفس الاتصال عبر خيوط متزامنة مما يرمي أخطاء Concurrency. توفر .NET خيار ValidateScopes الذي يرمي استثناء فورياً عند الإقلاع في بيئة Development إذا وجد هذه التبعية.' or l.code_example is distinct from '// مفعل تلقائياً في Development:
builder.Host.UseDefaultServiceProvider(options => {
    options.ValidateScopes = true;
    options.ValidateOnBuild = true;
});' or l.common_mistakes is distinct from '["تعطيل ValidateScopes في بيئة التطوير لتجاوز الخطأ بدلاً من إصلاح التبعيات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحل الحاجة لاستخدام خدمة Scoped داخل Singleton بأمان باستخدام IServiceScopeFactory؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Dependency injection guidelines: Captive dependencies","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection-guidelines#captive-dependency"}]'::jsonb)) then raise exception 'Question ndi-002 ar content changed; create a new revision before seeding'; end if; end $$;
