insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'من المسؤول عن استدعاء دالة Dispose() للخدمات التي تطبق IDisposable عند استخدام حاوية .NET DI؟', 'حاوية الـ DI هي المسؤولة حصراً عن استدعاء Dispose() تلقائياً لجميع الخدمات التي أنشأتها هي، عند انتهاء فترة حياة النطاق (Scope) أو انتهاء التطبيق للـ Singletons.', 'قاعدة أساسية: من يُنشئ المورد هو من ينظفه. إذا قامت الحاوية بإنشاء خدمة Scoped تطبق IDisposable، ستقوم الحاوية تلقائياً باستدعاء Dispose() عليها فور اكتمال طلب الـ HTTP وتدمير النطاق. استثناء وحيد خطير: إذا قمت بتسجيل نسخة جاهزة مسبقاً بنفسك عبر services.AddSingleton(new MyService())، فإن الحاوية لن تستدعي Dispose() عليها ويجب عليك تنظيفها يدوياً.', '// الحاوية تنشئ الكائن وستستدعي Dispose() تلقائياً:
builder.Services.AddScoped<MyDisposableService>();

// الحاوية لا تمتلك النسخة ولن تستدعي Dispose():
builder.Services.AddSingleton(new MyDisposableService());', '["استدعاء دالة Dispose() يدوياً داخل كود المتحكم لخدمة تم حقنها بواسطة الـ DI Container."]'::jsonb, '["كيف تتعامل الحاوية مع الخدمات التي تطبق واجهة IAsyncDisposable عند إغلاق النطاق؟"]'::jsonb, '[{"title":"Microsoft Learn — Disposal of services in dependency injection","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection-guidelines#disposal-of-services"}]'::jsonb from public.question_revisions r where r.question_id = 'ndi-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ndi-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'من المسؤول عن استدعاء دالة Dispose() للخدمات التي تطبق IDisposable عند استخدام حاوية .NET DI؟' or l.short_answer is distinct from 'حاوية الـ DI هي المسؤولة حصراً عن استدعاء Dispose() تلقائياً لجميع الخدمات التي أنشأتها هي، عند انتهاء فترة حياة النطاق (Scope) أو انتهاء التطبيق للـ Singletons.' or l.explanation is distinct from 'قاعدة أساسية: من يُنشئ المورد هو من ينظفه. إذا قامت الحاوية بإنشاء خدمة Scoped تطبق IDisposable، ستقوم الحاوية تلقائياً باستدعاء Dispose() عليها فور اكتمال طلب الـ HTTP وتدمير النطاق. استثناء وحيد خطير: إذا قمت بتسجيل نسخة جاهزة مسبقاً بنفسك عبر services.AddSingleton(new MyService())، فإن الحاوية لن تستدعي Dispose() عليها ويجب عليك تنظيفها يدوياً.' or l.code_example is distinct from '// الحاوية تنشئ الكائن وستستدعي Dispose() تلقائياً:
