insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يعد نمط Service Locator (حقن IServiceProvider مباشرة) نمطاً مضاداً (Anti-pattern) في C#؟', 'لأنه يخفي التبعيات الحقيقية للفئة، ويعطل فحص المترجم الساكن، ويصعب كتابة اختبارات الوحدة، وقد يؤدي لأخطاء وقت التشغيل عند طلب خدمات غير مسجلة.', 'عندما تطلب الفئة IServiceProvider في الباني، لا يعلم المطور الخارجي ما هي التبعيات الفعلية التي تحتاجها الفئة لتعمل، ويفشل فحص التبعيات عند الإنشاء. الممارسة الهندسية الصحيحة هي التصريح الصريح عن كل التبعيات في الباني (Constructor Injection)، مما يجعل الفئة ذات مسؤولية واضحة ويسهل استبدال التبعيات بـ Mocks في اختبارات الوحدة.', '// نمط مضاد سيء (Service Locator):
public class OrderService(IServiceProvider provider) {
    public void Process() {
        var repo = provider.GetRequiredService<IOrderRepo>(); // تبعية مخفية!
    }
}

// الطريقة الصحيحة الصريحة (Constructor Injection):
public class OrderService(IOrderRepo repo) { ... }', '["حقن IServiceProvider لتفادي كتابة 5 معاملات في الباني، بدلاً من إدراك أن الفئة متضخمة وتنتهك مبدأ Single Responsibility."]'::jsonb, '["متى يكون استخدام IServiceProvider مبرراً ومقبولاً (مثلاً في مصانع الفئات المتقدمة أو Middleware Invoke)؟"]'::jsonb, '[{"title":"Microsoft Learn — Dependency injection guidelines: Service locator","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection-guidelines"}]'::jsonb from public.question_revisions r where r.question_id = 'ndi-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
