insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى تلجأ لاستبدال الحاوية المدمجة في .NET بحاوية متقدمة مثل Autofac؟', 'عند الحاجة لميزات متقدمة غير مدعومة أصلياً مثل Property Injection، والـ Interception للبرمجة الموجهة للجوانب (AOP)، والنطاقات المخصصة المعقدة.', 'صُممت حاوية .NET الافتراضية (Microsoft.Extensions.DependencyInjection) لتكون خفيفة وسريعة وتغطي 95% من الاحتياجات الشائعة. إذا كان مشروعك يتطلب حقن الخصائص تلقائياً، أو اعتراض الاستدعاءات ديناميكياً لتطبيق الكاش والتسجيل (AOP Interception)، أو تنظيم الخدمات بنظام Autofac Modules، يمكنك استبدال موفر الخدمات بسهولة عبر builder.Host.UseServiceProviderFactory(new AutofacServiceProviderFactory()).', '// دمج Autofac في Host
builder.Host.UseServiceProviderFactory(new AutofacServiceProviderFactory());
builder.Host.ConfigureContainer<ContainerBuilder>(container => {
    container.RegisterModule(new ApplicationModule());
});', '["الانتقال لحاوية خارجية معقدة لمجرد التعود عليها في مشاريع سابقة دون وجود متطلب حقيقي يبرر التكلفة الإضافية."]'::jsonb, '["ما هو العبء الأدائي لاستخدام حزم الـ Dynamic Interception في حاويات مثل Autofac؟"]'::jsonb, '[{"title":"Microsoft Learn — Dependency injection: Third-party containers","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection"}]'::jsonb from public.question_revisions r where r.question_id = 'ndi-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
