insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل متبع التغييرات (Change Tracker) في EF Core ولماذا يجب استخدام AsNoTracking() لاستعلامات القراءة؟', 'يحتفظ الـ Change Tracker بنسخة من الكائنات في الذاكرة لمراقبة تعديلاتها وحفظها بـ SaveChanges()؛ وAsNoTracking يلغي هذه المراقبة مما يوفر الذاكرة ويسرع استعلامات القراءة بشكل ضخم.', 'عند تنفيذ أي استعلام عادي في EF Core، يقوم المحرك بإنشاء كائن ومطابقته بلقطة أصلية (Snapshot) في ذاكرة الـ DbContext لمراقبة أي تغيير يطرأ على الخصائص. في استعلامات القراءة فقط (مثل واجهات العرض والـ APIs)، لا توجد نية لتعديل البيانات وحفظها، لذا فإن استخدام .AsNoTracking() يمنع إنشاء لقطات التتبع، مما يخفض استهلاك الـ RAM ويسرع زمن الاستعلام بنسبة تفوق 40%.', '// استعلام قراءة فائق السرعة دون حجز ذاكرة تتبع
var users = await dbContext.Users
    .AsNoTracking()
    .Where(u => u.IsActive)
    .ToListAsync();', '["استدعاء AsNoTracking() على كائن ترغب في تعديله ثم التساؤل عن سبب عدم حفظ التغييرات عند استدعاء SaveChangesAsync()."]'::jsonb, '["كيف تضبط سلوك عدم التتبع كافتراضي لكامل سياق قاعدة البيانات عبر QueryTrackingBehavior.NoTracking؟"]'::jsonb, '[{"title":"Microsoft Learn — Tracking vs. No-Tracking Queries in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/querying/tracking"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nef-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل متبع التغييرات (Change Tracker) في EF Core ولماذا يجب استخدام AsNoTracking() لاستعلامات القراءة؟' or l.short_answer is distinct from 'يحتفظ الـ Change Tracker بنسخة من الكائنات في الذاكرة لمراقبة تعديلاتها وحفظها بـ SaveChanges()؛ وAsNoTracking يلغي هذه المراقبة مما يوفر الذاكرة ويسرع استعلامات القراءة بشكل ضخم.' or l.explanation is distinct from 'عند تنفيذ أي استعلام عادي في EF Core، يقوم المحرك بإنشاء كائن ومطابقته بلقطة أصلية (Snapshot) في ذاكرة الـ DbContext لمراقبة أي تغيير يطرأ على الخصائص. في استعلامات القراءة فقط (مثل واجهات العرض والـ APIs)، لا توجد نية لتعديل البيانات وحفظها، لذا فإن استخدام .AsNoTracking() يمنع إنشاء لقطات التتبع، مما يخفض استهلاك الـ RAM ويسرع زمن الاستعلام بنسبة تفوق 40%.' or l.code_example is distinct from '// استعلام قراءة فائق السرعة دون حجز ذاكرة تتبع
var users = await dbContext.Users
    .AsNoTracking()
    .Where(u => u.IsActive)
    .ToListAsync();' or l.common_mistakes is distinct from '["استدعاء AsNoTracking() على كائن ترغب في تعديله ثم التساؤل عن سبب عدم حفظ التغييرات عند استدعاء SaveChangesAsync()."]'::jsonb or l.follow_up_questions is distinct from '["كيف تضبط سلوك عدم التتبع كافتراضي لكامل سياق قاعدة البيانات عبر QueryTrackingBehavior.NoTracking؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Tracking vs. No-Tracking Queries in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/querying/tracking"}]'::jsonb)) then raise exception 'Question nef-001 ar content changed; create a new revision before seeding'; end if; end $$;
