insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مشكلة الـ Cartesian Explosion عند تضمين عدة علاقات بـ Include وكيف تحلها تقنية Split Queries؟', 'تحدث عندما يُولد Include المتعدد استعلام JOIN عملاقاً يضاعف الصفوف المسترجعة بشكل أسي؛ وتحلها AsSplitQuery() بتقسيم الاستعلام إلى استعلامات SQL منفصلة لكل علاقة.', 'إذا كان لدى المدونة مقالات، وكل مقال يحتوي تعليقات ووسوماً، فإن استعلام .Include(p => p.Comments).Include(p => p.Tags) يولد استعلام SQL واحد يحتوي على عدة LEFT JOINs. إذا كان للمقال 20 تعليقاً و10 وسوم، سيعيد خادم SQL عدد 200 صف لنفس المقال مكرراً نصوصه (انفجار ديكارتي). ميزة AsSplitQuery() تفصل العملية لاستعلامات مستقلة تجلب المقالات، ثم التعليقات، ثم الوسوم، وتجمعها في الذاكرة بكفاءة وأمان.', 'var blogs = await dbContext.Blogs
    .Include(b => b.Posts)
        .ThenInclude(p => p.Comments)
    .AsSplitQuery() // يمنع الانفجار الديكارتي ويسرع الشبكة
    .ToListAsync();', '["استخدام AsSplitQuery دون التأكد من أن قاعدة البيانات تدعم التناسق أو في حالات غياب المعاملات عند تحديث البيانات أثناء القراءة."]'::jsonb, '["كيف تفعل Split Queries كإعداد افتراضي لكامل الـ DbContext؟"]'::jsonb, '[{"title":"Microsoft Learn — Single vs. Split Queries in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/querying/single-split-queries"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
