insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا لا يعد DbContext آمناً للخيوط المتزامنة (Not Thread-Safe) وما هي ميزة DbContext Pooling؟', 'لا يمكن استخدام نفس نسخة DbContext في عمليتين غير متزامنتين معاً في نفس اللحظة؛ وميزة AddDbContextPool تعيد استخدام نسخ السياق المفتوحة مسبقاً لتوفير كلفة إنشائها المتكرر.', 'الـ DbContext يحتفظ بحالة اتصال ومتبع تغييرات غير محمي بأقفال متزامنة. إذا حاولت تشغيل استعلامين بـ Task.WhenAll(db.Users.ToListAsync(), db.Orders.ToListAsync()) على نفس النسخة، سيرمي EF Core خطأ فورياً. ميزة AddDbContextPool تحتفظ بحمام نُسخ مفحوصة ومنظفة من الـ DbContext وتعيد تدويرها بين طلبات الـ HTTP، مما يرفع كفاءة معالجة الطلبات في الثانية بنسبة ملحوظة.', '// تفعيل حمام DbContext
builder.Services.AddDbContextPool<AppDbContext>(options =>
    options.UseSqlServer(connectionString));', '["مشاركة نسخة واحدة من DbContext عبر عدة خيوط متزامنة أو تخزينها كـ Singleton."]'::jsonb, '["ما الشروط الواجب توفرها في فئة DbContext لتكون متوافقة مع الـ DbContext Pooling (مثل عدم الاحتفاظ بحالة داخلية خاصة)؟"]'::jsonb, '[{"title":"Microsoft Learn — DbContext Pooling","url":"https://learn.microsoft.com/en-us/ef/core/performance/advanced-performance-topics#dbcontext-pooling"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nef-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا لا يعد DbContext آمناً للخيوط المتزامنة (Not Thread-Safe) وما هي ميزة DbContext Pooling؟' or l.short_answer is distinct from 'لا يمكن استخدام نفس نسخة DbContext في عمليتين غير متزامنتين معاً في نفس اللحظة؛ وميزة AddDbContextPool تعيد استخدام نسخ السياق المفتوحة مسبقاً لتوفير كلفة إنشائها المتكرر.' or l.explanation is distinct from 'الـ DbContext يحتفظ بحالة اتصال ومتبع تغييرات غير محمي بأقفال متزامنة. إذا حاولت تشغيل استعلامين بـ Task.WhenAll(db.Users.ToListAsync(), db.Orders.ToListAsync()) على نفس النسخة، سيرمي EF Core خطأ فورياً. ميزة AddDbContextPool تحتفظ بحمام نُسخ مفحوصة ومنظفة من الـ DbContext وتعيد تدويرها بين طلبات الـ HTTP، مما يرفع كفاءة معالجة الطلبات في الثانية بنسبة ملحوظة.' or l.code_example is distinct from '// تفعيل حمام DbContext
builder.Services.AddDbContextPool<AppDbContext>(options =>
    options.UseSqlServer(connectionString));' or l.common_mistakes is distinct from '["مشاركة نسخة واحدة من DbContext عبر عدة خيوط متزامنة أو تخزينها كـ Singleton."]'::jsonb or l.follow_up_questions is distinct from '["ما الشروط الواجب توفرها في فئة DbContext لتكون متوافقة مع الـ DbContext Pooling (مثل عدم الاحتفاظ بحالة داخلية خاصة)؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — DbContext Pooling","url":"https://learn.microsoft.com/en-us/ef/core/performance/advanced-performance-topics#dbcontext-pooling"}]'::jsonb)) then raise exception 'Question nef-003 ar content changed; create a new revision before seeding'; end if; end $$;
