insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق مرشحات الاستعلام العامة (Global Query Filters) لتنفيذ الحذف اللين والـ Multi-Tenancy في EF Core؟', 'بتعريف شرط بـ HasQueryFilter داخل OnModelCreating يدمج شرط WHERE تلقائياً في كل استعلامات النموذج ما لم يُعطل بـ IgnoreQueryFilters().', 'تضمن Global Query Filters عدم نسيان شرط الأمان أو الحذف اللين في أي مكان في التطبيق. بتحديد modelBuilder.Entity<Order>().HasQueryFilter(o => !o.IsDeleted && o.TenantId == _tenantId)، يضمن EF Core أن كل استعلام SELECT (بما في ذلك العلاقات عبر Include) سيحتوي تلقائياً على هذه الشروط، مانعاً تسريب بيانات مستأجر لآخر.', 'protected override void OnModelCreating(ModelBuilder modelBuilder) {
    modelBuilder.Entity<User>()
        .HasQueryFilter(u => !u.IsDeleted);
}
// لطلب المحذوفات عمداً:
var allUsers = await db.Users.IgnoreQueryFilters().ToListAsync();', '["عدم توفير فهارس مركبة تشمل أعمدة الـ Query Filters (مثل IsDeleted و TenantId) مما يبطئ كل استعلامات النظام."]'::jsonb, '["كيف تتأكد من أن التنقل بين المستأجرين (Tenant Change) يحدث بأمان داخل DbContext ذي النطاق المشترك؟"]'::jsonb, '[{"title":"Microsoft Learn — Global Query Filters in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/querying/filters"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nef-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق مرشحات الاستعلام العامة (Global Query Filters) لتنفيذ الحذف اللين والـ Multi-Tenancy في EF Core؟' or l.short_answer is distinct from 'بتعريف شرط بـ HasQueryFilter داخل OnModelCreating يدمج شرط WHERE تلقائياً في كل استعلامات النموذج ما لم يُعطل بـ IgnoreQueryFilters().' or l.explanation is distinct from 'تضمن Global Query Filters عدم نسيان شرط الأمان أو الحذف اللين في أي مكان في التطبيق. بتحديد modelBuilder.Entity<Order>().HasQueryFilter(o => !o.IsDeleted && o.TenantId == _tenantId)، يضمن EF Core أن كل استعلام SELECT (بما في ذلك العلاقات عبر Include) سيحتوي تلقائياً على هذه الشروط، مانعاً تسريب بيانات مستأجر لآخر.' or l.code_example is distinct from 'protected override void OnModelCreating(ModelBuilder modelBuilder) {
    modelBuilder.Entity<User>()
        .HasQueryFilter(u => !u.IsDeleted);
}
// لطلب المحذوفات عمداً:
var allUsers = await db.Users.IgnoreQueryFilters().ToListAsync();' or l.common_mistakes is distinct from '["عدم توفير فهارس مركبة تشمل أعمدة الـ Query Filters (مثل IsDeleted و TenantId) مما يبطئ كل استعلامات النظام."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتأكد من أن التنقل بين المستأجرين (Tenant Change) يحدث بأمان داخل DbContext ذي النطاق المشترك؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Global Query Filters in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/querying/filters"}]'::jsonb)) then raise exception 'Question nef-004 ar content changed; create a new revision before seeding'; end if; end $$;
