insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق القفل التفاؤلي (Optimistic Concurrency) وحل التعارضات باستخدام RowVersion في EF Core؟', 'بإضافة خاصية [Timestamp] byte[] RowVersion للنموذج؛ حيث يرفض التحديث ويرمي DbUpdateConcurrencyException إذا قام مستخدم آخر بتعديل السجل أثناء قراءتك له.', 'في القفل التفاؤلي، لا يتم حجز أقفال على قاعدة البيانات أثناء قراءة المستخدم للبيانات. يقوم عمود RowVersion (أو xmin في PostgreSQL) بتوليد قيمة ثنائية جديدة تلقائياً مع كل تعديل للصف. عند الحفظ، ينفذ EF Core استعلام UPDATE ... WHERE Id = @id AND RowVersion = @originalRowVersion. إذا تغيرت البصمة، لا يتأثر أي صف ويرمي EF Core استثناء التعارض لتتمكن من دمج التعديلات أو إشعار المستخدم.', 'public class BankAccount {
    public int Id { get; set; }
    public decimal Balance { get; set; }

    [Timestamp]
    public byte[] RowVersion { get; set; } = null!;
}', '["تجاهل التقاط DbUpdateConcurrencyException مما يؤدي لفقدان بيانات المستخدمين وإعادة الكتابة فوقها (Blind Overwrite)."]'::jsonb, '["كيف تستخدم خاصية entry.OriginalValues و entry.CurrentValues و entry.GetDatabaseValues() لحل التعارض برمجياً؟"]'::jsonb, '[{"title":"Microsoft Learn — Handling Concurrency Conflicts in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/saving/concurrency"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
