insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الاستعلامات المجمعة مسبقاً (Compiled Queries) في EF Core ومتى تستحق استخدامها؟', 'استعلامات تجمع شجرة تعبيرات LINQ إلى دالة مفوضة جاهزة مسبقاً، لتفادي تكلفة تحليل وترجمة LINQ إلى SQL مع كل استدعاء متكرر لنفس المسار.', 'مع أن EF Core يخزن استعلامات SQL الناتجة مؤقتاً، إلا أن مطابقة شجرة LINQ وبناء خطة التنفيذ في كل استدعاء يستهلك وقتاً طفيفاً. باستخدام EF.CompileAsyncQuery()، يتم تجميع الاستعلام مرة واحدة في حقل إستاتيكي، مما يتيح تنفيذه مباشرة بأزمنة استجابة خارقة تضاهي سرعة ميكرو-ORMs مثل Dapper في المسارات الحيوية متكررة الاستدعاء.', 'private static readonly Func<AppDbContext, int, Task<User?>> GetUserCompiled =
    EF.CompileAsyncQuery((AppDbContext db, int id) =>
        db.Users.AsNoTracking().FirstOrDefault(u => u.Id == id));

// الاستخدام الفائق السرعة:
var user = await GetUserCompiled(dbContext, userId);', '["تجميع كل استعلامات التطبيق مسبقاً دون حاجة حقيقية، متناسين تعقيد الكود وعدم الحاجة لذلك إلا في مسارات الـ Hot Paths."]'::jsonb, '["ما القيود البرمجية التي تمنع استخدام Compiled Queries مع استعلامات LINQ الديناميكية متغيرة الشروط؟"]'::jsonb, '[{"title":"Microsoft Learn — Compiled queries in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/performance/advanced-performance-topics#compiled-queries"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
