insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين استراتيجيات الوراثة في EF Core: Table-Per-Hierarchy (TPH) و Table-Per-Type (TPT).', 'TPH تخزن كل الفئات المشتقة في جدول واحد باستخدام عمود تمييز (Discriminator) وهي الأسرع، بينما TPT تنشئ جدولاً لكل فئة فرعية وتربطها بـ JOIN وهي أبطأ في الاستعلامات المعقدة.', 'الاستراتيجية الافتراضية في EF Core هي TPH؛ فإذا كان لديك كلاس أساسي Payment وكلاسين مشتقين CreditCardPayment و PaypalPayment، يتم حفظ الجميع في جدول واحد Payments مع عمود Discriminator يحدد النوع. تتميز TPH بالسرعة القصوى لعدم الحاجة لـ JOINs، ولكن عيبها هو وجود أعمدة فارغة (Nullable). في المقابل، توفر TPT تطبيعاً تاماً لقاعدة البيانات لكنها تتطلب استعلامات JOIN معقدة ومكلفة جداً مع تفرع الوراثة.', '// تكوين TPH الافتراضي الأسرع
modelBuilder.Entity<Payment>()
    .HasDiscriminator<string>("payment_type")
    .HasValue<CreditCardPayment>("credit_card")
    .HasValue<PaypalPayment>("paypal");', '["اختيار TPT في المشاريع الضخمة دون إدراك أن استعلام جلب قائمة الكيانات سينفذ استعلامات JOIN بطيئة جداً عبر عشرات الجداول."]'::jsonb, '["ما هي استراتيجية Table-Per-Concrete-Type (TPC) المضافة في EF Core 7 ومتى تفضلها على TPH؟"]'::jsonb, '[{"title":"Microsoft Learn — Inheritance mapping in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/modeling/inheritance"}]'::jsonb from public.question_revisions r where r.question_id = 'nef-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nef-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين استراتيجيات الوراثة في EF Core: Table-Per-Hierarchy (TPH) و Table-Per-Type (TPT).' or l.short_answer is distinct from 'TPH تخزن كل الفئات المشتقة في جدول واحد باستخدام عمود تمييز (Discriminator) وهي الأسرع، بينما TPT تنشئ جدولاً لكل فئة فرعية وتربطها بـ JOIN وهي أبطأ في الاستعلامات المعقدة.' or l.explanation is distinct from 'الاستراتيجية الافتراضية في EF Core هي TPH؛ فإذا كان لديك كلاس أساسي Payment وكلاسين مشتقين CreditCardPayment و PaypalPayment، يتم حفظ الجميع في جدول واحد Payments مع عمود Discriminator يحدد النوع. تتميز TPH بالسرعة القصوى لعدم الحاجة لـ JOINs، ولكن عيبها هو وجود أعمدة فارغة (Nullable). في المقابل، توفر TPT تطبيعاً تاماً لقاعدة البيانات لكنها تتطلب استعلامات JOIN معقدة ومكلفة جداً مع تفرع الوراثة.' or l.code_example is distinct from '// تكوين TPH الافتراضي الأسرع
modelBuilder.Entity<Payment>()
    .HasDiscriminator<string>("payment_type")
    .HasValue<CreditCardPayment>("credit_card")
    .HasValue<PaypalPayment>("paypal");' or l.common_mistakes is distinct from '["اختيار TPT في المشاريع الضخمة دون إدراك أن استعلام جلب قائمة الكيانات سينفذ استعلامات JOIN بطيئة جداً عبر عشرات الجداول."]'::jsonb or l.follow_up_questions is distinct from '["ما هي استراتيجية Table-Per-Concrete-Type (TPC) المضافة في EF Core 7 ومتى تفضلها على TPH؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Inheritance mapping in EF Core","url":"https://learn.microsoft.com/en-us/ef/core/modeling/inheritance"}]'::jsonb)) then raise exception 'Question nef-010 ar content changed; create a new revision before seeding'; end if; end $$;
