insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين Task<T> و ValueTask<T> ومتى يجب اختيار ValueTask في دوال C#؟', 'الـ Task هو كائن Reference Type يحجز مساحة في الـ Heap مع كل إنشاء، بينما ValueTask هو struct يوفر صفر تخصيص في الذاكرة عندما تكتمل العملية تزامناً من الكاش.', 'في الدوال التي تُستدعى ملايين المرات وتكتمل نتيجتها غالباً من الـ Memory Cache أو Buffer دون انتظار فعلي للشبكة، فإن إرجاع new Task<T>() يولد ملايين الكائنات غير الضرورية في الـ Heap. بنية ValueTask<T> تعالج ذلك؛ فإذا كانت البيانات جاهزة فوراً، تعاد القيمة في الـ Stack بصفر تكلفة للـ GC، ولا يُنشأ كائن Task في الـ Heap إلا عند الانتظار الفعلي للـ I/O غير المتزامن.', 'public ValueTask<string> GetCachedDataAsync(string key) {
    if (_cache.TryGetValue(key, out var val)) {
        return ValueTask.FromResult(val); // صفر حجز في الـ Heap
    }
    return new ValueTask<string>(FetchFromNetworkAsync(key));
}', '["استدعاء await مرتين على نفس كائن ValueTask أو استدعاء .AsTask() دون داعٍ حيث إن ValueTask لا تدعم تكرار الـ await."]'::jsonb, '["لماذا يحظر تخزين ValueTask في متغيرات وانتظارها لاحقاً عبر Task.WhenAll؟"]'::jsonb, '[{"title":"Microsoft Learn — Understanding the Whys, Whats, and Whens of ValueTask","url":"https://learn.microsoft.com/en-us/dotnet/api/system.threading.tasks.valuetask-1"}]'::jsonb from public.question_revisions r where r.question_id = 'nasyncnet-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasyncnet-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين Task<T> و ValueTask<T> ومتى يجب اختيار ValueTask في دوال C#؟' or l.short_answer is distinct from 'الـ Task هو كائن Reference Type يحجز مساحة في الـ Heap مع كل إنشاء، بينما ValueTask هو struct يوفر صفر تخصيص في الذاكرة عندما تكتمل العملية تزامناً من الكاش.' or l.explanation is distinct from 'في الدوال التي تُستدعى ملايين المرات وتكتمل نتيجتها غالباً من الـ Memory Cache أو Buffer دون انتظار فعلي للشبكة، فإن إرجاع new Task<T>() يولد ملايين الكائنات غير الضرورية في الـ Heap. بنية ValueTask<T> تعالج ذلك؛ فإذا كانت البيانات جاهزة فوراً، تعاد القيمة في الـ Stack بصفر تكلفة للـ GC، ولا يُنشأ كائن Task في الـ Heap إلا عند الانتظار الفعلي للـ I/O غير المتزامن.' or l.code_example is distinct from 'public ValueTask<string> GetCachedDataAsync(string key) {
    if (_cache.TryGetValue(key, out var val)) {
        return ValueTask.FromResult(val); // صفر حجز في الـ Heap
    }
    return new ValueTask<string>(FetchFromNetworkAsync(key));
}' or l.common_mistakes is distinct from '["استدعاء await مرتين على نفس كائن ValueTask أو استدعاء .AsTask() دون داعٍ حيث إن ValueTask لا تدعم تكرار الـ await."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يحظر تخزين ValueTask في متغيرات وانتظارها لاحقاً عبر Task.WhenAll؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Understanding the Whys, Whats, and Whens of ValueTask","url":"https://learn.microsoft.com/en-us/dotnet/api/system.threading.tasks.valuetask-1"}]'::jsonb)) then raise exception 'Question nasyncnet-001 ar content changed; create a new revision before seeding'; end if; end $$;
