insert into public.interview_questions (id, slug, track_id, difficulty) values ('nasyncnet-002', 'dotnet-async-configureawait-false', 'dotnet', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
