insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو دور ConfigureAwait(false) ولماذا كان إلزامياً في تطبيقات المكتب والمكتبات وتغير دوره في ASP.NET Core؟', 'يوجه المحرك بعدم العودة إلى نفس الـ SynchronizationContext الأصلي بعد انتهاء الـ await؛ وكان يمنع الـ Deadlocks في تطبيقات واجهات المستخدم والمكتبات.', 'في بيئات مثل WPF أو ASP.NET الكلاسيكي، كان يوجد SynchronizationContext يفرض تنفيذ ما بعد await على نفس الخيط الأساسي. إذا استخدم كود متزامن .Result، واستدعى الكود الداخلي await، فإنه ينتظر الخيط الأساسي المحجوز مسبقاً وتحدث Deadlock. كتابة ConfigureAwait(false) تتيح استئناف التنفيذ على أي خيط متاح من الـ ThreadPool. في ASP.NET Core الحديث، أُلغي الـ SynchronizationContext تماماً، لكن يظل استخدام ConfigureAwait(false) ممارسة مثالية وموصى بها في كتابة المكتبات العامة (Class Libraries).', '// في المكتبات المشتركة:
await httpClient.GetStringAsync(url).ConfigureAwait(false);', '["الاعتقاد بأن عدم كتابة ConfigureAwait(false) في ASP.NET Core سيسبب Deadlock؛ الـ SynchronizationContext غير موجود أصلاً في ASP.NET Core."]'::jsonb, '["كيف يؤثر ConfigureAwait(false) على تدفق سياق AsyncLocal والمصادقة في نفس مسار الطلب؟"]'::jsonb, '[{"title":"Microsoft Learn — ConfigureAwait FAQ","url":"https://learn.microsoft.com/en-us/dotnet/fundamentals/code-analysis/quality-rules/ca2007"}]'::jsonb from public.question_revisions r where r.question_id = 'nasyncnet-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasyncnet-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو دور ConfigureAwait(false) ولماذا كان إلزامياً في تطبيقات المكتب والمكتبات وتغير دوره في ASP.NET Core؟' or l.short_answer is distinct from 'يوجه المحرك بعدم العودة إلى نفس الـ SynchronizationContext الأصلي بعد انتهاء الـ await؛ وكان يمنع الـ Deadlocks في تطبيقات واجهات المستخدم والمكتبات.' or l.explanation is distinct from 'في بيئات مثل WPF أو ASP.NET الكلاسيكي، كان يوجد SynchronizationContext يفرض تنفيذ ما بعد await على نفس الخيط الأساسي. إذا استخدم كود متزامن .Result، واستدعى الكود الداخلي await، فإنه ينتظر الخيط الأساسي المحجوز مسبقاً وتحدث Deadlock. كتابة ConfigureAwait(false) تتيح استئناف التنفيذ على أي خيط متاح من الـ ThreadPool. في ASP.NET Core الحديث، أُلغي الـ SynchronizationContext تماماً، لكن يظل استخدام ConfigureAwait(false) ممارسة مثالية وموصى بها في كتابة المكتبات العامة (Class Libraries).' or l.code_example is distinct from '// في المكتبات المشتركة:
await httpClient.GetStringAsync(url).ConfigureAwait(false);' or l.common_mistakes is distinct from '["الاعتقاد بأن عدم كتابة ConfigureAwait(false) في ASP.NET Core سيسبب Deadlock؛ الـ SynchronizationContext غير موجود أصلاً في ASP.NET Core."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر ConfigureAwait(false) على تدفق سياق AsyncLocal والمصادقة في نفس مسار الطلب؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — ConfigureAwait FAQ","url":"https://learn.microsoft.com/en-us/dotnet/fundamentals/code-analysis/quality-rules/ca2007"}]'::jsonb)) then raise exception 'Question nasyncnet-002 ar content changed; create a new revision before seeding'; end if; end $$;
