insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل مكتبة System.Threading.Channels وما هي مميزاتها لتطبيق نمط المنتج والمستهلك (Producer-Consumer)؟', 'توفر قنوات تدفق بيانات غير متزامنة عالية الأداء وخالية من الأقفال (Lock-Free) لنقل البيانات بين خيوط الإنتاج والاستهلاك مع دعم كامل للـ Backpressure.', 'بدلاً من استخدام BlockingCollection الكلاسيكية التي تحجب الخيوط، صُممت Channels لتكون متوافقة بالكامل مع نموذج async/await الحديث. يمكنك إنشاء Channel.CreateBounded<T>(1000) لتحديد سعة المخزن؛ فإذا حاول المنتج الكتابة والمخزن ممتلئ، ينتظر غير متزامن بـ await writer.WriteAsync() دون تجميد الخيط، بينما يقرأ المستهلكون التدفق بسلاسة عبر await foreach.', 'var channel = Channel.CreateBounded<Order>(100);

// منتج يكتب
await channel.Writer.WriteAsync(new Order());

// مستهلك يقرأ
await foreach (var order in channel.Reader.ReadAllAsync()) {
    await ProcessOrderAsync(order);
}', '["استخدام Unbounded Channels دون سقف أقصى للذاكرة مما يهدد بنفاد الذاكرة في حال تفوق سرعة الإنتاج على الاستهلاك."]'::jsonb, '["كيف تزيد كفاءة القنوات بضبط خيارات SingleReader و SingleWriter؟"]'::jsonb, '[{"title":"Microsoft Learn — An Introduction to System.Threading.Channels","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/channels"}]'::jsonb from public.question_revisions r where r.question_id = 'nasyncnet-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
