insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي واجهة IAsyncEnumerable<T> وكيف تتيح تدفق نتائج البيانات الكبيرة في ASP.NET Core؟', 'تمثل مكرراً غير متزامن يجمع بين الـ Async والـ Yield، مما يتيح تدفق السجلات للعميل سطراً بسطر فور توفرها دون انتظار تحميل كامل القائمة في الذاكرة.', 'قديماً، كان إرجاع قائمة بيانات ضخمة يتطلب جلب كل السجلات في Task<List<T>> قبل إرسال أول بايت للعميل. باستخدام IAsyncEnumerable<T> وحلقة await foreach، يستطيع السيرفر قراءة السجلات من قاعدة البيانات وتدفقها مباشرة كـ JSON Stream للعميل فور جهوزيتها، مما يخفض زمن استلام أول بايت (TTFB) ويحافظ على ذاكرة السيرفر.', '[HttpGet("stream")]
public async IAsyncEnumerable<ProductDto> StreamProducts([EnumeratorCancellation] CancellationToken ct) {
    await foreach (var p in db.Products.AsAsyncEnumerable().WithCancellation(ct)) {
        yield return new ProductDto(p.Id, p.Name);
    }
}', '["نسيان إضافة سمة [EnumeratorCancellation] لمعامل الـ CancellationToken في دالة الـ IAsyncEnumerable."]'::jsonb, '["كيف تدعم المتصفحات قراءة استجابات IAsyncEnumerable المتدفقة عبر Fetch API Streams؟"]'::jsonb, '[{"title":"Microsoft Learn — IAsyncEnumerable<T> Interface","url":"https://learn.microsoft.com/en-us/dotnet/api/system.collections.generic.iasyncenumerable-1"}]'::jsonb from public.question_revisions r where r.question_id = 'nasyncnet-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
