insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين ThreadLocal<T> و AsyncLocal<T> في بيئات المعالجة غير المتزامنة بـ .NET؟', 'الـ ThreadLocal يربط القيمة بخيط نظام التشغيل الحالي ويفقد سياقه عند تبديل الخيوط بعد await، بينما AsyncLocal يتدفق مع سياق التنفيذ المنطقي عبر كل خيوط الـ await.', 'في البرمجة غير المتزامنة، ينتقل تنفيذ ما بعد await غالباً إلى خيط مختلف من خيوط الـ ThreadPool. إذا استخدمت ThreadLocal لحفظ معرف الطلب أو المستخدم، ستفقد القيمة أو تقرأ قيمة خيط آخر فور أول await. فئة AsyncLocal<T> صُممت خصيصاً لتتدفق مع الـ ExecutionContext؛ فحيثما انتقل كود الـ async عبر الخيوط، ترافقه القيمة المنطقية بأمان وتناسق.', 'private static readonly AsyncLocal<string> _traceId = new();

public async Task Process() {
    _traceId.Value = Guid.NewGuid().ToString();
    await Task.Delay(100); // قد يعود التنفيذ على خيط آخر تماماً
    Console.WriteLine(_traceId.Value); // تظل القيمة محفوظة بدقة
}', '["استخدام ThreadLocal لتخزين سياق طلب الـ HTTP في خوادم الويب غير المتزامنة الحديثة."]'::jsonb, '["كيف يمنع استدعاء ExecutionContext.SuppressFlow() تدفق السياق غير المتزامن لحماية الأمان أو زيادة الأداء؟"]'::jsonb, '[{"title":"Microsoft Learn — AsyncLocal<T> Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.threading.asynclocal-1"}]'::jsonb from public.question_revisions r where r.question_id = 'nasyncnet-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
