public async Task Process() {
    _traceId.Value = Guid.NewGuid().ToString();
    await Task.Delay(100); // قد يعود التنفيذ على خيط آخر تماماً
    Console.WriteLine(_traceId.Value); // تظل القيمة محفوظة بدقة
}' or l.common_mistakes is distinct from '["استخدام ThreadLocal لتخزين سياق طلب الـ HTTP في خوادم الويب غير المتزامنة الحديثة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يمنع استدعاء ExecutionContext.SuppressFlow() تدفق السياق غير المتزامن لحماية الأمان أو زيادة الأداء؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — AsyncLocal<T> Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.threading.asynclocal-1"}]'::jsonb)) then raise exception 'Question nasyncnet-008 ar content changed; create a new revision before seeding'; end if; end $$;
