insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يحظر استخدام async void في C# وما هو الاستثناء الوحيد المقبول لاستخدامها؟', 'يحظر لأن الأخطاء التي تقع داخل async void لا يمكن التقاطها بكتل try/catch الخارجية وتسقط التطبيق فوراً؛ والاستثناء المقبول الوحيد هو معالجات الأحداث (Event Handlers).', 'الدوال غير المتزامنة يجب أن تعيد دائماً Task أو Task<T> لتتيح للمستدعي انتظارها بـ await والتقاط أي استثناء داخل كتلة try/catch. عندما تعيد الدالة async void، لا يمتلك المستدعي أي كائن Task ليتتبعه، وأي استثناء غير معالج بداخلها يُرمى مباشرة على الـ SynchronizationContext ويسقط عملية الخادم بالكامل كخطأ غير معالج.', '// خطأ فادح: يسقط السيرفر ولا يمكن التقاط خطئه
public async void ProcessBad() {
    throw new Exception("Crash");
}

// الطريقة الصحيحة دائماً:
public async Task ProcessGood() {
    throw new Exception("Safely caught");
}', '["كتابة async void في مسارات الـ Background Tasks أو دوال المتحكمات."]'::jsonb, '["كيف تكتب اختبار وحدة لدالة async void ولماذا يعد ذلك شبه مستحيل بالطرق التقليدية؟"]'::jsonb, '[{"title":"Microsoft Learn — Async Return Types (C#)","url":"https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/async-return-types"}]'::jsonb from public.question_revisions r where r.question_id = 'nasyncnet-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nasyncnet-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يحظر استخدام async void في C# وما هو الاستثناء الوحيد المقبول لاستخدامها؟' or l.short_answer is distinct from 'يحظر لأن الأخطاء التي تقع داخل async void لا يمكن التقاطها بكتل try/catch الخارجية وتسقط التطبيق فوراً؛ والاستثناء المقبول الوحيد هو معالجات الأحداث (Event Handlers).' or l.explanation is distinct from 'الدوال غير المتزامنة يجب أن تعيد دائماً Task أو Task<T> لتتيح للمستدعي انتظارها بـ await والتقاط أي استثناء داخل كتلة try/catch. عندما تعيد الدالة async void، لا يمتلك المستدعي أي كائن Task ليتتبعه، وأي استثناء غير معالج بداخلها يُرمى مباشرة على الـ SynchronizationContext ويسقط عملية الخادم بالكامل كخطأ غير معالج.' or l.code_example is distinct from '// خطأ فادح: يسقط السيرفر ولا يمكن التقاط خطئه
public async void ProcessBad() {
    throw new Exception("Crash");
}

// الطريقة الصحيحة دائماً:
public async Task ProcessGood() {
    throw new Exception("Safely caught");
}' or l.common_mistakes is distinct from '["كتابة async void في مسارات الـ Background Tasks أو دوال المتحكمات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تكتب اختبار وحدة لدالة async void ولماذا يعد ذلك شبه مستحيل بالطرق التقليدية؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Async Return Types (C#)","url":"https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/async-return-types"}]'::jsonb)) then raise exception 'Question nasyncnet-009 ar content changed; create a new revision before seeding'; end if; end $$;
