insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تضبط إعدادات التحقق من رموز JWT بأمان في TokenValidationParameters بـ ASP.NET Core؟', 'بتفعيل التحقق الصارم من التوقيع (ValidateIssuerSigningKey)، والنطاق (ValidateIssuer)، والجمهور المستهدف (ValidateAudience)، وتعيين ClockSkew لصفر.', 'حزمة JwtBearer توفر التحقق التلقائي من التوكن عبر Middleware. الأمان الصارم يتطلب تعيين ValidateLifetime: true وتخفيض ClockSkew الافتراضي (وهو 5 دقائق) إلى TimeSpan.Zero لمنع قبول التوكن بعد لحظة انتهاء صلاحيته الفعلية، وتحديد ValidateIssuer و ValidateAudience بدقة لمنع استخدام توكن مصدر لنظام آخر في نظامك.', 'builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options => {
        options.TokenValidationParameters = new TokenValidationParameters {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),
            ValidateIssuer = true,
            ValidIssuer = "https://my-auth.com",
            ValidateAudience = true,
            ValidAudience = "my-api",
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero // إلغاء مهلة السماح الإضافية
        };
    });', '["ترك ClockSkew بالقيمة الافتراضية (5 دقائق) في أنظمة تتطلب إبطالاً دقيقاً وسريعاً لصلاحية الجلسات."]'::jsonb, '["كيف تتعامل مع تجديد الرموز المنتهية عبر آلية Refresh Tokens في ASP.NET Core Web API؟"]'::jsonb, '[{"title":"Microsoft Learn — Overview of ASP.NET Core authentication","url":"https://learn.microsoft.com/en-us/aspnet/core/security/authentication/"}]'::jsonb from public.question_revisions r where r.question_id = 'nsecnet-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsecnet-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تضبط إعدادات التحقق من رموز JWT بأمان في TokenValidationParameters بـ ASP.NET Core؟' or l.short_answer is distinct from 'بتفعيل التحقق الصارم من التوقيع (ValidateIssuerSigningKey)، والنطاق (ValidateIssuer)، والجمهور المستهدف (ValidateAudience)، وتعيين ClockSkew لصفر.' or l.explanation is distinct from 'حزمة JwtBearer توفر التحقق التلقائي من التوكن عبر Middleware. الأمان الصارم يتطلب تعيين ValidateLifetime: true وتخفيض ClockSkew الافتراضي (وهو 5 دقائق) إلى TimeSpan.Zero لمنع قبول التوكن بعد لحظة انتهاء صلاحيته الفعلية، وتحديد ValidateIssuer و ValidateAudience بدقة لمنع استخدام توكن مصدر لنظام آخر في نظامك.' or l.code_example is distinct from 'builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options => {
        options.TokenValidationParameters = new TokenValidationParameters {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),
            ValidateIssuer = true,
            ValidIssuer = "https://my-auth.com",
            ValidateAudience = true,
            ValidAudience = "my-api",
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero // إلغاء مهلة السماح الإضافية
        };
    });' or l.common_mistakes is distinct from '["ترك ClockSkew بالقيمة الافتراضية (5 دقائق) في أنظمة تتطلب إبطالاً دقيقاً وسريعاً لصلاحية الجلسات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتعامل مع تجديد الرموز المنتهية عبر آلية Refresh Tokens في ASP.NET Core Web API؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Overview of ASP.NET Core authentication","url":"https://learn.microsoft.com/en-us/aspnet/core/security/authentication/"}]'::jsonb)) then raise exception 'Question nsecnet-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a .NET developer know about Dotnet Jwt Authentication And Validation Parameters?', 'This question checks the core Dotnet Jwt Authentication And Validation Parameters concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.', 'Explain Dotnet Jwt Authentication And Validation Parameters with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options => {
        options.TokenValidationParameters = new TokenValidationParameters {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),
            ValidateIssuer = true,
            ValidIssuer = "https://my-auth.com",
            ValidateAudience = true,
            ValidAudience = "my-api",
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero // إلغاء مهلة السماح الإضافية
        };
    });', '["Missing the key trade-off in Dotnet Jwt Authentication And Validation Parameters (point 1)."]'::jsonb, '["How would you apply Dotnet Jwt Authentication And Validation Parameters in a production .NET app (follow-up 1)?"]'::jsonb, '[{"title":"Microsoft Learn — Overview of ASP.NET Core authentication","url":"https://learn.microsoft.com/en-us/aspnet/core/security/authentication/"}]'::jsonb from public.question_revisions r where r.question_id = 'nsecnet-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsecnet-001' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a .NET developer know about Dotnet Jwt Authentication And Validation Parameters?' or l.short_answer is distinct from 'This question checks the core Dotnet Jwt Authentication And Validation Parameters concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.' or l.explanation is distinct from 'Explain Dotnet Jwt Authentication And Validation Parameters with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from 'builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options => {
        options.TokenValidationParameters = new TokenValidationParameters {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),
            ValidateIssuer = true,
            ValidIssuer = "https://my-auth.com",
            ValidateAudience = true,
            ValidAudience = "my-api",
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero // إلغاء مهلة السماح الإضافية
        };
    });' or l.common_mistakes is distinct from '["Missing the key trade-off in Dotnet Jwt Authentication And Validation Parameters (point 1)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Dotnet Jwt Authentication And Validation Parameters in a production .NET app (follow-up 1)?"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Overview of ASP.NET Core authentication","url":"https://learn.microsoft.com/en-us/aspnet/core/security/authentication/"}]'::jsonb)) then raise exception 'Question nsecnet-001 en content changed; create a new revision before seeding'; end if; end $$;
