insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق الصلاحيات المعتمدة على السياسات (Policy-Based Authorization) وحقن متطلبات IAuthorizationRequirement؟', 'تُعرف سياسات في AddAuthorization تقبل متطلبات خاصة (Requirements)، وتنفذ فئة AuthorizationHandler لفحص شروط معقدة مثل مطابقة ملكية المورد أو السن.', 'بدلاً من تقييد التطبيق بالأدوار الثابتة القديمة [Authorize(Roles = ''Admin'')]، يوفر نظام السياسات في .NET مرونة برمجية فائقة. يمكنك إنشاء متطلب مثل MinimumAgeRequirement(18) وتطبيقه عبر فئة AuthorizationHandler<T> التي تفحص مطالبات الـ Claims في التوكن وسجل قاعدة البيانات قبل منح الإذن عبر context.Succeed(requirement).', 'builder.Services.AddAuthorization(options => {
    options.AddPolicy("AtLeast18", policy =>
        policy.Requirements.Add(new MinimumAgeRequirement(18)));
});

// التطبيق على المتحكم أو الـ Endpoint
[Authorize(Policy = "AtLeast18")]
public IActionResult ViewAdultContent() { ... }', '["حشو منطق فحص الصلاحيات داخل كود الـ Controller مباشرة بدلاً من عزله في Authorization Handlers مستقلة قابلة للاختبار."]'::jsonb, '["كيف تنفذ فحص صلاحيات الوصول للموارد الفردية عبر IAuthorizationService.AuthorizeAsync(user, resource, policy)؟"]'::jsonb, '[{"title":"Microsoft Learn — Policy-based authorization in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/security/authorization/policies"}]'::jsonb from public.question_revisions r where r.question_id = 'nsecnet-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsecnet-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق الصلاحيات المعتمدة على السياسات (Policy-Based Authorization) وحقن متطلبات IAuthorizationRequirement؟' or l.short_answer is distinct from 'تُعرف سياسات في AddAuthorization تقبل متطلبات خاصة (Requirements)، وتنفذ فئة AuthorizationHandler لفحص شروط معقدة مثل مطابقة ملكية المورد أو السن.' or l.explanation is distinct from 'بدلاً من تقييد التطبيق بالأدوار الثابتة القديمة [Authorize(Roles = ''Admin'')]، يوفر نظام السياسات في .NET مرونة برمجية فائقة. يمكنك إنشاء متطلب مثل MinimumAgeRequirement(18) وتطبيقه عبر فئة AuthorizationHandler<T> التي تفحص مطالبات الـ Claims في التوكن وسجل قاعدة البيانات قبل منح الإذن عبر context.Succeed(requirement).' or l.code_example is distinct from 'builder.Services.AddAuthorization(options => {
    options.AddPolicy("AtLeast18", policy =>
        policy.Requirements.Add(new MinimumAgeRequirement(18)));
});

// التطبيق على المتحكم أو الـ Endpoint
[Authorize(Policy = "AtLeast18")]
public IActionResult ViewAdultContent() { ... }' or l.common_mistakes is distinct from '["حشو منطق فحص الصلاحيات داخل كود الـ Controller مباشرة بدلاً من عزله في Authorization Handlers مستقلة قابلة للاختبار."]'::jsonb or l.follow_up_questions is distinct from '["كيف تنفذ فحص صلاحيات الوصول للموارد الفردية عبر IAuthorizationService.AuthorizeAsync(user, resource, policy)؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Policy-based authorization in ASP.NET Core","url":"https://learn.microsoft.com/en-us/aspnet/core/security/authorization/policies"}]'::jsonb)) then raise exception 'Question nsecnet-002 ar content changed; create a new revision before seeding'; end if; end $$;
