insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي واجهة برمجة حماية البيانات (Data Protection API) في .NET وأين يجب تخزين مفاتيحها في خوادم الإنتاج الموزعة؟', 'نظام تشفير مدمج لتأمين الكوكيز ورموز إعادة تعيين كلمات المرور؛ وفي الخوادم الموزعة يجب تخزين المفاتيح في مخزن مركزي (كـ Redis أو Azure Blob) وتشفيرها بـ Key Vault.', 'تستخدم الـ Data Protection API لتشفير كل ما هو مؤقت وحساس في التطبيق. افتراضياً، تحفظ المفاتيح في مجلد محلي على القرص. إذا نشرت تطبيقك على عدة خوادم خلف Load Balancer، فإن خادماً لن يستطيع فك تشفير الكوكي الصادرة من خادم آخر. الحل الحتمي هو ضبط PersistKeysToStackExchangeRedis أو قاعدة بيانات مشتركة، وتشفير حلقة المفاتيح عبر ProtectKeysWithCertificate أو Azure Key Vault.', 'builder.Services.AddDataProtection()
    .PersistKeysToStackExchangeRedis(redisConnection, "DataProtection-Keys")
    .SetApplicationName("SharedApp");', '["ترك المفاتيح في المجلد المحلي الافتراضي في بيئات الحاويات السحابية مما يؤدي لخروج المستخدمين مع كل إعادة تشغيل للحاوية."]'::jsonb, '["ما أهمية توحيد SetApplicationName عبر جميع الخوادم والخدمات المشتركة لنفس النظام؟"]'::jsonb, '[{"title":"Microsoft Learn — ASP.NET Core Data Protection overview","url":"https://learn.microsoft.com/en-us/aspnet/core/security/data-protection/introduction"}]'::jsonb from public.question_revisions r where r.question_id = 'nsecnet-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsecnet-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي واجهة برمجة حماية البيانات (Data Protection API) في .NET وأين يجب تخزين مفاتيحها في خوادم الإنتاج الموزعة؟' or l.short_answer is distinct from 'نظام تشفير مدمج لتأمين الكوكيز ورموز إعادة تعيين كلمات المرور؛ وفي الخوادم الموزعة يجب تخزين المفاتيح في مخزن مركزي (كـ Redis أو Azure Blob) وتشفيرها بـ Key Vault.' or l.explanation is distinct from 'تستخدم الـ Data Protection API لتشفير كل ما هو مؤقت وحساس في التطبيق. افتراضياً، تحفظ المفاتيح في مجلد محلي على القرص. إذا نشرت تطبيقك على عدة خوادم خلف Load Balancer، فإن خادماً لن يستطيع فك تشفير الكوكي الصادرة من خادم آخر. الحل الحتمي هو ضبط PersistKeysToStackExchangeRedis أو قاعدة بيانات مشتركة، وتشفير حلقة المفاتيح عبر ProtectKeysWithCertificate أو Azure Key Vault.' or l.code_example is distinct from 'builder.Services.AddDataProtection()
    .PersistKeysToStackExchangeRedis(redisConnection, "DataProtection-Keys")
    .SetApplicationName("SharedApp");' or l.common_mistakes is distinct from '["ترك المفاتيح في المجلد المحلي الافتراضي في بيئات الحاويات السحابية مما يؤدي لخروج المستخدمين مع كل إعادة تشغيل للحاوية."]'::jsonb or l.follow_up_questions is distinct from '["ما أهمية توحيد SetApplicationName عبر جميع الخوادم والخدمات المشتركة لنفس النظام؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — ASP.NET Core Data Protection overview","url":"https://learn.microsoft.com/en-us/aspnet/core/security/data-protection/introduction"}]'::jsonb)) then raise exception 'Question nsecnet-003 ar content changed; create a new revision before seeding'; end if; end $$;
