insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحمي استعلامات Dapper و ADO.NET من ثغرات SQL Injection؟', 'باستخدام الاستعلامات المجهزة المعتمدة على المعلمات النائبة (@param) وتمرير كائنات مجهولة لـ Dapper، وحظر دمج النصوص المباشر نهائياً.', 'في الـ Micro-ORMs مثل Dapper، يكتب المطور استعلامات SQL بيده. الخطر الأكبر هو دمج متغيرات المستخدم بنصوص الـ string interpolation. الطريقة الآمنة الحتمية هي استخدام المعلمات المصرحة (@email)، حيث يقوم Dapper بتوليد كائنات DbParameter وإرسال القيم معزولة لقاعدة البيانات لحمايتها من أي استغلال خبيث.', '// آمن تماماً بواسطة Dapper Parameterization
var user = await connection.QueryFirstOrDefaultAsync<User>(
    "SELECT * FROM Users WHERE Email = @Email AND Status = @Status",
    new { Email = inputEmail, Status = "Active" }
);', '["كتابة $\"SELECT * FROM Users WHERE Email = ''{inputEmail}''\" مع Dapper مما يفتح ثغرة حقن SQL فادحة."]'::jsonb, '["كيف تحمي استعلامات جملة IN في Dapper عند تمرير مصفوفة قيم معلمات ديناميكية؟"]'::jsonb, '[{"title":"Microsoft Learn — Security in .NET data access","url":"https://learn.microsoft.com/en-us/dotnet/framework/data/adonet/sql/sql-server-security"}]'::jsonb from public.question_revisions r where r.question_id = 'nsecnet-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
