insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يحظر استخدام فئة System.Random للأغراض الأمنية وما هو البديل التشفيري المعتمد؟', 'لأن System.Random خوارزمية شبه عشوائية حتمية يسهل التنبؤ بقيمها التالية؛ والبديل التشفيري الآمن هو RandomNumberGenerator في System.Security.Cryptography.', 'تعتمد فئة Random على بذرة زمنية بسيطة (Clock Seed)، مما يمكن المهاجم من تخمين الرموز الأمنية، ورموز تفعيل الحسابات، ومفاتيح الجلسات بعد مراقبة بضع قيم سابقة. توفر فئة RandomNumberGenerator واجهة آمنة تشفيرياً (CSPRNG) تسحب عشوائيتها من أحداث العتاد ونواة نظام التشغيل، وتوفر دوالاً مريحة مثل RandomNumberGenerator.GetInt32() و GetBytes().', '// توليد رمز OTP آمن تشفيرياً مكون من 6 أرقام
int otp = RandomNumberGenerator.GetInt32(100000, 1000000);

// توليد مفتاح عشوائي مشفر
byte[] salt = RandomNumberGenerator.GetBytes(32);', '["استخدام new Random().Next() لإنشاء رموز إعادة تعيين كلمات المرور أو التواقيع الأمنية."]'::jsonb, '["ما هي فئة CryptographicOperations وما دور CryptographicOperations.FixedTimeEquals في منع هجمات التوقيت؟"]'::jsonb, '[{"title":"Microsoft Learn — RandomNumberGenerator Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.security.cryptography.randomnumbergenerator"}]'::jsonb from public.question_revisions r where r.question_id = 'nsecnet-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nsecnet-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يحظر استخدام فئة System.Random للأغراض الأمنية وما هو البديل التشفيري المعتمد؟' or l.short_answer is distinct from 'لأن System.Random خوارزمية شبه عشوائية حتمية يسهل التنبؤ بقيمها التالية؛ والبديل التشفيري الآمن هو RandomNumberGenerator في System.Security.Cryptography.' or l.explanation is distinct from 'تعتمد فئة Random على بذرة زمنية بسيطة (Clock Seed)، مما يمكن المهاجم من تخمين الرموز الأمنية، ورموز تفعيل الحسابات، ومفاتيح الجلسات بعد مراقبة بضع قيم سابقة. توفر فئة RandomNumberGenerator واجهة آمنة تشفيرياً (CSPRNG) تسحب عشوائيتها من أحداث العتاد ونواة نظام التشغيل، وتوفر دوالاً مريحة مثل RandomNumberGenerator.GetInt32() و GetBytes().' or l.code_example is distinct from '// توليد رمز OTP آمن تشفيرياً مكون من 6 أرقام
int otp = RandomNumberGenerator.GetInt32(100000, 1000000);

// توليد مفتاح عشوائي مشفر
byte[] salt = RandomNumberGenerator.GetBytes(32);' or l.common_mistakes is distinct from '["استخدام new Random().Next() لإنشاء رموز إعادة تعيين كلمات المرور أو التواقيع الأمنية."]'::jsonb or l.follow_up_questions is distinct from '["ما هي فئة CryptographicOperations وما دور CryptographicOperations.FixedTimeEquals في منع هجمات التوقيت؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — RandomNumberGenerator Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.security.cryptography.randomnumbergenerator"}]'::jsonb)) then raise exception 'Question nsecnet-009 ar content changed; create a new revision before seeding'; end if; end $$;
