insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تساعد فئات ArrayPool<T> و MemoryPool<T> في القضاء على ضغط مجمع المهملات (GC Pressure)؟', 'توفر مخزناً للمصفوفات وكتل الذاكرة يعاد استخدامها واستئجارها (Rent) وإرجاعها (Return) بدلاً من حجز مصفوفات جديدة وحذفها في كل طلب.', 'في الخوادم التي تعالج آلاف الطلبات في الثانية، حجز مصفوفات byte[] لقراءة حزم الشبكة والملفات يملأ Gen 0 بسرعة ويجبر الـ GC على إيقاف العمليات دورياً. استخدام ArrayPool<T>.Shared.Rent(minSize) يستعير مصفوفة موجودة مسبقاً في الـ Pool في كسر من الميكروثانية، وعند الانتهاء بكتلة finally يُستدعى pool.Return(array)، مما يحقق استقراراً فائقاً للذاكرة وصفر ضغط على الـ GC.', 'var pool = ArrayPool<byte>.Shared;
byte[] buffer = pool.Rent(4096);
try {
    int bytesRead = await stream.ReadAsync(buffer);
    Process(buffer.AsSpan(0, bytesRead));
} finally {
    pool.Return(buffer); // إعادة تدوير المصفوفة
}', '["نسيان إرجاع المصفوفة المستعارة في كتلة finally مما يفرغ الـ Pool ويفقد الميزة فاعليتها."]'::jsonb, '["لماذا قد تكون المصفوفة المعادة من pool.Rent أكبر حجماً من الحجم الذي طلبته صراحة؟"]'::jsonb, '[{"title":"Microsoft Learn — ArrayPool<T> Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.buffers.arraypool-1"}]'::jsonb from public.question_revisions r where r.question_id = 'nperfnet-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nperfnet-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تساعد فئات ArrayPool<T> و MemoryPool<T> في القضاء على ضغط مجمع المهملات (GC Pressure)؟' or l.short_answer is distinct from 'توفر مخزناً للمصفوفات وكتل الذاكرة يعاد استخدامها واستئجارها (Rent) وإرجاعها (Return) بدلاً من حجز مصفوفات جديدة وحذفها في كل طلب.' or l.explanation is distinct from 'في الخوادم التي تعالج آلاف الطلبات في الثانية، حجز مصفوفات byte[] لقراءة حزم الشبكة والملفات يملأ Gen 0 بسرعة ويجبر الـ GC على إيقاف العمليات دورياً. استخدام ArrayPool<T>.Shared.Rent(minSize) يستعير مصفوفة موجودة مسبقاً في الـ Pool في كسر من الميكروثانية، وعند الانتهاء بكتلة finally يُستدعى pool.Return(array)، مما يحقق استقراراً فائقاً للذاكرة وصفر ضغط على الـ GC.' or l.code_example is distinct from 'var pool = ArrayPool<byte>.Shared;
byte[] buffer = pool.Rent(4096);
try {
    int bytesRead = await stream.ReadAsync(buffer);
    Process(buffer.AsSpan(0, bytesRead));
} finally {
    pool.Return(buffer); // إعادة تدوير المصفوفة
}' or l.common_mistakes is distinct from '["نسيان إرجاع المصفوفة المستعارة في كتلة finally مما يفرغ الـ Pool ويفقد الميزة فاعليتها."]'::jsonb or l.follow_up_questions is distinct from '["لماذا قد تكون المصفوفة المعادة من pool.Rent أكبر حجماً من الحجم الذي طلبته صراحة؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — ArrayPool<T> Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.buffers.arraypool-1"}]'::jsonb)) then raise exception 'Question nperfnet-001 ar content changed; create a new revision before seeding'; end if; end $$;
