insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تستخدم مكتبة BenchmarkDotNet لقياس أداء كود C# بدقة وما هي القواعد الذهبية للقياس؟', 'تنشئ مشروع Console منفصل وتستخدم سمة [Benchmark]؛ وتقوم المكتبة بالإحماء التلقائي وعزل المعالج وقياس الزمن وتخصيصات الذاكرة بـ [MemoryDiagnoser].', 'القياس اليدوي باستخدام Stopwatch يعطي نتائج مضللة وغير علمية بسبب تداخل الـ JIT compilation وتوقفات الـ GC وتقلبات تردد المعالج. تقوم أداة BenchmarkDotNet بعزل بيئة التشغيل، وتشغيل دورات إحماء (Warmup) متكررة حتى يستقر الكود في أقصى تحسين (Tier 1 JIT)، وإجراء مئات التكرارات الإحصائية وتوليد جداول دقيقة بالنانوثانية وكمية البايتات المحجوزة في الـ Heap.', '[MemoryDiagnoser]
public class StringBenchmarks {
    [Benchmark]
    public string UsingStringBuilder() {
        var sb = new StringBuilder();
        for (int i = 0; i < 100; i++) sb.Append(i);
        return sb.ToString();
    }
}', '["تشغيل اختبارات الأداء في وضع Debug بدلاً من Release مما يعطي نتائج مشوهة لغياب تحسينات المترجم."]'::jsonb, '["كيف تفسر عمود Allocated في تقارير BenchmarkDotNet لتحديد تسريبات الذاكرة؟"]'::jsonb, '[{"title":"Microsoft Learn — Performance testing and benchmarking in .NET","url":"https://learn.microsoft.com/en-us/dotnet/standard/base-types/best-practices-strings#performance-and-best-practices-for-stringbuilder"}]'::jsonb from public.question_revisions r where r.question_id = 'nperfnet-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
