insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو تضمين الدوال (Method Inlining) ومتى تستخدم سمة [MethodImpl(MethodImplOptions.AggressiveInlining)]؟', 'هو استبدال استدعاء الدالة بكود جسمها مباشرة لتوفير تكلفة الـ Call Stack والقفز بالمعالج؛ وتستخدم للدوائر السريعة والصغيرة جداً في المسارات الحيوية.', 'يقوم مجمع JIT تلقائياً بتضمين الدوال الصغيرة التي يقل حجمها عن حد معين. استدعاء الدالة العادي يتطلب دفع المعاملات في الـ Stack وقفز مسار المعالج (Call/Return). استخدام AggressiveInlining يجبر الـ JIT على دمج الدالة في كود المستدعي مباشرة. ومع ذلك، فإن الإفراط في استخدامها مع دوال كبيرة يؤدي لتضخم حجم كود الآلة (Code Bloat) وخروج الكود من كاش المعالج السريع (L1/L2 Instruction Cache).', '[MethodImpl(MethodImplOptions.AggressiveInlining)]
public static int FastMax(int a, int b) => a > b ? a : b;', '["وضع AggressiveInlining على دوال كبيرة ومعقدة تحتوي على استثناءات مما يؤدي لتدهور كفاءة الكاش وتراجع الأداء."]'::jsonb, '["لماذا ينصح بفصل رمي الاستثناءات في دوال مساعدة منفصلة (Throw Helpers) لتسهيل تضمين الدالة الرئيسية؟"]'::jsonb, '[{"title":"Microsoft Learn — MethodImplOptions Enum","url":"https://learn.microsoft.com/en-us/dotnet/api/system.runtime.compilerservices.methodimploptions"}]'::jsonb from public.question_revisions r where r.question_id = 'nperfnet-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'nperfnet-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو تضمين الدوال (Method Inlining) ومتى تستخدم سمة [MethodImpl(MethodImplOptions.AggressiveInlining)]؟' or l.short_answer is distinct from 'هو استبدال استدعاء الدالة بكود جسمها مباشرة لتوفير تكلفة الـ Call Stack والقفز بالمعالج؛ وتستخدم للدوائر السريعة والصغيرة جداً في المسارات الحيوية.' or l.explanation is distinct from 'يقوم مجمع JIT تلقائياً بتضمين الدوال الصغيرة التي يقل حجمها عن حد معين. استدعاء الدالة العادي يتطلب دفع المعاملات في الـ Stack وقفز مسار المعالج (Call/Return). استخدام AggressiveInlining يجبر الـ JIT على دمج الدالة في كود المستدعي مباشرة. ومع ذلك، فإن الإفراط في استخدامها مع دوال كبيرة يؤدي لتضخم حجم كود الآلة (Code Bloat) وخروج الكود من كاش المعالج السريع (L1/L2 Instruction Cache).' or l.code_example is distinct from '[MethodImpl(MethodImplOptions.AggressiveInlining)]
public static int FastMax(int a, int b) => a > b ? a : b;' or l.common_mistakes is distinct from '["وضع AggressiveInlining على دوال كبيرة ومعقدة تحتوي على استثناءات مما يؤدي لتدهور كفاءة الكاش وتراجع الأداء."]'::jsonb or l.follow_up_questions is distinct from '["لماذا ينصح بفصل رمي الاستثناءات في دوال مساعدة منفصلة (Throw Helpers) لتسهيل تضمين الدالة الرئيسية؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — MethodImplOptions Enum","url":"https://learn.microsoft.com/en-us/dotnet/api/system.runtime.compilerservices.methodimploptions"}]'::jsonb)) then raise exception 'Question nperfnet-004 ar content changed; create a new revision before seeding'; end if; end $$;
