insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف ترصد مقاييس الأداء واستهلاك الذاكرة حياً في تطبيقات .NET باستخدام System.Diagnostics.Metrics و OpenTelemetry؟', 'باستخدام فئات Meter و Counter لتسجيل مقاييس الأعمال والأداء، وتصديرها بصيغة Prometheus القياسية لمراقبتها في لوحات Grafana.', 'في .NET الحديثة، تم توحيد نظام المقاييس تحت فضاء System.Diagnostics.Metrics المتوافق مع OpenTelemetry. بدلاً من الاعتماد على Performance Counters القديمة الخاصة بـ Windows فقط، تتيح فئة Meter إنشاء عدادات خفيفة وموحدة (Counters و Histograms و UpDownCounters) تعمل عبر Linux و Windows وتصدر تلقائياً للأنظمة الموزعة عبر مسار /metrics.', 'private static readonly Meter MyMeter = new("MyApp.Orders");
private static readonly Counter<int> OrdersPlaced = MyMeter.CreateCounter<int>("orders_total");

public void PlaceOrder() {
    OrdersPlaced.Add(1, new KeyValuePair<string, object?>("country", "EG"));
}', '["إنشاء نُسخ جديدة من كائن Meter مع كل طلب بدلاً من تعريفه كـ static أو مشاركته كـ Singleton."]'::jsonb, '["كيف تراقب أزمنة تنفيذ طلبات HTTP عبر كائن Histogram<double>؟"]'::jsonb, '[{"title":"Microsoft Learn — System.Diagnostics.Metrics overview","url":"https://learn.microsoft.com/en-us/dotnet/core/diagnostics/metrics"}]'::jsonb from public.question_revisions r where r.question_id = 'nperfnet-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
