insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي تعليمات SIMD و Hardware Intrinsics في .NET وكيف تسرع معالجة المصفوفات الحسابية؟', 'تسمح بتنفيذ عملية حسابية واحدة على عدة بيانات بالتوازي في نفس نبضة المعالج (Single Instruction, Multiple Data) عبر فئات Vector<T> ومكتبات AVX2/SSE.', 'بدلاً من معالجة مصفوفة رقمية عنصراً بعنصر في حلقة تكرارية، تستغل فئة Vector<T> مسجلات المعالج العريضة (128-bit أو 256-bit أو 512-bit). في المعالجات التي تدعم AVX-512، يمكن جمع 16 رقماً عائماً (float) في نبضة ساعة واحدة متزامنة، مما يرفع سرعة الحسابات الرياضية، ومعالجة الصور، والتشفير بعشرات الأضعاف بمجرد تفعيل الدعم في الكود.', '// جمع مصفوفتين باستخدام متجهات الـ SIMD
int vectorSize = Vector<int>.Count;
for (int i = 0; i <= length - vectorSize; i += vectorSize) {
    var v1 = new Vector<int>(arrayA, i);
    var v2 = new Vector<int>(arrayB, i);
    (v1 + v2).CopyTo(result, i);
}', '["افتراض دعم كل المعالجات لنفس تعليمات الـ Intrinsics دون فحص الخصائص التوافقية مثل Avx2.IsSupported."]'::jsonb, '["كيف تدعم فئة Vector64 و Vector128 و Vector256 في System.Runtime.Intrinsics التفاعل المباشر مع عتاد المعالج؟"]'::jsonb, '[{"title":"Microsoft Learn — Hardware intrinsics in .NET","url":"https://learn.microsoft.com/en-us/dotnet/standard/simd"}]'::jsonb from public.question_revisions r where r.question_id = 'nperfnet-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
