    // 6 bytes padding
}' or l.common_mistakes is distinct from '["تجاهل محاذاة الذاكرة عند تبادل هياكل البيانات مع مكتبات C عبر P/Invoke."]'::jsonb or l.follow_up_questions is distinct from '["كيف تجبر المحرك على رص المتغيرات بدون أي حشوات عبر [StructLayout(LayoutKind.Sequential, Pack = 1)]؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — StructLayoutAttribute Class","url":"https://learn.microsoft.com/en-us/dotnet/api/system.runtime.interopservices.structlayoutattribute"}]'::jsonb)) then raise exception 'Question nperfnet-007 ar content changed; create a new revision before seeding'; end if; end $$;
