insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يعد System.Text.Json أسرع بكثير من Newtonsoft.Json (Json.NET) وما المعمارية المبني عليها؟', 'يعتمد على معالجة تدفقات UTF-8 مباشرة (ReadOnlySpan<byte>) دون تحويل لنصوص UTF-16، ويتجنب تخصيص الكائنات في الـ Heap ويدعم الـ Source Generation.', 'قديماً، كانت مكتبة Newtonsoft تقرأ البيانات كنصوص string، وتنشئ كائنات وسيطة كثيرة وتعتمد بشدة على Reflection. صُمم System.Text.Json من الصفر في .NET Core للاستفادة من بنى الأداء الفائق مثل Utf8JsonReader و ArrayPool. مع دعم JsonSourceGeneration، يتم تسلسل وفك تسلسل البيانات بسرعة فائقة وصفر تخصيصات إضافية وتوافق تام مع Native AOT.', '[JsonSerializable(typeof(UserDto))]
internal partial class AppJsonSerializerContext : JsonSerializerContext {}

// استخدام المولد المسبق فائق السرعة
var json = JsonSerializer.Serialize(user, AppJsonSerializerContext.Default.UserDto);', '["الاحتفاظ بمكتبة Newtonsoft.Json في المشاريع الحديثة دون مسوغ حقيقي، مما يحرم التطبيق من مضاعفة سرعة تسلسل الـ JSON."]'::jsonb, '["كيف تنشئ Custom JsonConverter مخصصاً لمعالجة تنسيق التواريخ أو التعدادات المعقدة؟"]'::jsonb, '[{"title":"Microsoft Learn — System.Text.Json overview","url":"https://learn.microsoft.com/en-us/dotnet/standard/serialization/system-text-json/overview"}]'::jsonb from public.question_revisions r where r.question_id = 'nperfnet-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
