insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفلسفة المعمارية لإطار xUnit وكيف يعزل الاختبارات عبر إنشاء نسخة فئة جديدة لكل اختبار؟', 'ينشئ xUnit نسخة جديدة تماماً من فئة الاختبار لكل دالة [Fact] لضمان استقلال الحالات ومنع التداخل، ويعتمد على الباني و IDisposable بدلاً من Setup و Teardown.', 'في NUnit، يُعاد استخدام نفس نسخة الفئة لجميع الاختبارات ما لم يُطلب العكس، مما قد يسبب تداخلاً غير مقصود في حالة المتغيرات. تبنى xUnit مبدأ العزل الصارم؛ فلكل اختبار يتم تشغيل الباني وإنشاء الفئة وتدميرها عبر Dispose(). لمشاركة بيانات باهظة التكلفة بين عدة اختبارات، يوفر xUnit فئات Fixtures مخصصة عبر واجهة IClassFixture<T>.', 'public class CalculatorTests : IDisposable {
    private readonly Calculator _calc = new(); // نظيف وجديد لكل Fact

    [Fact]
    public void AddsCorrectly() => Assert.Equal(4, _calc.Add(2, 2));

    public void Dispose() { /* تنظيف بعد كل اختبار */ }
}', '["الاعتماد على متغيرات الفئة العامة لمشاركة الحالة بين اختبارات xUnit دون إدراك أنها نسخ منفصلة تماماً."]'::jsonb, '["كيف تشارك سياق قاعدة بيانات واحدة بين عدة فئات اختبارات عبر ICollectionFixture<T>؟"]'::jsonb, '[{"title":"Microsoft Learn — Unit testing C# with xUnit and .NET","url":"https://learn.microsoft.com/en-us/dotnet/core/testing/unit-testing-with-dotnet-test"}]'::jsonb from public.question_revisions r where r.question_id = 'ntestnet-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
