insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي فئة TimeProvider المضافة في .NET 8 وكيف حلت معضلة اختبار الأكواد المعتمدة على الوقت والمؤقتات؟', 'تجريد رسمي للوقت والمؤقتات يُحقن في الخدمات كـ TimeProvider؛ ويتيح في الاختبارات تجميد وتمرير الوقت يدوياً عبر FakeTimeProvider دون انتظار حقيقي.', 'قديماً، كان المطورون يكتبون واجهات مخصصة مثل IDateTimeProvider لاستبدال DateTime.UtcNow في الاختبارات. في .NET 8، وفرت مايكروسوفت TimeProvider كمعيار موحد في الـ BCL. في بيئة الاختبار، تحقن حزمة Microsoft.Extensions.Time.Testing فئة FakeTimeProvider؛ وتستطيع استدعاء fakeTime.Advance(TimeSpan.FromMinutes(10)) ليتم إطلاق المؤقتات وفحص انتهاء الصلاحيات لحظياً وبصفر انتظار.', '// في خدمة الأعمال
public class TokenService(TimeProvider timeProvider) {
    public bool IsExpired(Token t) => timeProvider.GetUtcNow() > t.ExpiresAt;
