insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق اختبارات المعمارية (Architecture Tests) باستخدام مكتبات مثل NetArchTest في .NET؟', 'تكتب اختبارات وحدة تفحص التجميعات وتفرض القواعد المعمارية؛ كأن تمنع طبقة الـ Domain من الإشارة لطبقة الـ Infrastructure أو تفرض تسميات موحدة للمتحكمات.', 'في الفرق الكبيرة، يسهل كسر قواعد المعمارية النظيفة (Clean Architecture) بالخطأ كأن يستورد مطور كود SQL داخل كيان الـ Domain. تقوم مكتبة NetArchTest بفحص شجرة الأنواع في الـ Assemblies برمجياً؛ فإذا قامت أي فئة في Domain بتوريث أو استيراد كلاس من Infrastructure، يفشل اختبار الـ CI فوراً ويمنع دمج الكود قبل وصوله للإنتاج.', '[Fact]
public void Domain_Should_Not_DependOn_Infrastructure() {
    var result = Types.InAssembly(typeof(DomainEntity).Assembly)
        .ShouldNot()
        .HaveDependencyOn("Infrastructure")
        .GetResult();

    Assert.True(result.IsSuccessful);
}', '["الاعتماد حصراً على مراجعة الكود اليدوية (Code Review) لاكتشاف انتهاكات المعمارية النظيفة بدلاً من أتمتتها."]'::jsonb, '["كيف تختبر قاعدة أن جميع الـ Commands في تطبيقك يجب أن تطبق واجهة IRequest<T> وتنتهي بكلمة Command؟"]'::jsonb, '[{"title":"Microsoft Learn — Common Application Architecture Design","url":"https://learn.microsoft.com/en-us/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures"}]'::jsonb from public.question_revisions r where r.question_id = 'ntestnet-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
