insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تختبر عملاء HttpClient بأمان دون إرسال طلبات شبكة حقيقية باستخدام MockHttpMessageHandler؟', 'باستبدال معالج الرسائل الأساسي (HttpMessageHandler) بمعالج وهمي يعترض استدعاء SendAsync ويرجع استجابة HttpResponseMessage محددة مسبقاً.', 'فئة HttpClient لا تمتلك دوالاً افتراضية لتطبيق Mock عليها مباشرة. الطريقة المعمارية الرسمية لاختبارها هي استبدال المعالج الداخلي HttpMessageHandler بفئة وهمية مخصصة (أو باستخدام مكتبة RichardSzalay.MockHttp). يقوم هذا المعالج باعتراض الطلب وفحص الروابط والترويسات وإرجاع كود الحالة والـ JSON المتوقع دون لمس شبكة الإنترنت إطلاقاً.', 'var handler = new MockHttpMessageHandler();
handler.When("https://api.github.com/users/*")
       .Respond("application/json", "{''name'':''octocat''}");

var client = new HttpClient(handler);
var service = new GitHubService(client);
var result = await service.GetUserNameAsync("octocat");
Assert.Equal("octocat", result);', '["استدعاء خوادم إنترنت حقيقية في اختبارات الوحدة مما يجعلها تفشل عند انقطاع الشبكة أو بطء الخادم الخارجي."]'::jsonb, '["كيف تدمج المعالج الوهمي مع IHttpClientFactory عبر services.AddHttpClient().ConfigurePrimaryHttpMessageHandler()؟"]'::jsonb, '[{"title":"Microsoft Learn — Mocking HttpClient in ASP.NET Core tests","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/implement-resilient-applications/use-httpclientfactory-to-implement-resilient-http-requests"}]'::jsonb from public.question_revisions r where r.question_id = 'ntestnet-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ntestnet-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تختبر عملاء HttpClient بأمان دون إرسال طلبات شبكة حقيقية باستخدام MockHttpMessageHandler؟' or l.short_answer is distinct from 'باستبدال معالج الرسائل الأساسي (HttpMessageHandler) بمعالج وهمي يعترض استدعاء SendAsync ويرجع استجابة HttpResponseMessage محددة مسبقاً.' or l.explanation is distinct from 'فئة HttpClient لا تمتلك دوالاً افتراضية لتطبيق Mock عليها مباشرة. الطريقة المعمارية الرسمية لاختبارها هي استبدال المعالج الداخلي HttpMessageHandler بفئة وهمية مخصصة (أو باستخدام مكتبة RichardSzalay.MockHttp). يقوم هذا المعالج باعتراض الطلب وفحص الروابط والترويسات وإرجاع كود الحالة والـ JSON المتوقع دون لمس شبكة الإنترنت إطلاقاً.' or l.code_example is distinct from 'var handler = new MockHttpMessageHandler();
handler.When("https://api.github.com/users/*")
