insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو نمط CQRS وكيف تسهل مكتبة MediatR فصل القراءة عن الكتابة في مشاريع C#؟', 'يفصل عمليات تعديل الحالة (Commands) عن استعلامات جلب البيانات (Queries)؛ وتعمل MediatR كناقل رسائل وسيط (In-process Mediator) يربط كل طلب بمعالجه المستقل IRequestHandler.', 'في أنظمة Command Query Responsibility Segregation (CQRS)، تختلف متطلبات القراءة عن الكتابة. في الكتابة، تحتاج لـ Domain Models وتدقيق صارم ومعاملات ذرية. في القراءة، تحتاج لسرعة فائقة واستعلامات DTO مسطحة دون أعباء التتبع. توفر MediatR عزل كامل؛ حيث يرسل المتحكم الأمر mediator.Send(new CreateOrderCommand(dto)) وتتوجه الرسالة للمعالج المخصص دون معرفة المتحكم بالتفاصيل.', 'public record GetUserQuery(int Id) : IRequest<UserDto?>;

public class GetUserHandler(AppDbContext db) : IRequestHandler<GetUserQuery, UserDto?> {
    public async Task<UserDto?> Handle(GetUserQuery request, CancellationToken ct) =>
        await db.Users.AsNoTracking().Where(u => u.Id == request.Id).ProjectToDto().FirstOrDefaultAsync(ct);
}', '["تعديل بيانات الكيان داخل معالجات الـ Queries؛ يجب أن تكون الاستعلامات خالية تماماً من أي آثار جانبية (Side Effects)."]'::jsonb, '["كيف تطبق وسائط معالجة مدمجة مثل التدقيق والتسجيل التلقائي عبر MediatR IPipelineBehavior؟"]'::jsonb, '[{"title":"Microsoft Learn — CQRS pattern in Microservices","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/apply-simplified-cqrs-cqrs-s-architecture"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narchnet-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو نمط CQRS وكيف تسهل مكتبة MediatR فصل القراءة عن الكتابة في مشاريع C#؟' or l.short_answer is distinct from 'يفصل عمليات تعديل الحالة (Commands) عن استعلامات جلب البيانات (Queries)؛ وتعمل MediatR كناقل رسائل وسيط (In-process Mediator) يربط كل طلب بمعالجه المستقل IRequestHandler.' or l.explanation is distinct from 'في أنظمة Command Query Responsibility Segregation (CQRS)، تختلف متطلبات القراءة عن الكتابة. في الكتابة، تحتاج لـ Domain Models وتدقيق صارم ومعاملات ذرية. في القراءة، تحتاج لسرعة فائقة واستعلامات DTO مسطحة دون أعباء التتبع. توفر MediatR عزل كامل؛ حيث يرسل المتحكم الأمر mediator.Send(new CreateOrderCommand(dto)) وتتوجه الرسالة للمعالج المخصص دون معرفة المتحكم بالتفاصيل.' or l.code_example is distinct from 'public record GetUserQuery(int Id) : IRequest<UserDto?>;

public class GetUserHandler(AppDbContext db) : IRequestHandler<GetUserQuery, UserDto?> {
