insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي سلوكيات خط الأنابيب (Pipeline Behaviors) في MediatR وكيف تطبق البرمجة الموجهة للجوانب (AOP)؟', 'وسائط داخلية تعترض كل طلب IRequest قبل وصوله للـ Handler، وتستخدم لتنفيذ مهام متقاطعة مثل التحقق من المدخلات بـ FluentValidation، والتسجيل، والكاش، وإدارة المعاملات.', 'بدلاً من كتابة كود فحص الصلاحيات أو قياس زمن التنفيذ داخل كل معالج بشكل متكرر، تتيح فئة IPipelineBehavior<TRequest, TResponse> اعتراض أي طلب يمر عبر MediatR. يمكنك مثلاً إنشاء ValidationBehavior يفحص ما إذا كان هناك أي قواعد FluentValidation للطلب ويرمي ValidationException قبل تشغيل الـ Handler، محافظاً على نقاء منطق الأعمال.', 'public class LoggingBehavior<TRequest, TResponse>(ILogger<TRequest> logger)
    : IPipelineBehavior<TRequest, TResponse> where TRequest : notnull {
    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken ct) {
        logger.LogInformation("Handling {RequestName}", typeof(TRequest).Name);
        var response = await next();
        logger.LogInformation("Handled {RequestName}", typeof(TRequest).Name);
        return response;
    }
}', '["نسيان استدعاء await next() داخل الـ Behavior مما يقطع تدفق الطلب ويمنع وصوله للـ Handler."]'::jsonb, '["كيف تسجل الـ Pipeline Behaviors بالترتيب الصحيح داخل الـ Dependency Injection Container؟"]'::jsonb, '[{"title":"Microsoft Learn — Cross-cutting concerns in ASP.NET Core microservices","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/net-core-net-framework-differences/"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narchnet-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي سلوكيات خط الأنابيب (Pipeline Behaviors) في MediatR وكيف تطبق البرمجة الموجهة للجوانب (AOP)؟' or l.short_answer is distinct from 'وسائط داخلية تعترض كل طلب IRequest قبل وصوله للـ Handler، وتستخدم لتنفيذ مهام متقاطعة مثل التحقق من المدخلات بـ FluentValidation، والتسجيل، والكاش، وإدارة المعاملات.' or l.explanation is distinct from 'بدلاً من كتابة كود فحص الصلاحيات أو قياس زمن التنفيذ داخل كل معالج بشكل متكرر، تتيح فئة IPipelineBehavior<TRequest, TResponse> اعتراض أي طلب يمر عبر MediatR. يمكنك مثلاً إنشاء ValidationBehavior يفحص ما إذا كان هناك أي قواعد FluentValidation للطلب ويرمي ValidationException قبل تشغيل الـ Handler، محافظاً على نقاء منطق الأعمال.' or l.code_example is distinct from 'public class LoggingBehavior<TRequest, TResponse>(ILogger<TRequest> logger)
    : IPipelineBehavior<TRequest, TResponse> where TRequest : notnull {
    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken ct) {
        logger.LogInformation("Handling {RequestName}", typeof(TRequest).Name);
        var response = await next();
        logger.LogInformation("Handled {RequestName}", typeof(TRequest).Name);
        return response;
    }
}' or l.common_mistakes is distinct from '["نسيان استدعاء await next() داخل الـ Behavior مما يقطع تدفق الطلب ويمنع وصوله للـ Handler."]'::jsonb or l.follow_up_questions is distinct from '["كيف تسجل الـ Pipeline Behaviors بالترتيب الصحيح داخل الـ Dependency Injection Container؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Cross-cutting concerns in ASP.NET Core microservices","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/net-core-net-framework-differences/"}]'::jsonb)) then raise exception 'Question narchnet-003 ar content changed; create a new revision before seeding'; end if; end $$;
