insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين الكيانات (Entities) وكائنات القيمة (Value Objects) وجذور التجميع (Aggregate Roots) في DDD؟', 'الـ Entity تتميز بهوية فريدة مستمرة (Id)، والـ Value Object تتميز بقيمها وليس لها هوية، والـ Aggregate Root هو الكيان القائد الذي يضمن اتساق وتعديل كامل المجموعة التابعة له.', 'في التصميم الموجه بالنطاق (DDD)، يمثل الـ Aggregate Root (مثل Order) الحارس الوحيد لقواعد العمل؛ فلا يمكن لكود خارجي تعديل بنود الطلب (OrderItems) مباشرة بل من خلال دوال الـ Order (مثل order.AddItem(...)) لضمان عدم خرق أي قاعدة عمل (Invariants). كائنات القيمة (مثل Address أو Money) تعامل كـ Immutable Records وتتطابق بتطابق قيمها.', 'public class Order : AggregateRoot {
    public OrderId Id { get; private set; }
    private readonly List<OrderItem> _items = [];
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();

    public void AddItem(ProductId productId, decimal price, int quantity) {
        // حماية قواعد العمل والاتساق الذاتي
        _items.Add(new OrderItem(productId, price, quantity));
    }
}', '["كشف مجموعات الكائنات التابعة كـ public List<T> مع إمكانية التعديل المباشر من الخارج مما يكسر حماية الـ Aggregate Root."]'::jsonb, '["كيف تطلق كائنات الـ Aggregate أحداث النطاق (Domain Events) لإشعار الأنظمة الأخرى بالتغييرات؟"]'::jsonb, '[{"title":"Microsoft Learn — Design a DDD-oriented microservice","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narchnet-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين الكيانات (Entities) وكائنات القيمة (Value Objects) وجذور التجميع (Aggregate Roots) في DDD؟' or l.short_answer is distinct from 'الـ Entity تتميز بهوية فريدة مستمرة (Id)، والـ Value Object تتميز بقيمها وليس لها هوية، والـ Aggregate Root هو الكيان القائد الذي يضمن اتساق وتعديل كامل المجموعة التابعة له.' or l.explanation is distinct from 'في التصميم الموجه بالنطاق (DDD)، يمثل الـ Aggregate Root (مثل Order) الحارس الوحيد لقواعد العمل؛ فلا يمكن لكود خارجي تعديل بنود الطلب (OrderItems) مباشرة بل من خلال دوال الـ Order (مثل order.AddItem(...)) لضمان عدم خرق أي قاعدة عمل (Invariants). كائنات القيمة (مثل Address أو Money) تعامل كـ Immutable Records وتتطابق بتطابق قيمها.' or l.code_example is distinct from 'public class Order : AggregateRoot {
    public OrderId Id { get; private set; }
    private readonly List<OrderItem> _items = [];
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();

    public void AddItem(ProductId productId, decimal price, int quantity) {
        // حماية قواعد العمل والاتساق الذاتي
        _items.Add(new OrderItem(productId, price, quantity));
    }
}' or l.common_mistakes is distinct from '["كشف مجموعات الكائنات التابعة كـ public List<T> مع إمكانية التعديل المباشر من الخارج مما يكسر حماية الـ Aggregate Root."]'::jsonb or l.follow_up_questions is distinct from '["كيف تطلق كائنات الـ Aggregate أحداث النطاق (Domain Events) لإشعار الأنظمة الأخرى بالتغييرات؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — Design a DDD-oriented microservice","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"}]'::jsonb)) then raise exception 'Question narchnet-004 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a .NET developer know about Dotnet Domain Driven Design Entities Aggregates?', 'This question checks the core Dotnet Domain Driven Design Entities Aggregates concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.', 'Explain Dotnet Domain Driven Design Entities Aggregates with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'public class Order : AggregateRoot {
    public OrderId Id { get; private set; }
    private readonly List<OrderItem> _items = [];
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();

    public void AddItem(ProductId productId, decimal price, int quantity) {
        // حماية قواعد العمل والاتساق الذاتي
        _items.Add(new OrderItem(productId, price, quantity));
    }
}', '["Missing the key trade-off in Dotnet Domain Driven Design Entities Aggregates (point 1)."]'::jsonb, '["How would you apply Dotnet Domain Driven Design Entities Aggregates in a production .NET app (follow-up 1)?"]'::jsonb, '[{"title":"Microsoft Learn — Design a DDD-oriented microservice","url":"https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
