insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو نمط استقصاء الأحداث (Event Sourcing) وكيف تختلف قواعد بيانات الأحداث عن قواعد البيانات التقليدية؟', 'بدلاً من حفظ الحالة الحالية فقط، يسجل النظام كل تغيير كحدث تاريخي غير قابل للتعديل (Append-Only Event)، وتُبنى الحالة الحالية بإعادة تطبيق سلسلة الأحداث من البداية.', 'في الأنظمة المالية وتتبع الشحنات، لا يكفي معرفة أن رصيد الحساب 500$؛ بل يجب معرفة السجل الكامل لكل عملية إيداع وسحب وقعت تاريخياً. يوفر Event Sourcing سجلاً تدقيقياً كاملاً لا يمكن تزويره. توفر مكتبات مثل Marten (فوق PostgreSQL) أو EventStoreDB دعماً أصيلاً لتسجيل الأحداث وتوليد إسقاطات القراءة السريعة (Read Projections) تلقائياً.', '// الأحداث المخزنة غير القابلة للتعديل
public record AccountCreated(Guid Id, string Owner);
public record MoneyDeposited(Guid Id, decimal Amount);
public record MoneyWithdrawn(Guid Id, decimal Amount);', '["تعديل أو حذف أحداث سابقة مخزنة في الـ Event Store؛ سجل الأحداث ثابت للأبد (Immutable) ويتم التصحيح بإضافة حدث جديد."]'::jsonb, '["كيف تحل مشكلة بطء بناء الحالة للحسابات التي تمتلك ملايين الأحداث باستخدام الـ Snapshots؟"]'::jsonb, '[{"title":"Microsoft Learn — Event Sourcing pattern","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/event-sourcing"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
