insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق التتبع والمراقبة الموزعة (Distributed Tracing) باستخدام فئة Activity و OpenTelemetry في .NET؟', 'فئة Activity هي التمثيل المدمج لـ Span في .NET؛ وتجمع OpenTelemetry مسارات الطلبات عبر الخدمات وتمرر ترويسة traceparent القياسية بين الخوادم.', 'تتمتع .NET بدعم استثنائي أصيل للـ Tracing عبر System.Diagnostics.ActivitySource. عند تفعيل OpenTelemetry SDK، يتم تتبع مسار كل طلب HTTP، واستعلام SQL في EF Core، ورسالة في MassTransit تلقائياً، وتمرير معرف الـ TraceId عبر ترويسات W3C Trace Context، لتظهر الرحلة الكاملة للطلب كمخطط زمني شامل على لوحات Jaeger و Aspire Dashboard.', 'builder.Services.AddOpenTelemetry()
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddEntityFrameworkCoreInstrumentation()
        .AddOtlpExporter());', '["عدم تتبع ونقل ترويسات الـ Tracing داخل خيوط المهام الخلفية أو قنوات الـ Channels."]'::jsonb, '["كيف تنشئ ActivitySource مخصصاً داخل نطاق عملك لقياس فترات العمليات الحسابية الخاصة؟"]'::jsonb, '[{"title":"Microsoft Learn — .NET distributed tracing","url":"https://learn.microsoft.com/en-us/dotnet/core/diagnostics/distributed-tracing"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
