insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو .NET Aspire وكيف يسهل بناء ومراقبة التطبيقات السحابية الموزعة (Cloud-Native)؟', 'إطار عمل يجمع بين تنسيق الخدمات محلياً (Orchestration)، ومكونات جاهزة مسبقاً (Components) مزودة بأفضل ممارسات الصمود، ولوحة تحكم مركزية للتشخيص.', 'أطلقت مايكروسوفت .NET Aspire لحل تعقيدات إدارة الـ Microservices في بيئات التطوير والسحاب. يتكون من: AppHost لتحديد العلاقات وتشغيل حاويات Redis وقواعد البيانات وخدمات الـ API تلقائياً، وحزم Aspire Components المجهزة مسبقاً بفحوصات الجاهزية (Health Checks) والتتبع الموزع ومكتبات Polly، ولوحة تحكم مدمجة (Aspire Dashboard) لمراقبة السجلات والمقاييس حياً.', '// AppHost/Program.cs
var builder = DistributedApplication.CreateBuilder(args);
var redis = builder.AddRedis("cache");
var postgres = builder.AddPostgres("db");
builder.AddProject<Projects.MyApi>("api")
       .WithReference(redis)
       .WithReference(postgres);
builder.Build().Run();', '["اعتبار .NET Aspire بديلاً عن Kubernetes؛ هو أداة تنسيق للتطوير وتبسيط البنية تترجم بسهولة لنشر Kubernetes أو Azure Container Apps."]'::jsonb, '["كيف يدعم .NET Aspire نشر التطبيقات السحابية عبر أداة azure developer cli (azd) بملف manifest موحد؟"]'::jsonb, '[{"title":"Microsoft Learn — .NET Aspire overview","url":"https://learn.microsoft.com/en-us/dotnet/aspire/get-started/aspire-overview"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'narchnet-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو .NET Aspire وكيف يسهل بناء ومراقبة التطبيقات السحابية الموزعة (Cloud-Native)؟' or l.short_answer is distinct from 'إطار عمل يجمع بين تنسيق الخدمات محلياً (Orchestration)، ومكونات جاهزة مسبقاً (Components) مزودة بأفضل ممارسات الصمود، ولوحة تحكم مركزية للتشخيص.' or l.explanation is distinct from 'أطلقت مايكروسوفت .NET Aspire لحل تعقيدات إدارة الـ Microservices في بيئات التطوير والسحاب. يتكون من: AppHost لتحديد العلاقات وتشغيل حاويات Redis وقواعد البيانات وخدمات الـ API تلقائياً، وحزم Aspire Components المجهزة مسبقاً بفحوصات الجاهزية (Health Checks) والتتبع الموزع ومكتبات Polly، ولوحة تحكم مدمجة (Aspire Dashboard) لمراقبة السجلات والمقاييس حياً.' or l.code_example is distinct from '// AppHost/Program.cs
var builder = DistributedApplication.CreateBuilder(args);
var redis = builder.AddRedis("cache");
var postgres = builder.AddPostgres("db");
builder.AddProject<Projects.MyApi>("api")
       .WithReference(redis)
       .WithReference(postgres);
builder.Build().Run();' or l.common_mistakes is distinct from '["اعتبار .NET Aspire بديلاً عن Kubernetes؛ هو أداة تنسيق للتطوير وتبسيط البنية تترجم بسهولة لنشر Kubernetes أو Azure Container Apps."]'::jsonb or l.follow_up_questions is distinct from '["كيف يدعم .NET Aspire نشر التطبيقات السحابية عبر أداة azure developer cli (azd) بملف manifest موحد؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Learn — .NET Aspire overview","url":"https://learn.microsoft.com/en-us/dotnet/aspire/get-started/aspire-overview"}]'::jsonb)) then raise exception 'Question narchnet-010 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a .NET developer know about Dotnet Aspire Cloud Native Orchestration?', 'This question checks the core Dotnet Aspire Cloud Native Orchestration concept and how to use it safely in C#, ASP.NET Core, and modern .NET runtime.', 'Explain Dotnet Aspire Cloud Native Orchestration with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// AppHost/Program.cs
var builder = DistributedApplication.CreateBuilder(args);
var redis = builder.AddRedis("cache");
var postgres = builder.AddPostgres("db");
builder.AddProject<Projects.MyApi>("api")
       .WithReference(redis)
       .WithReference(postgres);
builder.Build().Run();', '["Missing the key trade-off in Dotnet Aspire Cloud Native Orchestration (point 1)."]'::jsonb, '["How would you apply Dotnet Aspire Cloud Native Orchestration in a production .NET app (follow-up 1)?"]'::jsonb, '[{"title":"Microsoft Learn — .NET Aspire overview","url":"https://learn.microsoft.com/en-us/dotnet/aspire/get-started/aspire-overview"}]'::jsonb from public.question_revisions r where r.question_id = 'narchnet-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
