insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو Virtual DOM في ريأكت وكيف يعمل خوارزمية الـ Reconciliation (Diffing)؟', 'الـ Virtual DOM هو تمثيل خفيف في الذاكرة لشجرة DOM الحقيقية، تستخدمه خوارزمية Reconciliation لحساب الفروقات بدقة وإجراء أقل عدد ممكن من التعديلات المباشرة على متصفح الـ DOM.', 'عند تغير حالة مكون (State) في ريأكت، يتم إنشاء شجرة Virtual DOM جديدة. تقارن خوارزمية Diffing الشجرة الجديدة بالشجرة السابقة بناءً على فرضيتين: عناصر بنوعين مختلفين تنتج أشجاراً مختلفة، والمفاتيح (Keys) تتيح تتبع العناصر المستقرة عبر عمليات إعادة التصيير. بعد حساب الفروقات (Diffs)، يتم تطبيقها دفعة واحدة في خطوة Commit على الـ Real DOM.', '// مثال توضيحي لنمط عمل العناصر الافتراضية
function Welcome({ name }: { name: string }) {
  // يترجم JSX إلى React.createElement("h1", null, `مرحباً ${name}`)
  return <h1 className="greeting">مرحباً {name}</h1>;
}', '["الاعتقاد بأن Virtual DOM أسرع دائماً من المعالجة المباشرة بالـ DOM الخام دون اعتبار تكلفة المقارنة في الذاكرة."]'::jsonb, '["كيف يختلف محرك React Fiber الحديث عن محرك الـ Stack Reconciler القديم في جدولة الأولويات؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/preserving-and-resetting-state"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rcore-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو Virtual DOM في ريأكت وكيف يعمل خوارزمية الـ Reconciliation (Diffing)؟' or l.short_answer is distinct from 'الـ Virtual DOM هو تمثيل خفيف في الذاكرة لشجرة DOM الحقيقية، تستخدمه خوارزمية Reconciliation لحساب الفروقات بدقة وإجراء أقل عدد ممكن من التعديلات المباشرة على متصفح الـ DOM.' or l.explanation is distinct from 'عند تغير حالة مكون (State) في ريأكت، يتم إنشاء شجرة Virtual DOM جديدة. تقارن خوارزمية Diffing الشجرة الجديدة بالشجرة السابقة بناءً على فرضيتين: عناصر بنوعين مختلفين تنتج أشجاراً مختلفة، والمفاتيح (Keys) تتيح تتبع العناصر المستقرة عبر عمليات إعادة التصيير. بعد حساب الفروقات (Diffs)، يتم تطبيقها دفعة واحدة في خطوة Commit على الـ Real DOM.' or l.code_example is distinct from '// مثال توضيحي لنمط عمل العناصر الافتراضية
function Welcome({ name }: { name: string }) {
  // يترجم JSX إلى React.createElement("h1", null, `مرحباً ${name}`)
  return <h1 className="greeting">مرحباً {name}</h1>;
}' or l.common_mistakes is distinct from '["الاعتقاد بأن Virtual DOM أسرع دائماً من المعالجة المباشرة بالـ DOM الخام دون اعتبار تكلفة المقارنة في الذاكرة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يختلف محرك React Fiber الحديث عن محرك الـ Stack Reconciler القديم في جدولة الأولويات؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/preserving-and-resetting-state"}]'::jsonb)) then raise exception 'Question rcore-001 ar content changed; create a new revision before seeding'; end if; end $$;
