insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تعتبر الـ Keys مهمة جداً عند عرض القوائم وما مخاطر استخدام فهرس المصفوفة (Index) كـ Key؟', 'المفاتيح (Keys) تمكّن ريأكت من معرفة هوية العناصر الفريدة بين عمليات إعادة التصيير لمعرفة أيها أضيف أو أزيل أو تم تحريكه؛ استخدام الـ Index يؤدي لمشاكل في الحالة واختلال ترتيب المدخلات عند التعديل.', 'تعتمد خوارزمية الـ Diffing على الـ Key لمطابقة المكونات الفرعية عبر دورات الـ render. إذا استخدمت index المصفوفة كـ key وتمت إضافة عنصر في بداية القائمة أو حذف عنصر في المنتصف، يتغير فهرس جميع العناصر التالية، مما يجعل ريأكت تعيد استخدام نفس حالات المكونات الداخلية (مثل عناصر الـ input والـ animations) مع بيانات خاطئة.', '// الاستخدام السليم: استخدام معرف فريد وثابت
function TodoList({ todos }: { todos: { id: string; text: string }[] }) {
  return (
    <ul>
      {todos.map(todo => (
        <li key={todo.id}>{todo.text}</li>
      ))}
    </ul>
  );
}', '["استخدام Math.random() كـ key، مما يجبر ريأكت على تدمير وإعادة إنشاء الشجرة في كل render."]'::jsonb, '["متى يعتبر استخدام index كمفتاح مقبولاً وآمناً بنسبة 100%؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/rendering-lists"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rcore-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تعتبر الـ Keys مهمة جداً عند عرض القوائم وما مخاطر استخدام فهرس المصفوفة (Index) كـ Key؟' or l.short_answer is distinct from 'المفاتيح (Keys) تمكّن ريأكت من معرفة هوية العناصر الفريدة بين عمليات إعادة التصيير لمعرفة أيها أضيف أو أزيل أو تم تحريكه؛ استخدام الـ Index يؤدي لمشاكل في الحالة واختلال ترتيب المدخلات عند التعديل.' or l.explanation is distinct from 'تعتمد خوارزمية الـ Diffing على الـ Key لمطابقة المكونات الفرعية عبر دورات الـ render. إذا استخدمت index المصفوفة كـ key وتمت إضافة عنصر في بداية القائمة أو حذف عنصر في المنتصف، يتغير فهرس جميع العناصر التالية، مما يجعل ريأكت تعيد استخدام نفس حالات المكونات الداخلية (مثل عناصر الـ input والـ animations) مع بيانات خاطئة.' or l.code_example is distinct from '// الاستخدام السليم: استخدام معرف فريد وثابت
function TodoList({ todos }: { todos: { id: string; text: string }[] }) {
  return (
    <ul>
      {todos.map(todo => (
        <li key={todo.id}>{todo.text}</li>
      ))}
    </ul>
  );
}' or l.common_mistakes is distinct from '["استخدام Math.random() كـ key، مما يجبر ريأكت على تدمير وإعادة إنشاء الشجرة في كل render."]'::jsonb or l.follow_up_questions is distinct from '["متى يعتبر استخدام index كمفتاح مقبولاً وآمناً بنسبة 100%؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/rendering-lists"}]'::jsonb)) then raise exception 'Question rcore-002 ar content changed; create a new revision before seeding'; end if; end $$;
