insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو JSX وما الذي يحدث له خلف الكواليس أثناء عملية الـ Compilation؟', 'JSX هو امتداد نحوي لـ JavaScript يسمح بكتابة بنية تشبه HTML داخل الكود، ويقوم المترجم (مثل Babel أو SWC) بتحويله إلى استدعاءات دوال إنشاء العناصر (React.createElement أو jsx runtime).', 'JSX ليس لغة مستقلة ولا يفهمه المتصفح مباشرة. يقوم Babel أو مترجمات TypeScript بتحويل كل وسم JSX إلى استدعاء دالة مثل _jsx("div", { children: "Hello" }). هذه الدوال تعيد كائنات JavaScript عادية تسمى React Elements، والتي تصف نوع العنصر والـ props والأبناء.', '// كود JSX الأصلي:
const element = <button className="btn">انقر هنا</button>;

// ما يترجم إليه خلف الكواليس بواسطة React 17+ JSX Transform:
import { jsx as _jsx } from ''react/jsx-runtime'';
const compiled = _jsx("button", { className: "btn", children: "انقر هنا" });', '["الاعتقاد بأن JSX يكتب عناصر DOM حقيقية مباشرة في المتصفح، أو محاولة استخدام كلمات محجوزة مثل class و for بدلاً من className و htmlFor."]'::jsonb, '["ما الفرق بين الـ New JSX Transform الذي أُطلق في React 17 ونظام React.createElement القديم؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/writing-markup-with-jsx"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rcore-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو JSX وما الذي يحدث له خلف الكواليس أثناء عملية الـ Compilation؟' or l.short_answer is distinct from 'JSX هو امتداد نحوي لـ JavaScript يسمح بكتابة بنية تشبه HTML داخل الكود، ويقوم المترجم (مثل Babel أو SWC) بتحويله إلى استدعاءات دوال إنشاء العناصر (React.createElement أو jsx runtime).' or l.explanation is distinct from 'JSX ليس لغة مستقلة ولا يفهمه المتصفح مباشرة. يقوم Babel أو مترجمات TypeScript بتحويل كل وسم JSX إلى استدعاء دالة مثل _jsx("div", { children: "Hello" }). هذه الدوال تعيد كائنات JavaScript عادية تسمى React Elements، والتي تصف نوع العنصر والـ props والأبناء.' or l.code_example is distinct from '// كود JSX الأصلي:
const element = <button className="btn">انقر هنا</button>;

// ما يترجم إليه خلف الكواليس بواسطة React 17+ JSX Transform:
import { jsx as _jsx } from ''react/jsx-runtime'';
const compiled = _jsx("button", { className: "btn", children: "انقر هنا" });' or l.common_mistakes is distinct from '["الاعتقاد بأن JSX يكتب عناصر DOM حقيقية مباشرة في المتصفح، أو محاولة استخدام كلمات محجوزة مثل class و for بدلاً من className و htmlFor."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين الـ New JSX Transform الذي أُطلق في React 17 ونظام React.createElement القديم؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/writing-markup-with-jsx"}]'::jsonb)) then raise exception 'Question rcore-003 ar content changed; create a new revision before seeding'; end if; end $$;
