insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو مفهوم الـ Pure Components و Purity في دوال ريأكت (Pure Functions)؟', 'الدالة أو المكون النقي هو الذي ينتج دائماً نفس المخرجات لنفس المدخلات (Props) دون إحداث أي آثار جانبية (Side Effects) خارج نطاقه أثناء الـ Render.', 'في ريأكت، يجب أن تكون مرحلة التصيير (Render Phase) خالية من الآثار الجانبية. لا يجوز لمكون أثناء تنفيذه أن يغير متغيرات عامة سابقة، أو يرسل طلبات HTTP، أو يعدل DOM مباشرة. الآثار الجانبية يجب أن تقع فقط داخل Event Handlers أو useEffect.', '// مكون نقي: يعتمد فقط على الـ props
function Cup({ guest }: { guest: number }) {
  return <h2>كوب الشاي للضيف رقم #{guest}</h2>;
}', '["تعديل مصفوفة أو كائن ممرر في الـ props مباشرة داخل جسم الدالة (Mutation)."]'::jsonb, '["كيف يساعد StrictMode في كشف الدوال غير النقية عبر استدعائها مرتين في بيئة التطوير؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/keeping-components-pure"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rcore-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو مفهوم الـ Pure Components و Purity في دوال ريأكت (Pure Functions)؟' or l.short_answer is distinct from 'الدالة أو المكون النقي هو الذي ينتج دائماً نفس المخرجات لنفس المدخلات (Props) دون إحداث أي آثار جانبية (Side Effects) خارج نطاقه أثناء الـ Render.' or l.explanation is distinct from 'في ريأكت، يجب أن تكون مرحلة التصيير (Render Phase) خالية من الآثار الجانبية. لا يجوز لمكون أثناء تنفيذه أن يغير متغيرات عامة سابقة، أو يرسل طلبات HTTP، أو يعدل DOM مباشرة. الآثار الجانبية يجب أن تقع فقط داخل Event Handlers أو useEffect.' or l.code_example is distinct from '// مكون نقي: يعتمد فقط على الـ props
function Cup({ guest }: { guest: number }) {
  return <h2>كوب الشاي للضيف رقم #{guest}</h2>;
}' or l.common_mistakes is distinct from '["تعديل مصفوفة أو كائن ممرر في الـ props مباشرة داخل جسم الدالة (Mutation)."]'::jsonb or l.follow_up_questions is distinct from '["كيف يساعد StrictMode في كشف الدوال غير النقية عبر استدعائها مرتين في بيئة التطوير؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/keeping-components-pure"}]'::jsonb)) then raise exception 'Question rcore-004 ar content changed; create a new revision before seeding'; end if; end $$;
