insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو دور React Fiber وما الفرق بين Render Phase و Commit Phase؟', 'مرحلة Render تحسب التغييرات في الذاكرة ويمكن مقاطعتها وتأجيلها بواسطة Fiber لضمان استجابة الواجهة، بينما مرحلة Commit تطبق التغييرات على الـ DOM الحقيقي دفعة واحدة وتعمل بشكل متزامن دون مقاطعة.', 'محرك React Fiber يقسم العمل إلى وحدات عمل صغيرة (Fibers). خلال مرحلة Render، يقوم ريأكت باستدعاء المكونات ومقارنة الأشجار، ويمكنه إيقاف أو إرجاء التحديث إذا كانت هناك أحداث ذات أولوية أعلى (مثل إدخال المستخدم). بمجرد انتهاء الحسابات، تبدأ مرحلة Commit حيث يتم تحديث الـ DOM واستدعاء useLayoutEffect ثم useEffect.', '// تمثيل تسلسل المراحل
// 1. Render Phase (Pure, no DOM changes, interruptible):
//    استدعاء Component(props) -> إرجاع Virtual DOM -> حساب الفروقات (Fiber tree diff)
// 2. Commit Phase (Mutates DOM, non-interruptible):
//    تحديث الـ Real DOM -> تنفيذ useLayoutEffect -> تنفيذ useEffect', '["وضع آثار جانبية كالـ fetch أو تغيير document.title مباشرة في مرحلة الـ Render بدلاً من useEffect."]'::jsonb, '["كيف استفادت ميزات Concurrent React (مثل useTransition و Suspense) من بنية Fiber القابلة للمقاطعة؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/render-and-commit"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rcore-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو دور React Fiber وما الفرق بين Render Phase و Commit Phase؟' or l.short_answer is distinct from 'مرحلة Render تحسب التغييرات في الذاكرة ويمكن مقاطعتها وتأجيلها بواسطة Fiber لضمان استجابة الواجهة، بينما مرحلة Commit تطبق التغييرات على الـ DOM الحقيقي دفعة واحدة وتعمل بشكل متزامن دون مقاطعة.' or l.explanation is distinct from 'محرك React Fiber يقسم العمل إلى وحدات عمل صغيرة (Fibers). خلال مرحلة Render، يقوم ريأكت باستدعاء المكونات ومقارنة الأشجار، ويمكنه إيقاف أو إرجاء التحديث إذا كانت هناك أحداث ذات أولوية أعلى (مثل إدخال المستخدم). بمجرد انتهاء الحسابات، تبدأ مرحلة Commit حيث يتم تحديث الـ DOM واستدعاء useLayoutEffect ثم useEffect.' or l.code_example is distinct from '// تمثيل تسلسل المراحل
// 1. Render Phase (Pure, no DOM changes, interruptible):
//    استدعاء Component(props) -> إرجاع Virtual DOM -> حساب الفروقات (Fiber tree diff)
// 2. Commit Phase (Mutates DOM, non-interruptible):
//    تحديث الـ Real DOM -> تنفيذ useLayoutEffect -> تنفيذ useEffect' or l.common_mistakes is distinct from '["وضع آثار جانبية كالـ fetch أو تغيير document.title مباشرة في مرحلة الـ Render بدلاً من useEffect."]'::jsonb or l.follow_up_questions is distinct from '["كيف استفادت ميزات Concurrent React (مثل useTransition و Suspense) من بنية Fiber القابلة للمقاطعة؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/render-and-commit"}]'::jsonb)) then raise exception 'Question rcore-005 ar content changed; create a new revision before seeding'; end if; end $$;
