insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل الـ Event Pooling والـ SyntheticEvent System في ريأكت؟', 'يوفر ريأكت كائناً موحداً يدعى SyntheticEvent يغلف أحداث المتصفح الأصلية لضمان توافق سلوك الأحداث عبر كافة المتصفحات، مع إدارة الأحداث عبر Event Delegation عند جذر التطبيق.', 'بدلاً من ربط event listener لكل عنصر DOM على حدة، يقوم ريأكت بتسجيل مستمع واحد عند جذر الـ DOM (root container). عند وقوع الحدث، يتم توجيهه للمكون المناسب. كان هناك مفهوم Event Pooling لإعادة تدوير كائنات الأحداث في React 16 وما قبله، لكن تم إلغاؤه في React 17 لتبسيط التعامل مع العمليات غير المتزامنة.', 'function Button() {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    // e هو SyntheticEvent موحد عبر كل المتصفحات
    console.log("إحداثيات النقر:", e.clientX, e.clientY);
  };

  return <button onClick={handleClick}>تسجيل الحدث</button>;
}', '["محاولة استدعاء e.persist() في React 17+ حيث أصبح كائن الحدث لا يخضع للـ Pooling ولا يتم مسح حقوله تلقائياً."]'::jsonb, '["أين يتم تثبيت معالجات الأحداث بالضبط في React 17+ مقارنة بنظام document القديم في React 16؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/responding-to-events"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rcore-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل الـ Event Pooling والـ SyntheticEvent System في ريأكت؟' or l.short_answer is distinct from 'يوفر ريأكت كائناً موحداً يدعى SyntheticEvent يغلف أحداث المتصفح الأصلية لضمان توافق سلوك الأحداث عبر كافة المتصفحات، مع إدارة الأحداث عبر Event Delegation عند جذر التطبيق.' or l.explanation is distinct from 'بدلاً من ربط event listener لكل عنصر DOM على حدة، يقوم ريأكت بتسجيل مستمع واحد عند جذر الـ DOM (root container). عند وقوع الحدث، يتم توجيهه للمكون المناسب. كان هناك مفهوم Event Pooling لإعادة تدوير كائنات الأحداث في React 16 وما قبله، لكن تم إلغاؤه في React 17 لتبسيط التعامل مع العمليات غير المتزامنة.' or l.code_example is distinct from 'function Button() {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    // e هو SyntheticEvent موحد عبر كل المتصفحات
    console.log("إحداثيات النقر:", e.clientX, e.clientY);
  };

  return <button onClick={handleClick}>تسجيل الحدث</button>;
}' or l.common_mistakes is distinct from '["محاولة استدعاء e.persist() في React 17+ حيث أصبح كائن الحدث لا يخضع للـ Pooling ولا يتم مسح حقوله تلقائياً."]'::jsonb or l.follow_up_questions is distinct from '["أين يتم تثبيت معالجات الأحداث بالضبط في React 17+ مقارنة بنظام document القديم في React 16؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/learn/responding-to-events"}]'::jsonb)) then raise exception 'Question rcore-006 ar content changed; create a new revision before seeding'; end if; end $$;
