function Modal({ children, isOpen }: { children: React.ReactNode; isOpen: boolean }) {
  if (!isOpen) return null;

  const modalRoot = document.getElementById(''modal-root'') || document.body;
  return createPortal(
    <div className="modal-backdrop">
      <div className="modal-content">{children}</div>
    </div>,
    modalRoot
  );
}' or l.common_mistakes is distinct from '["نسيان أن الـ Events الصادرة من داخل الـ Portal ستتصاعد (Bubble) عبر شجرة مكونات ريأكت إلى المكون الأب حتى لو كان الـ DOM منفصلاً تماماً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتصرف الـ Context Providers مع المكونات المعروضة عبر createPortal؟"]'::jsonb or l.sources is distinct from '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/reference/react-dom/createPortal"}]'::jsonb)) then raise exception 'Question rcore-007 ar content changed; create a new revision before seeding'; end if; end $$;
