insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الـ StrictMode وما هي الفحوصات والتدقيقات التي يجريها في بيئة التطوير؟', 'الـ StrictMode هو أداة تساعد المطورين على رصد الممارسات القديمة والمشاكل الخفية في الكود، حيث يقوم بإعادة تصيير المكونات وإعادة تشغيل الـ Effects مرتين في بيئة التطوير.', 'لا ينتج StrictMode أي واجهة مرئية في الـ DOM. في بيئة التطوير فقط، يقوم بتشغيل الـ render مرتين لاكتشاف الدوال غير النقية (Impure Functions)، وتشغيل Setup والـ Cleanup في useEffect مرتين للتأكد من التخلص من الاشتراكات وتسريبات الذاكرة، بالإضافة للتحذير من استخدام دوال دورة الحياة المهجورة أو findDOMNode.', 'import { StrictMode } from ''react'';
import { createRoot } from ''react-dom/client'';

const root = createRoot(document.getElementById(''root'')!);
root.render(
  <StrictMode>
    <App />
  </StrictMode>
);', '["الاعتقاد بأن استدعاء useEffect مرتين هو خطأ في ريأكت ومحاولة تعطيل StrictMode بدلاً من كتابة دالة cleanup سليمة."]'::jsonb, '["هل يؤثر StrictMode على أداء تطبيق ريأكت النهائي في بيئة الإنتاج (Production)؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/reference/react/StrictMode"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
