insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو مبدأ الـ Lifting State Up ومتى نلجأ إليه؟', 'هو نقل الحالة المشتركة إلى أقرب سلف (Ancestor) مشترك بين عدة مكونات تحتاج للتزامن مع نفس البيانات وتعديلها.', 'عندما يحتاج مكونان شقيقان للوصول لنفس البيانات أو تعديلها معاً، بدلاً من تكرار الحالة أو محاولة مزامنة حالتين محليتين، يتم رفع الحالة إلى المكون الأب المشترك وتمرير القيمة الحالية ودالة التحديث عبر الـ props.', '// رفع حالة الفلتر للأب المشترك
function FilterableList() {
  const [filter, setFilter] = useState('''');

  return (
    <div>
      <SearchBar filter={filter} onFilterChange={setFilter} />
      <ProductList filter={filter} />
    </div>
  );
