insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الـ Error Boundaries وكيف تتعامل مع الأخطاء غير المتوقعة في شجرة المكونات؟', 'هي مكونات خاصة تعترض أخطاء JavaScript في شجرة المكونات التابعة لها أثناء الـ Render و lifecycle methods، وتعرض واجهة بديلة (Fallback UI) دون انهيار التطبيق كاملاً.', 'يتم إنشاء الـ Error Boundary باستخدام Class Component يطبق إحدى دالتي getDerivedStateFromError (لتحديث الـ state وعرض واجهة بديلة) أو componentDidCatch (لتسجيل تفاصيل الخطأ لخدمات المراقبة). لا تعترض الـ Error Boundaries أخطاء معالجات الأحداث (Event Handlers) أو العمليات غير المتزامنة كـ setTimeout.', 'import React, { Component, ReactNode } from ''react'';

interface Props { children: ReactNode; fallback: ReactNode }
interface State { hasError: boolean }

class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false };

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error("خطأ تم التقاطه في الواجهة:", error, info.componentStack);
  }

  render() {
    if (this.state.hasError) return this.props.fallback;
    return this.props.children;
  }
}', '["محاولة استخدام try/catch داخل دالة الـ JSX المرتجعة للتعامل مع أخطاء تصيير المكونات الفرعية."]'::jsonb, '["لماذا لا يوجد حتى الآن Hook مدمج بديل لـ Error Boundaries وما هي مكتبة react-error-boundary المستخدمة عادة؟"]'::jsonb, '[{"title":"React Core & Virtual DOM Documentation","url":"https://react.dev/reference/react/Component#catching-rendering-errors-with-an-error-boundary"}]'::jsonb from public.question_revisions r where r.question_id = 'rcore-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
