insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين تمرير قيمة مباشرة لدالة setState وتمرير دالة تحديث وظيفية (Updater Function)؟', 'تمرير دالة تحديث (Functional Updater) يضمن قراءة أحدث حالة متوفرة في الطابور وحساب القيمة الجديدة بناءً عليها حتى مع وجود تحديثات مجمعة متعددة أو إغلاقات قديمة (Stale Closures).', 'التحديث في ريأكت غير متزامن ومجمع (Batched). إذا قمت باستدعاء setCount(count + 1) ثلاث مرات متتالية داخل نفس معالج الحدث، فستقرأ جميعها نفس قيمة count الأولية وتزيدها بمقدار 1 فقط. أما setCount(c => c + 1) فتأخذ القيمة السابقة من طابور التحديثات وتضمن زيادة القيمة ثلاث مرات.', '// مثال الزيادة التراكمية الصحيحة
function Counter() {
  const [count, setCount] = useState(0);

  const incrementThreeTimes = () => {
    setCount(prev => prev + 1);
    setCount(prev => prev + 1);
    setCount(prev => prev + 1); // النتيجة النهائية ستكون 3
  };

  return <button onClick={incrementThreeTimes}>القيمة: {count}</button>;
}', '["استخدام setCount(count + 1) داخل دوال غير متزامنة مثل setTimeout أو عند توالي العمليات، مما يسبب مشكلة Stale State."]'::jsonb, '["كيف تعمل ميزة Automatic Batching التي تم تطبيقها في React 18 عبر جميع معالجات الأحداث والـ Promises؟"]'::jsonb, '[{"title":"Hooks Fundamentals Documentation","url":"https://react.dev/reference/react/useState#updating-state-based-on-the-previous-state"}]'::jsonb from public.question_revisions r where r.question_id = 'rhook-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rhook-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين تمرير قيمة مباشرة لدالة setState وتمرير دالة تحديث وظيفية (Updater Function)؟' or l.short_answer is distinct from 'تمرير دالة تحديث (Functional Updater) يضمن قراءة أحدث حالة متوفرة في الطابور وحساب القيمة الجديدة بناءً عليها حتى مع وجود تحديثات مجمعة متعددة أو إغلاقات قديمة (Stale Closures).' or l.explanation is distinct from 'التحديث في ريأكت غير متزامن ومجمع (Batched). إذا قمت باستدعاء setCount(count + 1) ثلاث مرات متتالية داخل نفس معالج الحدث، فستقرأ جميعها نفس قيمة count الأولية وتزيدها بمقدار 1 فقط. أما setCount(c => c + 1) فتأخذ القيمة السابقة من طابور التحديثات وتضمن زيادة القيمة ثلاث مرات.' or l.code_example is distinct from '// مثال الزيادة التراكمية الصحيحة
function Counter() {
  const [count, setCount] = useState(0);

  const incrementThreeTimes = () => {
    setCount(prev => prev + 1);
    setCount(prev => prev + 1);
    setCount(prev => prev + 1); // النتيجة النهائية ستكون 3
  };

  return <button onClick={incrementThreeTimes}>القيمة: {count}</button>;
}' or l.common_mistakes is distinct from '["استخدام setCount(count + 1) داخل دوال غير متزامنة مثل setTimeout أو عند توالي العمليات، مما يسبب مشكلة Stale State."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل ميزة Automatic Batching التي تم تطبيقها في React 18 عبر جميع معالجات الأحداث والـ Promises؟"]'::jsonb or l.sources is distinct from '[{"title":"Hooks Fundamentals Documentation","url":"https://react.dev/reference/react/useState#updating-state-based-on-the-previous-state"}]'::jsonb)) then raise exception 'Question rhook-002 ar content changed; create a new revision before seeding'; end if; end $$;
