insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى يجب استخدام useRef وما الفارق الجوهري بينه وبين useState؟', 'يستخدم useRef لتخزين قيم قابلة للتعديل تدوم طوال عمر المكون دون التسبب في إعادة التصيير (Re-render) عند تعديلها، وكذلك للوصول المباشر لعقد الـ DOM.', 'كائن الـ ref هو كائن JavaScript عادي يحتوي على خاصية .current. تعديل ref.current لا يشعر ريأكت بحدوث تغيير ولذلك لا يطلق دورة تصيير جديدة. يستخدم لتخزين معرّفات الـ Timers، وتخزين الحالة السابقة، والتحكم بالتركيز والوسائط داخل عناصر الـ DOM مباشرة.', 'function TextInputWithFocusButton() {
  const inputEl = useRef<HTMLInputElement>(null);

  const onButtonClick = () => {
    // الوصول المباشر لعنصر الـ DOM وتركيز المؤشر عليه
    inputEl.current?.focus();
  };

  return (
    <>
      <input ref={inputEl} type="text" />
      <button onClick={onButtonClick}>تركيز المؤشر</button>
    </>
  );
}', '["قراءة أو كتابة ref.current أثناء مرحلة الـ Render بدلاً من معالجات الأحداث أو الـ Effects."]'::jsonb, '["ما الفرق بين Callback Refs والـ Object Refs في التعامل مع القوائم الديناميكية؟"]'::jsonb, '[{"title":"Hooks Fundamentals Documentation","url":"https://react.dev/reference/react/useRef"}]'::jsonb from public.question_revisions r where r.question_id = 'rhook-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
