insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو useReducer ومتى يفضل اختياره كبديل لـ useState؟', 'هو hook لإدارة الحالات المعقدة التي تتضمن انتقالات حالات متعددة أو عندما تعتمد الحالة التالية على خطوات متفرقة، حيث يفصل منطق تعديل الحالة في دالة Reducer نقية ومستقلة.', 'يتبع useReducer نمط Redux، حيث يستقبل دالة reducer بصيغة (state, action) => newState مع حالة ابتدائية، ويعيد [state, dispatch]. يفضل استخدامه عندما تتألف الحالة من كائن معقد ذي حقول متداخلة، أو عندما يكون منطق التحديث قابلاً للاختبار بمعزل عن المكون، أو عند الحاجة لتفادي تمرير callbacks متعددة واستبدالها بدالة dispatch مستقرة.', 'type Action = { type: ''inc'' } | { type: ''dec'' } | { type: ''reset'' };

function reducer(state: number, action: Action): number {
  switch (action.type) {
    case ''inc'': return state + 1;
    case ''dec'': return state - 1;
    case ''reset'': return 0;
    default: return state;
  }
}

function Counter() {
  const [count, dispatch] = useReducer(reducer, 0);
  return (
    <div>
      <p>العدد: {count}</p>
      <button onClick={() => dispatch({ type: ''inc'' })}>+</button>
      <button onClick={() => dispatch({ type: ''reset'' })}>إعادة ضبط</button>
    </div>
  );
}', '["تنفيذ آثار جانبية (كالـ API calls) مباشرة داخل دالة الـ reducer بدلاً من إبقائها دالة نقية 100%."]'::jsonb, '["كيف يسهل useReducer تحسين الأداء عند تمرير dispatch لأسفل شجرة المكونات العميقة بدلاً من دوال الـ callbacks؟"]'::jsonb, '[{"title":"Hooks Fundamentals Documentation","url":"https://react.dev/reference/react/useReducer"}]'::jsonb from public.question_revisions r where r.question_id = 'rhook-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rhook-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو useReducer ومتى يفضل اختياره كبديل لـ useState؟' or l.short_answer is distinct from 'هو hook لإدارة الحالات المعقدة التي تتضمن انتقالات حالات متعددة أو عندما تعتمد الحالة التالية على خطوات متفرقة، حيث يفصل منطق تعديل الحالة في دالة Reducer نقية ومستقلة.' or l.explanation is distinct from 'يتبع useReducer نمط Redux، حيث يستقبل دالة reducer بصيغة (state, action) => newState مع حالة ابتدائية، ويعيد [state, dispatch]. يفضل استخدامه عندما تتألف الحالة من كائن معقد ذي حقول متداخلة، أو عندما يكون منطق التحديث قابلاً للاختبار بمعزل عن المكون، أو عند الحاجة لتفادي تمرير callbacks متعددة واستبدالها بدالة dispatch مستقرة.' or l.code_example is distinct from 'type Action = { type: ''inc'' } | { type: ''dec'' } | { type: ''reset'' };

function reducer(state: number, action: Action): number {
  switch (action.type) {
    case ''inc'': return state + 1;
    case ''dec'': return state - 1;
    case ''reset'': return 0;
    default: return state;
  }
}

function Counter() {
