insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو دور useSyncExternalStore ولماذا تم تقديمه في React 18 لحل مشكلة الـ Tearing؟', 'يقوم useSyncExternalStore بالاشتراك في مخازن البيانات الخارجية (External Stores) بشكل متزامن لمنع ظاهرة Tearing الناتجة عن تعديل البيانات أثناء تشغيل التحديثات المتزامنة المقاطعة (Concurrent Rendering).', 'في الوضع التوافقي (Concurrent Mode)، يمكن لريأكت مقاطعة الـ render واستئنافه لاحقاً. إذا تغير مصدر بيانات خارجي (مثل Redux أو window.history) أثناء المقاطعة، قد تعرض بعض المكونات القيمة القديمة بينما تعرض مكونات أخرى القيمة الجديدة على نفس الشاشة، وهو ما يعرف بالـ Tearing. يضمن هذا الـ hook قراءة متسقة ذرية.', 'import { useSyncExternalStore } from ''react'';

function subscribe(callback: () => void) {
  window.addEventListener(''online'', callback);
  window.addEventListener(''offline'', callback);
  return () => {
    window.removeEventListener(''online'', callback);
    window.removeEventListener(''offline'', callback);
  };
}

function useOnlineStatus() {
  return useSyncExternalStore(
    subscribe,
    () => navigator.onLine,
    () => true // القيمة الافتراضية على الخادم أثناء SSR
  );
}', '["إرجاع كائن جديد دائماً في دالة getSnapshot مما يدخل المكون في حلقة لا نهائية من إعادة التصيير."]'::jsonb, '["كيف تستفيد مكتبات الحالة كـ Redux و Zustand من useSyncExternalStore؟"]'::jsonb, '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/reference/react/useSyncExternalStore"}]'::jsonb from public.question_revisions r where r.question_id = 'rhookadv-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
