insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو useDeferredValue وكيف يختلف عن مفهوم الـ Debounce / Throttle التقليدي؟', 'يقوم useDeferredValue بتأجيل تحديث جزء من الشاشة ليتبع التحديث العاجل تلقائياً بناءً على سرعة معالج الجهاز، دون فرض مهلة زمنية ثابتة (Timeout) كما يفعل Debounce.', 'يقبل useDeferredValue قيمة ويعيد نسخة مؤجلة منها. أثناء الـ render السريع، يحتفظ بالقيمة القديمة حتى ينتهي المتصفح من العمل العاجل، ثم يطلق عملية render بالخلفية بالقيمة الجديدة فور توفر طاقة المعالجة. هذا يوفر تجربة أكثر مرونة وتكيفاً مع أجهزة المستخدمين مقارنة بفترات التأخير الثابتة (e.g. 300ms).', 'function SearchPage() {
  const [query, setQuery] = useState('''');
  const deferredQuery = useDeferredValue(query);

  return (
    <div>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      {/* القائمة الثقيلة تتلقى القيمة المؤجلة لمنع تجميد حقل الإدخال */}
      <SlowList search={deferredQuery} />
    </div>
  );
}', '["الاعتقاد بأن useDeferredValue يمنع استدعاءات الـ Network عند كتابة نصوص سريعة بدلاً من دوره الأساسي في تخفيف عبء الـ CPU Rendering."]'::jsonb, '["متى ندمج بين Debouncing للطلبات الشبكية و useDeferredValue لتصيير القوائم الثقيلة؟"]'::jsonb, '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/reference/react/useDeferredValue"}]'::jsonb from public.question_revisions r where r.question_id = 'rhookadv-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
