insert into public.interview_questions (id, slug, track_id, difficulty) values ('rhookadv-006', 'react-custom-hooks-debounce-timers-006', 'react', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('rhookadv-006', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم Custom Hook للـ Debouncing للقيم أو الدوال مع إلغاء العمليات السابقة؟', 'نصمم Hook يستقبل القيمة ومدة التأخير، ويستخدم useState للقيمة المؤجلة مع useEffect يحتوي على setTimeout لإطلاق التحديث ودالة cleanup تقوم بـ clearTimeout.', 'يعمل Hook التهدئة (Debounce) على تجميع التغييرات المتكررة وتأجيل تنفيذها حتى يستقر التفاعل لفترة زمنية محددة. بفضل آلية الـ cleanup في useEffect، يتم إلغاء الـ timer السابق في كل مرة تتغير فيها القيمة قبل انقضاء المهلة.', 'function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
}', '["عدم توفير دالة تنظيف للـ timeout مما يسبب تشغيل استدعاءات متأخرة متراكبة."]'::jsonb, '["كيف نحول هذا النمط ليعمل مع الدوال الإجرائية بدلاً من مجرد تأخير القيم المتغيرة؟"]'::jsonb, '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/learn/reusing-logic-with-custom-hooks"}]'::jsonb from public.question_revisions r where r.question_id = 'rhookadv-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rhookadv-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم Custom Hook للـ Debouncing للقيم أو الدوال مع إلغاء العمليات السابقة؟' or l.short_answer is distinct from 'نصمم Hook يستقبل القيمة ومدة التأخير، ويستخدم useState للقيمة المؤجلة مع useEffect يحتوي على setTimeout لإطلاق التحديث ودالة cleanup تقوم بـ clearTimeout.' or l.explanation is distinct from 'يعمل Hook التهدئة (Debounce) على تجميع التغييرات المتكررة وتأجيل تنفيذها حتى يستقر التفاعل لفترة زمنية محددة. بفضل آلية الـ cleanup في useEffect، يتم إلغاء الـ timer السابق في كل مرة تتغير فيها القيمة قبل انقضاء المهلة.' or l.code_example is distinct from 'function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
}' or l.common_mistakes is distinct from '["عدم توفير دالة تنظيف للـ timeout مما يسبب تشغيل استدعاءات متأخرة متراكبة."]'::jsonb or l.follow_up_questions is distinct from '["كيف نحول هذا النمط ليعمل مع الدوال الإجرائية بدلاً من مجرد تأخير القيم المتغيرة؟"]'::jsonb or l.sources is distinct from '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/learn/reusing-logic-with-custom-hooks"}]'::jsonb)) then raise exception 'Question rhookadv-006 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a React developer know about React Custom Hooks Debounce Timers 006?', 'This question checks the core React Custom Hooks Debounce Timers 006 concept and how to use it safely in React, modern hooks, and frontend architecture.', 'Explain React Custom Hooks Debounce Timers 006 with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'function useDebounce<T>(value: T, delay: number): T {
