// استخدام حصري في مكتبات التنسيق CSS-in-JS
function useCSS(rule: string) {
  useInsertionEffect(() => {
    const style = document.createElement(''style'');
    style.textContent = rule;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, [rule]);
