insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني Custom Hook للـ Infinite Scroll باستخدام IntersectionObserver؟', 'ننشئ Hook يراقب عنصراً مستهدفاً (Sentinel Ref) في أسفل القائمة، وعند تقاطعه مع الـ viewport يطلق دالة جلب المزيد من البيانات تلقائياً.', 'باستخدام IntersectionObserver داخل useEffect مع تنظيف المراقب عند فك المكون، نقوم بفحص ظهور العنصر الأخير. يفيد تمرير حالات مثل hasMore و isLoading لمنع تكرار إطلاق الطلبات الشبكية أثناء انتظار الاستجابة أو عند استنفاد كافة البيانات.', 'function useInfiniteScroll(onLoadMore: () => void, hasMore: boolean, loading: boolean) {
  const sentinelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!hasMore || loading) return;
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        onLoadMore();
      }
    });

    if (sentinelRef.current) observer.observe(sentinelRef.current);
    return () => observer.disconnect();
  }, [onLoadMore, hasMore, loading]);

  return sentinelRef;
}', '["الاستماع لحدث scroll المباشر على window دون تقييد (throttling)، مما يسبب استهلاكاً مكثفاً للمعالج."]'::jsonb, '["كيف تتأكد من إلغاء وتحديث مراقب الـ Observer عندما تتغير أبعاد القائمة بسرعة؟"]'::jsonb, '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/learn/reusing-logic-with-custom-hooks"}]'::jsonb from public.question_revisions r where r.question_id = 'rhookadv-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
