insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الـ Action Hooks الجديدة في React 19 (مثل useActionState و useFormStatus و useOptimistic)؟', 'هي منظومة متكاملة لتبسيط إدارة النماذج والعمليات غير المتزامنة، حيث تتعامل تلقائياً مع حالات التحميل والخطأ والتحديث التفاؤلي (Optimistic UI) دون الحاجة لتعريف حالات يدوية متعددة.', 'يقدم React 19 ميزات لدعم دورة حياة الـ Actions: يقوم useActionState بإدارة نتيجة وحالة تنفيذ دالة غير متزامنة، ويتيح useFormStatus للأزرار والحقول معرفة حالة تقديم النموذج الأب دون تمرير props، بينما يوفر useOptimistic عرضاً فورياً للنتيجة المتوقعة للمستخدم قبل اكتمال رد الخادم مع الرجوع التلقائي عند الفشل.', 'import { useOptimistic, useTransition } from ''react'';

function LikeButton({ initialLikes }: { initialLikes: number }) {
  const [isPending, startTransition] = useTransition();
  const [likes, setOptimisticLikes] = useOptimistic(
    initialLikes,
    (state, delta: number) => state + delta
  );

  async function handleLike() {
    startTransition(async () => {
      setOptimisticLikes(1); // تحديث الواجهة فوراً
      await api.likePost();   // استدعاء السيرفر
    });
  }

  return <button onClick={handleLike} disabled={isPending}>إعجاب ({likes})</button>;
}', '["محاولة استدعاء دالة التحديث التفاؤلي خارج نطاق startTransition أو بدون Action مدعوم."]'::jsonb, '["كيف غيرت ميزات React 19 أسلوب بناء نماذج الويب مقارنة بالـ Controlled Inputs التقليدية؟"]'::jsonb, '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/reference/react/useOptimistic"}]'::jsonb from public.question_revisions r where r.question_id = 'rhookadv-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rhookadv-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الـ Action Hooks الجديدة في React 19 (مثل useActionState و useFormStatus و useOptimistic)؟' or l.short_answer is distinct from 'هي منظومة متكاملة لتبسيط إدارة النماذج والعمليات غير المتزامنة، حيث تتعامل تلقائياً مع حالات التحميل والخطأ والتحديث التفاؤلي (Optimistic UI) دون الحاجة لتعريف حالات يدوية متعددة.' or l.explanation is distinct from 'يقدم React 19 ميزات لدعم دورة حياة الـ Actions: يقوم useActionState بإدارة نتيجة وحالة تنفيذ دالة غير متزامنة، ويتيح useFormStatus للأزرار والحقول معرفة حالة تقديم النموذج الأب دون تمرير props، بينما يوفر useOptimistic عرضاً فورياً للنتيجة المتوقعة للمستخدم قبل اكتمال رد الخادم مع الرجوع التلقائي عند الفشل.' or l.code_example is distinct from 'import { useOptimistic, useTransition } from ''react'';

function LikeButton({ initialLikes }: { initialLikes: number }) {
  const [isPending, startTransition] = useTransition();
  const [likes, setOptimisticLikes] = useOptimistic(
    initialLikes,
    (state, delta: number) => state + delta
  );

