insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تتعامل مع مشكلة الـ Hook Factory وتفادي إعادة إنشاء الدوال داخلياً مع useEffectEvent؟', 'تفصل دالة useEffectEvent المنطق التفاعلي (الذي يجب أن يقرأ أحدث المتغيرات دائماً) عن مصفوفة تبعيات الـ Effect (التي يجب ألا تتسبب في إعادة تشغيل الـ Effect غير المرغوب).', 'كثيراً ما نحتاج لقراءة متغيرات حديثة (مثل theme أو callback) داخل useEffect دون أن نريد إعادة تشغيل الـ Effect في كل مرة يتغير فيها هذا المتغير. توفر تجربة useEffectEvent حلاً ثورياً يسمح باستدعاء دوال تقرأ أحدث الـ props/state دون إدراجها في مصفوفة التبعيات.', '// مثال بالنمط التجريبي الرسمي لـ useEffectEvent
import { useEffect, experimental_useEffectEvent as useEffectEvent } from ''react'';

function ChatRoom({ roomId, theme }: { roomId: string; theme: string }) {
  const onConnected = useEffectEvent(() => {
    showNotification("تم الاتصال!", theme);
  });

  useEffect(() => {
    const connection = createConnection(roomId);
    connection.on(''connected'', () => onConnected());
    connection.connect();
    return () => connection.disconnect();
  }, [roomId]); // يعاد الاتصال فقط بتغير roomId، وليس بتغير theme
}', '["استدعاء دالة مسجلة بـ useEffectEvent أثناء الـ Render بدلاً من داخل الـ Effect نفسه."]'::jsonb, '["ما هي الطريقة التقليدية السابقة لتحقيق نفس هذا السلوك باستخدام useRef؟"]'::jsonb, '[{"title":"Advanced Hooks & Custom Hooks Documentation","url":"https://react.dev/reference/react/experimental_useEffectEvent"}]'::jsonb from public.question_revisions r where r.question_id = 'rhookadv-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
