insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مكتبة Zustand ولماذا تحظى بشعبية طاغية كبديل خفيف وسريع لـ Redux؟', 'هي مكتبة إدارة حالة بسيطة للغاية تعتمد على نموذج Hook مباشر بدون Context أو Boilerplate، مع دعم الـ Selectors الدقيقة والتحديث خارج شجرة ريأكت (Transient Updates).', 'تتميز Zustand بصغر حجمها (أقل من 2KB) وعدم حاجتها لتغليف التطبيق بـ Providers. يتم إنشاء Store عبر دالة create، ويمكن لأي مكوّن الاشتراك في جزء محدد من الحالة عبر Selector لمنع الـ Re-renders غير اللازمة، كما تدعم المزامنة السهلة مع التخزين المحلي عبر middleware مدمج.', 'import { create } from ''zustand'';

interface BearStore {
  bears: number;
  increasePopulation: () => void;
}

export const useBearStore = create<BearStore>((set) => ({
  bears: 0,
  increasePopulation: () => set((state) => ({ bears: state.bears + 1 })),
}));

function BearCounter() {
  // يشترك المكون فقط في خاصية bears
  const bears = useBearStore((state) => state.bears);
  return <h1>عدد الدببة: {bears}</h1>;
}', '["استدعاء كامل الـ store بدون selector مثل const store = useStore()، مما يؤدي لإعادة تصيير المكون عند أي تعديل لأي حقل."]'::jsonb, '["كيف تنفذ تحديثات الحالة غير المقترنة بالتصيير (Transient Updates) باستخدام getState و subscribe في Zustand؟"]'::jsonb, '[{"title":"State Management & Context Documentation","url":"https://react.dev/learn/scaling-up-with-reducer-and-context"}]'::jsonb from public.question_revisions r where r.question_id = 'rstate-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
