insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير الـ Optimistic UI Updates وتتعامل مع حالات الفشل والتراجع (Rollback)؟', 'يتم تحديث واجهة المستخدم بالحالة المتوقعة فور تفاعل المستخدم، مع الاحتفاظ بلقطة من الحالة السابقة للرجوع إليها وإظهار تنبيه خطأ إذا فشل الطلب على الخادم.', 'يحسن التحديث التفاؤلي سرعة الاستجابة الظاهرية للتطبيق. على سبيل المثال عند الضغط على زر الإعجاب، يتم زيادة العداد وتلوين الزر فورياً، وإرسال طلب للـ API. إذا نجح الطلب يتم تثبيت التغيير؛ وإذا رفض السيرفر الطلب، يتم تنفيذ Rollback فوري لإعادة العداد لحالته السابقة.', 'async function handleToggleFavorite(todoId: string) {
  const previousState = todos;
  // 1. تحديث تفاؤلي فوري
  setTodos(todos.map(t => t.id === todoId ? { ...t, fav: !t.fav } : t));

  try {
    await api.toggleFavorite(todoId);
  } catch (error) {
    // 2. تراجع عند الخطأ
    setTodos(previousState);
    toast.error("فشل حفظ التفضيل، يرجى المحاولة ثانية");
  }
}', '["نسيان حفظ مرجع الحالة الأصلية بدقة قبل إجراء التعديل التفاؤلي."]'::jsonb, '["كيف توفر مكتبة TanStack Query دعماً مدمجاً للتحديثات التفاؤلية عبر onMutate و onError؟"]'::jsonb, '[{"title":"State Management & Context Documentation","url":"https://react.dev/learn/reacting-to-input-with-state"}]'::jsonb from public.question_revisions r where r.question_id = 'rstate-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
