insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تتعامل مع حفظ ومزامنة حالة الواجهة في رابط الصفحة (URL Search Params كـ State)؟', 'باستخدام الـ URL Search Params لتخزين عوامل التصفية والبحث ورقم الصفحة، لتمكين المستخدم من مشاركة الرابط أو العودة إليه بنفس الحالة بالضبط.', 'تخزين معايير البحث والترتيب في الـ URL يجعل الصفحة سهلة المشاركة ويدعم أزرار الرجوع والتقدم في المتصفح وتوافق الـ SEO. توفر أطر العمل والمكتبات (مثل react-router أو Next.js nuqs) هوكس متخصصة مثل useSearchParams لقراءة وكتابة هذه المعاملات بشكل متزامن.', 'import { useSearchParams } from ''react-router-dom'';

function ProductFilter() {
  const [searchParams, setSearchParams] = useSearchParams();
  const currentCategory = searchParams.get(''category'') || ''all'';

  const setCategory = (cat: string) => {
    setSearchParams(prev => {
      prev.set(''category'', cat);
      return prev;
    });
  };

  return <button onClick={() => setCategory(''electronics'')}>إلكترونيات</button>;
}', '["تخزين الفلاتر في useState محلي غير متصل بالـ URL مما يؤدي لضياع الحالة بمجرد تحديث الصفحة (Refresh)."]'::jsonb, '["كيف تتجنب إنشاء إدخالات تاريخ تصفح مفرطة في المتصفح باستخدام خيار replace: true؟"]'::jsonb, '[{"title":"State Management & Context Documentation","url":"https://react.dev/learn/sharing-state-between-components"}]'::jsonb from public.question_revisions r where r.question_id = 'rstate-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
