insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يتم التنقل البرمجي (Programmatic Navigation) والتعامل مع معلمات المسار (Params)؟', 'نستخدم خطاف useNavigate لتوجيه المستخدم برمجياً كاستجابة لحدث ما، وخطاف useParams لاستخراج المعاملات الديناميكية من الـ URL.', 'يوفر useNavigate دالة تنقل تستقبل مساراً أو رقماً للتنقل في السجل (مثل navigate(-1) للرجوع)، مع خيارات للتحكم في استبدال التاريخ replace. بينما يحلل useParams الأجزاء المعرفة بنقطتين رأسيتين مثل :id ويحولها لكائن يحمل تلك القيم.', 'import { useParams, useNavigate } from ''react-router-dom'';

function OrderDetails() {
  const { orderId } = useParams<{ orderId: string }>();
  const navigate = useNavigate();

  const handleComplete = () => {
    // إجراء منطق إنهاء الطلب ثم التوجيه لصفحة الشكر
    navigate(''/thank-you'', { replace: true });
  };

  return <div>طلب رقم: {orderId} <button onClick={handleComplete}>إنهاء</button></div>;
}', '["استدعاء navigate مباشرة في جسم دالة المكون أثناء مرحلة الـ Render بدلاً من معالجات الأحداث أو useEffect."]'::jsonb, '["ما هي المخاطر التقنية لمحاولة التوجيه المتزامن أثناء عملية الـ Rendering؟"]'::jsonb, '[{"title":"Routing & Single Page Apps Documentation","url":"https://react.dev/learn"}]'::jsonb from public.question_revisions r where r.question_id = 'rroute-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
