insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين MemoryRouter و BrowserRouter و HashRouter ومتى نستخدم كلاً منها؟', 'BrowserRouter يستخدم HTML5 History API لتطبيقات الويب الحديثة، و HashRouter يستخدم # في الرابط للخوادم البسيطة، بينما MemoryRouter يحتفظ بالمسارات في الذاكرة ومثالي لبيئات الاختبار (Jest/Vitest).', 'BrowserRouter هو الخيار القياسي لإنتاج روابط نظيفة تتطلب تهيئة السيرفر لرد index.html لجميع المسارات. HashRouter يستخدم التجزئة (#) ولا يحتاج لأي تكوين في السيرفر لكنه ضار بـ SEO. MemoryRouter لا يتعامل مع متصفح أو شريط عناوين إطلاقاً ويستخدم خصيصاً في وحدات الاختبار وبيئات التفاعل غير المتصفحية مثل React Native.', '// مثال لاختبار مكون تنقل باستخدام MemoryRouter
import { render, screen } from ''@testing-library/react'';
import { MemoryRouter } from ''react-router-dom'';

test(''يعرض صفحة الملف الشخصي'', () => {
  render(
    <MemoryRouter initialEntries={[''/profile/42'']}>
      <AppRoutes />
    </MemoryRouter>
  );
  expect(screen.getByText(/الملف الشخصي/i)).toBeInTheDocument();
});', '["استخدام BrowserRouter داخل بيئة Node.js الخاصة باختبارات Unit Tests دون توفر نافذة window/history كاملة."]'::jsonb, '["لماذا ينصح بتفادي HashRouter في التطبيقات التي تعتمد على تحسين محركات البحث SEO؟"]'::jsonb, '[{"title":"Routing & Single Page Apps Documentation","url":"https://react.dev/learn"}]'::jsonb from public.question_revisions r where r.question_id = 'rroute-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rroute-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين MemoryRouter و BrowserRouter و HashRouter ومتى نستخدم كلاً منها؟' or l.short_answer is distinct from 'BrowserRouter يستخدم HTML5 History API لتطبيقات الويب الحديثة، و HashRouter يستخدم # في الرابط للخوادم البسيطة، بينما MemoryRouter يحتفظ بالمسارات في الذاكرة ومثالي لبيئات الاختبار (Jest/Vitest).' or l.explanation is distinct from 'BrowserRouter هو الخيار القياسي لإنتاج روابط نظيفة تتطلب تهيئة السيرفر لرد index.html لجميع المسارات. HashRouter يستخدم التجزئة (#) ولا يحتاج لأي تكوين في السيرفر لكنه ضار بـ SEO. MemoryRouter لا يتعامل مع متصفح أو شريط عناوين إطلاقاً ويستخدم خصيصاً في وحدات الاختبار وبيئات التفاعل غير المتصفحية مثل React Native.' or l.code_example is distinct from '// مثال لاختبار مكون تنقل باستخدام MemoryRouter
