insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مشكلة الـ Layout Thrashing وكيف نتجنبها في مكونات ريأكت؟', 'تحدث عندما يتعاقب قراءة قياسات الـ DOM (مثل offsetHeight) مع تعديل أنماط الـ DOM في حلقة سريعة، مما يجبر المتصفح على إعادة حساب التخطيط (Reflow) بشكل متكرر ومكلف.', 'يجمع المتصفح تعديلات الـ DOM ويطبقها دفعة واحدة. لكن إذا قمت بقراءة خصائص التخطيط الهندسي فور إجراء تعديل، يضطر المتصفح لإيقاف التنفيذ فوراً وحساب التخطيط الجديد قسرياً (Forced Synchronous Layout). في ريأكت يتم تجنب هذا بقراءة كافة القياسات دفعة واحدة أولاً، ثم تطبيق تعديلات الحالة في خطوة موحدة.', '// نمط سيء: قراءة وكتابة متناوبة تجبر Reflow متكرر
// elements.forEach(el => { const h = el.offsetHeight; el.style.height = (h + 10) + ''px''; });

// نمط سليم: تجميع القراءات ثم تجميع التعديلات
const heights = elements.map(el => el.offsetHeight);
elements.forEach((el, i) => {
  el.style.height = `${heights[i] + 10}px`;
});', '["تنفيذ قياسات مستمرة للعناصر داخل معالج حدث onScroll دون استخدام requestAnimationFrame."]'::jsonb, '["كيف يمكن الاستفادة من ResizeObserver لقياس تغير أبعاد العناصر بكفاءة دون التسبب في Reflows متزامنة؟"]'::jsonb, '[{"title":"Performance Optimization & Profiling Documentation","url":"https://react.dev/learn"}]'::jsonb from public.question_revisions r where r.question_id = 'rperf-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
