insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تستخدم Web Workers في تطبيقات ريأكت لنقل العمليات الحسابية الشاقة خارج الـ Main Thread؟', 'باستخدام Web Workers لتشغيل أكواد معالجة البيانات الضخمة وفك تشفير الملفات في خيط معالجة منفصل بالخلفية، مما يحافظ على سلاسة واجهة المستخدم واستجابتها بمعدل 60fps دون أي تقطيع.', 'نظراً لأن JavaScript تعمل في خيط أحادي (Single Threaded)، فإن العمليات الحسابية الشاقة تجمد تفاعل الواجهة تماماً. يتيح Web Worker تشغيل نصوص برمجية في الخلفية والتواصل مع مكون ريأكت عبر postMessage و onmessage، وهو ما توفره أدوات حديثة مثل Comlink لتسهيل الاستدعاء كدوال عادية.', '// إنشاء واستخدام Worker
const worker = new Worker(new URL(''./heavy-calc.worker.ts'', import.meta.url));

function runCalculation(data: BigData) {
  worker.postMessage(data);
  worker.onmessage = (e) => {
    setResult(e.data);
  };
}', '["محاولة تمرير كائنات DOM أو دوال غير قابلة للتسلسل (Functions) عبر postMessage للـ Worker."]'::jsonb, '["ما هي خوارزمية Structured Clone المستخدمة في نقل البيانات إلى الـ Web Worker وما هي أنواع البيانات غير المدعومة؟"]'::jsonb, '[{"title":"Performance Optimization & Profiling Documentation","url":"https://react.dev/learn"}]'::jsonb from public.question_revisions r where r.question_id = 'rperf-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
