insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي معضلة الـ Hydration وما هي مسببات الـ Hydration Mismatch الشهيرة؟', 'هي عملية ربط أحداث JavaScript بشجرة الـ HTML المبنية مسبقاً من الخادم؛ ويحدث الـ Mismatch عندما تختلف بنية الشجرة المكونة على السيرفر عن بنية الشجرة التي يريد العميل إنشاؤها.', 'عندما يستلم المتصفح HTML من SSR، يقوم React بمطابقة عناصر الـ DOM القائمة مع ناتج الـ render للعميل. إذا كان هناك اختلاف (مثل استخدام Date.now()، أو نافذة window، أو صياغة HTML غير صالحة مثل وضع <p> داخل <p>)، يفشل التطابق ويضطر ريأكت للتخلي عن الشجرة القديمة وإعادة بنائها مع إطلاق خطأ تحذيري.', '// سبب شائع للـ Mismatch: الاعتماد على تاريخ متغير في الخادم والعميل
function Timestamp() {
  // خطأ: السيرفر له توقيت والعميل له توقيت آخر
  // return <span>{new Date().toLocaleTimeString()}</span>;

  // حل سليم: إظهار التوقيت بعد اكتمال الـ mount في المتصفح فقط
  const [time, setTime] = useState<string | null>(null);
  useEffect(() => {
    setTime(new Date().toLocaleTimeString());
  }, []);

  return <span>{time || "جاري التحميل..."}</span>;
}', '["محاولة إخفاء الخطأ بوضع suppressHydrationWarning في كل مكان بدلاً من إصلاح سبب عدم التوافق."]'::jsonb, '["كيف يسهم استخدام مكتبة التنسيق السليمة في تجنب مشاكل الـ Hydration للأنماط والخطوط؟"]'::jsonb, '[{"title":"SSR, SSG & Server Components Documentation","url":"https://react.dev/reference/react-dom/client/hydrateRoot"}]'::jsonb from public.question_revisions r where r.question_id = 'rrender-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
