import db from ''@/lib/db'';

export async function ProductReviewList({ productId }: { productId: string }) {
  // استعلام مباشر بقاعدة البيانات بدون إنشاء API endpoint
  const reviews = await db.reviews.findMany({ where: { productId } });

  return (
    <div>
      {reviews.map(r => (
        <p key={r.id}>{r.comment}</p>
      ))}
    </div>
  );
}', '["الاعتقاد بأن RSC تلغي الحاجة لـ Client Components، فالمكونات التفاعلية (مع onClick و useState) لا تزال تتطلب التوجيه \"use client\"."]'::jsonb, '["كيف تتواصل Server Components مع Client Components عبر تمرير الـ Props والـ Children؟"]'::jsonb, '[{"title":"SSR, SSG & Server Components Documentation","url":"https://react.dev/reference/rsc/server-components"}]'::jsonb from public.question_revisions r where r.question_id = 'rrender-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
