  const { pipe } = renderToPipeableStream(<App />, {
    bootstrapScripts: [''/main.js''],
    onShellReady() {
      res.setHeader(''content-type'', ''text/html'');
      pipe(res); // بدء بث الهيكل الأساسي فوراً
    },
    onError(error) {
      console.error(error);
    }
  });
});', '["استخدام الدالة القديمة renderToString التي كانت تحبس الاستجابة وتمنع إرسال أي بايت حتى يكتمل تجهيز كامل شجرة المكونات."]'::jsonb, '["كيف يتعامل Streaming SSR مع محركات البحث وعناكب الفهرسة التي لا تنتظر دفق البيانات المتأخر؟"]'::jsonb, '[{"title":"SSR, SSG & Server Components Documentation","url":"https://react.dev/reference/react-dom/server/renderToPipeableStream"}]'::jsonb from public.question_revisions r where r.question_id = 'rrender-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
