function LoginForm() {
  const { register, handleSubmit, formState: { errors } } = useForm<{ email: string }>();

  const onSubmit = (data: { email: string }) => console.log(data);

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <input {...register("email", { required: "البريد الإلكتروني مطلوب" })} />
      {errors.email && <span>{errors.email.message}</span>}
      <button type="submit">دخول</button>
    </form>
  );
}', '["استخدام watch() في أعلى المكون دون تحديد حقول معينة مما يعيد تصيير كامل المكون ويفقد ميزة RHF الأساسية."]'::jsonb, '["كيف يتم ربط مكونات واجهة المستخدم المخصصة (مثل مكاتب MUI أو Radix) مع RHF باستخدام مكون Controller؟"]'::jsonb, '[{"title":"Forms & Data Handling Documentation","url":"https://react.dev/reference/react-dom/components/input"}]'::jsonb from public.question_revisions r where r.question_id = 'rform-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
