insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير النماذج الديناميكية التي تحتوي على مصفوفة حقول متغيرة (Dynamic Field Arrays)؟', 'نستخدم خطاف useFieldArray في React Hook Form لإضافة وحذف وتحريك الحقول ديناميكياً مع تزويد كل حقل بمفتاح فريد (Key) ثابت ومخصص.', 'تتطلب نماذج الفواتير وقوائم المهام إضافة حقول أو إزالتها أثناء ملء النموذج. استخدام useState التقليدي لمصفوفة من الكائنات يسبب مشاكل في حفظ التركيز وأداء بطيء عند الحذف. يوفر useFieldArray دوال append و remove و move مسبقة الضبط مع معالجة هوية المفاتيح عبر field.id التلقائي.', 'import { useForm, useFieldArray } from ''react-hook-form'';

function InvoiceForm() {
  const { control, register } = useForm();
  const { fields, append, remove } = useFieldArray({ control, name: ''items'' });

  return (
    <div>
      {fields.map((field, index) => (
        <div key={field.id}>
          <input {...register(`items.${index}.name`)} />
          <button type="button" onClick={() => remove(index)}>حذف</button>
        </div>
      ))}
      <button type="button" onClick={() => append({ name: '''' })}>إضافة صنف</button>
    </div>
  );
}', '["استخدام index المصفوفة كـ key لعناصر الحقول الديناميكية، مما يسبب اختلال محتوى الحقول وقيمها عند حذف صف وسطي."]'::jsonb, '["كيف تتأكد من مطابقة التحقق في Zod لمصفوفة كائنات متغيرة بأبعاد غير محددة؟"]'::jsonb, '[{"title":"Forms & Data Handling Documentation","url":"https://react.dev/reference/react-dom/components/input"}]'::jsonb from public.question_revisions r where r.question_id = 'rform-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
