insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الـ Server Actions في React 19 وكيف تحدث ثورة في إرسال النماذج بدون جافاسكربت؟', 'هي دوال غير متزامنة تنفذ حصرياً على الخادم ويمكن ربطها مباشرة بخاصية action في وسم <form>، وتعمل حتى لو تم تعطيل JavaScript في متصفح العميل (Progressive Enhancement).', 'بدلاً من كتابة معالج onSubmit يدوي وتغليفه بـ e.preventDefault() واستدعاء API خارجي، يتيح React 19 تمرير دالة Server Action مباشرة للنموذج. يستقبل السيرفر كائن FormData، ويقوم بتعديل قاعدة البيانات، ثم يعيد ريأكت تحديث وتصيير الصفحة تلقائياً مع معالجة التحقق والتحديثات التفاؤلية.', '// خادم: دالة Server Action
async function updateUsername(formData: FormData) {
  ''use server'';
  const newName = formData.get(''username'');
  await db.user.update({ name: String(newName) });
}

// مكون عميل أو خادم
function ProfileForm() {
  return (
    <form action={updateUsername}>
      <input name="username" defaultValue="أحمد" />
      <button type="submit">حفظ الاسم</button>
    </form>
  );
}', '["الاعتقاد بأن Server Actions محمية تلقائياً من ثغرات CSRF أو أنها لا تحتاج للتحقق من تصاريح المصادقة."]'::jsonb, '["كيف يتم تأمين وحماية دوال Server Actions ضد هجمات تزوير الطلبات والتحقق من صلاحية المستخدم؟"]'::jsonb, '[{"title":"Forms & Data Handling Documentation","url":"https://react.dev/reference/rsc/server-actions"}]'::jsonb from public.question_revisions r where r.question_id = 'rform-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rform-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الـ Server Actions في React 19 وكيف تحدث ثورة في إرسال النماذج بدون جافاسكربت؟' or l.short_answer is distinct from 'هي دوال غير متزامنة تنفذ حصرياً على الخادم ويمكن ربطها مباشرة بخاصية action في وسم <form>، وتعمل حتى لو تم تعطيل JavaScript في متصفح العميل (Progressive Enhancement).' or l.explanation is distinct from 'بدلاً من كتابة معالج onSubmit يدوي وتغليفه بـ e.preventDefault() واستدعاء API خارجي، يتيح React 19 تمرير دالة Server Action مباشرة للنموذج. يستقبل السيرفر كائن FormData، ويقوم بتعديل قاعدة البيانات، ثم يعيد ريأكت تحديث وتصيير الصفحة تلقائياً مع معالجة التحقق والتحديثات التفاؤلية.' or l.code_example is distinct from '// خادم: دالة Server Action
async function updateUsername(formData: FormData) {
  ''use server'';
  const newName = formData.get(''username'');
  await db.user.update({ name: String(newName) });
}

// مكون عميل أو خادم
function ProfileForm() {
  return (
    <form action={updateUsername}>
      <input name="username" defaultValue="أحمد" />
      <button type="submit">حفظ الاسم</button>
