  const subscription = watch((values) => {
    const timer = setTimeout(() => {
      localStorage.setItem(''form_draft'', JSON.stringify(values));
    }, 1500);
    return () => clearTimeout(timer);
  });
  return () => subscription.unsubscribe();
}, [watch]);', '["حفظ كلمات المرور أو أرقام البطاقات الائتمانية الحساسة في الـ localStorage كمسودات غير مشفرة."]'::jsonb, '["كيف تستخدم حدث beforeunload لتحذير المستخدم عند محاولة إغلاق الصفحة بوجود تغييرات غير محفوظة؟"]'::jsonb, '[{"title":"Forms & Data Handling Documentation","url":"https://react.dev/reference/react-dom/components/input"}]'::jsonb from public.question_revisions r where r.question_id = 'rform-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
