insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني معالج نماذج متعدد الخطوات (Multi-step Wizard Form) مع الحفاظ على البيانات عند الرجوع؟', 'نعرف حالة مركزية تخزن بيانات جميع الخطوات في المكون الأب، ونعرض المكون المقابل لرقم الخطوة الحالية مع تزويده بزر للرجوع والتقدم دون فقدان المدخلات السابقة.', 'يمكن تقسيم النماذج الطويلة إلى خطوات منطقية. يتم التحقق من صحة حقول الخطوة الحالية فقط قبل السماح بالانتقال للخطوة التالية. يتم الاحتفاظ بكامل البيانات المجمعة في كائن موحد، بحيث يتم إرسال الكائن النهائي للخادم فقط في الخطوة الأخيرة.', 'function Wizard() {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({});

  const nextStep = (stepData: object) => {
    setFormData(prev => ({ ...prev, ...stepData }));
    setStep(s => s + 1);
  };

  const prevStep = () => setStep(s => Math.max(1, s - 1));

  return (
    <div>
      {step === 1 && <PersonalInfo onNext={nextStep} defaultValues={formData} />}
      {step === 2 && <BillingInfo onNext={nextStep} onBack={prevStep} defaultValues={formData} />}
    </div>
  );
}', '["تدمير بيانات الخطوات السابقة عند الرجوع بسبب إعادة تهيئة الـ State المحلية في كل خطوة."]'::jsonb, '["كيف يمكنك استخدام مسارات الـ URL لتمثيل كل خطوة في الـ Wizard لدعم زر الرجوع في المتصفح؟"]'::jsonb, '[{"title":"Forms & Data Handling Documentation","url":"https://react.dev/learn/choosing-the-state-structure"}]'::jsonb from public.question_revisions r where r.question_id = 'rform-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
