function AccessibleModal() {
  return (
    <Dialog.Root>
      <Dialog.Trigger className="btn">فتح النافذة</Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay className="overlay" />
        <Dialog.Content className="modal-body">
          <Dialog.Title>تأكيد العملية</Dialog.Title>
          <Dialog.Close>إلغاء</Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}', '["محاولة إعادة اختراع منطق المكونات المعقدة كالقوائم المنسدلة من الصفر دون تطبيق سمات الإتاحة الضرورية."]'::jsonb, '["كيف أسهم مفهوم الـ Headless في نجاح مكتبات التوزيع المباشر للكود مثل shadcn/ui؟"]'::jsonb, '[{"title":"Architecture, Component Patterns & Best Practices Documentation","url":"https://react.dev/learn"}]'::jsonb from public.question_revisions r where r.question_id = 'rpat-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
