insert into public.interview_questions (id, slug, track_id, difficulty) values ('rpat-004', 'react-container-presentational-solid-architecture-004', 'react', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
