insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق مبدأ المسؤولية الواحدة (Single Responsibility) وفصل الـ Container والمكونات التقديمية؟', 'بفصل المكونات التي تجلب البيانات وتدير الحالة (Container / Smart) عن المكونات التي تهتم فقط بعرض البيانات وتنسيق الواجهة (Presentational / Dumb).', 'يقوم المكون الذكي بجلب البيانات والاشتراك في الـ Stores والتعامل مع الخطأ، ثم يمرر البيانات النقية ودوال الأحداث كمجرد Props للمكون التقديمي. هذا الفصل يجعل المكونات التقديمية سهلة الاختبار للغاية وسهلة العرض في Storybook وقابلة لإعادة الاستخدام في سياقات مختلفة تماماً.', '// 1. Presentational Component (نقي وسهل الاختبار)
function UserCardView({ name, email, onFollow }: UserCardProps) {
  return (
    <div className="card">
      <h3>{name}</h3>
      <p>{email}</p>
      <button onClick={onFollow}>متابعة</button>
    </div>
  );
}

// 2. Container Component (مسؤول عن جلب البيانات والمنطق)
function UserCardContainer({ userId }: { userId: string }) {
  const { data: user } = useQuery([''user'', userId], fetchUser);
  const handleFollow = () => api.followUser(userId);

  if (!user) return <Skeleton />;
  return <UserCardView name={user.name} email={user.email} onFollow={handleFollow} />;
}', '["خلط عمليات الاستعلام من قاعدة البيانات وإرسال الأحداث والتنسيق المعقد داخل ملف مكون واحد ضخم يتجاوز 500 سطر."]'::jsonb, '["كيف وفرت Custom Hooks بديلاً عصرياً قلل من الحاجة للفصل الهرمي بين Container و Presentational components؟"]'::jsonb, '[{"title":"Architecture, Component Patterns & Best Practices Documentation","url":"https://react.dev/learn"}]'::jsonb from public.question_revisions r where r.question_id = 'rpat-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
