insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو نمط Render Props وما هي استخداماته المعاصرة؟', 'هو نمط يتم فيه تمرير دالة كـ prop (أو كـ children) للمكون، ويقوم المكون باستدعائها وتزويدها ببياناته الداخلية للتحكم في كيفية تصيير المخرجات.', 'كان هذا النمط وسيلة شائعة لمشاركة السلوك (مثل تتبع حركة الفأرة أو التحقق من التمرير) قبل ظهور الهوكس. على الرغم من أن الـ Custom Hooks غطت معظم حالاته، إلا أن Render Props لا تزال تستخدم بكفاءة في المكونات الافتراضية (Virtualizers) ومكتبات الرسوم البيانية لتخصيص رسم العناصر الفردية.', 'interface MouseTrackerProps {
  render: (mouse: { x: number; y: number }) => React.ReactNode;
}

function MouseTracker({ render }: MouseTrackerProps) {
  const [pos, setPos] = useState({ x: 0, y: 0 });

  return (
    <div onMouseMove={(e) => setPos({ x: e.clientX, y: e.clientY })}>
      {render(pos)}
