insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو نظام Fabric وما الفرق بينه وبين نظام التصيير القديم في React Native؟', 'نظام Fabric هو محرك التصيير الجديد (Renderer) المعتمد على C++، حيث يدمج مباشرة مع شجرة React 18 Concurrency ويوفر رسم متزامن لعناصر الواجهة وتكامل فوري مع Yoga.', 'في المحرك القديم، كان حساب التخطيط في Shadow Thread ينقل الأبعاد للـ Native UI عبر الـ Bridge مما يسبب وميضاً وتأخراً في الرسوم. في Fabric، تم توحيد كود الـ Shadow Tree والتخطيط بلغة C++ موحدة، وأصبح بالإمكان إنشاء شجرة عناصر الـ UI بشكل متزامن مع دعم كامل لـ Concurrent React وميزات مثل Suspense و Transitions.', '// تسلسل Fabric الجديد:
// [React Component] -> [C++ Element Tree] -> [Yoga Layout C++] -> [Direct Host View Mutation]', '["الاعتقاد بأن تفعيل Fabric يتطلب إعادة كتابة كود شاشات JSX بالكامل، فالتغييرات تكمن في طبقة المكتبات والـ Native Modules."]'::jsonb, '["كيف يمنع Fabric ظهور القفزات البيضاء المؤقتة (White Jumps) أثناء تمرير القوائم الطويلة بسرعة فائقة؟"]'::jsonb, '[{"title":"React Native Architecture & Bridge / New Architecture Documentation","url":"https://reactnative.dev/docs/the-new-architecture/fabric-renderer"}]'::jsonb from public.question_revisions r where r.question_id = 'rncore-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rncore-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو نظام Fabric وما الفرق بينه وبين نظام التصيير القديم في React Native؟' or l.short_answer is distinct from 'نظام Fabric هو محرك التصيير الجديد (Renderer) المعتمد على C++، حيث يدمج مباشرة مع شجرة React 18 Concurrency ويوفر رسم متزامن لعناصر الواجهة وتكامل فوري مع Yoga.' or l.explanation is distinct from 'في المحرك القديم، كان حساب التخطيط في Shadow Thread ينقل الأبعاد للـ Native UI عبر الـ Bridge مما يسبب وميضاً وتأخراً في الرسوم. في Fabric، تم توحيد كود الـ Shadow Tree والتخطيط بلغة C++ موحدة، وأصبح بالإمكان إنشاء شجرة عناصر الـ UI بشكل متزامن مع دعم كامل لـ Concurrent React وميزات مثل Suspense و Transitions.' or l.code_example is distinct from '// تسلسل Fabric الجديد:
