insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الـ TurboModules وكيف تحسن من سرعة إقلاع التطبيق (Startup Time)؟', 'هي نظام الوحدات الأصلية الجديد الذي يقوم بتحميل الوحدات بطريقة كسولة (Lazy Loading) عند أول استدعاء فقط بدلاً من تهيئتها دفعة واحدة عند إقلاع التطبيق كما كان يحدث سابقاً.', 'في المعمارية السابقة، كان يتم تحميل وتهيئة كافة الـ Native Modules المسجلة في التطبيق (الكاميرا، الموقع، البلوتوث) أثناء بدء التشغيل حتى لو لم يحتج المستخدم سوى شاشة تسجيل دخول بسيطة. باستخدام TurboModules و JSI، لا يتم حجز الذاكرة أو إنشاء الوحدة الأصلية إلا في اللحظة التي يستدعي فيها كود JS تلك الوحدة فعلياً.', '// استيراد TurboModule يتم بإنشاء واجهة Typed Spec:
import type { TurboModule } from ''react-native'';
import { TurboModuleRegistry } from ''react-native'';

export interface Spec extends TurboModule {
  getDeviceModel(): string;
}

export default TurboModuleRegistry.getEnforcing<Spec>(''DeviceDetails'');', '["تطبيق أنماط التهيئة الثقيلة داخل دوال البناء (Constructors) لوحدات TurboModule بدلاً من تأجيلها للاستدعاء الفعلي."]'::jsonb, '["ما هو دور أداة Codegen في توليد واجهات C++ و Java و Obj-C تلقائياً لـ TurboModules؟"]'::jsonb, '[{"title":"React Native Architecture & Bridge / New Architecture Documentation","url":"https://reactnative.dev/docs/the-new-architecture/turbomodules"}]'::jsonb from public.question_revisions r where r.question_id = 'rncore-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rncore-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الـ TurboModules وكيف تحسن من سرعة إقلاع التطبيق (Startup Time)؟' or l.short_answer is distinct from 'هي نظام الوحدات الأصلية الجديد الذي يقوم بتحميل الوحدات بطريقة كسولة (Lazy Loading) عند أول استدعاء فقط بدلاً من تهيئتها دفعة واحدة عند إقلاع التطبيق كما كان يحدث سابقاً.' or l.explanation is distinct from 'في المعمارية السابقة، كان يتم تحميل وتهيئة كافة الـ Native Modules المسجلة في التطبيق (الكاميرا، الموقع، البلوتوث) أثناء بدء التشغيل حتى لو لم يحتج المستخدم سوى شاشة تسجيل دخول بسيطة. باستخدام TurboModules و JSI، لا يتم حجز الذاكرة أو إنشاء الوحدة الأصلية إلا في اللحظة التي يستدعي فيها كود JS تلك الوحدة فعلياً.' or l.code_example is distinct from '// استيراد TurboModule يتم بإنشاء واجهة Typed Spec:
