export default TurboModuleRegistry.getEnforcing<Spec>(''DeviceDetails'');' or l.common_mistakes is distinct from '["تطبيق أنماط التهيئة الثقيلة داخل دوال البناء (Constructors) لوحدات TurboModule بدلاً من تأجيلها للاستدعاء الفعلي."]'::jsonb or l.follow_up_questions is distinct from '["ما هو دور أداة Codegen في توليد واجهات C++ و Java و Obj-C تلقائياً لـ TurboModules؟"]'::jsonb or l.sources is distinct from '[{"title":"React Native Architecture & Bridge / New Architecture Documentation","url":"https://reactnative.dev/docs/the-new-architecture/turbomodules"}]'::jsonb)) then raise exception 'Question rncore-004 ar content changed; create a new revision before seeding'; end if; end $$;
