insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين React Native CLI الخالص (Bare Workflow) و Expo Managed Workflow؟', 'المسار الخالص (Bare) يتيح وصولاً كاملاً وتعديلاً مباشراً لمجلدي android و ios وكود Native، بينما Expo Managed يخفي المجلدات الأصلية ويدير البناء والتحديثات سحابياً عبر Prebuild و Config Plugins.', 'يوفر الـ Bare Workflow مرونة مطلقة لكتابة كود أصلي مخصص لكنه يتطلب صيانة دورية لملفات البناء و Xcode و Gradle. بينما في Expo المعاصر، بفضل ميزة Continuous Native Generation (CNG) واستخدام Config Plugins، يمكن الوصول لأي مكتبة أصلية بدون كتابة كود يدوي في مجلدي أندرويد و iOS، مما يوفر سرعة إنتاجية فائقة وترقيات سلسة.', '// تخصيص إعدادات Native في Expo دون لمس مجلد أندرويد/آيفون (app.json):
{
  "expo": {
    "name": "MyApp",
    "plugins": [
      ["expo-camera", { "cameraPermission": "السماح بالوصول للكاميرا لالتقاط الصور" }]
    ]
  }
}', '["الاعتقاد القديم بأن Expo لا يدعم مكتبات الـ Native المخصصة أو البلوتوث كما كان في 2018."]'::jsonb, '["كيف يعمل أمر npx expo prebuild في توليد مجلدي android و ios بصورة نظيفة وقابلة للإعادة؟"]'::jsonb, '[{"title":"React Native Architecture & Bridge / New Architecture Documentation","url":"https://docs.expo.dev/bare/overview/"}]'::jsonb from public.question_revisions r where r.question_id = 'rncore-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rncore-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين React Native CLI الخالص (Bare Workflow) و Expo Managed Workflow؟' or l.short_answer is distinct from 'المسار الخالص (Bare) يتيح وصولاً كاملاً وتعديلاً مباشراً لمجلدي android و ios وكود Native، بينما Expo Managed يخفي المجلدات الأصلية ويدير البناء والتحديثات سحابياً عبر Prebuild و Config Plugins.' or l.explanation is distinct from 'يوفر الـ Bare Workflow مرونة مطلقة لكتابة كود أصلي مخصص لكنه يتطلب صيانة دورية لملفات البناء و Xcode و Gradle. بينما في Expo المعاصر، بفضل ميزة Continuous Native Generation (CNG) واستخدام Config Plugins، يمكن الوصول لأي مكتبة أصلية بدون كتابة كود يدوي في مجلدي أندرويد و iOS، مما يوفر سرعة إنتاجية فائقة وترقيات سلسة.' or l.code_example is distinct from '// تخصيص إعدادات Native في Expo دون لمس مجلد أندرويد/آيفون (app.json):
