insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يعتبر FlatList خياراً أفضل بكثير من ScrollView مع القوائم الطويلة في React Native؟', 'لأن FlatList يعتمد على التحميل الكسول وإعادة تدوير العناصر المرئية فقط (Virtualization)، بينما ScrollView يقوم بتصيير وحجز ذاكرة لكافة عناصر القائمة دفعة واحدة.', 'إذا كانت قائمتك تحتوي على 500 عنصر واستخدمت ScrollView، سيحاول النظام إنشاء 500 عقدة Native فوراً مما يستهلك مئات الميجابايتات ويجمد الشاشة. FlatList يقوم برسم العناصر الظاهرة على الشاشة فقط وهامش صغير حولها، ويتخلص من العناصر البعيدة عن مجال الرؤية لتوفير الذاكرة وسلاسة التمرير بمعدل 60 إطاراً في الثانية.', 'import { FlatList, Text, View } from ''react-native'';

function ProductList({ items }: { items: { id: string; name: string }[] }) {
  return (
    <FlatList
      data={items}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View style={{ padding: 16 }}>
          <Text>{item.name}</Text>
        </View>
      )}
      initialNumToRender={10}
      maxToRenderPerBatch={10}
      windowSize={5}
    />
  );
}', '["استخدام دوال مجهولة مدمجة (Inline Arrow Functions) داخل renderItem مما يسبب إعادة تصيير كافة الصفوف عند كل تحديث."]'::jsonb, '["ما هي مكتبة FlashList المطورة من Shopify ولماذا تتفوق على FlatList بـ 5 أضعاف في سرعة إعادة التدوير؟"]'::jsonb, '[{"title":"Core Components & Primitives Documentation","url":"https://reactnative.dev/docs/flatlist"}]'::jsonb from public.question_revisions r where r.question_id = 'rncomp-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
