insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين TouchableOpacity و TouchableHighlight و Pressable ومتى نعتمد Pressable دائماً؟', 'مكون Pressable هو المكون الأحدث والأكثر مرونة ودقة، حيث يوفر وصولاً دقيقاً لحالات الضغط المتعددة (Pressed, Hovered, Focused) وتأخير الضغط الطويل دون تعقيدات التغليف القديمة.', 'المكونات القديمة مثل TouchableOpacity كانت مجرد أغلفة تعتمد على أنظمة تحريك محددة مسبقاً (تعديل الشفافية opacity فقط). بينما صُمم Pressable ليكون الأساس الموحد لكافة التفاعلات اللمسية في ريأكت نيتف، حيث يستقبل دالة لتنسيق العنصر بناءً على حالة { pressed } بدقة فائقة ويدعم سمات إمكانية الوصول والتفاعل العصري.', 'import { Pressable, Text, StyleSheet } from ''react-native'';

function ActionButton({ onPress, title }: { onPress: () => void; title: string }) {
  return (
    <Pressable
      onPress={onPress}
      style={({ pressed }) => [
        styles.button,
        { opacity: pressed ? 0.7 : 1.0, transform: [{ scale: pressed ? 0.98 : 1.0 }] }
      ]}
    >
      <Text style={styles.text}>{title}</Text>
    </Pressable>
  );
}', '["استخدام TouchableOpacity لتأثيرات معقدة تتطلب تعديل خصائص متعددة غير الشفافية (مثل تغيير لون الخلفية أو الحجم)."]'::jsonb, '["ما هي خاصية hitSlop في Pressable وكيف تحسن من سهولة النقر على الأيقونات الصغيرة في الهواتف؟"]'::jsonb, '[{"title":"Core Components & Primitives Documentation","url":"https://reactnative.dev/docs/pressable"}]'::jsonb from public.question_revisions r where r.question_id = 'rncomp-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
