insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تستخدم مكون SectionList لعرض البيانات المقسمة إلى مجموعات مصنفة مع رؤوس ثابتة (Sticky Headers)؟', 'يستخدم SectionList لعرض بيانات هيكلية مقسمة إلى أقسام (Sections) لكل منها عنوان ومجموعة عناصر، مع دعم تثبيت الترويسة أعلى الشاشة تلقائياً أثناء التمرير.', 'يستقبل SectionList مصفوفة من كائنات الأقسام بصيغة [{ title: "...", data: [...] }]، ويوفر خاصية renderSectionHeader لرسم ترويسة كل قسم، وخاصية renderItem لرسم العناصر الفردية. خاصية stickySectionHeadersEnabled تفعل التثبيت التلقائي للعنوان حتى انتهاء القسم.', 'import { SectionList, Text, View } from ''react-native'';

const SECTIONS = [
  { title: ''أ'', data: [''أحمد'', ''أمجد'', ''أيمن''] },
  { title: ''ب'', data: [''باسم'', ''براء'', ''بلال''] }
];

function ContactsList() {
  return (
    <SectionList
      sections={SECTIONS}
      keyExtractor={(item, index) => item + index}
      renderItem={({ item }) => <Text style={{ padding: 12 }}>{item}</Text>}
      renderSectionHeader={({ section: { title } }) => (
        <View style={{ backgroundColor: ''#eee'', padding: 8 }}>
          <Text style={{ fontWeight: ''bold'' }}>{title}</Text>
        </View>
      )}
      stickySectionHeadersEnabled={true}
    />
  );
}', '["تمرير مصفوفة مسطحة بدلاً من الهيكل الإلزامي للأقسام المتضمن خاصية data كمصفوفة فرعية."]'::jsonb, '["كيف تخصص خلفية الترويسة المثبتة لتفادي شفافية المحتوى الذي يمر خلفها أثناء التمرير؟"]'::jsonb, '[{"title":"Core Components & Primitives Documentation","url":"https://reactnative.dev/docs/sectionlist"}]'::jsonb from public.question_revisions r where r.question_id = 'rncomp-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
