insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تتعامل مع مشكلة حجب لوحة المفاتيح للمدخلات باستخدام KeyboardAvoidingView؟', 'نغلف حقول الإدخال بمكون KeyboardAvoidingView ونحدد خاصية behavior المناسبة ("padding" لنظام iOS و "height" أو التعديل في AndroidManifest لأندرويد).', 'عند فتح لوحة المفاتيح الافتراضية، فإنها تغطي الجزء السفلي من الشاشة وقد تحجب حقل الإدخال الذي يكتب فيه المستخدم. يوفر KeyboardAvoidingView إمكانية ضبط التمرير تلقائياً ورفع الحاوية للأعلى بمقدار ارتفاع لوحة المفاتيح. في المشاريع الكبيرة غالباً ما تستخدم مكتبات متطورة مثل react-native-keyboard-controller لتجربة أكثر ثباتاً.', 'import { KeyboardAvoidingView, Platform, TextInput, StyleSheet } from ''react-native'';

function LoginForm() {
  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === ''ios'' ? ''padding'' : ''height''}
      style={styles.container}
      keyboardVerticalOffset={Platform.OS === ''ios'' ? 64 : 0}
    >
      <TextInput placeholder="اسم المستخدم" style={styles.input} />
      <TextInput placeholder="كلمة المرور" secureTextEntry style={styles.input} />
    </KeyboardAvoidingView>
  );
}', '["استخدام behavior=\"padding\" على أجهزة أندرويد دون داعٍ، حيث يتكفل نظام أندرويد بتعديل الشاشة افتراضياً عبر windowSoftInputMode=\"adjustResize\"."]'::jsonb, '["كيف تتكامل مكتبة react-native-keyboard-aware-scroll-view لحل مشكلات النماذج الطويلة؟"]'::jsonb, '[{"title":"Core Components & Primitives Documentation","url":"https://reactnative.dev/docs/keyboardavoidingview"}]'::jsonb from public.question_revisions r where r.question_id = 'rncomp-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
