insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين مكون Switch ومكون ActivityIndicator وكيف تخصص مظهرهما عبر المنصتين؟', 'مكون Switch يعرض زر تبديل منطقي (On/Off) أصلي لنظام التشغيل، بينما ActivityIndicator يعرض سبينر تحميل دائري؛ وكلاهما يدعم تخصيص الألوان والحجم ليتناسب مع هوية التطبيق.', 'يستخدم Switch خصائص مثل trackColor و thumbColor لتوحيد ألوان المفتاح بين iOS وأندرويد مع الحفاظ على الرسوم الحركية الخاصة بكل نظام. بينما يقبل ActivityIndicator أحجام "small" أو "large" مع خاصية color لتغيير لون الدائرة المتحركة بما يتناسب مع ثيم الشاشة الحالي.', 'import { Switch, ActivityIndicator, View } from ''react-native'';

function SettingsItem({ enabled, onToggle, loading }: { enabled: boolean; onToggle: () => void; loading: boolean }) {
  if (loading) {
    return <ActivityIndicator size="small" color="#0066cc" />;
  }

  return (
    <Switch
      value={enabled}
      onValueChange={onToggle}
      trackColor={{ false: ''#767577'', true: ''#81b0ff'' }}
      thumbColor={enabled ? ''#0066cc'' : ''#f4f3f4''}
    />
  );
}', '["محاولة تمرير قيم بكسل رقمية عشوائية لخاصية size في ActivityIndicator، حيث تقبل فقط \"small\" أو \"large\" في النظام القياسي."]'::jsonb, '["كيف تنشئ مؤشر تحميل مخصص يعتمد على SVG أو Lottie animations للهويات البصرية المتقدمة؟"]'::jsonb, '[{"title":"Core Components & Primitives Documentation","url":"https://reactnative.dev/docs/switch"}]'::jsonb from public.question_revisions r where r.question_id = 'rncomp-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
