insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يعتبر StyleSheet.create مفضلاً على استخدام Inline Styles المباشرة؟', 'لأنه يتحقق من صحة أسماء وقيم التنسيقات عند الإنشاء، ويوفر أمان الأنواع في TypeScript، ويرسل التنسيقات مرة واحدة عبر الذاكرة الأصلية لربطها بمعرفات رقمية ثابتة (IDs) بدلاً من إنشاء كائنات جديدة في كل دورة تصيير.', 'كتابة style={{ padding: 16 }} مباشرة داخل JSX تؤدي إلى إنشاء كائن JavaScript جديد تماماً في كل مرة يتم فيها تصيير المكون. هذا يثقل عمل الـ Garbage Collector ويفشل مقارنة الفحص السطحي للـ Props. يضمن StyleSheet.create تجميع التنسيقات وثبات مراجعها وتسهيل قراءتها وتنظيمها خارج الـ JSX.', 'import { StyleSheet, View } from ''react-native'';

const styles = StyleSheet.create({
  card: {
    padding: 16,
    borderRadius: 12,
    backgroundColor: ''#fff'',
  }
});

function Card() {
  return <View style={styles.card} />;
}', '["إعادة إنشاء StyleSheet.create داخل جسم دالة المكون بدلاً من وضعها خارج نطاق الدالة في أسفل الملف."]'::jsonb, '["متى نضطر لاستخدام Inline Styles لتطبيق قيم متغيرة ديناميكياً صادرة من Props أو حسابات آنية؟"]'::jsonb, '[{"title":"Styling, Layout & Flexbox Documentation","url":"https://reactnative.dev/docs/stylesheet"}]'::jsonb from public.question_revisions r where r.question_id = 'rnstyle-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnstyle-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يعتبر StyleSheet.create مفضلاً على استخدام Inline Styles المباشرة؟' or l.short_answer is distinct from 'لأنه يتحقق من صحة أسماء وقيم التنسيقات عند الإنشاء، ويوفر أمان الأنواع في TypeScript، ويرسل التنسيقات مرة واحدة عبر الذاكرة الأصلية لربطها بمعرفات رقمية ثابتة (IDs) بدلاً من إنشاء كائنات جديدة في كل دورة تصيير.' or l.explanation is distinct from 'كتابة style={{ padding: 16 }} مباشرة داخل JSX تؤدي إلى إنشاء كائن JavaScript جديد تماماً في كل مرة يتم فيها تصيير المكون. هذا يثقل عمل الـ Garbage Collector ويفشل مقارنة الفحص السطحي للـ Props. يضمن StyleSheet.create تجميع التنسيقات وثبات مراجعها وتسهيل قراءتها وتنظيمها خارج الـ JSX.' or l.code_example is distinct from 'import { StyleSheet, View } from ''react-native'';

