insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تتعامل مع تصميم واجهات متجاوبة (Responsive Layouts) لمختلف أحجام الهواتف والتابلت؟', 'باستخدام useWindowDimensions لمراقبة تغييرات الحجم وتدوير الشاشة، مقترنة بنسب Flexbox المئوية والمكتبات المساعدة لحساب مقاييس متناسبة (Scaling utilities).', 'تختلف مقاسات الشاشات من هواتف صغيرة 4.7 إنش إلى أجهزة تابلت 12.9 إنش. يوفر useWindowDimensions قراءات فورية لـ width و height ويتحدث تلقائياً عند تدوير الجهاز. يتم استخدام نقاط توقف (Breakpoints) لتحديد هل الجهاز هاتف أم لوحي وتغيير اتجاه العرض أو عدد الأعمدة في القوائم تبعاً لذلك.', 'import { useWindowDimensions, View, StyleSheet } from ''react-native'';

function ResponsiveContainer({ children }: { children: React.ReactNode }) {
  const { width } = useWindowDimensions();
  const isTablet = width >= 768;

  return (
    <View style={[styles.base, isTablet ? styles.tabletLayout : styles.phoneLayout]}>
      {children}
    </View>
  );
}', '["استخدام Dimensions.get(\"window\") الثابت خارج المكونات مما يمنع تحديث التخطيط عند تدوير الهاتف (Orientation Change) أو في وضع الشاشات المقسمة."]'::jsonb, '["ما الفرق بين الأبعاد الناتجة عن \"window\" والأبعاد الناتجة عن \"screen\" في أجهزة أندرويد؟"]'::jsonb, '[{"title":"Styling, Layout & Flexbox Documentation","url":"https://reactnative.dev/docs/usewindowdimensions"}]'::jsonb from public.question_revisions r where r.question_id = 'rnstyle-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnstyle-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تتعامل مع تصميم واجهات متجاوبة (Responsive Layouts) لمختلف أحجام الهواتف والتابلت؟' or l.short_answer is distinct from 'باستخدام useWindowDimensions لمراقبة تغييرات الحجم وتدوير الشاشة، مقترنة بنسب Flexbox المئوية والمكتبات المساعدة لحساب مقاييس متناسبة (Scaling utilities).' or l.explanation is distinct from 'تختلف مقاسات الشاشات من هواتف صغيرة 4.7 إنش إلى أجهزة تابلت 12.9 إنش. يوفر useWindowDimensions قراءات فورية لـ width و height ويتحدث تلقائياً عند تدوير الجهاز. يتم استخدام نقاط توقف (Breakpoints) لتحديد هل الجهاز هاتف أم لوحي وتغيير اتجاه العرض أو عدد الأعمدة في القوائم تبعاً لذلك.' or l.code_example is distinct from 'import { useWindowDimensions, View, StyleSheet } from ''react-native'';

function ResponsiveContainer({ children }: { children: React.ReactNode }) {
  const { width } = useWindowDimensions();
  const isTablet = width >= 768;

  return (
    <View style={[styles.base, isTablet ? styles.tabletLayout : styles.phoneLayout]}>
      {children}
    </View>
  );
