insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير الوضع الليلي والنهاري (Dark & Light Mode) بسلاسة بالاعتماد على useColorScheme؟', 'باستخدام خطاف useColorScheme للاستماع لسمة نظام تشغيل الجهاز، وربطه بكائن ألوان ديناميكي أو Theme Provider لتحديث ألوان الشاشات فورياً.', 'يراقب useColorScheme إعدادات مظهر الجهاز في الوقت الفعلي ويعيد "light" أو "dark" أو null. نقوم بإنشاء لوحة ألوان (Color Palette) مركزية تستخرج القيم الصحيحة بناءً على السمة النشطة، مع إمكانية توفير خيار للمستخدم لاختيار الثيم يدوياً وتخزينه في التخزين المحلي لتجاوز إعدادات النظام.', 'import { useColorScheme, View, Text, StyleSheet } from ''react-native'';

function ThemedScreen() {
  const theme = useColorScheme() ?? ''light'';
  const isDark = theme === ''dark'';

  return (
    <View style={[styles.container, { backgroundColor: isDark ? ''#121212'' : ''#ffffff'' }]}>
      <Text style={{ color: isDark ? ''#ffffff'' : ''#000000'' }}>مرحباً بك في التطبيق</Text>
    </View>
  );
}', '["استخدام Appearance.getColorScheme() الثابت غير التفاعلي بدلاً من خطاف useColorScheme التفاعلي الذي يستمع للتبديل الفوري."]'::jsonb, '["كيف تتأكد من تحديث لون شريط الحالة (StatusBar style) ليتطابق مع مظهر الثيم الداكن والفاتح؟"]'::jsonb, '[{"title":"Styling, Layout & Flexbox Documentation","url":"https://reactnative.dev/docs/usecolorscheme"}]'::jsonb from public.question_revisions r where r.question_id = 'rnstyle-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
