insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الفرق الجوهري بين Native Stack Navigator و Stack Navigator في React Navigation؟', 'الـ Native Stack يستفيد من مكونات التنقل الأصلية لنظامي التشغيل (UINavigationController على iOS و FragmentManager على Android) لأداء فائق بمعدل 60fps، بينما الـ Stack العادي يحاكي الحركات بكود JavaScript خالص داخل الـ JS Thread.', 'يوفر @react-navigation/native-stack أداءً أصلياً حقيقياً، مع دعم الحركات الانتقالية الافتراضية للنظام (مثل حركة السحب للرجوع الإيمائية التفاعلية في iOS دون أي تقطيع)، وتثبيت شريط العنوان الأصلي واستخدام ذاكرة أقل. بينما يوفر @react-navigation/stack العادي مرونة أكبر لتخصيص الحركات المعقدة غير القياسية عبر الجافاسكربت على حساب الأداء.', 'import { createNativeStackNavigator } from ''@react-navigation/native-stack'';

const Stack = createNativeStackNavigator();

function AppNavigation() {
  return (
    <Stack.Navigator screenOptions={{ headerBackTitleVisible: false }}>
      <Stack.Screen name="Home" component={HomeScreen} />
      <Stack.Screen name="Details" component={DetailsScreen} />
    </Stack.Navigator>
  );
}', '["استخدام Stack Navigator الكلاسيكي المبني بالـ JS في التطبيقات الحديثة دون حاجة لتخصيصات شاذة، مما يسبب ثقلاً في الحركات الانتقالية."]'::jsonb, '["ما هي مكتبة react-native-screens وكيف تمثل العمود الفقري الذي يعتمد عليه Native Stack Navigator؟"]'::jsonb, '[{"title":"React Navigation & Screen Stacks Documentation","url":"https://reactnavigation.org/docs/native-stack-navigator"}]'::jsonb from public.question_revisions r where r.question_id = 'rnnav-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
