const Stack = createNativeStackNavigator();

function HomeTabs() {
  return (
    <Tab.Navigator>
      <Tab.Screen name="Feed" component={FeedScreen} />
      <Tab.Screen name="Profile" component={ProfileScreen} />
    </Tab.Navigator>
  );
}

function RootNavigator() {
  return (
    <Stack.Navigator>
      <Stack.Screen name="MainTabs" component={HomeTabs} options={{ headerShown: false }} />
      <Stack.Screen name="Checkout" component={CheckoutScreen} />
    </Stack.Navigator>
  );
}', '["تغليف الـ Root Stack بداخل كل تبويب في الـ Bottom Tab بشكل منفصل، مما يسبب تكرار الـ Stacks واستهلاكاً ضخماً للذاكرة وبقاء شريط التبويب ظاهراً فوق شاشات الدفع."]'::jsonb, '["كيف تتنقل برمجياً إلى مسار عميق متداخل باستخدام بنية navigate(\"MainTabs\", { screen: \"Profile\" })؟"]'::jsonb, '[{"title":"React Navigation & Screen Stacks Documentation","url":"https://reactnavigation.org/docs/nesting-navigators"}]'::jsonb from public.question_revisions r where r.question_id = 'rnnav-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
