insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي أحداث دورة حياة الشاشة في React Navigation (useFocusEffect و useIsFocused)؟', 'نظراً لأن الشاشات تظل معلقة في الذاكرة داخل مكدس الـ Stack عند الانتقال للأمام، فإن useEffect العادي لا يعمل عند الرجوع؛ لذلك نستخدم useFocusEffect لتشغيل المنطق في كل مرة تصبح فيها الشاشة نشطة ومعروضة.', 'عندما ينتقل المستخدم من الشاشة A إلى الشاشة B، تظل الشاشة A مركبة في الشجرة (Mounted) دون إزالتها لتسهيل الرجوع الفوري. إذا كنت تريد تحديث البيانات أو إعادة الاستماع لحدث ما بمجرد عودة المستخدم للشاشة، نستخدم useFocusEffect مقترنة بـ useCallback لإعادة تشغيل الكود وتنظيفه فور مغادرة الشاشة.', 'import { useFocusEffect } from ''@react-navigation/native'';
import { useCallback } from ''react'';

function UserProfileScreen() {
  useFocusEffect(
    useCallback(() => {
      // ينفذ فور أن تصبح الشاشة في بؤرة التركيز
      fetchLatestProfileData();

      return () => {
        // دالة تنظيف تنفذ عند فقدان التركيز
        stopPolling();
      };
    }, [])
  );

  return <View>{/* ... */}</View>;
}', '["نسيان تغليف الدالة داخل useFocusEffect بـ useCallback مما يسبب تشغيلها في كل إعادة تصيير بلا توقف."]'::jsonb, '["ما الفرق بين useIsFocused البسيط و useFocusEffect في إدارة التأثيرات ذات دوال التنظيف؟"]'::jsonb, '[{"title":"React Navigation & Screen Stacks Documentation","url":"https://reactnavigation.org/docs/use-focus-effect"}]'::jsonb from public.question_revisions r where r.question_id = 'rnnav-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
