insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تخصص شريط العنوان العلوي (Custom Navigation Header) مع الحفاظ على أداء الـ Native؟', 'باستخدام خاصية headerTitle لتمرير مكون مخصص أو تخصيص headerStyle و headerTintColor، وتجنب استخدام header الكامل المكتوب بـ JS إن لم تكن هناك حاجة قاهرة.', 'يوفر Native Stack خيارات ممتازة لتخصيص العنوان عبر إعدادات أصلية مثل headerLargeTitle (في iOS)، وأزرار جانبية عبر headerRight و headerLeft. إذا استبدلت الـ Header بالكامل بمكون JS عبر header: () => <CustomHeader />، تفقد ميزات الرسوم الأصلية وشريط البحث المدمج Native Search Bar وسلاسة حركات الـ Blur.', '<Stack.Screen
  name="Inbox"
  component={InboxScreen}
  options={{
    headerTitle: ''صندوق الوارد'',
    headerLargeTitle: true, // ميزة iOS الأصلية للترويسات الكبيرة
    headerSearchBarOptions: {
      placeholder: ''ابحث في الرسائل...'',
      onChangeText: (event) => searchMessages(event.nativeEvent.text),
    },
    headerRight: () => (
      <Pressable onPress={openSettings}><Icon name="settings" /></Pressable>
    ),
  }}
/>', '["استبدال الهيدر كاملاً بمكون واجهة عادية داخل كل شاشة مما يسبب قفزات بصرية أثناء الانتقال واختفاء دعم الترويسات الكبيرة الأصلية."]'::jsonb, '["كيف تتكامل ميزة headerTransparent مع صور الغلاف التي تمتد خلف شريط العنوان الشفاف؟"]'::jsonb, '[{"title":"React Navigation & Screen Stacks Documentation","url":"https://reactnavigation.org/docs/native-stack-navigator#options"}]'::jsonb from public.question_revisions r where r.question_id = 'rnnav-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnnav-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تخصص شريط العنوان العلوي (Custom Navigation Header) مع الحفاظ على أداء الـ Native؟' or l.short_answer is distinct from 'باستخدام خاصية headerTitle لتمرير مكون مخصص أو تخصيص headerStyle و headerTintColor، وتجنب استخدام header الكامل المكتوب بـ JS إن لم تكن هناك حاجة قاهرة.' or l.explanation is distinct from 'يوفر Native Stack خيارات ممتازة لتخصيص العنوان عبر إعدادات أصلية مثل headerLargeTitle (في iOS)، وأزرار جانبية عبر headerRight و headerLeft. إذا استبدلت الـ Header بالكامل بمكون JS عبر header: () => <CustomHeader />، تفقد ميزات الرسوم الأصلية وشريط البحث المدمج Native Search Bar وسلاسة حركات الـ Blur.' or l.code_example is distinct from '<Stack.Screen
  name="Inbox"
  component={InboxScreen}
  options={{
    headerTitle: ''صندوق الوارد'',
    headerLargeTitle: true, // ميزة iOS الأصلية للترويسات الكبيرة
    headerSearchBarOptions: {
      placeholder: ''ابحث في الرسائل...'',
      onChangeText: (event) => searchMessages(event.nativeEvent.text),
    },
    headerRight: () => (
      <Pressable onPress={openSettings}><Icon name="settings" /></Pressable>
    ),
  }}
/>' or l.common_mistakes is distinct from '["استبدال الهيدر كاملاً بمكون واجهة عادية داخل كل شاشة مما يسبب قفزات بصرية أثناء الانتقال واختفاء دعم الترويسات الكبيرة الأصلية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتكامل ميزة headerTransparent مع صور الغلاف التي تمتد خلف شريط العنوان الشفاف؟"]'::jsonb or l.sources is distinct from '[{"title":"React Navigation & Screen Stacks Documentation","url":"https://reactnavigation.org/docs/native-stack-navigator#options"}]'::jsonb)) then raise exception 'Question rnnav-008 ar content changed; create a new revision before seeding'; end if; end $$;
