insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تستخدم Zustand مع MMKV لإنشاء مخزن حالة عالمي متزامن ومحفوظ محلياً (Persistent Store)؟', 'بدمج خاصية persist middleware في Zustand وتمرير محول تخزين مخصص (Custom Storage Engine) يوجه عمليات القراءة والكتابة إلى MMKV المتزامنة.', 'يوفر هذا الدمج الحل الأمثل لحفظ واسترجاع حالة التطبيق تلقائياً (مثل تفضيلات الثيم، بيانات الجلسة، واللغة). نظراً لأن MMKV متزامنة، فإن استعادة الحالة تكون فورية وخالية من وميض الشاشة الافتراضية، مع إمكانية تحديد الحقول المراد حفظها فقط عبر partialize.', 'import { create } from ''zustand'';
import { persist, createJSONStorage } from ''zustand/middleware'';
import { MMKV } from ''react-native-mmkv'';

const storage = new MMKV();
const mmkvStorage = {
  setItem: (name: string, value: string) => storage.set(name, value),
  getItem: (name: string) => storage.getString(name) ?? null,
  removeItem: (name: string) => storage.delete(name),
};

export const useUserStore = create(
  persist<{ name: string; setName: (n: string) => void }>(
    (set) => ({
      name: '''',
      setName: (name) => set({ name }),
    }),
    {
      name: ''user-storage'',
      storage: createJSONStorage(() => mmkvStorage),
    }
  )
);', '["حفظ كائنات غير قابلة للتسلسل (كالـ functions أو circular objects) داخل الـ persistent store."]'::jsonb, '["كيف تعالج ترقية هيكل البيانات المحفوظة القديمة باستخدام ميزة migrate في persist middleware؟"]'::jsonb, '[{"title":"State & Local Storage (AsyncStorage, MMKV) Documentation","url":"https://reactnative.dev/docs/state"}]'::jsonb from public.question_revisions r where r.question_id = 'rnstore-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
