  // 1. مسح رموز التوثيق المشفرة
  await SecureStore.deleteItemAsync(''auth_token'');
  // 2. مسح كاش الـ API
  queryClient.clear();
  // 3. إعادة ضبط مخازن الحالة
  useUserStore.getState().reset();
  // 4. حذف التخزين المحلي السريع
  storage.clearAll();
}', '["الاكتفاء بمسح الـ token من الـ State في الذاكرة دون حذفه من التخزين الدائم أو كاش الاستعلامات."]'::jsonb, '["كيف تتأكد من إلغاء تسجيل توكن الإشعارات (Push Notification Token) من السيرفر عند تسجيل الخروج؟"]'::jsonb, '[{"title":"State & Local Storage (AsyncStorage, MMKV) Documentation","url":"https://reactnative.dev/docs/security"}]'::jsonb from public.question_revisions r where r.question_id = 'rnstore-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
