const handlePress = () => {
  // تحديث حركي مرن بدون أي re-render
  progress.value = withSpring(1);
};', '["محاولة قراءة أو كتابة sharedValue.value مباشرة داخل مرحلة الـ Render لدالة المكون."]'::jsonb, '["كيف تحافظ القيم المشتركة على تزامنها بين الخيوط دون حدوث مشاكل سباق الذاكرة (Race Conditions)؟"]'::jsonb, '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'rnanim-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
