insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي حركات العناصر المشتركة (Shared Element Transitions) بين الشاشات وكيف تنفذها؟', 'هي حركة انتقال سلسة لعنصر بصري (مثل صورة منتج) أثناء الانتقال من شاشة القائمة إلى شاشة التفاصيل ليتوسع بسلاسة من موضعه الأصلي إلى موضعه النهائي في الشاشة الجديدة.', 'توفر Reanimated v3 دعماً مدمجاً لحركات العناصر المشتركة عبر خاصية sharedTransitionTag. عندما تحتوي الشاشة الأولى والشاشة الثانية على عنصرين يحملان نفس الـ tag، يقوم محرك الحركات بحساب مسار التحول ومطابقة أبعاد العنصر وموضعه بسلاسة سينمائية دون أي انقطاع أثناء تنقل الراوتر.', '// في شاشة القائمة:
<Animated.Image
  source={{ uri: item.imageUrl }}
  sharedTransitionTag={`image-${item.id}`}
  style={styles.thumbnail}
/>

// في شاشة التفاصيل:
<Animated.Image
  source={{ uri: item.imageUrl }}
  sharedTransitionTag={`image-${item.id}`}
  style={styles.fullHeroImage}
/>', '["استخدام sharedTransitionTag متطابق لأكثر من عنصر ظاهر على نفس الشاشة مما يسبب تعارض المعرفات."]'::jsonb, '["كيف تتكامل Shared Element Transitions مع Native Stack Navigator في React Navigation؟"]'::jsonb, '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'rnanim-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnanim-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي حركات العناصر المشتركة (Shared Element Transitions) بين الشاشات وكيف تنفذها؟' or l.short_answer is distinct from 'هي حركة انتقال سلسة لعنصر بصري (مثل صورة منتج) أثناء الانتقال من شاشة القائمة إلى شاشة التفاصيل ليتوسع بسلاسة من موضعه الأصلي إلى موضعه النهائي في الشاشة الجديدة.' or l.explanation is distinct from 'توفر Reanimated v3 دعماً مدمجاً لحركات العناصر المشتركة عبر خاصية sharedTransitionTag. عندما تحتوي الشاشة الأولى والشاشة الثانية على عنصرين يحملان نفس الـ tag، يقوم محرك الحركات بحساب مسار التحول ومطابقة أبعاد العنصر وموضعه بسلاسة سينمائية دون أي انقطاع أثناء تنقل الراوتر.' or l.code_example is distinct from '// في شاشة القائمة:
<Animated.Image
  source={{ uri: item.imageUrl }}
  sharedTransitionTag={`image-${item.id}`}
  style={styles.thumbnail}
/>

// في شاشة التفاصيل:
<Animated.Image
  source={{ uri: item.imageUrl }}
  sharedTransitionTag={`image-${item.id}`}
  style={styles.fullHeroImage}
/>' or l.common_mistakes is distinct from '["استخدام sharedTransitionTag متطابق لأكثر من عنصر ظاهر على نفس الشاشة مما يسبب تعارض المعرفات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتكامل Shared Element Transitions مع Native Stack Navigator في React Navigation؟"]'::jsonb or l.sources is distinct from '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb)) then raise exception 'Question rnanim-005 ar content changed; create a new revision before seeding'; end if; end $$;
