insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى نستخدم Lottie Animations وكيف نتحكم في تشغيل ملفات JSON الحركية في React Native؟', 'نستخدم Lottie لعرض الرسوم المعقدة التي يصممها محترفو الأنيميشن على Adobe After Effects وتصديرها كملفات JSON متجهة خفيفة، باستخدام مكتبة lottie-react-native.', 'توفر ملفات Lottie رسوماً متحركة مبهرة (أيقونات تفاعلية، شاشات نجاح، رسوم بيانية) بحجم ملفات ضئيل جداً مقارنة بالفيديو أو الـ GIFs، مع الحفاظ على دقة المتجهات (Vector Graphics) دون أي بكسلة على مختلف مقاسات الشاشات، مع إمكانية التحكم برمجياً في التقدم والسرعة والإيقاف المؤقت.', 'import LottieView from ''lottie-react-native'';
import { useRef } from ''react'';

function SuccessAnimation() {
  const animationRef = useRef<LottieView>(null);

  return (
    <LottieView
      ref={animationRef}
      source={require(''./assets/success-check.json'')}
      autoPlay
      loop={false}
      style={{ width: 120, height: 120 }}
    />
  );
}', '["استخدام ملفات Lottie غير محسنة تحتوي على صور مدمجة بصيغة Base64 مما يضخم حجم ملف الـ JSON ويستهلك الذاكرة."]'::jsonb, '["كيف تدعم مكتبة dotLottie ضغط ملفات الأنيميشن لتصبح أصغر بنسبة تصل لـ 80% مقارنة بـ JSON العادي؟"]'::jsonb, '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'rnanim-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
