insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي حركات النوابض الفيزيائية (Spring Physics) ومزاياها مقارنة بالحركات التوقيتية (Timing Animations)؟', 'حركات الـ Spring تحاكي القوانين الفيزيائية الحقيقية (الكتلة والصلابة والتخميد) دون تحديد مدة زمنية ثابتة، وتتكيف طبيعياً مع سرعة إيماءة إصبع المستخدم دون توقف مصطنع.', 'الحركات المعتمدة على المدة الزمنية الثابتة (Timing مع Duration و Easing) تبدو آلية وجافة وغالباً ما تصطدم بحركة إصبع المستخدم إذا كان سريعاً. بينما تحسب فيزياء الـ Spring سرعة الانطلاق (Velocity)، والتخميد (Damping)، والصلابة (Stiffness)، مما يمنح الواجهة ملمساً طبيعياً ومرناً يشبه سحب الأجسام الحقيقية.', 'import { withSpring } from ''react-native-reanimated'';

// حركة نابض فيزيائية عالية الاستجابة
offset.value = withSpring(100, {
  damping: 12,
  stiffness: 100,
  mass: 0.5,
});', '["ضبط قيمة تخميد (damping) منخفضة جداً مما يجعل العنصر يرتد ويتذبذب إلى ما لا نهاية ويشتت المستخدم."]'::jsonb, '["ما الفرق بين تكوين mass و stiffness في تحديد استجابة وسرعة ارتداد الأزرار عند الضغط؟"]'::jsonb, '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'rnanim-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnanim-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي حركات النوابض الفيزيائية (Spring Physics) ومزاياها مقارنة بالحركات التوقيتية (Timing Animations)؟' or l.short_answer is distinct from 'حركات الـ Spring تحاكي القوانين الفيزيائية الحقيقية (الكتلة والصلابة والتخميد) دون تحديد مدة زمنية ثابتة، وتتكيف طبيعياً مع سرعة إيماءة إصبع المستخدم دون توقف مصطنع.' or l.explanation is distinct from 'الحركات المعتمدة على المدة الزمنية الثابتة (Timing مع Duration و Easing) تبدو آلية وجافة وغالباً ما تصطدم بحركة إصبع المستخدم إذا كان سريعاً. بينما تحسب فيزياء الـ Spring سرعة الانطلاق (Velocity)، والتخميد (Damping)، والصلابة (Stiffness)، مما يمنح الواجهة ملمساً طبيعياً ومرناً يشبه سحب الأجسام الحقيقية.' or l.code_example is distinct from 'import { withSpring } from ''react-native-reanimated'';

// حركة نابض فيزيائية عالية الاستجابة
offset.value = withSpring(100, {
  damping: 12,
  stiffness: 100,
  mass: 0.5,
});' or l.common_mistakes is distinct from '["ضبط قيمة تخميد (damping) منخفضة جداً مما يجعل العنصر يرتد ويتذبذب إلى ما لا نهاية ويشتت المستخدم."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين تكوين mass و stiffness في تحديد استجابة وسرعة ارتداد الأزرار عند الضغط؟"]'::jsonb or l.sources is distinct from '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb)) then raise exception 'Question rnanim-007 ar content changed; create a new revision before seeding'; end if; end $$;
