insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني مؤشر تمرير مخصص (Custom Scroll Interpolation) باستخدام useAnimatedScrollHandler؟', 'باستخدام useAnimatedScrollHandler لتسجيل إزاحة التمرير (contentOffset.y) في قيمة Shared Value، واستخدام interpolate لربطها بتغيير شفافية أو حجم شريط العنوان بسلاسة.', 'يتيح useAnimatedScrollHandler الاستماع لأحداث التمرير بدقة 60 إطاراً في الثانية على الـ UI Thread. من خلال دالة interpolate، نقوم بتعيين مجال الإدخال (مثلاً التمرير من 0 إلى 150 بكسل) إلى مجال الإخراج (تقليص حجم العنوان من 1 إلى 0.8 وتغيير خلفية الهيدر من شفافة إلى معتمة).', 'const scrollY = useSharedValue(0);

const scrollHandler = useAnimatedScrollHandler({
  onScroll: (event) => {
    scrollY.value = event.contentOffset.y;
  },
});

const headerStyle = useAnimatedStyle(() => ({
  opacity: interpolate(scrollY.value, [0, 100], [0, 1], Extrapolate.CLAMP),
}));

<Animated.ScrollView onScroll={scrollHandler} scrollEventThrottle={16}>
  {/* المحتوى */}
</Animated.ScrollView>;', '["نسيان تحديد خاصية scrollEventThrottle={16} مما يجعل نظام iOS يرسل أحداث التمرير على فترات متباعدة وغير سلسة."]'::jsonb, '["ما هي أهمية استخدام Extrapolate.CLAMP لمنع تمدد قيم الإخراج خارج الحدود المحددة؟"]'::jsonb, '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'rnanim-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnanim-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تبني مؤشر تمرير مخصص (Custom Scroll Interpolation) باستخدام useAnimatedScrollHandler؟' or l.short_answer is distinct from 'باستخدام useAnimatedScrollHandler لتسجيل إزاحة التمرير (contentOffset.y) في قيمة Shared Value، واستخدام interpolate لربطها بتغيير شفافية أو حجم شريط العنوان بسلاسة.' or l.explanation is distinct from 'يتيح useAnimatedScrollHandler الاستماع لأحداث التمرير بدقة 60 إطاراً في الثانية على الـ UI Thread. من خلال دالة interpolate، نقوم بتعيين مجال الإدخال (مثلاً التمرير من 0 إلى 150 بكسل) إلى مجال الإخراج (تقليص حجم العنوان من 1 إلى 0.8 وتغيير خلفية الهيدر من شفافة إلى معتمة).' or l.code_example is distinct from 'const scrollY = useSharedValue(0);

const scrollHandler = useAnimatedScrollHandler({
  onScroll: (event) => {
    scrollY.value = event.contentOffset.y;
  },
});

const headerStyle = useAnimatedStyle(() => ({
  opacity: interpolate(scrollY.value, [0, 100], [0, 1], Extrapolate.CLAMP),
}));

<Animated.ScrollView onScroll={scrollHandler} scrollEventThrottle={16}>
  {/* المحتوى */}
</Animated.ScrollView>;' or l.common_mistakes is distinct from '["نسيان تحديد خاصية scrollEventThrottle={16} مما يجعل نظام iOS يرسل أحداث التمرير على فترات متباعدة وغير سلسة."]'::jsonb or l.follow_up_questions is distinct from '["ما هي أهمية استخدام Extrapolate.CLAMP لمنع تمدد قيم الإخراج خارج الحدود المحددة؟"]'::jsonb or l.sources is distinct from '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb)) then raise exception 'Question rnanim-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a React Native developer know about Rn Scroll Interpolation Reanimated Extrapolate 008?', 'This question checks the core Rn Scroll Interpolation Reanimated Extrapolate 008 concept and how to use it safely in React Native, mobile performance, and native integrations.', 'Explain Rn Scroll Interpolation Reanimated Extrapolate 008 with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'const scrollY = useSharedValue(0);

