insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مكتبة React Native Skia وكيف تستخدم للرسوم البيانية والمؤثرات البصرية ثنائية الأبعاد فائقة السرعة؟', 'هي غلاف عالي الأداء لمحرك Google Skia المكتوب بـ C++، يتيح الرسم المباشر على الـ Canvas، وإنشاء التدرجات اللونية الحركية (Shaders)، والرسوم البيانية المخصصة بطلاقة 120fps.', 'محرك Skia هو نفس المحرك الذي يغذي Google Chrome ونظام Android ومكتبة Flutter. عبر @shopify/react-native-skia، يمكنك رسم خطوط وأقواس وأشكال معقدة ومؤثرات ضبابية (Glassmorphism Blur) وفلاتر ألوان مباشرة على كرت الشاشة (GPU) دون أي تكلفة لإنشاء عقد DOM أو Views نظام التشغيل.', 'import { Canvas, Circle, Paint } from ''@shopify/react-native-skia'';

function SkiaGraphic() {
  return (
    <Canvas style={{ width: 200, height: 200 }}>
      <Circle cx={100} cy={100} r={50} color="#00ffcc" />
    </Canvas>
  );
}', '["استخدام مكونات View عادية ومكتبات SVG بطيئة لبناء رسوم بيانية تفاعلية حية تتطلب معالجة آلاف النقاط في الثانية."]'::jsonb, '["كيف تتكامل مكتبة Skia بسلاسة مع Reanimated Shared Values لتحريك مسارات الرسوم البيانية؟"]'::jsonb, '[{"title":"Animations & Gestures (Reanimated & RNGH) Documentation","url":"https://reactnative.dev/docs/animations"}]'::jsonb from public.question_revisions r where r.question_id = 'rnanim-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
