insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني Custom Native Module في أندرويد (Kotlin) وتربطه بـ React Native؟', 'بإنشاء فئة ترث ReactContextBaseJavaModule، ووضع وسم @ReactMethod على الدوال المصدرة، وتسجيلها في ReactPackage مخصص لإضافته إلى getPackages() في MainApplication.', 'يتم تحديد اسم الوحدة عبر دالة getName(). الدوال الموسومة بـ @ReactMethod يمكنها استقبال معاملات أساسية (Strings, Numbers, ReadableMap) واستخدام كائن Promise لإرجاع النتائج أو الأخطاء بشكل غير متزامن إلى شفرة الـ JavaScript.', '// كود Kotlin في مجلد android:
class BatteryModule(reactContext: ReactApplicationContext) : ReactContextBaseJavaModule(reactContext) {
    override fun getName() = "BatteryModule"

    @ReactMethod
    fun getBatteryLevel(promise: Promise) {
        try {
            val level = 85 // قراءة من نظام أندرويد
            promise.resolve(level)
        } catch (e: Exception) {
            promise.reject("ERROR_BATTERY", e.message)
        }
    }
}', '["محاولة إرجاع كائنات مخصصة معقدة مباشرة دون تحويلها إلى WritableMap أو أنواع مدعومة من الـ Bridge."]'::jsonb, '["كيف تختلف كتابة هذه الوحدة في المعمارية الجديدة عبر TurboModule Spec وتوليد واجهات C++ بواسطة Codegen؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://reactnative.dev/docs/native-modules-android"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
