insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني Custom Native Module في نظام iOS (Swift / Objective-C)؟', 'بإنشاء فئة Swift تحتوي على الدوال المرغوبة، واستخدام ملف جسر Objective-C (Bridging Header) وماكرو RCT_EXTERN_MODULE لتسجيلها في شجرة وحدات React Native.', 'نظراً لأن نواة React Native القديمة تعتمد على Objective-C، فإن ربط كود Swift يتطلب كتابة ملف Objective-C صغير لتصدير الفئة والدوال باستخدام RCT_EXTERN_MODULE و RCT_EXTERN_METHOD، مع تحديد ما إذا كانت الوحدة تتطلب التنفيذ على الـ Main Queue أو خيط منفصل.', '// في ملف Swift:
@objc(BatteryModule)
class BatteryModule: NSObject {
  @objc(getBatteryLevel:rejecter:)
  func getBatteryLevel(resolve: RCTPromiseResolveBlock, reject: RCTPromiseRejectBlock) {
    resolve(UIDevice.current.batteryLevel * 100)
  }
}

// في ملف Objective-C المصدر (BatteryModule.m):
#import <React/RCTBridgeModule.h>
@interface RCT_EXTERN_MODULE(BatteryModule, NSObject)
RCT_EXTERN_METHOD(getBatteryLevel:(RCTPromiseResolveBlock)resolve rejecter:(RCTPromiseRejectBlock)reject)
@end', '["نسيان إضافة علامة @objc перед الفئات والدوال في Swift مما يمنع محرك Objective-C من رؤيتها."]'::jsonb, '["كيف تدعم الوحدات إرسال أحداث مستمرة إلى الجافاسكربت عبر وراثة RCTEventEmitter؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://reactnative.dev/docs/native-modules-ios"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
