import { useEffect, useState } from ''react'';

function MotionTracker() {
  const [data, setData] = useState({ x: 0, y: 0, z: 0 });

  useEffect(() => {
    Accelerometer.setUpdateInterval(100);
    const subscription = Accelerometer.addListener(setData);
    return () => subscription.remove();
  }, []);

  return <Text>الميلان: X: {data.x.toFixed(2)}, Y: {data.y.toFixed(2)}</Text>;
}', '["تعيين وتيرة التحديث بتردد فائق (مثل 16ms) دون داعٍ مما يسبب استنزافاً سريعاً لبطارية الهاتف وسخونة المعالج."]'::jsonb, '["كيف يتم دمج قراءات المستشعرات مع مكتبة Reanimated لتحريك عناصر الواجهة وفق ميلان الهاتف (Parallax Effect)؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://docs.expo.dev/versions/latest/sdk/accelerometer/"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
