insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a React Native developer know about Rn Push Notifications Fcm Apns 006?', 'This question checks the core Rn Push Notifications Fcm Apns 006 concept and how to use it safely in React Native, mobile performance, and native integrations.', 'Explain Rn Push Notifications Fcm Apns 006 with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'import * as Notifications from ''expo-notifications'';

async function registerForPushNotifications(): Promise<string | null> {
  const { status } = await Notifications.requestPermissionsAsync();
  if (status !== ''granted'') return null;

  const tokenData = await Notifications.getExpoPushTokenAsync();
  return tokenData.data; // إرسال هذا التوكن لخادم الـ Backend
