insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير التتبع الدقيق للموقع الجغرافي بالخلفية (Background Geolocation) دون إغلاق التطبيق؟', 'بتسجيل مهمة خلفية عبر TaskManager و expo-location مع ضبط نوع النشاط ومسافة التحديث، وضمان الحصول على إذن ACCESS_BACKGROUND_LOCATION الصريح.', 'يفرض كلا النظامين قيوداً صارمة جداً على تتبع الموقع أثناء نوم الشاشة لمنع التجسس وتوفير الطاقة. يتطلب أندرويد إظهار خدمة أمامية دائمة (Foreground Service Notification) توضح للمستخدم أن التطبيق يتتبع موقعه، بينما يتطلب iOS تحديد السبب الدقيق في UIBackgroundModes.', 'import * as TaskManager from ''expo-task-manager'';
import * as Location from ''expo-location'';

const LOCATION_TASK_NAME = ''background-location-task'';

TaskManager.defineTask(LOCATION_TASK_NAME, ({ data, error }) => {
  if (error) return;
  if (data) {
    const { locations } = data as any;
    console.log("الموقع في الخلفية:", locations);
  }
});

// بدء التتبع:
await Location.startLocationUpdatesAsync(LOCATION_TASK_NAME, {
  accuracy: Location.Accuracy.Balanced,
  distanceInterval: 50, // التحديث كل 50 متراً فقط
  showsBackgroundLocationIndicator: true,
});', '["استخدام أقصى دقة للموقع (Highest Accuracy) طوال الوقت مما يستنزف كامل طاقة بطارية الهاتف في أقل من ساعتين."]'::jsonb, '["ما هي الشروط الصارمة التي تفرضها متاجر التطبيقات لقبول التطبيقات التي تستخدم تتبع الموقع في الخلفية؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://docs.expo.dev/versions/latest/sdk/location/"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
