insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تتعامل مع الاهتزازات التفاعلية اللمسية (Haptic Feedback) لتحسين تجربة المستخدم؟', 'باستخدام مكتبة expo-haptics لإطلاق نبضات اهتزازية دقيقة وخفيفة (Light, Medium, Heavy, Success, Error) عند النقر على الأزرار أو السحب لتأكيد الإجراء فيزيائياً.', 'الاهتزازات اللمسية الذكية تمنح التطبيق طابع الفخامة والأصالة عبر محاكاة ملمس الأزرار المادية الحقيقية (Taptic Engine). ينصح بإطلاق Haptics.impactAsync(ImpactFeedbackStyle.Light) عند الضغط على أزرار التبديل، و notificationAsync(NotificationFeedbackType.Success) عند نجاح عملية الدفع.', 'import * as Haptics from ''expo-haptics'';

function ConfirmButton({ onConfirm }: { onConfirm: () => void }) {
  const handlePress = () => {
    // نبضة لمسية خفيفة تؤكد اللمس
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    onConfirm();
  };

  return <Pressable onPress={handlePress}><Text>تأكيد الطلب</Text></Pressable>;
}', '["الإفراط في إطلاق الاهتزازات اللمسية في كل حركة وتمرير مما يزعج المستخدم ويجعله يعطل إشعارات التطبيق."]'::jsonb, '["كيف تتأكد من احترام تفضيلات المستخدم إذا كان قد عطل الاهتزازات في إعدادات إمكانية الوصول في هاتفه؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://docs.expo.dev/versions/latest/sdk/haptics/"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
