insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدمج ميزة مسح وقراءة الباركود ورموز الاستجابة السريعة (QR Code Scanning)؟', 'باستخدام expo-camera أو expo-barcode-scanner مع تحديد خاصية onBarcodeScanned وتحديد أنواع الأكواد المستهدفة لمنع الاستهلاك العشوائي للمعالج.', 'يتم تشغيل معاينة الكاميرا والاستماع لأكواد الباركود. بمجرد التقاط كود صالح، يجب تعطيل المسح فوراً عبر حالة boolean (مثل const [scanned, setScanned] = useState(false)) لمنع استدعاء معالج الحدث عشرات المرات في الثانية الواحدة لنفس الكود.', 'import { CameraView, useCameraPermissions } from ''expo-camera'';
import { useState } from ''react'';

function BarcodeScanner() {
  const [scanned, setScanned] = useState(false);

  const handleBarcodeScanned = ({ data }: { data: string }) => {
    setScanned(true);
    alert(`تم قراءة الكود: ${data}`);
  };

  return (
    <CameraView
      style={{ flex: 1 }}
      barcodeScannerSettings={{ barcodeTypes: [''qr'', ''ean13''] }}
      onBarcodeScanned={scanned ? undefined : handleBarcodeScanned}
    />
  );
}', '["عدم تعطيل خاصية onBarcodeScanned بعد أول قراءة ناجحة مما يطلق سيل طلبات متكررة لنفس الرمز."]'::jsonb, '["كيف ترسم إطاراً مربعاً مرئياً حول منطقة المسح المستهدفة لتوجيه عين المستخدم؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://docs.expo.dev/versions/latest/sdk/camera/"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rndev-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدمج ميزة مسح وقراءة الباركود ورموز الاستجابة السريعة (QR Code Scanning)؟' or l.short_answer is distinct from 'باستخدام expo-camera أو expo-barcode-scanner مع تحديد خاصية onBarcodeScanned وتحديد أنواع الأكواد المستهدفة لمنع الاستهلاك العشوائي للمعالج.' or l.explanation is distinct from 'يتم تشغيل معاينة الكاميرا والاستماع لأكواد الباركود. بمجرد التقاط كود صالح، يجب تعطيل المسح فوراً عبر حالة boolean (مثل const [scanned, setScanned] = useState(false)) لمنع استدعاء معالج الحدث عشرات المرات في الثانية الواحدة لنفس الكود.' or l.code_example is distinct from 'import { CameraView, useCameraPermissions } from ''expo-camera'';
import { useState } from ''react'';

function BarcodeScanner() {
  const [scanned, setScanned] = useState(false);

  const handleBarcodeScanned = ({ data }: { data: string }) => {
    setScanned(true);
    alert(`تم قراءة الكود: ${data}`);
  };

  return (
    <CameraView
      style={{ flex: 1 }}
      barcodeScannerSettings={{ barcodeTypes: [''qr'', ''ean13''] }}
      onBarcodeScanned={scanned ? undefined : handleBarcodeScanned}
    />
  );
