insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير حفظ وقراءة الملفات المحلية باستخدام FileSystem ومشاركة المحتوى عبر Sharing API؟', 'باستخدام expo-file-system لتنزيل الملفات وتخزينها في DocumentDirectory أو CacheDirectory، واستدعاء expo-sharing لمشاركة الملفات مع التطبيقات الأخرى.', 'DocumentDirectory مخصص للملفات الدائمة التي يملكها المستخدم والتي تظل محفوظة أثناء النسخ الاحتياطي، بينما CacheDirectory للملفات المؤقتة التي يمكن للنظام حذفها عند انخفاض مساحة الهاتف. توفر Sharing.shareAsync فتح نافذة المشاركة الأصلية في النظام لإرسال التقارير و PDF عبر البريد أو واتساب.', 'import * as FileSystem from ''expo-file-system'';
import * as Sharing from ''expo-sharing'';

async function downloadAndSharePDF(url: string) {
  const fileUri = FileSystem.documentDirectory + ''invoice.pdf'';
  const downloadResult = await FileSystem.downloadAsync(url, fileUri);

  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(downloadResult.uri);
  }
}', '["حفظ ملفات كاش ضخمة ومؤقتة في DocumentDirectory مما يضخم حجم النسخ الاحتياطي للتطبيق على iCloud و Google Drive."]'::jsonb, '["كيف تتأكد من فحص مساحة التخزين المتبقية في الجهاز قبل بدء تنزيل ملفات فيديو أو تحديثات ضخمة؟"]'::jsonb, '[{"title":"Native Modules & Hardware APIs Documentation","url":"https://docs.expo.dev/versions/latest/sdk/filesystem/"}]'::jsonb from public.question_revisions r where r.question_id = 'rndev-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
