  fetchUserData({ signal: controller.signal })
    .then(data => setUser(data))
    .catch(err => { if (err.name !== ''AbortError'') console.error(err); });

  return () => controller.abort(); // إلغاء فوري عند مغادرة الشاشة
}, [userId]);', '["تجاهل تنظيف مؤقتات setInterval ومستمعي AppState عند فك المكون."]'::jsonb, '["كيف يساعد Profiler أندرويد في اكتشاف تسريبات الـ Bitmaps الناتجة عن فك تشفير صور ضخمة بدقة تفوق دقة الشاشة؟"]'::jsonb, '[{"title":"Performance & Memory Optimization Documentation","url":"https://reactnative.dev/docs/performance"}]'::jsonb from public.question_revisions r where r.question_id = 'rnperf-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
