insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي ظاهرة الـ Overdraw في أجهزة أندرويد وكيف تؤثر على سلاسة رسم الواجهة؟', 'هي قيام النظام برسم نفس البكسل على الشاشة عدة مرات في نفس الإطار نتيجة لتراكم خلفيات ملونة غير ضرورية في حاويات <View> المتداخلة، مما يهدر طاقة كرت الشاشة (GPU).', 'يمكن تفعيل خيار "Show GPU Overdraw" في خيارات مطور أندرويد. العناصر التي تظهر باللون الأزرق رسمت مرة واحدة (ممتاز)، بينما اللون الأخضر مرتان، والوردي والأحمر 3 إلى 4 مرات (سيء). لحل المشكلة، نقوم بإزالة خصائص backgroundColor من الحاويات الداخلية والاعتماد على خلفية الحاوية الرئيسية فقط.', '// نمط سيء يسبب Overdraw عالي:
// <View style={{ backgroundColor: ''#fff'' }}>
//   <View style={{ backgroundColor: ''#fff'' }}>
//     <View style={{ backgroundColor: ''#fff'' }}><Text>نص</Text></View>
//   </View>
// </View>

// نمط سليم ومحسن: خلفية واحدة فقط
<View style={{ backgroundColor: ''#fff'' }}>
  <View>
    <View><Text>نص</Text></View>
