insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تسرع وقت بدء تشغيل التطبيق (Time to Interactive - TTI)؟', 'بالاعتماد على محرك Hermes لتشغيل الـ Bytecode مسبقاً، وتأجيل تهيئة حزم الـ SDK غير العاجلة بالخلفية، وتفادي استدعاءات التخزين والشبكة المتزامنة الثقيلة أثناء عرض الشاشة الأولى.', 'يقاس TTI بالفترة من لحظة نقر أيقونة التطبيق حتى تصبح الشاشة مرسومة بالكامل وقابلة للتفاعل. يتم تسريعه بعرض Splash Screen أصلية فورية، وتجنب استيراد ملفات برميلية ضخمة (Barrel files)، واستخدام الإنشاء الكسول (Lazy initialization) لمكتبات التحليلات (Analytics) والإعلانات حتى بعد اكتمال رسم أول شاشة للمستخدم.', '// تأجيل تهيئة SDK التحليلات الثقيلة لما بعد أول تصيير
useEffect(() => {
  const timer = setTimeout(() => {
    initializeAnalytics();
  }, 2000);
  return () => clearTimeout(timer);
}, []);', '["تنفيذ استعلامات شبكية متتالية وحظر واجهة البداية بانتظار استجابة السيرفر قبل السماح بظهور واجهة التطبيق."]'::jsonb, '["كيف تفيد ميزة Inline Requires في مترجم Metro في تسريع تحميل ملفات الجافاسكربت عند الإقلاع؟"]'::jsonb, '[{"title":"Performance & Memory Optimization Documentation","url":"https://reactnative.dev/docs/performance"}]'::jsonb from public.question_revisions r where r.question_id = 'rnperf-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
