insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي خاصية removeClippedSubviews ومتى يكون تفعيلها سلاحاً ذا حدين؟', 'تقوم بفصل عناصر الـ Native Views التي تقع خارج حدود نافذة العرض من شجرة الرسم الأصلية لتوفير الذاكرة، لكنها قد تسبب وميضاً أو اختفاءً مؤقتاً لبعض العناصر أثناء التمرير السريع.', 'تعتبر removeClippedSubviews مفيدة جداً لتقليل استهلاك الذاكرة في القوائم الضخمة. لكن في بعض إصدارات أندرويد أو مع العناصر التي تحتوي على حقول إدخال وخرائط ونوافذ ويب، قد يؤدي فصلها المفاجئ إلى فقدان حالة التركيز أو ظهور مساحات فارغة بيضاء حتى يلحق النظام بإعادة تركيبها.', '<FlatList
  data={heavyItems}
  removeClippedSubviews={Platform.OS === ''android''}
