insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي معمارية FlashList من Shopify ولماذا تحل كافة مشاكل FlatList التقليدية؟', 'تقوم FlashList بإعادة تدوير خلايا الـ Native Views القائمة واستبدال محتواها الداخلي فقط (Cell Recycling) بدلاً من تدمير وإنشاء مكونات جديدة عند التمرير.', 'عند التمرير في FlatList، يقوم النظام بإنشاء عناصر جديدة وتدمير القديمة، مما يسبب ظهور فراغات بيضاء عند التمرير السريع واستهلاكاً مستمراً للذاكرة. تعتمد FlashList على خوارزمية إعادة التدوير الشبيهة بـ RecyclerView في أندرويد و UICollectionView في iOS، وتتطلب فقط تحديد estimatedItemSize لتعمل بسرعة تفوق FlatList بـ 5 إلى 10 أضعاف.', 'import { FlashList } from ''@shopify/flash-list'';

function ProductFeed({ items }: { items: Product[] }) {
  return (
    <FlashList
      data={items}
      renderItem={({ item }) => <ProductRow item={item} />}
      estimatedItemSize={100} // تحديد متوسط الارتفاع لإعادة التدوير الفورية
    />
  );
}', '["تحديد قيمة estimatedItemSize بعيدة جداً عن الارتفاع الحقيقي مما يربك حسابات شريط التمرير."]'::jsonb, '["كيف تتعامل FlashList مع العناصر ذات الأنواع المختلفة (getItemType) لضمان إعادة تدوير القوالب المطابقة؟"]'::jsonb, '[{"title":"Performance & Memory Optimization Documentation","url":"https://reactnative.dev/docs/flatlist"}]'::jsonb from public.question_revisions r where r.question_id = 'rnperf-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
