insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الـ Expo Config Plugins وكيف تسمح بتعديل كود ومكتبات الـ Native بأمان؟', 'هي دوال برمجية بلغة JavaScript/TypeScript تنفذ أثناء npx expo prebuild لتعديل ملفات البناء الأصلية (مثل Info.plist و AndroidManifest.xml و build.gradle) تلقائياً دون لمسها يدوياً.', 'تسمح الـ Config Plugins لأي مكتبة خارجية بنقل إعداداتها الأصلية إلى ملف app.json أو app.config.js. يمكن للمطور كتابة Plugin مخصص لإضافة أذونات، أو تعديل إعدادات التجميع، أو حقن أكواد في كود البداية (AppDelegate/MainActivity) مع ضمان بقاء الكود نقياً وخالياً من الأخطاء البشرية.', '// مثال Plugin مخصص لتعديل Info.plist برمجياً:
const { withInfoPlist } = require(''@expo/config-plugins'');

const withCustomSetting = (config) => {
  return withInfoPlist(config, (config) => {
    config.modResults.NSMicrophoneUsageDescription = "نحتاج الميكروفون لتسجيل الرسائل الصوتية";
    return config;
  });
};

module.exports = withCustomSetting;', '["محاولة كتابة إضافات Config Plugins معقدة تعتمد على تعديل نصوص عشوائية عبر Regex بدلاً من استخدام الـ Modifiers الهيكلية الرسمية."]'::jsonb, '["ما الفرق بين الـ Static Modifiers والـ Dangerous Modifiers في نظام إضافات إكسبو؟"]'::jsonb, '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/config-plugins/introduction/"}]'::jsonb from public.question_revisions r where r.question_id = 'rnexpo-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnexpo-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الـ Expo Config Plugins وكيف تسمح بتعديل كود ومكتبات الـ Native بأمان؟' or l.short_answer is distinct from 'هي دوال برمجية بلغة JavaScript/TypeScript تنفذ أثناء npx expo prebuild لتعديل ملفات البناء الأصلية (مثل Info.plist و AndroidManifest.xml و build.gradle) تلقائياً دون لمسها يدوياً.' or l.explanation is distinct from 'تسمح الـ Config Plugins لأي مكتبة خارجية بنقل إعداداتها الأصلية إلى ملف app.json أو app.config.js. يمكن للمطور كتابة Plugin مخصص لإضافة أذونات، أو تعديل إعدادات التجميع، أو حقن أكواد في كود البداية (AppDelegate/MainActivity) مع ضمان بقاء الكود نقياً وخالياً من الأخطاء البشرية.' or l.code_example is distinct from '// مثال Plugin مخصص لتعديل Info.plist برمجياً:
const { withInfoPlist } = require(''@expo/config-plugins'');

const withCustomSetting = (config) => {
  return withInfoPlist(config, (config) => {
    config.modResults.NSMicrophoneUsageDescription = "نحتاج الميكروفون لتسجيل الرسائل الصوتية";
    return config;
  });
};

module.exports = withCustomSetting;' or l.common_mistakes is distinct from '["محاولة كتابة إضافات Config Plugins معقدة تعتمد على تعديل نصوص عشوائية عبر Regex بدلاً من استخدام الـ Modifiers الهيكلية الرسمية."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين الـ Static Modifiers والـ Dangerous Modifiers في نظام إضافات إكسبو؟"]'::jsonb or l.sources is distinct from '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/config-plugins/introduction/"}]'::jsonb)) then raise exception 'Question rnexpo-002 ar content changed; create a new revision before seeding'; end if; end $$;
