insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو نظام EAS Build وكيف يختلف عن البناء المحلي على جهاز المطور؟', 'نظام EAS Build هو خدمة سحابية متكاملة تقوم بتشغيل خوادم macOS ولينكس مخصصة ومجهزة بـ Xcode و Android SDK لإنشاء ملفات APK و AAB و IPA دون استهلاك طاقة ومساحة جهاز المطور.', 'يتطلب بناء تطبيقات iOS محلياً امتلاك جهاز Mac حديث مع تنزيل Xcode بحجم 40 جيجابايت وصيانة شهادات التوقيع. يتيح EAS Build لأي مطور (حتى على أجهزة Windows أو Linux) بناء حزم إنتاجية موقعة ومجهزة للمتاجر بنقرة زر واحدة عبر السحابة، مع إدارة آمنة للشهادات والبيئات المتعددة.', '// ملف eas.json لتكوين ملفات البناء:
{
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal"
    },
    "preview": {
      "distribution": "internal"
    },
    "production": {
      "autoIncrement": true
    }
  }
}', '["الاعتقاد بأن خدمة EAS Build تتطلب نشر كود التطبيق علنياً أو أنها لا تدعم مشاريع الـ Bare اليدوية."]'::jsonb, '["كيف تدعم EAS Build البناء الموازي وتخزين كاش الـ Pods و Gradle لتسريع زمن البناء إلى بضع دقائق؟"]'::jsonb, '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/build/introduction/"}]'::jsonb from public.question_revisions r where r.question_id = 'rnexpo-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnexpo-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو نظام EAS Build وكيف يختلف عن البناء المحلي على جهاز المطور؟' or l.short_answer is distinct from 'نظام EAS Build هو خدمة سحابية متكاملة تقوم بتشغيل خوادم macOS ولينكس مخصصة ومجهزة بـ Xcode و Android SDK لإنشاء ملفات APK و AAB و IPA دون استهلاك طاقة ومساحة جهاز المطور.' or l.explanation is distinct from 'يتطلب بناء تطبيقات iOS محلياً امتلاك جهاز Mac حديث مع تنزيل Xcode بحجم 40 جيجابايت وصيانة شهادات التوقيع. يتيح EAS Build لأي مطور (حتى على أجهزة Windows أو Linux) بناء حزم إنتاجية موقعة ومجهزة للمتاجر بنقرة زر واحدة عبر السحابة، مع إدارة آمنة للشهادات والبيئات المتعددة.' or l.code_example is distinct from '// ملف eas.json لتكوين ملفات البناء:
{
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal"
    },
    "preview": {
      "distribution": "internal"
    },
    "production": {
      "autoIncrement": true
    }
  }
}' or l.common_mistakes is distinct from '["الاعتقاد بأن خدمة EAS Build تتطلب نشر كود التطبيق علنياً أو أنها لا تدعم مشاريع الـ Bare اليدوية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تدعم EAS Build البناء الموازي وتخزين كاش الـ Pods و Gradle لتسريع زمن البناء إلى بضع دقائق؟"]'::jsonb or l.sources is distinct from '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/build/introduction/"}]'::jsonb)) then raise exception 'Question rnexpo-003 ar content changed; create a new revision before seeding'; end if; end $$;
