insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير المتغيرات البيئية (Environment Variables) في Expo بأمان وموثوقية؟', 'باستخدام بادئة EXPO_PUBLIC_ للمتغيرات المسموح بكشفها في جانب العميل، وحفظ المفاتيح السرية في EAS Secrets واستخدامها فقط أثناء عملية البناء السحابي.', 'في Expo الحديث، أي متغير يبدأ بـ EXPO_PUBLIC_ (مثل EXPO_PUBLIC_API_URL) يتم تضمينه تلقائياً في شفرة الـ JavaScript ويكون مرئياً في كود العميل. أما المفاتيح الخاصة والحساسة (مثل مفاتيح توقيع الخادم) فيجب ألا تحمل هذه البادئة، ويتم تمريرها عبر eas secret:create لتستخدمها نصوص البناء في الخادم دون تسريبها لملفات العميل.', '// في ملف .env:
EXPO_PUBLIC_API_URL=https://api.example.com
PRIVATE_DEPLOY_KEY=secret_not_exposed_to_client

// في كود التطبيق:
const apiUrl = process.env.EXPO_PUBLIC_API_URL; // آمن وصحيح', '["تسمية مفاتيح التشفير السرية ورموز الـ API الخاصة بالدفع ببادئة EXPO_PUBLIC_ مما يجعلها قابلة للاستخراج من ملفات الـ JS."]'::jsonb, '["كيف تدير المتغيرات البيئية المختلفة لبيئات التطوير (Dev) والاختبار (Staging) والإنتاج (Prod) في eas.json؟"]'::jsonb, '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/guides/environment-variables/"}]'::jsonb from public.question_revisions r where r.question_id = 'rnexpo-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'rnexpo-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير المتغيرات البيئية (Environment Variables) في Expo بأمان وموثوقية؟' or l.short_answer is distinct from 'باستخدام بادئة EXPO_PUBLIC_ للمتغيرات المسموح بكشفها في جانب العميل، وحفظ المفاتيح السرية في EAS Secrets واستخدامها فقط أثناء عملية البناء السحابي.' or l.explanation is distinct from 'في Expo الحديث، أي متغير يبدأ بـ EXPO_PUBLIC_ (مثل EXPO_PUBLIC_API_URL) يتم تضمينه تلقائياً في شفرة الـ JavaScript ويكون مرئياً في كود العميل. أما المفاتيح الخاصة والحساسة (مثل مفاتيح توقيع الخادم) فيجب ألا تحمل هذه البادئة، ويتم تمريرها عبر eas secret:create لتستخدمها نصوص البناء في الخادم دون تسريبها لملفات العميل.' or l.code_example is distinct from '// في ملف .env:
EXPO_PUBLIC_API_URL=https://api.example.com
PRIVATE_DEPLOY_KEY=secret_not_exposed_to_client

// في كود التطبيق:
const apiUrl = process.env.EXPO_PUBLIC_API_URL; // آمن وصحيح' or l.common_mistakes is distinct from '["تسمية مفاتيح التشفير السرية ورموز الـ API الخاصة بالدفع ببادئة EXPO_PUBLIC_ مما يجعلها قابلة للاستخراج من ملفات الـ JS."]'::jsonb or l.follow_up_questions is distinct from '["كيف تدير المتغيرات البيئية المختلفة لبيئات التطوير (Dev) والاختبار (Staging) والإنتاج (Prod) في eas.json؟"]'::jsonb or l.sources is distinct from '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/guides/environment-variables/"}]'::jsonb)) then raise exception 'Question rnexpo-006 ar content changed; create a new revision before seeding'; end if; end $$;
