insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير شاشات البداية والـ Splash Screen الاحترافية باستخدام expo-splash-screen؟', 'باستدعاء SplashScreen.preventAutoHideAsync() لمنع إخفاء الشاشة الافتتاحية تلقائياً، والانتظار حتى اكتمال تحميل الموارد والبيانات الأساسية ثم إخفائها بـ hideAsync() مع حركة تلاشٍ ناعمة.', 'تعتبر الشاشة الافتتاحية الانطباع الأول للمستخدم. لضمان عدم ظهور شاشات فارغة أو وميض أبيض أثناء تحميل الخطوط أو استرجاع الجلسة المحفوظة، نمنع إخفاء الـ Splash Screen فوراً، ونقوم بتهيئة التطبيق بالخلفية، ثم نطلق إخفاءها بحركة انسيابية عند جاهزية الشاشة الأولى.', 'import * as SplashScreen from ''expo-splash-screen'';
import { useEffect, useState } from ''react'';

SplashScreen.preventAutoHideAsync();

export default function App() {
  const [appIsReady, setAppIsReady] = useState(false);

  useEffect(() => {
    async function prepare() {
      await loadAppResourcesAsync();
      setAppIsReady(true);
      await SplashScreen.hideAsync();
    }
    prepare();
  }, []);

  if (!appIsReady) return null;
  return <MainNavigator />;
}', '["نسيان استدعاء SplashScreen.hideAsync() عند حدوث خطأ في استدعاء الموارد، مما يترك التطبيق معلقاً على شاشة الـ Splash للأبد."]'::jsonb, '["كيف يتم تكوين ألوان وأبعاد صورة الـ Splash Screen بدقة في ملف app.json لتتوافق مع مختلف مقاسات الشاشات؟"]'::jsonb, '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/versions/latest/sdk/splash-screen/"}]'::jsonb from public.question_revisions r where r.question_id = 'rnexpo-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
