export default Sentry.wrap(App);' or l.common_mistakes is distinct from '["عدم رفع ملفات Source Maps و dSYM مما يجعل تتبع الأخطاء في بيئة الإنتاج مستحيلاً بسبب الكود المشفر."]'::jsonb or l.follow_up_questions is distinct from '["كيف تفيد ميزة Breadcrumbs في Sentry في معرفة آخر الشاشات والنقرات التي قام بها المستخدم قبل وقوع الانهيار بثوانٍ؟"]'::jsonb or l.sources is distinct from '[{"title":"Expo Ecosystem & EAS Documentation","url":"https://docs.expo.dev/guides/using-sentry/"}]'::jsonb)) then raise exception 'Question rnexpo-010 ar content changed; create a new revision before seeding'; end if; end $$;
