async function handleDeleteAccount() {
  Alert.alert(''تأكيد الحذف'', ''سيتم حذف حسابك وكافة بياناتك نهائياً ولن تتمكن من استعادتها.'', [
    { text: ''إلغاء'', style: ''cancel'' },
    { text: ''حذف نهائي'', style: ''destructive'', onPress: executeAccountDeletion }
  ]);
}', '["استخدام بوابات دفع كـ Stripe أو PayPal لشراء ميزات رقمية داخل التطبيق بدلاً من نظام Apple In-App Purchases الإلزامي."]'::jsonb, '["ما هي متطلبات إشعار App Tracking Transparency (ATT) عند استخدام أي مكتبات إعلانية أو تتبعية؟"]'::jsonb, '[{"title":"Release, App Stores & CI/CD Documentation","url":"https://reactnative.dev/docs/publishing-to-app-store"}]'::jsonb from public.question_revisions r where r.question_id = 'rndeploy-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
