insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الفحوصات الأمنية وقواعد حماية الكود المصدري ضد الهندسة العكسية (Reverse Engineering)؟', 'بتفعيل Hermes لتشفير الكود إلى Bytecode، واستخدام ProGuard/R8 لتشويش كود أندرويد الأصلي، وتفعيل شهادات التثبيت الآمن (SSL Pinning) لمنع اعتراض هجمات Man-In-The-Middle.', 'في تطبيقات الهاتف، يمكن لأي شخص استخراج ملف الـ APK أو IPA وقراءة أكواد الـ JavaScript إذا كانت نصوصاً صريحة. استخدام Hermes يحول الكود إلى ملف Bytecode ثنائي يصعب تفكيكه. كما يحمي SSL Pinning حركة البيانات الشبكية من الاعتراض عبر أدوات مثل Charles أو Burp Suite عبر التحقق الصارم من شهادة الخادم.', '// التحقق من سلامة بيئة الهاتف (Jailbreak / Root Detection):
import * as Device from ''expo-device'';

async function verifyDeviceSecurity() {
  const isRooted = await Device.isRootedExperimentalAsync();
  if (isRooted) {
    // إيقاف تشغيل المعاملات الحساسة
    throw new Error("لا يمكن تشغيل التطبيق على أجهزة مكسورة الحماية");
  }
}', '["تضمين مفاتيح API الخاصة بالخادم أو الـ Private Keys داخل كود التطبيق ظناً أنه كود محمي من القراءة."]'::jsonb, '["كيف تمنع لقطات الشاشة وتسجيل الفيديو في الشاشات الحساسة (مثل شاشات البنوك) باستخدام FlagSecure؟"]'::jsonb, '[{"title":"Release, App Stores & CI/CD Documentation","url":"https://reactnative.dev/docs/security"}]'::jsonb from public.question_revisions r where r.question_id = 'rndeploy-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
