insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الأركان الأربعة للبرمجة كائنية التوجه (OOP) وما الفرق بين التغليف (Encapsulation) والتجريد (Abstraction)؟', 'الأركان الأربعة هي: التغليف، التجريد، الوراثة، وتعدد الأشكال. التغليف يركز على إخفاء الحالة الداخلية وحمايتها، بينما التجريد يركز على إخفاء تفاصيل التنفيذ المعقدة وإبراز الواجهة الضرورية فقط.', 'التغليف (Encapsulation) يدمج البيانات والعمليات التي تعمل عليها في وحدة واحدة (Class) ويقيد الوصول المباشر إلى المتغيرات إلا عبر Getters/Setters أو دوال محددة لضمان تكامل الحالة. بينما التجريد (Abstraction) يُعنى بتبسيط الرؤية البرمجية للمستخدم (كالضغط على زر تشغيل السيارة دون الحاجة لفهم دورة الاحتراق الداخلي).', 'class BankAccount {
  private balance: number = 0;

  public deposit(amount: number): void {
    if (amount <= 0) throw new Error(''Invalid amount'');
    this.balance += amount;
  }

  public getBalance(): number {
    return this.balance;
  }
}', '["الخلط بين التغليف ومجرد كتابة دوال Getters و Setters لكل حقل دون أي منطق تحقق وحماية.","اعتبار التجريد والتغليف اسماً لمعنى واحد، متجاهلين أن أحدهما لإخفاء البيانات والآخر لإخفاء التعقيد."]'::jsonb, '["كيف يؤدي غياب التغليف إلى ظهور نموذج الدومين الفقير (Anemic Domain Model)؟"]'::jsonb, '[{"title":"Refactoring Guru — OOP Basics","url":"https://refactoring.guru/design-patterns/oop"}]'::jsonb from public.question_revisions r where r.question_id = 'foop-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'foop-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الأركان الأربعة للبرمجة كائنية التوجه (OOP) وما الفرق بين التغليف (Encapsulation) والتجريد (Abstraction)؟' or l.short_answer is distinct from 'الأركان الأربعة هي: التغليف، التجريد، الوراثة، وتعدد الأشكال. التغليف يركز على إخفاء الحالة الداخلية وحمايتها، بينما التجريد يركز على إخفاء تفاصيل التنفيذ المعقدة وإبراز الواجهة الضرورية فقط.' or l.explanation is distinct from 'التغليف (Encapsulation) يدمج البيانات والعمليات التي تعمل عليها في وحدة واحدة (Class) ويقيد الوصول المباشر إلى المتغيرات إلا عبر Getters/Setters أو دوال محددة لضمان تكامل الحالة. بينما التجريد (Abstraction) يُعنى بتبسيط الرؤية البرمجية للمستخدم (كالضغط على زر تشغيل السيارة دون الحاجة لفهم دورة الاحتراق الداخلي).' or l.code_example is distinct from 'class BankAccount {
  private balance: number = 0;

  public deposit(amount: number): void {
    if (amount <= 0) throw new Error(''Invalid amount'');
    this.balance += amount;
  }

  public getBalance(): number {
    return this.balance;
  }
}' or l.common_mistakes is distinct from '["الخلط بين التغليف ومجرد كتابة دوال Getters و Setters لكل حقل دون أي منطق تحقق وحماية.","اعتبار التجريد والتغليف اسماً لمعنى واحد، متجاهلين أن أحدهما لإخفاء البيانات والآخر لإخفاء التعقيد."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤدي غياب التغليف إلى ظهور نموذج الدومين الفقير (Anemic Domain Model)؟"]'::jsonb or l.sources is distinct from '[{"title":"Refactoring Guru — OOP Basics","url":"https://refactoring.guru/design-patterns/oop"}]'::jsonb)) then raise exception 'Question foop-001 ar content changed; create a new revision before seeding'; end if; end $$;
