insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا ينصح مبدأ ''Composition over Inheritance'' بتفضيل التركيب على الوراثة الكلاسيكية؟', 'لأن الوراثة تنشئ ارتباطاً وثيقاً ثابتاً وقت الترجمة (Compile-time Coupling) وتؤدي لمشكلة الفئة الأساسية الهشة، بينما يتيح التركيب تبديل السلوك ديناميكياً وقت التشغيل وبمرونة عالية.', 'تعتبر الوراثة علاقة ''is-a'' تفضح تفاصيل الفئة الأب للابن (White-box reuse)، وأي تعديل في الأب قد يكسر الأبناء دون قصد (Fragile Base Class Problem). بينما يمثل التركيب علاقة ''has-a'' (Black-box reuse) حيث يمتلك الكائن مراجع لكائنات أخرى تنفذ واجهات محددة، مما يسهل الاختبار واستبدال المكونات.', '// بدلاً من الوراثة الصلبة: class FlyingSwimmingDuck extends Duck
class Duck {
  constructor(private flyBehavior: FlyBehavior, private swimBehavior: SwimBehavior) {}
  performFly() { this.flyBehavior.fly(); }
}', '["استخدام الوراثة لمجرد إعادة استخدام بضعة أسطر من الكود دون وجود علاقة منطقية حقيقية بين النوعين."]'::jsonb, '["متى تكون الوراثة خياراً ممتازاً ومبرراً هندسياً؟"]'::jsonb, '[{"title":"Composition over inheritance - Wikipedia","url":"https://en.wikipedia.org/wiki/Composition_over_inheritance"}]'::jsonb from public.question_revisions r where r.question_id = 'foop-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
