insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو تعدد الأشكال (Polymorphism) وما الفرق بين الإرسال الثابت (Static Dispatch) والإرسال الديناميكي (Dynamic Dispatch)؟', 'تعدد الأشكال هو قدرة الكائنات المختلفة على الاستجابة لنفس الرسالة بطرق متباينة. الإرسال الثابت يُحسم وقت الترجمة (مثل Method Overloading)، بينما الديناميكي يُحسم وقت التشغيل عبر جداول الدوال الافتراضية (vtable).', 'في اللغات ذات الكتابة الثابتة (مثل C++ و C# و Java)، يتم تنفيذ Dynamic Dispatch عن طريق Virtual Method Table (vtable). يحتوي كل كائن على مؤشر للـ vtable الخاصة بفئته، وعند استدعاء دالة افتراضية يتم قراءة عنوان الدالة في وقت التشغيل، مما يضيف كلفة معالجة طفيفة جداً لكنه يمنح مرونة معمارية هائلة.', 'interface Shape {
  draw(): void;
}
class Circle implements Shape { draw() { console.log(''Circle''); } }
class Square implements Shape { draw() { console.log(''Square''); } }

function render(shapes: Shape[]) {
  for (const s of shapes) s.draw(); // Dynamic Dispatch وقت التشغيل
}', '["الاعتقاد بأن Overloading و Overriding يعملان بنفس الطريقة في الذاكرة ووقت التنفيذ."]'::jsonb, '["كيف تؤثر دوال Inline والمترجمات الذكية على تقليل تكلفة الـ vtable lookup؟"]'::jsonb, '[{"title":"Virtual method table - Wikipedia","url":"https://en.wikipedia.org/wiki/Virtual_method_table"}]'::jsonb from public.question_revisions r where r.question_id = 'foop-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'foop-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو تعدد الأشكال (Polymorphism) وما الفرق بين الإرسال الثابت (Static Dispatch) والإرسال الديناميكي (Dynamic Dispatch)؟' or l.short_answer is distinct from 'تعدد الأشكال هو قدرة الكائنات المختلفة على الاستجابة لنفس الرسالة بطرق متباينة. الإرسال الثابت يُحسم وقت الترجمة (مثل Method Overloading)، بينما الديناميكي يُحسم وقت التشغيل عبر جداول الدوال الافتراضية (vtable).' or l.explanation is distinct from 'في اللغات ذات الكتابة الثابتة (مثل C++ و C# و Java)، يتم تنفيذ Dynamic Dispatch عن طريق Virtual Method Table (vtable). يحتوي كل كائن على مؤشر للـ vtable الخاصة بفئته، وعند استدعاء دالة افتراضية يتم قراءة عنوان الدالة في وقت التشغيل، مما يضيف كلفة معالجة طفيفة جداً لكنه يمنح مرونة معمارية هائلة.' or l.code_example is distinct from 'interface Shape {
  draw(): void;
}
class Circle implements Shape { draw() { console.log(''Circle''); } }
class Square implements Shape { draw() { console.log(''Square''); } }

function render(shapes: Shape[]) {
  for (const s of shapes) s.draw(); // Dynamic Dispatch وقت التشغيل
}' or l.common_mistakes is distinct from '["الاعتقاد بأن Overloading و Overriding يعملان بنفس الطريقة في الذاكرة ووقت التنفيذ."]'::jsonb or l.follow_up_questions is distinct from '["كيف تؤثر دوال Inline والمترجمات الذكية على تقليل تكلفة الـ vtable lookup؟"]'::jsonb or l.sources is distinct from '[{"title":"Virtual method table - Wikipedia","url":"https://en.wikipedia.org/wiki/Virtual_method_table"}]'::jsonb)) then raise exception 'Question foop-003 ar content changed; create a new revision before seeding'; end if; end $$;
