insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق المعماري الدقيق بين الفئة المجردة (Abstract Class) والواجهة (Interface)؟', 'الفئة المجردة تمثل هوية جزئية مشتركة (''is-a'') ويمكنها الاحتفاظ بحالة (State) وتنفيذ افتراضي للدوال، بينما الواجهة تمثل عقداً سلوكياً (''can-do'') يحدد ماذا تفعل الكائنات دون احتفاظ بحالة الفئة.', 'تُستخدم Abstract Classes عندما تشترك عدة فئات في كود تنفيذي مشترك وحالة محددة (Protected fields)، وتكون هناك علاقة وراثية عميقة. أما الواجهات (Interfaces) فتُستخدم لفصل واجهة الاستخدام تماماً عن التنفيذ وتحقيق فك الارتباط الكامل (Decoupling) وتمكين الاختبارات وعزل التبعيات.', 'abstract class Animal {
  constructor(public name: string) {} // تحتفظ بحالة
  abstract makeSound(): void;
  sleep() { console.log(''Zzz...''); } // تنفيذ مشترك
}

interface Flyable {
  fly(): void; // عقد سلوكي بحت
}', '["استخدام الفئات المجردة فقط كعقود فارغة دون أي كود مشترك بدلاً من استخدام الواجهات الأبسط والأخف."]'::jsonb, '["لماذا أضافت لغات حديثة مثل Java 8+ و C# 8+ ميزة Default Interface Methods وما هي محاذيرها المعمارية؟"]'::jsonb, '[{"title":"Interfaces vs Abstract Classes - Microsoft Docs","url":"https://learn.microsoft.com/en-us/dotnet/csharp/fundamentals/tutorials/oop"}]'::jsonb from public.question_revisions r where r.question_id = 'foop-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'foop-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق المعماري الدقيق بين الفئة المجردة (Abstract Class) والواجهة (Interface)؟' or l.short_answer is distinct from 'الفئة المجردة تمثل هوية جزئية مشتركة (''is-a'') ويمكنها الاحتفاظ بحالة (State) وتنفيذ افتراضي للدوال، بينما الواجهة تمثل عقداً سلوكياً (''can-do'') يحدد ماذا تفعل الكائنات دون احتفاظ بحالة الفئة.' or l.explanation is distinct from 'تُستخدم Abstract Classes عندما تشترك عدة فئات في كود تنفيذي مشترك وحالة محددة (Protected fields)، وتكون هناك علاقة وراثية عميقة. أما الواجهات (Interfaces) فتُستخدم لفصل واجهة الاستخدام تماماً عن التنفيذ وتحقيق فك الارتباط الكامل (Decoupling) وتمكين الاختبارات وعزل التبعيات.' or l.code_example is distinct from 'abstract class Animal {
  constructor(public name: string) {} // تحتفظ بحالة
  abstract makeSound(): void;
  sleep() { console.log(''Zzz...''); } // تنفيذ مشترك
}

interface Flyable {
  fly(): void; // عقد سلوكي بحت
}' or l.common_mistakes is distinct from '["استخدام الفئات المجردة فقط كعقود فارغة دون أي كود مشترك بدلاً من استخدام الواجهات الأبسط والأخف."]'::jsonb or l.follow_up_questions is distinct from '["لماذا أضافت لغات حديثة مثل Java 8+ و C# 8+ ميزة Default Interface Methods وما هي محاذيرها المعمارية؟"]'::jsonb or l.sources is distinct from '[{"title":"Interfaces vs Abstract Classes - Microsoft Docs","url":"https://learn.microsoft.com/en-us/dotnet/csharp/fundamentals/tutorials/oop"}]'::jsonb)) then raise exception 'Question foop-005 ar content changed; create a new revision before seeding'; end if; end $$;
