insert into public.interview_questions (id, slug, track_id, difficulty) values ('foop-007', 'oop-coupling-and-cohesion-metrics', 'fundamentals', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('foop-007', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين الاقتران (Coupling) والتماسك (Cohesion) ولماذا نسعى دائماً إلى ''High Cohesion, Low Coupling''؟', 'التماسك يقيس مدى ترابط وتركيز المسؤوليات داخل الوحدة الواحدة، بينما الاقتران يقيس درجة اعتماد الوحدات المختلفة على بعضها البعض.', 'التماسك العالي (High Cohesion) يعني أن الفئة تقوم بمهمة واحدة محددة وتخدم هدفاً موحداً، مما يجعلها سهلة الفهم والصيانة وإعادة الاستخدام. الاقتران المنخفض (Low Coupling) يعني أن تغيير فئة ما لن يجبرك على تعديل عشرات الفئات الأخرى. العمارة الممتازة تجمع المهام المتشابهة معاً وتفصل التبعيات عبر واجهات مجردة مستقرة.', '// فئة منخفضة التماسك وعالية الاقتران (God Object):
class OrderManager {
  processOrder() { /*...*/ }
  sendEmail() { /*...*/ }
  renderHtmlInvoice() { /*...*/ }
  executeSql() { /*...*/ }
}', '["الاعتقاد بأن الاقتران المنخفض يعني عدم وجود أي تواصل بين الفئات نهائياً؛ الهدف هو تقليل الاعتماد على التفاصيل والتنفيذ الملموس."]'::jsonb, '["ما هي مقاييس Afferent Coupling و Efferent Coupling وكيف تحسب عدم استقرار الحزمة (Instability Metric)؟"]'::jsonb, '[{"title":"Coupling and Cohesion - Martin Fowler","url":"https://martinfowler.com/articles/refactoring-2nd-ed.html"}]'::jsonb from public.question_revisions r where r.question_id = 'foop-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'foop-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين الاقتران (Coupling) والتماسك (Cohesion) ولماذا نسعى دائماً إلى ''High Cohesion, Low Coupling''؟' or l.short_answer is distinct from 'التماسك يقيس مدى ترابط وتركيز المسؤوليات داخل الوحدة الواحدة، بينما الاقتران يقيس درجة اعتماد الوحدات المختلفة على بعضها البعض.' or l.explanation is distinct from 'التماسك العالي (High Cohesion) يعني أن الفئة تقوم بمهمة واحدة محددة وتخدم هدفاً موحداً، مما يجعلها سهلة الفهم والصيانة وإعادة الاستخدام. الاقتران المنخفض (Low Coupling) يعني أن تغيير فئة ما لن يجبرك على تعديل عشرات الفئات الأخرى. العمارة الممتازة تجمع المهام المتشابهة معاً وتفصل التبعيات عبر واجهات مجردة مستقرة.' or l.code_example is distinct from '// فئة منخفضة التماسك وعالية الاقتران (God Object):
