insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين نموذج الدومين الفقير (Anemic Domain Model) ونموذج الدومين الثري (Rich Domain Model)؟', 'النموذج الفقير يفصل البيانات في كائنات بلا سلوك (مجموعات Getters/Setters) ويضع المنطق في خدمات خارجية، بينما يدمج النموذج الثري البيانات والمنطق وقواعد العمل معاً داخل الكيان.', 'وصف مارتن فاولر النموذج الفقير بأنه مضاد نمط (Anti-pattern) في البرمجة كائنية التوجه؛ لأنه يعيدنا للبرمجة الإجرائية القديمة (Procedural)، حيث تكون الفئات مجرد هياكل بيانات صامتة ويتبعثر منطق التحقق وقواعد العمل في طبقات الخدمات (Services). في المقابل، يضمن النموذج الثري عدم وصول الكيان إلى حالة غير صالحة أبداً (Always-valid state) عبر تغليف العمليات الحقيقية داخله.', '// نموذج ثري: الكيان يحمي شروطه:
class Order {
  private items: OrderItem[] = [];
  private status: OrderStatus = ''Draft'';

  public cancel(): void {
    if (this.status === ''Shipped'') throw new Error(''Cannot cancel shipped order'');
    this.status = ''Cancelled'';
  }
}', '["وضع منطق البنية التحتية مثل استعلامات قاعدة البيانات أو إرسال الإيميلات داخل كيان الدومين الثري؛ الكيان يحتوي على منطق العمل فقط."]'::jsonb, '["متى يكون استخدام DTOs البسيطة فقيراً ومقبولاً في طبقات النقل والتواصل؟"]'::jsonb, '[{"title":"Martin Fowler — AnemicDomainModel","url":"https://martinfowler.com/bliki/AnemicDomainModel.html"}]'::jsonb from public.question_revisions r where r.question_id = 'foop-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'foop-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين نموذج الدومين الفقير (Anemic Domain Model) ونموذج الدومين الثري (Rich Domain Model)؟' or l.short_answer is distinct from 'النموذج الفقير يفصل البيانات في كائنات بلا سلوك (مجموعات Getters/Setters) ويضع المنطق في خدمات خارجية، بينما يدمج النموذج الثري البيانات والمنطق وقواعد العمل معاً داخل الكيان.' or l.explanation is distinct from 'وصف مارتن فاولر النموذج الفقير بأنه مضاد نمط (Anti-pattern) في البرمجة كائنية التوجه؛ لأنه يعيدنا للبرمجة الإجرائية القديمة (Procedural)، حيث تكون الفئات مجرد هياكل بيانات صامتة ويتبعثر منطق التحقق وقواعد العمل في طبقات الخدمات (Services). في المقابل، يضمن النموذج الثري عدم وصول الكيان إلى حالة غير صالحة أبداً (Always-valid state) عبر تغليف العمليات الحقيقية داخله.' or l.code_example is distinct from '// نموذج ثري: الكيان يحمي شروطه:
class Order {
  private items: OrderItem[] = [];
  private status: OrderStatus = ''Draft'';

  public cancel(): void {
    if (this.status === ''Shipped'') throw new Error(''Cannot cancel shipped order'');
    this.status = ''Cancelled'';
  }
}' or l.common_mistakes is distinct from '["وضع منطق البنية التحتية مثل استعلامات قاعدة البيانات أو إرسال الإيميلات داخل كيان الدومين الثري؛ الكيان يحتوي على منطق العمل فقط."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون استخدام DTOs البسيطة فقيراً ومقبولاً في طبقات النقل والتواصل؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — AnemicDomainModel","url":"https://martinfowler.com/bliki/AnemicDomainModel.html"}]'::jsonb)) then raise exception 'Question foop-009 ar content changed; create a new revision before seeding'; end if; end $$;
