insert into public.interview_questions (id, slug, track_id, difficulty) values ('foop-010', 'oop-method-overriding-covariance-contravariance', 'fundamentals', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('foop-010', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مفاهيم الـ Covariance والـ Contravariance في بارامترات وقيم إرجاع الدوال عند عمل Override؟', 'عند استبدال دالة في الفئة الابنة: يجب أن تكون قيمة الإرجاع متوافقة أو أكثر تخصيصاً (Covariant)، بينما يجب أن تكون معاملات الإدخال متوافقة أو أكثر عمومية (Contravariant).', 'وفقاً لمبدأ الاستبدال، إذا كان الكود يتوقع دالة ترجع Animal، فإن الفئة المشتقة يمكنها إرجاع Dog (تخصيص للناتج - Covariance) لأن الكلب هو حيوان ولن ينكسر الكود الطالب. أما بالنسبة لمعاملات الدالة، فإذا كانت الفئة الأصلية تقبل Dog، فلا يجوز للابن تضييق المعامل ليشترط GermanShepherd فقط، بل يجب أن يقبل Dog أو أكثر عمومية Animal (Contravariance) لضمان عدم حدوث أخطاء استدعاء غير متوقعة.', 'class AnimalShelter {
  getResident(): Animal { return new Animal(); }
}
class DogShelter extends AnimalShelter {
  @override
  getResident(): Dog { return new Dog(); } // Covariant return type: صحيح وآمن
