insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق مبدأ الانفتاح والإغلاق (Open/Closed Principle) دون الوقوع في فخ التعقيد المفرط؟', 'يكون الكود مفتوحاً للتوسيع (إضافة ميزات جديدة) ومغلقاً للتعديل (دون الحاجة لتغيير الكود المجرب مسبقاً) عبر الاعتماد على الواجهات والاستراتيجيات المجردة.', 'الهدف هو إضافة ميزة جديدة بمجرد كتابة فئة جديدة تنفذ واجهة محددة دون فتح وتعديل ملفات الكود الحالية بسلاسل switch-case طويلة. ولكن يجب تطبيقه بحذر فقط عند محاور التغيير المؤكدة (Axes of Change)، وليس على كل سطر تحسباً لمستقبل وهمي (YAGNI).', 'interface PaymentGateway {
  process(amount: number): Promise<void>;
}
class StripeGateway implements PaymentGateway { /*...*/ }
class PayPalGateway implements PaymentGateway { /*...*/ }

class PaymentProcessor {
  constructor(private gateway: PaymentGateway) {}
  execute(amount: number) { return this.gateway.process(amount); }
}', '["تعديل كود مجرب ويعمل في الإنتاج بإضافة شروط if/else جديدة لكل عميل جديد، بدلاً من استخدام نمط الاستراتيجية (Strategy)."]'::jsonb, '["ما العلاقة الوثيقة بين مبدأ OCP واستخدام الـ Plugins والمكتبات الخارجية في النظم الكبيرة؟"]'::jsonb, '[{"title":"Open-closed principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Open%E2%80%93closed_principle"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق مبدأ الانفتاح والإغلاق (Open/Closed Principle) دون الوقوع في فخ التعقيد المفرط؟' or l.short_answer is distinct from 'يكون الكود مفتوحاً للتوسيع (إضافة ميزات جديدة) ومغلقاً للتعديل (دون الحاجة لتغيير الكود المجرب مسبقاً) عبر الاعتماد على الواجهات والاستراتيجيات المجردة.' or l.explanation is distinct from 'الهدف هو إضافة ميزة جديدة بمجرد كتابة فئة جديدة تنفذ واجهة محددة دون فتح وتعديل ملفات الكود الحالية بسلاسل switch-case طويلة. ولكن يجب تطبيقه بحذر فقط عند محاور التغيير المؤكدة (Axes of Change)، وليس على كل سطر تحسباً لمستقبل وهمي (YAGNI).' or l.code_example is distinct from 'interface PaymentGateway {
