insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح مبدأ استبدال لسكوف (LSP) ومفهوم الشروط المسبقة (Preconditions) واللاحقة (Postconditions) ومثال المستطيل والمربع الشهير؟', 'ينص LSP على أن كائنات الفئة المشتقة يجب أن تحل محل كائنات الفئة الأساسية دون تغيير صحة وسلوك البرنامج. ولا يجوز للابن تشديد الشروط المسبقة أو إضعاف الشروط اللاحقة.', 'المثال الكلاسيكي: كلاس Square ترث من Rectangle. إذا قمت بتغيير setWidth() في المربع، فإنك مجبر على تغيير height أيضاً للحفاظ على التساوي. لكن الكود الذي يتعامل مع Rectangle يتوقع أن تغيير العرض لا يؤثر على الارتفاع! عند استبدال المستطيل بمربع ينكسر منطق الحسابات. قواعد لسكوف الصارمة: (1) الشروط المسبقة لا يمكن تقويتها في الابن. (2) الشروط اللاحقة لا يمكن إضعافها. (3) ثوابت الفئة (Invariants) يجب الحفاظ عليها بالكامل. (4) لا يجوز رمي استثناءات غير متوقعة في الفئة الأب.', 'class Rectangle {
  constructor(protected w: number, protected h: number) {}
  setWidth(val: number) { this.w = val; }
  setHeight(val: number) { this.h = val; }
  getArea(): number { return this.w * this.h; }
}
// انتهاك LSP: المربع يغير سلوك الارتفاع خفية عند تغيير العرض!', '["وراثة فئة ورمي NotImplementedException في بعض دوالها، وهو انتهاك مباشر لمبدأ لسكوف يكسر توقعات المستدعي."]'::jsonb, '["كيف تكتشف انتهاك LSP إذا رأيت شفرة تستخدم كتل if (obj instanceof SubClass) للتعامل مع كائنات مشتقة؟"]'::jsonb, '[{"title":"Liskov substitution principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Liskov_substitution_principle"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'اشرح مبدأ استبدال لسكوف (LSP) ومفهوم الشروط المسبقة (Preconditions) واللاحقة (Postconditions) ومثال المستطيل والمربع الشهير؟' or l.short_answer is distinct from 'ينص LSP على أن كائنات الفئة المشتقة يجب أن تحل محل كائنات الفئة الأساسية دون تغيير صحة وسلوك البرنامج. ولا يجوز للابن تشديد الشروط المسبقة أو إضعاف الشروط اللاحقة.' or l.explanation is distinct from 'المثال الكلاسيكي: كلاس Square ترث من Rectangle. إذا قمت بتغيير setWidth() في المربع، فإنك مجبر على تغيير height أيضاً للحفاظ على التساوي. لكن الكود الذي يتعامل مع Rectangle يتوقع أن تغيير العرض لا يؤثر على الارتفاع! عند استبدال المستطيل بمربع ينكسر منطق الحسابات. قواعد لسكوف الصارمة: (1) الشروط المسبقة لا يمكن تقويتها في الابن. (2) الشروط اللاحقة لا يمكن إضعافها. (3) ثوابت الفئة (Invariants) يجب الحفاظ عليها بالكامل. (4) لا يجوز رمي استثناءات غير متوقعة في الفئة الأب.' or l.code_example is distinct from 'class Rectangle {
  constructor(protected w: number, protected h: number) {}
  setWidth(val: number) { this.w = val; }
  setHeight(val: number) { this.h = val; }
  getArea(): number { return this.w * this.h; }
}
// انتهاك LSP: المربع يغير سلوك الارتفاع خفية عند تغيير العرض!' or l.common_mistakes is distinct from '["وراثة فئة ورمي NotImplementedException في بعض دوالها، وهو انتهاك مباشر لمبدأ لسكوف يكسر توقعات المستدعي."]'::jsonb or l.follow_up_questions is distinct from '["كيف تكتشف انتهاك LSP إذا رأيت شفرة تستخدم كتل if (obj instanceof SubClass) للتعامل مع كائنات مشتقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Liskov substitution principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Liskov_substitution_principle"}]'::jsonb)) then raise exception 'Question fsld-003 ar content changed; create a new revision before seeding'; end if; end $$;
