insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يحذر مبدأ فصل الواجهات (Interface Segregation Principle) من الواجهات الضخمة (Fat Interfaces)؟', 'لأنه لا ينبغي إجبار أي عميل برمجي على الاعتماد على دوال أو واجهات لا يستخدمها، مما يمنع الاقتران غير الضروري وإعادة الترجمة غير المبررة.', 'عندما تحتوي الواجهة على عشرات الدوال المتنوعة (God Interface)، فإن أي فئة تطبقها ستضطر لكتابة دوال فارغة أو رمي أخطاء للوظائف التي لا تلزمها، وأي تعديل على دالة واحدة في الواجهة يجبر جميع الفئات المطبقة لها على إعادة الترجمة والاختبار. الحل هو تقسيم الواجهة الضخمة إلى واجهات أصغر وأدق تركز على أدوار محددة (Role Interfaces).', '// واجهات مفصولة بدقة:
interface Printer {
  print(doc: Document): void;
}
interface Scanner {
  scan(): Document;
}
class BasicPrinter implements Printer {
  print(doc: Document) { /*...*/ }
}', '["دمج كل عمليات CRUD وعمليات التقارير وعمليات التصدير في واجهة مستودع موحدة وعريضة لكل الكيانات."]'::jsonb, '["كيف يدعم مبدأ ISP تطبيق بنية المنافذ والمحولات (Ports and Adapters) في العمارة السداسية؟"]'::jsonb, '[{"title":"Interface segregation principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Interface_segregation_principle"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يحذر مبدأ فصل الواجهات (Interface Segregation Principle) من الواجهات الضخمة (Fat Interfaces)؟' or l.short_answer is distinct from 'لأنه لا ينبغي إجبار أي عميل برمجي على الاعتماد على دوال أو واجهات لا يستخدمها، مما يمنع الاقتران غير الضروري وإعادة الترجمة غير المبررة.' or l.explanation is distinct from 'عندما تحتوي الواجهة على عشرات الدوال المتنوعة (God Interface)، فإن أي فئة تطبقها ستضطر لكتابة دوال فارغة أو رمي أخطاء للوظائف التي لا تلزمها، وأي تعديل على دالة واحدة في الواجهة يجبر جميع الفئات المطبقة لها على إعادة الترجمة والاختبار. الحل هو تقسيم الواجهة الضخمة إلى واجهات أصغر وأدق تركز على أدوار محددة (Role Interfaces).' or l.code_example is distinct from '// واجهات مفصولة بدقة:
interface Printer {
  print(doc: Document): void;
}
interface Scanner {
  scan(): Document;
}
class BasicPrinter implements Printer {
  print(doc: Document) { /*...*/ }
}' or l.common_mistakes is distinct from '["دمج كل عمليات CRUD وعمليات التقارير وعمليات التصدير في واجهة مستودع موحدة وعريضة لكل الكيانات."]'::jsonb or l.follow_up_questions is distinct from '["كيف يدعم مبدأ ISP تطبيق بنية المنافذ والمحولات (Ports and Adapters) في العمارة السداسية؟"]'::jsonb or l.sources is distinct from '[{"title":"Interface segregation principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Interface_segregation_principle"}]'::jsonb)) then raise exception 'Question fsld-004 ar content changed; create a new revision before seeding'; end if; end $$;
