insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو جوهر مبدأ عكس التبعية (Dependency Inversion Principle) وكيف يختلف عن حقن التبعية (DI)؟', 'DIP هو مبدأ معماري يفرض أن الوحدات عالية المستوى والتفاصيل منخفضة المستوى يجب أن تعتمد كلاهما على التجريدات (Abstractions)، بينما DI هو نمط برمجي لتمرير التبعيات من الخارج.', 'في المعماريات التقليدية، تعتمد طبقة الأعمال (High-level Business Logic) مباشرة على طبقة البيانات (SQL Database Client). مبدأ DIP يعكس هذا الاتجاه: طبقة الأعمال تحدد واجهة تجريدية (Port/Contract) تلبي احتياجاتها، وطبقة البيانات تنفذ هذه الواجهة (Adapter). بذلك تصبح قواعد العمل مستقلة تماماً عن تفاصيل قواعد البيانات أو مزودي الخدمات السحابية.', '// طبقة الأعمال تمتلك العقد:
interface NotificationSender {
  send(message: string): Promise<void>;
}
// طبقة الأعمال تعتمد على الواجهة المجردة:
class OrderService {
  constructor(private notifier: NotificationSender) {}
}', '["اعتبار أن استخدام مكتبات مثل Inversify أو Dagger هو تطبيق تلقائي لـ DIP، في حين أن جوهر المبدأ هو ملكية الواجهة والاتجاه المعماري للتبعية."]'::jsonb, '["لماذا يجب أن تُعرّف الواجهة المجردة في نفس الحزمة مع المستدعي (Client-owned interface) وليس مع المنفذ؟"]'::jsonb, '[{"title":"Dependency inversion principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Dependency_inversion_principle"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو جوهر مبدأ عكس التبعية (Dependency Inversion Principle) وكيف يختلف عن حقن التبعية (DI)؟' or l.short_answer is distinct from 'DIP هو مبدأ معماري يفرض أن الوحدات عالية المستوى والتفاصيل منخفضة المستوى يجب أن تعتمد كلاهما على التجريدات (Abstractions)، بينما DI هو نمط برمجي لتمرير التبعيات من الخارج.' or l.explanation is distinct from 'في المعماريات التقليدية، تعتمد طبقة الأعمال (High-level Business Logic) مباشرة على طبقة البيانات (SQL Database Client). مبدأ DIP يعكس هذا الاتجاه: طبقة الأعمال تحدد واجهة تجريدية (Port/Contract) تلبي احتياجاتها، وطبقة البيانات تنفذ هذه الواجهة (Adapter). بذلك تصبح قواعد العمل مستقلة تماماً عن تفاصيل قواعد البيانات أو مزودي الخدمات السحابية.' or l.code_example is distinct from '// طبقة الأعمال تمتلك العقد:
interface NotificationSender {
  send(message: string): Promise<void>;
}
// طبقة الأعمال تعتمد على الواجهة المجردة:
class OrderService {
  constructor(private notifier: NotificationSender) {}
}' or l.common_mistakes is distinct from '["اعتبار أن استخدام مكتبات مثل Inversify أو Dagger هو تطبيق تلقائي لـ DIP، في حين أن جوهر المبدأ هو ملكية الواجهة والاتجاه المعماري للتبعية."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يجب أن تُعرّف الواجهة المجردة في نفس الحزمة مع المستدعي (Client-owned interface) وليس مع المنفذ؟"]'::jsonb or l.sources is distinct from '[{"title":"Dependency inversion principle - Wikipedia","url":"https://en.wikipedia.org/wiki/Dependency_inversion_principle"}]'::jsonb)) then raise exception 'Question fsld-005 ar content changed; create a new revision before seeding'; end if; end $$;
