insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الفرق بين نمط Service Locator وحاويات حقن التبعيات (IoC Containers) ولماذا يُعتبر الأول مضاد نمط أحياناً؟', 'يعتمد Service Locator على استدعاء مركزي صريح من داخل الفئة لجلب التبعيات مما يخفيها، بينما يقوم DI بتمرير التبعيات علانية عبر الـ Constructor مما يجعل متطلبات الفئة واضحة وصريحة.', 'يخفي Service Locator التبعيات الحقيقية للفئة؛ فعند النظر إلى منشئ الفئة يبدو فارغاً، لكن الكود ينفجر وقت التشغيل إذا لم يتم تسجيل خدمة معينة في السجل المركزي. كما أنه يصعب كتابة اختبارات الوحدة لأنه يتطلب إعداد الحالة العامة للـ Locator. في المقابل، يفرض Constructor Injection عقداً معلناً لا يمكن إنشاء الكائن بدونه.', '// مضاد نمط (Service Locator):
class InvoiceService {
  private db = ServiceLocator.get<Database>(); // تبعية مخفية وغير مرئية من الخارج
}
// حقن التبعية الصريح:
class InvoiceService {
  constructor(private db: Database) {} // واضحة تماماً وسهلة الـ Mock
}', '["استخدام Service Locator داخل خدمات الدومين العميقة، مما يجعل تتبع شجرة التبعيات أمراً شديد التعقيد."]'::jsonb, '["متى يكون استخدام Service Locator مقبولاً أو اضطرارياً في بعض أطر العمل القديمة؟"]'::jsonb, '[{"title":"Martin Fowler — Inversion of Control Containers and the Dependency Injection pattern","url":"https://martinfowler.com/articles/injection.html"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الفرق بين نمط Service Locator وحاويات حقن التبعيات (IoC Containers) ولماذا يُعتبر الأول مضاد نمط أحياناً؟' or l.short_answer is distinct from 'يعتمد Service Locator على استدعاء مركزي صريح من داخل الفئة لجلب التبعيات مما يخفيها، بينما يقوم DI بتمرير التبعيات علانية عبر الـ Constructor مما يجعل متطلبات الفئة واضحة وصريحة.' or l.explanation is distinct from 'يخفي Service Locator التبعيات الحقيقية للفئة؛ فعند النظر إلى منشئ الفئة يبدو فارغاً، لكن الكود ينفجر وقت التشغيل إذا لم يتم تسجيل خدمة معينة في السجل المركزي. كما أنه يصعب كتابة اختبارات الوحدة لأنه يتطلب إعداد الحالة العامة للـ Locator. في المقابل، يفرض Constructor Injection عقداً معلناً لا يمكن إنشاء الكائن بدونه.' or l.code_example is distinct from '// مضاد نمط (Service Locator):
class InvoiceService {
  private db = ServiceLocator.get<Database>(); // تبعية مخفية وغير مرئية من الخارج
}
// حقن التبعية الصريح:
class InvoiceService {
  constructor(private db: Database) {} // واضحة تماماً وسهلة الـ Mock
}' or l.common_mistakes is distinct from '["استخدام Service Locator داخل خدمات الدومين العميقة، مما يجعل تتبع شجرة التبعيات أمراً شديد التعقيد."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون استخدام Service Locator مقبولاً أو اضطرارياً في بعض أطر العمل القديمة؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — Inversion of Control Containers and the Dependency Injection pattern","url":"https://martinfowler.com/articles/injection.html"}]'::jsonb)) then raise exception 'Question fsld-006 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Solid Ioc Containers And Dependency Injection?', 'This question checks the core Solid Ioc Containers And Dependency Injection concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Solid Ioc Containers And Dependency Injection with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// مضاد نمط (Service Locator):
