insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي دورات حياة الكائنات في حاويات DI (Transient, Scoped, Singleton) وما هي مشكلة التبعية الأسيرة (Captive Dependency)؟', 'الـ Transient ينشئ كائناً جديداً في كل طلب، والـ Scoped ينشئ كائناً واحداً لكل طلب HTTP/سياق عمل، والـ Singleton ينشئ نسخة واحدة لكل عمر التطبيق. وتحدث التبعية الأسيرة عندما يعتمد Singleton على Scoped/Transient.', 'تعتبر التبعية الأسيرة (Captive Dependency) خطأ فادحاً يهدد أمان وتماسك البيانات: إذا تم حقن خدمة Scoped (مثل DbContext مخصص لطلب المستخدم الحالي) داخل خدمة من نوع Singleton، فسيتم أسر كائن قاعدة البيانات داخل الـ Singleton ولن يُحرر أبداً، مما يؤدي لتسريب الذاكرة (Memory Leak) ومشاركة سياق المستخدم الخاطئ بين طلبات مستخدمين مختلفين عبر الـ Threads!', '// خطأ كارثي (Captive Dependency):
// خدمات Singleton طويلة العمر لا يجوز أن تحقن بداخلها خدمات Scoped أو Transient محملة بحالة طلب معينة', '["تسجيل خدمة تعتمد على سياق المستخدم والمصادقة كـ Singleton، مما يخلط بيانات العملاء ببعضها في وقت التشغيل."]'::jsonb, '["كيف تكتشف حاويات حقن التبعيات الحديثة التبعيات الأسيرة تلقائياً أثناء تشغيل بيئة التطوير؟"]'::jsonb, '[{"title":"Dependency injection in .NET - Lifecycles","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection#service-lifetimes"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي دورات حياة الكائنات في حاويات DI (Transient, Scoped, Singleton) وما هي مشكلة التبعية الأسيرة (Captive Dependency)؟' or l.short_answer is distinct from 'الـ Transient ينشئ كائناً جديداً في كل طلب، والـ Scoped ينشئ كائناً واحداً لكل طلب HTTP/سياق عمل، والـ Singleton ينشئ نسخة واحدة لكل عمر التطبيق. وتحدث التبعية الأسيرة عندما يعتمد Singleton على Scoped/Transient.' or l.explanation is distinct from 'تعتبر التبعية الأسيرة (Captive Dependency) خطأ فادحاً يهدد أمان وتماسك البيانات: إذا تم حقن خدمة Scoped (مثل DbContext مخصص لطلب المستخدم الحالي) داخل خدمة من نوع Singleton، فسيتم أسر كائن قاعدة البيانات داخل الـ Singleton ولن يُحرر أبداً، مما يؤدي لتسريب الذاكرة (Memory Leak) ومشاركة سياق المستخدم الخاطئ بين طلبات مستخدمين مختلفين عبر الـ Threads!' or l.code_example is distinct from '// خطأ كارثي (Captive Dependency):
// خدمات Singleton طويلة العمر لا يجوز أن تحقن بداخلها خدمات Scoped أو Transient محملة بحالة طلب معينة' or l.common_mistakes is distinct from '["تسجيل خدمة تعتمد على سياق المستخدم والمصادقة كـ Singleton، مما يخلط بيانات العملاء ببعضها في وقت التشغيل."]'::jsonb or l.follow_up_questions is distinct from '["كيف تكتشف حاويات حقن التبعيات الحديثة التبعيات الأسيرة تلقائياً أثناء تشغيل بيئة التطوير؟"]'::jsonb or l.sources is distinct from '[{"title":"Dependency injection in .NET - Lifecycles","url":"https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection#service-lifetimes"}]'::jsonb)) then raise exception 'Question fsld-007 ar content changed; create a new revision before seeding'; end if; end $$;
