insert into public.interview_questions (id, slug, track_id, difficulty) values ('fsld-008', 'solid-over-engineering-and-speculative-generality', 'fundamentals', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
