insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى يصبح تطبيق مبادئ SOLID مفرطاً وهندسة زائدة (Over-engineering) وما هي علامات رائحة الكود Speculative Generality؟', 'يحدث الإفراط عندما تُبنى طبقات تجريد وواجهات وسيطة لميزات غير مطلوبة بدعوى الاستعداد للمستقبل، مما يضاعف تكلفة قراءة الشفرة وصيانتها دون أي عائد حقيقي.', 'تظهر رائحة ''التعميم التخميني'' عندما تجد واجهات برمجية لا تملك سوى تنفيذ واحد فقط، وفئات محولة (Adapters) لوظائف لن تتغير قط، ومرور المعاملات عبر خمس طبقات وسيطة لا تفعل شيئاً سوى إعادة التمرير. يجب تطبيق SOLID كعلاج لضغط التغيير الواقعي والتعقيد المتزايد، وليس كقالب إلزامي على كل سطر في تطبيق بسيط.', '// مثال هندسة مفرطة: إضافة 4 ملفات interface و factory لجمع رقمين!
// القاعدة: ابدأ بأبسط حل يعمل، ثم أعد الهيكلة (Refactor) بمجرد ظهور متطلب التغيير الثاني.', '["إنشاء واجهة Interface لكل فئة حتى لو كانت الفئة داخلية وغير مرشحة للاستبدال، فقط لإرضاء فكرة ''البرمجة ضد الواجهات''."]'::jsonb, '["ما هي قاعدة الثلاثة (Rule of Three) في هندسة البرمجيات لتجنب التجريد المبكر؟"]'::jsonb, '[{"title":"Martin Fowler — Speculative Generality","url":"https://refactoring.guru/smells/speculative-generality"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'متى يصبح تطبيق مبادئ SOLID مفرطاً وهندسة زائدة (Over-engineering) وما هي علامات رائحة الكود Speculative Generality؟' or l.short_answer is distinct from 'يحدث الإفراط عندما تُبنى طبقات تجريد وواجهات وسيطة لميزات غير مطلوبة بدعوى الاستعداد للمستقبل، مما يضاعف تكلفة قراءة الشفرة وصيانتها دون أي عائد حقيقي.' or l.explanation is distinct from 'تظهر رائحة ''التعميم التخميني'' عندما تجد واجهات برمجية لا تملك سوى تنفيذ واحد فقط، وفئات محولة (Adapters) لوظائف لن تتغير قط، ومرور المعاملات عبر خمس طبقات وسيطة لا تفعل شيئاً سوى إعادة التمرير. يجب تطبيق SOLID كعلاج لضغط التغيير الواقعي والتعقيد المتزايد، وليس كقالب إلزامي على كل سطر في تطبيق بسيط.' or l.code_example is distinct from '// مثال هندسة مفرطة: إضافة 4 ملفات interface و factory لجمع رقمين!
// القاعدة: ابدأ بأبسط حل يعمل، ثم أعد الهيكلة (Refactor) بمجرد ظهور متطلب التغيير الثاني.' or l.common_mistakes is distinct from '["إنشاء واجهة Interface لكل فئة حتى لو كانت الفئة داخلية وغير مرشحة للاستبدال، فقط لإرضاء فكرة ''البرمجة ضد الواجهات''."]'::jsonb or l.follow_up_questions is distinct from '["ما هي قاعدة الثلاثة (Rule of Three) في هندسة البرمجيات لتجنب التجريد المبكر؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — Speculative Generality","url":"https://refactoring.guru/smells/speculative-generality"}]'::jsonb)) then raise exception 'Question fsld-008 ar content changed; create a new revision before seeding'; end if; end $$;
