insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبدأ بإعادة هيكلة كود قديم معقد (Legacy Code) ليتوافق مع مبادئ SOLID بأمان تام ودون كسر الوظائف الحالية؟', 'عبر تثبيت السلوك القائم أولاً باستخدام اختبارات التوصيف (Characterization Tests)، ثم إيجاد خطوط الفصل (Seams) وتفكيك التبعيات تدريجياً خطوة بخطوة.', 'كما وثق مايكل فيذرز في كتاب ''Working Effectively with Legacy Code''، لا يجوز أبداً إعادة كتابة كود معقد يعمل في الإنتاج دون شبكة أمان. الخطوات العملية: (1) كتابة Golden Master / Characterization Tests لتسجيل المدخلات والمخرجات الحقيقية الحالية. (2) استخدام تقنية Sprout Method أو Wrap Class لإضافة التغييرات الجديدة معزولة. (3) كسر الاعتماد المباشر على الموارد الخارجية عبر Extract Interface وحقنها تدريجياً.', '// عزل كود قديم داخل Seam:
// استخراج واجهة للمكون الخارجي لتسهيل عزله وتمريره:
interface LegacyOrderSeam {
  executeLegacyValidation(orderId: string): boolean;
}', '["البدء في إعادة كتابة (Rewrite) كاملة للنظام من الصفر، وهي مخاطرة كارثية تؤدي غالباً لفشل المشاريع وإدخال أخطاء مجهولة."]'::jsonb, '["ما الفرق بين الـ Seam ونقطة الدخول المفصلية (Enabling Point) عند اختبار كود لا يملك منشئات مرنة؟"]'::jsonb, '[{"title":"Working Effectively with Legacy Code - Michael Feathers","url":"https://en.wikipedia.org/wiki/Michael_Feathers"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
