insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين التكرار الحقيقي (True Duplication) والتكرار العرضي (Accidental Duplication) ومتى يكون تكرار الكود أفضل من التجريد الخاطئ؟', 'التكرار الحقيقي يحدث عندما يتطابق المنطق والسبب في التغيير، بينما التكرار العرضي هو تشابه في الشكل السطحي لكود يخدم جهتين فاعلتين مختلفتين ستتغير متطلباتهما بشكل مستقل مستقبلاً.', 'إذا كان كود حساب خصم المتجر الإلكتروني يشبه سطرين من كود تقرير الضرائب، فدمجهما في دالة واحدة انتهاك لمبدأ SRP باسم DRY! مستقبلاً عندما تتغير قوانين الضرائب، سيعدل المطور الدالة فينكسر حساب المتجر دون قصد. التكرار العرضي أقل تكلفة بكثير من التجريد الخاطئ (The Wrong Abstraction is far worse than Duplication).', '// الأفضل إبقاء الكودين منفصلين إذا كان أحدهما لعملاء التجزئة والآخر للمؤسسات، لأن أسباب تغييرهما متباينة تماماً.', '["الاستعجال في دمج أي دالتين متشابهتين في دالة عامة معقدة مليئة بـ flags وشروط if/else للتعامل مع الفروق الطفيفة."]'::jsonb, '["ما هي مقولة ساندي ميتز الشهيرة حول تفضيل التكرار على التجريد الخاطئ؟"]'::jsonb, '[{"title":"Sandi Metz — The Wrong Abstraction","url":"https://sandimetz.com/blog/2016/1/20/the-wrong-abstraction"}]'::jsonb from public.question_revisions r where r.question_id = 'fsld-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsld-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين التكرار الحقيقي (True Duplication) والتكرار العرضي (Accidental Duplication) ومتى يكون تكرار الكود أفضل من التجريد الخاطئ؟' or l.short_answer is distinct from 'التكرار الحقيقي يحدث عندما يتطابق المنطق والسبب في التغيير، بينما التكرار العرضي هو تشابه في الشكل السطحي لكود يخدم جهتين فاعلتين مختلفتين ستتغير متطلباتهما بشكل مستقل مستقبلاً.' or l.explanation is distinct from 'إذا كان كود حساب خصم المتجر الإلكتروني يشبه سطرين من كود تقرير الضرائب، فدمجهما في دالة واحدة انتهاك لمبدأ SRP باسم DRY! مستقبلاً عندما تتغير قوانين الضرائب، سيعدل المطور الدالة فينكسر حساب المتجر دون قصد. التكرار العرضي أقل تكلفة بكثير من التجريد الخاطئ (The Wrong Abstraction is far worse than Duplication).' or l.code_example is distinct from '// الأفضل إبقاء الكودين منفصلين إذا كان أحدهما لعملاء التجزئة والآخر للمؤسسات، لأن أسباب تغييرهما متباينة تماماً.' or l.common_mistakes is distinct from '["الاستعجال في دمج أي دالتين متشابهتين في دالة عامة معقدة مليئة بـ flags وشروط if/else للتعامل مع الفروق الطفيفة."]'::jsonb or l.follow_up_questions is distinct from '["ما هي مقولة ساندي ميتز الشهيرة حول تفضيل التكرار على التجريد الخاطئ؟"]'::jsonb or l.sources is distinct from '[{"title":"Sandi Metz — The Wrong Abstraction","url":"https://sandimetz.com/blog/2016/1/20/the-wrong-abstraction"}]'::jsonb)) then raise exception 'Question fsld-010 ar content changed; create a new revision before seeding'; end if; end $$;
