insert into public.interview_questions (id, slug, track_id, difficulty) values ('fpat-001', 'design-patterns-creational-structural-behavioral-overview', 'fundamentals', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
