insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الفرق الجوهري بين نمط Factory Method ونمط Abstract Factory؟', 'نمط Factory Method يعتمد على الوراثة لإنشاء نوع واحد من الكائنات عبر دالة مخصصة، بينما Abstract Factory يعتمد على التركيب لإنشاء عائلات كاملة من الكائنات المترابطة دون تحديد فئاتها الملموسة.', 'في Factory Method، تمتلك الفئة دالة createProduct() تترك للفئات المشتقة حرية اختيار المنتج الملموس. أما في Abstract Factory، توجد واجهة برمجية كاملة تحتوي على عدة دوال إنشائية لإنشاء عائلة كاملة من المنتجات المتوافقة (مثل واجهة GUIFactory التي تنشئ Button و Checkbox لأنظمة مختلفة: WindowsFactory و MacFactory).', 'interface GUIFactory {
  createButton(): Button;
  createCheckbox(): Checkbox;
}
class WinFactory implements GUIFactory {
  createButton() { return new WinButton(); }
  createCheckbox() { return new WinCheckbox(); }
}', '["استدعاء أي دالة ثابتة تنشئ كائناً (مثل User.create()) باسم Abstract Factory؛ الدوال الثابتة البسيطة تسمى Simple Factory."]'::jsonb, '["كيف يضمن نمط Abstract Factory توافق المنتجات المنشأة مع بعضها البعض (Compatibility)?"]'::jsonb, '[{"title":"Abstract Factory Pattern - Refactoring Guru","url":"https://refactoring.guru/design-patterns/abstract-factory"}]'::jsonb from public.question_revisions r where r.question_id = 'fpat-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
