insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يعتبر نمط السينجلتون (Singleton Pattern) مضاد نمط (Anti-pattern) في معظم تطبيقات المؤسسات الحديثة؟', 'لأنه يدخل حالة عامة مشتركة (Global Mutable State) تخفي التبعيات وتجعل الاختبار المستقل مستحيلاً، فضلاً عن تعقيدات الأمان وتعدد الخيوط (Thread Safety).', 'السينجلتون ينتهك مبدأ المسؤولية الواحدة (SRP) لأنه يدير دورة حياته بنفسه بالإضافة لأداء وظيفته الأساسية. في بيئات تعدد الخيوط والـ Unit Testing، تحتفظ الكائنات العامة بحالتها بين الاختبارات مما يؤدي لفشل عشوائي متسلسل وغير مفهوم. في النظم الحديثة، يتم الاعتماد على حاويات حقن التبعيات (DI Containers) لتسجيل الخدمات كـ Singleton Lifecycle مع إبقاء الكود نفسه عادياً وقابلاً للاختبار والـ Mock.', 'class Singleton {
  private static instance: Singleton;
  private constructor() {} // منع الإنشاء المباشر
  public static getInstance(): Singleton {
    if (!Singleton.instance) Singleton.instance = new Singleton();
    return Singleton.instance;
  }
}', '["تطبيق السينجلتون في بيئة متعددة الخيوط دون مزامنة ملائمة، مما يسبب إنشاء عدة نسخ متزامنة في الذاكرة (Race Condition)."]'::jsonb, '["كيف يعمل أسلوب Double-Checked Locking لضمان Thread Safety في السينجلتون؟"]'::jsonb, '[{"title":"Singleton Pattern - Refactoring Guru","url":"https://refactoring.guru/design-patterns/singleton"}]'::jsonb from public.question_revisions r where r.question_id = 'fpat-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
