class DraftState implements OrderState {
  next(order: Order) { order.setState(new PaidState()); }
}
// Strategy: العميل يمرر الخوارزمية
const sorter = new Sorter(new QuickSortStrategy());' or l.common_mistakes is distinct from '["استخدام سلاسل if/else عملاقة لإدارة الحالات المعقدة، مما يسبب تعقيداً شديداً وصعوبة في إضافة حالات جديدة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يساعد نمط State في تطبيق آلات الحالة المحدودة (Finite State Machines) بشكل نظيف؟"]'::jsonb or l.sources is distinct from '[{"title":"Strategy Pattern - Refactoring Guru","url":"https://refactoring.guru/design-patterns/strategy"}]'::jsonb)) then raise exception 'Question fpat-004 ar content changed; create a new revision before seeding'; end if; end $$;
