insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين الأنماط الهيكلية الثلاثة المتشابهة: Decorator و Adapter و Proxy من حيث الغرض؟', 'الـ Adapter يغير واجهة كائن موجود ليتوافق مع واجهة أخرى، والـ Decorator يضيف وظائف ومسؤوليات جديدة لنفس الواجهة، والـ Proxy يتحكم في الوصول للكائن مع الاحتفاظ بنفس الواجهة تماماً.', 'الـ Adapter مثل محول الكهرباء للمسافرين: يحول واجهة غير متوافقة إلى واجهة يتوقعها العميل. الـ Decorator مثل ارتداء معطف فوق الملابس: يغلف الكائن الأصلي ويضيف سلوكيات جديدة (مثل التخزين المؤقت Caching أو التسجيل Logging) دون تعديل الفئة الأصلية. أما الـ Proxy فهو وكيل يقف أمام الكائن للتحكم فيه (مثل التحقق من الصلاحيات Security Proxy أو التحميل الكسول Lazy Loading أو حماية الاتصال عن بعد Remote Proxy).', '// Decorator: نفس الواجهة + سلوك إضافي
class LoggingNotifier implements Notifier {
  constructor(private inner: Notifier) {}
  send(msg: string) { console.log(''Log''); this.inner.send(msg); }
}', '["استخدام نمط Adapter لتعديل سلوك الكائن، في حين أن مهمته الوحيدة هي ترجمة الواجهات دون المساس بالسلوك الأصلي."]'::jsonb, '["كيف يطبق نمط Dynamic Proxy في أطر العمل لإنشاء المعاملات التلقائية (Declarative Transactions)؟"]'::jsonb, '[{"title":"Decorator Pattern - Refactoring Guru","url":"https://refactoring.guru/design-patterns/decorator"}]'::jsonb from public.question_revisions r where r.question_id = 'fpat-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fpat-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين الأنماط الهيكلية الثلاثة المتشابهة: Decorator و Adapter و Proxy من حيث الغرض؟' or l.short_answer is distinct from 'الـ Adapter يغير واجهة كائن موجود ليتوافق مع واجهة أخرى، والـ Decorator يضيف وظائف ومسؤوليات جديدة لنفس الواجهة، والـ Proxy يتحكم في الوصول للكائن مع الاحتفاظ بنفس الواجهة تماماً.' or l.explanation is distinct from 'الـ Adapter مثل محول الكهرباء للمسافرين: يحول واجهة غير متوافقة إلى واجهة يتوقعها العميل. الـ Decorator مثل ارتداء معطف فوق الملابس: يغلف الكائن الأصلي ويضيف سلوكيات جديدة (مثل التخزين المؤقت Caching أو التسجيل Logging) دون تعديل الفئة الأصلية. أما الـ Proxy فهو وكيل يقف أمام الكائن للتحكم فيه (مثل التحقق من الصلاحيات Security Proxy أو التحميل الكسول Lazy Loading أو حماية الاتصال عن بعد Remote Proxy).' or l.code_example is distinct from '// Decorator: نفس الواجهة + سلوك إضافي
class LoggingNotifier implements Notifier {
