  send(msg: string) { console.log(''Log''); this.inner.send(msg); }
}' or l.common_mistakes is distinct from '["استخدام نمط Adapter لتعديل سلوك الكائن، في حين أن مهمته الوحيدة هي ترجمة الواجهات دون المساس بالسلوك الأصلي."]'::jsonb or l.follow_up_questions is distinct from '["كيف يطبق نمط Dynamic Proxy في أطر العمل لإنشاء المعاملات التلقائية (Declarative Transactions)؟"]'::jsonb or l.sources is distinct from '[{"title":"Decorator Pattern - Refactoring Guru","url":"https://refactoring.guru/design-patterns/decorator"}]'::jsonb)) then raise exception 'Question fpat-006 ar content changed; create a new revision before seeding'; end if; end $$;
