insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل نمط سلسلة المسؤولية (Chain of Responsibility) وما علاقته بمعمارية الـ Middleware في خوادم الويب الحديثة؟', 'يمرر النمط الطلب عبر سلسلة من المعالجات، حيث يقرر كل معالج إما معالجة الطلب وتمريره للمعالج التالي أو إيقاف السلسلة ورفض الطلب فوراً.', 'هذا النمط هو الأساس المعماري لأنظمة الـ Middleware في Express و ASP.NET و Fastify و Laravel. عند وصول طلب HTTP، يمر أولاً بـ LoggingMiddleware، ثم CorsMiddleware، ثم AuthenticationMiddleware (الذي قد يقطع السلسلة ويرد بـ 401)، ثم RateLimitingMiddleware، وصولاً إلى معالج المسار النهائي (Route Handler). هذا يفصل اهتمامات البنية التحتية تماماً عن كود الخدمة.', 'interface Handler {
  setNext(h: Handler): Handler;
  handle(req: Request): Response | null;
}', '["نسيان تمرير الطلب للمعالج التالي عبر next()، مما يسبب تعليق الطلب للأبد دون استجابة."]'::jsonb, '["كيف تختلف سلسلة المسؤولية الكلاسيكية (حيث يعالج الطلب عنصر واحد فقط) عن نموذج الـ Pipeline/Interceptors؟"]'::jsonb, '[{"title":"Chain of Responsibility - Refactoring Guru","url":"https://refactoring.guru/design-patterns/chain-of-responsibility"}]'::jsonb from public.question_revisions r where r.question_id = 'fpat-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
