insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي قواعد التسمية المعبرة ومبدأ فصل الأوامر عن الاستعلامات (Command-Query Separation - CQS) في الشفرة النظيفة؟', 'التسمية المعبرة توضح القصد والهدف والسياق دون الحاجة لتعليقات مفسرة، ومبدأ CQS يفرض أن الدالة إما أن تغير حالة النظام (Command) أو ترجع إجابة وبيانات (Query) ولكن ليس كلاهما معاً.', 'تجنب الأسماء المبهمة مثل data أو info أو x. دالة get يجب ألا تعدل البيانات خلسة، ودالة set لا يجب أن ترجع نتائج معقدة. انتهاك CQS (مثل دالة loginUser() التي تعيد مصفوفة الأصدقاء وتعدل كلمة المرور) ينتج عنه آثار جانبية خفية (Side Effects) تجعل تتبع الأخطاء واختبار النظام كابوساً للمطورين.', '// انتهاك CQS: الدالة تقرأ وتعدل في نفس الوقت
function getUserAndIncrementLoginCount(id: string): User { /*...*/ }

// متوافق مع CQS: عمليتان منفصلتان
function incrementLoginCount(id: string): void { /*...*/ }
function getUser(id: string): User { /*...*/ }', '["استخدام أسماء مختصرة غير مفهومة لتوفير بضعة أحرف في الكتابة، مما يرفع الجهد الإدراكي لكل من يقرأ الكود لاحقاً.","كتابة تعليقات تشرح ''ماذا يفعل الكود'' بدلاً من تحسين تسمية المتغيرات والدوال ليتحدث الكود عن نفسه."]'::jsonb, '["ما هي الاستثناءات النادرة لمبدأ CQS مثل عمليات طوابير البيانات (Stack.pop())؟"]'::jsonb, '[{"title":"Martin Fowler — Command Query Separation","url":"https://martinfowler.com/bliki/CommandQuerySeparation.html"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcln-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي قواعد التسمية المعبرة ومبدأ فصل الأوامر عن الاستعلامات (Command-Query Separation - CQS) في الشفرة النظيفة؟' or l.short_answer is distinct from 'التسمية المعبرة توضح القصد والهدف والسياق دون الحاجة لتعليقات مفسرة، ومبدأ CQS يفرض أن الدالة إما أن تغير حالة النظام (Command) أو ترجع إجابة وبيانات (Query) ولكن ليس كلاهما معاً.' or l.explanation is distinct from 'تجنب الأسماء المبهمة مثل data أو info أو x. دالة get يجب ألا تعدل البيانات خلسة، ودالة set لا يجب أن ترجع نتائج معقدة. انتهاك CQS (مثل دالة loginUser() التي تعيد مصفوفة الأصدقاء وتعدل كلمة المرور) ينتج عنه آثار جانبية خفية (Side Effects) تجعل تتبع الأخطاء واختبار النظام كابوساً للمطورين.' or l.code_example is distinct from '// انتهاك CQS: الدالة تقرأ وتعدل في نفس الوقت
function getUserAndIncrementLoginCount(id: string): User { /*...*/ }

// متوافق مع CQS: عمليتان منفصلتان
function incrementLoginCount(id: string): void { /*...*/ }
function getUser(id: string): User { /*...*/ }' or l.common_mistakes is distinct from '["استخدام أسماء مختصرة غير مفهومة لتوفير بضعة أحرف في الكتابة، مما يرفع الجهد الإدراكي لكل من يقرأ الكود لاحقاً.","كتابة تعليقات تشرح ''ماذا يفعل الكود'' بدلاً من تحسين تسمية المتغيرات والدوال ليتحدث الكود عن نفسه."]'::jsonb or l.follow_up_questions is distinct from '["ما هي الاستثناءات النادرة لمبدأ CQS مثل عمليات طوابير البيانات (Stack.pop())؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — Command Query Separation","url":"https://martinfowler.com/bliki/CommandQuerySeparation.html"}]'::jsonb)) then raise exception 'Question fcln-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Clean Code Meaningful Naming Cqs Principle?', 'This question checks the core Clean Code Meaningful Naming Cqs Principle concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Clean Code Meaningful Naming Cqs Principle with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// انتهاك CQS: الدالة تقرأ وتعدل في نفس الوقت
