insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي روائح الكود (Code Smells) واشرح رائحتي ''God Object'' و ''Feature Envy'' وكيف تتخلص منهما؟', 'روائح الكود هي مؤشرات سطحية في الشفرة تدل على وجود مشاكل تصميمية ومعمارية أعمق. ''God Object'' هي فئة عملاقة تعرف وتفعل كل شيء، و''Feature Envy'' تحدث عندما تكون الدالة مهتمة ببيانات فئة أخرى أكثر من بيانات فئتها.', 'علاج God Object هو استخدام Extract Class وتقسيم المسؤوليات وفقاً لـ SRP. أما علاج Feature Envy فهو تطبيق أسلوب Move Method؛ إذا وجدت دالة في OrderService تستدعي عشرات الـ Getters من كائن Customer لحساب نقاط الولاء، فهذا يعني أن هذا المنطق ينتمي في الأصل داخل فئة Customer، فننقل الدالة إلى هناك ونستدعيها ببساطة.', '// Feature Envy: دالة تتدخل في بيانات كائن آخر وتطلب بياناته الداخلية بدلاً من تفويضه
class OrderPrinter {
  printCustomer(c: Customer) {
    // استدعاء 5 خصائص من العميل لحساب التنسيق
  }
}', '["اعتبار أن Code Smell هو خطأ برمجي مباشر (Bug)؛ الروائح لا توقف البرنامج عن العمل ولكنها تجعل صيانته وتطويره مستحيلاً وبطيئاً."]'::jsonb, '["ما هي رائحة الكود المسماة Shotgun Surgery وكيف تختلف عن Divergent Change؟"]'::jsonb, '[{"title":"Refactoring Guru — Code Smells","url":"https://refactoring.guru/refactoring/smells"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcln-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي روائح الكود (Code Smells) واشرح رائحتي ''God Object'' و ''Feature Envy'' وكيف تتخلص منهما؟' or l.short_answer is distinct from 'روائح الكود هي مؤشرات سطحية في الشفرة تدل على وجود مشاكل تصميمية ومعمارية أعمق. ''God Object'' هي فئة عملاقة تعرف وتفعل كل شيء، و''Feature Envy'' تحدث عندما تكون الدالة مهتمة ببيانات فئة أخرى أكثر من بيانات فئتها.' or l.explanation is distinct from 'علاج God Object هو استخدام Extract Class وتقسيم المسؤوليات وفقاً لـ SRP. أما علاج Feature Envy فهو تطبيق أسلوب Move Method؛ إذا وجدت دالة في OrderService تستدعي عشرات الـ Getters من كائن Customer لحساب نقاط الولاء، فهذا يعني أن هذا المنطق ينتمي في الأصل داخل فئة Customer، فننقل الدالة إلى هناك ونستدعيها ببساطة.' or l.code_example is distinct from '// Feature Envy: دالة تتدخل في بيانات كائن آخر وتطلب بياناته الداخلية بدلاً من تفويضه
class OrderPrinter {
  printCustomer(c: Customer) {
    // استدعاء 5 خصائص من العميل لحساب التنسيق
  }
}' or l.common_mistakes is distinct from '["اعتبار أن Code Smell هو خطأ برمجي مباشر (Bug)؛ الروائح لا توقف البرنامج عن العمل ولكنها تجعل صيانته وتطويره مستحيلاً وبطيئاً."]'::jsonb or l.follow_up_questions is distinct from '["ما هي رائحة الكود المسماة Shotgun Surgery وكيف تختلف عن Divergent Change؟"]'::jsonb or l.sources is distinct from '[{"title":"Refactoring Guru — Code Smells","url":"https://refactoring.guru/refactoring/smells"}]'::jsonb)) then raise exception 'Question fcln-002 ar content changed; create a new revision before seeding'; end if; end $$;
