insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو مقياس التعقيد الدوري (Cyclomatic Complexity) وكيف تقلله لتحسين قابلية الاختبار؟', 'هو مقياس كمي لعدد المسارات المنطقية المستقلة داخل الدالة، ويُحسب بعدد نقاط التفرع (if, while, for, case, &&, ||) مضافاً إليها واحد.', 'كلما زاد التعقيد الدوري (فوق 10)، كلما تطلب الكود كتابة عدد أكبر من اختبارات الوحدة لتغطية كل السيناريوهات، وزادت احتمالية الأخطاء غير المتوقعة. تقنيات تخفيض التعقيد: (1) استخدام حراس الإرجاع المبكر (Guard Clauses) للتخلص من التداخل العميق (Arrow Anti-pattern). (2) استبدال الشروط بتعدد الأشكال (Replace Conditional with Polymorphism). (3) استخراج الدوال المعقدة (Extract Method).', '// قبل (تعقيد عالي وتداخل عميق):
function process(user) {
  if (user != null) {
    if (user.isActive) {
      if (user.hasPermission) { doSomething(); }
    }
  }
}
// بعد (Guard Clauses - تعقيد منخفض ومسطح):
function process(user) {
  if (!user || !user.isActive || !user.hasPermission) return;
  doSomething();
}', '["كتابة كتل if متداخلة لـ 5 أو 6 مستويات، مما يجعل قراءة الكود صعبة جداً وتتبع الحالات مستحيلاً."]'::jsonb, '["كيف تساعد أدوات التحليل الساكن (Static Analyzers) في تحديد سقف التعقيد الدوري في مسارات CI/CD؟"]'::jsonb, '[{"title":"Cyclomatic complexity - Wikipedia","url":"https://en.wikipedia.org/wiki/Cyclomatic_complexity"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcln-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو مقياس التعقيد الدوري (Cyclomatic Complexity) وكيف تقلله لتحسين قابلية الاختبار؟' or l.short_answer is distinct from 'هو مقياس كمي لعدد المسارات المنطقية المستقلة داخل الدالة، ويُحسب بعدد نقاط التفرع (if, while, for, case, &&, ||) مضافاً إليها واحد.' or l.explanation is distinct from 'كلما زاد التعقيد الدوري (فوق 10)، كلما تطلب الكود كتابة عدد أكبر من اختبارات الوحدة لتغطية كل السيناريوهات، وزادت احتمالية الأخطاء غير المتوقعة. تقنيات تخفيض التعقيد: (1) استخدام حراس الإرجاع المبكر (Guard Clauses) للتخلص من التداخل العميق (Arrow Anti-pattern). (2) استبدال الشروط بتعدد الأشكال (Replace Conditional with Polymorphism). (3) استخراج الدوال المعقدة (Extract Method).' or l.code_example is distinct from '// قبل (تعقيد عالي وتداخل عميق):
function process(user) {
  if (user != null) {
    if (user.isActive) {
      if (user.hasPermission) { doSomething(); }
    }
  }
}
// بعد (Guard Clauses - تعقيد منخفض ومسطح):
function process(user) {
  if (!user || !user.isActive || !user.hasPermission) return;
  doSomething();
}' or l.common_mistakes is distinct from '["كتابة كتل if متداخلة لـ 5 أو 6 مستويات، مما يجعل قراءة الكود صعبة جداً وتتبع الحالات مستحيلاً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساعد أدوات التحليل الساكن (Static Analyzers) في تحديد سقف التعقيد الدوري في مسارات CI/CD؟"]'::jsonb or l.sources is distinct from '[{"title":"Cyclomatic complexity - Wikipedia","url":"https://en.wikipedia.org/wiki/Cyclomatic_complexity"}]'::jsonb)) then raise exception 'Question fcln-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Clean Code Cyclomatic Complexity Reduction?', 'This question checks the core Clean Code Cyclomatic Complexity Reduction concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Clean Code Cyclomatic Complexity Reduction with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// قبل (تعقيد عالي وتداخل عميق):
