insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي أفضل ممارسات معالجة الاستثناءات ومبدأ الإخفاق السريع (Fail-Fast) وتجنب ابتلاع الأخطاء (Exception Swallowing)؟', 'مبدأ Fail-Fast يقتضي الكشف عن المشاكل فور حدوثها في أقرب نقطة ورمي استثناء واضح، وتجنب كتل try-catch الفارغة التي تبتلع الأخطاء وتخفي الكوارث.', 'ابتلاع الاستثناء عبر catch (e) {} دون تسجيله أو معالجته يُعتبر جريمة برمجية؛ لأنه يترك النظام يعمل في حالة فاسدة وغير متسقة تقود إلى أخطاء غامضة بعد دقائق في مكان آخر تماماً. الممارسات الصحيحة: (1) التحقق من صحة المدخلات في بداية الدالة ورمي استثناء دقيق فوراً. (2) إنشاء استثناءات دومين مخصصة وذات مغزى (Domain Exceptions). (3) المعالجة في أعلى مستوى مناسب (مثل Global Error Handler).', '// خطأ كارثي (ابتلاع الخطأ):
try { saveTransaction(); } catch (err) { /* صمت مطبق */ }

// صحيح (Fail-Fast):
if (amount <= 0) throw new InvalidTransactionAmountException(amount);', '["استخدام الاستثناءات (Exceptions) لإدارة التدفق المنطقي العادي للبرنامج (Flow Control) بدلاً من معالجة الحالات الاستثنائية الحقيقية."]'::jsonb, '["متى تفضل استخدام نمط النتيجة (Result Pattern / Either Monad) بدلاً من رمي الاستثناءات؟"]'::jsonb, '[{"title":"Fail-fast system - Wikipedia","url":"https://en.wikipedia.org/wiki/Fail-fast"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcln-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي أفضل ممارسات معالجة الاستثناءات ومبدأ الإخفاق السريع (Fail-Fast) وتجنب ابتلاع الأخطاء (Exception Swallowing)؟' or l.short_answer is distinct from 'مبدأ Fail-Fast يقتضي الكشف عن المشاكل فور حدوثها في أقرب نقطة ورمي استثناء واضح، وتجنب كتل try-catch الفارغة التي تبتلع الأخطاء وتخفي الكوارث.' or l.explanation is distinct from 'ابتلاع الاستثناء عبر catch (e) {} دون تسجيله أو معالجته يُعتبر جريمة برمجية؛ لأنه يترك النظام يعمل في حالة فاسدة وغير متسقة تقود إلى أخطاء غامضة بعد دقائق في مكان آخر تماماً. الممارسات الصحيحة: (1) التحقق من صحة المدخلات في بداية الدالة ورمي استثناء دقيق فوراً. (2) إنشاء استثناءات دومين مخصصة وذات مغزى (Domain Exceptions). (3) المعالجة في أعلى مستوى مناسب (مثل Global Error Handler).' or l.code_example is distinct from '// خطأ كارثي (ابتلاع الخطأ):
try { saveTransaction(); } catch (err) { /* صمت مطبق */ }

// صحيح (Fail-Fast):
if (amount <= 0) throw new InvalidTransactionAmountException(amount);' or l.common_mistakes is distinct from '["استخدام الاستثناءات (Exceptions) لإدارة التدفق المنطقي العادي للبرنامج (Flow Control) بدلاً من معالجة الحالات الاستثنائية الحقيقية."]'::jsonb or l.follow_up_questions is distinct from '["متى تفضل استخدام نمط النتيجة (Result Pattern / Either Monad) بدلاً من رمي الاستثناءات؟"]'::jsonb or l.sources is distinct from '[{"title":"Fail-fast system - Wikipedia","url":"https://en.wikipedia.org/wiki/Fail-fast"}]'::jsonb)) then raise exception 'Question fcln-005 ar content changed; create a new revision before seeding'; end if; end $$;
