insert into public.interview_questions (id, slug, track_id, difficulty) values ('fcln-006', 'clean-code-defensive-programming-vs-contract', 'fundamentals', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
