insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين البرمجة الدفاعية (Defensive Programming) ومبدأ التصميم بالتعاقد (Design by Contract - DbC)؟', 'البرمجة الدفاعية تفترض أن جميع المدخلات غير موثوقة ويجب فحصها في كل دالة لتفادي الانهيار، بينما Design by Contract يحدد عقداً صريحاً بين المستدعي والمستدعى يتحمل كل طرف مسؤوليته فيه.', 'الإفراط في البرمجة الدفاعية يؤدي لملء كل دالة داخلية بفحوصات if (arg == null) متكررة في كل طبقة حتى داخل الدومين الآمن. أما DbC فيحدد: الشروط المسبقة تقع على عاتق المستدعي (لو أرسلت قيمة سالبة فالخطأ خطؤك أنت)، والشروط اللاحقة يضمنها المنفذ. في الأنظمة الحديثة، تُستخدم البرمجة الدفاعية الصارمة على حدود النظام الخارجية (API Gateways, User Inputs)، بينما يعتمد الدومين الداخلي على DbC والأنواع القوية (Type Safety) لمنع التكرار.', '// حدود النظام (Defensive Validation):
const body = validateSchema(req.body); // دفاعي صارم على الحدود
// منطق الدومين الداخلي (Contract):
executeTransfer(source, target, body.amount); // يثق في صحة النوع المنقى', '["تطبيق البرمجة الدفاعية على كل دالة private داخلية، مما يؤدي لتضخم الكود وإخفاء الأخطاء المنطقية بدلاً من كشفها في الاختبارات."]'::jsonb, '["كيف تساهم الأنواع غير القابلة للقيم الفارغة (Null Safety) في القضاء على الحاجة لمعظم الفحوصات الدفاعية التقليدية؟"]'::jsonb, '[{"title":"Design by contract - Wikipedia","url":"https://en.wikipedia.org/wiki/Design_by_contract"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcln-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين البرمجة الدفاعية (Defensive Programming) ومبدأ التصميم بالتعاقد (Design by Contract - DbC)؟' or l.short_answer is distinct from 'البرمجة الدفاعية تفترض أن جميع المدخلات غير موثوقة ويجب فحصها في كل دالة لتفادي الانهيار، بينما Design by Contract يحدد عقداً صريحاً بين المستدعي والمستدعى يتحمل كل طرف مسؤوليته فيه.' or l.explanation is distinct from 'الإفراط في البرمجة الدفاعية يؤدي لملء كل دالة داخلية بفحوصات if (arg == null) متكررة في كل طبقة حتى داخل الدومين الآمن. أما DbC فيحدد: الشروط المسبقة تقع على عاتق المستدعي (لو أرسلت قيمة سالبة فالخطأ خطؤك أنت)، والشروط اللاحقة يضمنها المنفذ. في الأنظمة الحديثة، تُستخدم البرمجة الدفاعية الصارمة على حدود النظام الخارجية (API Gateways, User Inputs)، بينما يعتمد الدومين الداخلي على DbC والأنواع القوية (Type Safety) لمنع التكرار.' or l.code_example is distinct from '// حدود النظام (Defensive Validation):
const body = validateSchema(req.body); // دفاعي صارم على الحدود
// منطق الدومين الداخلي (Contract):
executeTransfer(source, target, body.amount); // يثق في صحة النوع المنقى' or l.common_mistakes is distinct from '["تطبيق البرمجة الدفاعية على كل دالة private داخلية، مما يؤدي لتضخم الكود وإخفاء الأخطاء المنطقية بدلاً من كشفها في الاختبارات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم الأنواع غير القابلة للقيم الفارغة (Null Safety) في القضاء على الحاجة لمعظم الفحوصات الدفاعية التقليدية؟"]'::jsonb or l.sources is distinct from '[{"title":"Design by contract - Wikipedia","url":"https://en.wikipedia.org/wiki/Design_by_contract"}]'::jsonb)) then raise exception 'Question fcln-006 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Clean Code Defensive Programming Vs Contract?', 'This question checks the core Clean Code Defensive Programming Vs Contract concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Clean Code Defensive Programming Vs Contract with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// حدود النظام (Defensive Validation):
const body = validateSchema(req.body); // دفاعي صارم على الحدود
// منطق الدومين الداخلي (Contract):
executeTransfer(source, target, body.amount); // يثق في صحة النوع المنقى', '["Missing the key trade-off in Clean Code Defensive Programming Vs Contract (point 1)."]'::jsonb, '["How would you apply Clean Code Defensive Programming Vs Contract in a production Software Engineering app (follow-up 1)?"]'::jsonb, '[{"title":"Design by contract - Wikipedia","url":"https://en.wikipedia.org/wiki/Design_by_contract"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
