insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هما مبدآ KISS و YAGNI ولماذا يعتبران أهم صمام أمان ضد تعقيد وتضخم المشاريع؟', 'KISS ينص على ''اجعل الأمر بسيطاً للغاية'' وتجنب التعقيد، و YAGNI ينص على ''لن تحتاجه على الإطلاق'' ويحظر كتابة أي وظيفة أو بنية لم تطلبها المتطلبات الحالية فوراً.', 'المشاريع لا تفشل بسبب نقص الميزات المستقبلية، بل تنهار تحت وطأة التعقيد الإدراكي وصعوبة صيانة آلاف الأسطر المكتوبة تحسباً لاحتمالات نادراً ما تحدث. كل سطر كود تكتبه يمثل التزاماً مستقبلياً بالصيانة والاختبار وإصلاح الأخطاء. المطور المحترف هو من يحل المشكلة المعقدة بأبسط كود ممكن ومفهوم، ويرفض بناء عوالم افتراضية قبل أوانها.', '// YAGNI: العميل طلب حفظ المستخدمين في ملف محلي بسيط، فلا تقم ببناء بنية Microservices موزعة مع Kafka و Redis!', '["تبرير الكود السيء والمهمل باسم KISS؛ البساطة تعني كوداً نظيفاً ومقروءاً ومصمماً بعناية، وليس كوداً عشوائياً بدون بنية."]'::jsonb, '["ما هي العلاقة بين YAGNI وتسليم الميزات الرشيقة (Agile Delivery) في شكل MVP؟"]'::jsonb, '[{"title":"Martin Fowler — YAGNI","url":"https://martinfowler.com/bliki/Yagni.html"}]'::jsonb from public.question_revisions r where r.question_id = 'fcln-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcln-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هما مبدآ KISS و YAGNI ولماذا يعتبران أهم صمام أمان ضد تعقيد وتضخم المشاريع؟' or l.short_answer is distinct from 'KISS ينص على ''اجعل الأمر بسيطاً للغاية'' وتجنب التعقيد، و YAGNI ينص على ''لن تحتاجه على الإطلاق'' ويحظر كتابة أي وظيفة أو بنية لم تطلبها المتطلبات الحالية فوراً.' or l.explanation is distinct from 'المشاريع لا تفشل بسبب نقص الميزات المستقبلية، بل تنهار تحت وطأة التعقيد الإدراكي وصعوبة صيانة آلاف الأسطر المكتوبة تحسباً لاحتمالات نادراً ما تحدث. كل سطر كود تكتبه يمثل التزاماً مستقبلياً بالصيانة والاختبار وإصلاح الأخطاء. المطور المحترف هو من يحل المشكلة المعقدة بأبسط كود ممكن ومفهوم، ويرفض بناء عوالم افتراضية قبل أوانها.' or l.code_example is distinct from '// YAGNI: العميل طلب حفظ المستخدمين في ملف محلي بسيط، فلا تقم ببناء بنية Microservices موزعة مع Kafka و Redis!' or l.common_mistakes is distinct from '["تبرير الكود السيء والمهمل باسم KISS؛ البساطة تعني كوداً نظيفاً ومقروءاً ومصمماً بعناية، وليس كوداً عشوائياً بدون بنية."]'::jsonb or l.follow_up_questions is distinct from '["ما هي العلاقة بين YAGNI وتسليم الميزات الرشيقة (Agile Delivery) في شكل MVP؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — YAGNI","url":"https://martinfowler.com/bliki/Yagni.html"}]'::jsonb)) then raise exception 'Question fcln-010 ar content changed; create a new revision before seeding'; end if; end $$;
