insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تتفوق المصفوفات (Arrays) على القوائم المترابطة (Linked Lists) في سرعة التكرار حتى لو كانت بنفس التعقيد الزمني O(N)؟', 'بسبب التموضع المكاني في الذاكرة (Spatial Locality) ومواءمتها مع خطوط التخزين المؤقت للمعالج (CPU Cache Lines)، بينما تتوزع عقد القائمة المترابطة عشوائياً في الـ Heap.', 'تُخزن عناصر المصفوفة في كتل متجاورة فيزيائياً في الذاكرة (Contiguous Memory). عندما يقرأ المعالج عنصراً، يقوم تلقائياً بجلب الكتلة المحيطة بالكامل (Cache Line عادة 64 بايت) إلى الـ L1/L2 Cache، فتكون العناصر التالية جاهزة بسرعة نانو ثانية دون التوجه للـ RAM. في المقابل، كل عقدة (Node) في Linked List تُخصص في مكان عشوائي في الذاكرة وتتطلب مؤشراً إضافياً، مما يسبب إخفاقات مستمرة في التخزين المؤقت (Cache Misses).', '// مصفوفة متصلة:
// [Elem0 | Elem1 | Elem2 | Elem3] -> تقرأ دفعة واحدة في خط كاش واحد
// قائمة مترابطة:
// [Node0] -> مؤشر -> [Node1 بعيد في الذاكرة] -> Cache Miss مستمر!', '["الاعتقاد بأن Linked List أفضل دائماً من Array للإدراج في البداية O(1)، متجاهلين أن كلفة تخصيص الذاكرة للعقدة والـ Cache Misses تجعل المصفوفة الديناميكية أسرع في معظم الحالات العملية الصغيرة."]'::jsonb, '["متى تكون القائمة المترابطة خياراً متفوقاً بالفعل على المصفوفة؟"]'::jsonb, '[{"title":"Locality of reference - Wikipedia","url":"https://en.wikipedia.org/wiki/Locality_of_reference"}]'::jsonb from public.question_revisions r where r.question_id = 'fds-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fds-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تتفوق المصفوفات (Arrays) على القوائم المترابطة (Linked Lists) في سرعة التكرار حتى لو كانت بنفس التعقيد الزمني O(N)؟' or l.short_answer is distinct from 'بسبب التموضع المكاني في الذاكرة (Spatial Locality) ومواءمتها مع خطوط التخزين المؤقت للمعالج (CPU Cache Lines)، بينما تتوزع عقد القائمة المترابطة عشوائياً في الـ Heap.' or l.explanation is distinct from 'تُخزن عناصر المصفوفة في كتل متجاورة فيزيائياً في الذاكرة (Contiguous Memory). عندما يقرأ المعالج عنصراً، يقوم تلقائياً بجلب الكتلة المحيطة بالكامل (Cache Line عادة 64 بايت) إلى الـ L1/L2 Cache، فتكون العناصر التالية جاهزة بسرعة نانو ثانية دون التوجه للـ RAM. في المقابل، كل عقدة (Node) في Linked List تُخصص في مكان عشوائي في الذاكرة وتتطلب مؤشراً إضافياً، مما يسبب إخفاقات مستمرة في التخزين المؤقت (Cache Misses).' or l.code_example is distinct from '// مصفوفة متصلة:
// [Elem0 | Elem1 | Elem2 | Elem3] -> تقرأ دفعة واحدة في خط كاش واحد
// قائمة مترابطة:
// [Node0] -> مؤشر -> [Node1 بعيد في الذاكرة] -> Cache Miss مستمر!' or l.common_mistakes is distinct from '["الاعتقاد بأن Linked List أفضل دائماً من Array للإدراج في البداية O(1)، متجاهلين أن كلفة تخصيص الذاكرة للعقدة والـ Cache Misses تجعل المصفوفة الديناميكية أسرع في معظم الحالات العملية الصغيرة."]'::jsonb or l.follow_up_questions is distinct from '["متى تكون القائمة المترابطة خياراً متفوقاً بالفعل على المصفوفة؟"]'::jsonb or l.sources is distinct from '[{"title":"Locality of reference - Wikipedia","url":"https://en.wikipedia.org/wiki/Locality_of_reference"}]'::jsonb)) then raise exception 'Question fds-001 ar content changed; create a new revision before seeding'; end if; end $$;
