insert into public.interview_questions (id, slug, track_id, difficulty) values ('fds-002', 'data-structures-hash-tables-collision-resolution', 'fundamentals', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fds-002', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل جداول التجزئة (Hash Tables) وما الفرق بين حل التصادمات عبر Chaining وعبر Open Addressing؟', 'تقوم دالة التجزئة بتحويل المفتاح إلى مؤشر رقمي في مصفوفة داخلية لتحقيق وصول O(1). وعندما ينتج نفس المؤشر لمفتاحين مختلفين (Collision)، تُحل عبر ربط القوائم (Chaining) أو البحث في الفهارس الشاغرة (Open Addressing).', 'في Separate Chaining، يحتوي كل موضع في الجدول على قائمة مترابطة أو شجرة بحث حمراء-سوداء تجمع العناصر المتصادمة في نفس الـ Bucket. في Open Addressing (مثل Linear Probing أو Quadratic Probing)، تظل كل العناصر داخل المصفوفة الرئيسية نفسها؛ وعند حدوث تصادم، يبحث الخوارزمي عن الخانة التالية الفارغة وفقاً لمعادلة فحص محددة. يحدد عامل التحميل (Load Factor) متى يجب مضاعفة حجم الجدول وإعادة التجزئة (Rehashing).', '// Chaining:
// Index 3 -> [KeyA: Val1] -> [KeyB: Val2]
// Open Addressing (Linear Probing):
// Index 3 -> [KeyA: Val1]
// Index 4 -> [KeyB: Val2] (تم وضعه في الخانة التالية الشاغرة)', '["استخدام دالة تجزئة (Hash Function) رديئة توزع العناصر في فهارس متجاورة، مما يحول جدول التجزئة إلى قائمة خطية بطيئة O(N)."]'::jsonb, '["ما هي مشكلة التكتل الأولي (Primary Clustering) في أسلوب Linear Probing؟"]'::jsonb, '[{"title":"Hash table - Wikipedia","url":"https://en.wikipedia.org/wiki/Hash_table"}]'::jsonb from public.question_revisions r where r.question_id = 'fds-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fds-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل جداول التجزئة (Hash Tables) وما الفرق بين حل التصادمات عبر Chaining وعبر Open Addressing؟' or l.short_answer is distinct from 'تقوم دالة التجزئة بتحويل المفتاح إلى مؤشر رقمي في مصفوفة داخلية لتحقيق وصول O(1). وعندما ينتج نفس المؤشر لمفتاحين مختلفين (Collision)، تُحل عبر ربط القوائم (Chaining) أو البحث في الفهارس الشاغرة (Open Addressing).' or l.explanation is distinct from 'في Separate Chaining، يحتوي كل موضع في الجدول على قائمة مترابطة أو شجرة بحث حمراء-سوداء تجمع العناصر المتصادمة في نفس الـ Bucket. في Open Addressing (مثل Linear Probing أو Quadratic Probing)، تظل كل العناصر داخل المصفوفة الرئيسية نفسها؛ وعند حدوث تصادم، يبحث الخوارزمي عن الخانة التالية الفارغة وفقاً لمعادلة فحص محددة. يحدد عامل التحميل (Load Factor) متى يجب مضاعفة حجم الجدول وإعادة التجزئة (Rehashing).' or l.code_example is distinct from '// Chaining:
// Index 3 -> [KeyA: Val1] -> [KeyB: Val2]
// Open Addressing (Linear Probing):
// Index 3 -> [KeyA: Val1]
// Index 4 -> [KeyB: Val2] (تم وضعه في الخانة التالية الشاغرة)' or l.common_mistakes is distinct from '["استخدام دالة تجزئة (Hash Function) رديئة توزع العناصر في فهارس متجاورة، مما يحول جدول التجزئة إلى قائمة خطية بطيئة O(N)."]'::jsonb or l.follow_up_questions is distinct from '["ما هي مشكلة التكتل الأولي (Primary Clustering) في أسلوب Linear Probing؟"]'::jsonb or l.sources is distinct from '[{"title":"Hash table - Wikipedia","url":"https://en.wikipedia.org/wiki/Hash_table"}]'::jsonb)) then raise exception 'Question fds-002 ar content changed; create a new revision before seeding'; end if; end $$;
