insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل الكوم الثنائي (Binary Heap) وكيف تمثله مصفوفة بسيطة بدون مؤشرات عقد مع عملية Heapify؟', 'الكوم الثنائي هو شجرة ثنائية شبه مكتملة تحقق خاصية الكوم (العنصر الأب أصغر من أبنائه في Min-Heap أو أكبر في Max-Heap)، ويُمثل بكفاءة في مصفوفة حيث أبناء العنصر عند المؤشر i يقعان عند 2i+1 و 2i+2.', 'لأن الشجرة مكتملة دائماً، لا نحتاج لتخزين مؤشرات pointers في الذاكرة؛ فالأب عند index يمتلك ابنه الأيسر عند 2*i + 1 والأيمن عند 2*i + 2، والأب عند floor((i-1)/2). تتيح عملية Heapify تحويل مصفوفة عشوائية إلى Heap في زمن خطي مدهش O(N) بدلاً من O(N log N) عبر بناء المستويات من الأسفل للأعلى، بينما يستغرق استخراج القمة O(log N).', '// تمثيل المصفوفة: [Min, Child1, Child2, Grandchild1, ...]
// Left child = 2*i + 1
// Right child = 2*i + 2
// Parent = (i - 1) / 2', '["الخلط بين شجرة البحث الثنائية (BST) والكوم الثنائي (Binary Heap)؛ الـ Heap لا يرتب الأبناء الأيسر والأيمن بالنسبة لبعضهما بل بالنسبة للأب فقط."]'::jsonb, '["لماذا تستغرق خوارزمية Heapify على مصفوفة كاملة زمناً قدره O(N) رياضياً وليس O(N log N)؟"]'::jsonb, '[{"title":"Binary heap - Wikipedia","url":"https://en.wikipedia.org/wiki/Binary_heap"}]'::jsonb from public.question_revisions r where r.question_id = 'fds-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fds-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل الكوم الثنائي (Binary Heap) وكيف تمثله مصفوفة بسيطة بدون مؤشرات عقد مع عملية Heapify؟' or l.short_answer is distinct from 'الكوم الثنائي هو شجرة ثنائية شبه مكتملة تحقق خاصية الكوم (العنصر الأب أصغر من أبنائه في Min-Heap أو أكبر في Max-Heap)، ويُمثل بكفاءة في مصفوفة حيث أبناء العنصر عند المؤشر i يقعان عند 2i+1 و 2i+2.' or l.explanation is distinct from 'لأن الشجرة مكتملة دائماً، لا نحتاج لتخزين مؤشرات pointers في الذاكرة؛ فالأب عند index يمتلك ابنه الأيسر عند 2*i + 1 والأيمن عند 2*i + 2، والأب عند floor((i-1)/2). تتيح عملية Heapify تحويل مصفوفة عشوائية إلى Heap في زمن خطي مدهش O(N) بدلاً من O(N log N) عبر بناء المستويات من الأسفل للأعلى، بينما يستغرق استخراج القمة O(log N).' or l.code_example is distinct from '// تمثيل المصفوفة: [Min, Child1, Child2, Grandchild1, ...]
// Left child = 2*i + 1
// Right child = 2*i + 2
// Parent = (i - 1) / 2' or l.common_mistakes is distinct from '["الخلط بين شجرة البحث الثنائية (BST) والكوم الثنائي (Binary Heap)؛ الـ Heap لا يرتب الأبناء الأيسر والأيمن بالنسبة لبعضهما بل بالنسبة للأب فقط."]'::jsonb or l.follow_up_questions is distinct from '["لماذا تستغرق خوارزمية Heapify على مصفوفة كاملة زمناً قدره O(N) رياضياً وليس O(N log N)؟"]'::jsonb or l.sources is distinct from '[{"title":"Binary heap - Wikipedia","url":"https://en.wikipedia.org/wiki/Binary_heap"}]'::jsonb)) then raise exception 'Question fds-005 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Data Structures Heaps Priority Queues Heapify?', 'This question checks the core Data Structures Heaps Priority Queues Heapify concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Data Structures Heaps Priority Queues Heapify with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// تمثيل المصفوفة: [Min, Child1, Child2, Grandchild1, ...]
