insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين مصفوفة التجاور (Adjacency Matrix) وقائمة التجاور (Adjacency List) في تمثيل الرسوم البيانية (Graphs)؟', 'مصفوفة التجاور تستخدم شبكة ثنائية الأبعاد V×V ممتازة للرسوم الكثيفة وتوفر فحص وجود ضلع بـ O(1)، بينما قائمة التجاور تخزن جيران كل رأس في قائمة موفرة للذاكرة O(V + E) ومثالية للرسوم المتناثرة.', 'في معظم التطبيقات العملية (كالشبكات الاجتماعية وشبكات الطرق)، تكون الرسوم متناثرة (Sparse Graphs) حيث عدد الأضلاع E أقل بكثير من V^2؛ لذلك تستهلك مصفوفة التجاور ذاكرة هائلة O(V^2) معظمها أصفار. قائمة التجاور تحتفظ فقط بالعلاقات الفعلية، مما يتيح التكرار السريع على الجيران في خوارزميات BFS و DFS بزمن O(V + E).', '// مصفوفة التجاور (Matrix):
//   A B C
// A 0 1 0
// B 1 0 1
// قائمة التجاور (List):
// A -> [B]
// B -> [A, C]', '["اختيار مصفوفة تجاور لرسم بياني يحتوي على 1,000,000 رأس، مما يتطلب مصفوفة بتريليون خانة وتتسبب فوراً في Out Of Memory."]'::jsonb, '["كيف تُمثل الأوزان والاتجاهات (Directed & Weighted Graphs) في كل من البنيتين؟"]'::jsonb, '[{"title":"Adjacency list - Wikipedia","url":"https://en.wikipedia.org/wiki/Adjacency_list"}]'::jsonb from public.question_revisions r where r.question_id = 'fds-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fds-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين مصفوفة التجاور (Adjacency Matrix) وقائمة التجاور (Adjacency List) في تمثيل الرسوم البيانية (Graphs)؟' or l.short_answer is distinct from 'مصفوفة التجاور تستخدم شبكة ثنائية الأبعاد V×V ممتازة للرسوم الكثيفة وتوفر فحص وجود ضلع بـ O(1)، بينما قائمة التجاور تخزن جيران كل رأس في قائمة موفرة للذاكرة O(V + E) ومثالية للرسوم المتناثرة.' or l.explanation is distinct from 'في معظم التطبيقات العملية (كالشبكات الاجتماعية وشبكات الطرق)، تكون الرسوم متناثرة (Sparse Graphs) حيث عدد الأضلاع E أقل بكثير من V^2؛ لذلك تستهلك مصفوفة التجاور ذاكرة هائلة O(V^2) معظمها أصفار. قائمة التجاور تحتفظ فقط بالعلاقات الفعلية، مما يتيح التكرار السريع على الجيران في خوارزميات BFS و DFS بزمن O(V + E).' or l.code_example is distinct from '// مصفوفة التجاور (Matrix):
//   A B C
// A 0 1 0
// B 1 0 1
// قائمة التجاور (List):
// A -> [B]
// B -> [A, C]' or l.common_mistakes is distinct from '["اختيار مصفوفة تجاور لرسم بياني يحتوي على 1,000,000 رأس، مما يتطلب مصفوفة بتريليون خانة وتتسبب فوراً في Out Of Memory."]'::jsonb or l.follow_up_questions is distinct from '["كيف تُمثل الأوزان والاتجاهات (Directed & Weighted Graphs) في كل من البنيتين؟"]'::jsonb or l.sources is distinct from '[{"title":"Adjacency list - Wikipedia","url":"https://en.wikipedia.org/wiki/Adjacency_list"}]'::jsonb)) then raise exception 'Question fds-006 ar content changed; create a new revision before seeding'; end if; end $$;
