insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم ذاكرة مؤقتة بنظام الأقل استخداماً مؤخراً (LRU Cache) تحقق عمليات Get و Put بزمن O(1) صارم؟', 'عبر دمج هيكلين للبيانات معاً: جدول تجزئة (Hash Map) للبحث الفوري O(1)، وقائمة مترابطة مزدوجة (Doubly Linked List) لتتبع ترتيب الاستخدام وإضافة وحذف العناصر في O(1).', 'يحتفظ الـ Hash Map بمفتاح العنصر وقيمة تشير مباشرة إلى عقدة في القائمة المترابطة المزدوجة. تحتوي القائمة على رأس وهمي (Head) وذيل وهمي (Tail). عند استدعاء get(key) أو تعديل قيمة، نحدد العقدة من الـ Map وننقلها إلى بداية القائمة (Most Recently Used). وعند امتلاء السعة واستدعاء put()، نقوم بحذف العقدة الموجودة قبل الذيل مباشرة (Least Recently Used) وحذفها من الـ Map في O(1) ثابت.', 'class LRUCache {
  private map = new Map<string, Node>();
  private head = new Node('''', 0);
  private tail = new Node('''', 0);
  // ربط Head بـ Tail والتحريك عند كل وصول
}', '["استخدام مصفوفة عادية وتحديث موقع العنصر عبر إزاحة بقية العناصر، مما يرفع كلفة التحديث إلى O(N) ويفقد الذاكرة المؤقتة سرعتها."]'::jsonb, '["ما الفرق بين سياسة الإخلاء LRU (Least Recently Used) وسياسة LFU (Least Frequently Used)؟"]'::jsonb, '[{"title":"LRU cache implementation - Wikipedia","url":"https://en.wikipedia.org/wiki/Cache_replacement_policies#LRU"}]'::jsonb from public.question_revisions r where r.question_id = 'fds-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fds-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم ذاكرة مؤقتة بنظام الأقل استخداماً مؤخراً (LRU Cache) تحقق عمليات Get و Put بزمن O(1) صارم؟' or l.short_answer is distinct from 'عبر دمج هيكلين للبيانات معاً: جدول تجزئة (Hash Map) للبحث الفوري O(1)، وقائمة مترابطة مزدوجة (Doubly Linked List) لتتبع ترتيب الاستخدام وإضافة وحذف العناصر في O(1).' or l.explanation is distinct from 'يحتفظ الـ Hash Map بمفتاح العنصر وقيمة تشير مباشرة إلى عقدة في القائمة المترابطة المزدوجة. تحتوي القائمة على رأس وهمي (Head) وذيل وهمي (Tail). عند استدعاء get(key) أو تعديل قيمة، نحدد العقدة من الـ Map وننقلها إلى بداية القائمة (Most Recently Used). وعند امتلاء السعة واستدعاء put()، نقوم بحذف العقدة الموجودة قبل الذيل مباشرة (Least Recently Used) وحذفها من الـ Map في O(1) ثابت.' or l.code_example is distinct from 'class LRUCache {
  private map = new Map<string, Node>();
  private head = new Node('''', 0);
  private tail = new Node('''', 0);
  // ربط Head بـ Tail والتحريك عند كل وصول
}' or l.common_mistakes is distinct from '["استخدام مصفوفة عادية وتحديث موقع العنصر عبر إزاحة بقية العناصر، مما يرفع كلفة التحديث إلى O(N) ويفقد الذاكرة المؤقتة سرعتها."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين سياسة الإخلاء LRU (Least Recently Used) وسياسة LFU (Least Frequently Used)؟"]'::jsonb or l.sources is distinct from '[{"title":"LRU cache implementation - Wikipedia","url":"https://en.wikipedia.org/wiki/Cache_replacement_policies#LRU"}]'::jsonb)) then raise exception 'Question fds-008 ar content changed; create a new revision before seeding'; end if; end $$;
