insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين ذاكرة المكدس (Stack Memory) وذاكرة الكومة (Heap Memory) في إدارة موارد البرنامج؟', 'الـ Stack هو مساحة ذاكرة خطية سريعة جداً تُدار تلقائياً بواسطة المعالج لتخزين المتغيرات المحلية وإطارات الدوال، بينما الـ Heap مساحة ديناميكية ضخمة لحجز كائنات متغيرة الحجم يديرها المبرمج أو جامع القمامة (GC).', 'يتحرك مؤشر الـ Stack بمجرد زيادة أو إنقاص سجل المؤشر (Stack Pointer) مع دخول وخروج الدوال؛ تخصيصها لحظي وتحريرها تلقائي ومحمي من التجزئة، لكن حجمها محدود وأي تجاوز يسبب Stack Overflow. أما الـ Heap فيتطلب البحث عن كتلة حرة وحجزها (malloc/new)، وهي أبطأ بكثير وعرضة لتجزئة الذاكرة (Memory Fragmentation) وتتطلب إدارة واعية لمنع تسريب الذاكرة.', '// المتغيرات المحلية الصغيرة على الـ Stack:
int count = 42;
// الكائنات الديناميكية على الـ Heap مع مؤشر محلي على الـ Stack:
User* user = new User(''Alice'');', '["الاعتقاد بأن لغات الـ Managed مثل Java و C# و JavaScript لا تستخدم الـ Stack؛ جميع اللغات تستخدم الـ Stack لإطارات الاستدعاء والمتغيرات الأولية."]'::jsonb, '["كيف يعمل تحليل الهروب (Escape Analysis) في المترجمات الحديثة لتخصيص الكائنات على الـ Stack بدلاً من الـ Heap؟"]'::jsonb, '[{"title":"Memory management - Wikipedia","url":"https://en.wikipedia.org/wiki/Memory_management"}]'::jsonb from public.question_revisions r where r.question_id = 'fds-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fds-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الجوهري بين ذاكرة المكدس (Stack Memory) وذاكرة الكومة (Heap Memory) في إدارة موارد البرنامج؟' or l.short_answer is distinct from 'الـ Stack هو مساحة ذاكرة خطية سريعة جداً تُدار تلقائياً بواسطة المعالج لتخزين المتغيرات المحلية وإطارات الدوال، بينما الـ Heap مساحة ديناميكية ضخمة لحجز كائنات متغيرة الحجم يديرها المبرمج أو جامع القمامة (GC).' or l.explanation is distinct from 'يتحرك مؤشر الـ Stack بمجرد زيادة أو إنقاص سجل المؤشر (Stack Pointer) مع دخول وخروج الدوال؛ تخصيصها لحظي وتحريرها تلقائي ومحمي من التجزئة، لكن حجمها محدود وأي تجاوز يسبب Stack Overflow. أما الـ Heap فيتطلب البحث عن كتلة حرة وحجزها (malloc/new)، وهي أبطأ بكثير وعرضة لتجزئة الذاكرة (Memory Fragmentation) وتتطلب إدارة واعية لمنع تسريب الذاكرة.' or l.code_example is distinct from '// المتغيرات المحلية الصغيرة على الـ Stack:
int count = 42;
// الكائنات الديناميكية على الـ Heap مع مؤشر محلي على الـ Stack:
