insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الفرق الدقيق بين ترميزات Big-O و Big-Omega و Big-Theta في تحليل تعقيد الخوارزميات؟', 'ترميز Big-O يمثل الحد الأعلى المقارب للنمو (السيناريو الأسوأ Worst Case)، و Big-Omega يمثل الحد الأدنى (السيناريو الأفضل Best Case)، و Big-Theta يمثل حداً محكماً يطابق سلوك الخوارزمية في جميع الحالات.', 'عندما نقول خوارزمية O(N^2)، فإننا نضمن رياضياً أن استهلاكها للوقت لن ينمو أسرع من ثابت مضروب في N^2 عندما تقترب المدخلات من اللانهاية. أما Big-Omega (Ω) فتحدد أقل زمن ممكن. وإذا كان أفضل وأسوأ سيناريو متطابقين في معدل النمو (مثل MergeSort التي تأخذ N log N في كل الأحوال)، فنصفها بأنها Θ(N log N). يركز مهندسو البرمجيات على Big-O لضمان عدم انهيار النظام تحت الحمل الأقصى.', '// تحليل التعقيد:
// O(1) < O(log N) < O(N) < O(N log N) < O(N^2) < O(2^N) < O(N!)', '["إهمال تعقيد الذاكرة والمساحة (Space Complexity) والتركيز فقط على تعقيد الوقت (Time Complexity)."]'::jsonb, '["لماذا نتجاهل الثوابت الرياضية (Constants) والحدود الدنيا في تحليل Big-O للأنظمة الكبيرة؟"]'::jsonb, '[{"title":"Big O notation - Wikipedia","url":"https://en.wikipedia.org/wiki/Big_O_notation"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'falg-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الفرق الدقيق بين ترميزات Big-O و Big-Omega و Big-Theta في تحليل تعقيد الخوارزميات؟' or l.short_answer is distinct from 'ترميز Big-O يمثل الحد الأعلى المقارب للنمو (السيناريو الأسوأ Worst Case)، و Big-Omega يمثل الحد الأدنى (السيناريو الأفضل Best Case)، و Big-Theta يمثل حداً محكماً يطابق سلوك الخوارزمية في جميع الحالات.' or l.explanation is distinct from 'عندما نقول خوارزمية O(N^2)، فإننا نضمن رياضياً أن استهلاكها للوقت لن ينمو أسرع من ثابت مضروب في N^2 عندما تقترب المدخلات من اللانهاية. أما Big-Omega (Ω) فتحدد أقل زمن ممكن. وإذا كان أفضل وأسوأ سيناريو متطابقين في معدل النمو (مثل MergeSort التي تأخذ N log N في كل الأحوال)، فنصفها بأنها Θ(N log N). يركز مهندسو البرمجيات على Big-O لضمان عدم انهيار النظام تحت الحمل الأقصى.' or l.code_example is distinct from '// تحليل التعقيد:
// O(1) < O(log N) < O(N) < O(N log N) < O(N^2) < O(2^N) < O(N!)' or l.common_mistakes is distinct from '["إهمال تعقيد الذاكرة والمساحة (Space Complexity) والتركيز فقط على تعقيد الوقت (Time Complexity)."]'::jsonb or l.follow_up_questions is distinct from '["لماذا نتجاهل الثوابت الرياضية (Constants) والحدود الدنيا في تحليل Big-O للأنظمة الكبيرة؟"]'::jsonb or l.sources is distinct from '[{"title":"Big O notation - Wikipedia","url":"https://en.wikipedia.org/wiki/Big_O_notation"}]'::jsonb)) then raise exception 'Question falg-001 ar content changed; create a new revision before seeding'; end if; end $$;
