insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين خوارزميتي QuickSort و MergeSort من حيث التعقيد المكاني، استقرار الترتيب (Stability)، وأسوأ سيناريو؟', 'ترتيب MergeSort مستقر (Stable) ويضمن دائماً O(N log N) لكنه يستهلك ذاكرة إضافية O(N)، بينما QuickSort يرتب في نفس المكان (In-place O(1) auxiliary space) وأسرع عملياً لكنه غير مستقر وأسوأ سيناريو له O(N^2).', 'الترتيب المستقر (Stable Sort) يحافظ على الترتيب النسبي للعناصر المتساوية في القيمة، وهو أمر حيوي عند الترتيب المتعدد (مثل ترتيب الطلاب حسب الاسم ثم حسب الدرجة). في خوارزمية QuickSort، إذا تم اختيار Pivot سيئ دائماً (مثل اختيار أول عنصر في مصفوفة مرتبة مسبقاً)، يتدهور التقسيم إلى O(N^2). تعالج الخوارزميات الحديثة ذلك بـ Randomized QuickSort أو هجين IntroSort المستخدم في C++ std::sort.', '// MergeSort: يقسم المصفوفة إلى نصفين ويدمجهما بذاكرة إضافية
// QuickSort: يختار Pivot ويقسم العناصر حوله في نفس المكان', '["استخدام QuickSort الكلاسيكي دون اختيار عشوائي للـ Pivot على بيانات مرتبة جزئياً، مما يسبب بطئاً شديداً."]'::jsonb, '["كيف تعمل خوارزمية TimSort الهجينة المستخدمة في Python و Java لترتيب البيانات الحقيقية بسرعة قياسية؟"]'::jsonb, '[{"title":"Quicksort - Wikipedia","url":"https://en.wikipedia.org/wiki/Quicksort"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'falg-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين خوارزميتي QuickSort و MergeSort من حيث التعقيد المكاني، استقرار الترتيب (Stability)، وأسوأ سيناريو؟' or l.short_answer is distinct from 'ترتيب MergeSort مستقر (Stable) ويضمن دائماً O(N log N) لكنه يستهلك ذاكرة إضافية O(N)، بينما QuickSort يرتب في نفس المكان (In-place O(1) auxiliary space) وأسرع عملياً لكنه غير مستقر وأسوأ سيناريو له O(N^2).' or l.explanation is distinct from 'الترتيب المستقر (Stable Sort) يحافظ على الترتيب النسبي للعناصر المتساوية في القيمة، وهو أمر حيوي عند الترتيب المتعدد (مثل ترتيب الطلاب حسب الاسم ثم حسب الدرجة). في خوارزمية QuickSort، إذا تم اختيار Pivot سيئ دائماً (مثل اختيار أول عنصر في مصفوفة مرتبة مسبقاً)، يتدهور التقسيم إلى O(N^2). تعالج الخوارزميات الحديثة ذلك بـ Randomized QuickSort أو هجين IntroSort المستخدم في C++ std::sort.' or l.code_example is distinct from '// MergeSort: يقسم المصفوفة إلى نصفين ويدمجهما بذاكرة إضافية
// QuickSort: يختار Pivot ويقسم العناصر حوله في نفس المكان' or l.common_mistakes is distinct from '["استخدام QuickSort الكلاسيكي دون اختيار عشوائي للـ Pivot على بيانات مرتبة جزئياً، مما يسبب بطئاً شديداً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل خوارزمية TimSort الهجينة المستخدمة في Python و Java لترتيب البيانات الحقيقية بسرعة قياسية؟"]'::jsonb or l.sources is distinct from '[{"title":"Quicksort - Wikipedia","url":"https://en.wikipedia.org/wiki/Quicksort"}]'::jsonb)) then raise exception 'Question falg-002 ar content changed; create a new revision before seeding'; end if; end $$;
