insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل خوارزمية البحث الثنائي (Binary Search) وما هي الحيل الرياضية لتفادي مشكلة Integer Overflow؟', 'تعمل على مصفوفة مرتبة مسبقاً بتقسيم نطاق البحث إلى النصف في كل خطوة بزمن O(log N)، ولتفادي طفحان الأعداد الصحيحة يُحسب المنتصف عبر low + (high - low) / 2 بدلاً من (low + high) / 2.', 'إذا كانت قيمتا low و high قريبتين من الحد الأقصى للأعداد الصحيحة (مثل 2^31 - 1)، فإن جمعهما (low + high) يسبب طفحاناً عددياً (Integer Overflow) يتحول إلى رقم سالب في لغات مثل Java و C++، مما يؤدي لرمي ArrayIndexOutOfBoundsException. يمكن أيضاً تطبيق البحث الثنائي ليس فقط على مصفوفات الأرقام، بل على فضاءات الإجابات المستمرة (Binary Search on Answer Space) لحل مسائل التحسين والحد الأدنى للحد الأقصى.', 'function binarySearch(arr: number[], target: number): number {
  let low = 0, high = arr.length - 1;
  while (low <= high) {
    const mid = low + Math.floor((high - low) / 2); // آمن من الـ Overflow
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}', '["تطبيق البحث الثنائي على مصفوفة غير مرتبة وتوقع نتائج صحيحة."]'::jsonb, '["كيف تختلف خوارزميتا Lower Bound و Upper Bound عند البحث عن أول أو آخر ظهور لعنصر مكرر؟"]'::jsonb, '[{"title":"Binary search algorithm - Wikipedia","url":"https://en.wikipedia.org/wiki/Binary_search_algorithm"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'falg-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل خوارزمية البحث الثنائي (Binary Search) وما هي الحيل الرياضية لتفادي مشكلة Integer Overflow؟' or l.short_answer is distinct from 'تعمل على مصفوفة مرتبة مسبقاً بتقسيم نطاق البحث إلى النصف في كل خطوة بزمن O(log N)، ولتفادي طفحان الأعداد الصحيحة يُحسب المنتصف عبر low + (high - low) / 2 بدلاً من (low + high) / 2.' or l.explanation is distinct from 'إذا كانت قيمتا low و high قريبتين من الحد الأقصى للأعداد الصحيحة (مثل 2^31 - 1)، فإن جمعهما (low + high) يسبب طفحاناً عددياً (Integer Overflow) يتحول إلى رقم سالب في لغات مثل Java و C++، مما يؤدي لرمي ArrayIndexOutOfBoundsException. يمكن أيضاً تطبيق البحث الثنائي ليس فقط على مصفوفات الأرقام، بل على فضاءات الإجابات المستمرة (Binary Search on Answer Space) لحل مسائل التحسين والحد الأدنى للحد الأقصى.' or l.code_example is distinct from 'function binarySearch(arr: number[], target: number): number {
  let low = 0, high = arr.length - 1;
  while (low <= high) {
    const mid = low + Math.floor((high - low) / 2); // آمن من الـ Overflow
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}' or l.common_mistakes is distinct from '["تطبيق البحث الثنائي على مصفوفة غير مرتبة وتوقع نتائج صحيحة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تختلف خوارزميتا Lower Bound و Upper Bound عند البحث عن أول أو آخر ظهور لعنصر مكرر؟"]'::jsonb or l.sources is distinct from '[{"title":"Binary search algorithm - Wikipedia","url":"https://en.wikipedia.org/wiki/Binary_search_algorithm"}]'::jsonb)) then raise exception 'Question falg-003 ar content changed; create a new revision before seeding'; end if; end $$;
