insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين البحث بالعرض (BFS) والبحث بالعمق (DFS) في استكشاف الرسوم البيانية ومتى تختار كلاً منهما؟', 'يستكشف BFS الجيران مستوى بمستوى باستخدام طابور (Queue) وهو مثالي لإيجاد أقصر مسار في الرسوم غير الموزونة، بينما يتعمق DFS لأقصى مسار ممكن باستخدام مكدس (Stack/Recursion) ومثالي لاكتشاف الدورات والمطابقة الطوبولوجية.', 'يضمن BFS زيارة كافة العقد الواقعة على بُعد خطوة واحدة أولاً، ثم خطوتين، مما يجعله الخوارزمي الأسرع لإيجاد أقصر مسار في شبكات التواصل ومسارات المتاهات غير الموزونة، لكنه يستهلك ذاكرة أكبر لحفظ طبقة الجيران O(W). بينما يتعمق DFS مستكشفاً فرعاً حتى آخره، مما يجعله ممتازاً لحل مسائل المتاهات الكاملة، الترتيب الطوبولوجي (Topological Sort)، كشف الدورات (Cycle Detection)، وحساب المكونات المتصلة بقوة (Strongly Connected Components).', '// BFS: يستخدم Queue
const queue = [startNode];
// DFS: يستخدم Stack أو استدعاء ذاتي Recursion
function dfs(node) { visited.add(node); for (const n of node.neighbors) dfs(n); }', '["نسيان تسجيل العقد التي تمت زيارتها في Set أو مصفوفة visited، مما يسبب دوراناً لا نهائياً (Infinite Loop) في الرسوم التي تحتوي على دورات."]'::jsonb, '["كيف تختلف مساحة الذاكرة المستهلكة بين BFS و DFS في شجرة متوازنة ذات عمق كبير وتفرع عريض؟"]'::jsonb, '[{"title":"Breadth-first search - Wikipedia","url":"https://en.wikipedia.org/wiki/Breadth-first_search"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'falg-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين البحث بالعرض (BFS) والبحث بالعمق (DFS) في استكشاف الرسوم البيانية ومتى تختار كلاً منهما؟' or l.short_answer is distinct from 'يستكشف BFS الجيران مستوى بمستوى باستخدام طابور (Queue) وهو مثالي لإيجاد أقصر مسار في الرسوم غير الموزونة، بينما يتعمق DFS لأقصى مسار ممكن باستخدام مكدس (Stack/Recursion) ومثالي لاكتشاف الدورات والمطابقة الطوبولوجية.' or l.explanation is distinct from 'يضمن BFS زيارة كافة العقد الواقعة على بُعد خطوة واحدة أولاً، ثم خطوتين، مما يجعله الخوارزمي الأسرع لإيجاد أقصر مسار في شبكات التواصل ومسارات المتاهات غير الموزونة، لكنه يستهلك ذاكرة أكبر لحفظ طبقة الجيران O(W). بينما يتعمق DFS مستكشفاً فرعاً حتى آخره، مما يجعله ممتازاً لحل مسائل المتاهات الكاملة، الترتيب الطوبولوجي (Topological Sort)، كشف الدورات (Cycle Detection)، وحساب المكونات المتصلة بقوة (Strongly Connected Components).' or l.code_example is distinct from '// BFS: يستخدم Queue
const queue = [startNode];
// DFS: يستخدم Stack أو استدعاء ذاتي Recursion
function dfs(node) { visited.add(node); for (const n of node.neighbors) dfs(n); }' or l.common_mistakes is distinct from '["نسيان تسجيل العقد التي تمت زيارتها في Set أو مصفوفة visited، مما يسبب دوراناً لا نهائياً (Infinite Loop) في الرسوم التي تحتوي على دورات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تختلف مساحة الذاكرة المستهلكة بين BFS و DFS في شجرة متوازنة ذات عمق كبير وتفرع عريض؟"]'::jsonb or l.sources is distinct from '[{"title":"Breadth-first search - Wikipedia","url":"https://en.wikipedia.org/wiki/Breadth-first_search"}]'::jsonb)) then raise exception 'Question falg-004 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Algorithms Bfs Vs Dfs Applications?', 'This question checks the core Algorithms Bfs Vs Dfs Applications concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Algorithms Bfs Vs Dfs Applications with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// BFS: يستخدم Queue
