insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحول تقنيتا المؤشرين (Two Pointers) والنافذة المنزلقة (Sliding Window) المسائل التربيعية O(N^2) إلى خطية O(N)؟', 'عبر الاحتفاظ بمؤشرين يتحركان في اتجاه محدد بدلاً من فحص كل الأزواج الممكنة بحلقتين متداخلتين، مما يضمن زيارة كل عنصر عدداً ثابتاً من المرات.', 'في تقنية Two Pointers (مثل مسألة Two Sum على مصفوفة مرتبة)، نضع مؤشراً في البداية والآخر في النهاية، فإذا كان المجموع صغيراً نحرك الأيسر للأمام، وإذا كان كبيراً نحرك الأيمن للخلف بزمن O(N). وفي Sliding Window (مثل إيجاد أطول سلسلة فرعية بدون تكرار)، نوسع النافذة بزيادة المؤشر الأيمن، وعند اختراق الشرط نقوم بتقليصها بزيادة المؤشر الأيسر، محافظين على فحص النطاق المتحرك بزمن خطي ثابت.', 'let left = 0;
for (let right = 0; right < s.length; right++) {
  // توسيع النافذة
  while (windowConditionBroken()) {
    // تقليص النافذة من اليسار
    left++;
  }
  maxLength = Math.max(maxLength, right - left + 1);
}', '["محاولة استخدام Two Pointers على مصفوفة غير مرتبة لمسائل الأرقام، مما يقود لقرارات توجيه خاطئة."]'::jsonb, '["ما الفرق بين النافذة المنزلقة ذات الحجم الثابت (Fixed-size) والنافذة ذات الحجم الديناميكي (Variable-size)؟"]'::jsonb, '[{"title":"Sliding window protocol and algorithms","url":"https://en.wikipedia.org/wiki/Sliding_window_protocol"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'falg-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تحول تقنيتا المؤشرين (Two Pointers) والنافذة المنزلقة (Sliding Window) المسائل التربيعية O(N^2) إلى خطية O(N)؟' or l.short_answer is distinct from 'عبر الاحتفاظ بمؤشرين يتحركان في اتجاه محدد بدلاً من فحص كل الأزواج الممكنة بحلقتين متداخلتين، مما يضمن زيارة كل عنصر عدداً ثابتاً من المرات.' or l.explanation is distinct from 'في تقنية Two Pointers (مثل مسألة Two Sum على مصفوفة مرتبة)، نضع مؤشراً في البداية والآخر في النهاية، فإذا كان المجموع صغيراً نحرك الأيسر للأمام، وإذا كان كبيراً نحرك الأيمن للخلف بزمن O(N). وفي Sliding Window (مثل إيجاد أطول سلسلة فرعية بدون تكرار)، نوسع النافذة بزيادة المؤشر الأيمن، وعند اختراق الشرط نقوم بتقليصها بزيادة المؤشر الأيسر، محافظين على فحص النطاق المتحرك بزمن خطي ثابت.' or l.code_example is distinct from 'let left = 0;
for (let right = 0; right < s.length; right++) {
  // توسيع النافذة
  while (windowConditionBroken()) {
    // تقليص النافذة من اليسار
    left++;
  }
  maxLength = Math.max(maxLength, right - left + 1);
}' or l.common_mistakes is distinct from '["محاولة استخدام Two Pointers على مصفوفة غير مرتبة لمسائل الأرقام، مما يقود لقرارات توجيه خاطئة."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين النافذة المنزلقة ذات الحجم الثابت (Fixed-size) والنافذة ذات الحجم الديناميكي (Variable-size)؟"]'::jsonb or l.sources is distinct from '[{"title":"Sliding window protocol and algorithms","url":"https://en.wikipedia.org/wiki/Sliding_window_protocol"}]'::jsonb)) then raise exception 'Question falg-006 ar content changed; create a new revision before seeding'; end if; end $$;
