insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي خاصية الاختيار الجشع (Greedy Choice Property) ولماذا تنجح الخوارزميات الجشعة في Fractional Knapsack وتفشل في 0/1 Knapsack؟', 'خاصية الاختيار الجشع تعني أن اختيار أفضل حل محلي لحظي يقود بالضرورة للحل الأمثل الشامل، وتنجح عند إمكانية تجزئة العناصر وتفشل عند اشتراط أخذ العنصر كاملاً أو تركه.', 'في مسألة Fractional Knapsack، يمكننا ترتيب العناصر حسب النسبة بين القيمة والوزن (Value/Weight Ratio) واختيار أعلى نسبة دائماً وأخذ أجزاء كسرية من العنصر الأخير، محققين الحل الأمثل بـ O(N log N). لكن في 0/1 Knapsack، قد يؤدي اختيار عنصر ذي كثافة قيمة عالية إلى إشغال مساحة تمنع وضع عنصرين آخرين مجموعهما أفضل، مما يجعل الأسلوب الجشع قاصراً ويجبرنا على اللجوء للبرمجة الديناميكية.', '// الأسلوب الجشع يختار الأفضل فوراً دون ندم أو تراجع:
items.sort((a, b) => (b.value / b.weight) - (a.value / a.weight));', '["الافتراض بأن الحل الجشع صحيح دائماً بمجرد أنه يبدو منطقياً وبديهياً، دون إثبات رياضي لصحة الاختيار."]'::jsonb, '["كيف تبرهن خوارزميات شهيرة مثل Kruskal و Prim لحساب شجرة الامتداد الصغرى (MST) صحة خياراتها الجشعة؟"]'::jsonb, '[{"title":"Greedy algorithm - Wikipedia","url":"https://en.wikipedia.org/wiki/Greedy_algorithm"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
