insert into public.interview_questions (id, slug, track_id, difficulty) values ('falg-009', 'algorithms-backtracking-pruning-n-queens', 'fundamentals', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('falg-009', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل خوارزميات التراجع (Backtracking) وما هو دور التقليم (Pruning) في استكشاف شجرة فضاء الحالات لمسألة N-Queens؟', 'يقوم Backtracking ببناء الحل تدريجياً، وبمجرد اكتشاف أن المسار الحالي ينتهك الشروط، يتراجع خطوة للوراء (Backtracks)؛ ويقوم التقليم (Pruning) بإلغاء فروع الشجرة المستحيلة مسبقاً لتوفير الوقت.', 'في مسألة N-Queens، بدلاً من تجربة كافة التباديل البالغة N^N بأسلوب القوة الغاشمة (Brute Force)، نضع ملكة في الصف الأول، ثم نبحث في الصف التالي عن عمود غير مهدد. إذا وجدنا أن وضع الملكة في خانة معينة يهدد قطرياً أو عمودياً، نقوم بالتقليم (Pruning) ونتجاهل استكشاف كل الصفوف اللاحقة المتفرعة من هذا الموضع، ونعود للوراء لتغيير موقع الملكة السابقة. هذا يقلص فضاء البحث من أرقام فلكية إلى بضعة آلاف خطوة.', 'function solve(row) {
  if (row === N) { result.push([...board]); return; }
  for (let col = 0; col < N; col++) {
    if (isValid(row, col)) {
      placeQueen(row, col);
      solve(row + 1); // تعمق
      removeQueen(row, col); // تراجع (Backtrack)
    }
  }
}', '["نسيان عكس التغييرات واستعادة حالة المتغيرات عند الرجوع من الاستدعاء الذاتي (Undo State)."]'::jsonb, '["كيف تحل تقنية التقليم ذاتها مسائل خوارزمية Sudoku ومسألة توليد المجموعات الجزئية (Subsets)؟"]'::jsonb, '[{"title":"Backtracking - Wikipedia","url":"https://en.wikipedia.org/wiki/Backtracking"}]'::jsonb from public.question_revisions r where r.question_id = 'falg-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'falg-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل خوارزميات التراجع (Backtracking) وما هو دور التقليم (Pruning) في استكشاف شجرة فضاء الحالات لمسألة N-Queens؟' or l.short_answer is distinct from 'يقوم Backtracking ببناء الحل تدريجياً، وبمجرد اكتشاف أن المسار الحالي ينتهك الشروط، يتراجع خطوة للوراء (Backtracks)؛ ويقوم التقليم (Pruning) بإلغاء فروع الشجرة المستحيلة مسبقاً لتوفير الوقت.' or l.explanation is distinct from 'في مسألة N-Queens، بدلاً من تجربة كافة التباديل البالغة N^N بأسلوب القوة الغاشمة (Brute Force)، نضع ملكة في الصف الأول، ثم نبحث في الصف التالي عن عمود غير مهدد. إذا وجدنا أن وضع الملكة في خانة معينة يهدد قطرياً أو عمودياً، نقوم بالتقليم (Pruning) ونتجاهل استكشاف كل الصفوف اللاحقة المتفرعة من هذا الموضع، ونعود للوراء لتغيير موقع الملكة السابقة. هذا يقلص فضاء البحث من أرقام فلكية إلى بضعة آلاف خطوة.' or l.code_example is distinct from 'function solve(row) {
  if (row === N) { result.push([...board]); return; }
  for (let col = 0; col < N; col++) {
    if (isValid(row, col)) {
      placeQueen(row, col);
      solve(row + 1); // تعمق
      removeQueen(row, col); // تراجع (Backtrack)
    }
  }
}' or l.common_mistakes is distinct from '["نسيان عكس التغييرات واستعادة حالة المتغيرات عند الرجوع من الاستدعاء الذاتي (Undo State)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحل تقنية التقليم ذاتها مسائل خوارزمية Sudoku ومسألة توليد المجموعات الجزئية (Subsets)؟"]'::jsonb or l.sources is distinct from '[{"title":"Backtracking - Wikipedia","url":"https://en.wikipedia.org/wiki/Backtracking"}]'::jsonb)) then raise exception 'Question falg-009 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Algorithms Backtracking Pruning N Queens?', 'This question checks the core Algorithms Backtracking Pruning N Queens concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Algorithms Backtracking Pruning N Queens with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', 'function solve(row) {
  if (row === N) { result.push([...board]); return; }
