insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي حالة السباق (Race Condition) وما هو القسم الحرج (Critical Section) في البرمجة المتزامنة؟', 'القسم الحرج هو جزء الشفرة الذي يصل إلى مورد مشترك قابل للتعديل، وحالة السباق تحدث عندما تتنافس خيوط متعددة للوصول والتعديل على هذا المورد في نفس الوقت دون تزامن مناسب.', 'المثال الكلاسيكي هو عملية count++ البسيطة؛ على مستوى لغة الآلة تتكون من 3 تعليمات: (1) قراءة القيمة من الذاكرة إلى السجل (Read). (2) إضافة واحد (Increment). (3) كتابة القيمة في الذاكرة (Write). إذا دخل خيطان في نفس الوقت، قد يقرأ كلاهما القيمة 5 معاً، ويحسبان 6، ويكتبان 6 في الذاكرة بدلاً من 7! هذا الفقدان العشوائي للبيانات يمثل حالة سباق كارثية.', '// كود غير آمن متعدد الخيوط:
int counter = 0;
void increment() {
  counter++; // غير ذرية (Not Atomic) وتسبب Race Condition
}', '["الاعتقاد بأن سطراً واحداً من الكود (مثل x++) هو عملية ذرية آمنة في بيئة متعددة الخيوط."]'::jsonb, '["كيف تساعد أدوات ThreadSanitizer في اكتشاف حالات السباق الخفية أثناء تشغيل الاختبارات؟"]'::jsonb, '[{"title":"Race condition - Wikipedia","url":"https://en.wikipedia.org/wiki/Race_condition"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي حالة السباق (Race Condition) وما هو القسم الحرج (Critical Section) في البرمجة المتزامنة؟' or l.short_answer is distinct from 'القسم الحرج هو جزء الشفرة الذي يصل إلى مورد مشترك قابل للتعديل، وحالة السباق تحدث عندما تتنافس خيوط متعددة للوصول والتعديل على هذا المورد في نفس الوقت دون تزامن مناسب.' or l.explanation is distinct from 'المثال الكلاسيكي هو عملية count++ البسيطة؛ على مستوى لغة الآلة تتكون من 3 تعليمات: (1) قراءة القيمة من الذاكرة إلى السجل (Read). (2) إضافة واحد (Increment). (3) كتابة القيمة في الذاكرة (Write). إذا دخل خيطان في نفس الوقت، قد يقرأ كلاهما القيمة 5 معاً، ويحسبان 6، ويكتبان 6 في الذاكرة بدلاً من 7! هذا الفقدان العشوائي للبيانات يمثل حالة سباق كارثية.' or l.code_example is distinct from '// كود غير آمن متعدد الخيوط:
