insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين أدوات المزامنة: Mutex و Semaphore و Spinlock و Read-Write Lock ومتى تختار كلاً منها؟', 'الـ Mutex قفل متبادل يملكه خيط واحد فقط، والـ Semaphore إشارة تسمح بعدد N من الخيوط المتزامنة، والـ Spinlock يدور في حلقة مشغولة دون تعليق الخيط، والـ ReadWrite Lock يسمح بقراء متعددين أو كاتب واحد فقط.', 'إذا كان القسم الحرج قصيراً للغاية (بضعة تعليمات نانوثانية)، فإن الـ Spinlock ممتاز لأنه يتجنب كلفة التبديل السياقي لوضع الخيط في النوم وإيقاظه. وإذا كان لديك مورد مقيد (مثل حوض اتصالات قاعدة بيانات يستوعب 10 اتصالات)، فالـ Counting Semaphore هو الحل الأمثل. وإذا كان الكود يقرأ البيانات آلاف المرات ويكتب نادراً، فالـ Reader-Writer Lock يضاعف سرعة الأداء بالسماح بالقراءة المتزامنة دون أي حجب حتى يأتي كاتب جديد.', '// Mutex: حصر متبادل لخيط واحد
mutex.lock();
try { criticalWork(); } finally { mutex.unlock(); }

// Semaphore: يسمح لـ 5 خيوط كحد أقصى بالتزامن
semaphore.acquire();
service();
semaphore.release();', '["استخدام Spinlock في نظام أحادي النواة (Single Core)، مما يسبب تجميد المعالج بالكامل في حلقة دوران بلا فائدة."]'::jsonb, '["ما هو القفل التكراري (Reentrant Lock / Recursive Mutex) ومتى تحتاجه الدالة لتفادي إقفال نفسها؟"]'::jsonb, '[{"title":"Lock (computer science) - Wikipedia","url":"https://en.wikipedia.org/wiki/Lock_(computer_science)"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين أدوات المزامنة: Mutex و Semaphore و Spinlock و Read-Write Lock ومتى تختار كلاً منها؟' or l.short_answer is distinct from 'الـ Mutex قفل متبادل يملكه خيط واحد فقط، والـ Semaphore إشارة تسمح بعدد N من الخيوط المتزامنة، والـ Spinlock يدور في حلقة مشغولة دون تعليق الخيط، والـ ReadWrite Lock يسمح بقراء متعددين أو كاتب واحد فقط.' or l.explanation is distinct from 'إذا كان القسم الحرج قصيراً للغاية (بضعة تعليمات نانوثانية)، فإن الـ Spinlock ممتاز لأنه يتجنب كلفة التبديل السياقي لوضع الخيط في النوم وإيقاظه. وإذا كان لديك مورد مقيد (مثل حوض اتصالات قاعدة بيانات يستوعب 10 اتصالات)، فالـ Counting Semaphore هو الحل الأمثل. وإذا كان الكود يقرأ البيانات آلاف المرات ويكتب نادراً، فالـ Reader-Writer Lock يضاعف سرعة الأداء بالسماح بالقراءة المتزامنة دون أي حجب حتى يأتي كاتب جديد.' or l.code_example is distinct from '// Mutex: حصر متبادل لخيط واحد
mutex.lock();
try { criticalWork(); } finally { mutex.unlock(); }

// Semaphore: يسمح لـ 5 خيوط كحد أقصى بالتزامن
semaphore.acquire();
service();
semaphore.release();' or l.common_mistakes is distinct from '["استخدام Spinlock في نظام أحادي النواة (Single Core)، مما يسبب تجميد المعالج بالكامل في حلقة دوران بلا فائدة."]'::jsonb or l.follow_up_questions is distinct from '["ما هو القفل التكراري (Reentrant Lock / Recursive Mutex) ومتى تحتاجه الدالة لتفادي إقفال نفسها؟"]'::jsonb or l.sources is distinct from '[{"title":"Lock (computer science) - Wikipedia","url":"https://en.wikipedia.org/wiki/Lock_(computer_science)"}]'::jsonb)) then raise exception 'Question fcnc-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Concurrency Mutex Semaphore Spinlock Readwrite?', 'This question checks the core Concurrency Mutex Semaphore Spinlock Readwrite concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Concurrency Mutex Semaphore Spinlock Readwrite with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// Mutex: حصر متبادل لخيط واحد
