insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي شروط كوفمان الأربعة (Coffman Conditions) لحدوث الجمود (Deadlock) وكيف تكسر أحدها لحل المشكلة؟', 'شروط الجمود الأربعة هي: (1) الحصر المتبادل (Mutual Exclusion). (2) التعليق والانتظار (Hold and Wait). (3) عدم انتزاع القفل قسراً (No Preemption). (4) الانتظار الدائري (Circular Wait). وكسر أي شرط منها يمنع الجمود نهائياً.', 'يحدث الجمود الكلاسيكي عندما يمسك الخيط 1 بالقفل A وينتظر القفل B، بينما يمسك الخيط 2 بالقفل B وينتظر القفل A؛ يتوقف النظام للأبد. أسهل وأقوى استراتيجية هندسية لكسر الجمود هي كسر شرط الانتظار الدائري عبر فرض ترتيب صارم لاكتساب الأقفال (Lock Ordering): يجب على جميع خيوط النظام دائماً حجز القفل A قبل القفل B وفقاً لترتيب هرمي ثابت وموحد.', '// كسر الجمود بفرض ترتيب القفل عالمياً:
void transfer(Account from, Account to) {
  Account first = from.id < to.id ? from : to;
  Account second = from.id < to.id ? to : from;
  synchronized(first) {
    synchronized(second) {
      // مستحيل حدوث Deadlock لأن الترتيب موحد لكل العمليات!
    }
  }
}', '["محاولة حل الجمود بإضافة تأخير زمني عشوائي Thread.sleep() بدلاً من معالجة ترتيب الأقفال بنيوياً."]'::jsonb, '["ما هي خوارزمية المصرفي (Banker''s Algorithm) لإدارة وتجنب الجمود في أنظمة التشغيل؟"]'::jsonb, '[{"title":"Deadlock - Wikipedia","url":"https://en.wikipedia.org/wiki/Deadlock"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي شروط كوفمان الأربعة (Coffman Conditions) لحدوث الجمود (Deadlock) وكيف تكسر أحدها لحل المشكلة؟' or l.short_answer is distinct from 'شروط الجمود الأربعة هي: (1) الحصر المتبادل (Mutual Exclusion). (2) التعليق والانتظار (Hold and Wait). (3) عدم انتزاع القفل قسراً (No Preemption). (4) الانتظار الدائري (Circular Wait). وكسر أي شرط منها يمنع الجمود نهائياً.' or l.explanation is distinct from 'يحدث الجمود الكلاسيكي عندما يمسك الخيط 1 بالقفل A وينتظر القفل B، بينما يمسك الخيط 2 بالقفل B وينتظر القفل A؛ يتوقف النظام للأبد. أسهل وأقوى استراتيجية هندسية لكسر الجمود هي كسر شرط الانتظار الدائري عبر فرض ترتيب صارم لاكتساب الأقفال (Lock Ordering): يجب على جميع خيوط النظام دائماً حجز القفل A قبل القفل B وفقاً لترتيب هرمي ثابت وموحد.' or l.code_example is distinct from '// كسر الجمود بفرض ترتيب القفل عالمياً:
void transfer(Account from, Account to) {
  Account first = from.id < to.id ? from : to;
  Account second = from.id < to.id ? to : from;
  synchronized(first) {
    synchronized(second) {
      // مستحيل حدوث Deadlock لأن الترتيب موحد لكل العمليات!
    }
  }
}' or l.common_mistakes is distinct from '["محاولة حل الجمود بإضافة تأخير زمني عشوائي Thread.sleep() بدلاً من معالجة ترتيب الأقفال بنيوياً."]'::jsonb or l.follow_up_questions is distinct from '["ما هي خوارزمية المصرفي (Banker''s Algorithm) لإدارة وتجنب الجمود في أنظمة التشغيل؟"]'::jsonb or l.sources is distinct from '[{"title":"Deadlock - Wikipedia","url":"https://en.wikipedia.org/wiki/Deadlock"}]'::jsonb)) then raise exception 'Question fcnc-004 ar content changed; create a new revision before seeding'; end if; end $$;
