insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مشكلة رؤية الذاكرة (Memory Visibility) وما هو دور الكلمة المفتاحية volatile وحواجز الذاكرة (Memory Barriers)؟', 'تقوم المعالجات بتخزين المتغيرات في كاش محلي (L1/L2) وإعادة ترتيب التعليمات، مما يجعل التعديلات التي يجريها خيط غير مرئية فوراً للخيوط الأخرى؛ وتضمن volatile القراءة والكتابة المباشرة في الذاكرة المشتركة.', 'بدون إشارات مزامنة، قد يدخل الخيط A في حلقة while (!flag) {}. إذا عدل الخيط B قيمة flag إلى true، قد لا يرى الخيط A هذا التغيير أبداً لأن المعالج وضع flag في سجل محلي وافترض أنها لن تتغير من داخل الحلقة. كلمة volatile تخبر المترجم والمعالج بعدم إعادة ترتيب التعليمات المحيطة وتفرض حاجز ذاكرة (Memory Barrier / Fence) يجبر المعالج على تفريغ القيمة إلى الذاكرة الرئيسية وقراءتها منها دائماً.', '// يضمن رؤية المتغير فوراً عبر كافة النوى بدون كاش معزول:
private volatile boolean isRunning = true;', '["الاعتقاد بأن volatile توفر عمليات ذرية (Atomicity)؛ فهي تحل مشكلة الرؤية فقط (Visibility) ولا تحمي count++ من الـ Race Conditions."]'::jsonb, '["ما هو نموذج الذاكرة (Java/C++ Memory Model) وعلاقة ''Happens-Before'' الرياضية؟"]'::jsonb, '[{"title":"Volatile (computer programming) - Wikipedia","url":"https://en.wikipedia.org/wiki/Volatile_(computer_programming)"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي مشكلة رؤية الذاكرة (Memory Visibility) وما هو دور الكلمة المفتاحية volatile وحواجز الذاكرة (Memory Barriers)؟' or l.short_answer is distinct from 'تقوم المعالجات بتخزين المتغيرات في كاش محلي (L1/L2) وإعادة ترتيب التعليمات، مما يجعل التعديلات التي يجريها خيط غير مرئية فوراً للخيوط الأخرى؛ وتضمن volatile القراءة والكتابة المباشرة في الذاكرة المشتركة.' or l.explanation is distinct from 'بدون إشارات مزامنة، قد يدخل الخيط A في حلقة while (!flag) {}. إذا عدل الخيط B قيمة flag إلى true، قد لا يرى الخيط A هذا التغيير أبداً لأن المعالج وضع flag في سجل محلي وافترض أنها لن تتغير من داخل الحلقة. كلمة volatile تخبر المترجم والمعالج بعدم إعادة ترتيب التعليمات المحيطة وتفرض حاجز ذاكرة (Memory Barrier / Fence) يجبر المعالج على تفريغ القيمة إلى الذاكرة الرئيسية وقراءتها منها دائماً.' or l.code_example is distinct from '// يضمن رؤية المتغير فوراً عبر كافة النوى بدون كاش معزول:
private volatile boolean isRunning = true;' or l.common_mistakes is distinct from '["الاعتقاد بأن volatile توفر عمليات ذرية (Atomicity)؛ فهي تحل مشكلة الرؤية فقط (Visibility) ولا تحمي count++ من الـ Race Conditions."]'::jsonb or l.follow_up_questions is distinct from '["ما هو نموذج الذاكرة (Java/C++ Memory Model) وعلاقة ''Happens-Before'' الرياضية؟"]'::jsonb or l.sources is distinct from '[{"title":"Volatile (computer programming) - Wikipedia","url":"https://en.wikipedia.org/wiki/Volatile_(computer_programming)"}]'::jsonb)) then raise exception 'Question fcnc-005 ar content changed; create a new revision before seeding'; end if; end $$;
