insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل خوارزميات المقارنة والتبديل (Compare-And-Swap - CAS) وبناء هياكل البيانات غير المقفلة (Lock-Free)؟', 'تعتمد تعليمات CAS على تعليمة ذرية مدمجة بالمعالج تقارن محتوى الذاكرة بقيمة متوقعة، وإذا تطابقت تستبدلها بالقيمة الجديدة بنجاح؛ وإذا فشلت يعيد الخيط المحاولة دون حجز أي قفل.', 'الأقفال التقليدية تضع الخيط في النوم عند التعارض وتكلف تبديلاً سياقياً باهظاً. أما المتغيرات الذرية (مثل AtomicInteger في Java أو std::atomic في C++) فتستخدم حلقة متكررة خفيفة (CAS Loop): يقرأ الخيط القيمة الحالية، يحسب القيمة الجديدة، وينفذ تعليمة CAS. إذا عدل خيط آخر القيمة في نفس النانوثانية، تفشل التعليمة فيدور الخيط ثانية ويقرأ القيمة المحدثة فوراً، محققاً أداءً فائقاً وإنتاجية هائلة (High Throughput).', '// مفهوم حلقة CAS الذرية بدون أقفال:
do {
  current = value.get();
  next = current + 1;
} while (!value.compareAndSet(current, next));', '["تعرض خوارزميات CAS لمشكلة ABA الشهيرة، حيث تتغير القيمة من A إلى B ثم تعود إلى A دون أن يكتشف الخيط أن المحتوى قد تم تعديله بالفعل."]'::jsonb, '["كيف تحل الـ AtomicStampedReference مشكلة ABA بإضافة عداد إصدارات تراكمي مع كل تعديل؟"]'::jsonb, '[{"title":"Compare-and-swap - Wikipedia","url":"https://en.wikipedia.org/wiki/Compare-and-swap"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل خوارزميات المقارنة والتبديل (Compare-And-Swap - CAS) وبناء هياكل البيانات غير المقفلة (Lock-Free)؟' or l.short_answer is distinct from 'تعتمد تعليمات CAS على تعليمة ذرية مدمجة بالمعالج تقارن محتوى الذاكرة بقيمة متوقعة، وإذا تطابقت تستبدلها بالقيمة الجديدة بنجاح؛ وإذا فشلت يعيد الخيط المحاولة دون حجز أي قفل.' or l.explanation is distinct from 'الأقفال التقليدية تضع الخيط في النوم عند التعارض وتكلف تبديلاً سياقياً باهظاً. أما المتغيرات الذرية (مثل AtomicInteger في Java أو std::atomic في C++) فتستخدم حلقة متكررة خفيفة (CAS Loop): يقرأ الخيط القيمة الحالية، يحسب القيمة الجديدة، وينفذ تعليمة CAS. إذا عدل خيط آخر القيمة في نفس النانوثانية، تفشل التعليمة فيدور الخيط ثانية ويقرأ القيمة المحدثة فوراً، محققاً أداءً فائقاً وإنتاجية هائلة (High Throughput).' or l.code_example is distinct from '// مفهوم حلقة CAS الذرية بدون أقفال:
do {
  current = value.get();
  next = current + 1;
} while (!value.compareAndSet(current, next));' or l.common_mistakes is distinct from '["تعرض خوارزميات CAS لمشكلة ABA الشهيرة، حيث تتغير القيمة من A إلى B ثم تعود إلى A دون أن يكتشف الخيط أن المحتوى قد تم تعديله بالفعل."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحل الـ AtomicStampedReference مشكلة ABA بإضافة عداد إصدارات تراكمي مع كل تعديل؟"]'::jsonb or l.sources is distinct from '[{"title":"Compare-and-swap - Wikipedia","url":"https://en.wikipedia.org/wiki/Compare-and-swap"}]'::jsonb)) then raise exception 'Question fcnc-006 ar content changed; create a new revision before seeding'; end if; end $$;
