insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير أحواض الخيوط (Thread Pools) المهام وما هي معادلة الحجم المثالي للـ CPU-bound مقابل I/O-bound؟', 'تدير أحواض الخيوط طابوراً من المهام مع عدد محدد من الخيوط الجاهزة وتمنع انهيار النظام؛ وحجم الحوض للعمليات الحسابية يساوي عدد النوى (N_cpu)، بينما لعمليات الإدخال/الإخراج يساوي N_cpu * (1 + Wait_Time / Compute_Time).', 'إنشاء وتدمير خيط لكل طلب مستخدم يؤدي لانهيار السيرفر بسبب استهلاك الذاكرة. يحتفظ الـ Thread Pool بعدد ثابت من الخيوط العاملة التي تلتقط المهام من BlockingQueue. إذا كانت المهام CPU-bound (تشفير أو ضغط)، فزيادة الخيوط عن عدد النوى يضر الأداء بسبب الـ Context Switching. أما إذا كانت I/O-bound (انتظار قاعدة البيانات أو الشبكة حيث يقضي الخيط 90% من وقته في الانتظار)، فيمكن زيادة الخيوط لـ 10 إلى 50 ضعفاً لتشغيل النوى أثناء انتظار الآخرين.', '// ForkJoinPool تستخدم خوارزمية سرقة العمل (Work-Stealing):
// عندما ينتهي خيط من طابوره الخاص، يسرق مهام من ذيل طوابير الخيوط المزدحمة لضمان أقصى كفاءة!', '["استخدام نفس الـ Thread Pool المشترك للعمليات الحسابية السريعة والعمليات الخارجية البطيئة، مما يؤدي لاختناق المهام السريعة وتعطل الخادم."]'::jsonb, '["ما هي استراتيجيات التعامل مع طفحان طابور الحوض (Saturation Policies: Abort, CallerRuns, Discard)؟"]'::jsonb, '[{"title":"Thread pool - Wikipedia","url":"https://en.wikipedia.org/wiki/Thread_pool"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير أحواض الخيوط (Thread Pools) المهام وما هي معادلة الحجم المثالي للـ CPU-bound مقابل I/O-bound؟' or l.short_answer is distinct from 'تدير أحواض الخيوط طابوراً من المهام مع عدد محدد من الخيوط الجاهزة وتمنع انهيار النظام؛ وحجم الحوض للعمليات الحسابية يساوي عدد النوى (N_cpu)، بينما لعمليات الإدخال/الإخراج يساوي N_cpu * (1 + Wait_Time / Compute_Time).' or l.explanation is distinct from 'إنشاء وتدمير خيط لكل طلب مستخدم يؤدي لانهيار السيرفر بسبب استهلاك الذاكرة. يحتفظ الـ Thread Pool بعدد ثابت من الخيوط العاملة التي تلتقط المهام من BlockingQueue. إذا كانت المهام CPU-bound (تشفير أو ضغط)، فزيادة الخيوط عن عدد النوى يضر الأداء بسبب الـ Context Switching. أما إذا كانت I/O-bound (انتظار قاعدة البيانات أو الشبكة حيث يقضي الخيط 90% من وقته في الانتظار)، فيمكن زيادة الخيوط لـ 10 إلى 50 ضعفاً لتشغيل النوى أثناء انتظار الآخرين.' or l.code_example is distinct from '// ForkJoinPool تستخدم خوارزمية سرقة العمل (Work-Stealing):
// عندما ينتهي خيط من طابوره الخاص، يسرق مهام من ذيل طوابير الخيوط المزدحمة لضمان أقصى كفاءة!' or l.common_mistakes is distinct from '["استخدام نفس الـ Thread Pool المشترك للعمليات الحسابية السريعة والعمليات الخارجية البطيئة، مما يؤدي لاختناق المهام السريعة وتعطل الخادم."]'::jsonb or l.follow_up_questions is distinct from '["ما هي استراتيجيات التعامل مع طفحان طابور الحوض (Saturation Policies: Abort, CallerRuns, Discard)؟"]'::jsonb or l.sources is distinct from '[{"title":"Thread pool - Wikipedia","url":"https://en.wikipedia.org/wiki/Thread_pool"}]'::jsonb)) then raise exception 'Question fcnc-007 ar content changed; create a new revision before seeding'; end if; end $$;
