insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين نموذج الخيط لكل طلب (Thread-per-request) ونموذج حلقة الأحداث غير المحجوبة (Event Loop with Non-blocking I/O)؟', 'نموذج الخيط لكل طلب يخصص خيطاً كاملاً لكل اتصال مستخدم ويحجزه طوال فترة الانتظار، بينما تعتمد حلقة الأحداث على خيط واحد يستمع لأحداث المقابس عبر آليات النواة (epoll/kqueue) دون حجب.', 'في السيرفرات الكلاسيكية (مثل Apache Tomcat القديم)، حجز خيط لكل طلب يعني أنه عند وصول 10,000 اتصال متزامن يحتاج السيرفر لـ 10,000 خيط، مما يستهلك عدة غيغابايت من الذاكرة للمكدسات (Stacks) وينهار تحت وطأة الـ Context Switching (معضلة C10K). في المقابل، يعمل Node.js و Nginx و Netty بحلقة أحداث واحدة: يُسجل مقبس العميل مع النواة، وعند وصول بايتات من الشبكة، تطلق النواة إشعاراً ليلتقطه الـ Event Loop وينفذ الـ Callback بسرعة ويعود للاستماع فوراً.', '// Event Loop:
// Single Thread -> epoll_wait() -> ينفذ الـ Callbacks الجاهزة فقط ويعود في ميكروثانية
// Thread-per-request:
// Client 1 -> Thread 1 (Blocked waiting for DB)
// Client 2 -> Thread 2 (Blocked waiting for DB)', '["تشغيل عملية حسابية ثقيلة (CPU-intensive مثل تشفير معقد أو تعدين) على خيط الـ Event Loop، مما يجمد معالجة كافة طلبات المستخدمين الآخرين في نفس اللحظة."]'::jsonb, '["كيف أغلقت ميزة Virtual Threads في Java 21 فجوة كفاءة الذاكرة بين النموذجين؟"]'::jsonb, '[{"title":"The C10K problem","url":"https://en.wikipedia.org/wiki/C10k_problem"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين نموذج الخيط لكل طلب (Thread-per-request) ونموذج حلقة الأحداث غير المحجوبة (Event Loop with Non-blocking I/O)؟' or l.short_answer is distinct from 'نموذج الخيط لكل طلب يخصص خيطاً كاملاً لكل اتصال مستخدم ويحجزه طوال فترة الانتظار، بينما تعتمد حلقة الأحداث على خيط واحد يستمع لأحداث المقابس عبر آليات النواة (epoll/kqueue) دون حجب.' or l.explanation is distinct from 'في السيرفرات الكلاسيكية (مثل Apache Tomcat القديم)، حجز خيط لكل طلب يعني أنه عند وصول 10,000 اتصال متزامن يحتاج السيرفر لـ 10,000 خيط، مما يستهلك عدة غيغابايت من الذاكرة للمكدسات (Stacks) وينهار تحت وطأة الـ Context Switching (معضلة C10K). في المقابل، يعمل Node.js و Nginx و Netty بحلقة أحداث واحدة: يُسجل مقبس العميل مع النواة، وعند وصول بايتات من الشبكة، تطلق النواة إشعاراً ليلتقطه الـ Event Loop وينفذ الـ Callback بسرعة ويعود للاستماع فوراً.' or l.code_example is distinct from '// Event Loop:
// Single Thread -> epoll_wait() -> ينفذ الـ Callbacks الجاهزة فقط ويعود في ميكروثانية
// Thread-per-request:
// Client 1 -> Thread 1 (Blocked waiting for DB)
// Client 2 -> Thread 2 (Blocked waiting for DB)' or l.common_mistakes is distinct from '["تشغيل عملية حسابية ثقيلة (CPU-intensive مثل تشفير معقد أو تعدين) على خيط الـ Event Loop، مما يجمد معالجة كافة طلبات المستخدمين الآخرين في نفس اللحظة."]'::jsonb or l.follow_up_questions is distinct from '["كيف أغلقت ميزة Virtual Threads في Java 21 فجوة كفاءة الذاكرة بين النموذجين؟"]'::jsonb or l.sources is distinct from '[{"title":"The C10K problem","url":"https://en.wikipedia.org/wiki/C10k_problem"}]'::jsonb)) then raise exception 'Question fcnc-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Concurrency Event Loop Vs Thread Per Request?', 'This question checks the core Concurrency Event Loop Vs Thread Per Request concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Concurrency Event Loop Vs Thread Per Request with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// Event Loop:
// Single Thread -> epoll_wait() -> ينفذ الـ Callbacks الجاهزة فقط ويعود في ميكروثانية
