insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم نمط المنتج والمستهلك (Producer-Consumer) باستخدام حاجز مقيد (Bounded Buffer) مع الضغط العكسي (Backpressure)؟', 'باستخدام طابور ذي سعة قصوى مدعوم بمتغيرات الشروط (Condition Variables)؛ يتوقف المنتج عن العمل عندما يمتلئ الطابور، ويتوقف المستهلك عندما يفرغ الطابور.', 'إذا كان المنتج ينتج 10,000 عنصر في الثانية والمستهلك يعالج 1,000 فقط، فإن الطابور غير المحدود (Unbounded Queue) سينمو حتى يبتلع كل ذاكرة النظام ويسبب OutOfMemoryError. استخدام حاجز مقيد بسعة محددة (مثل 100 عنصر) يفرض الضغط العكسي (Backpressure) الطبيعي: عندما يمتلئ الطابور، يستدعي المنتج notFull.await() ويتوقف تلقائياً حتى يستهلك الطرف الآخر عنصراً ويطلق notFull.signal()، مما يوازن سرعة المنظومة بتناغم وأمان تام.', 'class BlockingQueue<T> {
  private queue: T[] = [];
  constructor(private capacity: number) {}
  // انتظار عند الامتلاء (Put) وانتظار عند الفراغ (Take)
}', '["استخدام طوابير غير محدودة في معالجة طلبات الإنتاج، مما يجعل السيرفر فريسة سهلة لانهيارات الذاكرة عند حدوث هجمات أو أوقات الذروة."]'::jsonb, '["كيف تترجم مكتبات Reactive Streams (مثل RxJava أو Project Reactor) الضغط العكسي عبر بروتوكول request(n)؟"]'::jsonb, '[{"title":"Producer–consumer problem - Wikipedia","url":"https://en.wikipedia.org/wiki/Producer%E2%80%93consumer_problem"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم نمط المنتج والمستهلك (Producer-Consumer) باستخدام حاجز مقيد (Bounded Buffer) مع الضغط العكسي (Backpressure)؟' or l.short_answer is distinct from 'باستخدام طابور ذي سعة قصوى مدعوم بمتغيرات الشروط (Condition Variables)؛ يتوقف المنتج عن العمل عندما يمتلئ الطابور، ويتوقف المستهلك عندما يفرغ الطابور.' or l.explanation is distinct from 'إذا كان المنتج ينتج 10,000 عنصر في الثانية والمستهلك يعالج 1,000 فقط، فإن الطابور غير المحدود (Unbounded Queue) سينمو حتى يبتلع كل ذاكرة النظام ويسبب OutOfMemoryError. استخدام حاجز مقيد بسعة محددة (مثل 100 عنصر) يفرض الضغط العكسي (Backpressure) الطبيعي: عندما يمتلئ الطابور، يستدعي المنتج notFull.await() ويتوقف تلقائياً حتى يستهلك الطرف الآخر عنصراً ويطلق notFull.signal()، مما يوازن سرعة المنظومة بتناغم وأمان تام.' or l.code_example is distinct from 'class BlockingQueue<T> {
  private queue: T[] = [];
  constructor(private capacity: number) {}
  // انتظار عند الامتلاء (Put) وانتظار عند الفراغ (Take)
}' or l.common_mistakes is distinct from '["استخدام طوابير غير محدودة في معالجة طلبات الإنتاج، مما يجعل السيرفر فريسة سهلة لانهيارات الذاكرة عند حدوث هجمات أو أوقات الذروة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم مكتبات Reactive Streams (مثل RxJava أو Project Reactor) الضغط العكسي عبر بروتوكول request(n)؟"]'::jsonb or l.sources is distinct from '[{"title":"Producer–consumer problem - Wikipedia","url":"https://en.wikipedia.org/wiki/Producer%E2%80%93consumer_problem"}]'::jsonb)) then raise exception 'Question fcnc-009 ar content changed; create a new revision before seeding'; end if; end $$;
