insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين القفل التفاؤلي (Optimistic Concurrency) والقفل التشاؤمي (Pessimistic Concurrency) في قواعد البيانات والذاكرة؟', 'القفل التشاؤمي يحجز المورد فوراً ويمنع الآخرين من القراءة أو التعديل حتى انتهاء المعاملة، بينما القفل التفاؤلي يسمح للجميع بالتعديل المتزامن مع فحص إصدار السجل (Version) عند الحفظ ورفض المعاملة إذا تغير.', 'القفل التشاؤمي (مثل SELECT ... FOR UPDATE) ممتاز عندما تكون احتمالية التعارض عالية جداً (High Contention) مثل حجز المقعد الأخير في طائرة أو شراء سلعة محدودة المخزون؛ لأنه يضمن عدم إهدار وقت المعالجة. أما القفل التفاؤلي فمثالي عندما يكون التعارض نادراً (Low Contention) والقراءة أكثر بكثير من الكتابة؛ حيث نقوم بتحديث السجل بشرط WHERE version = @currentVersion مع زيادة العداد. إذا كان الصف قد عُدل بالفعل، ترجع العملية 0 صفوف متأثرة فنطلب من المستخدم إعادة المحاولة دون أي حجز أو أقفال قاعدة بيانات باهظة.', '// قفل تفاؤلي عبر رقم الإصدار في SQL:
UPDATE products
SET stock = stock - 1, version = version + 1
WHERE id = 42 AND version = 5;
// إذا كانت النتيجة 0 rows، فهذا يعني أن خيطاً آخر قد عدل المخزون قبلك!', '["استخدام الأقفال التشاؤمية لمعاملات طويلة تتضمن مدخلات مستخدم تفاعلية، مما يعلق جداول قاعدة البيانات للأبد."]'::jsonb, '["كيف تتعامل أنظمة التوزيع الحديثة مع القفل التفاؤلي عبر تقنية MVCC (Multi-Version Concurrency Control)؟"]'::jsonb, '[{"title":"Optimistic concurrency control - Wikipedia","url":"https://en.wikipedia.org/wiki/Optimistic_concurrency_control"}]'::jsonb from public.question_revisions r where r.question_id = 'fcnc-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fcnc-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين القفل التفاؤلي (Optimistic Concurrency) والقفل التشاؤمي (Pessimistic Concurrency) في قواعد البيانات والذاكرة؟' or l.short_answer is distinct from 'القفل التشاؤمي يحجز المورد فوراً ويمنع الآخرين من القراءة أو التعديل حتى انتهاء المعاملة، بينما القفل التفاؤلي يسمح للجميع بالتعديل المتزامن مع فحص إصدار السجل (Version) عند الحفظ ورفض المعاملة إذا تغير.' or l.explanation is distinct from 'القفل التشاؤمي (مثل SELECT ... FOR UPDATE) ممتاز عندما تكون احتمالية التعارض عالية جداً (High Contention) مثل حجز المقعد الأخير في طائرة أو شراء سلعة محدودة المخزون؛ لأنه يضمن عدم إهدار وقت المعالجة. أما القفل التفاؤلي فمثالي عندما يكون التعارض نادراً (Low Contention) والقراءة أكثر بكثير من الكتابة؛ حيث نقوم بتحديث السجل بشرط WHERE version = @currentVersion مع زيادة العداد. إذا كان الصف قد عُدل بالفعل، ترجع العملية 0 صفوف متأثرة فنطلب من المستخدم إعادة المحاولة دون أي حجز أو أقفال قاعدة بيانات باهظة.' or l.code_example is distinct from '// قفل تفاؤلي عبر رقم الإصدار في SQL:
UPDATE products
SET stock = stock - 1, version = version + 1
WHERE id = 42 AND version = 5;
// إذا كانت النتيجة 0 rows، فهذا يعني أن خيطاً آخر قد عدل المخزون قبلك!' or l.common_mistakes is distinct from '["استخدام الأقفال التشاؤمية لمعاملات طويلة تتضمن مدخلات مستخدم تفاعلية، مما يعلق جداول قاعدة البيانات للأبد."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتعامل أنظمة التوزيع الحديثة مع القفل التفاؤلي عبر تقنية MVCC (Multi-Version Concurrency Control)؟"]'::jsonb or l.sources is distinct from '[{"title":"Optimistic concurrency control - Wikipedia","url":"https://en.wikipedia.org/wiki/Optimistic_concurrency_control"}]'::jsonb)) then raise exception 'Question fcnc-010 ar content changed; create a new revision before seeding'; end if; end $$;
