insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين التوسع الأفقي (Horizontal Scaling) والتوسع الرأسي (Vertical Scaling) ولماذا تعتبر الخوادم عديمة الحالة (Stateless) شرطاً أساسياً؟', 'التوسع الرأسي (Scale Up) يعني زيادة موارد نفس السيرفر (RAM, CPU)، بينما التوسع الأفقي (Scale Out) يعني إضافة المزيد من الخوادم المتوازية خلف موزع أحمال (Load Balancer). وتعتبر الخوادم عديمة الحالة شرطاً للتوسع الأفقي لتمكين توجيه أي طلب لأي خادم عشوائياً.', 'التوسع الرأسي له سقف عتادي صارم (Hardware Limit) وتكلفة متزايدة بشكل أسي ومخاطرة وجود نقطة فشل مفردة (Single Point of Failure). التوسع الأفقي غير محدود عملياً ويمكنه التكيف التلقائي مع الحمل (Auto-scaling). لكن إذا كان السيرفر يخزن جلسة المستخدم (User Session) في ذاكرته المحلية، فإن توجيه الطلب التالي لسيرفر آخر يسجل خروج المستخدم؛ لذا يتم نقل الجلسات إلى كاش مركزي مشترك (مثل Redis) لتصبح الخوادم عديمة الحالة بالكامل (Stateless).', '// بنية خوادم عديمة الحالة (Stateless Architecture):
// [Clients] -> [Load Balancer] -> [App Server 1 | App Server 2 | App Server 3]
//                                        │                │                │
//                                        └────────┬───────┴────────┬───────┘
//                                                 ▼                ▼
//                                           [Redis Cache]   [Postgres DB]', '["تخزين ملفات المستخدم المرفوعة أو جلسات الدخول على القرص الصلب أو ذاكرة خادم التطبيق بدلاً من خدمات التخزين السحابي (S3/Redis)."]'::jsonb, '["ما هي استراتيجية الـ Sticky Sessions (Session Affinity) وما هي عيوبها عند حدوث فشل في السيرفر؟"]'::jsonb, '[{"title":"Scalability - Wikipedia","url":"https://en.wikipedia.org/wiki/Scalability"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين التوسع الأفقي (Horizontal Scaling) والتوسع الرأسي (Vertical Scaling) ولماذا تعتبر الخوادم عديمة الحالة (Stateless) شرطاً أساسياً؟' or l.short_answer is distinct from 'التوسع الرأسي (Scale Up) يعني زيادة موارد نفس السيرفر (RAM, CPU)، بينما التوسع الأفقي (Scale Out) يعني إضافة المزيد من الخوادم المتوازية خلف موزع أحمال (Load Balancer). وتعتبر الخوادم عديمة الحالة شرطاً للتوسع الأفقي لتمكين توجيه أي طلب لأي خادم عشوائياً.' or l.explanation is distinct from 'التوسع الرأسي له سقف عتادي صارم (Hardware Limit) وتكلفة متزايدة بشكل أسي ومخاطرة وجود نقطة فشل مفردة (Single Point of Failure). التوسع الأفقي غير محدود عملياً ويمكنه التكيف التلقائي مع الحمل (Auto-scaling). لكن إذا كان السيرفر يخزن جلسة المستخدم (User Session) في ذاكرته المحلية، فإن توجيه الطلب التالي لسيرفر آخر يسجل خروج المستخدم؛ لذا يتم نقل الجلسات إلى كاش مركزي مشترك (مثل Redis) لتصبح الخوادم عديمة الحالة بالكامل (Stateless).' or l.code_example is distinct from '// بنية خوادم عديمة الحالة (Stateless Architecture):
// [Clients] -> [Load Balancer] -> [App Server 1 | App Server 2 | App Server 3]
//                                        │                │                │
//                                        └────────┬───────┴────────┬───────┘
//                                                 ▼                ▼
//                                           [Redis Cache]   [Postgres DB]' or l.common_mistakes is distinct from '["تخزين ملفات المستخدم المرفوعة أو جلسات الدخول على القرص الصلب أو ذاكرة خادم التطبيق بدلاً من خدمات التخزين السحابي (S3/Redis)."]'::jsonb or l.follow_up_questions is distinct from '["ما هي استراتيجية الـ Sticky Sessions (Session Affinity) وما هي عيوبها عند حدوث فشل في السيرفر؟"]'::jsonb or l.sources is distinct from '[{"title":"Scalability - Wikipedia","url":"https://en.wikipedia.org/wiki/Scalability"}]'::jsonb)) then raise exception 'Question fsys-001 ar content changed; create a new revision before seeding'; end if; end $$;
