insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح نظرية CAP ونظرية PACELC وما الذي تختاره الأنظمة الموزعة عند حدوث انقطاع في الشبكة (Network Partition)؟', 'تنص نظرية CAP على أنه في أي نظام موزع عند حدوث انقسام في الشبكة (Partition - P)، يستحيل الجمع بين الاتساق الكامل (Consistency - C) والتوافر التام (Availability - A)؛ فيجب التضحية بأحدهما.', 'إذا انقطع الاتصال بين مركز بيانات في أوروبا وآخر في أمريكا (Network Partition): إذا اخترت الاتساق (CP System مثل HBase أو Zookeeper)، فإن النظام يرفض كتابات جديدة أو يعيد خطأ حتى تعود الشبكة منعاً للتعارض. إذا اخترت التوافر (AP System مثل Cassandra أو DynamoDB)، يتيح النظام القراءة والكتابة في كلا المركزين ولكن يضحي بالاتساق اللحظي معتمداً على الاتساق النهائي (Eventual Consistency). نظرية PACELC توسع ذلك: إذا كان هناك انقسام (P) اختر بين A و C، وإلا (Else - E) اختر بين زمن الاستجابة (Latency - L) والاتساق (Consistency - C).', '// الاختيار أثناء انقطاع الشبكة:
// CP: ضمان صحة الرصيد البنكي حتى لو توقفت الخدمة مؤقتاً
// AP: بقاء التغريدات ومنشورات السوشيال ميديا متاحة حتى لو تأخرت بضع ثوان في المزامنة', '["الاعتقاد بأنه يمكنك اختيار ''CA System'' في الأنظمة الموزعة؛ انقطاعات الشبكة (Partitions) أمر حتمي فيزيائياً في العالم الحقيقي، لذا فإن الاختيار الحقيقي محصور بين CP أو AP."]'::jsonb, '["كيف تحل متجهات الساعات (Vector Clocks) وخوارزمية Last-Write-Wins تعارضات البيانات في أنظمة AP؟"]'::jsonb, '[{"title":"CAP theorem - Wikipedia","url":"https://en.wikipedia.org/wiki/CAP_theorem"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'اشرح نظرية CAP ونظرية PACELC وما الذي تختاره الأنظمة الموزعة عند حدوث انقطاع في الشبكة (Network Partition)؟' or l.short_answer is distinct from 'تنص نظرية CAP على أنه في أي نظام موزع عند حدوث انقسام في الشبكة (Partition - P)، يستحيل الجمع بين الاتساق الكامل (Consistency - C) والتوافر التام (Availability - A)؛ فيجب التضحية بأحدهما.' or l.explanation is distinct from 'إذا انقطع الاتصال بين مركز بيانات في أوروبا وآخر في أمريكا (Network Partition): إذا اخترت الاتساق (CP System مثل HBase أو Zookeeper)، فإن النظام يرفض كتابات جديدة أو يعيد خطأ حتى تعود الشبكة منعاً للتعارض. إذا اخترت التوافر (AP System مثل Cassandra أو DynamoDB)، يتيح النظام القراءة والكتابة في كلا المركزين ولكن يضحي بالاتساق اللحظي معتمداً على الاتساق النهائي (Eventual Consistency). نظرية PACELC توسع ذلك: إذا كان هناك انقسام (P) اختر بين A و C، وإلا (Else - E) اختر بين زمن الاستجابة (Latency - L) والاتساق (Consistency - C).' or l.code_example is distinct from '// الاختيار أثناء انقطاع الشبكة:
// CP: ضمان صحة الرصيد البنكي حتى لو توقفت الخدمة مؤقتاً
// AP: بقاء التغريدات ومنشورات السوشيال ميديا متاحة حتى لو تأخرت بضع ثوان في المزامنة' or l.common_mistakes is distinct from '["الاعتقاد بأنه يمكنك اختيار ''CA System'' في الأنظمة الموزعة؛ انقطاعات الشبكة (Partitions) أمر حتمي فيزيائياً في العالم الحقيقي، لذا فإن الاختيار الحقيقي محصور بين CP أو AP."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحل متجهات الساعات (Vector Clocks) وخوارزمية Last-Write-Wins تعارضات البيانات في أنظمة AP؟"]'::jsonb or l.sources is distinct from '[{"title":"CAP theorem - Wikipedia","url":"https://en.wikipedia.org/wiki/CAP_theorem"}]'::jsonb)) then raise exception 'Question fsys-002 ar content changed; create a new revision before seeding'; end if; end $$;
