insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fsys-003', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين استراتيجيات التخزين المؤقت: Cache-Aside و Write-Through و Write-Back وما هي ظاهرة تدافع الكاش (Cache Stampede)؟', 'في Cache-Aside يقرأ التطبيق من الكاش أولاً ويملأه عند الفشل، وفي Write-Through يكتب في الكاش وقاعدة البيانات معاً، وفي Write-Back يكتب في الكاش ويؤجل كتابة قاعدة البيانات للدفعة. وتدافع الكاش يحدث عندما تنتهي صلاحية مفتاح شائع فتهجم آلاف الطلبات المتزامنة على قاعدة البيانات في نفس اللحظة.', 'استراتيجية Cache-Aside هي الأكثر شيوعاً ومرونة. Write-Through تضمن أن الكاش محدث دائماً لكنها تزيد زمن الكتابة. Write-Back سريعة جداً في الكتابة لكنها مهددة بفقدان البيانات إذا تعطل الكاش قبل تفريغها في الذاكرة الدائمة. لمنع Cache Stampede (تدافع الكاش / Thundering Herd): (1) استخدام أقفال المزامنة الموزعة (Mutex) بحيث يقوم طلب واحد فقط بإعادة الاستعلام من قاعدة البيانات وتحديث الكاش بينما ينتظر البقية. (2) إضافة تباين عشوائي لوقت انتهاء الصلاحية (Jitter / Randomized TTL). (3) إعادة الحساب المبكر في الخلفية (Probabilistic Early Expiration).', '// منع تدافع الكاش باستخدام قفل موزع:
const data = await redis.get(key);
if (!data) {
  if (await redis.set(''lock:'' + key, ''1'', ''NX'', ''EX'', 5)) {
    const dbData = await fetchFromDB();
    await redis.set(key, dbData, ''EX'', 3600);
    await redis.del(''lock:'' + key);
  }
}', '["تعيين نفس وقت انتهاء الصلاحية (TTL) الدقيق لجميع المفتايح الحيوية في نفس الثانية، مما يسبب سقوطها جميعاً في وقت واحد وانهيار قاعدة البيانات."]'::jsonb, '["ما هي تقنية Cache Invalidation الأفضل: الإبطال الصريح (Eviction) أم التحديث الفوري عند الكتابة؟"]'::jsonb, '[{"title":"Cache-aside pattern - Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين استراتيجيات التخزين المؤقت: Cache-Aside و Write-Through و Write-Back وما هي ظاهرة تدافع الكاش (Cache Stampede)؟' or l.short_answer is distinct from 'في Cache-Aside يقرأ التطبيق من الكاش أولاً ويملأه عند الفشل، وفي Write-Through يكتب في الكاش وقاعدة البيانات معاً، وفي Write-Back يكتب في الكاش ويؤجل كتابة قاعدة البيانات للدفعة. وتدافع الكاش يحدث عندما تنتهي صلاحية مفتاح شائع فتهجم آلاف الطلبات المتزامنة على قاعدة البيانات في نفس اللحظة.' or l.explanation is distinct from 'استراتيجية Cache-Aside هي الأكثر شيوعاً ومرونة. Write-Through تضمن أن الكاش محدث دائماً لكنها تزيد زمن الكتابة. Write-Back سريعة جداً في الكتابة لكنها مهددة بفقدان البيانات إذا تعطل الكاش قبل تفريغها في الذاكرة الدائمة. لمنع Cache Stampede (تدافع الكاش / Thundering Herd): (1) استخدام أقفال المزامنة الموزعة (Mutex) بحيث يقوم طلب واحد فقط بإعادة الاستعلام من قاعدة البيانات وتحديث الكاش بينما ينتظر البقية. (2) إضافة تباين عشوائي لوقت انتهاء الصلاحية (Jitter / Randomized TTL). (3) إعادة الحساب المبكر في الخلفية (Probabilistic Early Expiration).' or l.code_example is distinct from '// منع تدافع الكاش باستخدام قفل موزع:
const data = await redis.get(key);
if (!data) {
  if (await redis.set(''lock:'' + key, ''1'', ''NX'', ''EX'', 5)) {
    const dbData = await fetchFromDB();
    await redis.set(key, dbData, ''EX'', 3600);
    await redis.del(''lock:'' + key);
  }
}' or l.common_mistakes is distinct from '["تعيين نفس وقت انتهاء الصلاحية (TTL) الدقيق لجميع المفتايح الحيوية في نفس الثانية، مما يسبب سقوطها جميعاً في وقت واحد وانهيار قاعدة البيانات."]'::jsonb or l.follow_up_questions is distinct from '["ما هي تقنية Cache Invalidation الأفضل: الإبطال الصريح (Eviction) أم التحديث الفوري عند الكتابة؟"]'::jsonb or l.sources is distinct from '[{"title":"Cache-aside pattern - Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside"}]'::jsonb)) then raise exception 'Question fsys-003 ar content changed; create a new revision before seeding'; end if; end $$;
