insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين قواعد البيانات العلائقية (SQL) وغير العلائقية (NoSQL) من حيث معايير ACID مقابل BASE؟', 'قواعد SQL تضمن معايير ACID الصارمة وتتميز بجداول منظمة وعلاقات قوية، بينما تعتمد NoSQL على نموذج BASE وتضحي بالاتساق الفوري لصالح التوسع الأفقي الهائل والمرونة في شكل البيانات.', 'معايير ACID: الذرية (Atomicity)، الاتساق (Consistency)، العزل (Isolation)، والمتانة (Durability) وهي ضرورية للمعاملات المالية والحسابية. أما نموذج BASE فيعتمد على: التوافر الأساسي (Basically Available)، الحالة اللينة المرنة (Soft state)، والاتساق النهائي (Eventual consistency)، وهو مثالي لأنظمة التخزين الضخمة، تحليل السجلات (Log Analytics)، والبيانات غير المهيكلة (كالملفات الوثائقية في MongoDB ومخازن المفاتيح في Redis وقواعد البيانات العمودية في Cassandra).', '// SQL: التزام صارم بالـ Schema ومفتاح أجنبي وضمانات المعاملات
// NoSQL: مستندات JSON ديناميكية، سهولة تقسيم أفقية، وتحديثات غير مقيدة', '["استخدام NoSQL للمعاملات المحاسبية المعقدة التي تتطلب حركات ذرية متعددة بين عدة جداول وحسابات."]'::jsonb, '["ما هي مستويات عزل المعاملات (Isolation Levels) في SQL: Read Uncommitted, Read Committed, Repeatable Read, Serializable؟"]'::jsonb, '[{"title":"ACID vs BASE - Wikipedia","url":"https://en.wikipedia.org/wiki/Eventual_consistency"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين قواعد البيانات العلائقية (SQL) وغير العلائقية (NoSQL) من حيث معايير ACID مقابل BASE؟' or l.short_answer is distinct from 'قواعد SQL تضمن معايير ACID الصارمة وتتميز بجداول منظمة وعلاقات قوية، بينما تعتمد NoSQL على نموذج BASE وتضحي بالاتساق الفوري لصالح التوسع الأفقي الهائل والمرونة في شكل البيانات.' or l.explanation is distinct from 'معايير ACID: الذرية (Atomicity)، الاتساق (Consistency)، العزل (Isolation)، والمتانة (Durability) وهي ضرورية للمعاملات المالية والحسابية. أما نموذج BASE فيعتمد على: التوافر الأساسي (Basically Available)، الحالة اللينة المرنة (Soft state)، والاتساق النهائي (Eventual consistency)، وهو مثالي لأنظمة التخزين الضخمة، تحليل السجلات (Log Analytics)، والبيانات غير المهيكلة (كالملفات الوثائقية في MongoDB ومخازن المفاتيح في Redis وقواعد البيانات العمودية في Cassandra).' or l.code_example is distinct from '// SQL: التزام صارم بالـ Schema ومفتاح أجنبي وضمانات المعاملات
// NoSQL: مستندات JSON ديناميكية، سهولة تقسيم أفقية، وتحديثات غير مقيدة' or l.common_mistakes is distinct from '["استخدام NoSQL للمعاملات المحاسبية المعقدة التي تتطلب حركات ذرية متعددة بين عدة جداول وحسابات."]'::jsonb or l.follow_up_questions is distinct from '["ما هي مستويات عزل المعاملات (Isolation Levels) في SQL: Read Uncommitted, Read Committed, Repeatable Read, Serializable؟"]'::jsonb or l.sources is distinct from '[{"title":"ACID vs BASE - Wikipedia","url":"https://en.wikipedia.org/wiki/Eventual_consistency"}]'::jsonb)) then raise exception 'Question fsys-006 ar content changed; create a new revision before seeding'; end if; end $$;
