insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين وسيط الرسائل المعتمد على الطوابير (RabbitMQ) وسجل الالتزام الموزع (Apache Kafka) ومتى تستخدم كلاً منهما؟', 'يتميز RabbitMQ بتوجيه الرسائل المعقد والمرن (Smart Broker, Dumb Consumer) وحذف الرسالة بمجرد معالجتها، بينما يعتبر Kafka سجل أحداث متسلسلاً فائق السرعة يحتفظ بالرسائل لفترات طويلة وتتتبع جهات الاستهلاك موضعها بنفسها (Dumb Broker, Smart Consumer).', 'RabbitMQ ممتاز لمهام الخلفية المتفرقة ومعالجة الطلبات غير المتزامنة التي تتطلب توجيهاً دقيقاً (Routing Keys, Topic Exchanges) وأولويات للرسائل. في المقابل، Kafka مصمم لتدفق البيانات الضخمة (Event Streaming) وملايين الأحداث في الثانية؛ حيث تُكتب الأحداث في أقسام (Partitions) متسلسلة على القرص، ويستطيع المشتركون قراءة الرسائل أو إعادة تشغيلها من البداية (Replay events) في أي وقت دون أن تُحذف.', '// RabbitMQ: مهام فردية، إقرارات لحظية، وحذف فوري للرسالة المستهلكة
// Kafka: سجل أحداث ثابت غير قابل للتعديل (Append-Only Log) يدعم القراءة المكررة وملايين الرسائل/ثانية', '["استخدام Kafka لإدارة مهام الخلفية البسيطة الفردية، مما يضيف تعقيداً تشغيلياً هائلاً للبنية التحتية دون داعٍ."]'::jsonb, '["كيف تضمن مجموعات المستهلكين (Consumer Groups) في Kafka معالجة الأحداث بالتوازي مع الحفاظ على الترتيب داخل القسم؟"]'::jsonb, '[{"title":"Apache Kafka Architecture","url":"https://en.wikipedia.org/wiki/Apache_Kafka"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين وسيط الرسائل المعتمد على الطوابير (RabbitMQ) وسجل الالتزام الموزع (Apache Kafka) ومتى تستخدم كلاً منهما؟' or l.short_answer is distinct from 'يتميز RabbitMQ بتوجيه الرسائل المعقد والمرن (Smart Broker, Dumb Consumer) وحذف الرسالة بمجرد معالجتها، بينما يعتبر Kafka سجل أحداث متسلسلاً فائق السرعة يحتفظ بالرسائل لفترات طويلة وتتتبع جهات الاستهلاك موضعها بنفسها (Dumb Broker, Smart Consumer).' or l.explanation is distinct from 'RabbitMQ ممتاز لمهام الخلفية المتفرقة ومعالجة الطلبات غير المتزامنة التي تتطلب توجيهاً دقيقاً (Routing Keys, Topic Exchanges) وأولويات للرسائل. في المقابل، Kafka مصمم لتدفق البيانات الضخمة (Event Streaming) وملايين الأحداث في الثانية؛ حيث تُكتب الأحداث في أقسام (Partitions) متسلسلة على القرص، ويستطيع المشتركون قراءة الرسائل أو إعادة تشغيلها من البداية (Replay events) في أي وقت دون أن تُحذف.' or l.code_example is distinct from '// RabbitMQ: مهام فردية، إقرارات لحظية، وحذف فوري للرسالة المستهلكة
// Kafka: سجل أحداث ثابت غير قابل للتعديل (Append-Only Log) يدعم القراءة المكررة وملايين الرسائل/ثانية' or l.common_mistakes is distinct from '["استخدام Kafka لإدارة مهام الخلفية البسيطة الفردية، مما يضيف تعقيداً تشغيلياً هائلاً للبنية التحتية دون داعٍ."]'::jsonb or l.follow_up_questions is distinct from '["كيف تضمن مجموعات المستهلكين (Consumer Groups) في Kafka معالجة الأحداث بالتوازي مع الحفاظ على الترتيب داخل القسم؟"]'::jsonb or l.sources is distinct from '[{"title":"Apache Kafka Architecture","url":"https://en.wikipedia.org/wiki/Apache_Kafka"}]'::jsonb)) then raise exception 'Question fsys-007 ar content changed; create a new revision before seeding'; end if; end $$;
