insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل خوارزميات تحديد معدل الطلبات (Rate Limiting): خوارزمية Token Bucket وخوارزمية Leaky Bucket؟', 'تعتمد Token Bucket على إضافة رموز إلى دلو بمعدل ثابت وتسمح برشقات من الطلبات طالما توفرت رموز، بينما تمرر Leaky Bucket الطلبات بمعدل تدفق ثابت تماماً كقطرات الماء دون السماح بأي طفرات مفاجئة.', 'في خوارزمية Token Bucket، يمتلك الدلو سعة قصوى C، وتضاف الرموز بمعدل R رمز/ثانية. مع كل طلب، يُخصم رمز واحد؛ إذا فرغ الدلو يُرفض الطلب بخطأ 429 Too Many Requests. ميزتها أنها تسمح بمرور رشقة سريعة (Burst) طالما لم يتجاوز الحجم سعة الدلو. أما خوارزمية Leaky Bucket فتضع الطلبات في طابور وتخرجها بمعدل خروج ثابت وصارم، مما يضمن حملاً منتظماً تماماً على الأنظمة الحساسة التي لا تتحمل أي قفزات مفاجئة.', '// خوارزمية Token Bucket في Redis:
// يتم التحقق من الوقت المنقضي وإضافة الرموز الحسابية رياضياً دون الحاجة لمؤقتات خلفية مستمرة!', '["استخدام خوارزمية Fixed Window Counter البسيطة، التي تعاني من عيب خطير يسمح بضعف معدل الطلبات المسموح به عند حافة النافذة الزمنية (Boundary Burst)."]'::jsonb, '["كيف تحل خوارزمية Sliding Window Log مشكلة حواف النوافذ وما هي تكلفتها على استهلاك ذاكرة Redis؟"]'::jsonb, '[{"title":"Token bucket - Wikipedia","url":"https://en.wikipedia.org/wiki/Token_bucket"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل خوارزميات تحديد معدل الطلبات (Rate Limiting): خوارزمية Token Bucket وخوارزمية Leaky Bucket؟' or l.short_answer is distinct from 'تعتمد Token Bucket على إضافة رموز إلى دلو بمعدل ثابت وتسمح برشقات من الطلبات طالما توفرت رموز، بينما تمرر Leaky Bucket الطلبات بمعدل تدفق ثابت تماماً كقطرات الماء دون السماح بأي طفرات مفاجئة.' or l.explanation is distinct from 'في خوارزمية Token Bucket، يمتلك الدلو سعة قصوى C، وتضاف الرموز بمعدل R رمز/ثانية. مع كل طلب، يُخصم رمز واحد؛ إذا فرغ الدلو يُرفض الطلب بخطأ 429 Too Many Requests. ميزتها أنها تسمح بمرور رشقة سريعة (Burst) طالما لم يتجاوز الحجم سعة الدلو. أما خوارزمية Leaky Bucket فتضع الطلبات في طابور وتخرجها بمعدل خروج ثابت وصارم، مما يضمن حملاً منتظماً تماماً على الأنظمة الحساسة التي لا تتحمل أي قفزات مفاجئة.' or l.code_example is distinct from '// خوارزمية Token Bucket في Redis:
// يتم التحقق من الوقت المنقضي وإضافة الرموز الحسابية رياضياً دون الحاجة لمؤقتات خلفية مستمرة!' or l.common_mistakes is distinct from '["استخدام خوارزمية Fixed Window Counter البسيطة، التي تعاني من عيب خطير يسمح بضعف معدل الطلبات المسموح به عند حافة النافذة الزمنية (Boundary Burst)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحل خوارزمية Sliding Window Log مشكلة حواف النوافذ وما هي تكلفتها على استهلاك ذاكرة Redis؟"]'::jsonb or l.sources is distinct from '[{"title":"Token bucket - Wikipedia","url":"https://en.wikipedia.org/wiki/Token_bucket"}]'::jsonb)) then raise exception 'Question fsys-008 ar content changed; create a new revision before seeding'; end if; end $$;
