insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير المعاملات الموزعة في بنية المايكروسيرفس وما الفرق بين Two-Phase Commit ونمط Saga؟', 'بروتوكول 2PC يفرض قفلاً موزعاً متزامناً عبر منسق مركزي يضمن الاتساق الصارم لكنه يعاني من بطء شديد ونقطة فشل مفردة، بينما يدير نمط Saga المعاملات كسلسلة من المعاملات المحلية المنفصلة مع معاملات تعويضية (Compensating Transactions) للتراجع عند الفشل.', 'في نمط Saga، تنفذ كل خدمة معاملتها المحلية وتطلق حدثاً يخبر الخدمة التالية لإكمال دورها. إذا فشلت خطوة في المنتصف (مثل رفض بطاقة الائتمان في خدمة الدفع بعد حجز المقعد في خدمة التذاكر)، تطلق الخدمة حدث فشل وتبدأ خطة التراجع بتنفيذ معاملات تعويضية بالعكس (إلغاء حجز المقعد). ينقسم Saga إلى: Choreography (حيث تتواصل الخدمات ذاتياً عبر الأحداث) أو Orchestration (حيث يوجه منسق مركزي الأوامر والتعويضات).', '// نمط Saga مع التعويض:
// 1. CreateOrder (محلي) -> 2. ReserveInventory (محلي) -> 3. ChargeCard (فشل!)
// التعويض: 4. CancelInventoryReservation -> 5. MarkOrderFailed', '["استخدام بروتوكول Two-Phase Commit (2PC) في بيئات الخدمات السحابية واسعة النطاق، مما يسبب بطئاً شديداً وحجب الموارد عند أي اضطراب شبكي."]'::jsonb, '["ما هي معضلة القراءة غير النظيفة (Dirty Reads) التي قد تواجهها أنظمة Saga أثناء تنفيذ المعاملات التعويضية؟"]'::jsonb, '[{"title":"Saga pattern - Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/saga"}]'::jsonb from public.question_revisions r where r.question_id = 'fsys-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fsys-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير المعاملات الموزعة في بنية المايكروسيرفس وما الفرق بين Two-Phase Commit ونمط Saga؟' or l.short_answer is distinct from 'بروتوكول 2PC يفرض قفلاً موزعاً متزامناً عبر منسق مركزي يضمن الاتساق الصارم لكنه يعاني من بطء شديد ونقطة فشل مفردة، بينما يدير نمط Saga المعاملات كسلسلة من المعاملات المحلية المنفصلة مع معاملات تعويضية (Compensating Transactions) للتراجع عند الفشل.' or l.explanation is distinct from 'في نمط Saga، تنفذ كل خدمة معاملتها المحلية وتطلق حدثاً يخبر الخدمة التالية لإكمال دورها. إذا فشلت خطوة في المنتصف (مثل رفض بطاقة الائتمان في خدمة الدفع بعد حجز المقعد في خدمة التذاكر)، تطلق الخدمة حدث فشل وتبدأ خطة التراجع بتنفيذ معاملات تعويضية بالعكس (إلغاء حجز المقعد). ينقسم Saga إلى: Choreography (حيث تتواصل الخدمات ذاتياً عبر الأحداث) أو Orchestration (حيث يوجه منسق مركزي الأوامر والتعويضات).' or l.code_example is distinct from '// نمط Saga مع التعويض:
// 1. CreateOrder (محلي) -> 2. ReserveInventory (محلي) -> 3. ChargeCard (فشل!)
// التعويض: 4. CancelInventoryReservation -> 5. MarkOrderFailed' or l.common_mistakes is distinct from '["استخدام بروتوكول Two-Phase Commit (2PC) في بيئات الخدمات السحابية واسعة النطاق، مما يسبب بطئاً شديداً وحجب الموارد عند أي اضطراب شبكي."]'::jsonb or l.follow_up_questions is distinct from '["ما هي معضلة القراءة غير النظيفة (Dirty Reads) التي قد تواجهها أنظمة Saga أثناء تنفيذ المعاملات التعويضية؟"]'::jsonb or l.sources is distinct from '[{"title":"Saga pattern - Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/saga"}]'::jsonb)) then raise exception 'Question fsys-010 ar content changed; create a new revision before seeding'; end if; end $$;
