insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين نموذج OSI المكون من 7 طبقات ونموذج TCP/IP وكيف تعمل عملية التغليف (Encapsulation) لحزم البيانات؟', 'نموذج OSI هو إطار نظري مرجعي من 7 طبقات، بينما TCP/IP هو النموذج العملي الحقيقي للإنترنت المكون من 4 طبقات؛ وتغليف البيانات يعني إضافة ترويسة (Header) خاصة بكل طبقة أثناء هبوط البيانات للأسفل.', 'طبقات OSI: التطبيق (Application)، العرض (Presentation)، الجلسة (Session)، النقل (Transport)، الشبكة (Network)، ربط البيانات (Data Link)، والفيزيائية (Physical). في TCP/IP، دُمجت الطبقات الثلاث العليا في طبقة التطبيق. عند إرسال طلب، تضاف ترويسة TCP في طبقة النقل (لتصبح Segment)، ثم ترويسة IP في طبقة الشبكة (لتصبح Packet)، ثم ترويسة Ethernet في طبقة الرابط (لتصبح Frame)، ثم تُحول لإشارات كهربائية/ضوئية (Bits) عبر الأسلاك.', '// تدفق التغليف (Encapsulation):
// [Data] -> [TCP | Data] -> [IP | TCP | Data] -> [Ethernet | IP | TCP | Data | FCS]', '["الخلط بين عنوان الـ IP (طبقة الشبكة للتوجيه العالمي بين الراوترات) وعنوان الـ MAC (طبقة الرابط للتوصيل المحلي بين الأجهزة المباشرة)."]'::jsonb, '["كيف تعمل عملية فك التغليف (Decapsulation) العكسية عند استقبال الحزمة لدى الخادم المستلم؟"]'::jsonb, '[{"title":"OSI model - Wikipedia","url":"https://en.wikipedia.org/wiki/OSI_model"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين نموذج OSI المكون من 7 طبقات ونموذج TCP/IP وكيف تعمل عملية التغليف (Encapsulation) لحزم البيانات؟' or l.short_answer is distinct from 'نموذج OSI هو إطار نظري مرجعي من 7 طبقات، بينما TCP/IP هو النموذج العملي الحقيقي للإنترنت المكون من 4 طبقات؛ وتغليف البيانات يعني إضافة ترويسة (Header) خاصة بكل طبقة أثناء هبوط البيانات للأسفل.' or l.explanation is distinct from 'طبقات OSI: التطبيق (Application)، العرض (Presentation)، الجلسة (Session)، النقل (Transport)، الشبكة (Network)، ربط البيانات (Data Link)، والفيزيائية (Physical). في TCP/IP، دُمجت الطبقات الثلاث العليا في طبقة التطبيق. عند إرسال طلب، تضاف ترويسة TCP في طبقة النقل (لتصبح Segment)، ثم ترويسة IP في طبقة الشبكة (لتصبح Packet)، ثم ترويسة Ethernet في طبقة الرابط (لتصبح Frame)، ثم تُحول لإشارات كهربائية/ضوئية (Bits) عبر الأسلاك.' or l.code_example is distinct from '// تدفق التغليف (Encapsulation):
// [Data] -> [TCP | Data] -> [IP | TCP | Data] -> [Ethernet | IP | TCP | Data | FCS]' or l.common_mistakes is distinct from '["الخلط بين عنوان الـ IP (طبقة الشبكة للتوجيه العالمي بين الراوترات) وعنوان الـ MAC (طبقة الرابط للتوصيل المحلي بين الأجهزة المباشرة)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل عملية فك التغليف (Decapsulation) العكسية عند استقبال الحزمة لدى الخادم المستلم؟"]'::jsonb or l.sources is distinct from '[{"title":"OSI model - Wikipedia","url":"https://en.wikipedia.org/wiki/OSI_model"}]'::jsonb)) then raise exception 'Question fnet-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Networking Osi Vs Tcpip Model Encapsulation?', 'This question checks the core Networking Osi Vs Tcpip Model Encapsulation concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Networking Osi Vs Tcpip Model Encapsulation with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// تدفق التغليف (Encapsulation):
