insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين بروتوكول TCP وبروتوكول UDP وكيف تضمن مصافحة الـ 3-Way Handshake موثوقية الاتصال؟', 'بروتوكول TCP موثوق، موجه بالاتصال (Connection-oriented)، يضمن وصول وترتيب الحزم والتحكم بالتدفق، بينما UDP بروتوكول عديم الاتصال وسريع جداً دون أي ضمان للوصول أو الترتيب.', 'تؤسس مصافحة TCP الثلاثية الاتصال عبر: (1) إرسال العميل حزمة SYN برقم تسلسلي مبدئي. (2) رد الخادم بـ SYN-ACK لتأكيد الاستلام وإرسال رقمه الخاص. (3) رد العميل بـ ACK لبدء نقل البيانات. يعيد TCP إرسال الحزم المفقودة تلقائياً (Retransmission) ويتحكم بالازدحام (Congestion Control). في المقابل، يرسل UDP الحزم فوراً دون انتظار، مما يجعله الخيار الأمثل للبث المباشر (Video Streaming)، ألعاب الفيديو التنافسية، واستعلامات DNS السريعة.', '// TCP 3-Way Handshake:
// Client ─── SYN (Seq=X) ───> Server
// Client <── SYN-ACK (Seq=Y, Ack=X+1) ── Server
// Client ─── ACK (Ack=Y+1) ───> Server', '["استخدام TCP للبث الصوتي الحي في الألعاب، مما يسبب تقطيعاً وتراكماً للتأخير عند ضياع حزمة غير هامة ومحاولة إعادة إرسالها."]'::jsonb, '["كيف تعمل مصافحة الإنهاء الرباعية (4-Way Handshake / FIN-ACK) لإغلاق اتصال TCP بأمان؟"]'::jsonb, '[{"title":"Transmission Control Protocol - Wikipedia","url":"https://en.wikipedia.org/wiki/Transmission_Control_Protocol"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين بروتوكول TCP وبروتوكول UDP وكيف تضمن مصافحة الـ 3-Way Handshake موثوقية الاتصال؟' or l.short_answer is distinct from 'بروتوكول TCP موثوق، موجه بالاتصال (Connection-oriented)، يضمن وصول وترتيب الحزم والتحكم بالتدفق، بينما UDP بروتوكول عديم الاتصال وسريع جداً دون أي ضمان للوصول أو الترتيب.' or l.explanation is distinct from 'تؤسس مصافحة TCP الثلاثية الاتصال عبر: (1) إرسال العميل حزمة SYN برقم تسلسلي مبدئي. (2) رد الخادم بـ SYN-ACK لتأكيد الاستلام وإرسال رقمه الخاص. (3) رد العميل بـ ACK لبدء نقل البيانات. يعيد TCP إرسال الحزم المفقودة تلقائياً (Retransmission) ويتحكم بالازدحام (Congestion Control). في المقابل، يرسل UDP الحزم فوراً دون انتظار، مما يجعله الخيار الأمثل للبث المباشر (Video Streaming)، ألعاب الفيديو التنافسية، واستعلامات DNS السريعة.' or l.code_example is distinct from '// TCP 3-Way Handshake:
// Client ─── SYN (Seq=X) ───> Server
// Client <── SYN-ACK (Seq=Y, Ack=X+1) ── Server
// Client ─── ACK (Ack=Y+1) ───> Server' or l.common_mistakes is distinct from '["استخدام TCP للبث الصوتي الحي في الألعاب، مما يسبب تقطيعاً وتراكماً للتأخير عند ضياع حزمة غير هامة ومحاولة إعادة إرسالها."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل مصافحة الإنهاء الرباعية (4-Way Handshake / FIN-ACK) لإغلاق اتصال TCP بأمان؟"]'::jsonb or l.sources is distinct from '[{"title":"Transmission Control Protocol - Wikipedia","url":"https://en.wikipedia.org/wiki/Transmission_Control_Protocol"}]'::jsonb)) then raise exception 'Question fnet-002 ar content changed; create a new revision before seeding'; end if; end $$;
