insert into public.interview_questions (id, slug, track_id, difficulty) values ('fnet-003', 'networking-http1-vs-http2-vs-http3-quic', 'fundamentals', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
