insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'تتبع التطور التاريخي لبروتوكول HTTP: من HTTP/1.1 إلى HTTP/2 والـ Multiplexing وصولاً إلى HTTP/3 ومحرك QUIC القائم على UDP؟', 'عالج HTTP/2 مشكلة حجب صدارة الطابور على مستوى التطبيق بدمج كل الطلبات في اتصال TCP واحد عبر Multiplexing، بينما حل HTTP/3 المشكلة على مستوى النقل بالكامل باستبدال TCP ببروتوكول QUIC فوق UDP.', 'في HTTP/1.1، يتطلب كل طلب اتصالاً مستقلاً أو ينتظر انتهاء الطلب السابق (Head-of-Line Blocking). حل HTTP/2 ذلك بتقسيم البيانات إلى إطارات ثنائية (Binary Frames) ونقل تيارات متزامنة عبر نفس اتصال TCP وميزة ضغط الترويسات (HPACK). لكن عند ضياع حزمة TCP واحدة بسبب تشويش الشبكة، يتوقف بروتوكول TCP عن تمرير كافة التيارات الأخرى حتى تُعاد تلك الحزمة المفقودة! جاء HTTP/3 المبني على QUIC فوق UDP ليعالج ذلك: كل تيار بيانات مستقل تماماً، وضياع حزمة في تدفق لا يؤثر مطلقاً على باقي التيارات، مع دمج مصافحة TLS 1.3 في خطوة واحدة (0-RTT).', '// HTTP/1.1: عدة اتصالات متوازية مع استهلاك عالي لموارد الخادم
// HTTP/2: اتصال TCP واحد + Multiplexing ثنائي (يعاني من HOL Blocking عند ضياع باكت)
// HTTP/3: مبني على QUIC عبر UDP (انعدام تام لـ HOL Blocking + اتصال لحظي 0-RTT)', '["الاعتقاد بأن HTTP/3 غير آمن لأنه يستخدم UDP؛ بروتوكول QUIC يدمج تشفير TLS 1.3 إلزامياً في كل حزمة ولا يمكن تشغيله كنص خام غير مشفر."]'::jsonb, '["كيف تساهم ميزة Server Push في HTTP/2 وميزة مقاومة انتقال الشبكات (Connection Migration) في QUIC في تحسين تجربة الهواتف الذكية؟"]'::jsonb, '[{"title":"HTTP/3 and QUIC - MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Overview"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'تتبع التطور التاريخي لبروتوكول HTTP: من HTTP/1.1 إلى HTTP/2 والـ Multiplexing وصولاً إلى HTTP/3 ومحرك QUIC القائم على UDP؟' or l.short_answer is distinct from 'عالج HTTP/2 مشكلة حجب صدارة الطابور على مستوى التطبيق بدمج كل الطلبات في اتصال TCP واحد عبر Multiplexing، بينما حل HTTP/3 المشكلة على مستوى النقل بالكامل باستبدال TCP ببروتوكول QUIC فوق UDP.' or l.explanation is distinct from 'في HTTP/1.1، يتطلب كل طلب اتصالاً مستقلاً أو ينتظر انتهاء الطلب السابق (Head-of-Line Blocking). حل HTTP/2 ذلك بتقسيم البيانات إلى إطارات ثنائية (Binary Frames) ونقل تيارات متزامنة عبر نفس اتصال TCP وميزة ضغط الترويسات (HPACK). لكن عند ضياع حزمة TCP واحدة بسبب تشويش الشبكة، يتوقف بروتوكول TCP عن تمرير كافة التيارات الأخرى حتى تُعاد تلك الحزمة المفقودة! جاء HTTP/3 المبني على QUIC فوق UDP ليعالج ذلك: كل تيار بيانات مستقل تماماً، وضياع حزمة في تدفق لا يؤثر مطلقاً على باقي التيارات، مع دمج مصافحة TLS 1.3 في خطوة واحدة (0-RTT).' or l.code_example is distinct from '// HTTP/1.1: عدة اتصالات متوازية مع استهلاك عالي لموارد الخادم
// HTTP/2: اتصال TCP واحد + Multiplexing ثنائي (يعاني من HOL Blocking عند ضياع باكت)
// HTTP/3: مبني على QUIC عبر UDP (انعدام تام لـ HOL Blocking + اتصال لحظي 0-RTT)' or l.common_mistakes is distinct from '["الاعتقاد بأن HTTP/3 غير آمن لأنه يستخدم UDP؛ بروتوكول QUIC يدمج تشفير TLS 1.3 إلزامياً في كل حزمة ولا يمكن تشغيله كنص خام غير مشفر."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم ميزة Server Push في HTTP/2 وميزة مقاومة انتقال الشبكات (Connection Migration) في QUIC في تحسين تجربة الهواتف الذكية؟"]'::jsonb or l.sources is distinct from '[{"title":"HTTP/3 and QUIC - MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Overview"}]'::jsonb)) then raise exception 'Question fnet-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Networking Http1 Vs Http2 Vs Http3 Quic?', 'This question checks the core Networking Http1 Vs Http2 Vs Http3 Quic concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Networking Http1 Vs Http2 Vs Http3 Quic with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// HTTP/1.1: عدة اتصالات متوازية مع استهلاك عالي لموارد الخادم
