insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تجري دورة حياة دقة نظام أسماء النطاقات (DNS Resolution) وما الفرق بين الاستعلامات المتكررة والمتتالية؟', 'يقوم DNS بترجمة أسماء النطاقات البشرية (example.com) إلى عناوين IP رقمية؛ في الاستعلام التكراري (Recursive) يتولى الخادم الوسيط جلب الإجابة الكاملة للعميل، بينما في الاستعلام المتتالي (Iterative) يوجه الخادم السائل إلى الخادم التالي في التسلسل الهرمي.', 'عند كتابة رابط في المتصفح: (1) فحص الكاش المحلي في المتصفح ثم نظام التشغيل ثم الروتر. (2) إرسال استعلام لمحلل DNS لمزود الإنترنت (DNS Resolver). (3) يستعلم المحلل خوادم الجذر (Root Servers) التي توجهه لخوادم نطاق المستوى الأعلى (.com TLD Servers). (4) يوجه خادم TLD المحلل إلى خادم الأسماء المعتمد للنطاق (Authoritative Name Server). (5) يجلب المحلل سجل A ويحفظه في الكاش وفقاً لـ TTL ويرسله للمتصفح ليبدأ الاتصال.', '// مسار دقة الـ DNS الهرمي:
// Browser -> Local Cache -> DNS Resolver -> Root (.) -> TLD (.com) -> Authoritative (example.com) -> IP', '["ضبط قيمة TTL (Time to Live) طويلة جداً في سجلات الـ DNS قبل إجراء عملية نقل أو ترقية لخوادم الموقع، مما يؤدي لبقاء الزوار عالقين في السيرفرات القديمة لساعات."]'::jsonb, '["ما الفرق بين أنواع سجلات DNS الأساسية: A و AAAA و CNAME و MX و TXT؟"]'::jsonb, '[{"title":"Domain Name System - Wikipedia","url":"https://en.wikipedia.org/wiki/Domain_Name_System"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تجري دورة حياة دقة نظام أسماء النطاقات (DNS Resolution) وما الفرق بين الاستعلامات المتكررة والمتتالية؟' or l.short_answer is distinct from 'يقوم DNS بترجمة أسماء النطاقات البشرية (example.com) إلى عناوين IP رقمية؛ في الاستعلام التكراري (Recursive) يتولى الخادم الوسيط جلب الإجابة الكاملة للعميل، بينما في الاستعلام المتتالي (Iterative) يوجه الخادم السائل إلى الخادم التالي في التسلسل الهرمي.' or l.explanation is distinct from 'عند كتابة رابط في المتصفح: (1) فحص الكاش المحلي في المتصفح ثم نظام التشغيل ثم الروتر. (2) إرسال استعلام لمحلل DNS لمزود الإنترنت (DNS Resolver). (3) يستعلم المحلل خوادم الجذر (Root Servers) التي توجهه لخوادم نطاق المستوى الأعلى (.com TLD Servers). (4) يوجه خادم TLD المحلل إلى خادم الأسماء المعتمد للنطاق (Authoritative Name Server). (5) يجلب المحلل سجل A ويحفظه في الكاش وفقاً لـ TTL ويرسله للمتصفح ليبدأ الاتصال.' or l.code_example is distinct from '// مسار دقة الـ DNS الهرمي:
// Browser -> Local Cache -> DNS Resolver -> Root (.) -> TLD (.com) -> Authoritative (example.com) -> IP' or l.common_mistakes is distinct from '["ضبط قيمة TTL (Time to Live) طويلة جداً في سجلات الـ DNS قبل إجراء عملية نقل أو ترقية لخوادم الموقع، مما يؤدي لبقاء الزوار عالقين في السيرفرات القديمة لساعات."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين أنواع سجلات DNS الأساسية: A و AAAA و CNAME و MX و TXT؟"]'::jsonb or l.sources is distinct from '[{"title":"Domain Name System - Wikipedia","url":"https://en.wikipedia.org/wiki/Domain_Name_System"}]'::jsonb)) then raise exception 'Question fnet-005 ar content changed; create a new revision before seeding'; end if; end $$;
