insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fnet-006', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين تقنيات الاتصال اللحظي: WebSockets و Server-Sent Events (SSE) و Long Polling ومتى تختار كلاً منها؟', 'الـ WebSockets يوفر اتصالاً ثنائي الاتجاه كاملاً (Full-Duplex) فوق اتصال TCP واحد مستمر، والـ SSE يوفر تدفقاً أحادي الاتجاه من الخادم للعميل فوق HTTP القياسي، والـ Long Polling يعتمد على إبقاء طلبات HTTP معلقة حتى تتوفر بيانات جديدة.', 'إذا كان التطبيق يتطلب تواصلاً سريعاً في الاتجاهين (مثل غرف الدردشة الجماعية، الألعاب متعددة اللاعبين، والبورصات اللحظية)، فالـ WebSockets هو الخيار الأفضل لأنه يزيل ترويسات HTTP المتكررة. إذا كان التطبيق يتطلب بث بيانات من الخادم فقط دون إرسال من العميل (مثل أسعار العملات، إشعارات التطبيق، وتدفق نصوص ChatGPT)، فالـ SSE ممتاز وبسيط للغاية ويدعم إعادة الاتصال التلقائي ومرور الجدران النارية والبروكسيات بسهولة عبر HTTP.', '// WebSockets: ثنائي الاتجاه (Client <───> Server) عبر ws:// أو wss://
// SSE: أحادي الاتجاه (Server ───> Client) عبر Content-Type: text/event-stream
// Long Polling: طلبات متتالية تنتظر الرد وتفتح طلباً جديداً فوراً', '["استخدام WebSockets لبث إشعارات بسيطة أحادية الاتجاه، مما يضيف تعقيداً في الحفاظ على الـ Handshake وإدارة الخوادم وحجب الـ Proxies بدون داع."]'::jsonb, '["كيف تمنع تسريبات اتصالات الـ WebSockets الخاملة عبر آلية Heartbeats (Ping/Pong Frames)؟"]'::jsonb, '[{"title":"WebSockets API - MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Web/API/WebSockets_API"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
