insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مبادئ معمارية REST وما معنى أن تكون العملية متكررة النتائج (Idempotent)؟', 'تعتمد REST على بنية عميل/خادم عديمة الحالة (Stateless)، وموارد محددة بروابط URI موحدة، واستخدام أفعال HTTP القياسية؛ وتكون العملية Idempotent إذا كان تكرار تنفيذها N مرة ينتج نفس الحالة النهائية للنظام تماماً كمرة واحدة.', 'أفعال GET و PUT و DELETE و HEAD و OPTIONS كلها Idempotent؛ فإذا حذفت المورد DELETE /users/42 عشر مرات، فإن النتيجة النهائية على قاعدة البيانات هي حذف المستخدم ولا يختلف أثره في المرة الثانية عن الأولى. بينما يعتبر POST غير متكرر النتائج (Non-Idempotent)؛ لأن إرساله مرتين سينشئ سجلين أو معاملتين ماليتين مكررتين ما لم يُحمى بمفتاح عدم تكرار (Idempotency Key).', '// GET, PUT, DELETE: Idempotent (آمن للتكرار عند انقطاع الشبكة)
// POST: Non-Idempotent (يتطلب حماية مفتاح idempotency-key)', '["استخدام أفعال GET لتعديل أو حذف البيانات في السيرفر (مثل /delete-user?id=5)، مما يسمح لمحركات البحث والـ Prefetching بحذف بيانات المستخدمين دون قصد!"]'::jsonb, '["ما هو معيار HATEOAS (Hypermedia as the Engine of Application State) وأعلى درجات نضج ريتشاردسون (Richardson Maturity Model)؟"]'::jsonb, '[{"title":"Representational state transfer - Wikipedia","url":"https://en.wikipedia.org/wiki/REST"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي مبادئ معمارية REST وما معنى أن تكون العملية متكررة النتائج (Idempotent)؟' or l.short_answer is distinct from 'تعتمد REST على بنية عميل/خادم عديمة الحالة (Stateless)، وموارد محددة بروابط URI موحدة، واستخدام أفعال HTTP القياسية؛ وتكون العملية Idempotent إذا كان تكرار تنفيذها N مرة ينتج نفس الحالة النهائية للنظام تماماً كمرة واحدة.' or l.explanation is distinct from 'أفعال GET و PUT و DELETE و HEAD و OPTIONS كلها Idempotent؛ فإذا حذفت المورد DELETE /users/42 عشر مرات، فإن النتيجة النهائية على قاعدة البيانات هي حذف المستخدم ولا يختلف أثره في المرة الثانية عن الأولى. بينما يعتبر POST غير متكرر النتائج (Non-Idempotent)؛ لأن إرساله مرتين سينشئ سجلين أو معاملتين ماليتين مكررتين ما لم يُحمى بمفتاح عدم تكرار (Idempotency Key).' or l.code_example is distinct from '// GET, PUT, DELETE: Idempotent (آمن للتكرار عند انقطاع الشبكة)
// POST: Non-Idempotent (يتطلب حماية مفتاح idempotency-key)' or l.common_mistakes is distinct from '["استخدام أفعال GET لتعديل أو حذف البيانات في السيرفر (مثل /delete-user?id=5)، مما يسمح لمحركات البحث والـ Prefetching بحذف بيانات المستخدمين دون قصد!"]'::jsonb or l.follow_up_questions is distinct from '["ما هو معيار HATEOAS (Hypermedia as the Engine of Application State) وأعلى درجات نضج ريتشاردسون (Richardson Maturity Model)؟"]'::jsonb or l.sources is distinct from '[{"title":"Representational state transfer - Wikipedia","url":"https://en.wikipedia.org/wiki/REST"}]'::jsonb)) then raise exception 'Question fnet-007 ar content changed; create a new revision before seeding'; end if; end $$;
