insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي آلية مشاركة الموارد عبر الأصول (CORS) ولماذا يرسل المتصفح طلب Preflight من نوع OPTIONS تلقائياً؟', 'الـ CORS هي آلية أمان تطبقها المتصفحات لمنع مواقع خبيثة من قراءة بيانات موقعك، ويرسل المتصفح طلب Preflight استطلاعي بنوع OPTIONS للتأكد من موافقة السيرفر قبل إرسال الطلبات المعدلة أو المعقدة.', 'سياسة الأصل الواحد (Same-Origin Policy - SOP) تمنع السكريبت من نطاق foo.com من قراءة استجابة api.bar.com. إذا كان الطلب معقداً (يستخدم PUT/DELETE، أو ترويسات مخصصة مثل Authorization، أو Content-Type غير تقليدي مثل application/json)، يرسل المتصفح أولاً طلب OPTIONS يحتوي على Access-Control-Request-Method. إذا رد الخادم بترويسات قبول متوافقة (Access-Control-Allow-Origin)، يرسل المتصفح الطلب الفعلي، وإلا يمنعه ويرمي خطأ في الكونسول.', '// استجابة السيرفر المسموح بها:
Access-Control-Allow-Origin: https://myapp.com
Access-Control-Allow-Methods: GET, POST, PUT, DELETE
Access-Control-Allow-Headers: Authorization, Content-Type', '["وضع Access-Control-Allow-Origin: * جنباً إلى جنب مع السماح بملفات تعريف الارتباط credentials: true، وهو أمر يحظره المتصفح تماماً لأسباب أمنية."]'::jsonb, '["لماذا تفشل استدعاءات API من متصفح الويب بسبب CORS بينما تنجح نفس الاستدعاءات 100% من تطبيق الهاتف أو أداة Postman؟"]'::jsonb, '[{"title":"Cross-Origin Resource Sharing (CORS) - MDN","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي آلية مشاركة الموارد عبر الأصول (CORS) ولماذا يرسل المتصفح طلب Preflight من نوع OPTIONS تلقائياً؟' or l.short_answer is distinct from 'الـ CORS هي آلية أمان تطبقها المتصفحات لمنع مواقع خبيثة من قراءة بيانات موقعك، ويرسل المتصفح طلب Preflight استطلاعي بنوع OPTIONS للتأكد من موافقة السيرفر قبل إرسال الطلبات المعدلة أو المعقدة.' or l.explanation is distinct from 'سياسة الأصل الواحد (Same-Origin Policy - SOP) تمنع السكريبت من نطاق foo.com من قراءة استجابة api.bar.com. إذا كان الطلب معقداً (يستخدم PUT/DELETE، أو ترويسات مخصصة مثل Authorization، أو Content-Type غير تقليدي مثل application/json)، يرسل المتصفح أولاً طلب OPTIONS يحتوي على Access-Control-Request-Method. إذا رد الخادم بترويسات قبول متوافقة (Access-Control-Allow-Origin)، يرسل المتصفح الطلب الفعلي، وإلا يمنعه ويرمي خطأ في الكونسول.' or l.code_example is distinct from '// استجابة السيرفر المسموح بها:
Access-Control-Allow-Origin: https://myapp.com
Access-Control-Allow-Methods: GET, POST, PUT, DELETE
Access-Control-Allow-Headers: Authorization, Content-Type' or l.common_mistakes is distinct from '["وضع Access-Control-Allow-Origin: * جنباً إلى جنب مع السماح بملفات تعريف الارتباط credentials: true، وهو أمر يحظره المتصفح تماماً لأسباب أمنية."]'::jsonb or l.follow_up_questions is distinct from '["لماذا تفشل استدعاءات API من متصفح الويب بسبب CORS بينما تنجح نفس الاستدعاءات 100% من تطبيق الهاتف أو أداة Postman؟"]'::jsonb or l.sources is distinct from '[{"title":"Cross-Origin Resource Sharing (CORS) - MDN","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS"}]'::jsonb)) then raise exception 'Question fnet-008 ar content changed; create a new revision before seeding'; end if; end $$;
