insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحدث هجمات الرجل في المنتصف (MITM) وهجمات إغراق المزامنة (SYN Flood) وكيف تعمل تقنية SYN Cookies؟', 'تحدث هجمات MITM عند اعتراض وتعديل البيانات بين طرفين دون علمهما ويحميها التشفير والشهادات الموثوقة، وهجمات SYN Flood تغرق الخادم بطلبات اتصال وهمية لملء طابور الاتصالات واستنزاف موارده.', 'في هجوم SYN Flood، يرسل المهاجم ملايين حزم SYN بعناوين IP وهمية (Spoofed IPs)، فيرد الخادم بـ SYN-ACK وينتظر رد ACK النهائي واضعاً الاتصال في طابور نصف المكتمل (SYN Queue / Backlog). تمتلئ ذاكرة الخادم ويتوقف عن استقبال أي مستخدم حقيقي. تعالج تقنية SYN Cookies ذلك بعبقرية: لا يخصص الخادم أي ذاكرة على الإطلاق في البداية! بل يشفر بيانات الاتصال والوقت في الرقم التسلسلي المبدئي (Initial Sequence Number)، وعندما يرد العميل الشرعي بـ ACK، يتحقق الخادم من صحة التشفير حسابياً ويفتح الاتصال فوراً.', '// SYN Cookies تشفر حالة الاتصال رياضياً داخل Sequence Number بدلاً من حجز ذاكرة الخادم', '["تعطيل فحص الشهادات الرقمية (SSL Verification) في بيئة التطوير ونسيان إعادة تفعيله في الإنتاج، مما يجعل التطبيق عرضة فورية لاختراق MITM."]'::jsonb, '["كيف تحمي شبكات Anycast وموزعات الحماية العالمية مثل Cloudflare من هجمات الحرمان من الخدمة الموزعة (DDoS)؟"]'::jsonb, '[{"title":"SYN cookies - Wikipedia","url":"https://en.wikipedia.org/wiki/SYN_cookies"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تحدث هجمات الرجل في المنتصف (MITM) وهجمات إغراق المزامنة (SYN Flood) وكيف تعمل تقنية SYN Cookies؟' or l.short_answer is distinct from 'تحدث هجمات MITM عند اعتراض وتعديل البيانات بين طرفين دون علمهما ويحميها التشفير والشهادات الموثوقة، وهجمات SYN Flood تغرق الخادم بطلبات اتصال وهمية لملء طابور الاتصالات واستنزاف موارده.' or l.explanation is distinct from 'في هجوم SYN Flood، يرسل المهاجم ملايين حزم SYN بعناوين IP وهمية (Spoofed IPs)، فيرد الخادم بـ SYN-ACK وينتظر رد ACK النهائي واضعاً الاتصال في طابور نصف المكتمل (SYN Queue / Backlog). تمتلئ ذاكرة الخادم ويتوقف عن استقبال أي مستخدم حقيقي. تعالج تقنية SYN Cookies ذلك بعبقرية: لا يخصص الخادم أي ذاكرة على الإطلاق في البداية! بل يشفر بيانات الاتصال والوقت في الرقم التسلسلي المبدئي (Initial Sequence Number)، وعندما يرد العميل الشرعي بـ ACK، يتحقق الخادم من صحة التشفير حسابياً ويفتح الاتصال فوراً.' or l.code_example is distinct from '// SYN Cookies تشفر حالة الاتصال رياضياً داخل Sequence Number بدلاً من حجز ذاكرة الخادم' or l.common_mistakes is distinct from '["تعطيل فحص الشهادات الرقمية (SSL Verification) في بيئة التطوير ونسيان إعادة تفعيله في الإنتاج، مما يجعل التطبيق عرضة فورية لاختراق MITM."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحمي شبكات Anycast وموزعات الحماية العالمية مثل Cloudflare من هجمات الحرمان من الخدمة الموزعة (DDoS)؟"]'::jsonb or l.sources is distinct from '[{"title":"SYN cookies - Wikipedia","url":"https://en.wikipedia.org/wiki/SYN_cookies"}]'::jsonb)) then raise exception 'Question fnet-009 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Networking Security Mitm Syn Flood Ddos?', 'This question checks the core Networking Security Mitm Syn Flood Ddos concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Networking Security Mitm Syn Flood Ddos with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// SYN Cookies تشفر حالة الاتصال رياضياً داخل Sequence Number بدلاً من حجز ذاكرة الخادم', '["Missing the key trade-off in Networking Security Mitm Syn Flood Ddos (point 1)."]'::jsonb, '["How would you apply Networking Security Mitm Syn Flood Ddos in a production Software Engineering app (follow-up 1)?"]'::jsonb, '[{"title":"SYN cookies - Wikipedia","url":"https://en.wikipedia.org/wiki/SYN_cookies"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
