insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تعمل شبكات توصيل المحتوى (CDNs) وكيف توجه تقنية Anycast Routing المستخدمين لأقرب خادم حافة (Edge Server)؟', 'توزع الـ CDNs المحتوى الثابت والوسائط جغرافياً على مئات الخوادم المحيطة بالمستخدمين؛ وتعلن تقنية Anycast عن نفس عنوان الـ IP من عشرات المواقع عالمياً ليوجه بروتوكول BGP الزائر لأقرب نقطة بأقل زمن تأخير.', 'في التوجيه التقليدي (Unicast)، يملك السيرفر عنوان IP فريد في مكان واحد، مما يعني أن مستخدم اليابان سيعاني من تأخير 250 مللي ثانية للوصول لخادم في نيويورك. باستخدام Anycast وشبكات CDN (مثل Cloudflare و Fastly)، يعلن كل خادم حافة محلي عن نفس الـ IP، فتقوم راوترات الإنترنت بتوجيه حزم المستخدم لأقرب سيرفر على بعد بضعة كيلومترات (Edge Node) في 5 مللي ثانية فقط، مما يخفف الحمل عن الخادم الأصلي (Origin) بنسبة 90% ويوفر حماية ضخمة ضد هجمات الـ DDoS.', '// المستخدم يطلب الصورة -> يتصل بـ Anycast Edge محلي في ثوان -> إن كانت في الكاش تُسلم فوراً
// إن لم تكن في الكاش -> يجلبها الحافة من الـ Origin مرة واحدة ويخزنها للبقية', '["نسيان إضافة ترويسات Cache-Control: no-cache لملفات HTML أو نقاط الـ API الحساسة، مما يؤدي لتخزين بيانات شخصية للعملاء وتوزيعها لزوار آخرين عبر الـ CDN."]'::jsonb, '["كيف تعمل ميزة Edge Functions و Cloudflare Workers لتنفيذ كود برمجي عند الحافة بالقرب من المستخدم؟"]'::jsonb, '[{"title":"Content delivery network - Wikipedia","url":"https://en.wikipedia.org/wiki/Content_delivery_network"}]'::jsonb from public.question_revisions r where r.question_id = 'fnet-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fnet-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تعمل شبكات توصيل المحتوى (CDNs) وكيف توجه تقنية Anycast Routing المستخدمين لأقرب خادم حافة (Edge Server)؟' or l.short_answer is distinct from 'توزع الـ CDNs المحتوى الثابت والوسائط جغرافياً على مئات الخوادم المحيطة بالمستخدمين؛ وتعلن تقنية Anycast عن نفس عنوان الـ IP من عشرات المواقع عالمياً ليوجه بروتوكول BGP الزائر لأقرب نقطة بأقل زمن تأخير.' or l.explanation is distinct from 'في التوجيه التقليدي (Unicast)، يملك السيرفر عنوان IP فريد في مكان واحد، مما يعني أن مستخدم اليابان سيعاني من تأخير 250 مللي ثانية للوصول لخادم في نيويورك. باستخدام Anycast وشبكات CDN (مثل Cloudflare و Fastly)، يعلن كل خادم حافة محلي عن نفس الـ IP، فتقوم راوترات الإنترنت بتوجيه حزم المستخدم لأقرب سيرفر على بعد بضعة كيلومترات (Edge Node) في 5 مللي ثانية فقط، مما يخفف الحمل عن الخادم الأصلي (Origin) بنسبة 90% ويوفر حماية ضخمة ضد هجمات الـ DDoS.' or l.code_example is distinct from '// المستخدم يطلب الصورة -> يتصل بـ Anycast Edge محلي في ثوان -> إن كانت في الكاش تُسلم فوراً
// إن لم تكن في الكاش -> يجلبها الحافة من الـ Origin مرة واحدة ويخزنها للبقية' or l.common_mistakes is distinct from '["نسيان إضافة ترويسات Cache-Control: no-cache لملفات HTML أو نقاط الـ API الحساسة، مما يؤدي لتخزين بيانات شخصية للعملاء وتوزيعها لزوار آخرين عبر الـ CDN."]'::jsonb or l.follow_up_questions is distinct from '["كيف تعمل ميزة Edge Functions و Cloudflare Workers لتنفيذ كود برمجي عند الحافة بالقرب من المستخدم؟"]'::jsonb or l.sources is distinct from '[{"title":"Content delivery network - Wikipedia","url":"https://en.wikipedia.org/wiki/Content_delivery_network"}]'::jsonb)) then raise exception 'Question fnet-010 ar content changed; create a new revision before seeding'; end if; end $$;
