insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو هرم الاختبارات (The Test Pyramid) وما هو التوازن المثالي بين اختبارات الوحدة، التكامل، والاختبارات الشاملة (E2E)؟', 'يقترح هرم الاختبارات قاعدة عريضة من اختبارات الوحدة السريعة والرخيصة في الأسفل، تليها اختبارات التكامل في المنتصف، وقمة مدببة من الاختبارات الشاملة (E2E) المعقدة والبطيئة.', 'اختبارات الوحدة (Unit Tests) تختبر دوال وفئات معزولة بالميكروثانية وتمنح تشخيصاً لحظياً دقيقاً لمكان الخطأ ورخيصة الصيانة. اختبارات التكامل (Integration Tests) تتحقق من سلامة تفاعل عدة مكونات حقيقية معاً (مثل الخدمة مع قاعدة البيانات). أما اختبارات E2E فتحاكي المستخدم الحقيقي في المتصفح؛ وهي ممتازة لزرع الثقة قبل الشحن ولكنها بطيئة جداً ومكلفة وعرضة للاهتزاز (Flakiness). الاعتماد على هرم مقلوب (Ice Cream Cone Anti-pattern) يقتل سرعة فرق التطوير.', '// Test Pyramid:
//       /\    E2E (بطيء، مكلف، ثقة شاملة)
//      /  \   Integration (متوسط السرعة والتكلفة)
//     /____\  Unit Tests (فائق السرعة، رخيص، تغطية شاملة)', '["كتابة معظم الاختبارات كـ E2E متجاهلين اختبارات الوحدة، مما يجعل بناء الـ CI/CD يستغرق ساعات طويلة ويفشل عشوائياً."]'::jsonb, '["ما هو نموذج قرص العسل (Testing Honeycomb) المفضل في بنية المايكروسيرفس بدلاً من الهرم التقليدي؟"]'::jsonb, '[{"title":"Martin Fowler — The Practical Test Pyramid","url":"https://martinfowler.com/articles/practical-test-pyramid.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو هرم الاختبارات (The Test Pyramid) وما هو التوازن المثالي بين اختبارات الوحدة، التكامل، والاختبارات الشاملة (E2E)؟' or l.short_answer is distinct from 'يقترح هرم الاختبارات قاعدة عريضة من اختبارات الوحدة السريعة والرخيصة في الأسفل، تليها اختبارات التكامل في المنتصف، وقمة مدببة من الاختبارات الشاملة (E2E) المعقدة والبطيئة.' or l.explanation is distinct from 'اختبارات الوحدة (Unit Tests) تختبر دوال وفئات معزولة بالميكروثانية وتمنح تشخيصاً لحظياً دقيقاً لمكان الخطأ ورخيصة الصيانة. اختبارات التكامل (Integration Tests) تتحقق من سلامة تفاعل عدة مكونات حقيقية معاً (مثل الخدمة مع قاعدة البيانات). أما اختبارات E2E فتحاكي المستخدم الحقيقي في المتصفح؛ وهي ممتازة لزرع الثقة قبل الشحن ولكنها بطيئة جداً ومكلفة وعرضة للاهتزاز (Flakiness). الاعتماد على هرم مقلوب (Ice Cream Cone Anti-pattern) يقتل سرعة فرق التطوير.' or l.code_example is distinct from '// Test Pyramid:
//       /\    E2E (بطيء، مكلف، ثقة شاملة)
//      /  \   Integration (متوسط السرعة والتكلفة)
//     /____\  Unit Tests (فائق السرعة، رخيص، تغطية شاملة)' or l.common_mistakes is distinct from '["كتابة معظم الاختبارات كـ E2E متجاهلين اختبارات الوحدة، مما يجعل بناء الـ CI/CD يستغرق ساعات طويلة ويفشل عشوائياً."]'::jsonb or l.follow_up_questions is distinct from '["ما هو نموذج قرص العسل (Testing Honeycomb) المفضل في بنية المايكروسيرفس بدلاً من الهرم التقليدي؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — The Practical Test Pyramid","url":"https://martinfowler.com/articles/practical-test-pyramid.html"}]'::jsonb)) then raise exception 'Question ftst-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Testing Pyramid Unit Integration E2e Cost Ratio?', 'This question checks the core Testing Pyramid Unit Integration E2e Cost Ratio concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Testing Pyramid Unit Integration E2e Cost Ratio with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// Test Pyramid:
