insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الدورة الثلاثية للتطوير الموجه بالاختبارات (TDD: Red-Green-Refactor) وما هي ميزتها التصميمية وليست الاختبارية فقط؟', 'تبدأ بكتابة اختبار صغير يفشل أولاً (Red)، ثم كتابة أقل كود كافٍ لنجاح الاختبار (Green)، ثم إعادة تحسين وهيكلة الكود وتنظيفه مع ضمان بقاء الاختبار ناجحاً (Refactor).', 'الميزة الكبرى لـ TDD ليست مجرد فحص الأخطاء، بل هي أداة تصميم هندسي (Design Feedback Tool). عندما تكتب الاختبار قبل الكود، فإنك تجبر نفسك على التفكير كمستخدم للواجهة البرمجية (API Consumer) وليس كصانع لها، مما ينتج واجهات بديهية وسهلة الاستخدام ووحدات مفكوكة الارتباط بطبيعتها وقابلة للاختبار (Testable by design).', '// 1. Red: اكتب اختباراً يستدعي دالة غير موجودة بعد -> يفشل
// 2. Green: اكتب الدالة بأبسط شكل ممكن حتى يمر الاختبار
// 3. Refactor: أزل التكرار وحسن التسميات ونظم الكود مع الحفاظ على اللون الأخضر', '["تجاهل خطوة الـ Refactor بعد النجاح (Green) والقفز للمهمة التالية، مما يترك الكود مليئاً بالترقيعات السريعة وتراكم الديون الفنية."]'::jsonb, '["ما الفرق بين أسلوب مدرسة شيكاغو (Classicist/Detroit TDD) ومدرسة لندن (Mockist/London TDD)؟"]'::jsonb, '[{"title":"Test-driven development - Wikipedia","url":"https://en.wikipedia.org/wiki/Test-driven_development"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الدورة الثلاثية للتطوير الموجه بالاختبارات (TDD: Red-Green-Refactor) وما هي ميزتها التصميمية وليست الاختبارية فقط؟' or l.short_answer is distinct from 'تبدأ بكتابة اختبار صغير يفشل أولاً (Red)، ثم كتابة أقل كود كافٍ لنجاح الاختبار (Green)، ثم إعادة تحسين وهيكلة الكود وتنظيفه مع ضمان بقاء الاختبار ناجحاً (Refactor).' or l.explanation is distinct from 'الميزة الكبرى لـ TDD ليست مجرد فحص الأخطاء، بل هي أداة تصميم هندسي (Design Feedback Tool). عندما تكتب الاختبار قبل الكود، فإنك تجبر نفسك على التفكير كمستخدم للواجهة البرمجية (API Consumer) وليس كصانع لها، مما ينتج واجهات بديهية وسهلة الاستخدام ووحدات مفكوكة الارتباط بطبيعتها وقابلة للاختبار (Testable by design).' or l.code_example is distinct from '// 1. Red: اكتب اختباراً يستدعي دالة غير موجودة بعد -> يفشل
// 2. Green: اكتب الدالة بأبسط شكل ممكن حتى يمر الاختبار
// 3. Refactor: أزل التكرار وحسن التسميات ونظم الكود مع الحفاظ على اللون الأخضر' or l.common_mistakes is distinct from '["تجاهل خطوة الـ Refactor بعد النجاح (Green) والقفز للمهمة التالية، مما يترك الكود مليئاً بالترقيعات السريعة وتراكم الديون الفنية."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين أسلوب مدرسة شيكاغو (Classicist/Detroit TDD) ومدرسة لندن (Mockist/London TDD)؟"]'::jsonb or l.sources is distinct from '[{"title":"Test-driven development - Wikipedia","url":"https://en.wikipedia.org/wiki/Test-driven_development"}]'::jsonb)) then raise exception 'Question ftst-002 ar content changed; create a new revision before seeding'; end if; end $$;
