insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح تصنيف بدلاء الاختبار (Test Doubles) بحسب جيرارد ميسزاروس: ما الفرق بين Dummy و Stub و Fake و Mock و Spy؟', 'البدلاء هم كائنات تُستبدل في الاختبار بالتبعية الحقيقية: الـ Dummy لملء البارامترات فقط، والـ Stub يعيد إجابات ثابتة معدة مسبقاً، والـ Spy يسجل معلومات الاستدعاءات، والـ Mock يضع توقعات ويتحقق من السلوك، والـ Fake تطبيق حقيقي خفيف كقاعدة بيانات في الذاكرة.', 'الـ Dummy مثل كائن فارغ يُمرر لدالة تطلب 3 معاملات وأنت تحتاج واحداً فقط. الـ Stub يعيد دوماً true عند استدعاء isValid(). الـ Spy يراقب ويسجل: كم مرة استُدعيت دالة sendEmail() وما هي المعاملات التي مُررت لها. الـ Mock يحدد الشروط مسبقاً: ''أتوقع استدعاء save() مرة واحدة بالضبط''، ويفشل الاختبار إذا لم يُستدع. أما الـ Fake فهو تنفيذ يعمل بالكامل لكنه مبسط ولا يناسب الإنتاج، مثل فئة InMemoryUserRepository.', '// Fake: تطبيق شغال بالكامل في الذاكرة بدون قاعدة بيانات حقيقية
class FakeUserRepository implements UserRepository {
  private users = new Map<string, User>();
  async save(u: User) { this.users.set(u.id, u); }
  async findById(id: string) { return this.users.get(id) ?? null; }
}', '["الإفراط في استخدام الـ Mocks للتحقق من تفاصيل التنفيذ الداخلي للدوال بدلاً من التحقق من المخرجات والنتائج النهائية (State Verification vs Interaction Verification)."]'::jsonb, '["لماذا يفضل مارتن فاولر استخدام الـ Fakes على الـ Mocks لتفادي كسر الاختبارات عند كل Refactoring بسيط؟"]'::jsonb, '[{"title":"Martin Fowler — TestDouble","url":"https://martinfowler.com/bliki/TestDouble.html"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'اشرح تصنيف بدلاء الاختبار (Test Doubles) بحسب جيرارد ميسزاروس: ما الفرق بين Dummy و Stub و Fake و Mock و Spy؟' or l.short_answer is distinct from 'البدلاء هم كائنات تُستبدل في الاختبار بالتبعية الحقيقية: الـ Dummy لملء البارامترات فقط، والـ Stub يعيد إجابات ثابتة معدة مسبقاً، والـ Spy يسجل معلومات الاستدعاءات، والـ Mock يضع توقعات ويتحقق من السلوك، والـ Fake تطبيق حقيقي خفيف كقاعدة بيانات في الذاكرة.' or l.explanation is distinct from 'الـ Dummy مثل كائن فارغ يُمرر لدالة تطلب 3 معاملات وأنت تحتاج واحداً فقط. الـ Stub يعيد دوماً true عند استدعاء isValid(). الـ Spy يراقب ويسجل: كم مرة استُدعيت دالة sendEmail() وما هي المعاملات التي مُررت لها. الـ Mock يحدد الشروط مسبقاً: ''أتوقع استدعاء save() مرة واحدة بالضبط''، ويفشل الاختبار إذا لم يُستدع. أما الـ Fake فهو تنفيذ يعمل بالكامل لكنه مبسط ولا يناسب الإنتاج، مثل فئة InMemoryUserRepository.' or l.code_example is distinct from '// Fake: تطبيق شغال بالكامل في الذاكرة بدون قاعدة بيانات حقيقية
class FakeUserRepository implements UserRepository {
  private users = new Map<string, User>();
  async save(u: User) { this.users.set(u.id, u); }
  async findById(id: string) { return this.users.get(id) ?? null; }
}' or l.common_mistakes is distinct from '["الإفراط في استخدام الـ Mocks للتحقق من تفاصيل التنفيذ الداخلي للدوال بدلاً من التحقق من المخرجات والنتائج النهائية (State Verification vs Interaction Verification)."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يفضل مارتن فاولر استخدام الـ Fakes على الـ Mocks لتفادي كسر الاختبارات عند كل Refactoring بسيط؟"]'::jsonb or l.sources is distinct from '[{"title":"Martin Fowler — TestDouble","url":"https://martinfowler.com/bliki/TestDouble.html"}]'::jsonb)) then raise exception 'Question ftst-003 ar content changed; create a new revision before seeding'; end if; end $$;
