insert into public.interview_questions (id, slug, track_id, difficulty) values ('ftst-004', 'testing-first-principles-unit-testing', 'fundamentals', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('ftst-004', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مبادئ F.I.R.S.T الخمسة لكتابة اختبارات وحدة احترافية وموثوقة؟', 'المبادئ هي: سريعة (Fast)، مستقلة (Independent)، قابلة للتكرار في أي بيئة (Repeatable)، ذاتية التحقق والنتيجة (Self-Validating)، وتُكتب في الوقت المناسب (Timely).', 'سريعة: يجب أن تعمل آلاف الاختبارات في ثوان لكي يكررها المطور مع كل تغيير. مستقلة: لا يجوز أن يعتمد اختبار على ناتج أو ترتيب اختبار آخر، وأي اختبار يجب أن يعمل منفرداً بنجاح. قابلة للتكرار: تنجح على جهاز المطور، على سيرفر الـ CI، وبدون اتصال بالإنترنت في أي وقت. ذاتية التحقق: ترجع نتيجة واضحة إما Pass أو Fail دون الحاجة لقراءة ملفات سجل أو فحص يدوي. مكتوبة في الوقت المناسب: تُكتب أثناء أو قبل كتابة كود الميزة وليس بعد أشهر من نسيان التفاصيل.', '// اختبار مستقل وسريع وذاتي التحقق:
test(''calculates discount correctly'', () => {
  const cart = new Cart();
  cart.add(new Item(100));
  expect(cart.totalWithDiscount(0.1)).toBe(90);
});', '["كتابة اختبارات تعتمد على وجود سجل معين في قاعدة بيانات مشتركة أنشأه اختبار سابق، مما يسبب فشلها عند التشغيل المتوازي."]'::jsonb, '["ما هي مشكلة الاختبارات المتسربة (Shared State Leaks) وكيف تعالجها دوال beforeEach و afterEach؟"]'::jsonb, '[{"title":"F.I.R.S.T principles of testing","url":"https://en.wikipedia.org/wiki/Unit_testing"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي مبادئ F.I.R.S.T الخمسة لكتابة اختبارات وحدة احترافية وموثوقة؟' or l.short_answer is distinct from 'المبادئ هي: سريعة (Fast)، مستقلة (Independent)، قابلة للتكرار في أي بيئة (Repeatable)، ذاتية التحقق والنتيجة (Self-Validating)، وتُكتب في الوقت المناسب (Timely).' or l.explanation is distinct from 'سريعة: يجب أن تعمل آلاف الاختبارات في ثوان لكي يكررها المطور مع كل تغيير. مستقلة: لا يجوز أن يعتمد اختبار على ناتج أو ترتيب اختبار آخر، وأي اختبار يجب أن يعمل منفرداً بنجاح. قابلة للتكرار: تنجح على جهاز المطور، على سيرفر الـ CI، وبدون اتصال بالإنترنت في أي وقت. ذاتية التحقق: ترجع نتيجة واضحة إما Pass أو Fail دون الحاجة لقراءة ملفات سجل أو فحص يدوي. مكتوبة في الوقت المناسب: تُكتب أثناء أو قبل كتابة كود الميزة وليس بعد أشهر من نسيان التفاصيل.' or l.code_example is distinct from '// اختبار مستقل وسريع وذاتي التحقق:
test(''calculates discount correctly'', () => {
  const cart = new Cart();
  cart.add(new Item(100));
  expect(cart.totalWithDiscount(0.1)).toBe(90);
});' or l.common_mistakes is distinct from '["كتابة اختبارات تعتمد على وجود سجل معين في قاعدة بيانات مشتركة أنشأه اختبار سابق، مما يسبب فشلها عند التشغيل المتوازي."]'::jsonb or l.follow_up_questions is distinct from '["ما هي مشكلة الاختبارات المتسربة (Shared State Leaks) وكيف تعالجها دوال beforeEach و afterEach؟"]'::jsonb or l.sources is distinct from '[{"title":"F.I.R.S.T principles of testing","url":"https://en.wikipedia.org/wiki/Unit_testing"}]'::jsonb)) then raise exception 'Question ftst-004 ar content changed; create a new revision before seeding'; end if; end $$;
