insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تعتبر نسبة تغطية الكود (Code Coverage) مقياساً مضللاً أحياناً وما هي اختبارات الطفرات (Mutation Testing)؟', 'تغطية الكود تقيس فقط الأسطر التي مر عليها التنفيذ دون التحقق من جودة وصحة الـ Assertions؛ بينما تقوم اختبارات الطفرات بحقن أخطاء متعمدة في الشفرة وتفحص قدرة الاختبارات على اكتشافها وقتلها (Kill Mutants).', 'يمكنك بسهولة الحصول على تغطية 100% بكتابة اختبار يستدعي كل الدوال دون كتابة سطر assert واحد! أدوات Mutation Testing (مثل Stryker أو Pitest) تقوم بتغيير الرموز في الكود المصدري سراً (تغيير > إلى <، حذف استدعاء دالة، أو استبدال true بـ false). إذا ظل الاختبار ناجحاً بعد هذا التغيير الخبيث، فهذا دليل على نجاة الطافرة (Survived Mutant) وضعف الاختبار وعدم فاعليته.', '// إذا غيرت أداة الطفرات: if (age >= 18) إلى if (age > 18)
// ونجح الاختبار، فهذا يعني أن اختباراتك لم تغط حالة الحافة (Edge Case) عند age === 18!', '["اشتراط نسبة تغطية 100% في مسار الـ CI كهدف إداري، مما يدفع المطورين لكتابة اختبارات شكلية فارغة من الفحص الحقيقي لإرضاء النسبة فقط."]'::jsonb, '["ما هي مقاييس Branch Coverage و Path Coverage وكيف تتفوق على Line Coverage البسيطة؟"]'::jsonb, '[{"title":"Mutation testing - Wikipedia","url":"https://en.wikipedia.org/wiki/Mutation_testing"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تعتبر نسبة تغطية الكود (Code Coverage) مقياساً مضللاً أحياناً وما هي اختبارات الطفرات (Mutation Testing)؟' or l.short_answer is distinct from 'تغطية الكود تقيس فقط الأسطر التي مر عليها التنفيذ دون التحقق من جودة وصحة الـ Assertions؛ بينما تقوم اختبارات الطفرات بحقن أخطاء متعمدة في الشفرة وتفحص قدرة الاختبارات على اكتشافها وقتلها (Kill Mutants).' or l.explanation is distinct from 'يمكنك بسهولة الحصول على تغطية 100% بكتابة اختبار يستدعي كل الدوال دون كتابة سطر assert واحد! أدوات Mutation Testing (مثل Stryker أو Pitest) تقوم بتغيير الرموز في الكود المصدري سراً (تغيير > إلى <، حذف استدعاء دالة، أو استبدال true بـ false). إذا ظل الاختبار ناجحاً بعد هذا التغيير الخبيث، فهذا دليل على نجاة الطافرة (Survived Mutant) وضعف الاختبار وعدم فاعليته.' or l.code_example is distinct from '// إذا غيرت أداة الطفرات: if (age >= 18) إلى if (age > 18)
// ونجح الاختبار، فهذا يعني أن اختباراتك لم تغط حالة الحافة (Edge Case) عند age === 18!' or l.common_mistakes is distinct from '["اشتراط نسبة تغطية 100% في مسار الـ CI كهدف إداري، مما يدفع المطورين لكتابة اختبارات شكلية فارغة من الفحص الحقيقي لإرضاء النسبة فقط."]'::jsonb or l.follow_up_questions is distinct from '["ما هي مقاييس Branch Coverage و Path Coverage وكيف تتفوق على Line Coverage البسيطة؟"]'::jsonb or l.sources is distinct from '[{"title":"Mutation testing - Wikipedia","url":"https://en.wikipedia.org/wiki/Mutation_testing"}]'::jsonb)) then raise exception 'Question ftst-005 ar content changed; create a new revision before seeding'; end if; end $$;
