insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الاختبارات المتقلبة (Flaky Tests) وما هي أسبابها الجذرية وكيف تقضي عليها في بيئات الـ CI/CD؟', 'هي الاختبارات التي تنجح وتفشل عشوائياً لنفس الكود دون أي تغيير؛ وتنتج عادة عن الاعتماد على توقيتات غير متزامنة، حالات مشتركة بين الاختبارات، أو تقلبات الاتصال الخارجي والشبكة.', 'تعتبر الاختبارات المتقلبة سماً قاتلاً لثقة الفريق؛ لأن المطورين يبدأون في تجاهل فشل الـ CI والضغط على زر ''Re-run'' حتى يمر الاختبار صدفة. الأسباب وعلاجها: (1) استخدام sleep/delay زمني ثابت بدلاً من انتظار الشروط صراحة (Await Polling / waitFor). (2) بقاء بيانات في الذاكرة أو قاعدة البيانات بين الاختبارات وعلاجها بالتنظيف التام بعد كل اختبار. (3) التبعيات على خدمات خارجية واستبدالها بـ Mocks ومحاكيات محلية (مثل WireMock / Testcontainers).', '// خطأ يسبب Flakiness:
await sleep(1000); expect(result).toBeReady();
// كود قوي ومستقر:
await waitFor(() => expect(result).toBeReady(), { timeout: 5000 });', '["إخفاء مشكلة الاختبار المتقلب بإضافة إعادة محاولة آلية (Auto-retry 3 times) في إعدادات الـ CI بدلاً من إصلاح السبب الجذري للسباق في التزامن."]'::jsonb, '["ما هي استراتيجية الحجر الصحي للاختبارات (Test Quarantine) لحماية الفروع الرئيسية من الإيقاف العشوائي؟"]'::jsonb, '[{"title":"Flaky tests in software engineering","url":"https://en.wikipedia.org/wiki/Flaky_test"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الاختبارات المتقلبة (Flaky Tests) وما هي أسبابها الجذرية وكيف تقضي عليها في بيئات الـ CI/CD؟' or l.short_answer is distinct from 'هي الاختبارات التي تنجح وتفشل عشوائياً لنفس الكود دون أي تغيير؛ وتنتج عادة عن الاعتماد على توقيتات غير متزامنة، حالات مشتركة بين الاختبارات، أو تقلبات الاتصال الخارجي والشبكة.' or l.explanation is distinct from 'تعتبر الاختبارات المتقلبة سماً قاتلاً لثقة الفريق؛ لأن المطورين يبدأون في تجاهل فشل الـ CI والضغط على زر ''Re-run'' حتى يمر الاختبار صدفة. الأسباب وعلاجها: (1) استخدام sleep/delay زمني ثابت بدلاً من انتظار الشروط صراحة (Await Polling / waitFor). (2) بقاء بيانات في الذاكرة أو قاعدة البيانات بين الاختبارات وعلاجها بالتنظيف التام بعد كل اختبار. (3) التبعيات على خدمات خارجية واستبدالها بـ Mocks ومحاكيات محلية (مثل WireMock / Testcontainers).' or l.code_example is distinct from '// خطأ يسبب Flakiness:
await sleep(1000); expect(result).toBeReady();
// كود قوي ومستقر:
await waitFor(() => expect(result).toBeReady(), { timeout: 5000 });' or l.common_mistakes is distinct from '["إخفاء مشكلة الاختبار المتقلب بإضافة إعادة محاولة آلية (Auto-retry 3 times) في إعدادات الـ CI بدلاً من إصلاح السبب الجذري للسباق في التزامن."]'::jsonb or l.follow_up_questions is distinct from '["ما هي استراتيجية الحجر الصحي للاختبارات (Test Quarantine) لحماية الفروع الرئيسية من الإيقاف العشوائي؟"]'::jsonb or l.sources is distinct from '[{"title":"Flaky tests in software engineering","url":"https://en.wikipedia.org/wiki/Flaky_test"}]'::jsonb)) then raise exception 'Question ftst-006 ar content changed; create a new revision before seeding'; end if; end $$;
