insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الاختبار القائم على الخصائص (Property-Based Testing) وكيف يكشف حالات الحافة المجهولة مقارنة بالاختبار القائم على الأمثلة؟', 'بدلاً من فحص أمثلة ومدخلات محددة يكتبها المبرمج يدوياً، يحدد المبرمج خصائص عامة صادقة دائماً (Invariants) وتقوم أداة الاختبار بتوليد مئات الآلاف من المدخلات العشوائية والمتطرفة لاكتشاف أي كسر لتلك الخصائص.', 'في Example-based Testing، تفحص: sort([3, 1, 2]) == [1, 2, 3]. في Property-based Testing (مثل مكتبات QuickCheck أو Fast-Check)، نحدد الخصائص: (1) طول المصفوفة المرتبة يجب أن يطابق المصفوفة الأصلية. (2) كل عنصر يجب أن يكون <= العنصر التالي له. (3) كل عنصر في المصفوفة الأصلية موجود في الناتجة. تقوم الأداة بتوليد مصفوفات فارغة، سالبة، ضخمة، أو مكررة، وإذا وجدت خطأً، تقوم بتقليص المدخلات (Shrinking) للوصول لأصغر مدخل يسبب الانهيار.', '// خاصية الانعكاس في فك وضغط البيانات (Roundtrip property):
// forall x: decompress(compress(x)) === x', '["الاعتماد فقط على الأمثلة الإيجابية السعيدة (Happy Path) وتجاهل القيم القصوى والرموز الخاصة والأرقام السالبة والقيم الفارغة."]'::jsonb, '["كيف تساعد عملية التقليص (Shrinking) المبرمج في فهم سبب الخطأ العشوائي في ثوان معدودة؟"]'::jsonb, '[{"title":"Property-based testing - Wikipedia","url":"https://en.wikipedia.org/wiki/QuickCheck"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الاختبار القائم على الخصائص (Property-Based Testing) وكيف يكشف حالات الحافة المجهولة مقارنة بالاختبار القائم على الأمثلة؟' or l.short_answer is distinct from 'بدلاً من فحص أمثلة ومدخلات محددة يكتبها المبرمج يدوياً، يحدد المبرمج خصائص عامة صادقة دائماً (Invariants) وتقوم أداة الاختبار بتوليد مئات الآلاف من المدخلات العشوائية والمتطرفة لاكتشاف أي كسر لتلك الخصائص.' or l.explanation is distinct from 'في Example-based Testing، تفحص: sort([3, 1, 2]) == [1, 2, 3]. في Property-based Testing (مثل مكتبات QuickCheck أو Fast-Check)، نحدد الخصائص: (1) طول المصفوفة المرتبة يجب أن يطابق المصفوفة الأصلية. (2) كل عنصر يجب أن يكون <= العنصر التالي له. (3) كل عنصر في المصفوفة الأصلية موجود في الناتجة. تقوم الأداة بتوليد مصفوفات فارغة، سالبة، ضخمة، أو مكررة، وإذا وجدت خطأً، تقوم بتقليص المدخلات (Shrinking) للوصول لأصغر مدخل يسبب الانهيار.' or l.code_example is distinct from '// خاصية الانعكاس في فك وضغط البيانات (Roundtrip property):
// forall x: decompress(compress(x)) === x' or l.common_mistakes is distinct from '["الاعتماد فقط على الأمثلة الإيجابية السعيدة (Happy Path) وتجاهل القيم القصوى والرموز الخاصة والأرقام السالبة والقيم الفارغة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساعد عملية التقليص (Shrinking) المبرمج في فهم سبب الخطأ العشوائي في ثوان معدودة؟"]'::jsonb or l.sources is distinct from '[{"title":"Property-based testing - Wikipedia","url":"https://en.wikipedia.org/wiki/QuickCheck"}]'::jsonb)) then raise exception 'Question ftst-007 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Testing Property Based Testing Vs Example Based?', 'This question checks the core Testing Property Based Testing Vs Example Based concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Testing Property Based Testing Vs Example Based with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// خاصية الانعكاس في فك وضغط البيانات (Roundtrip property):
// forall x: decompress(compress(x)) === x', '["Missing the key trade-off in Testing Property Based Testing Vs Example Based (point 1)."]'::jsonb, '["How would you apply Testing Property Based Testing Vs Example Based in a production Software Engineering app (follow-up 1)?"]'::jsonb, '[{"title":"Property-based testing - Wikipedia","url":"https://en.wikipedia.org/wiki/QuickCheck"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-007' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a Software developer know about Testing Property Based Testing Vs Example Based?' or l.short_answer is distinct from 'This question checks the core Testing Property Based Testing Vs Example Based concept and how to use it safely in Computer Science, Software Engineering, and architecture.' or l.explanation is distinct from 'Explain Testing Property Based Testing Vs Example Based with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from '// خاصية الانعكاس في فك وضغط البيانات (Roundtrip property):
// forall x: decompress(compress(x)) === x' or l.common_mistakes is distinct from '["Missing the key trade-off in Testing Property Based Testing Vs Example Based (point 1)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Testing Property Based Testing Vs Example Based in a production Software Engineering app (follow-up 1)?"]'::jsonb or l.sources is distinct from '[{"title":"Property-based testing - Wikipedia","url":"https://en.wikipedia.org/wiki/QuickCheck"}]'::jsonb)) then raise exception 'Question ftst-007 en content changed; create a new revision before seeding'; end if; end $$;
