insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو التطوير الموجه بالسلوك (Behavior-Driven Development - BDD) وصيغة Given-When-Then؟', 'هو تطور لـ TDD يهدف لتوحيد لغة التواصل بين المطورين ومحللي الأعمال باستخدام لغة دومين موحدة (Ubiquitous Language)، مع صياغة سيناريوهات الاختبار بصيغة Given (السياق) و When (الحدث) و Then (النتيجة المتوقعة).', 'تساعد صيغة Given-When-Then في جعل مواصفات الاختبار مفهومة لجميع الأطراف المعنية (مثل استخدام ملفات Gherkin في أدوات Cucumber). تصف Given الحالة الابتدائية للنظام (المستخدم مسجل دخول ورصيده 100)، وتصف When الإجراء الذي اتخذه المستخدم (قام بسحب 40)، وتصف Then الحالة النهائية للنظام (يصبح رصيده 60 ويتم إصدار إشعار بالسحب). هذا يضمن أن الفريق يبني الشيء الصحيح المطلوب للأعمال.', 'Scenario: Successful withdrawal
  Given a customer with balance of $100
  When they request to withdraw $40
  Then the remaining balance should be $60
  And they should receive $40 cash', '["كتابة تفاصيل تقنية سطحية في سيناريوهات BDD (مثل: Given I click on button with id #submit_btn)، مما يفقدها هدفها الدوميني."]'::jsonb, '["كيف تترجم أدوات مثل Cucumber و SpecFlow سيناريوهات النصوص الطبيعية إلى دوال برمجية قابلة للتنفيذ؟"]'::jsonb, '[{"title":"Behavior-driven development - Wikipedia","url":"https://en.wikipedia.org/wiki/Behavior-driven_development"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو التطوير الموجه بالسلوك (Behavior-Driven Development - BDD) وصيغة Given-When-Then؟' or l.short_answer is distinct from 'هو تطور لـ TDD يهدف لتوحيد لغة التواصل بين المطورين ومحللي الأعمال باستخدام لغة دومين موحدة (Ubiquitous Language)، مع صياغة سيناريوهات الاختبار بصيغة Given (السياق) و When (الحدث) و Then (النتيجة المتوقعة).' or l.explanation is distinct from 'تساعد صيغة Given-When-Then في جعل مواصفات الاختبار مفهومة لجميع الأطراف المعنية (مثل استخدام ملفات Gherkin في أدوات Cucumber). تصف Given الحالة الابتدائية للنظام (المستخدم مسجل دخول ورصيده 100)، وتصف When الإجراء الذي اتخذه المستخدم (قام بسحب 40)، وتصف Then الحالة النهائية للنظام (يصبح رصيده 60 ويتم إصدار إشعار بالسحب). هذا يضمن أن الفريق يبني الشيء الصحيح المطلوب للأعمال.' or l.code_example is distinct from 'Scenario: Successful withdrawal
  Given a customer with balance of $100
  When they request to withdraw $40
  Then the remaining balance should be $60
  And they should receive $40 cash' or l.common_mistakes is distinct from '["كتابة تفاصيل تقنية سطحية في سيناريوهات BDD (مثل: Given I click on button with id #submit_btn)، مما يفقدها هدفها الدوميني."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم أدوات مثل Cucumber و SpecFlow سيناريوهات النصوص الطبيعية إلى دوال برمجية قابلة للتنفيذ؟"]'::jsonb or l.sources is distinct from '[{"title":"Behavior-driven development - Wikipedia","url":"https://en.wikipedia.org/wiki/Behavior-driven_development"}]'::jsonb)) then raise exception 'Question ftst-008 ar content changed; create a new revision before seeding'; end if; end $$;
