insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي اختبارات التعاقد (Contract Testing) وكيف تحمي خدمات المايكروسيرفس الموزعة دون الحاجة لتشغيل بيئات E2E مجمعة؟', 'تتحقق اختبارات التعاقد من توافق واجهات الـ API بين المستهلك (Consumer) والمزود (Provider) بشكل مستقل ومنفصل دون الحاجة لتشغيل النظام الموزع بالكامل في بيئة اختبار موحدة.', 'في معمارية المايكروسيرفس، تشغيل 50 خدمة معاً لاختبارات E2E بطيء جداً وغير مستقر ومكلف. بدلاً من ذلك، في Consumer-Driven Contract Testing (باستخدام أدوات مثل Pact)، يكتب المستهلك اختباراً يحدد ما يتوقعه من المزود (عقد Contract بصيغة JSON). يُرسل هذا العقد لوسيط (Pact Broker)، ثم يقوم المزود بتشغيل اختبار ضد هذا العقد للتحقق من التزامه به. إذا قام المزود بتغيير حقل حاسم يكسر المستهلك، يفشل بناء المزود فوراً قبل النشر دون أي حاجة لبيئات متصلة.', '// عقد المستهلك: أتوقع من GET /users/1 أن يعيد حقل ''fullName'' بنوع string
// المزود يختبر واجهته ضد هذا العقد ويضمن عدم كسر التطبيقات التابعة له', '["الاعتماد على افتراضات شفهية أو توثيق يدوي قديم بين فرق الـ Frontend والـ Backend، مما يؤدي لكسر الإنتاج عند النشر المستقل."]'::jsonb, '["ما الفرق بين Consumer-Driven Contracts و Provider-Driven Contracts؟"]'::jsonb, '[{"title":"Pact Contract Testing Documentation","url":"https://en.wikipedia.org/wiki/Contract_testing"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي اختبارات التعاقد (Contract Testing) وكيف تحمي خدمات المايكروسيرفس الموزعة دون الحاجة لتشغيل بيئات E2E مجمعة؟' or l.short_answer is distinct from 'تتحقق اختبارات التعاقد من توافق واجهات الـ API بين المستهلك (Consumer) والمزود (Provider) بشكل مستقل ومنفصل دون الحاجة لتشغيل النظام الموزع بالكامل في بيئة اختبار موحدة.' or l.explanation is distinct from 'في معمارية المايكروسيرفس، تشغيل 50 خدمة معاً لاختبارات E2E بطيء جداً وغير مستقر ومكلف. بدلاً من ذلك، في Consumer-Driven Contract Testing (باستخدام أدوات مثل Pact)، يكتب المستهلك اختباراً يحدد ما يتوقعه من المزود (عقد Contract بصيغة JSON). يُرسل هذا العقد لوسيط (Pact Broker)، ثم يقوم المزود بتشغيل اختبار ضد هذا العقد للتحقق من التزامه به. إذا قام المزود بتغيير حقل حاسم يكسر المستهلك، يفشل بناء المزود فوراً قبل النشر دون أي حاجة لبيئات متصلة.' or l.code_example is distinct from '// عقد المستهلك: أتوقع من GET /users/1 أن يعيد حقل ''fullName'' بنوع string
// المزود يختبر واجهته ضد هذا العقد ويضمن عدم كسر التطبيقات التابعة له' or l.common_mistakes is distinct from '["الاعتماد على افتراضات شفهية أو توثيق يدوي قديم بين فرق الـ Frontend والـ Backend، مما يؤدي لكسر الإنتاج عند النشر المستقل."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين Consumer-Driven Contracts و Provider-Driven Contracts؟"]'::jsonb or l.sources is distinct from '[{"title":"Pact Contract Testing Documentation","url":"https://en.wikipedia.org/wiki/Contract_testing"}]'::jsonb)) then raise exception 'Question ftst-009 ar content changed; create a new revision before seeding'; end if; end $$;
