insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحسن زمن تنفيذ الاختبارات في مسارات التكامل المستمر (CI Pipelines) عبر التوازي وتقسيم الأحمال؟', 'عبر تقسيم مجموعة الاختبارات الكبيرة إلى حزم متوازية تعمل على عدة خوادم في نفس الوقت (Test Parallelization / Matrix)، وتشغيل الاختبارات المتأثرة فقط بالتغيير الأخير (Test Impact Analysis).', 'إذا كان جناح الاختبارات يستغرق ساعة كاملة للعمل على خادم واحد، فإن دورة تسليم الكود تصبح بالغة البطء. الحلول الفعالة: (1) تقسيم الاختبارات عبر خوارزميات التوقيت التاريخي (Timing-based Test Splitting) لتوزيع الحزم بالتساوي بين 4 أو 8 عمال (Workers). (2) تشغيل اختبارات التكامل التي تتطلب قواعد بيانات باستخدام حاويات خفيفة معزولة في الذاكرة (tmpfs). (3) عزل واختبار الميزات عبر Test Impact Analysis لتشغيل الاختبارات المرتبطة فقط بالملفات المعدلة في الـ PR.', '// تكوين GitHub Actions لتقسيم الاختبارات على 4 أجهزة متوازية:
strategy:
  matrix:
    ci_node_total: [4]
    ci_node_index: [0, 1, 2, 3]', '["تشغيل الاختبارات المتوازية على قاعدة بيانات واحدة مشتركة مما يسبب تصادم البيانات وفشل الاختبارات عشوائياً."]'::jsonb, '["كيف تساهم أدوات Caching (مثل Nx أو Turborepo) في تخطي إعادة تشغيل الاختبارات التي لم تتغير مدخلاتها البرمجية؟"]'::jsonb, '[{"title":"Continuous integration - Wikipedia","url":"https://en.wikipedia.org/wiki/Continuous_integration"}]'::jsonb from public.question_revisions r where r.question_id = 'ftst-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'ftst-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تحسن زمن تنفيذ الاختبارات في مسارات التكامل المستمر (CI Pipelines) عبر التوازي وتقسيم الأحمال؟' or l.short_answer is distinct from 'عبر تقسيم مجموعة الاختبارات الكبيرة إلى حزم متوازية تعمل على عدة خوادم في نفس الوقت (Test Parallelization / Matrix)، وتشغيل الاختبارات المتأثرة فقط بالتغيير الأخير (Test Impact Analysis).' or l.explanation is distinct from 'إذا كان جناح الاختبارات يستغرق ساعة كاملة للعمل على خادم واحد، فإن دورة تسليم الكود تصبح بالغة البطء. الحلول الفعالة: (1) تقسيم الاختبارات عبر خوارزميات التوقيت التاريخي (Timing-based Test Splitting) لتوزيع الحزم بالتساوي بين 4 أو 8 عمال (Workers). (2) تشغيل اختبارات التكامل التي تتطلب قواعد بيانات باستخدام حاويات خفيفة معزولة في الذاكرة (tmpfs). (3) عزل واختبار الميزات عبر Test Impact Analysis لتشغيل الاختبارات المرتبطة فقط بالملفات المعدلة في الـ PR.' or l.code_example is distinct from '// تكوين GitHub Actions لتقسيم الاختبارات على 4 أجهزة متوازية:
strategy:
  matrix:
    ci_node_total: [4]
    ci_node_index: [0, 1, 2, 3]' or l.common_mistakes is distinct from '["تشغيل الاختبارات المتوازية على قاعدة بيانات واحدة مشتركة مما يسبب تصادم البيانات وفشل الاختبارات عشوائياً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم أدوات Caching (مثل Nx أو Turborepo) في تخطي إعادة تشغيل الاختبارات التي لم تتغير مدخلاتها البرمجية؟"]'::jsonb or l.sources is distinct from '[{"title":"Continuous integration - Wikipedia","url":"https://en.wikipedia.org/wiki/Continuous_integration"}]'::jsonb)) then raise exception 'Question ftst-010 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a Software developer know about Testing Ci Cd Strategies Parallelization Splitting?', 'This question checks the core Testing Ci Cd Strategies Parallelization Splitting concept and how to use it safely in Computer Science, Software Engineering, and architecture.', 'Explain Testing Ci Cd Strategies Parallelization Splitting with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', '// تكوين GitHub Actions لتقسيم الاختبارات على 4 أجهزة متوازية:
