insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين البحث النوعي (Qualitative) والبحث الكمي (Quantitative) في تجربة المستخدم؟', 'البحث النوعي يجيب عن ''لماذا'' و''كيف'' يفكر المستخدم ويفسر مشاعره ودوافعه، بينما البحث الكمي يجيب عن ''كم'' و''ماذا'' بالبيانات الإحصائية والنسب المئوية.', 'البحث النوعي (مثل المقابلات المتعمقة واختبارات قابلية الاستخدام المباشرة) يركز على فهم الدوافع ونقاط الألم العميقة لدى عينة صغيرة من المستخدمين. أما البحث الكمي (مثل استطلاعات الرأي الضخمة وتحليلات Google Analytics وA/B Testing) فيقيس السلوكيات ويتحقق من الفرضيات إحصائياً على نطاق واسع. التصميم الاحترافي يدمج بينهما: البحث النوعي لاكتشاف المشكلة والبحث الكمي للتحقق من حجم تأثيرها.', null, '["الاعتماد على الأرقام وحدها دون معرفة أسباب سلوك المستخدم خلف الشاشات.","تعميم استنتاجات مقابلة 5 مستخدمين كأنها حقائق إحصائية تمثل كل الجمهور."]'::jsonb, '["متى تبدأ بالبحث النوعي ومتى تبدأ بالبحث الكمي في دورة حياة المنتج؟","كيف يؤثر Triangulation (تثليث مصادر البيانات) على دقة قرارات التصميم؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Quantitative vs. Qualitative Usability Testing","url":"https://www.nngroup.com/articles/quant-vs-qual/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الجوهري بين البحث النوعي (Qualitative) والبحث الكمي (Quantitative) في تجربة المستخدم؟' or l.short_answer is distinct from 'البحث النوعي يجيب عن ''لماذا'' و''كيف'' يفكر المستخدم ويفسر مشاعره ودوافعه، بينما البحث الكمي يجيب عن ''كم'' و''ماذا'' بالبيانات الإحصائية والنسب المئوية.' or l.explanation is distinct from 'البحث النوعي (مثل المقابلات المتعمقة واختبارات قابلية الاستخدام المباشرة) يركز على فهم الدوافع ونقاط الألم العميقة لدى عينة صغيرة من المستخدمين. أما البحث الكمي (مثل استطلاعات الرأي الضخمة وتحليلات Google Analytics وA/B Testing) فيقيس السلوكيات ويتحقق من الفرضيات إحصائياً على نطاق واسع. التصميم الاحترافي يدمج بينهما: البحث النوعي لاكتشاف المشكلة والبحث الكمي للتحقق من حجم تأثيرها.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاعتماد على الأرقام وحدها دون معرفة أسباب سلوك المستخدم خلف الشاشات.","تعميم استنتاجات مقابلة 5 مستخدمين كأنها حقائق إحصائية تمثل كل الجمهور."]'::jsonb or l.follow_up_questions is distinct from '["متى تبدأ بالبحث النوعي ومتى تبدأ بالبحث الكمي في دورة حياة المنتج؟","كيف يؤثر Triangulation (تثليث مصادر البيانات) على دقة قرارات التصميم؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Quantitative vs. Qualitative Usability Testing","url":"https://www.nngroup.com/articles/quant-vs-qual/"}]'::jsonb)) then raise exception 'Question uxr-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Qualitative Vs Quantitative Ux Research?', 'This question checks the core Qualitative Vs Quantitative Ux Research concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Qualitative Vs Quantitative Ux Research with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Qualitative Vs Quantitative Ux Research (point 1).","Missing the key trade-off in Qualitative Vs Quantitative Ux Research (point 2)."]'::jsonb, '["How would you apply Qualitative Vs Quantitative Ux Research in a production Product Design app (follow-up 1)?","How would you apply Qualitative Vs Quantitative Ux Research in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Quantitative vs. Qualitative Usability Testing","url":"https://www.nngroup.com/articles/quant-vs-qual/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
