insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم وتجري مقابلات المستخدمين (User Interviews) مع تجنب الأسئلة الموجهة (Leading Questions)؟', 'اسأل أسئلة مفتوحة تركز على سلوكيات وتجارب المستخدمين السابقة الفعلية بدلاً من آرائهم أو تخيلاتهم المستقبلية، وتجنب تضمين الإجابة المتوقعة داخل السؤال.', 'الناس سيئون جداً في التنبؤ بسلوكهم المستقبلي (مثلاً: ''هل ستشتري هذا المنتج لو أضفنا ميزة كذا؟'' سيجيب معظمهم بنعم مجاملة). الصواب هو سؤالهم: ''حدثني عن آخر مرة واجهت فيها هذه المشكلة؟ كيف تصرفت؟''. استخدم أسلوب الصمت التكتيكي (Tactical Silence) لإعطاء المستخدم فرصة للاسترسال، واسأل ''لماذا؟'' للوصول إلى الجذر النفسي والدافع الحقيقي بدون توجيهه نحو إجابة محددة.', null, '["طرح أسئلة مغلقة تبدأ بـ ''هل أعجبك...'' مما يضطر المستخدم للمجاملة.","شرح فكرة التصميم والدفاع عنها أثناء المقابلة بدلاً من الاستماع التام للمستخدم."]'::jsonb, '["ما هي تقنية The Mom Test في إجراء مقابلات العملاء بدون تزييف الحقائق؟","كيف تتعامل مع المستخدم الخجول أو المقتضب في إجاباته؟"]'::jsonb, '[{"title":"Nielsen Norman Group — User Interviews: How to Conduct Them","url":"https://www.nngroup.com/articles/user-interviews/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم وتجري مقابلات المستخدمين (User Interviews) مع تجنب الأسئلة الموجهة (Leading Questions)؟' or l.short_answer is distinct from 'اسأل أسئلة مفتوحة تركز على سلوكيات وتجارب المستخدمين السابقة الفعلية بدلاً من آرائهم أو تخيلاتهم المستقبلية، وتجنب تضمين الإجابة المتوقعة داخل السؤال.' or l.explanation is distinct from 'الناس سيئون جداً في التنبؤ بسلوكهم المستقبلي (مثلاً: ''هل ستشتري هذا المنتج لو أضفنا ميزة كذا؟'' سيجيب معظمهم بنعم مجاملة). الصواب هو سؤالهم: ''حدثني عن آخر مرة واجهت فيها هذه المشكلة؟ كيف تصرفت؟''. استخدم أسلوب الصمت التكتيكي (Tactical Silence) لإعطاء المستخدم فرصة للاسترسال، واسأل ''لماذا؟'' للوصول إلى الجذر النفسي والدافع الحقيقي بدون توجيهه نحو إجابة محددة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["طرح أسئلة مغلقة تبدأ بـ ''هل أعجبك...'' مما يضطر المستخدم للمجاملة.","شرح فكرة التصميم والدفاع عنها أثناء المقابلة بدلاً من الاستماع التام للمستخدم."]'::jsonb or l.follow_up_questions is distinct from '["ما هي تقنية The Mom Test في إجراء مقابلات العملاء بدون تزييف الحقائق؟","كيف تتعامل مع المستخدم الخجول أو المقتضب في إجاباته؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — User Interviews: How to Conduct Them","url":"https://www.nngroup.com/articles/user-interviews/"}]'::jsonb)) then raise exception 'Question uxr-002 ar content changed; create a new revision before seeding'; end if; end $$;
