insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو بروتوكول التفكير بصوت عالٍ (Think-Aloud Protocol) في اختبارات قابلية الاستخدام وما فائدته؟', 'هو أسلوب يُطلب فيه من المستخدم نطق كل ما يدور في ذهنه ومشاعره وتوقعاته بصوت مسموع أثناء تنفيذ مهام محددة على النموذج الأولي.', 'يعد Think-Aloud البروتوكول الأكثر فعالية في كشف النماذج الذهنية للمستخدمين وفهم أين يتعثرون ولماذا. يكشف الفجوة بين ما يتوقعه المستخدم وما يراه في الواجهة. دور الباحث هنا هو المراقبة وتشجيع المستخدم بلطف إذا صمت عبر جمل محايدة مثل: ''ما الذي تفكر فيه الآن؟''، دون إرشاده إلى الحل أو زر الخطوة التالية إطلاقاً.', null, '["مساعدة المستخدم أو إخباره بالزر الصحيح عند ارتباكه، مما يفسد نتائج الاختبار.","مقاطعة تدفق أفكار المستخدم بأسئلة متكررة تشتت تركيزه عن المهمة الأساسية."]'::jsonb, '["ما الفرق بين Concurrent Think-Aloud و Retrospective Think-Aloud؟","كم عدد المستخدمين الكافي في اختبار قابلية الاستخدام لكشف 85% من المشاكل؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Thinking Aloud: The #1 Usability Tool","url":"https://www.nngroup.com/articles/thinking-aloud-the-number-one-usability-tool/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو بروتوكول التفكير بصوت عالٍ (Think-Aloud Protocol) في اختبارات قابلية الاستخدام وما فائدته؟' or l.short_answer is distinct from 'هو أسلوب يُطلب فيه من المستخدم نطق كل ما يدور في ذهنه ومشاعره وتوقعاته بصوت مسموع أثناء تنفيذ مهام محددة على النموذج الأولي.' or l.explanation is distinct from 'يعد Think-Aloud البروتوكول الأكثر فعالية في كشف النماذج الذهنية للمستخدمين وفهم أين يتعثرون ولماذا. يكشف الفجوة بين ما يتوقعه المستخدم وما يراه في الواجهة. دور الباحث هنا هو المراقبة وتشجيع المستخدم بلطف إذا صمت عبر جمل محايدة مثل: ''ما الذي تفكر فيه الآن؟''، دون إرشاده إلى الحل أو زر الخطوة التالية إطلاقاً.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["مساعدة المستخدم أو إخباره بالزر الصحيح عند ارتباكه، مما يفسد نتائج الاختبار.","مقاطعة تدفق أفكار المستخدم بأسئلة متكررة تشتت تركيزه عن المهمة الأساسية."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين Concurrent Think-Aloud و Retrospective Think-Aloud؟","كم عدد المستخدمين الكافي في اختبار قابلية الاستخدام لكشف 85% من المشاكل؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Thinking Aloud: The #1 Usability Tool","url":"https://www.nngroup.com/articles/thinking-aloud-the-number-one-usability-tool/"}]'::jsonb)) then raise exception 'Question uxr-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Usability Testing Think Aloud Protocol?', 'This question checks the core Usability Testing Think Aloud Protocol concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Usability Testing Think Aloud Protocol with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Usability Testing Think Aloud Protocol (point 1).","Missing the key trade-off in Usability Testing Think Aloud Protocol (point 2)."]'::jsonb, '["How would you apply Usability Testing Think Aloud Protocol in a production Product Design app (follow-up 1)?","How would you apply Usability Testing Think Aloud Protocol in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Thinking Aloud: The #1 Usability Tool","url":"https://www.nngroup.com/articles/thinking-aloud-the-number-one-usability-tool/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
