insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين شخصيات المستخدمين (Personas) وإطار المهام المراد إنجازها (Jobs to be Done - JTBD)؟', 'الشخصيات تركز على هوية المستخدم وصفاته الديموغرافية والنفسية، بينما JTBD يركز على السياق والهدف والمهمة الوظيفية والعاطفية التي يريد المستخدم إنجازها بغض النظر عن هويته.', 'الـ Personas التقليدية قد تقع في فخ التركيز على تفاصيل غير مؤثرة (مثل العمر، الهوايات، الحالة الاجتماعية). في المقابل، إطار JTBD ينص على أن: ''المستخدم لا يشتري المنتج، بل يستأجره لينجز مهمة محددة في سياق معين''. الجمع الأفضل هو استخدام Proto-Personas مدعومة بـ Job Stories بصيغة: ''عندما أكون في (سياق)، أريد أن (دافع)، حتى أتمكن من (النتيجة المتوقعة)''.', null, '["صناعة شخصيات خيالية مبنية على تخمينات الفريق الداخلي بدون مقابلات واقعية.","حشو الـ Persona بمعلومات ديموغرافية سطحية لا تؤثر على قرارات التفاعل والواجهة."]'::jsonb, '["متى تفشل الـ Personas الديموغرافية في قيادة قرارات تصميم الميزات المعقدة؟","كيف تترجم Job Story إلى تسلسل شاشات تفاعلية؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Personas vs. Jobs-to-be-Done","url":"https://www.nngroup.com/articles/personas-jobs-be-done/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين شخصيات المستخدمين (Personas) وإطار المهام المراد إنجازها (Jobs to be Done - JTBD)؟' or l.short_answer is distinct from 'الشخصيات تركز على هوية المستخدم وصفاته الديموغرافية والنفسية، بينما JTBD يركز على السياق والهدف والمهمة الوظيفية والعاطفية التي يريد المستخدم إنجازها بغض النظر عن هويته.' or l.explanation is distinct from 'الـ Personas التقليدية قد تقع في فخ التركيز على تفاصيل غير مؤثرة (مثل العمر، الهوايات، الحالة الاجتماعية). في المقابل، إطار JTBD ينص على أن: ''المستخدم لا يشتري المنتج، بل يستأجره لينجز مهمة محددة في سياق معين''. الجمع الأفضل هو استخدام Proto-Personas مدعومة بـ Job Stories بصيغة: ''عندما أكون في (سياق)، أريد أن (دافع)، حتى أتمكن من (النتيجة المتوقعة)''.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["صناعة شخصيات خيالية مبنية على تخمينات الفريق الداخلي بدون مقابلات واقعية.","حشو الـ Persona بمعلومات ديموغرافية سطحية لا تؤثر على قرارات التفاعل والواجهة."]'::jsonb or l.follow_up_questions is distinct from '["متى تفشل الـ Personas الديموغرافية في قيادة قرارات تصميم الميزات المعقدة؟","كيف تترجم Job Story إلى تسلسل شاشات تفاعلية؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Personas vs. Jobs-to-be-Done","url":"https://www.nngroup.com/articles/personas-jobs-be-done/"}]'::jsonb)) then raise exception 'Question uxr-004 ar content changed; create a new revision before seeding'; end if; end $$;
