insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين فرز البطاقات المفتوح (Open Card Sorting) والمغلق (Closed Card Sorting)؟', 'الفرز المفتوح يتيح للمستخدمين تجميع الموضوعات في مجموعات وتسميتها بأنفسهم، بينما الفرز المغلق يطلب منهم توزيع الموضوعات داخل تصنيفات محددة مسبقاً.', 'يُستخدم الفرز المفتوح في المراحل الأولى لتوليد الأفكار واكتشاف النماذج الذهنية للمستخدمين وفهم كيف يصنفون المعلومات بطبيعتهم ومصطلحاتهم الخاصة. بينما يُستخدم الفرز المغلق لاختبار هيكل التصنيف القائم بالفعل وتقييم ما إذا كانت المسميات والفئات المقترحة واضحة ومنطقية لهم.', null, '["استخدام الفرز المغلق في مرحلة مبكرة جداً قبل معرفة مصطلحات المستخدمين.","كتابة بطاقات تحتوي على نفس كلمات التصنيف مما يقود المستخدمين آلياً لنفس الحل."]'::jsonb, '["كيف يساعد الفرز المختلط (Hybrid Card Sorting) في تطوير المنتجات القائمة؟","كيف تترجم نتائج مصفوفة التشابه (Similarity Matrix) إلى بنية ملاحة فعلية؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Card Sorting: Uncover Users'' Mental Models","url":"https://www.nngroup.com/articles/card-sorting-definition/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين فرز البطاقات المفتوح (Open Card Sorting) والمغلق (Closed Card Sorting)؟' or l.short_answer is distinct from 'الفرز المفتوح يتيح للمستخدمين تجميع الموضوعات في مجموعات وتسميتها بأنفسهم، بينما الفرز المغلق يطلب منهم توزيع الموضوعات داخل تصنيفات محددة مسبقاً.' or l.explanation is distinct from 'يُستخدم الفرز المفتوح في المراحل الأولى لتوليد الأفكار واكتشاف النماذج الذهنية للمستخدمين وفهم كيف يصنفون المعلومات بطبيعتهم ومصطلحاتهم الخاصة. بينما يُستخدم الفرز المغلق لاختبار هيكل التصنيف القائم بالفعل وتقييم ما إذا كانت المسميات والفئات المقترحة واضحة ومنطقية لهم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام الفرز المغلق في مرحلة مبكرة جداً قبل معرفة مصطلحات المستخدمين.","كتابة بطاقات تحتوي على نفس كلمات التصنيف مما يقود المستخدمين آلياً لنفس الحل."]'::jsonb or l.follow_up_questions is distinct from '["كيف يساعد الفرز المختلط (Hybrid Card Sorting) في تطوير المنتجات القائمة؟","كيف تترجم نتائج مصفوفة التشابه (Similarity Matrix) إلى بنية ملاحة فعلية؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Card Sorting: Uncover Users'' Mental Models","url":"https://www.nngroup.com/articles/card-sorting-definition/"}]'::jsonb)) then raise exception 'Question uxr-005 ar content changed; create a new revision before seeding'; end if; end $$;
