insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو اختبار الشجرة (Tree Testing) ولماذا يُعرف بالهندسة المعمارية العكسية للمعلومات؟', 'هو اختبار يقيس قابلية العثور على المعلومات (Findability) عبر هيكل شجري نصي مجرد من أي عناصر بصرية أو واجهات رسومية.', 'عبر إزالة الألوان والأزرار ومشتتات التصميم، يركز Tree Testing فقط على بنية القوائم والمسميات (Taxonomy). يُطلب من المستخدم: ''أين تجد وثيقة سداد الفواتير؟'' ويتنقل عبر الفئات المتداخلة فقط. إذا فشل المستخدم في العثور عليها، فهذا يعني أن المشكلة في تنظيم المعلومات والـ IA وليس في تصميم الأزرار أو الألوان.', null, '["تنفيذ اختبار الشجرة على واجهات ملونة كاملة مما يخلط بين قابلية الاستخدام وقابلية العثور.","صياغة سيناريو الاختبار باستخدام نفس كلمات الرابط النهائي (مما يلغي قيمة الاختبار)."]'::jsonb, '["ما الفرق بين مؤشر النجاح المباشر (Directness) ومعدل النجاح الإجمالي (Success Rate)؟","كيف يتكامل Card Sorting مع Tree Testing في دورة بناء الـ Navigation؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Tree Testing: Fast, Iterative Evaluation of Menu Labels and Categories","url":"https://www.nngroup.com/articles/tree-testing/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو اختبار الشجرة (Tree Testing) ولماذا يُعرف بالهندسة المعمارية العكسية للمعلومات؟' or l.short_answer is distinct from 'هو اختبار يقيس قابلية العثور على المعلومات (Findability) عبر هيكل شجري نصي مجرد من أي عناصر بصرية أو واجهات رسومية.' or l.explanation is distinct from 'عبر إزالة الألوان والأزرار ومشتتات التصميم، يركز Tree Testing فقط على بنية القوائم والمسميات (Taxonomy). يُطلب من المستخدم: ''أين تجد وثيقة سداد الفواتير؟'' ويتنقل عبر الفئات المتداخلة فقط. إذا فشل المستخدم في العثور عليها، فهذا يعني أن المشكلة في تنظيم المعلومات والـ IA وليس في تصميم الأزرار أو الألوان.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تنفيذ اختبار الشجرة على واجهات ملونة كاملة مما يخلط بين قابلية الاستخدام وقابلية العثور.","صياغة سيناريو الاختبار باستخدام نفس كلمات الرابط النهائي (مما يلغي قيمة الاختبار)."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين مؤشر النجاح المباشر (Directness) ومعدل النجاح الإجمالي (Success Rate)؟","كيف يتكامل Card Sorting مع Tree Testing في دورة بناء الـ Navigation؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Tree Testing: Fast, Iterative Evaluation of Menu Labels and Categories","url":"https://www.nngroup.com/articles/tree-testing/"}]'::jsonb)) then raise exception 'Question uxr-006 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Tree Testing Information Architecture Validation?', 'This question checks the core Tree Testing Information Architecture Validation concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Tree Testing Information Architecture Validation with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Tree Testing Information Architecture Validation (point 1).","Missing the key trade-off in Tree Testing Information Architecture Validation (point 2)."]'::jsonb, '["How would you apply Tree Testing Information Architecture Validation in a production Product Design app (follow-up 1)?","How would you apply Tree Testing Information Architecture Validation in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Tree Testing: Fast, Iterative Evaluation of Menu Labels and Categories","url":"https://www.nngroup.com/articles/tree-testing/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-006' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Tree Testing Information Architecture Validation?' or l.short_answer is distinct from 'This question checks the core Tree Testing Information Architecture Validation concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Tree Testing Information Architecture Validation with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Tree Testing Information Architecture Validation (point 1).","Missing the key trade-off in Tree Testing Information Architecture Validation (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Tree Testing Information Architecture Validation in a production Product Design app (follow-up 1)?","How would you apply Tree Testing Information Architecture Validation in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Tree Testing: Fast, Iterative Evaluation of Menu Labels and Categories","url":"https://www.nngroup.com/articles/tree-testing/"}]'::jsonb)) then raise exception 'Question uxr-006 en content changed; create a new revision before seeding'; end if; end $$;
