insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مبادئ نيلسن العشرة لقابلية الاستخدام (Nielsen''s 10 Usability Heuristics) وما أهميتها؟', 'هي قواعد استرشادية معيارية لتقييم واجهات المستخدم وكشف مشاكل قابلية الاستخدام الشائعة بدون الحاجة لاختبار مستخدمين فوري.', 'تشمل: 1) وضوح حالة النظام (Visibility of system status). 2) المواءمة بين النظام والعالم الحقيقي. 3) حرية المستخدم وتحكمه (توفير زر تراجع). 4) الاتساق والمعايير. 5) منع الأخطاء قبل وقوعها. 6) التعرف بدلاً من التذكر. 7) المرونة وكفاءة الاستخدام للمحترفين. 8) التصميم الجمالي والبسيط (Minimalist). 9) مساعدة المستخدمين في التعرف على الأخطاء وعلاجها. 10) المساعدة والتوثيق عند اللزوم.', null, '["الاعتماد على التقييم الاستكشافي كبديل كامل عن اختبار المستخدمين الحقيقيين.","فحص الواجهات دون سيناريوهات استخدام واضحة مما يؤدي لملاحظات شكلية غير مؤثرة."]'::jsonb, '["ما الفرق بين مبدأ منع الخطأ (Error Prevention) ومبدأ معالجة الخطأ (Error Recovery)؟","كيف تطبق مبدأ Recognition over Recall في تصميم محركات البحث وقوائم التصفية؟"]'::jsonb, '[{"title":"Nielsen Norman Group — 10 Usability Heuristics for User Interface Design","url":"https://www.nngroup.com/articles/ten-usability-heuristics/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي مبادئ نيلسن العشرة لقابلية الاستخدام (Nielsen''s 10 Usability Heuristics) وما أهميتها؟' or l.short_answer is distinct from 'هي قواعد استرشادية معيارية لتقييم واجهات المستخدم وكشف مشاكل قابلية الاستخدام الشائعة بدون الحاجة لاختبار مستخدمين فوري.' or l.explanation is distinct from 'تشمل: 1) وضوح حالة النظام (Visibility of system status). 2) المواءمة بين النظام والعالم الحقيقي. 3) حرية المستخدم وتحكمه (توفير زر تراجع). 4) الاتساق والمعايير. 5) منع الأخطاء قبل وقوعها. 6) التعرف بدلاً من التذكر. 7) المرونة وكفاءة الاستخدام للمحترفين. 8) التصميم الجمالي والبسيط (Minimalist). 9) مساعدة المستخدمين في التعرف على الأخطاء وعلاجها. 10) المساعدة والتوثيق عند اللزوم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاعتماد على التقييم الاستكشافي كبديل كامل عن اختبار المستخدمين الحقيقيين.","فحص الواجهات دون سيناريوهات استخدام واضحة مما يؤدي لملاحظات شكلية غير مؤثرة."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين مبدأ منع الخطأ (Error Prevention) ومبدأ معالجة الخطأ (Error Recovery)؟","كيف تطبق مبدأ Recognition over Recall في تصميم محركات البحث وقوائم التصفية؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — 10 Usability Heuristics for User Interface Design","url":"https://www.nngroup.com/articles/ten-usability-heuristics/"}]'::jsonb)) then raise exception 'Question uxr-007 ar content changed; create a new revision before seeding'; end if; end $$;
