insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين خريطة رحلة المستخدم (Customer Journey Map) ومخطط التدفق (User Flow)؟', 'خريطة الرحلة توثق التجربة الشاملة والمشاعر ونقاط الألم عبر نقاط اتصال متعددة وزمن طويل، بينما مخطط التدفق يرسم المسار التقني للخطوات والشاشات داخل النظام لإنجاز مهمة محددة.', 'الـ Journey Map تركز على البعد الإنساني والعاطفي (ماذا يرى، يفكر، يشعر المستخدم، وما هي نقاط الإحباط في كل مرحلة من الوعي إلى الشراء والاستخدام). أما الـ User Flow فيركز على الهندسة التفاعلية: شاشة تسجيل الدخول -> التحقق -> نجاح العملية -> التوجيه للشاشة الرئيسية مع القرارات الشرطية (If/Else).', null, '["رسم شاشات التطبيق فقط وتسميتها Journey Map دون توثيق الدوافع والمشاعر ونقاط الألم.","إهمال المسارات البديلة والحالات الخاطئة (Unhappy Paths) في مخططات التدفق."]'::jsonb, '["كيف تترجم نقاط الألم (Pain Points) في رحلة العميل إلى متطلبات ميزات في الـ Flow؟","ما هي مكونات الـ Service Blueprint مقارنة بـ Journey Map؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Journey Mapping 101","url":"https://www.nngroup.com/articles/journey-mapping-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين خريطة رحلة المستخدم (Customer Journey Map) ومخطط التدفق (User Flow)؟' or l.short_answer is distinct from 'خريطة الرحلة توثق التجربة الشاملة والمشاعر ونقاط الألم عبر نقاط اتصال متعددة وزمن طويل، بينما مخطط التدفق يرسم المسار التقني للخطوات والشاشات داخل النظام لإنجاز مهمة محددة.' or l.explanation is distinct from 'الـ Journey Map تركز على البعد الإنساني والعاطفي (ماذا يرى، يفكر، يشعر المستخدم، وما هي نقاط الإحباط في كل مرحلة من الوعي إلى الشراء والاستخدام). أما الـ User Flow فيركز على الهندسة التفاعلية: شاشة تسجيل الدخول -> التحقق -> نجاح العملية -> التوجيه للشاشة الرئيسية مع القرارات الشرطية (If/Else).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["رسم شاشات التطبيق فقط وتسميتها Journey Map دون توثيق الدوافع والمشاعر ونقاط الألم.","إهمال المسارات البديلة والحالات الخاطئة (Unhappy Paths) في مخططات التدفق."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم نقاط الألم (Pain Points) في رحلة العميل إلى متطلبات ميزات في الـ Flow؟","ما هي مكونات الـ Service Blueprint مقارنة بـ Journey Map؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Journey Mapping 101","url":"https://www.nngroup.com/articles/journey-mapping-101/"}]'::jsonb)) then raise exception 'Question uxr-008 ar content changed; create a new revision before seeding'; end if; end $$;
