insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الاستفسار السياقي (Contextual Inquiry) وكيف يكشف الاحتياجات الكامنة للمستخدمين؟', 'هو أسلوب بحث إثنوغرافي يقوم فيه الباحث بملاحظة المستخدم وإجراء مقابلات معه في بيئة عمله الطبيعية والواقعية أثناء تأدية مهامه المعتادة.', 'يعتمد على مبدأ المتدرب والأستاذ (Master-Apprentice Relationship): المستخدم هو المعلم الذي يؤدي عمله، والباحث هو المتدرب الذي يلاحظ ويسأل عن القرارات والأسباب فور حدوثها. ميزته الكبرى أنه يكشف الـ Workarounds (الحيل غير الرسمية التي يخترعها المستخدم للتغلب على عيوب الأنظمة القديمة مثل أوراق Post-it الملصقة على الشاشات) والتي لا يذكرها أبداً في المقابلات المكتبية.', null, '["الجلوس كضيف سلبي دون مقاطعة مهذبة للاستفسار عن الحركات غير المفهومة في وقتها.","محاولة توجيه المستخدم أو تقديم نصائح له حول كيفية تحسين أسلوب عمله أثناء الجلسة."]'::jsonb, '["ما هي المبادئ الأربعة للـ Contextual Inquiry (Context, Partnership, Interpretation, Focus)؟","كيف تحلل بيانات الملاحظة الميدانية وتستخرج منها فرص تصميم غير مسبوقة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Contextual Inquiry: Inspire Design by Observing and Interviewing Users in Their Context","url":"https://www.nngroup.com/articles/contextual-inquiry/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الاستفسار السياقي (Contextual Inquiry) وكيف يكشف الاحتياجات الكامنة للمستخدمين؟' or l.short_answer is distinct from 'هو أسلوب بحث إثنوغرافي يقوم فيه الباحث بملاحظة المستخدم وإجراء مقابلات معه في بيئة عمله الطبيعية والواقعية أثناء تأدية مهامه المعتادة.' or l.explanation is distinct from 'يعتمد على مبدأ المتدرب والأستاذ (Master-Apprentice Relationship): المستخدم هو المعلم الذي يؤدي عمله، والباحث هو المتدرب الذي يلاحظ ويسأل عن القرارات والأسباب فور حدوثها. ميزته الكبرى أنه يكشف الـ Workarounds (الحيل غير الرسمية التي يخترعها المستخدم للتغلب على عيوب الأنظمة القديمة مثل أوراق Post-it الملصقة على الشاشات) والتي لا يذكرها أبداً في المقابلات المكتبية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الجلوس كضيف سلبي دون مقاطعة مهذبة للاستفسار عن الحركات غير المفهومة في وقتها.","محاولة توجيه المستخدم أو تقديم نصائح له حول كيفية تحسين أسلوب عمله أثناء الجلسة."]'::jsonb or l.follow_up_questions is distinct from '["ما هي المبادئ الأربعة للـ Contextual Inquiry (Context, Partnership, Interpretation, Focus)؟","كيف تحلل بيانات الملاحظة الميدانية وتستخرج منها فرص تصميم غير مسبوقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Contextual Inquiry: Inspire Design by Observing and Interviewing Users in Their Context","url":"https://www.nngroup.com/articles/contextual-inquiry/"}]'::jsonb)) then raise exception 'Question uxr-009 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Contextual Inquiry And Ethnographic Research?', 'This question checks the core Contextual Inquiry And Ethnographic Research concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Contextual Inquiry And Ethnographic Research with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Contextual Inquiry And Ethnographic Research (point 1).","Missing the key trade-off in Contextual Inquiry And Ethnographic Research (point 2)."]'::jsonb, '["How would you apply Contextual Inquiry And Ethnographic Research in a production Product Design app (follow-up 1)?","How would you apply Contextual Inquiry And Ethnographic Research in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Contextual Inquiry: Inspire Design by Observing and Interviewing Users in Their Context","url":"https://www.nngroup.com/articles/contextual-inquiry/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
