insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحلل البيانات النوعية غير المنظمة وتستخرج منها رؤى قابلة للتنفيذ عبر مخططات التقارب (Affinity Diagrams)؟', 'عبر تفريغ الملاحظات والاقتباسات على بطاقات منفردة، ثم تجميعها تصاعدياً (Bottom-up) بناءً على العلاقات والأنماط المشتركة لتكوين محاور ورؤى رئيسية.', 'تبدأ العملية بجمع مئات الملاحظات الفردية من مقابلات المستخدمين، وكتابة كل فكرة على بطاقة مستقلة. يجتمع الفريق لتجميع البطاقات المتشابهة في مجموعات بصمت في البداية لتجنب تحيز المناقشات. بعد التجميع، يُطلق اسم وصفي لكل محور (Theme)، وتُصاغ الرؤى (Insights) التي تفسر جذور السلوك وتتحول إلى فرص تصميم بصيغة ''How Might We'' (كيف يمكننا أن...؟).', null, '["التجميع المسبق للملاحظات داخل فئات محددة سلفاً (Top-down) مما يحجب الأنماط الجديدة غير المتوقعة.","الاكتفاء بتلخيص ما قاله المستخدمون دون الغوص وراء الدوافع النفسية غير المصرح بها."]'::jsonb, '["كيف تحول مخرجات الـ Affinity Diagram إلى خريطة أولويات الـ Product Backlog؟","ما الفرق بين البيانات الخام (Data) والنتائج (Findings) والرؤى الاستراتيجية (Insights)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Affinity Diagramming: Collaboratively Sort UX Findings & Ideas","url":"https://www.nngroup.com/articles/affinity-diagram/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxr-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxr-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تحلل البيانات النوعية غير المنظمة وتستخرج منها رؤى قابلة للتنفيذ عبر مخططات التقارب (Affinity Diagrams)؟' or l.short_answer is distinct from 'عبر تفريغ الملاحظات والاقتباسات على بطاقات منفردة، ثم تجميعها تصاعدياً (Bottom-up) بناءً على العلاقات والأنماط المشتركة لتكوين محاور ورؤى رئيسية.' or l.explanation is distinct from 'تبدأ العملية بجمع مئات الملاحظات الفردية من مقابلات المستخدمين، وكتابة كل فكرة على بطاقة مستقلة. يجتمع الفريق لتجميع البطاقات المتشابهة في مجموعات بصمت في البداية لتجنب تحيز المناقشات. بعد التجميع، يُطلق اسم وصفي لكل محور (Theme)، وتُصاغ الرؤى (Insights) التي تفسر جذور السلوك وتتحول إلى فرص تصميم بصيغة ''How Might We'' (كيف يمكننا أن...؟).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["التجميع المسبق للملاحظات داخل فئات محددة سلفاً (Top-down) مما يحجب الأنماط الجديدة غير المتوقعة.","الاكتفاء بتلخيص ما قاله المستخدمون دون الغوص وراء الدوافع النفسية غير المصرح بها."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحول مخرجات الـ Affinity Diagram إلى خريطة أولويات الـ Product Backlog؟","ما الفرق بين البيانات الخام (Data) والنتائج (Findings) والرؤى الاستراتيجية (Insights)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Affinity Diagramming: Collaboratively Sort UX Findings & Ideas","url":"https://www.nngroup.com/articles/affinity-diagram/"}]'::jsonb)) then raise exception 'Question uxr-010 ar content changed; create a new revision before seeding'; end if; end $$;
