insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو قانون فيتس (Fitts''s Law) وكيف يؤثر على تصميم الأزرار وتجربة اللمس في الهواتف؟', 'ينص على أن الوقت اللازم للوصول إلى هدف ما يعتمد على المسافة إليه وحجم مساحته؛ فكلما كان الهدف أكبر وأقرب، كان النقر عليه أسرع وأسهل.', 'في الهواتف الذكية، الأهداف الواقعة في أسفل الشاشة (ضمن منطقة الإبهام Thumb Zone) هي الأقرب والأسرع وصولاً، بينما أعلى الشاشة أبعد ويتطلب جهداً أكبر. يفرض القانون جعل الأزرار الهامة ذات مساحة لمس كافية (48x48dp كحد أدنى)، واستغلال حواف الشاشات وزواياها في الشاشات المكتبية لأنها ذات مساحة وصول لا نهائية فيزيائياً لمؤشر الفأرة.', null, '["وضع أزرار الإجراءات الأساسية (Primary CTAs) في الزوايا العلوية البعيدة عن يد المستخدم في الهواتف.","تصميم مساحات نقر صغيرة جداً تجعل المستخدم ينقر بالخطأ على العناصر المجاورة."]'::jsonb, '["كيف يؤثر Fitts''s Law على تصميم القوائم السياقية (Contextual Menus) ومجموعات الأزرار؟","ما هي المسافة التفاعلية المثلى في شاشات الحواسيب ذات الأبعاد العريضة جداً؟"]'::jsonb, '[{"title":"Laws of UX — Fitts''s Law","url":"https://lawsofux.com/fittss-law/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو قانون فيتس (Fitts''s Law) وكيف يؤثر على تصميم الأزرار وتجربة اللمس في الهواتف؟' or l.short_answer is distinct from 'ينص على أن الوقت اللازم للوصول إلى هدف ما يعتمد على المسافة إليه وحجم مساحته؛ فكلما كان الهدف أكبر وأقرب، كان النقر عليه أسرع وأسهل.' or l.explanation is distinct from 'في الهواتف الذكية، الأهداف الواقعة في أسفل الشاشة (ضمن منطقة الإبهام Thumb Zone) هي الأقرب والأسرع وصولاً، بينما أعلى الشاشة أبعد ويتطلب جهداً أكبر. يفرض القانون جعل الأزرار الهامة ذات مساحة لمس كافية (48x48dp كحد أدنى)، واستغلال حواف الشاشات وزواياها في الشاشات المكتبية لأنها ذات مساحة وصول لا نهائية فيزيائياً لمؤشر الفأرة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع أزرار الإجراءات الأساسية (Primary CTAs) في الزوايا العلوية البعيدة عن يد المستخدم في الهواتف.","تصميم مساحات نقر صغيرة جداً تجعل المستخدم ينقر بالخطأ على العناصر المجاورة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر Fitts''s Law على تصميم القوائم السياقية (Contextual Menus) ومجموعات الأزرار؟","ما هي المسافة التفاعلية المثلى في شاشات الحواسيب ذات الأبعاد العريضة جداً؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Fitts''s Law","url":"https://lawsofux.com/fittss-law/"}]'::jsonb)) then raise exception 'Question uxp-001 ar content changed; create a new revision before seeding'; end if; end $$;
