insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو قانون هيك (Hick''s Law) وكيف يساعد في منع شلل اتخاذ القرار (Decision Paralysis)؟', 'ينص على أن الوقت المطلوب لاتخاذ القرار يزداد لوغاريتمياً مع زيادة عدد الخيارات المتاحة ودرجة تعقيدها.', 'عندما يواجه المستخدم عدداً هائلاً من الخيارات (مثل قوائم ملاحة ممتدة أو نماذج دفع تحتوي 20 حقلاً في صفحة واحدة)، يصاب بالإرهاق الذهني وقد يتراجع عن الشراء. التطبيق العملي هو: تقليص الخيارات المتاحة في اللحظة الواحدة، تجزئة العمليات المعقدة إلى خطوات متعاقبة (Wizard / Stepper)، وتسليط الضوء على خيار موصى به واحد لتسهيل القرار السريع.', null, '["عرض كافة الميزات والخيارات المتقدمة في الواجهة الرئيسية بحجة تسهيل وصول المستخدم إليها.","تصميم قوائم منسدلة عملاقة تحتوي عشرات العناصر دون تقسيم هرمي أو إمكانية بحث سريع."]'::jsonb, '["متى لا ينطبق قانون هيك على الواجهات التفاعلية؟","كيف ترتب الخيارات في شاشات التسعير (Pricing Tiers) وفق قانون هيك؟"]'::jsonb, '[{"title":"Laws of UX — Hick''s Law","url":"https://lawsofux.com/hicks-law/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو قانون هيك (Hick''s Law) وكيف يساعد في منع شلل اتخاذ القرار (Decision Paralysis)؟' or l.short_answer is distinct from 'ينص على أن الوقت المطلوب لاتخاذ القرار يزداد لوغاريتمياً مع زيادة عدد الخيارات المتاحة ودرجة تعقيدها.' or l.explanation is distinct from 'عندما يواجه المستخدم عدداً هائلاً من الخيارات (مثل قوائم ملاحة ممتدة أو نماذج دفع تحتوي 20 حقلاً في صفحة واحدة)، يصاب بالإرهاق الذهني وقد يتراجع عن الشراء. التطبيق العملي هو: تقليص الخيارات المتاحة في اللحظة الواحدة، تجزئة العمليات المعقدة إلى خطوات متعاقبة (Wizard / Stepper)، وتسليط الضوء على خيار موصى به واحد لتسهيل القرار السريع.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["عرض كافة الميزات والخيارات المتقدمة في الواجهة الرئيسية بحجة تسهيل وصول المستخدم إليها.","تصميم قوائم منسدلة عملاقة تحتوي عشرات العناصر دون تقسيم هرمي أو إمكانية بحث سريع."]'::jsonb or l.follow_up_questions is distinct from '["متى لا ينطبق قانون هيك على الواجهات التفاعلية؟","كيف ترتب الخيارات في شاشات التسعير (Pricing Tiers) وفق قانون هيك؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Hick''s Law","url":"https://lawsofux.com/hicks-law/"}]'::jsonb)) then raise exception 'Question uxp-002 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Hicks Law Reducing Cognitive Choices?', 'This question checks the core Hicks Law Reducing Cognitive Choices concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Hicks Law Reducing Cognitive Choices with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Hicks Law Reducing Cognitive Choices (point 1).","Missing the key trade-off in Hicks Law Reducing Cognitive Choices (point 2)."]'::jsonb, '["How would you apply Hicks Law Reducing Cognitive Choices in a production Product Design app (follow-up 1)?","How would you apply Hicks Law Reducing Cognitive Choices in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Laws of UX — Hick''s Law","url":"https://lawsofux.com/hicks-law/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-002' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Hicks Law Reducing Cognitive Choices?' or l.short_answer is distinct from 'This question checks the core Hicks Law Reducing Cognitive Choices concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Hicks Law Reducing Cognitive Choices with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Hicks Law Reducing Cognitive Choices (point 1).","Missing the key trade-off in Hicks Law Reducing Cognitive Choices (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Hicks Law Reducing Cognitive Choices in a production Product Design app (follow-up 1)?","How would you apply Hicks Law Reducing Cognitive Choices in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Hick''s Law","url":"https://lawsofux.com/hicks-law/"}]'::jsonb)) then raise exception 'Question uxp-002 en content changed; create a new revision before seeding'; end if; end $$;
