insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو قانون جاكوب (Jakob''s Law) ولماذا يجب ألا تعيد اختراع العجلة في تصميم التفاعل؟', 'ينص على أن المستخدمين يقضون معظم وقتهم على مواقع وتطبيقات أخرى، لذا يتوقعون أن يعمل موقعك بنفس الطريقة المألوفة التي اعتادوا عليها.', 'المستخدمون يأتون بنماذج ذهنية مسبقة (Mental Models)؛ مثلاً يتوقعون سلة التسوق في أعلى اليمين أو اليسار، وشعار الموقع يعيد للصفحة الرئيسية، وأيقونة الترس للإعدادات. عندما يبتكر المصمم نظام ملاحة غريباً وغير مألوف، يضطر المستخدم لإهدار طاقته الذهنية في تعلم الواجهة بدلاً من التركيز على هدفه ومحتوى المنصة.', null, '["تغيير مواضع العناصر الاصطلاحية القياسية (مثل حقل البحث وسلة الشراء) لمجرد التميز البصري.","استخدام أيقونات مبتكرة غير مفهومة بدون نصوص توضيحية مصاحبة."]'::jsonb, '["متى يكون من المقبول كسر النمط السائد في السوق وابتكار نمط تفاعل جديد كلياً؟","كيف نوازن بين الإبداع البصري للعلامة التجارية وبين الألفة الوظيفية للمستخدم؟"]'::jsonb, '[{"title":"Laws of UX — Jakob''s Law","url":"https://lawsofux.com/jakobs-law/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو قانون جاكوب (Jakob''s Law) ولماذا يجب ألا تعيد اختراع العجلة في تصميم التفاعل؟' or l.short_answer is distinct from 'ينص على أن المستخدمين يقضون معظم وقتهم على مواقع وتطبيقات أخرى، لذا يتوقعون أن يعمل موقعك بنفس الطريقة المألوفة التي اعتادوا عليها.' or l.explanation is distinct from 'المستخدمون يأتون بنماذج ذهنية مسبقة (Mental Models)؛ مثلاً يتوقعون سلة التسوق في أعلى اليمين أو اليسار، وشعار الموقع يعيد للصفحة الرئيسية، وأيقونة الترس للإعدادات. عندما يبتكر المصمم نظام ملاحة غريباً وغير مألوف، يضطر المستخدم لإهدار طاقته الذهنية في تعلم الواجهة بدلاً من التركيز على هدفه ومحتوى المنصة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تغيير مواضع العناصر الاصطلاحية القياسية (مثل حقل البحث وسلة الشراء) لمجرد التميز البصري.","استخدام أيقونات مبتكرة غير مفهومة بدون نصوص توضيحية مصاحبة."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون من المقبول كسر النمط السائد في السوق وابتكار نمط تفاعل جديد كلياً؟","كيف نوازن بين الإبداع البصري للعلامة التجارية وبين الألفة الوظيفية للمستخدم؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Jakob''s Law","url":"https://lawsofux.com/jakobs-law/"}]'::jsonb)) then raise exception 'Question uxp-003 ar content changed; create a new revision before seeding'; end if; end $$;
