insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxp-004', 'millers-law-and-cognitive-chunking', 'ui-ux', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
