insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما المعنى الحقيقي لقانون ميلر (Miller''s Law) وما هو التفسير الخاطئ الشائع حول رقم 7؟', 'ينص على أن الذاكرة العاملة للإنسان قادرة على معالجة 7 ± 2 من قطع المعلومات (Chunks) في المرة الواحدة؛ ولا يعني حصر عناصر القوائم بسبعة أزرار إطلاقاً.', 'الخطأ الشائع هو افتراض أن أي واجهة لا يجب أن تحتوي أكثر من 7 عناصر. الحقيقة أن القانون يدعو إلى ''التجزئة الإدراكية'' (Chunking)، أي تنظيم المعلومات المترابطة في كتل بصرية ذات معنى لتسهيل تذكرها ومعالجتها؛ مثل تقسيم أرقام بطاقات الائتمان إلى 4 مجموعات (4-4-4-4) أو تجزئة أرقام الهواتف.', null, '["تقييد خيارات القوائم الرئيسية برقم 7 فقط وتشتيت الخيارات الضرورية الأخرى.","عرض بيانات رقمية طويلة كنص متصل بدون مسافات أو فواصل تنظم القراءة."]'::jsonb, '["كيف تساهم التجزئة (Chunking) في خفض الحمل المعرفي في لوحات التحكم المعقدة (Dashboards)؟","ما الفرق بين الذاكرة قصيرة المدى (Working Memory) والذاكرة طويلة المدى في استيعاب الواجهات؟"]'::jsonb, '[{"title":"Laws of UX — Miller''s Law","url":"https://lawsofux.com/millers-law/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما المعنى الحقيقي لقانون ميلر (Miller''s Law) وما هو التفسير الخاطئ الشائع حول رقم 7؟' or l.short_answer is distinct from 'ينص على أن الذاكرة العاملة للإنسان قادرة على معالجة 7 ± 2 من قطع المعلومات (Chunks) في المرة الواحدة؛ ولا يعني حصر عناصر القوائم بسبعة أزرار إطلاقاً.' or l.explanation is distinct from 'الخطأ الشائع هو افتراض أن أي واجهة لا يجب أن تحتوي أكثر من 7 عناصر. الحقيقة أن القانون يدعو إلى ''التجزئة الإدراكية'' (Chunking)، أي تنظيم المعلومات المترابطة في كتل بصرية ذات معنى لتسهيل تذكرها ومعالجتها؛ مثل تقسيم أرقام بطاقات الائتمان إلى 4 مجموعات (4-4-4-4) أو تجزئة أرقام الهواتف.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تقييد خيارات القوائم الرئيسية برقم 7 فقط وتشتيت الخيارات الضرورية الأخرى.","عرض بيانات رقمية طويلة كنص متصل بدون مسافات أو فواصل تنظم القراءة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم التجزئة (Chunking) في خفض الحمل المعرفي في لوحات التحكم المعقدة (Dashboards)؟","ما الفرق بين الذاكرة قصيرة المدى (Working Memory) والذاكرة طويلة المدى في استيعاب الواجهات؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Miller''s Law","url":"https://lawsofux.com/millers-law/"}]'::jsonb)) then raise exception 'Question uxp-004 ar content changed; create a new revision before seeding'; end if; end $$;
