insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف توظف مبادئ الجشطالت (Gestalt Principles) مثل التقارب والتشابه في إدراك الواجهات؟', 'مبادئ الجشطالت تفسر كيف يدرك الدماغ البشري العناصر البصرية ككل منظم بدلاً من تفاصيل متفرقة، وأهمها التقارب (Proximity) والتشابه (Similarity) والإغلاق (Closure).', 'مبدأ التقارب يعني أن العناصر القريبة من بعضها يراها الدماغ كمجموعة مترابطة وظيفياً؛ لذا يجب أن تكون المسافة بين حقل الإدخال وعنوانه أقرب بكثير من المسافة مع الحقل التالي. مبدأ التشابه يعني أن العناصر ذات الشكل أو اللون أو الحجم المتطابق (مثل أزرار الروابط النصية الزرقاء) تفيد بأن لها نفس الوظيفة والسلوك.', null, '["وضع مسافات بيضاء عشوائية تجعل عنوان الحقل يظهر في منتصف المسافة بين حقلين مختلفين.","استخدام نفس التنسيق البصري للزر الأساسي الفعال وزر الحذف الخطر مما يربك المستخدم."]'::jsonb, '["كيف يعمل مبدأ المصير المشترك (Common Fate) في التحريك والتمرير بالواجهات؟","كيف يساهم مبدأ الاستمرارية (Continuity) في توجيه عين المستخدم نحو مسارات القراءة؟"]'::jsonb, '[{"title":"Laws of UX — Law of Proximity","url":"https://lawsofux.com/law-of-proximity/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف توظف مبادئ الجشطالت (Gestalt Principles) مثل التقارب والتشابه في إدراك الواجهات؟' or l.short_answer is distinct from 'مبادئ الجشطالت تفسر كيف يدرك الدماغ البشري العناصر البصرية ككل منظم بدلاً من تفاصيل متفرقة، وأهمها التقارب (Proximity) والتشابه (Similarity) والإغلاق (Closure).' or l.explanation is distinct from 'مبدأ التقارب يعني أن العناصر القريبة من بعضها يراها الدماغ كمجموعة مترابطة وظيفياً؛ لذا يجب أن تكون المسافة بين حقل الإدخال وعنوانه أقرب بكثير من المسافة مع الحقل التالي. مبدأ التشابه يعني أن العناصر ذات الشكل أو اللون أو الحجم المتطابق (مثل أزرار الروابط النصية الزرقاء) تفيد بأن لها نفس الوظيفة والسلوك.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع مسافات بيضاء عشوائية تجعل عنوان الحقل يظهر في منتصف المسافة بين حقلين مختلفين.","استخدام نفس التنسيق البصري للزر الأساسي الفعال وزر الحذف الخطر مما يربك المستخدم."]'::jsonb or l.follow_up_questions is distinct from '["كيف يعمل مبدأ المصير المشترك (Common Fate) في التحريك والتمرير بالواجهات؟","كيف يساهم مبدأ الاستمرارية (Continuity) في توجيه عين المستخدم نحو مسارات القراءة؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Law of Proximity","url":"https://lawsofux.com/law-of-proximity/"}]'::jsonb)) then raise exception 'Question uxp-005 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Gestalt Principles In Ui Design?', 'This question checks the core Gestalt Principles In Ui Design concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Gestalt Principles In Ui Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Gestalt Principles In Ui Design (point 1).","Missing the key trade-off in Gestalt Principles In Ui Design (point 2)."]'::jsonb, '["How would you apply Gestalt Principles In Ui Design in a production Product Design app (follow-up 1)?","How would you apply Gestalt Principles In Ui Design in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Laws of UX — Law of Proximity","url":"https://lawsofux.com/law-of-proximity/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-005' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Gestalt Principles In Ui Design?' or l.short_answer is distinct from 'This question checks the core Gestalt Principles In Ui Design concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Gestalt Principles In Ui Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Gestalt Principles In Ui Design (point 1).","Missing the key trade-off in Gestalt Principles In Ui Design (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Gestalt Principles In Ui Design in a production Product Design app (follow-up 1)?","How would you apply Gestalt Principles In Ui Design in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Law of Proximity","url":"https://lawsofux.com/law-of-proximity/"}]'::jsonb)) then raise exception 'Question uxp-005 en content changed; create a new revision before seeding'; end if; end $$;
