insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxp-006', 'peak-end-rule-in-product-experience', 'ui-ux', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
