insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي قاعدة الذروة والنهاية (Peak-End Rule) وكيف تؤثر على انطباع المستخدم الدائم عن المنتج؟', 'تنص على أن المستخدم يحكم على التجربة ويتذكرها بناءً على ما شعر به عند نقطة ذروتها (سواء كانت الأكثر متعة أو الأكثر إحباطاً) وعند نهايتها، وليس بناءً على متوسط كل لحظات التجربة.', 'التجربة التي تتضمن 10 خطوات عادية ولكنها تنتهي بلحظة تأكيد مبهجة واحتفالية ومطمئنة (مثل شاشات النجاح المبتكرة في Mailchimp عند إرسال الحملة) تترك أثراً إيجابياً يدوم طويلاً. في المقابل، إذا كانت كل الخطوات ممتازة ولكن اللحظة الأخيرة شهدت خطأ غير مفهوم في بوابة الدفع أو صعوبة في إلغاء الاشتراك، سيتذكر المستخدم التطبيق بأنه فاشل ومزعج.', null, '["إهمال شاشات النهاية (مثل شاشة الشكر أو تأكيد الحجز) وجعلها باهتة ومجردة من الإرشاد.","تجاهل إصلاح أشد لحظة إحباط في رحلة المستخدم (مثل تعطل رفع الملفات) بحجة أن باقي التطبيق سريع."]'::jsonb, '["كيف تصمم تجربة إيقاف أو إلغاء الاشتراك (Offboarding) وفق قاعدة Peak-End Rule لترك انطباع محترم؟","كيف تعزز Micro-copy والرسوم التفاعلية المشاعر الإيجابية في لحظات الذروة؟"]'::jsonb, '[{"title":"Laws of UX — Peak-End Rule","url":"https://lawsofux.com/peak-end-rule/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي قاعدة الذروة والنهاية (Peak-End Rule) وكيف تؤثر على انطباع المستخدم الدائم عن المنتج؟' or l.short_answer is distinct from 'تنص على أن المستخدم يحكم على التجربة ويتذكرها بناءً على ما شعر به عند نقطة ذروتها (سواء كانت الأكثر متعة أو الأكثر إحباطاً) وعند نهايتها، وليس بناءً على متوسط كل لحظات التجربة.' or l.explanation is distinct from 'التجربة التي تتضمن 10 خطوات عادية ولكنها تنتهي بلحظة تأكيد مبهجة واحتفالية ومطمئنة (مثل شاشات النجاح المبتكرة في Mailchimp عند إرسال الحملة) تترك أثراً إيجابياً يدوم طويلاً. في المقابل، إذا كانت كل الخطوات ممتازة ولكن اللحظة الأخيرة شهدت خطأ غير مفهوم في بوابة الدفع أو صعوبة في إلغاء الاشتراك، سيتذكر المستخدم التطبيق بأنه فاشل ومزعج.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إهمال شاشات النهاية (مثل شاشة الشكر أو تأكيد الحجز) وجعلها باهتة ومجردة من الإرشاد.","تجاهل إصلاح أشد لحظة إحباط في رحلة المستخدم (مثل تعطل رفع الملفات) بحجة أن باقي التطبيق سريع."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم تجربة إيقاف أو إلغاء الاشتراك (Offboarding) وفق قاعدة Peak-End Rule لترك انطباع محترم؟","كيف تعزز Micro-copy والرسوم التفاعلية المشاعر الإيجابية في لحظات الذروة؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Peak-End Rule","url":"https://lawsofux.com/peak-end-rule/"}]'::jsonb)) then raise exception 'Question uxp-006 ar content changed; create a new revision before seeding'; end if; end $$;
