insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxp-007', 'von-restorff-effect-and-cta-design', 'ui-ux', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxp-007', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو تأثير فون ريستورف (Von Restorff Effect) وكيف يُستخدم في تصميم أزرار الإجراء (CTAs)؟', 'يُعرف أيضاً بتأثير العزل (Isolation Effect)؛ وينص على أنه عندما توجد عدة عناصر متشابهة، فإن العنصر الذي يختلف بصرياً عن البقية هو الأكثر ترجيحاً للتذكر وجذب الانتباه.', 'يُطبق هذا المبدأ بوضوح في تصميم باقات الأسعار (Pricing Tables): جعل باقة ''الأكثر شعبية'' أكبر حجماً وبلون مميز مع شارة خاصة لتبرز فوراً بين الباقات الأخرى. ويُستخدم في شاشات الحوار (Dialogs) لجعل زر الإجراء الإيجابي بارزاً وممتلئاً بلون مميز، بينما زر الإلغاء باهت أو مجرد رابط نصي بسيط.', null, '["تمييز أكثر من عنصر في نفس الوقت على الشاشة، مما يخلق تضارباً بصرية ويلغي تأثير العزل تماماً.","استخدام لون تمييز صارخ لعنصر ثانوي غير مرغوب فيه مما يشتت المستخدم عن الهدف الرئيسي."]'::jsonb, '["كيف تمنع الوقوع في فخ Banner Blindness (عمى الإعلانات) عند تطبيق تأثير العزل؟","ما هي العلاقة بين التأثير والتباين اللوني المعتمد في معايير إمكانية الوصول WCAG؟"]'::jsonb, '[{"title":"Laws of UX — Von Restorff Effect","url":"https://lawsofux.com/von-restorff-effect/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو تأثير فون ريستورف (Von Restorff Effect) وكيف يُستخدم في تصميم أزرار الإجراء (CTAs)؟' or l.short_answer is distinct from 'يُعرف أيضاً بتأثير العزل (Isolation Effect)؛ وينص على أنه عندما توجد عدة عناصر متشابهة، فإن العنصر الذي يختلف بصرياً عن البقية هو الأكثر ترجيحاً للتذكر وجذب الانتباه.' or l.explanation is distinct from 'يُطبق هذا المبدأ بوضوح في تصميم باقات الأسعار (Pricing Tables): جعل باقة ''الأكثر شعبية'' أكبر حجماً وبلون مميز مع شارة خاصة لتبرز فوراً بين الباقات الأخرى. ويُستخدم في شاشات الحوار (Dialogs) لجعل زر الإجراء الإيجابي بارزاً وممتلئاً بلون مميز، بينما زر الإلغاء باهت أو مجرد رابط نصي بسيط.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تمييز أكثر من عنصر في نفس الوقت على الشاشة، مما يخلق تضارباً بصرية ويلغي تأثير العزل تماماً.","استخدام لون تمييز صارخ لعنصر ثانوي غير مرغوب فيه مما يشتت المستخدم عن الهدف الرئيسي."]'::jsonb or l.follow_up_questions is distinct from '["كيف تمنع الوقوع في فخ Banner Blindness (عمى الإعلانات) عند تطبيق تأثير العزل؟","ما هي العلاقة بين التأثير والتباين اللوني المعتمد في معايير إمكانية الوصول WCAG؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Von Restorff Effect","url":"https://lawsofux.com/von-restorff-effect/"}]'::jsonb)) then raise exception 'Question uxp-007 ar content changed; create a new revision before seeding'; end if; end $$;
