insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو تأثير الجمالية على قابلية الاستخدام (Aesthetic-Usability Effect) وما خطورته أثناء الاختبارات؟', 'ينص على أن المستخدمين يميلون لإدراك التصميمات الجذابة بصرياً على أنها أكثر سهولة في الاستخدام وأكثر كفاءة، ويكونون أكثر تسامحاً مع مشاكل الاستخدام البسيطة.', 'الجمال البصري يولد استجابة عاطفية إيجابية تخفف من توتر المستخدم أثناء التفاعل. لكن خطورته تكمن في أبحاث المستخدمين: قد يقول المستخدم في المقابلة: ''الموقع رائع وسهل جداً!'' فقط لأنه مبهر بصرياً، بينما في الواقع يستغرق وقتاً مضاعفاً لإيجاد المنتج أو يرتكب أخطاء جسيمة. لذلك يجب على الباحث مراقبة الأفعال ومعدلات الإنجاز الفعلية وليس الانطباع البصري اللفظي.', null, '["تلميع واجهات غير وظيفية بألوان ورسوم حديثة لإخفاء مشاكل هيكلية في الملاحة وتدفق المهام.","أخذ آراء المستخدمين الإيجابية حول جمال الشكل كدليل على خلو الواجهة من عيوب الاستخدام."]'::jsonb, '["كيف تفصل بين جاذبية واجهة المستخدم (UI Aesthetics) وقابلية استخدامها (Usability) أثناء التحليل؟","كيف يؤثر التناغم بين الخطوط والألوان والمساحات في بناء الثقة الفورية (Credibility)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — The Aesthetic-Usability Effect","url":"https://www.nngroup.com/articles/aesthetic-usability-effect/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو تأثير الجمالية على قابلية الاستخدام (Aesthetic-Usability Effect) وما خطورته أثناء الاختبارات؟' or l.short_answer is distinct from 'ينص على أن المستخدمين يميلون لإدراك التصميمات الجذابة بصرياً على أنها أكثر سهولة في الاستخدام وأكثر كفاءة، ويكونون أكثر تسامحاً مع مشاكل الاستخدام البسيطة.' or l.explanation is distinct from 'الجمال البصري يولد استجابة عاطفية إيجابية تخفف من توتر المستخدم أثناء التفاعل. لكن خطورته تكمن في أبحاث المستخدمين: قد يقول المستخدم في المقابلة: ''الموقع رائع وسهل جداً!'' فقط لأنه مبهر بصرياً، بينما في الواقع يستغرق وقتاً مضاعفاً لإيجاد المنتج أو يرتكب أخطاء جسيمة. لذلك يجب على الباحث مراقبة الأفعال ومعدلات الإنجاز الفعلية وليس الانطباع البصري اللفظي.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تلميع واجهات غير وظيفية بألوان ورسوم حديثة لإخفاء مشاكل هيكلية في الملاحة وتدفق المهام.","أخذ آراء المستخدمين الإيجابية حول جمال الشكل كدليل على خلو الواجهة من عيوب الاستخدام."]'::jsonb or l.follow_up_questions is distinct from '["كيف تفصل بين جاذبية واجهة المستخدم (UI Aesthetics) وقابلية استخدامها (Usability) أثناء التحليل؟","كيف يؤثر التناغم بين الخطوط والألوان والمساحات في بناء الثقة الفورية (Credibility)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — The Aesthetic-Usability Effect","url":"https://www.nngroup.com/articles/aesthetic-usability-effect/"}]'::jsonb)) then raise exception 'Question uxp-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Aesthetic Usability Effect And Its Risks?', 'This question checks the core Aesthetic Usability Effect And Its Risks concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Aesthetic Usability Effect And Its Risks with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Aesthetic Usability Effect And Its Risks (point 1).","Missing the key trade-off in Aesthetic Usability Effect And Its Risks (point 2)."]'::jsonb, '["How would you apply Aesthetic Usability Effect And Its Risks in a production Product Design app (follow-up 1)?","How would you apply Aesthetic Usability Effect And Its Risks in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — The Aesthetic-Usability Effect","url":"https://www.nngroup.com/articles/aesthetic-usability-effect/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-008' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Aesthetic Usability Effect And Its Risks?' or l.short_answer is distinct from 'This question checks the core Aesthetic Usability Effect And Its Risks concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Aesthetic Usability Effect And Its Risks with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Aesthetic Usability Effect And Its Risks (point 1).","Missing the key trade-off in Aesthetic Usability Effect And Its Risks (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Aesthetic Usability Effect And Its Risks in a production Product Design app (follow-up 1)?","How would you apply Aesthetic Usability Effect And Its Risks in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — The Aesthetic-Usability Effect","url":"https://www.nngroup.com/articles/aesthetic-usability-effect/"}]'::jsonb)) then raise exception 'Question uxp-008 en content changed; create a new revision before seeding'; end if; end $$;
