insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي عتبة دوهرتي (Doherty Threshold) وما هي تقنيات تحسين الأداء المُدرك (Perceived Performance)؟', 'تنص على أن الإنتاجية تزداد بشكل كبير عندما يتفاعل الحاسوب والإنسان بوتيرة لا تتجاوز 400 مللي ثانية للرد؛ وإذا زادت المدة يتشتت انتباه المستخدم.', 'عندما يستغرق طلب الشبكة أكثر من 400ms، يجب تقديم تغذية بصرية فورية (Visual Feedback) تؤكد استلام الطلب. تشمل استراتيجيات الأداء المدرك: شاشات الهيكل العظمي (Skeleton Screens) التي توحي بأن الصفحة تتشكل، التحديث التفاؤلي للواجهة (Optimistic UI) الذي يظهر الإعجاب أو الرسالة فوراً قبل رد السيرفر، ومؤشرات التقدم المحددة بدلاً من الدوائر الدوارة البطيئة.', null, '["ترك الزر صامتاً وبلا أي استجابة حركية فورية لعدة ثوانٍ أثناء انتظار رد الشبكة، مما يدفع المستخدم للنقر المتكرر.","استخدام دوائر التحميل الدوارة (Spinners) لكل شاشة مما يشعر المستخدم بأن النظام بطيء وثقيل."]'::jsonb, '["ما الفرق بين زمن الاستجابة الحقيقي وزمن الاستجابة المدرك نفسياً لدى المستخدم؟","متى يكون من الأفضل تأخير الواجهة اصطناعياً (Artificial Delay) لزيادة ثقة المستخدم في النتيجة؟"]'::jsonb, '[{"title":"Laws of UX — Doherty Threshold","url":"https://lawsofux.com/doherty-threshold/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي عتبة دوهرتي (Doherty Threshold) وما هي تقنيات تحسين الأداء المُدرك (Perceived Performance)؟' or l.short_answer is distinct from 'تنص على أن الإنتاجية تزداد بشكل كبير عندما يتفاعل الحاسوب والإنسان بوتيرة لا تتجاوز 400 مللي ثانية للرد؛ وإذا زادت المدة يتشتت انتباه المستخدم.' or l.explanation is distinct from 'عندما يستغرق طلب الشبكة أكثر من 400ms، يجب تقديم تغذية بصرية فورية (Visual Feedback) تؤكد استلام الطلب. تشمل استراتيجيات الأداء المدرك: شاشات الهيكل العظمي (Skeleton Screens) التي توحي بأن الصفحة تتشكل، التحديث التفاؤلي للواجهة (Optimistic UI) الذي يظهر الإعجاب أو الرسالة فوراً قبل رد السيرفر، ومؤشرات التقدم المحددة بدلاً من الدوائر الدوارة البطيئة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ترك الزر صامتاً وبلا أي استجابة حركية فورية لعدة ثوانٍ أثناء انتظار رد الشبكة، مما يدفع المستخدم للنقر المتكرر.","استخدام دوائر التحميل الدوارة (Spinners) لكل شاشة مما يشعر المستخدم بأن النظام بطيء وثقيل."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين زمن الاستجابة الحقيقي وزمن الاستجابة المدرك نفسياً لدى المستخدم؟","متى يكون من الأفضل تأخير الواجهة اصطناعياً (Artificial Delay) لزيادة ثقة المستخدم في النتيجة؟"]'::jsonb or l.sources is distinct from '[{"title":"Laws of UX — Doherty Threshold","url":"https://lawsofux.com/doherty-threshold/"}]'::jsonb)) then raise exception 'Question uxp-009 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Doherty Threshold And Perceived Performance?', 'This question checks the core Doherty Threshold And Perceived Performance concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Doherty Threshold And Perceived Performance with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Doherty Threshold And Perceived Performance (point 1).","Missing the key trade-off in Doherty Threshold And Perceived Performance (point 2)."]'::jsonb, '["How would you apply Doherty Threshold And Perceived Performance in a production Product Design app (follow-up 1)?","How would you apply Doherty Threshold And Perceived Performance in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Laws of UX — Doherty Threshold","url":"https://lawsofux.com/doherty-threshold/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
