insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxp-010', 'progressive-disclosure-reducing-cognitive-load', 'ui-ux', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxp-010', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يعمل مبدأ الإفصاح التدريجي (Progressive Disclosure) على إدارة التعقيد في التطبيقات الاحترافية؟', 'هو أسلوب تصميم يقدم المعلومات والميزات الأساسية والضرورية فقط في البداية، ويؤجل عرض التفاصيل والخيارات المتقدمة إلى أن يطلبها المستخدم صراحة.', 'يحل الإفصاح التدريجي المعضلة الكلاسيكية: كيف تصمم واجهة سهلة للمبتدئين وتلبي احتياجات المحترفين في آن واحد؟ يتم ذلك عبر وضع الميزات الأكثر استخداماً (80% من الحالات) في الواجهة المباشرة، مع توفير أزرار ''خيارات متقدمة'' أو قوائم فرعية للتفاصيل المعقدة. هذا يمنع إغراق الواجهة بالفوضى ويحافظ على سرعة إنجاز المهام الشائعة.', null, '["دفن خيارات حيوية وأساسية داخل قوائم خفية يصعب على المستخدم العادي العثور عليها.","عرض كافة المعاملات البرمجية أو خيارات التصفية المعقدة دفعة واحدة في الشاشة الأولى."]'::jsonb, '["كيف تصمم Accordion أو Stepper يطبق الإفصاح التدريجي دون إرهاق المستخدم بالتنقل المتكرر؟","ما هي معايير الفصل بين الميزات الأساسية والميزات المتقدمة استناداً إلى بيانات التحليلات؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Progressive Disclosure","url":"https://www.nngroup.com/articles/progressive-disclosure/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxp-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxp-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يعمل مبدأ الإفصاح التدريجي (Progressive Disclosure) على إدارة التعقيد في التطبيقات الاحترافية؟' or l.short_answer is distinct from 'هو أسلوب تصميم يقدم المعلومات والميزات الأساسية والضرورية فقط في البداية، ويؤجل عرض التفاصيل والخيارات المتقدمة إلى أن يطلبها المستخدم صراحة.' or l.explanation is distinct from 'يحل الإفصاح التدريجي المعضلة الكلاسيكية: كيف تصمم واجهة سهلة للمبتدئين وتلبي احتياجات المحترفين في آن واحد؟ يتم ذلك عبر وضع الميزات الأكثر استخداماً (80% من الحالات) في الواجهة المباشرة، مع توفير أزرار ''خيارات متقدمة'' أو قوائم فرعية للتفاصيل المعقدة. هذا يمنع إغراق الواجهة بالفوضى ويحافظ على سرعة إنجاز المهام الشائعة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["دفن خيارات حيوية وأساسية داخل قوائم خفية يصعب على المستخدم العادي العثور عليها.","عرض كافة المعاملات البرمجية أو خيارات التصفية المعقدة دفعة واحدة في الشاشة الأولى."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم Accordion أو Stepper يطبق الإفصاح التدريجي دون إرهاق المستخدم بالتنقل المتكرر؟","ما هي معايير الفصل بين الميزات الأساسية والميزات المتقدمة استناداً إلى بيانات التحليلات؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Progressive Disclosure","url":"https://www.nngroup.com/articles/progressive-disclosure/"}]'::jsonb)) then raise exception 'Question uxp-010 ar content changed; create a new revision before seeding'; end if; end $$;
