insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الركائز الأربع الأساسية لهندسة المعلومات (Information Architecture - IA) وفقاً لـ Rosenfeld و Morville؟', 'الركائز الأربع هي: 1) أنظمة التنظيم (Organization). 2) أنظمة التسمية (Labeling). 3) أنظمة الملاحة (Navigation). 4) أنظمة البحث (Search).', 'نظام التنظيم يحدد كيفية هيكلة المحتوى وتقسيمه (هرمياً، زمنياً، أبجدياً، أو حسب الموضوع). نظام التسمية يحدد المصطلحات واللغة المفهومة للمستخدمين بدلاً من مصطلحات الشركة التقنية. نظام الملاحة يحدد كيفية تنقل المستخدم وتحديد موقعه الحالي ومساراته السابقة واللاحقة. ونظام البحث يساعد المستخدم في الاستعلام والفلترة والوصول المباشر دون تصفح طويل.', null, '["البدء في تصميم الشاشات والألوان قبل الاتفاق على هيكل وتصنيف محتوى التطبيق.","استخدام مسميات داخلية خاصة بالمبرمجين أو الإدارة لا يفهمها المستخدم النهائي."]'::jsonb, '["كيف تترجم ركائز هندسة المعلومات إلى Sitemap تفاعلي واضح؟","ما الفرق بين الفرز حسب الجمهور (Audience-specific) والفرز حسب المهام (Task-oriented)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Information Architecture: Study Guide","url":"https://www.nngroup.com/articles/ia-study-guide/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الركائز الأربع الأساسية لهندسة المعلومات (Information Architecture - IA) وفقاً لـ Rosenfeld و Morville؟' or l.short_answer is distinct from 'الركائز الأربع هي: 1) أنظمة التنظيم (Organization). 2) أنظمة التسمية (Labeling). 3) أنظمة الملاحة (Navigation). 4) أنظمة البحث (Search).' or l.explanation is distinct from 'نظام التنظيم يحدد كيفية هيكلة المحتوى وتقسيمه (هرمياً، زمنياً، أبجدياً، أو حسب الموضوع). نظام التسمية يحدد المصطلحات واللغة المفهومة للمستخدمين بدلاً من مصطلحات الشركة التقنية. نظام الملاحة يحدد كيفية تنقل المستخدم وتحديد موقعه الحالي ومساراته السابقة واللاحقة. ونظام البحث يساعد المستخدم في الاستعلام والفلترة والوصول المباشر دون تصفح طويل.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["البدء في تصميم الشاشات والألوان قبل الاتفاق على هيكل وتصنيف محتوى التطبيق.","استخدام مسميات داخلية خاصة بالمبرمجين أو الإدارة لا يفهمها المستخدم النهائي."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم ركائز هندسة المعلومات إلى Sitemap تفاعلي واضح؟","ما الفرق بين الفرز حسب الجمهور (Audience-specific) والفرز حسب المهام (Task-oriented)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Information Architecture: Study Guide","url":"https://www.nngroup.com/articles/ia-study-guide/"}]'::jsonb)) then raise exception 'Question uxia-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Four Pillars Of Information Architecture?', 'This question checks the core Four Pillars Of Information Architecture concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Four Pillars Of Information Architecture with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Four Pillars Of Information Architecture (point 1).","Missing the key trade-off in Four Pillars Of Information Architecture (point 2)."]'::jsonb, '["How would you apply Four Pillars Of Information Architecture in a production Product Design app (follow-up 1)?","How would you apply Four Pillars Of Information Architecture in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Information Architecture: Study Guide","url":"https://www.nngroup.com/articles/ia-study-guide/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-001' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Four Pillars Of Information Architecture?' or l.short_answer is distinct from 'This question checks the core Four Pillars Of Information Architecture concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Four Pillars Of Information Architecture with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Four Pillars Of Information Architecture (point 1).","Missing the key trade-off in Four Pillars Of Information Architecture (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Four Pillars Of Information Architecture in a production Product Design app (follow-up 1)?","How would you apply Four Pillars Of Information Architecture in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Information Architecture: Study Guide","url":"https://www.nngroup.com/articles/ia-study-guide/"}]'::jsonb)) then raise exception 'Question uxia-001 en content changed; create a new revision before seeding'; end if; end $$;
