insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين هياكل الملاحة المسطحة (Flat Navigation) والعميقة (Deep Navigation) ومتى تختار كلاً منهما؟', 'الملاحة المسطحة تقدم خيارات واسعة في المستوى الأول وعمقاً قليلاً (نقرات أقل)، بينما الملاحة العميقة تقدم خيارات قليلة في البداية وتتفرع لمستويات متعددة في العمق.', 'الملاحة المسطحة (Wide/Flat) تقلل الجهد المعرفي للوصول لأن معظم المحتوى يظهر بوضوح، ولكنها قد تسبب فوضى إذا تجاوزت الحدود المعقولة. الملاحة العميقة تقلل عدد الخيارات أمام العين دفعة واحدة، لكنها تزيد من النقر ومخاطر ضياع المستخدم في المستويات السفلية ونسيان مسار العودة. القاعدة المعاصرة تميل إلى جعل الهيكل مسطحاً قدر الإمكان مع تصنيفات واضحة.', null, '["بناء ملاحة عميقة تطلب من المستخدم 6 أو 7 نقرات متتالية للوصول لصفحة حيوية.","حشر عشرات الأقسام غير المتجانسة في قائمة أفقية واحدة بدعوى التسطيح."]'::jsonb, '["ما هي قاعدة الثلاث نقرات (3-Click Rule) وهل هي قاعدة علمية صحيحة أم خرافة في الـ UX؟","كيف تساهم Breadcrumbs (فتات الخبز) في إنقاذ المستخدم من الضياع في الهياكل العميقة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Flat vs. Deep Website Hierarchies","url":"https://www.nngroup.com/articles/flat-vs-deep-hierarchy/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين هياكل الملاحة المسطحة (Flat Navigation) والعميقة (Deep Navigation) ومتى تختار كلاً منهما؟' or l.short_answer is distinct from 'الملاحة المسطحة تقدم خيارات واسعة في المستوى الأول وعمقاً قليلاً (نقرات أقل)، بينما الملاحة العميقة تقدم خيارات قليلة في البداية وتتفرع لمستويات متعددة في العمق.' or l.explanation is distinct from 'الملاحة المسطحة (Wide/Flat) تقلل الجهد المعرفي للوصول لأن معظم المحتوى يظهر بوضوح، ولكنها قد تسبب فوضى إذا تجاوزت الحدود المعقولة. الملاحة العميقة تقلل عدد الخيارات أمام العين دفعة واحدة، لكنها تزيد من النقر ومخاطر ضياع المستخدم في المستويات السفلية ونسيان مسار العودة. القاعدة المعاصرة تميل إلى جعل الهيكل مسطحاً قدر الإمكان مع تصنيفات واضحة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["بناء ملاحة عميقة تطلب من المستخدم 6 أو 7 نقرات متتالية للوصول لصفحة حيوية.","حشر عشرات الأقسام غير المتجانسة في قائمة أفقية واحدة بدعوى التسطيح."]'::jsonb or l.follow_up_questions is distinct from '["ما هي قاعدة الثلاث نقرات (3-Click Rule) وهل هي قاعدة علمية صحيحة أم خرافة في الـ UX؟","كيف تساهم Breadcrumbs (فتات الخبز) في إنقاذ المستخدم من الضياع في الهياكل العميقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Flat vs. Deep Website Hierarchies","url":"https://www.nngroup.com/articles/flat-vs-deep-hierarchy/"}]'::jsonb)) then raise exception 'Question uxia-002 ar content changed; create a new revision before seeding'; end if; end $$;
