insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تختلف سلوكيات المستخدمين بين البحث (Search) والتصفح (Browse) وكيف تدعمهما معاً؟', 'المستخدمون ينقسمون إلى نوعين: الباحثون الذين يعرفون هدفهم بدقة ويريدون الوصول الفوري، والمتصفحون الذين يستكشفون الخيارات ويحتاجون إلى إرشاد وتصنيفات ملهمة.', 'الباحث الموجه بالهدف (Search-dominant) يحتاج إلى شريط بحث بارز، إكمال تلقائي ذكي (Autocomplete)، دعم للأخطاء الإملائية، وفلاتر دقيقة. أما المتصفح (Browse-dominant) فيحتاج إلى قوائم مرتبة، بطاقات مقترحات، تصنيفات شهيرة، ومسارات ملاحة بصرية واضحة. التطبيق الممتاز يدعم الاثنين بسلاسة، ويتيح للباحث العودة للتصفح إذا لم يجد نتيجته الدقيقة.', null, '["إخفاء شريط البحث في مواقع التجارة الإلكترونية الضخمة داخل أيقونة صغيرة أو قائمة جانبية.","عرض صفحة ''لا توجد نتائج'' فارغة وجافة دون اقتراح مسارات بديلة أو منتجات شائعة."]'::jsonb, '["كيف يؤثر الـ Faceted Search (البحث متعدد الأوجه) على معدلات التحويل في المتاجر الكبيرة؟","ما هي أفضل ممارسات تصميم الاقتراحات التلقائية (Auto-suggestions) لمنع التشتيت؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Search Is Not Always the Best Strategy","url":"https://www.nngroup.com/articles/search-not-always-best/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تختلف سلوكيات المستخدمين بين البحث (Search) والتصفح (Browse) وكيف تدعمهما معاً؟' or l.short_answer is distinct from 'المستخدمون ينقسمون إلى نوعين: الباحثون الذين يعرفون هدفهم بدقة ويريدون الوصول الفوري، والمتصفحون الذين يستكشفون الخيارات ويحتاجون إلى إرشاد وتصنيفات ملهمة.' or l.explanation is distinct from 'الباحث الموجه بالهدف (Search-dominant) يحتاج إلى شريط بحث بارز، إكمال تلقائي ذكي (Autocomplete)، دعم للأخطاء الإملائية، وفلاتر دقيقة. أما المتصفح (Browse-dominant) فيحتاج إلى قوائم مرتبة، بطاقات مقترحات، تصنيفات شهيرة، ومسارات ملاحة بصرية واضحة. التطبيق الممتاز يدعم الاثنين بسلاسة، ويتيح للباحث العودة للتصفح إذا لم يجد نتيجته الدقيقة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إخفاء شريط البحث في مواقع التجارة الإلكترونية الضخمة داخل أيقونة صغيرة أو قائمة جانبية.","عرض صفحة ''لا توجد نتائج'' فارغة وجافة دون اقتراح مسارات بديلة أو منتجات شائعة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر الـ Faceted Search (البحث متعدد الأوجه) على معدلات التحويل في المتاجر الكبيرة؟","ما هي أفضل ممارسات تصميم الاقتراحات التلقائية (Auto-suggestions) لمنع التشتيت؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Search Is Not Always the Best Strategy","url":"https://www.nngroup.com/articles/search-not-always-best/"}]'::jsonb)) then raise exception 'Question uxia-003 ar content changed; create a new revision before seeding'; end if; end $$;
