insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي مبادئ الاستدلال المكاني (Wayfinding) وكيف تصمم مسارات فتات الخبز (Breadcrumbs) باحتراف؟', 'الاستدلال المكاني يجيب عن 3 أسئلة دائمة في عقل المستخدم: أين أنا الآن؟ أين كنت؟ وإلى أين يمكنني الذهاب من هنا؟ وتعد Breadcrumbs الحل البصري الأمثل لذلك.', 'تعتبر Breadcrumbs أداة ملاحة ثانوية تدعم الملاحة الأساسية ولا تحل محلها. تنقسم إلى نوعين: هرمية قائمة على الموقع (Location-based: Home > Men > Shoes > Sneakers)، وتاريخية قائمة على المسار (Path-based). يجب دائماً جعل العنصر الأخير (الصفحة الحالية) غير قابل للنقر لتمييزه، واستخدام فواصل بصرية واضحة ومقروءة مثل ''>'' أو ''/''.', null, '["استبدال القائمة الرئيسية بـ Breadcrumbs أو الاعتماد عليها وحدها في الملاحة.","إظهار مسارات طويلة جداً وغير مستقرة تتغير بحسب كيفية وصول المستخدم للصفحة بدلاً من الهيكل الثابت."]'::jsonb, '["متى تكون مسارات Breadcrumbs غير مجدية على واجهات الهواتف المحمولة؟","كيف تؤثر Breadcrumbs على تحسين محركات البحث وتجربة مستخدمي Google Search؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Breadcrumbs: 11 Design Guidelines for Desktop and Mobile","url":"https://www.nngroup.com/articles/breadcrumbs/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي مبادئ الاستدلال المكاني (Wayfinding) وكيف تصمم مسارات فتات الخبز (Breadcrumbs) باحتراف؟' or l.short_answer is distinct from 'الاستدلال المكاني يجيب عن 3 أسئلة دائمة في عقل المستخدم: أين أنا الآن؟ أين كنت؟ وإلى أين يمكنني الذهاب من هنا؟ وتعد Breadcrumbs الحل البصري الأمثل لذلك.' or l.explanation is distinct from 'تعتبر Breadcrumbs أداة ملاحة ثانوية تدعم الملاحة الأساسية ولا تحل محلها. تنقسم إلى نوعين: هرمية قائمة على الموقع (Location-based: Home > Men > Shoes > Sneakers)، وتاريخية قائمة على المسار (Path-based). يجب دائماً جعل العنصر الأخير (الصفحة الحالية) غير قابل للنقر لتمييزه، واستخدام فواصل بصرية واضحة ومقروءة مثل ''>'' أو ''/''.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استبدال القائمة الرئيسية بـ Breadcrumbs أو الاعتماد عليها وحدها في الملاحة.","إظهار مسارات طويلة جداً وغير مستقرة تتغير بحسب كيفية وصول المستخدم للصفحة بدلاً من الهيكل الثابت."]'::jsonb or l.follow_up_questions is distinct from '["متى تكون مسارات Breadcrumbs غير مجدية على واجهات الهواتف المحمولة؟","كيف تؤثر Breadcrumbs على تحسين محركات البحث وتجربة مستخدمي Google Search؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Breadcrumbs: 11 Design Guidelines for Desktop and Mobile","url":"https://www.nngroup.com/articles/breadcrumbs/"}]'::jsonb)) then raise exception 'Question uxia-004 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Wayfinding Principles And Breadcrumbs?', 'This question checks the core Wayfinding Principles And Breadcrumbs concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Wayfinding Principles And Breadcrumbs with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Wayfinding Principles And Breadcrumbs (point 1).","Missing the key trade-off in Wayfinding Principles And Breadcrumbs (point 2)."]'::jsonb, '["How would you apply Wayfinding Principles And Breadcrumbs in a production Product Design app (follow-up 1)?","How would you apply Wayfinding Principles And Breadcrumbs in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Breadcrumbs: 11 Design Guidelines for Desktop and Mobile","url":"https://www.nngroup.com/articles/breadcrumbs/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-004' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Wayfinding Principles And Breadcrumbs?' or l.short_answer is distinct from 'This question checks the core Wayfinding Principles And Breadcrumbs concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Wayfinding Principles And Breadcrumbs with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Wayfinding Principles And Breadcrumbs (point 1).","Missing the key trade-off in Wayfinding Principles And Breadcrumbs (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Wayfinding Principles And Breadcrumbs in a production Product Design app (follow-up 1)?","How would you apply Wayfinding Principles And Breadcrumbs in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Breadcrumbs: 11 Design Guidelines for Desktop and Mobile","url":"https://www.nngroup.com/articles/breadcrumbs/"}]'::jsonb)) then raise exception 'Question uxia-004 en content changed; create a new revision before seeding'; end if; end $$;
