insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxia-005', 'mobile-navigation-tabs-vs-hamburger-drawer', 'ui-ux', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
