insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين شريط التنقل السفلي (Bottom Navigation Bar) وقائمة الهامبرغر الجانبية (Hamburger Drawer) في الهواتف؟', 'شريط التنقل السفلي يضع الأقسام الرئيسية (3 إلى 5) ظاهرة دائماً وفي متناول الإبهام، بينما قائمة الهامبرغر تخفي الملاحة وتقلل من اكتشاف المحتوى واستخدامه.', 'القاعدة المعروفة في الـ UX هي: ''ما يغيب عن العين يغيب عن الذهن'' (Out of sight, out of mind). أظهرت الدراسات أن معدل استخدام الشاشات المخفية داخل الهامبرغر ينخفض بنسبة تصل إلى 50% مقارنة بالـ Bottom Tabs. استخدم شريط التنقل السفلي لأهم مسارات التطبيق اليومية، واقصر القائمة الجانبية على الإعدادات والصفحات الثانوية ونادراً ما يُحتاج إليها.', null, '["وضع أكثر من 5 خيارات في شريط التنقل السفلي مما يجعل الأزرار ضيقة ومتداخلة.","إخفاء الأقسام الأساسية للمنتج داخل قائمة هامبرغر في تطبيقات المتاجر أو الخدمات الرئيسية."]'::jsonb, '["ما هو نمط الملاحة الهجين (Tabs + More Menu) ومتى يُعتبر حلاً عملياً؟","كيف يؤثر التمرير الإخفائي (Scroll-to-hide) لشريط الملاحة السفلي على تجربة القراءة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Hamburger Menus and Hidden Navigation Hurt UX Metrics","url":"https://www.nngroup.com/articles/hamburger-menus/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين شريط التنقل السفلي (Bottom Navigation Bar) وقائمة الهامبرغر الجانبية (Hamburger Drawer) في الهواتف؟' or l.short_answer is distinct from 'شريط التنقل السفلي يضع الأقسام الرئيسية (3 إلى 5) ظاهرة دائماً وفي متناول الإبهام، بينما قائمة الهامبرغر تخفي الملاحة وتقلل من اكتشاف المحتوى واستخدامه.' or l.explanation is distinct from 'القاعدة المعروفة في الـ UX هي: ''ما يغيب عن العين يغيب عن الذهن'' (Out of sight, out of mind). أظهرت الدراسات أن معدل استخدام الشاشات المخفية داخل الهامبرغر ينخفض بنسبة تصل إلى 50% مقارنة بالـ Bottom Tabs. استخدم شريط التنقل السفلي لأهم مسارات التطبيق اليومية، واقصر القائمة الجانبية على الإعدادات والصفحات الثانوية ونادراً ما يُحتاج إليها.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع أكثر من 5 خيارات في شريط التنقل السفلي مما يجعل الأزرار ضيقة ومتداخلة.","إخفاء الأقسام الأساسية للمنتج داخل قائمة هامبرغر في تطبيقات المتاجر أو الخدمات الرئيسية."]'::jsonb or l.follow_up_questions is distinct from '["ما هو نمط الملاحة الهجين (Tabs + More Menu) ومتى يُعتبر حلاً عملياً؟","كيف يؤثر التمرير الإخفائي (Scroll-to-hide) لشريط الملاحة السفلي على تجربة القراءة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Hamburger Menus and Hidden Navigation Hurt UX Metrics","url":"https://www.nngroup.com/articles/hamburger-menus/"}]'::jsonb)) then raise exception 'Question uxia-005 ar content changed; create a new revision before seeding'; end if; end $$;
