insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم حالات الفراغ (Empty States) لتحويل الشاشات الخالية إلى فرص توجيه وتفاعل فعالة؟', 'حالة الفراغ ليست مجرد شاشة بيضاء، بل هي مساحة إرشادية تعليمية تخبر المستخدم عن سبب فراغ الشاشة، وتوجهه بخطوة واضحة وإجراء مباشر للبدء وملء البيانات.', 'تحدث حالات الفراغ في عدة سياقات: عند أول استخدام للمنتج (First-use)، عند إتمام وحذف كافة المهام (Cleared/Success)، أو عند عدم العثور على نتائج بحث (No results). يجب أن تحتوي دائماً على: رسم توضيحي معبر، رسالة مقتضبة وواضحة، وزر إجراء فوري وبارز (Call to Action) مثل ''أنشئ أول مشروع لك الآن''.', null, '["ترك الصفحة خالية تماماً مما يدفع المستخدم للاعتقاد بأن التطبيق معطل أو فشل في الاتصال بالإنترنت.","كتابة رسالة سلبية جافة مثل ''لا توجد بيانات'' دون توضيح كيفية إضافة بيانات."]'::jsonb, '["كيف تساهم بيانات العرض التوضيحية (Starter Templates) في حل مشكلة الشاشة الفارغة الأولى؟","ما الفرق بين Empty State الترحيبي و Empty State الناتج عن أخطاء الاتصال؟"]'::jsonb, '[{"title":"Material Design — Empty States and Communication","url":"https://material.io/design/communication/empty-states.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم حالات الفراغ (Empty States) لتحويل الشاشات الخالية إلى فرص توجيه وتفاعل فعالة؟' or l.short_answer is distinct from 'حالة الفراغ ليست مجرد شاشة بيضاء، بل هي مساحة إرشادية تعليمية تخبر المستخدم عن سبب فراغ الشاشة، وتوجهه بخطوة واضحة وإجراء مباشر للبدء وملء البيانات.' or l.explanation is distinct from 'تحدث حالات الفراغ في عدة سياقات: عند أول استخدام للمنتج (First-use)، عند إتمام وحذف كافة المهام (Cleared/Success)، أو عند عدم العثور على نتائج بحث (No results). يجب أن تحتوي دائماً على: رسم توضيحي معبر، رسالة مقتضبة وواضحة، وزر إجراء فوري وبارز (Call to Action) مثل ''أنشئ أول مشروع لك الآن''.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ترك الصفحة خالية تماماً مما يدفع المستخدم للاعتقاد بأن التطبيق معطل أو فشل في الاتصال بالإنترنت.","كتابة رسالة سلبية جافة مثل ''لا توجد بيانات'' دون توضيح كيفية إضافة بيانات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم بيانات العرض التوضيحية (Starter Templates) في حل مشكلة الشاشة الفارغة الأولى؟","ما الفرق بين Empty State الترحيبي و Empty State الناتج عن أخطاء الاتصال؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Empty States and Communication","url":"https://material.io/design/communication/empty-states.html"}]'::jsonb)) then raise exception 'Question uxia-006 ar content changed; create a new revision before seeding'; end if; end $$;
