insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين التصنيف الصارم الموجه (Taxonomy) والتصنيف الشعبي الحر بالوسوم (Folksonomy)؟', 'الـ Taxonomy هو هيكل هرمي منظم يتم تعريفه مسبقاً من قِبل خبراء النظام، بينما الـ Folksonomy هو تصنيف تشاركي مفتوح ينشئه المستخدمون بحرية عبر الوسوم (Tags).', 'الـ Taxonomy ممتاز في ضمان الدقة والتناغم ومنع تكرار الفئات (مثل التصنيفات الطبية أو أقسام المتاجر الكبرى المنظمة). لكن عيبه الجمود وبطء مواكبة المصطلحات الجديدة. أما الـ Folksonomy (كما في Twitter أو Medium) فيتميز بالمرونة والتعبير التلقائي عن اهتمامات المجتمع، لكنه يسبب فوضى ترادف وتعدد كتابة نفس الكلمة (مثل #ux و #ui_ux). الأنظمة الاحترافية تجمع بين شجرة تصنيف أساسية مدعومة بنظام وسوم مرن.', null, '["الاعتماد الكامل على وسوم المستخدمين دون أي هيكل تحكم، مما يجعل البحث مستحيلاً بعد نمو المحتوى.","فرض تصنيفات بالغة الصرامة والتعقيد تجبر المستخدم على قضاء وقت طويل في فرز كل محتوى يرفعه."]'::jsonb, '["كيف تصمم نظام Controlled Vocabulary يدمج المرونة مع ضبط الجودة في المنصات الكبيرة؟","كيف تستخدم تحليلات البحث الداخلي لتحديث تصنيفات الموقع وتسمياته دورياً؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Tagging and Folksonomies: 7 Best Practices","url":"https://www.nngroup.com/articles/tagging-best-practices/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين التصنيف الصارم الموجه (Taxonomy) والتصنيف الشعبي الحر بالوسوم (Folksonomy)؟' or l.short_answer is distinct from 'الـ Taxonomy هو هيكل هرمي منظم يتم تعريفه مسبقاً من قِبل خبراء النظام، بينما الـ Folksonomy هو تصنيف تشاركي مفتوح ينشئه المستخدمون بحرية عبر الوسوم (Tags).' or l.explanation is distinct from 'الـ Taxonomy ممتاز في ضمان الدقة والتناغم ومنع تكرار الفئات (مثل التصنيفات الطبية أو أقسام المتاجر الكبرى المنظمة). لكن عيبه الجمود وبطء مواكبة المصطلحات الجديدة. أما الـ Folksonomy (كما في Twitter أو Medium) فيتميز بالمرونة والتعبير التلقائي عن اهتمامات المجتمع، لكنه يسبب فوضى ترادف وتعدد كتابة نفس الكلمة (مثل #ux و #ui_ux). الأنظمة الاحترافية تجمع بين شجرة تصنيف أساسية مدعومة بنظام وسوم مرن.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاعتماد الكامل على وسوم المستخدمين دون أي هيكل تحكم، مما يجعل البحث مستحيلاً بعد نمو المحتوى.","فرض تصنيفات بالغة الصرامة والتعقيد تجبر المستخدم على قضاء وقت طويل في فرز كل محتوى يرفعه."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم نظام Controlled Vocabulary يدمج المرونة مع ضبط الجودة في المنصات الكبيرة؟","كيف تستخدم تحليلات البحث الداخلي لتحديث تصنيفات الموقع وتسمياته دورياً؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Tagging and Folksonomies: 7 Best Practices","url":"https://www.nngroup.com/articles/tagging-best-practices/"}]'::jsonb)) then raise exception 'Question uxia-007 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Taxonomies Vs Folksonomies Content Classification?', 'This question checks the core Taxonomies Vs Folksonomies Content Classification concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Taxonomies Vs Folksonomies Content Classification with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Taxonomies Vs Folksonomies Content Classification (point 1).","Missing the key trade-off in Taxonomies Vs Folksonomies Content Classification (point 2)."]'::jsonb, '["How would you apply Taxonomies Vs Folksonomies Content Classification in a production Product Design app (follow-up 1)?","How would you apply Taxonomies Vs Folksonomies Content Classification in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Tagging and Folksonomies: 7 Best Practices","url":"https://www.nngroup.com/articles/tagging-best-practices/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-007' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Taxonomies Vs Folksonomies Content Classification?' or l.short_answer is distinct from 'This question checks the core Taxonomies Vs Folksonomies Content Classification concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Taxonomies Vs Folksonomies Content Classification with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Taxonomies Vs Folksonomies Content Classification (point 1).","Missing the key trade-off in Taxonomies Vs Folksonomies Content Classification (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Taxonomies Vs Folksonomies Content Classification in a production Product Design app (follow-up 1)?","How would you apply Taxonomies Vs Folksonomies Content Classification in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Tagging and Folksonomies: 7 Best Practices","url":"https://www.nngroup.com/articles/tagging-best-practices/"}]'::jsonb)) then raise exception 'Question uxia-007 en content changed; create a new revision before seeding'; end if; end $$;
