insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تفشل الجولات التعريفية الشاملة (Guided Tours) وما هو بديلها الأفضل في تأهيل المستخدم (Onboarding)؟', 'الجولات التي تطلق 10 نوافذ متتالية فور فتح التطبيق تفشل لأن المستخدم يعاني من حمل معرفي زائد ويتخطاها دون قراءة؛ والبديل الأفضل هو التعلم في السياق الفعلي (Contextual / Just-in-Time Onboarding).', 'المستخدم يقوم بتنزيل التطبيق لإنجاز مهمة عاجلة وليس لدراسة كتالوج إرشادي. بدلاً من الجولات الإجبارية المعقدة، اعتمد على: 1) إدخال المستخدم فورا في تجربة القيمة الأساسية (Time-to-Value). 2) تقديم التلميحات البسيطة (Tooltips) في اللحظة التي يحتاج إليها المستخدم فقط أثناء سيره في التدفق. 3) توفير عينات محتوى تفاعلية يجرب التعديل عليها.', null, '["حجب الشاشة بسلسلة طويلة من النوافذ المنبثقة الإجبارية فور أول تشغيل للتطبيق.","شرح كل عناصر الواجهة الواضحة بديهياً والتركيز على أزرار عادية بدلاً من القيمة الفريدة للمنتج."]'::jsonb, '["ما هو مؤشر Time to Value (TTV) وكيف يؤثر تقليصه على نسبة التمسك بالمنتج (Retention)؟","كيف تصمم شاشات جمع التفضيلات الأولية دون تحويلها إلى استمارة مرهقة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Mobile Onboarding: 8 Guidelines","url":"https://www.nngroup.com/articles/mobile-onboarding/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تفشل الجولات التعريفية الشاملة (Guided Tours) وما هو بديلها الأفضل في تأهيل المستخدم (Onboarding)؟' or l.short_answer is distinct from 'الجولات التي تطلق 10 نوافذ متتالية فور فتح التطبيق تفشل لأن المستخدم يعاني من حمل معرفي زائد ويتخطاها دون قراءة؛ والبديل الأفضل هو التعلم في السياق الفعلي (Contextual / Just-in-Time Onboarding).' or l.explanation is distinct from 'المستخدم يقوم بتنزيل التطبيق لإنجاز مهمة عاجلة وليس لدراسة كتالوج إرشادي. بدلاً من الجولات الإجبارية المعقدة، اعتمد على: 1) إدخال المستخدم فورا في تجربة القيمة الأساسية (Time-to-Value). 2) تقديم التلميحات البسيطة (Tooltips) في اللحظة التي يحتاج إليها المستخدم فقط أثناء سيره في التدفق. 3) توفير عينات محتوى تفاعلية يجرب التعديل عليها.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["حجب الشاشة بسلسلة طويلة من النوافذ المنبثقة الإجبارية فور أول تشغيل للتطبيق.","شرح كل عناصر الواجهة الواضحة بديهياً والتركيز على أزرار عادية بدلاً من القيمة الفريدة للمنتج."]'::jsonb or l.follow_up_questions is distinct from '["ما هو مؤشر Time to Value (TTV) وكيف يؤثر تقليصه على نسبة التمسك بالمنتج (Retention)؟","كيف تصمم شاشات جمع التفضيلات الأولية دون تحويلها إلى استمارة مرهقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Mobile Onboarding: 8 Guidelines","url":"https://www.nngroup.com/articles/mobile-onboarding/"}]'::jsonb)) then raise exception 'Question uxia-008 ar content changed; create a new revision before seeding'; end if; end $$;
