insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي منهجية تدقيق المحتوى (Content Audit) وبناء نموذج المحتوى (Content Modeling) في مشاريع إعادة التصميم؟', 'تدقيق المحتوى هو حصر وتقييم شامل لكل المحتوى الحالي لمعرفة ما يجب حذفه أو تحديثه أو دمجه، بينما نمذجة المحتوى هي تفكيك المحتوى إلى عناصره البنائية المستقلة عن التصميم الشكلي.', 'في تدقيق المحتوى (ROT Analysis)، نفحص كل صفحة لتحديد هل المحتوى متكرر (Redundant)، قديم (Outdated)، أو تافه (Trivial). في نمذجة المحتوى، نقوم بتجريد نوع المحتوى (مثلاً ''دورة تدريبية'') إلى حقوله الأساسية: عنوان، مدرب، مدة، متطلبات سابقة، ونتائج تعليمية. هذا يضمن أن بنية المحتوى مرنة وقابلة للعرض في أي شاشة وتغذية الـ Headless CMS دون الاعتماد على صفحة ثابتة واحدة.', null, '["نقل كافة ملفات ومقالات الموقع القديم إلى التصميم الجديد دون فحص جودتها وحداثتها.","تصميم قوالب الصفحات بناءً على نصوص وهمية (Lorem Ipsum) دون معرفة أطوال المحتوى الواقعي وطبيعته."]'::jsonb, '["كيف يمنع تدقيق المحتوى انهيار التصميمات في مرحلة إدخال البيانات الحقيقية؟","ما الفرق بين تدقيق المحتوى الكمي (Inventory) والتدقيق النوعي (Qualitative Assessment)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Content Audits and Inventories","url":"https://www.nngroup.com/articles/content-audits/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي منهجية تدقيق المحتوى (Content Audit) وبناء نموذج المحتوى (Content Modeling) في مشاريع إعادة التصميم؟' or l.short_answer is distinct from 'تدقيق المحتوى هو حصر وتقييم شامل لكل المحتوى الحالي لمعرفة ما يجب حذفه أو تحديثه أو دمجه، بينما نمذجة المحتوى هي تفكيك المحتوى إلى عناصره البنائية المستقلة عن التصميم الشكلي.' or l.explanation is distinct from 'في تدقيق المحتوى (ROT Analysis)، نفحص كل صفحة لتحديد هل المحتوى متكرر (Redundant)، قديم (Outdated)، أو تافه (Trivial). في نمذجة المحتوى، نقوم بتجريد نوع المحتوى (مثلاً ''دورة تدريبية'') إلى حقوله الأساسية: عنوان، مدرب، مدة، متطلبات سابقة، ونتائج تعليمية. هذا يضمن أن بنية المحتوى مرنة وقابلة للعرض في أي شاشة وتغذية الـ Headless CMS دون الاعتماد على صفحة ثابتة واحدة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["نقل كافة ملفات ومقالات الموقع القديم إلى التصميم الجديد دون فحص جودتها وحداثتها.","تصميم قوالب الصفحات بناءً على نصوص وهمية (Lorem Ipsum) دون معرفة أطوال المحتوى الواقعي وطبيعته."]'::jsonb or l.follow_up_questions is distinct from '["كيف يمنع تدقيق المحتوى انهيار التصميمات في مرحلة إدخال البيانات الحقيقية؟","ما الفرق بين تدقيق المحتوى الكمي (Inventory) والتدقيق النوعي (Qualitative Assessment)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Content Audits and Inventories","url":"https://www.nngroup.com/articles/content-audits/"}]'::jsonb)) then raise exception 'Question uxia-009 ar content changed; create a new revision before seeding'; end if; end $$;
