insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف توازن في هندسة المعلومات بين التماثل عبر المنصات (Parity) واحترام خصوصية المنصة (iOS vs Android vs Web)؟', 'الحل هو توحيد النموذج الذهني وبنية البيانات والمهام الأساسية، مع تكييف أدوات التحكم والملاحة والأنماط التفاعلية لكل منصة بحسب معاييرها الخاصة.', 'يجب أن تكون المصطلحات ونطاق الميزات وحساب المستخدم متطابقة على كل الأجهزة حتى لا يشعر المستخدم بنقص عند التبديل بين اللابتوب والهاتف. ومع ذلك، في iOS يجب اتباع Human Interface Guidelines (مثل أشرطة الأدوات العلوية وزر العودة بالتمرير السريع)، وفي Android اتباع Material Design (مثل أزرار FAB وتصرف زر الرجوع على مستوى النظام). فرض تصميم iOS على Android أو العكس يدمر الراحة الذهنية للمستخدم.', null, '["نسخ واجهة موقع الويب حرفياً داخل تطبيق الهاتف دون مراعاة قيود شاشات اللمس.","تطبيق نمط مرئي خاص بنظام تشغيل معين على النظام المنافس (مثل نقل شريط علامات تبويب iOS لأسفل تطبيق أندرويد بطريقة تخالف العادات)."]'::jsonb, '["كيف تترجم القوائم المعقدة الضخمة على الويب المكتبي (Mega Menus) إلى شاشات الهواتف بذكاء؟","ما هي استراتيجية Adaptive IA في دعم الشاشات القابلة للطي (Foldables) والأجهزة اللوحية؟"]'::jsonb, '[{"title":"Apple Developer — Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف توازن في هندسة المعلومات بين التماثل عبر المنصات (Parity) واحترام خصوصية المنصة (iOS vs Android vs Web)؟' or l.short_answer is distinct from 'الحل هو توحيد النموذج الذهني وبنية البيانات والمهام الأساسية، مع تكييف أدوات التحكم والملاحة والأنماط التفاعلية لكل منصة بحسب معاييرها الخاصة.' or l.explanation is distinct from 'يجب أن تكون المصطلحات ونطاق الميزات وحساب المستخدم متطابقة على كل الأجهزة حتى لا يشعر المستخدم بنقص عند التبديل بين اللابتوب والهاتف. ومع ذلك، في iOS يجب اتباع Human Interface Guidelines (مثل أشرطة الأدوات العلوية وزر العودة بالتمرير السريع)، وفي Android اتباع Material Design (مثل أزرار FAB وتصرف زر الرجوع على مستوى النظام). فرض تصميم iOS على Android أو العكس يدمر الراحة الذهنية للمستخدم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["نسخ واجهة موقع الويب حرفياً داخل تطبيق الهاتف دون مراعاة قيود شاشات اللمس.","تطبيق نمط مرئي خاص بنظام تشغيل معين على النظام المنافس (مثل نقل شريط علامات تبويب iOS لأسفل تطبيق أندرويد بطريقة تخالف العادات)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم القوائم المعقدة الضخمة على الويب المكتبي (Mega Menus) إلى شاشات الهواتف بذكاء؟","ما هي استراتيجية Adaptive IA في دعم الشاشات القابلة للطي (Foldables) والأجهزة اللوحية؟"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxia-010 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Cross Platform Ia Parity Vs Platform Conventions?', 'This question checks the core Cross Platform Ia Parity Vs Platform Conventions concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Cross Platform Ia Parity Vs Platform Conventions with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Cross Platform Ia Parity Vs Platform Conventions (point 1).","Missing the key trade-off in Cross Platform Ia Parity Vs Platform Conventions (point 2)."]'::jsonb, '["How would you apply Cross Platform Ia Parity Vs Platform Conventions in a production Product Design app (follow-up 1)?","How would you apply Cross Platform Ia Parity Vs Platform Conventions in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Apple Developer — Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxia-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxia-010' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Cross Platform Ia Parity Vs Platform Conventions?' or l.short_answer is distinct from 'This question checks the core Cross Platform Ia Parity Vs Platform Conventions concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Cross Platform Ia Parity Vs Platform Conventions with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Cross Platform Ia Parity Vs Platform Conventions (point 1).","Missing the key trade-off in Cross Platform Ia Parity Vs Platform Conventions (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Cross Platform Ia Parity Vs Platform Conventions in a production Product Design app (follow-up 1)?","How would you apply Cross Platform Ia Parity Vs Platform Conventions in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxia-010 en content changed; create a new revision before seeding'; end if; end $$;
