insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى تستخدم النماذج الأولية منخفضة الدقة (Low-Fi) ومتى تنتقل إلى عالية الدقة (High-Fi)؟', 'النماذج منخفضة الدقة (الورقية والمخططات السلكية البسيطة) تُستخدم في المراحل المبكرة لاختبار المفاهيم والتدفقات بسرعة وبأقل تكلفة، بينما عالية الدقة تُستخدم لاختبار التفاعل والجماليات الدقيقة قبل التطوير البرمجي.', 'إذا عرضت تصميماً عالي الدقة مبكراً، سينشغل أصحاب المصلحة والمستخدمون بمناقشة درجات الألوان وظلال الأزرار ويتجاهلون المنطق المعماري والخلل في رحلة المستخدم. النماذج السلكية بالأبيض والأسود ترغم الجميع على التركيز على المحتوى، التسلسل الهرمي، وهل الفكرة تحل المشكلة أصلاً. بمجرد استقرار الهيكل، ننتقل للنماذج عالية الدقة المزودة بأنظمة الألوان والحركات الواقعية.', null, '["البدء في Figma برسم أيقونات وألوان وتفاصيل دقيقة في أول جلسة عصف ذهني للمشروع.","اختبار سهولة قراءة النصوص وتباين الألوان عبر نماذج سلكية منخفضة الدقة."]'::jsonb, '["كيف يؤثر نوع النموذج الأولي على صدق ومصداقية ملاحظات المستخدمين في جلسات الاختبار؟","ما هي مخاطر الوقوع في حب النموذج الأولي الأول (IKEA Effect) وكيف تتفاداها؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Prototyping: Low-Fidelity vs. High-Fidelity","url":"https://www.nngroup.com/articles/ux-prototype-hi-lo-fidelity/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'متى تستخدم النماذج الأولية منخفضة الدقة (Low-Fi) ومتى تنتقل إلى عالية الدقة (High-Fi)؟' or l.short_answer is distinct from 'النماذج منخفضة الدقة (الورقية والمخططات السلكية البسيطة) تُستخدم في المراحل المبكرة لاختبار المفاهيم والتدفقات بسرعة وبأقل تكلفة، بينما عالية الدقة تُستخدم لاختبار التفاعل والجماليات الدقيقة قبل التطوير البرمجي.' or l.explanation is distinct from 'إذا عرضت تصميماً عالي الدقة مبكراً، سينشغل أصحاب المصلحة والمستخدمون بمناقشة درجات الألوان وظلال الأزرار ويتجاهلون المنطق المعماري والخلل في رحلة المستخدم. النماذج السلكية بالأبيض والأسود ترغم الجميع على التركيز على المحتوى، التسلسل الهرمي، وهل الفكرة تحل المشكلة أصلاً. بمجرد استقرار الهيكل، ننتقل للنماذج عالية الدقة المزودة بأنظمة الألوان والحركات الواقعية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["البدء في Figma برسم أيقونات وألوان وتفاصيل دقيقة في أول جلسة عصف ذهني للمشروع.","اختبار سهولة قراءة النصوص وتباين الألوان عبر نماذج سلكية منخفضة الدقة."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر نوع النموذج الأولي على صدق ومصداقية ملاحظات المستخدمين في جلسات الاختبار؟","ما هي مخاطر الوقوع في حب النموذج الأولي الأول (IKEA Effect) وكيف تتفاداها؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Prototyping: Low-Fidelity vs. High-Fidelity","url":"https://www.nngroup.com/articles/ux-prototype-hi-lo-fidelity/"}]'::jsonb)) then raise exception 'Question uxpr-001 ar content changed; create a new revision before seeding'; end if; end $$;
