insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxpr-002', 'rapid-prototyping-build-measure-learn', 'ui-ux', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxpr-002', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي دورة النماذج الأولية السريعة (Rapid Prototyping Cycle: Build - Measure - Learn)؟', 'هي عملية تكرارية تهدف إلى بناء نموذج أولي سريع بأقل جهد، واختباره فوراً مع مستخدمين حقيقيين، والتعلم من النتائج لتحسين الفكرة في جولات متتالية قصيرة.', 'الهدف ليس صناعة نموذج مثالي، بل الإجابة عن سؤال محدد أو التحقق من فرضية بأسرع وقت (Failing Fast & Cheap). بدلاً من قضاء شهرين في إعداد مواصفات نظرية، يصمم الفريق نموذجاً في يومين، ويختبره مع 5 مستخدمين في اليوم الثالث، ويحلل المخرجات في اليوم الرابع لتقرير: هل نعدل المسار (Pivot) أم نستمر ونعمق التفاصيل؟', null, '["التعامل مع النموذج الأولي كأنه كود نهائي قابل للشحن، مما يبطئ وتيرة التعديل والتجربة.","تجاهل نتائج الاختبار والتمسك بالتصميم فقط لأن الفريق بذل فيه وقتاً كبيراً."]'::jsonb, '["كيف تضع فرضيات قابلة للقياس (Testable Hypotheses) قبل البدء في رسم النموذج؟","ما الفرق بين إثبات المفهوم (PoC) والنموذج الأولي التفاعلي (Prototype)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Rapid Prototyping: What It Is and How to Do It","url":"https://www.nngroup.com/articles/rapid-prototyping/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي دورة النماذج الأولية السريعة (Rapid Prototyping Cycle: Build - Measure - Learn)؟' or l.short_answer is distinct from 'هي عملية تكرارية تهدف إلى بناء نموذج أولي سريع بأقل جهد، واختباره فوراً مع مستخدمين حقيقيين، والتعلم من النتائج لتحسين الفكرة في جولات متتالية قصيرة.' or l.explanation is distinct from 'الهدف ليس صناعة نموذج مثالي، بل الإجابة عن سؤال محدد أو التحقق من فرضية بأسرع وقت (Failing Fast & Cheap). بدلاً من قضاء شهرين في إعداد مواصفات نظرية، يصمم الفريق نموذجاً في يومين، ويختبره مع 5 مستخدمين في اليوم الثالث، ويحلل المخرجات في اليوم الرابع لتقرير: هل نعدل المسار (Pivot) أم نستمر ونعمق التفاصيل؟' or l.code_example is distinct from null or l.common_mistakes is distinct from '["التعامل مع النموذج الأولي كأنه كود نهائي قابل للشحن، مما يبطئ وتيرة التعديل والتجربة.","تجاهل نتائج الاختبار والتمسك بالتصميم فقط لأن الفريق بذل فيه وقتاً كبيراً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تضع فرضيات قابلة للقياس (Testable Hypotheses) قبل البدء في رسم النموذج؟","ما الفرق بين إثبات المفهوم (PoC) والنموذج الأولي التفاعلي (Prototype)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Rapid Prototyping: What It Is and How to Do It","url":"https://www.nngroup.com/articles/rapid-prototyping/"}]'::jsonb)) then raise exception 'Question uxpr-002 ar content changed; create a new revision before seeding'; end if; end $$;
