insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الأجزاء الأربعة المكونة للتفاعل الدقيق (Micro-interaction) وفقاً لدان سافر (Dan Saffer)؟', 'يتكون كل تفاعل دقيق من 4 أجزاء: 1) المُشغّل (Trigger). 2) القواعد (Rules). 3) التغذية الراجعة (Feedback). 4) الحلقات والأوضاع (Loops & Modes).', 'المُشغّل يبدأ التفاعل (قد يكون يدوياً بنقر زر، أو نظامياً كوصول إشعار). القواعد تحدد ما يحدث برمجياً فور تفعيل المشغل (مثل: لا يمكنك الإرسال إذا كان الحقل فارغاً). التغذية الراجعة تُعلم المستخدم بما حدث بصرياً أو صوتياً أو بالاهتزاز (مثل تحول الزر لعلامة صح واهتزاز الهاتف). الحلقات والأوضاع تحدد ما يحدث مع مرور الوقت أو إذا تكرر الإجراء (مثل زر ''تذكرني'' أو تغيير حالة الزر بعد أول نقرة).', null, '["إضافة حركات جمالية مبهرة لا تقدم أي تغذية راجعة وظيفية للمستخدم حول حالة النظام.","تجاهل تحديد القواعد المنطقية والحالات الاستثنائية للتفاعل والاكتفاء برسم الحالة المثالية."]'::jsonb, '["كيف تمنع تحول التفاعلات الدقيقة المبهجة إلى مصدر إزعاج وتشتيت عند الاستخدام اليومي المتكرر؟","ما هي أفضل الأدوات المتقدمة لمحاكاة التفاعلات الدقيقة المعقدة (مثل Protopie و Framer)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Microinteractions in User Experience","url":"https://www.nngroup.com/articles/microinteractions/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الأجزاء الأربعة المكونة للتفاعل الدقيق (Micro-interaction) وفقاً لدان سافر (Dan Saffer)؟' or l.short_answer is distinct from 'يتكون كل تفاعل دقيق من 4 أجزاء: 1) المُشغّل (Trigger). 2) القواعد (Rules). 3) التغذية الراجعة (Feedback). 4) الحلقات والأوضاع (Loops & Modes).' or l.explanation is distinct from 'المُشغّل يبدأ التفاعل (قد يكون يدوياً بنقر زر، أو نظامياً كوصول إشعار). القواعد تحدد ما يحدث برمجياً فور تفعيل المشغل (مثل: لا يمكنك الإرسال إذا كان الحقل فارغاً). التغذية الراجعة تُعلم المستخدم بما حدث بصرياً أو صوتياً أو بالاهتزاز (مثل تحول الزر لعلامة صح واهتزاز الهاتف). الحلقات والأوضاع تحدد ما يحدث مع مرور الوقت أو إذا تكرر الإجراء (مثل زر ''تذكرني'' أو تغيير حالة الزر بعد أول نقرة).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إضافة حركات جمالية مبهرة لا تقدم أي تغذية راجعة وظيفية للمستخدم حول حالة النظام.","تجاهل تحديد القواعد المنطقية والحالات الاستثنائية للتفاعل والاكتفاء برسم الحالة المثالية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تمنع تحول التفاعلات الدقيقة المبهجة إلى مصدر إزعاج وتشتيت عند الاستخدام اليومي المتكرر؟","ما هي أفضل الأدوات المتقدمة لمحاكاة التفاعلات الدقيقة المعقدة (مثل Protopie و Framer)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Microinteractions in User Experience","url":"https://www.nngroup.com/articles/microinteractions/"}]'::jsonb)) then raise exception 'Question uxpr-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Micro Interactions Four Parts Dan Saffer?', 'This question checks the core Micro Interactions Four Parts Dan Saffer concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Micro Interactions Four Parts Dan Saffer with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Micro Interactions Four Parts Dan Saffer (point 1).","Missing the key trade-off in Micro Interactions Four Parts Dan Saffer (point 2)."]'::jsonb, '["How would you apply Micro Interactions Four Parts Dan Saffer in a production Product Design app (follow-up 1)?","How would you apply Micro Interactions Four Parts Dan Saffer in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Microinteractions in User Experience","url":"https://www.nngroup.com/articles/microinteractions/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-003' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Micro Interactions Four Parts Dan Saffer?' or l.short_answer is distinct from 'This question checks the core Micro Interactions Four Parts Dan Saffer concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Micro Interactions Four Parts Dan Saffer with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Micro Interactions Four Parts Dan Saffer (point 1).","Missing the key trade-off in Micro Interactions Four Parts Dan Saffer (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Micro Interactions Four Parts Dan Saffer in a production Product Design app (follow-up 1)?","How would you apply Micro Interactions Four Parts Dan Saffer in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Microinteractions in User Experience","url":"https://www.nngroup.com/articles/microinteractions/"}]'::jsonb)) then raise exception 'Question uxpr-003 en content changed; create a new revision before seeding'; end if; end $$;
