insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يفشل التصميم الذي يقتصر على المسار المثالي (Happy Path) وكيف تصمم للحالات الحدية (Edge Cases)؟', 'المسار المثالي يمثل جزءاً يسيراً من الواقع؛ إهمال الحالات الحدية (مثل بطء الاتصال، النصوص الطويلة، الصلاحيات المرفوضة، والأرصدة الصفرية) يؤدي لانهيار تجربة المستخدم في بيئة الإنتاج.', 'المصمم المحترف يصمم للحالات الصعبة أولاً: 1) نصوص بأسماء طويلة تكسر تخطيط البطاقات. 2) لغات تكتب من اليمين لليسار (RTL) مقارنة بـ LTR. 3) حالات انقطاع الإنترنت وإعادة المحاولة. 4) الإدخال بحروف ورموز غير متوقعة. 5) حالات انتهاء صلاحية الجلسة أثناء كتابة نموذج طويل. توثيق هذه السيناريوهات يحمي التطبيق من التوقف غير المتوقع ويوفر إرشادات استرداد بديهية.', null, '["استخدام نصوص قصيرة ومثالية من كلمتين في النماذج وتفاجؤ الفريق بكسر التصميم بالبيانات الحقيقية.","ترك حالات الخطأ دون توجيه المستخدم لكيفية حل المشكلة أو المحاولة لاحقاً."]'::jsonb, '["كيف تصنع مصفوفة حالات الحافة (Edge-Case Matrix) بالتعاون مع مهندسي البرمجيات والـ QA؟","كيف تصمم استراتيجيات التراجع التلقائي (Graceful Degradation) عند فشل خدمات الطرف الثالث؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Error Message Guidelines","url":"https://www.nngroup.com/articles/error-message-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يفشل التصميم الذي يقتصر على المسار المثالي (Happy Path) وكيف تصمم للحالات الحدية (Edge Cases)؟' or l.short_answer is distinct from 'المسار المثالي يمثل جزءاً يسيراً من الواقع؛ إهمال الحالات الحدية (مثل بطء الاتصال، النصوص الطويلة، الصلاحيات المرفوضة، والأرصدة الصفرية) يؤدي لانهيار تجربة المستخدم في بيئة الإنتاج.' or l.explanation is distinct from 'المصمم المحترف يصمم للحالات الصعبة أولاً: 1) نصوص بأسماء طويلة تكسر تخطيط البطاقات. 2) لغات تكتب من اليمين لليسار (RTL) مقارنة بـ LTR. 3) حالات انقطاع الإنترنت وإعادة المحاولة. 4) الإدخال بحروف ورموز غير متوقعة. 5) حالات انتهاء صلاحية الجلسة أثناء كتابة نموذج طويل. توثيق هذه السيناريوهات يحمي التطبيق من التوقف غير المتوقع ويوفر إرشادات استرداد بديهية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام نصوص قصيرة ومثالية من كلمتين في النماذج وتفاجؤ الفريق بكسر التصميم بالبيانات الحقيقية.","ترك حالات الخطأ دون توجيه المستخدم لكيفية حل المشكلة أو المحاولة لاحقاً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصنع مصفوفة حالات الحافة (Edge-Case Matrix) بالتعاون مع مهندسي البرمجيات والـ QA؟","كيف تصمم استراتيجيات التراجع التلقائي (Graceful Degradation) عند فشل خدمات الطرف الثالث؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Error Message Guidelines","url":"https://www.nngroup.com/articles/error-message-guidelines/"}]'::jsonb)) then raise exception 'Question uxpr-004 ar content changed; create a new revision before seeding'; end if; end $$;
