insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المكونات الأساسية لتسليم التصميم للمطورين (Design Handoff) لضمان دقة التنفيذ؟', 'التسليم الناجح يتجاوز مجرد مشاركة رابط Figma؛ بل يتطلب توفير: توثيق الحالات المختلفة للمكونات، محاذاة Design Tokens مع كود البرمجة، وتحديد قواعد التجاوب وقيود التخطيط (Responsive Constraints).', 'يجب أن يتضمن ملف التسليم: 1) شجرة المكونات وحالاتها (Default, Hover, Active, Focused, Disabled, Error, Loading). 2) تحديد التباعد باستخدام مقياس الـ 8pt والرموز الدلالية (Spacing Tokens). 3) تحديد سلوك الخطوط والنصوص الطويلة (Truncation vs Multiline Wrap). 4) مواصفات الرسوم المتحركة (المدة، منحنى التسارع Easing Curve). الجلوس في جلسة مراجعة مسبقة (Pre-handoff Walkthrough) يمنع إعادة العمل وسوء الفهم.', null, '["تسليم إطارات ثابتة غير مرتبطة بمكونات ودون تحديد ما يحدث على شاشات الهواتف المختلفة.","استخدام قيم ألوان ومسافات اعتباطية (Hardcoded Values) تخالف نظام التصميم المشترك مع المطورين."]'::jsonb, '["كيف تسهم أدوات مثل Figma Dev Mode و Storybook في تضييق الفجوة بين التصميم والإنتاج؟","ما هي أفضل صيغة لتوثيق المنطق التفاعلي المعقد (Interactive Logic) للواجهات المعقدة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Design Handoff: Collaborative Workflows","url":"https://www.nngroup.com/articles/design-handoff/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المكونات الأساسية لتسليم التصميم للمطورين (Design Handoff) لضمان دقة التنفيذ؟' or l.short_answer is distinct from 'التسليم الناجح يتجاوز مجرد مشاركة رابط Figma؛ بل يتطلب توفير: توثيق الحالات المختلفة للمكونات، محاذاة Design Tokens مع كود البرمجة، وتحديد قواعد التجاوب وقيود التخطيط (Responsive Constraints).' or l.explanation is distinct from 'يجب أن يتضمن ملف التسليم: 1) شجرة المكونات وحالاتها (Default, Hover, Active, Focused, Disabled, Error, Loading). 2) تحديد التباعد باستخدام مقياس الـ 8pt والرموز الدلالية (Spacing Tokens). 3) تحديد سلوك الخطوط والنصوص الطويلة (Truncation vs Multiline Wrap). 4) مواصفات الرسوم المتحركة (المدة، منحنى التسارع Easing Curve). الجلوس في جلسة مراجعة مسبقة (Pre-handoff Walkthrough) يمنع إعادة العمل وسوء الفهم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تسليم إطارات ثابتة غير مرتبطة بمكونات ودون تحديد ما يحدث على شاشات الهواتف المختلفة.","استخدام قيم ألوان ومسافات اعتباطية (Hardcoded Values) تخالف نظام التصميم المشترك مع المطورين."]'::jsonb or l.follow_up_questions is distinct from '["كيف تسهم أدوات مثل Figma Dev Mode و Storybook في تضييق الفجوة بين التصميم والإنتاج؟","ما هي أفضل صيغة لتوثيق المنطق التفاعلي المعقد (Interactive Logic) للواجهات المعقدة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Design Handoff: Collaborative Workflows","url":"https://www.nngroup.com/articles/design-handoff/"}]'::jsonb)) then raise exception 'Question uxpr-005 ar content changed; create a new revision before seeding'; end if; end $$;
