insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو التخطيط القصصي (Storyboarding) وكيف يساعد الفريق في فهم السياق الإنساني لاستخدام المنتج؟', 'هو تمثيل بصري متسلسل يشبه القصص المصورة يوضح كيف ومتى ولماذا يستخدم شخص ما المنتج في حياته اليومية لحل مشكلة واقعية.', 'القصص المصورة لا تركز على عناصر الواجهة أو الأزرار، بل على البيئة والمشاعر والسياق المحيط بالمستخدم: هل هو يركب الحافلة ممسكاً بالهاتف بيد واحدة وضوء الشمس يعمي الشاشة؟ هل هو في مكتب هادئ أم في مستودع صاخب؟ هذا السياق يوضح للفريق لماذا نحتاج لأزرار ضخمة أو تباين لوني عالٍ أو تغذية راجعة صوتية، مما يجعل قرارات التصميم مبررة إنسانياً.', null, '["رسم شاشات التطبيق داخل إطارات القصة بدلاً من رسم المستخدم وتفاعله مع بيئته الحقيقية.","المبالغة في جودة الرسم الفني وإضاعة الوقت بدلاً من التركيز على سرد المشكلة والحل بوضوح."]'::jsonb, '["كيف يساعد Storyboarding في مواءمة الرؤية بين فريقي إدارة المنتجات والتسويق مع المصممين؟","ما الفرق بين السيناريو النصي (User Scenario) والقصة المصورة البصرية (Storyboard)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Storyboards Help Visualize UX Ideas","url":"https://www.nngroup.com/articles/storyboards-visualize-ideas/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو التخطيط القصصي (Storyboarding) وكيف يساعد الفريق في فهم السياق الإنساني لاستخدام المنتج؟' or l.short_answer is distinct from 'هو تمثيل بصري متسلسل يشبه القصص المصورة يوضح كيف ومتى ولماذا يستخدم شخص ما المنتج في حياته اليومية لحل مشكلة واقعية.' or l.explanation is distinct from 'القصص المصورة لا تركز على عناصر الواجهة أو الأزرار، بل على البيئة والمشاعر والسياق المحيط بالمستخدم: هل هو يركب الحافلة ممسكاً بالهاتف بيد واحدة وضوء الشمس يعمي الشاشة؟ هل هو في مكتب هادئ أم في مستودع صاخب؟ هذا السياق يوضح للفريق لماذا نحتاج لأزرار ضخمة أو تباين لوني عالٍ أو تغذية راجعة صوتية، مما يجعل قرارات التصميم مبررة إنسانياً.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["رسم شاشات التطبيق داخل إطارات القصة بدلاً من رسم المستخدم وتفاعله مع بيئته الحقيقية.","المبالغة في جودة الرسم الفني وإضاعة الوقت بدلاً من التركيز على سرد المشكلة والحل بوضوح."]'::jsonb or l.follow_up_questions is distinct from '["كيف يساعد Storyboarding في مواءمة الرؤية بين فريقي إدارة المنتجات والتسويق مع المصممين؟","ما الفرق بين السيناريو النصي (User Scenario) والقصة المصورة البصرية (Storyboard)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Storyboards Help Visualize UX Ideas","url":"https://www.nngroup.com/articles/storyboards-visualize-ideas/"}]'::jsonb)) then raise exception 'Question uxpr-006 ar content changed; create a new revision before seeding'; end if; end $$;
