insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يعد استخدام النصوص الوهمية (Lorem Ipsum) والصور المثالية خطراً كبيراً في النماذج الأولية؟', 'لأن البيانات الحقيقية تتميز بالتفاوت وعدم التناسق، واستخدام نصوص وهمية يخلق وهماً زائفاً بنظافة التخطيط ويحجب مشاكل القراءة والكسر التي تظهر فور تغذية النظام ببيانات الواقع.', 'في الواقع، قد يكون اسم المستخدم ''محمد'' المكون من 4 أحرف أو اسماً ألمانياً مركباً من 35 حرفاً. صور المنتجات في الحياة الواقعية قد تكون رديئة الإضاءة وذات خلفيات غير متجانسة وليست كصور النماذج الإعلانية. ملء النماذج الأولية بمحتوى واقعي ومترجم يكشف عيوب المساحات، ويساعد المشاركين في اختبارات قابلية الاستخدام على التفاعل بجدية وتصديق التجربة.', null, '["اختبار الواجهات بنصوص لاتينية لا يفهمها المستخدم، مما يشتت انتباهه في محاولة فك الكلمات.","تصميم بطاقات المنتجات معتمدة على صور ذات خلفية بيضاء نقية تتشوه بمجرد رفع صور حقيقية."]'::jsonb, '["كيف تستخدم ملحقات Figma لجلب بيانات حقيقية من Google Sheets أو APIs أثناء التصميم؟","كيف تصمم حلول التراجع للنصوص الطويلة (Text Clamping and Tooltips)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Why Real Content Matters in Prototypes","url":"https://www.nngroup.com/articles/real-content-prototypes/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يعد استخدام النصوص الوهمية (Lorem Ipsum) والصور المثالية خطراً كبيراً في النماذج الأولية؟' or l.short_answer is distinct from 'لأن البيانات الحقيقية تتميز بالتفاوت وعدم التناسق، واستخدام نصوص وهمية يخلق وهماً زائفاً بنظافة التخطيط ويحجب مشاكل القراءة والكسر التي تظهر فور تغذية النظام ببيانات الواقع.' or l.explanation is distinct from 'في الواقع، قد يكون اسم المستخدم ''محمد'' المكون من 4 أحرف أو اسماً ألمانياً مركباً من 35 حرفاً. صور المنتجات في الحياة الواقعية قد تكون رديئة الإضاءة وذات خلفيات غير متجانسة وليست كصور النماذج الإعلانية. ملء النماذج الأولية بمحتوى واقعي ومترجم يكشف عيوب المساحات، ويساعد المشاركين في اختبارات قابلية الاستخدام على التفاعل بجدية وتصديق التجربة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اختبار الواجهات بنصوص لاتينية لا يفهمها المستخدم، مما يشتت انتباهه في محاولة فك الكلمات.","تصميم بطاقات المنتجات معتمدة على صور ذات خلفية بيضاء نقية تتشوه بمجرد رفع صور حقيقية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستخدم ملحقات Figma لجلب بيانات حقيقية من Google Sheets أو APIs أثناء التصميم؟","كيف تصمم حلول التراجع للنصوص الطويلة (Text Clamping and Tooltips)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Why Real Content Matters in Prototypes","url":"https://www.nngroup.com/articles/real-content-prototypes/"}]'::jsonb)) then raise exception 'Question uxpr-007 ar content changed; create a new revision before seeding'; end if; end $$;
