insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو مخطط الخدمة (Service Blueprint) وما الفرق بين كواليس الواجهة (Frontstage) وخلفيتها (Backstage)؟', 'مخطط الخدمة هو خريطة تفصيلية توضح كيف تدعم العمليات الداخلية والتقنية في الكواليس (Backstage) رحلة المستخدم وتفاعلاته الظاهرة على السطح (Frontstage).', 'بينما تركز خريطة رحلة العميل على مشاعر وتصرفات المستخدم فقط، يتعمق الـ Service Blueprint ليوضح ما يجب أن يفعله الموظفون الداخليون، الأنظمة البرمجية، وقواعد البيانات في كل خطوة لجعل تلك التجربة ممكنة. يشمل 5 طبقات: إجراءات العميل، أفعال الواجهة الظاهرة (Frontstage)، أفعال الكواليس الخفية (Backstage)، العمليات والأنظمة الداعمة، والأدلة المادية.', null, '["تصميم تجربة مستخدم مبهرة على الشاشة دون التحقق من إمكانية تنفيذ الأنظمة اللوجستية والتقنية لدعمها.","الخلط بين رحلة المستخدم التي تركز على العميل ومخطط الخدمة الذي يدمج العمليات التشغيلية للمنظمة."]'::jsonb, '["ما هو ''خط الرؤية'' (Line of Visibility) في مخطط الخدمة وما أهميته؟","كيف يكشف Service Blueprint نقاط الاختناق (Bottlenecks) في تطبيقات التوصيل والخدمات اللوجستية؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Service Blueprints: Definition","url":"https://www.nngroup.com/articles/service-blueprints-definition/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو مخطط الخدمة (Service Blueprint) وما الفرق بين كواليس الواجهة (Frontstage) وخلفيتها (Backstage)؟' or l.short_answer is distinct from 'مخطط الخدمة هو خريطة تفصيلية توضح كيف تدعم العمليات الداخلية والتقنية في الكواليس (Backstage) رحلة المستخدم وتفاعلاته الظاهرة على السطح (Frontstage).' or l.explanation is distinct from 'بينما تركز خريطة رحلة العميل على مشاعر وتصرفات المستخدم فقط، يتعمق الـ Service Blueprint ليوضح ما يجب أن يفعله الموظفون الداخليون، الأنظمة البرمجية، وقواعد البيانات في كل خطوة لجعل تلك التجربة ممكنة. يشمل 5 طبقات: إجراءات العميل، أفعال الواجهة الظاهرة (Frontstage)، أفعال الكواليس الخفية (Backstage)، العمليات والأنظمة الداعمة، والأدلة المادية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تصميم تجربة مستخدم مبهرة على الشاشة دون التحقق من إمكانية تنفيذ الأنظمة اللوجستية والتقنية لدعمها.","الخلط بين رحلة المستخدم التي تركز على العميل ومخطط الخدمة الذي يدمج العمليات التشغيلية للمنظمة."]'::jsonb or l.follow_up_questions is distinct from '["ما هو ''خط الرؤية'' (Line of Visibility) في مخطط الخدمة وما أهميته؟","كيف يكشف Service Blueprint نقاط الاختناق (Bottlenecks) في تطبيقات التوصيل والخدمات اللوجستية؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Service Blueprints: Definition","url":"https://www.nngroup.com/articles/service-blueprints-definition/"}]'::jsonb)) then raise exception 'Question uxpr-008 ar content changed; create a new revision before seeding'; end if; end $$;
