insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تنقل النماذج الأولية من شاشات ثابتة مترابطة إلى نماذج ذكية معتمدة على المتغيرات والشروط (Variables & Logic)؟', 'باستخدام ميزات المتغيرات (Variables)، التعبيرات الرياضية، والعبارات الشرطية (Conditionals) لمحاكاة سلوك التطبيق الحقيقي كأنظمة السلال والحسابات وتسجيل الدخول دون الحاجة لبرمجة كود حقيقي.', 'النماذج التقليدية كانت تتطلب إنشاء 20 شاشة مكررة لمحاكاة إضافة عنصر لسلة التسوق وتعديل كميته وحساب المجموع الكلي. في النماذج المتقدمة الحديثة، يتم استخدام متغير رقمي (CartCount) يتغير بالنقر على زر (+) أو (-)، مع شروط (If CartCount == 0 show EmptyState). هذا يرفع دقة اختبارات قابلية الاستخدام ويسمح للمستخدمين بتجربة مدخلاتهم الخاصة بحرية تامة.', null, '["المبالغة في برمجة النماذج المعقدة جداً التي تستغرق أسابيع بدلاً من إنتاج كود أولي حقيقي.","الاعتماد على روابط الشاشات المباشرة فقط في اختبارات تعتمد على التفاعل الحسابي والبيانات."]'::jsonb, '["متى يكون استخدام أدوات متقدمة مثل ProtoPie أو Framer ضرورياً مقارنة بنماذج Figma؟","كيف تساهم النماذج المبنية على المتغيرات في اختبار حالات الدفع متعددة الخطوات بواقعية تامة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Interactive Prototypes in UX Testing","url":"https://www.nngroup.com/articles/ux-prototype-hi-lo-fidelity/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تنقل النماذج الأولية من شاشات ثابتة مترابطة إلى نماذج ذكية معتمدة على المتغيرات والشروط (Variables & Logic)؟' or l.short_answer is distinct from 'باستخدام ميزات المتغيرات (Variables)، التعبيرات الرياضية، والعبارات الشرطية (Conditionals) لمحاكاة سلوك التطبيق الحقيقي كأنظمة السلال والحسابات وتسجيل الدخول دون الحاجة لبرمجة كود حقيقي.' or l.explanation is distinct from 'النماذج التقليدية كانت تتطلب إنشاء 20 شاشة مكررة لمحاكاة إضافة عنصر لسلة التسوق وتعديل كميته وحساب المجموع الكلي. في النماذج المتقدمة الحديثة، يتم استخدام متغير رقمي (CartCount) يتغير بالنقر على زر (+) أو (-)، مع شروط (If CartCount == 0 show EmptyState). هذا يرفع دقة اختبارات قابلية الاستخدام ويسمح للمستخدمين بتجربة مدخلاتهم الخاصة بحرية تامة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["المبالغة في برمجة النماذج المعقدة جداً التي تستغرق أسابيع بدلاً من إنتاج كود أولي حقيقي.","الاعتماد على روابط الشاشات المباشرة فقط في اختبارات تعتمد على التفاعل الحسابي والبيانات."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون استخدام أدوات متقدمة مثل ProtoPie أو Framer ضرورياً مقارنة بنماذج Figma؟","كيف تساهم النماذج المبنية على المتغيرات في اختبار حالات الدفع متعددة الخطوات بواقعية تامة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Interactive Prototypes in UX Testing","url":"https://www.nngroup.com/articles/ux-prototype-hi-lo-fidelity/"}]'::jsonb)) then raise exception 'Question uxpr-009 ar content changed; create a new revision before seeding'; end if; end $$;
