insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم المعالجات التدريجية (Wizards / Steppers) للمهام المعقدة دون خلق إحباط لدى المستخدم؟', 'بتجزئة العملية الطويلة المرهقة إلى خطوات منطقية صغيرة ومترابطة، مع إظهار مؤشر تقدم واضح، وتمكين المستخدم من الحفظ والتراجع بحرية دون فقدان البيانات.', 'أفضل ممارسات الـ Stepper: 1) إظهار عدد الخطوات ومسمياتها بوضوح (الخطوة 2 من 4: بيانات الشحن). 2) السماح بالتنقل للخطوات السابقة لتعديل البيانات وتأكيد حفظ المسودات تلقائياً. 3) تخصيص كل خطوة لموضوع واحد متجانس. 4) عرض شاشة مراجعة نهائية (Review & Confirm) قبل التنفيذ المصيري.', null, '["إخفاء إجمالي عدد الخطوات مما يجعل المستخدم يشعر بنفق لا نهائي ويدفعه للتخلي عن العملية.","مسح البيانات المدخلة في الخطوات السابقة بمجرد نقر المستخدم على زر ''السابق''."]'::jsonb, '["متى يكون Stepper الأفقي أفضل من الرأسي في واجهات الهواتف والويب؟","كيف تصمم معالجاً مرناً يدعم الخطوات الاختيارية والمسارات المتشعبة (Conditional Branching)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Wizards: Definition and Design Recommendations","url":"https://www.nngroup.com/articles/wizards/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpr-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpr-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم المعالجات التدريجية (Wizards / Steppers) للمهام المعقدة دون خلق إحباط لدى المستخدم؟' or l.short_answer is distinct from 'بتجزئة العملية الطويلة المرهقة إلى خطوات منطقية صغيرة ومترابطة، مع إظهار مؤشر تقدم واضح، وتمكين المستخدم من الحفظ والتراجع بحرية دون فقدان البيانات.' or l.explanation is distinct from 'أفضل ممارسات الـ Stepper: 1) إظهار عدد الخطوات ومسمياتها بوضوح (الخطوة 2 من 4: بيانات الشحن). 2) السماح بالتنقل للخطوات السابقة لتعديل البيانات وتأكيد حفظ المسودات تلقائياً. 3) تخصيص كل خطوة لموضوع واحد متجانس. 4) عرض شاشة مراجعة نهائية (Review & Confirm) قبل التنفيذ المصيري.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إخفاء إجمالي عدد الخطوات مما يجعل المستخدم يشعر بنفق لا نهائي ويدفعه للتخلي عن العملية.","مسح البيانات المدخلة في الخطوات السابقة بمجرد نقر المستخدم على زر ''السابق''."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون Stepper الأفقي أفضل من الرأسي في واجهات الهواتف والويب؟","كيف تصمم معالجاً مرناً يدعم الخطوات الاختيارية والمسارات المتشعبة (Conditional Branching)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Wizards: Definition and Design Recommendations","url":"https://www.nngroup.com/articles/wizards/"}]'::jsonb)) then raise exception 'Question uxpr-010 ar content changed; create a new revision before seeding'; end if; end $$;
