insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxds-001', 'design-system-vs-component-library-vs-style-guide', 'ui-ux', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
