insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين نظام التصميم (Design System) ومكتبة المكونات (Component Library) ودليل الأسلوب (Style Guide)؟', 'دليل الأسلوب يحدد الهوية البصرية (ألوان وخطوط)، ومكتبة المكونات توفر عناصر برمجية قابلة لإعادة الاستخدام، بينما نظام التصميم هو المنظومة الشاملة التي تدمج الأدلة والمكونات والقواعد والمعايير والحوكمة.', 'دليل الأسلوب (Style Guide) وثيقة توضح كيفية تمثيل العلامة التجارية بصرياً. مكتبة المكونات (Component Library) هي كود برمجي (مثل React components أو ملف Figma) يحتوي عناصر جاهزة كالأزرار والحقول. أما نظام التصميم (Design System) فهو ''المنتج الذي يخدم المنتجات الأخرى''؛ يشمل المكونات البرمجية، رموز التصميم (Tokens)، إرشادات إمكانية الوصول، نبرة الصوت (Tone of Voice)، وأساليب الحوكمة والمساهمة بين المصممين والمطورين.', null, '["اعتبار ملف Figma الذي يضم مجموعة أزرار وألوان نظام تصميم متكامل.","بناء مكتبة مكونات برمجية دون توثيق مبادئ استخدامها وقواعد تفاعلها."]'::jsonb, '["كيف تبرر للإدارة الاستثمار في بناء نظام تصميم بدلاً من المكونات العشوائية؟","ما هي دورة حياة المكون داخل نظام التصميم من الاقتراح حتى الاستهلاك؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Design Systems 101","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين نظام التصميم (Design System) ومكتبة المكونات (Component Library) ودليل الأسلوب (Style Guide)؟' or l.short_answer is distinct from 'دليل الأسلوب يحدد الهوية البصرية (ألوان وخطوط)، ومكتبة المكونات توفر عناصر برمجية قابلة لإعادة الاستخدام، بينما نظام التصميم هو المنظومة الشاملة التي تدمج الأدلة والمكونات والقواعد والمعايير والحوكمة.' or l.explanation is distinct from 'دليل الأسلوب (Style Guide) وثيقة توضح كيفية تمثيل العلامة التجارية بصرياً. مكتبة المكونات (Component Library) هي كود برمجي (مثل React components أو ملف Figma) يحتوي عناصر جاهزة كالأزرار والحقول. أما نظام التصميم (Design System) فهو ''المنتج الذي يخدم المنتجات الأخرى''؛ يشمل المكونات البرمجية، رموز التصميم (Tokens)، إرشادات إمكانية الوصول، نبرة الصوت (Tone of Voice)، وأساليب الحوكمة والمساهمة بين المصممين والمطورين.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار ملف Figma الذي يضم مجموعة أزرار وألوان نظام تصميم متكامل.","بناء مكتبة مكونات برمجية دون توثيق مبادئ استخدامها وقواعد تفاعلها."]'::jsonb or l.follow_up_questions is distinct from '["كيف تبرر للإدارة الاستثمار في بناء نظام تصميم بدلاً من المكونات العشوائية؟","ما هي دورة حياة المكون داخل نظام التصميم من الاقتراح حتى الاستهلاك؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Design Systems 101","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Design System Vs Component Library Vs Style Guide?', 'This question checks the core Design System Vs Component Library Vs Style Guide concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Design System Vs Component Library Vs Style Guide with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Design System Vs Component Library Vs Style Guide (point 1).","Missing the key trade-off in Design System Vs Component Library Vs Style Guide (point 2)."]'::jsonb, '["How would you apply Design System Vs Component Library Vs Style Guide in a production Product Design app (follow-up 1)?","How would you apply Design System Vs Component Library Vs Style Guide in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Design Systems 101","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-001' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Design System Vs Component Library Vs Style Guide?' or l.short_answer is distinct from 'This question checks the core Design System Vs Component Library Vs Style Guide concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Design System Vs Component Library Vs Style Guide with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Design System Vs Component Library Vs Style Guide (point 1).","Missing the key trade-off in Design System Vs Component Library Vs Style Guide (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Design System Vs Component Library Vs Style Guide in a production Product Design app (follow-up 1)?","How would you apply Design System Vs Component Library Vs Style Guide in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Design Systems 101","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-001 en content changed; create a new revision before seeding'; end if; end $$;
