insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي منهجية التصميم الذري (Atomic Design) لبراد فروست (Brad Frost) وما هي مراحلها الخمس؟', 'هي منهجية لتفكيك الواجهات وبنائها هرمياً من أصغر العناصر إلى أكملها، وتشمل: الذرات (Atoms)، الجزيئات (Molecules)، الكائنات (Organisms)، القوالب (Templates)، والصفحات (Pages).', 'الذرات هي العناصر غير القابلة للتجزئة (الألوان، الخطوط، الأزرار الفردية، وحقول الإدخال). الجزيئات تجمع ذرتين أو أكثر لتعمل معاً كوحدة وظيفية (مثل حقل بحث مدمج به زر ''بحث''). الكائنات تدمج عدة جزيئات لتكوين قسم مستقل من الواجهة (مثل الهيدر الكامل أو بطاقة منتج تفاعلية). القوالب ترتب الكائنات في تخطيط هيكلي خالي من المحتوى. وأخيراً الصفحات تملأ القوالب بالمحتوى والبيانات الواقعية لاختبار قوة التصميم.', null, '["التعامل مع التصميم الذري كعملية خطية جامدة بدلاً من كونه أسلوباً ذهنياً لفهم العلاقات التركيبية.","إنشاء جزيئات معقدة جداً يصعب إعادة استخدامها في سياقات مختلفة."]'::jsonb, '["كيف تنعكس مراحل التصميم الذري على تنظيم المجلدات في Figma ومكتبات React/Flutter؟","ما الفرق بين القالب (Template) والصفحة (Page) في قياس مرونة التصميم؟"]'::jsonb, '[{"title":"Material Design — Understanding Layout and Components","url":"https://material.io/design/layout/understanding-layout.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي منهجية التصميم الذري (Atomic Design) لبراد فروست (Brad Frost) وما هي مراحلها الخمس؟' or l.short_answer is distinct from 'هي منهجية لتفكيك الواجهات وبنائها هرمياً من أصغر العناصر إلى أكملها، وتشمل: الذرات (Atoms)، الجزيئات (Molecules)، الكائنات (Organisms)، القوالب (Templates)، والصفحات (Pages).' or l.explanation is distinct from 'الذرات هي العناصر غير القابلة للتجزئة (الألوان، الخطوط، الأزرار الفردية، وحقول الإدخال). الجزيئات تجمع ذرتين أو أكثر لتعمل معاً كوحدة وظيفية (مثل حقل بحث مدمج به زر ''بحث''). الكائنات تدمج عدة جزيئات لتكوين قسم مستقل من الواجهة (مثل الهيدر الكامل أو بطاقة منتج تفاعلية). القوالب ترتب الكائنات في تخطيط هيكلي خالي من المحتوى. وأخيراً الصفحات تملأ القوالب بالمحتوى والبيانات الواقعية لاختبار قوة التصميم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["التعامل مع التصميم الذري كعملية خطية جامدة بدلاً من كونه أسلوباً ذهنياً لفهم العلاقات التركيبية.","إنشاء جزيئات معقدة جداً يصعب إعادة استخدامها في سياقات مختلفة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تنعكس مراحل التصميم الذري على تنظيم المجلدات في Figma ومكتبات React/Flutter؟","ما الفرق بين القالب (Template) والصفحة (Page) في قياس مرونة التصميم؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Understanding Layout and Components","url":"https://material.io/design/layout/understanding-layout.html"}]'::jsonb)) then raise exception 'Question uxds-002 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Atomic Design Methodology Brad Frost?', 'This question checks the core Atomic Design Methodology Brad Frost concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Atomic Design Methodology Brad Frost with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Atomic Design Methodology Brad Frost (point 1).","Missing the key trade-off in Atomic Design Methodology Brad Frost (point 2)."]'::jsonb, '["How would you apply Atomic Design Methodology Brad Frost in a production Product Design app (follow-up 1)?","How would you apply Atomic Design Methodology Brad Frost in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Understanding Layout and Components","url":"https://material.io/design/layout/understanding-layout.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
