insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي رموز التصميم (Design Tokens) وما الفرق بين المستويات العالمية والدلالية والخاصة بالمكون؟', 'رموز التصميم هي القرارات البصرية المجردة المخزنة كمتغيرات مستقلة عن المنصة (مثل JSON)، وتنقسم إلى 3 طبقات: الرموز العالمية (Global)، الرموز الدلالية (Semantic/Alias)، والرموز المخصصة للمكون (Component-specific).', 'الرموز العالمية تعرف القيم الخام المجردة (مثل: color-blue-500 = #0066FF). الرموز الدلالية تصف الغرض الوظيفي للرمز وترتبط بالرمز العالمي (مثل: color-action-primary = color-blue-500). رموز المكون تخصص الاستخدام لعنصر محدد (مثل: button-primary-bg = color-action-primary). هذه المعمارية ثلاثية الطبقات هي ما يتيح دعم الوضع الليلي وتعدد العلامات التجارية (Multi-brand) بضغطة زر واحدة دون لمس كود المكونات.', null, '["ربط المكونات مباشرة بالرموز العالمية الخام (مثل كتابة blue-500 للزر)، مما يجعل تفعيل الوضع الليلي مستحيلاً لاحقاً.","تسمية الرموز الدلالية بأسماء ألوان بدلاً من وظيفتها (مثل تسمية الخلفية bg-white بدلاً من bg-surface)."]'::jsonb, '["كيف تحول أداة Style Dictionary رموز JSON إلى متغيرات CSS وSwift وKotlin آلياً؟","كيف تدير الـ Modes في Figma Variables لمحاكاة الثيمات المتعددة بسلاسة؟"]'::jsonb, '[{"title":"Material Design — Design Tokens Architecture","url":"https://material.io/blog/design-tokens"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي رموز التصميم (Design Tokens) وما الفرق بين المستويات العالمية والدلالية والخاصة بالمكون؟' or l.short_answer is distinct from 'رموز التصميم هي القرارات البصرية المجردة المخزنة كمتغيرات مستقلة عن المنصة (مثل JSON)، وتنقسم إلى 3 طبقات: الرموز العالمية (Global)، الرموز الدلالية (Semantic/Alias)، والرموز المخصصة للمكون (Component-specific).' or l.explanation is distinct from 'الرموز العالمية تعرف القيم الخام المجردة (مثل: color-blue-500 = #0066FF). الرموز الدلالية تصف الغرض الوظيفي للرمز وترتبط بالرمز العالمي (مثل: color-action-primary = color-blue-500). رموز المكون تخصص الاستخدام لعنصر محدد (مثل: button-primary-bg = color-action-primary). هذه المعمارية ثلاثية الطبقات هي ما يتيح دعم الوضع الليلي وتعدد العلامات التجارية (Multi-brand) بضغطة زر واحدة دون لمس كود المكونات.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ربط المكونات مباشرة بالرموز العالمية الخام (مثل كتابة blue-500 للزر)، مما يجعل تفعيل الوضع الليلي مستحيلاً لاحقاً.","تسمية الرموز الدلالية بأسماء ألوان بدلاً من وظيفتها (مثل تسمية الخلفية bg-white بدلاً من bg-surface)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحول أداة Style Dictionary رموز JSON إلى متغيرات CSS وSwift وKotlin آلياً؟","كيف تدير الـ Modes في Figma Variables لمحاكاة الثيمات المتعددة بسلاسة؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Design Tokens Architecture","url":"https://material.io/blog/design-tokens"}]'::jsonb)) then raise exception 'Question uxds-003 ar content changed; create a new revision before seeding'; end if; end $$;
