insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني مكونات مرنة واحترافية في Figma باستخدام Auto Layout و Component Properties؟', 'باستخدام Auto Layout لمحاكاة نموذج Flexbox البرمجي، وتوظيف خصائص المكونات (Boolean, Text, Instance Swap, Variant) لتقليص عدد أشكال المكونات وجعلها متوافقة تماماً مع الكود.', 'قديماً كان المصممون ينسخون مئات التوليفات لزر واحد ليغطوا الأيقونة والحجم والحالة. مع Component Properties الحديثة، يُنشأ مكون واحد بخاصية Boolean لإظهار الأيقونة، وخاصية Text لتعديل التسمية، و Variant لتغيير الحجم أو الثيم. يضمن Auto Layout تمدد الأزرار والبطاقات وانكماشها تلقائياً عند تغيير النصوص، محاكياً بدقة سلوك متصفحات الويب وشاشات الهواتف.', null, '["استخدام التجميع العادي (Group) بدلاً من الإطارات المتجاوبة (Auto Layout Frames) في بناء المكونات.","تفجير عدد الـ Variants لعشرات العناصر المتشابهة بدلاً من استخدام خصائص المكونات الذكية."]'::jsonb, '["ما الفرق بين قيود التمدد (Fill Container) والاحتواء (Hug Contents) والثبات (Fixed Width)؟","كيف تصمم بطاقة متجاوبة بالكامل تتكيف مع كافة أحجام الشاشات دون تشوه عناصرها؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Component-Based Design in UI Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تبني مكونات مرنة واحترافية في Figma باستخدام Auto Layout و Component Properties؟' or l.short_answer is distinct from 'باستخدام Auto Layout لمحاكاة نموذج Flexbox البرمجي، وتوظيف خصائص المكونات (Boolean, Text, Instance Swap, Variant) لتقليص عدد أشكال المكونات وجعلها متوافقة تماماً مع الكود.' or l.explanation is distinct from 'قديماً كان المصممون ينسخون مئات التوليفات لزر واحد ليغطوا الأيقونة والحجم والحالة. مع Component Properties الحديثة، يُنشأ مكون واحد بخاصية Boolean لإظهار الأيقونة، وخاصية Text لتعديل التسمية، و Variant لتغيير الحجم أو الثيم. يضمن Auto Layout تمدد الأزرار والبطاقات وانكماشها تلقائياً عند تغيير النصوص، محاكياً بدقة سلوك متصفحات الويب وشاشات الهواتف.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام التجميع العادي (Group) بدلاً من الإطارات المتجاوبة (Auto Layout Frames) في بناء المكونات.","تفجير عدد الـ Variants لعشرات العناصر المتشابهة بدلاً من استخدام خصائص المكونات الذكية."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين قيود التمدد (Fill Container) والاحتواء (Hug Contents) والثبات (Fixed Width)؟","كيف تصمم بطاقة متجاوبة بالكامل تتكيف مع كافة أحجام الشاشات دون تشوه عناصرها؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Component-Based Design in UI Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-004 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Figma Auto Layout And Component Properties?', 'This question checks the core Figma Auto Layout And Component Properties concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Figma Auto Layout And Component Properties with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Figma Auto Layout And Component Properties (point 1).","Missing the key trade-off in Figma Auto Layout And Component Properties (point 2)."]'::jsonb, '["How would you apply Figma Auto Layout And Component Properties in a production Product Design app (follow-up 1)?","How would you apply Figma Auto Layout And Component Properties in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Component-Based Design in UI Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-004' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Figma Auto Layout And Component Properties?' or l.short_answer is distinct from 'This question checks the core Figma Auto Layout And Component Properties concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Figma Auto Layout And Component Properties with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Figma Auto Layout And Component Properties (point 1).","Missing the key trade-off in Figma Auto Layout And Component Properties (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Figma Auto Layout And Component Properties in a production Product Design app (follow-up 1)?","How would you apply Figma Auto Layout And Component Properties in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Component-Based Design in UI Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-004 en content changed; create a new revision before seeding'; end if; end $$;
