insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير حوكمة نظام التصميم (Design System Governance) ونماذج المساهمة لمنع الفوضى أو الجمود؟', 'باعتماد نموذج مساهمة هجين وتعيين فريق أساسي (Core Team) يضع المعايير ويدير مراجعات المكونات، مع فتح الباب للمصممين والمطورين لتقديم مقترحات واحتياجات جديدة عبر مسار تدقيق معتمد (RFC Process).', 'الحوكمة الصارمة المركزية تصيب النظام بالجمود وتدفع الفرق لتجاوزه وبناء حلول خاصة سرية. الحوكمة الفوضوية تلوث النظام بمكونات عشوائية مكررة. النموذج الأمثل هو ''الاتحادي'' (Federated Model): المصممون في فرق المنتجات يحددون الاحتياجات الجديدة ويصنعون مسوداتها، بينما الفريق الأساسي يراجع توافقها مع إمكانية الوصول وDesign Tokens ويضمن تعميمها على الجميع بعد اعتمادها.', null, '["إغلاق نظام التصميم ومنع أي تعديل أو إضافة، مما يجبر الفرق على كسر النظام وتكرار العمل المنفصل.","قبول أي مكون يرسله أي مصمم وإضافته للمكتبة العامة دون تدقيق لتوحيد المعايير."]'::jsonb, '["ما هي معايير قبول مكون جديد (Acceptance Criteria) في نظام التصميم المؤسسي؟","كيف تدير دورة التغييرات الجذرية (Breaking Changes) وإصدار النسخ وفق معيار Semantic Versioning؟"]'::jsonb, '[{"title":"Nielsen Norman Group — A Governance Process for Design Systems","url":"https://www.nngroup.com/articles/design-system-governance/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير حوكمة نظام التصميم (Design System Governance) ونماذج المساهمة لمنع الفوضى أو الجمود؟' or l.short_answer is distinct from 'باعتماد نموذج مساهمة هجين وتعيين فريق أساسي (Core Team) يضع المعايير ويدير مراجعات المكونات، مع فتح الباب للمصممين والمطورين لتقديم مقترحات واحتياجات جديدة عبر مسار تدقيق معتمد (RFC Process).' or l.explanation is distinct from 'الحوكمة الصارمة المركزية تصيب النظام بالجمود وتدفع الفرق لتجاوزه وبناء حلول خاصة سرية. الحوكمة الفوضوية تلوث النظام بمكونات عشوائية مكررة. النموذج الأمثل هو ''الاتحادي'' (Federated Model): المصممون في فرق المنتجات يحددون الاحتياجات الجديدة ويصنعون مسوداتها، بينما الفريق الأساسي يراجع توافقها مع إمكانية الوصول وDesign Tokens ويضمن تعميمها على الجميع بعد اعتمادها.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إغلاق نظام التصميم ومنع أي تعديل أو إضافة، مما يجبر الفرق على كسر النظام وتكرار العمل المنفصل.","قبول أي مكون يرسله أي مصمم وإضافته للمكتبة العامة دون تدقيق لتوحيد المعايير."]'::jsonb or l.follow_up_questions is distinct from '["ما هي معايير قبول مكون جديد (Acceptance Criteria) في نظام التصميم المؤسسي؟","كيف تدير دورة التغييرات الجذرية (Breaking Changes) وإصدار النسخ وفق معيار Semantic Versioning؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — A Governance Process for Design Systems","url":"https://www.nngroup.com/articles/design-system-governance/"}]'::jsonb)) then raise exception 'Question uxds-005 ar content changed; create a new revision before seeding'; end if; end $$;
