insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxds-006', 'theming-and-multi-brand-design-systems', 'ui-ux', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
