insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم معمارية نظام تصميم يدعم علامات تجارية متعددة (Multi-brand) والوضع الليلي (Dark Mode)؟', 'بفصل بنية المكون ومنطقه الهيكلي عن مظهره البصري، واستبدال كافة القيم اللونية المباشرة برموز دلالية (Semantic Tokens) تتغير قيمتها بحسب السياق أو الثيم المفعل.', 'في النظام متعدد العلامات (مثل شركة تمتلك 3 تطبيقات تابعة)، يكون للمكون (مثل بطاقة المنتج) نفس تخطيط Auto Layout ونفس قواعد التفاعل. تختلف العلامات عبر ملف الرموز الدلالية فقط: العلامة (أ) تستخدم درجات أزرق وزوايا مستديرة (radius-sm)، والعلامة (ب) تستخدم درجات أسود وزوايا حادة (radius-none). عند تفعيل الوضع الليلي، يُعاد تعيين الرموز الدلالية السطحية (Surface Tokens) لدرجات معتمة دون الحاجة لإنشاء مكونات جديدة.', null, '["إنشاء مكتبة مكونات كاملة منفصلة لكل علامة تجارية أو لكل وضع إضاءة، مما يضاعف تكلفة الصيانة.","استخدام قيم ألوان مباشرة (Hardcoded Hex Codes) داخل كود المكونات البرمجية أو إطارات Figma."]'::jsonb, '["كيف تتفادى مشاكل تباين الألوان التلقائي عند قلب الثيم من الفاتح إلى الداكن؟","ما هي استراتيجية Elevation Tokens (طبقات الارتفاع) في الوضع الليلي دون استخدام ظلال مفرطة؟"]'::jsonb, '[{"title":"Material Design — Dark Theme Implementation and Contrast","url":"https://material.io/design/color/dark-theme.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم معمارية نظام تصميم يدعم علامات تجارية متعددة (Multi-brand) والوضع الليلي (Dark Mode)؟' or l.short_answer is distinct from 'بفصل بنية المكون ومنطقه الهيكلي عن مظهره البصري، واستبدال كافة القيم اللونية المباشرة برموز دلالية (Semantic Tokens) تتغير قيمتها بحسب السياق أو الثيم المفعل.' or l.explanation is distinct from 'في النظام متعدد العلامات (مثل شركة تمتلك 3 تطبيقات تابعة)، يكون للمكون (مثل بطاقة المنتج) نفس تخطيط Auto Layout ونفس قواعد التفاعل. تختلف العلامات عبر ملف الرموز الدلالية فقط: العلامة (أ) تستخدم درجات أزرق وزوايا مستديرة (radius-sm)، والعلامة (ب) تستخدم درجات أسود وزوايا حادة (radius-none). عند تفعيل الوضع الليلي، يُعاد تعيين الرموز الدلالية السطحية (Surface Tokens) لدرجات معتمة دون الحاجة لإنشاء مكونات جديدة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إنشاء مكتبة مكونات كاملة منفصلة لكل علامة تجارية أو لكل وضع إضاءة، مما يضاعف تكلفة الصيانة.","استخدام قيم ألوان مباشرة (Hardcoded Hex Codes) داخل كود المكونات البرمجية أو إطارات Figma."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتفادى مشاكل تباين الألوان التلقائي عند قلب الثيم من الفاتح إلى الداكن؟","ما هي استراتيجية Elevation Tokens (طبقات الارتفاع) في الوضع الليلي دون استخدام ظلال مفرطة؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Dark Theme Implementation and Contrast","url":"https://material.io/design/color/dark-theme.html"}]'::jsonb)) then raise exception 'Question uxds-006 ar content changed; create a new revision before seeding'; end if; end $$;
