insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تقيس معدل تبني نظام التصميم (Adoption Rate) وعائد الاستثمار (ROI) للشركة؟', 'عبر قياس نسبة المكونات البرمجية المشتقة من النظام في كود الإنتاج مقارنة بالمكونات المخصصة، وحساب تسريع وتيرة شحن الميزات وانخفاض أخطاء التصميم وإعادة العمل.', 'مؤشرات الأداء الأساسية (KPIs) لنظام التصميم تشمل: 1) نسبة التغطية (Figma & Code Component Coverage). 2) استخدام Design Tokens في الكود. 3) وقت إطلاق الميزات الجديدة (Time to Market) مقارنة بالفترة السابقة للنظام. 4) توفير ساعات العمل المحسوبة بضرب عدد المصممين والمطورين في الساعات الموفرة شهرياً، مما يثبت الجدوى المالية المباشرة لإدارة الشركة.', null, '["قياس نجاح نظام التصميم بعدد المكونات المنشورة في Figma بدلاً من نسبة استهلاكها الفعلية في الإنتاج.","تجاهل استطلاعات رضا المصممين والمطورين واستجابتهم لتحديثات النظام الدورية."]'::jsonb, '["كيف تستخدم أدوات الفحص الآلي (Linters) لحساب نسبة الرموز المخصصة غير المعتمدة في الكود؟","ما هي استراتيجية إقناع الفرق المتأخرة بالهجرة التدريجية إلى نظام التصميم الموحد؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Measuring the Impact of Design Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تقيس معدل تبني نظام التصميم (Adoption Rate) وعائد الاستثمار (ROI) للشركة؟' or l.short_answer is distinct from 'عبر قياس نسبة المكونات البرمجية المشتقة من النظام في كود الإنتاج مقارنة بالمكونات المخصصة، وحساب تسريع وتيرة شحن الميزات وانخفاض أخطاء التصميم وإعادة العمل.' or l.explanation is distinct from 'مؤشرات الأداء الأساسية (KPIs) لنظام التصميم تشمل: 1) نسبة التغطية (Figma & Code Component Coverage). 2) استخدام Design Tokens في الكود. 3) وقت إطلاق الميزات الجديدة (Time to Market) مقارنة بالفترة السابقة للنظام. 4) توفير ساعات العمل المحسوبة بضرب عدد المصممين والمطورين في الساعات الموفرة شهرياً، مما يثبت الجدوى المالية المباشرة لإدارة الشركة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["قياس نجاح نظام التصميم بعدد المكونات المنشورة في Figma بدلاً من نسبة استهلاكها الفعلية في الإنتاج.","تجاهل استطلاعات رضا المصممين والمطورين واستجابتهم لتحديثات النظام الدورية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستخدم أدوات الفحص الآلي (Linters) لحساب نسبة الرموز المخصصة غير المعتمدة في الكود؟","ما هي استراتيجية إقناع الفرق المتأخرة بالهجرة التدريجية إلى نظام التصميم الموحد؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Measuring the Impact of Design Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-007 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Measuring Design System Adoption And Roi?', 'This question checks the core Measuring Design System Adoption And Roi concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Measuring Design System Adoption And Roi with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Measuring Design System Adoption And Roi (point 1).","Missing the key trade-off in Measuring Design System Adoption And Roi (point 2)."]'::jsonb, '["How would you apply Measuring Design System Adoption And Roi in a production Product Design app (follow-up 1)?","How would you apply Measuring Design System Adoption And Roi in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Measuring the Impact of Design Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-007' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Measuring Design System Adoption And Roi?' or l.short_answer is distinct from 'This question checks the core Measuring Design System Adoption And Roi concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Measuring Design System Adoption And Roi with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Measuring Design System Adoption And Roi (point 1).","Missing the key trade-off in Measuring Design System Adoption And Roi (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Measuring Design System Adoption And Roi in a production Product Design app (follow-up 1)?","How would you apply Measuring Design System Adoption And Roi in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Measuring the Impact of Design Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-007 en content changed; create a new revision before seeding'; end if; end $$;
