insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تعتمد معظم أنظمة التصميم العالمية على مقياس التباعد بـ 8 نقاط (8pt Spacing Grid)؟', 'لأن الرقم 8 قابل للقسمة والمضاعفة بسهولة على أغلب مقاسات الشاشات وكثافات البكسل المختلفة (1x, 2x, 3x) دون إنتاج كسور بكسل عشرية تشوش وضوح العناصر.', 'يعتمد نظام الـ 8pt على مضاعفات ثابتة: (4, 8, 16, 24, 32, 40, 48, 64px) لكل أبعاد العناصر والمسافات البينية (Paddings & Margins). الرقم 4 يُستخدم كخطوة فرعية دقيقة (Half-step) للعناصر الدقيقة كالأيقونات ومسافات النصوص الضيقة. يضمن هذا النظام التناغم البصري الفوري بين الشاشات ويلغي الخلافات العشوائية بين المصمم والمطور حول المسافات.', null, '["استخدام مسافات فردية عشوائية (مثل 13px أو 27px) لا تتبع مقياس المسافات المعتمد.","تجاهل ارتفاع السطر الطباعي (Line Height) وجعله غير متوافق مع شبكة الـ 4pt/8pt."]'::jsonb, '["كيف تضبط ارتفاع سطور الخطوط (Baseline Grid) ليتطابق بسلاسة مع شبكة الـ 8pt؟","ما الفرق بين Grid الأعمدة المتجاوبة (Column Grid) والشبكة الفراغية المكانية (Spatial Spacing System)؟"]'::jsonb, '[{"title":"Material Design — Responsive Layout Grid and Spacing","url":"https://material.io/design/layout/responsive-layout-grid.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تعتمد معظم أنظمة التصميم العالمية على مقياس التباعد بـ 8 نقاط (8pt Spacing Grid)؟' or l.short_answer is distinct from 'لأن الرقم 8 قابل للقسمة والمضاعفة بسهولة على أغلب مقاسات الشاشات وكثافات البكسل المختلفة (1x, 2x, 3x) دون إنتاج كسور بكسل عشرية تشوش وضوح العناصر.' or l.explanation is distinct from 'يعتمد نظام الـ 8pt على مضاعفات ثابتة: (4, 8, 16, 24, 32, 40, 48, 64px) لكل أبعاد العناصر والمسافات البينية (Paddings & Margins). الرقم 4 يُستخدم كخطوة فرعية دقيقة (Half-step) للعناصر الدقيقة كالأيقونات ومسافات النصوص الضيقة. يضمن هذا النظام التناغم البصري الفوري بين الشاشات ويلغي الخلافات العشوائية بين المصمم والمطور حول المسافات.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام مسافات فردية عشوائية (مثل 13px أو 27px) لا تتبع مقياس المسافات المعتمد.","تجاهل ارتفاع السطر الطباعي (Line Height) وجعله غير متوافق مع شبكة الـ 4pt/8pt."]'::jsonb or l.follow_up_questions is distinct from '["كيف تضبط ارتفاع سطور الخطوط (Baseline Grid) ليتطابق بسلاسة مع شبكة الـ 8pt؟","ما الفرق بين Grid الأعمدة المتجاوبة (Column Grid) والشبكة الفراغية المكانية (Spatial Spacing System)؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Responsive Layout Grid and Spacing","url":"https://material.io/design/layout/responsive-layout-grid.html"}]'::jsonb)) then raise exception 'Question uxds-008 ar content changed; create a new revision before seeding'; end if; end $$;
