insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي أفضل الممارسات لتوثيق مكونات نظام التصميم وكتابة إرشادات ''افعل ولا تفعل'' (Dos and Don''ts)؟', 'يجب ألا يقتصر التوثيق على وصف شكل المكون، بل يجب أن يشرح سياق الاستخدام، والبدائل المناسبة، وإرشادات إمكانية الوصول، وأمثلة بصرية ملونة توضح الممارسات الصحيحة والخاطئة.', 'التوثيق الفعال يحتوي على: 1) وصف مختصر للغرض الوظيفي للمكون. 2) متى تستخدمه ومتى تستخدم مكوناً آخر بديلاً. 3) أمثلة Dos and Don''ts واضحة وموضحة بصرياً (مثلاً: لا تضع أكثر من زر رئيسي واحد في بطاقة). 4) إرشادات الكتابة والنبرة (Content Guidelines). 5) معايير لوحة المفاتيح وقارئات الشاشة للمطورين.', null, '["كتابة توثيق نظري مطول يخلو من الأمثلة البصرية التي يقارن بها المصمم عمله سريعاً.","إهمال توثيق السلوكيات التفاعلية وحالات الخطأ وإمكانية الوصول للمكون."]'::jsonb, '["كيف يساهم دمج التوثيق المباشر داخل Storybook في تشجيع المطورين على قراءته؟","كيف تكتب نصوص الخطأ والمساعدة المصاحبة للمكون وفق إرشادات UX Writing الموحدة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Documenting Design Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي أفضل الممارسات لتوثيق مكونات نظام التصميم وكتابة إرشادات ''افعل ولا تفعل'' (Dos and Don''ts)؟' or l.short_answer is distinct from 'يجب ألا يقتصر التوثيق على وصف شكل المكون، بل يجب أن يشرح سياق الاستخدام، والبدائل المناسبة، وإرشادات إمكانية الوصول، وأمثلة بصرية ملونة توضح الممارسات الصحيحة والخاطئة.' or l.explanation is distinct from 'التوثيق الفعال يحتوي على: 1) وصف مختصر للغرض الوظيفي للمكون. 2) متى تستخدمه ومتى تستخدم مكوناً آخر بديلاً. 3) أمثلة Dos and Don''ts واضحة وموضحة بصرياً (مثلاً: لا تضع أكثر من زر رئيسي واحد في بطاقة). 4) إرشادات الكتابة والنبرة (Content Guidelines). 5) معايير لوحة المفاتيح وقارئات الشاشة للمطورين.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["كتابة توثيق نظري مطول يخلو من الأمثلة البصرية التي يقارن بها المصمم عمله سريعاً.","إهمال توثيق السلوكيات التفاعلية وحالات الخطأ وإمكانية الوصول للمكون."]'::jsonb or l.follow_up_questions is distinct from '["كيف يساهم دمج التوثيق المباشر داخل Storybook في تشجيع المطورين على قراءته؟","كيف تكتب نصوص الخطأ والمساعدة المصاحبة للمكون وفق إرشادات UX Writing الموحدة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Documenting Design Systems","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxds-009 ar content changed; create a new revision before seeding'; end if; end $$;
