insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تدير إصدارات نظام التصميم والتغييرات الجذرية (Breaking Changes) باستخدام Semantic Versioning؟', 'باستخدام ترقيم النسخ الدلالي (Major.Minor.Patch)؛ حيث تشير Major للتغييرات الجذرية التي قد تكسر شاشات المنتجات، و Minor للميزات الجديدة المتوافقة رجعياً، و Patch لإصلاح العيوب البصرية البسيطة.', 'إذا قمت بتغيير اسم خاصية (Prop Rename) أو حذفت خياراً أساسياً في المكون أو غيرت تصرف الحاوية الهيكلي، فهذا تغيير جذري (Major Release) يتطلب تنبيهاً مسبقاً ودليلاً للهجرة (Migration Guide) لفرق المنتجات. توفير فترة تعايش (Deprecation Period) يتيح للفرق جدولة تحديث واجهاتها دون تعطيل أعمالها، ويمنع انهيار الشاشات العاملة في بيئة الإنتاج.', null, '["نشر تعديلات جذرية في مكتبة Figma المشتركة دون التنسيق المسبق مع المطورين، مما يحدث فجوة بين التصميم والكود.","تعديل أحجام أو هوامش مكون مستخدم في آلاف الشاشات دون دراسة تأثير التغيير على تخطيط الصفحات القائمة."]'::jsonb, '["كيف تجري اختبارات الانحدار البصري (Visual Regression Testing) قبل إطلاق إصدار جديد لنظام التصميم؟","كيف تدير عملية استهلاك تحديثات مكتبات Figma للفرق الكبيرة دون إرباك المشروعات الجارية؟"]'::jsonb, '[{"title":"Material Design — Updating and Maintaining Design Systems","url":"https://material.io/design"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تدير إصدارات نظام التصميم والتغييرات الجذرية (Breaking Changes) باستخدام Semantic Versioning؟' or l.short_answer is distinct from 'باستخدام ترقيم النسخ الدلالي (Major.Minor.Patch)؛ حيث تشير Major للتغييرات الجذرية التي قد تكسر شاشات المنتجات، و Minor للميزات الجديدة المتوافقة رجعياً، و Patch لإصلاح العيوب البصرية البسيطة.' or l.explanation is distinct from 'إذا قمت بتغيير اسم خاصية (Prop Rename) أو حذفت خياراً أساسياً في المكون أو غيرت تصرف الحاوية الهيكلي، فهذا تغيير جذري (Major Release) يتطلب تنبيهاً مسبقاً ودليلاً للهجرة (Migration Guide) لفرق المنتجات. توفير فترة تعايش (Deprecation Period) يتيح للفرق جدولة تحديث واجهاتها دون تعطيل أعمالها، ويمنع انهيار الشاشات العاملة في بيئة الإنتاج.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["نشر تعديلات جذرية في مكتبة Figma المشتركة دون التنسيق المسبق مع المطورين، مما يحدث فجوة بين التصميم والكود.","تعديل أحجام أو هوامش مكون مستخدم في آلاف الشاشات دون دراسة تأثير التغيير على تخطيط الصفحات القائمة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تجري اختبارات الانحدار البصري (Visual Regression Testing) قبل إطلاق إصدار جديد لنظام التصميم؟","كيف تدير عملية استهلاك تحديثات مكتبات Figma للفرق الكبيرة دون إرباك المشروعات الجارية؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Updating and Maintaining Design Systems","url":"https://material.io/design"}]'::jsonb)) then raise exception 'Question uxds-010 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Design System Versioning And Breaking Changes?', 'This question checks the core Design System Versioning And Breaking Changes concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Design System Versioning And Breaking Changes with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Design System Versioning And Breaking Changes (point 1).","Missing the key trade-off in Design System Versioning And Breaking Changes (point 2)."]'::jsonb, '["How would you apply Design System Versioning And Breaking Changes in a production Product Design app (follow-up 1)?","How would you apply Design System Versioning And Breaking Changes in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Updating and Maintaining Design Systems","url":"https://material.io/design"}]'::jsonb from public.question_revisions r where r.question_id = 'uxds-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxds-010' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Design System Versioning And Breaking Changes?' or l.short_answer is distinct from 'This question checks the core Design System Versioning And Breaking Changes concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Design System Versioning And Breaking Changes with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Design System Versioning And Breaking Changes (point 1).","Missing the key trade-off in Design System Versioning And Breaking Changes (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Design System Versioning And Breaking Changes in a production Product Design app (follow-up 1)?","How would you apply Design System Versioning And Breaking Changes in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Updating and Maintaining Design Systems","url":"https://material.io/design"}]'::jsonb)) then raise exception 'Question uxds-010 en content changed; create a new revision before seeding'; end if; end $$;
