insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الركائز الأساسية لبناء التسلسل الهرمي البصري (Visual Hierarchy) في واجهات المستخدم؟', 'هي توظيف الحجم، والتباين اللوني، والوزن، والمسافات البيضاء، والمحاذاة لتوجيه عين المستخدم تلقائياً نحو المعلومات الأكثر أهمية أولاً.', 'بدون تسلسل هرمي واضح، تتنافس كل العناصر على جذب انتباه المستخدم مما يصيبه بالإرهاق البصري. يعتمد الترتيب الفعال على جعل العنوان الأهم هو الأكبر حجماً والأغمق وزناً، وتوفير مساحة بيضاء رحبة تفصله عما حوله، وجعل النصوص الداعمة ذات ألوان محايدة وحجم أصغر. هذا يتيح للمستخدم مسح الصفحة في أجزاء من الثانية واستيعاب الرسالة قبل البدء في القراءة المتعمقة.', null, '["جعل كل العناصر بارزة وبنفس الحجم واللون الصارخ مما يفقد الصفحة مركز الثقل البصري.","تجاهل تباين الألوان بين النصوص والخلفيات مما يجعل قراءة المحتوى الثانوي مجهدة للعين."]'::jsonb, '["ما هي أنماط المسح البصري الشائعة (F-Pattern و Z-Pattern) ومتى ينطبق كل منهما؟","كيف يؤثر التباين في الموضع والمحاذاة على جذب الانتباه الفوري مقارنة بالألوان وحدها؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Visual Hierarchy in UX: Definitions and Guidelines","url":"https://www.nngroup.com/articles/visual-hierarchy-ux-definition/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الركائز الأساسية لبناء التسلسل الهرمي البصري (Visual Hierarchy) في واجهات المستخدم؟' or l.short_answer is distinct from 'هي توظيف الحجم، والتباين اللوني، والوزن، والمسافات البيضاء، والمحاذاة لتوجيه عين المستخدم تلقائياً نحو المعلومات الأكثر أهمية أولاً.' or l.explanation is distinct from 'بدون تسلسل هرمي واضح، تتنافس كل العناصر على جذب انتباه المستخدم مما يصيبه بالإرهاق البصري. يعتمد الترتيب الفعال على جعل العنوان الأهم هو الأكبر حجماً والأغمق وزناً، وتوفير مساحة بيضاء رحبة تفصله عما حوله، وجعل النصوص الداعمة ذات ألوان محايدة وحجم أصغر. هذا يتيح للمستخدم مسح الصفحة في أجزاء من الثانية واستيعاب الرسالة قبل البدء في القراءة المتعمقة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["جعل كل العناصر بارزة وبنفس الحجم واللون الصارخ مما يفقد الصفحة مركز الثقل البصري.","تجاهل تباين الألوان بين النصوص والخلفيات مما يجعل قراءة المحتوى الثانوي مجهدة للعين."]'::jsonb or l.follow_up_questions is distinct from '["ما هي أنماط المسح البصري الشائعة (F-Pattern و Z-Pattern) ومتى ينطبق كل منهما؟","كيف يؤثر التباين في الموضع والمحاذاة على جذب الانتباه الفوري مقارنة بالألوان وحدها؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Visual Hierarchy in UX: Definitions and Guidelines","url":"https://www.nngroup.com/articles/visual-hierarchy-ux-definition/"}]'::jsonb)) then raise exception 'Question uxvd-001 ar content changed; create a new revision before seeding'; end if; end $$;
