insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطبق قاعدة 60-30-10 في توزيع ألوان واجهة المستخدم باحترافية؟', 'بتخصيص 60% من الشاشة للون السطح المهيمن (عادة خلفية محايدة بيضاء أو رمادية هادئة)، و 30% للون الثانوي الهيكلي (كالبطاقات والقوائم)، و 10% فقط للون التمييز (Accent Color) المخصص لأزرار الإجراء والدعوات الحيوية.', 'تضمن هذه القاعدة الكلاسيكية التوازن البصري وتمنع طغيان الألوان على المحتوى. عندما يكون 10% فقط من الصفحة باللون المميز (مثل الأزرق أو البرتقالي المخصص للـ CTA)، يبرز الزر الأساسي فوراً كمنارة تجذب العين دون أي مجهود، بينما استخدام اللون الصارخ في مساحات واسعة يفقد الأزرار أهميتها ويرهق المستخدم.', null, '["استخدام لون العلامة التجارية الصارخ كخلفية لمساحات شاسعة من الصفحة مما يشوش المحتوى.","تشتيت المستخدم بوجود 5 ألوان مميزة مختلفة للأزرار في نفس الشاشة دون دلالة واضحة."]'::jsonb, '["كيف تختار لوحة الألوان الدلالية (Success, Warning, Danger, Info) لتتسق مع اللون الأساسي؟","ما هي استراتيجيات التعامل مع ألوان البراندينج الصعبة ذات التباين المنخفض مع الأبيض؟"]'::jsonb, '[{"title":"Material Design — The Color System: Key Color Roles","url":"https://material.io/design/color/the-color-system.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطبق قاعدة 60-30-10 في توزيع ألوان واجهة المستخدم باحترافية؟' or l.short_answer is distinct from 'بتخصيص 60% من الشاشة للون السطح المهيمن (عادة خلفية محايدة بيضاء أو رمادية هادئة)، و 30% للون الثانوي الهيكلي (كالبطاقات والقوائم)، و 10% فقط للون التمييز (Accent Color) المخصص لأزرار الإجراء والدعوات الحيوية.' or l.explanation is distinct from 'تضمن هذه القاعدة الكلاسيكية التوازن البصري وتمنع طغيان الألوان على المحتوى. عندما يكون 10% فقط من الصفحة باللون المميز (مثل الأزرق أو البرتقالي المخصص للـ CTA)، يبرز الزر الأساسي فوراً كمنارة تجذب العين دون أي مجهود، بينما استخدام اللون الصارخ في مساحات واسعة يفقد الأزرار أهميتها ويرهق المستخدم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام لون العلامة التجارية الصارخ كخلفية لمساحات شاسعة من الصفحة مما يشوش المحتوى.","تشتيت المستخدم بوجود 5 ألوان مميزة مختلفة للأزرار في نفس الشاشة دون دلالة واضحة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تختار لوحة الألوان الدلالية (Success, Warning, Danger, Info) لتتسق مع اللون الأساسي؟","ما هي استراتيجيات التعامل مع ألوان البراندينج الصعبة ذات التباين المنخفض مع الأبيض؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — The Color System: Key Color Roles","url":"https://material.io/design/color/the-color-system.html"}]'::jsonb)) then raise exception 'Question uxvd-002 ar content changed; create a new revision before seeding'; end if; end $$;
