insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني مقياساً طباعياً هرمياً (Typographic Modular Scale) يضمن تناغم النصوص وتجاوبها؟', 'باستخدام نسبة تكبير وتصغير ثابتة (مثل Major Second 1.125 أو Minor Third 1.200 أو Perfect Fourth 1.333) لتوليد أحجام متدرجة منطقياً للخطوط من أصغر تعليق توضيحي حتى أكبر عنوان رئيسي.', 'بدلاً من اختيار أحجام نصوص عشوائية (مثل 13, 17, 21px)، يعتمد المقياس الطباعي على حجم أساسي (Base Size، غالباً 16px) ويتم ضربه أو قسمته على النسبة الثابتة. يرافق ذلك ضبط دقيق لارتفاع السطر (Line Height: 1.4 إلى 1.6 للنصوص المقروءة و 1.1 إلى 1.2 للعناوين الكبيرة) ومسافات التباعد بين الحروف (Letter Spacing: تباعد طفيف للنصوص الصغيرة وضغط طفيف للعناوين الضخمة).', null, '["استخدام ارتفاع سطر ضيق جداً (Line-height: 1.0) للفقرات الطويلة مما يسبب تداخل السطور.","دمج أكثر من خطين غير متجانسين في نفس الواجهة مما يخلق فوضى شكلية وتشتيتاً للقارئ."]'::jsonb, '["كيف تحدد الطول الأمثل للسطر الطباعي (Measure: 45 إلى 75 حرفاً) لراحة العين في القراءة المستمرة؟","ما هي مميزات استخدام الخطوط المرنة (Variable Fonts) في تحسين أداء وتجاوب الواجهات؟"]'::jsonb, '[{"title":"Material Design — Typography: Hierarchy and Scales","url":"https://material.io/design/typography/the-type-system.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تبني مقياساً طباعياً هرمياً (Typographic Modular Scale) يضمن تناغم النصوص وتجاوبها؟' or l.short_answer is distinct from 'باستخدام نسبة تكبير وتصغير ثابتة (مثل Major Second 1.125 أو Minor Third 1.200 أو Perfect Fourth 1.333) لتوليد أحجام متدرجة منطقياً للخطوط من أصغر تعليق توضيحي حتى أكبر عنوان رئيسي.' or l.explanation is distinct from 'بدلاً من اختيار أحجام نصوص عشوائية (مثل 13, 17, 21px)، يعتمد المقياس الطباعي على حجم أساسي (Base Size، غالباً 16px) ويتم ضربه أو قسمته على النسبة الثابتة. يرافق ذلك ضبط دقيق لارتفاع السطر (Line Height: 1.4 إلى 1.6 للنصوص المقروءة و 1.1 إلى 1.2 للعناوين الكبيرة) ومسافات التباعد بين الحروف (Letter Spacing: تباعد طفيف للنصوص الصغيرة وضغط طفيف للعناوين الضخمة).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام ارتفاع سطر ضيق جداً (Line-height: 1.0) للفقرات الطويلة مما يسبب تداخل السطور.","دمج أكثر من خطين غير متجانسين في نفس الواجهة مما يخلق فوضى شكلية وتشتيتاً للقارئ."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحدد الطول الأمثل للسطر الطباعي (Measure: 45 إلى 75 حرفاً) لراحة العين في القراءة المستمرة؟","ما هي مميزات استخدام الخطوط المرنة (Variable Fonts) في تحسين أداء وتجاوب الواجهات؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Typography: Hierarchy and Scales","url":"https://material.io/design/typography/the-type-system.html"}]'::jsonb)) then raise exception 'Question uxvd-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Typographic Hierarchy And Modular Scale?', 'This question checks the core Typographic Hierarchy And Modular Scale concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Typographic Hierarchy And Modular Scale with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Typographic Hierarchy And Modular Scale (point 1).","Missing the key trade-off in Typographic Hierarchy And Modular Scale (point 2)."]'::jsonb, '["How would you apply Typographic Hierarchy And Modular Scale in a production Product Design app (follow-up 1)?","How would you apply Typographic Hierarchy And Modular Scale in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Typography: Hierarchy and Scales","url":"https://material.io/design/typography/the-type-system.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-003' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Typographic Hierarchy And Modular Scale?' or l.short_answer is distinct from 'This question checks the core Typographic Hierarchy And Modular Scale concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Typographic Hierarchy And Modular Scale with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Typographic Hierarchy And Modular Scale (point 1).","Missing the key trade-off in Typographic Hierarchy And Modular Scale (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Typographic Hierarchy And Modular Scale in a production Product Design app (follow-up 1)?","How would you apply Typographic Hierarchy And Modular Scale in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Typography: Hierarchy and Scales","url":"https://material.io/design/typography/the-type-system.html"}]'::jsonb)) then raise exception 'Question uxvd-003 en content changed; create a new revision before seeding'; end if; end $$;
