insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxvd-004', 'affordance-vs-signifier-don-norman', 'ui-ux', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
