insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين الإتاحة (Affordance) والدلالة البصرية (Signifier) وفقاً لدون نورمان (Don Norman)؟', 'الإتاحة هي الخاصية الفيزيائية أو البرمجية التي تجعل الشيء قابلاً لفعل معين (مثل إمكانية النقر على الزر)، بينما الدلالة هي العلامة أو الإشارة البصرية التي تخبر المستخدم بوجود هذا الفعل وكيفية أدائه.', 'في العالم الرقمي، الشاشة الزجاجية تمتلك إتاحة اللمس فيزيائياً في كل مليمتر منها. لكن الدلالة البصرية (Signifier) هي التي ترشد المستخدم: الظل الخفيف والحدود المرتفعة واللون المختلف للزر تخبر الدماغ البشري: ''هذه المساحة بالذات معدة لتضغط عليها!''. إذا كان العنصر قابلاً للنقر ولكن تصميمه يبدو كنص مسطح عادي خالي من أي دلالة، تفشل الواجهة في توجيه المستخدم.', null, '["تصميم أزرار تبدو تماماً كالبطاقات النصية الثابتة الخالية من أي ظل أو تباين أو حدود (False Signifier).","وضع خطوط تحت نصوص عادية غير تفاعلية مما يوحي للمستخدم بأنها روابط قابلة للنقر."]'::jsonb, '["ما هي الإتاحة السلبية (Negative Affordance) وكيف تظهر في تصميم الأزرار المعطلة (Disabled State)؟","كيف تؤثر حركات الفأرة والـ Hover States كدلالات تفاعلية ديناميكية في واجهات الحواسيب؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Affordances and Signifiers in UI Design","url":"https://www.nngroup.com/articles/affordances-and-signifiers/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين الإتاحة (Affordance) والدلالة البصرية (Signifier) وفقاً لدون نورمان (Don Norman)؟' or l.short_answer is distinct from 'الإتاحة هي الخاصية الفيزيائية أو البرمجية التي تجعل الشيء قابلاً لفعل معين (مثل إمكانية النقر على الزر)، بينما الدلالة هي العلامة أو الإشارة البصرية التي تخبر المستخدم بوجود هذا الفعل وكيفية أدائه.' or l.explanation is distinct from 'في العالم الرقمي، الشاشة الزجاجية تمتلك إتاحة اللمس فيزيائياً في كل مليمتر منها. لكن الدلالة البصرية (Signifier) هي التي ترشد المستخدم: الظل الخفيف والحدود المرتفعة واللون المختلف للزر تخبر الدماغ البشري: ''هذه المساحة بالذات معدة لتضغط عليها!''. إذا كان العنصر قابلاً للنقر ولكن تصميمه يبدو كنص مسطح عادي خالي من أي دلالة، تفشل الواجهة في توجيه المستخدم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تصميم أزرار تبدو تماماً كالبطاقات النصية الثابتة الخالية من أي ظل أو تباين أو حدود (False Signifier).","وضع خطوط تحت نصوص عادية غير تفاعلية مما يوحي للمستخدم بأنها روابط قابلة للنقر."]'::jsonb or l.follow_up_questions is distinct from '["ما هي الإتاحة السلبية (Negative Affordance) وكيف تظهر في تصميم الأزرار المعطلة (Disabled State)؟","كيف تؤثر حركات الفأرة والـ Hover States كدلالات تفاعلية ديناميكية في واجهات الحواسيب؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Affordances and Signifiers in UI Design","url":"https://www.nngroup.com/articles/affordances-and-signifiers/"}]'::jsonb)) then raise exception 'Question uxvd-004 ar content changed; create a new revision before seeding'; end if; end $$;
