insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxvd-005', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي نسب التباين اللوني المعتمدة في معايير إمكانية الوصول (WCAG 2.1 Contrast Ratios) للنصوص والعناصر؟', 'تتطلب المعايير نسبة تباين لا تقل عن 4.5:1 للنصوص العادية، و 3:1 للنصوص الكبيرة (18pt فأكثر أو 14pt عريض) ولعناصر الواجهة الرسومية والأيقونات الأساسية لمستوى AA.', 'التباين اللوني يقيس الفرق بين لمعان النص ولون الخلفية خلفه. يضمن التباين الصحيح تمكن ضعاف البصر وكبار السن وأي شخص يتصفح هاتفه تحت أشعة الشمس المباشرة من قراءة المحتوى بوضوح دون إجهاد. للوصول للمستوى الأرقى (AAA)، ترتفع النسبة المطلوبة إلى 7:1 للنصوص العادية و 4.5:1 للنصوص الكبيرة.', null, '["استخدام نصوص رمادية باهتة على خلفيات بيضاء فاتحة لمجرد أنها تبدو ''عصرية وناعمة''.","الاعتماد على نص فوق صور غير مستقرة الإضاءة دون وضع طبقة تعتيم (Overlay) تضمن ثبات التباين."]'::jsonb, '["كيف تفحص وتضمن التباين اللوني آلياً داخل Figma وأدوات فحص المتصفح؟","ما هي استثناءات معايير التباين في إرشادات WCAG (مثل الشعارات والعناصر المعطلة غير الفعالة)؟"]'::jsonb, '[{"title":"W3C — Web Content Accessibility Guidelines (WCAG) Contrast","url":"https://www.w3.org/WAI/WCAG21/Understanding/contrast-minimum.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي نسب التباين اللوني المعتمدة في معايير إمكانية الوصول (WCAG 2.1 Contrast Ratios) للنصوص والعناصر؟' or l.short_answer is distinct from 'تتطلب المعايير نسبة تباين لا تقل عن 4.5:1 للنصوص العادية، و 3:1 للنصوص الكبيرة (18pt فأكثر أو 14pt عريض) ولعناصر الواجهة الرسومية والأيقونات الأساسية لمستوى AA.' or l.explanation is distinct from 'التباين اللوني يقيس الفرق بين لمعان النص ولون الخلفية خلفه. يضمن التباين الصحيح تمكن ضعاف البصر وكبار السن وأي شخص يتصفح هاتفه تحت أشعة الشمس المباشرة من قراءة المحتوى بوضوح دون إجهاد. للوصول للمستوى الأرقى (AAA)، ترتفع النسبة المطلوبة إلى 7:1 للنصوص العادية و 4.5:1 للنصوص الكبيرة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام نصوص رمادية باهتة على خلفيات بيضاء فاتحة لمجرد أنها تبدو ''عصرية وناعمة''.","الاعتماد على نص فوق صور غير مستقرة الإضاءة دون وضع طبقة تعتيم (Overlay) تضمن ثبات التباين."]'::jsonb or l.follow_up_questions is distinct from '["كيف تفحص وتضمن التباين اللوني آلياً داخل Figma وأدوات فحص المتصفح؟","ما هي استثناءات معايير التباين في إرشادات WCAG (مثل الشعارات والعناصر المعطلة غير الفعالة)؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Web Content Accessibility Guidelines (WCAG) Contrast","url":"https://www.w3.org/WAI/WCAG21/Understanding/contrast-minimum.html"}]'::jsonb)) then raise exception 'Question uxvd-005 ar content changed; create a new revision before seeding'; end if; end $$;
