insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المبادئ التصميمية لإنشاء وضع داكن (Dark Mode) مريح للعين ولا يقتصر على قلب الألوان عشوائياً؟', 'تجنب استخدام الأسود النقي المطلق (#000000) للخلفيات، واستخدام الرمادي الداكن السطحي، وتوضيح العمق والارتفاع (Elevation) عبر تفتيح نغمة الأسطح بدلاً من الاعتماد على الظلال السوداء.', 'الأسود النقي (#000000) مع النصوص البيضاء الصريحة (#FFFFFF) يسبب تبايناً شديد القسوة وظاهرة الهالات المزعجة للعين (Halation Effect). الممارسة القياسية (وفق Material Design) هي استخدام درجات رمادي غامق كـ #121212 كقاعدة. في الوضع الداكن، لا يمكن للظلال السوداء أن تظهر عمق العناصر؛ لذا يتم التعبير عن ارتفاع العنصر (Elevation) بزيادة نسبة لمعان السطح تدريجياً ليكون أقرب لمصدر الضوء الافتراضي.', null, '["قلب الألوان تلقائياً في البرمجة مما يشوه صور المستخدمين ويفسد دلالات الألوان التنبيهية.","استخدام نفس تشبع الألوان الفاقعة الخاصة بالوضع الفاتح في الوضع الداكن مما يسبب اهتزازاً بصرياً مجهداً."]'::jsonb, '["كيف تضبط تشبع الألوان (Desaturating Accents) في الوضع الداكن لضمان راحة المشاهدة؟","ما الفرق بين شاشات OLED وشاشات LCD في توفير طاقة البطارية عند استخدام الألوان الداكنة؟"]'::jsonb, '[{"title":"Material Design — Dark Theme Guidelines and Surface Depths","url":"https://material.io/design/color/dark-theme.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المبادئ التصميمية لإنشاء وضع داكن (Dark Mode) مريح للعين ولا يقتصر على قلب الألوان عشوائياً؟' or l.short_answer is distinct from 'تجنب استخدام الأسود النقي المطلق (#000000) للخلفيات، واستخدام الرمادي الداكن السطحي، وتوضيح العمق والارتفاع (Elevation) عبر تفتيح نغمة الأسطح بدلاً من الاعتماد على الظلال السوداء.' or l.explanation is distinct from 'الأسود النقي (#000000) مع النصوص البيضاء الصريحة (#FFFFFF) يسبب تبايناً شديد القسوة وظاهرة الهالات المزعجة للعين (Halation Effect). الممارسة القياسية (وفق Material Design) هي استخدام درجات رمادي غامق كـ #121212 كقاعدة. في الوضع الداكن، لا يمكن للظلال السوداء أن تظهر عمق العناصر؛ لذا يتم التعبير عن ارتفاع العنصر (Elevation) بزيادة نسبة لمعان السطح تدريجياً ليكون أقرب لمصدر الضوء الافتراضي.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["قلب الألوان تلقائياً في البرمجة مما يشوه صور المستخدمين ويفسد دلالات الألوان التنبيهية.","استخدام نفس تشبع الألوان الفاقعة الخاصة بالوضع الفاتح في الوضع الداكن مما يسبب اهتزازاً بصرياً مجهداً."]'::jsonb or l.follow_up_questions is distinct from '["كيف تضبط تشبع الألوان (Desaturating Accents) في الوضع الداكن لضمان راحة المشاهدة؟","ما الفرق بين شاشات OLED وشاشات LCD في توفير طاقة البطارية عند استخدام الألوان الداكنة؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Dark Theme Guidelines and Surface Depths","url":"https://material.io/design/color/dark-theme.html"}]'::jsonb)) then raise exception 'Question uxvd-006 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Dark Mode Design Principles And Elevation?', 'This question checks the core Dark Mode Design Principles And Elevation concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Dark Mode Design Principles And Elevation with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Dark Mode Design Principles And Elevation (point 1).","Missing the key trade-off in Dark Mode Design Principles And Elevation (point 2)."]'::jsonb, '["How would you apply Dark Mode Design Principles And Elevation in a production Product Design app (follow-up 1)?","How would you apply Dark Mode Design Principles And Elevation in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Dark Theme Guidelines and Surface Depths","url":"https://material.io/design/color/dark-theme.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-006' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Dark Mode Design Principles And Elevation?' or l.short_answer is distinct from 'This question checks the core Dark Mode Design Principles And Elevation concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Dark Mode Design Principles And Elevation with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Dark Mode Design Principles And Elevation (point 1).","Missing the key trade-off in Dark Mode Design Principles And Elevation (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Dark Mode Design Principles And Elevation in a production Product Design app (follow-up 1)?","How would you apply Dark Mode Design Principles And Elevation in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Dark Theme Guidelines and Surface Depths","url":"https://material.io/design/color/dark-theme.html"}]'::jsonb)) then raise exception 'Question uxvd-006 en content changed; create a new revision before seeding'; end if; end $$;
