insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تبني نظام أيقونات (Iconography System) متسقاً بصرياً من حيث الوزن والمحاذاة البصرية وشبكة الرسم؟', 'برسم كافة الأيقونات على شبكة قياسية موحدة (مثل 24x24px)، مع توحيد سمك الخط (Stroke Weight)، وزوايا الاستدارة، وضبط المحاذاة البصرية (Optical Alignment) بدلاً من المحاذاة الهندسية الرياضية الجامدة.', 'الأشكال الهندسية المختلفة لا تملك نفس الوزن البصري؛ فالدائرة أو المثلث بحجم 24x24px يبدو أصغر حجماً للعين البشرية من المربع الكامل 24x24px. لذا توفر شبكات الأيقونات الاحترافية خطوط إرشاد داخلية (Keyline Shapes) تسمح بزيادة أبعاد الدائرة والمثلث قليلاً لتعادل مساحتها كتلة المربع. الاتساق في اتجاه الإضاءة ومستوى التفاصيل يمنع ظهور أيقونة كأنها نشاز مأخوذ من مكتبة غريبة.', null, '["خلط أيقونات مفرغة (Outlined) وأيقونات ممتلئة (Filled) في نفس شريط الملاحة دون دلالة على الحالة النشطة.","استخدام أيقونات بأوزان خطوط مختلفة وتفاصيل غير متجانسة في شاشة واحدة."]'::jsonb, '["متى يجب أن تكون الأيقونة مصحوبة بنص توضيحي (Text Label) ومتى تستطيع الوقوف وحدها؟","كيف يؤثر تصدير الأيقونات بصيغة SVG ذات كود نظيف على سرعة تحميل واجهة الويب والتطبيقات؟"]'::jsonb, '[{"title":"Material Design — Iconography System and Keyline Shapes","url":"https://material.io/design/iconography/system-icons.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تبني نظام أيقونات (Iconography System) متسقاً بصرياً من حيث الوزن والمحاذاة البصرية وشبكة الرسم؟' or l.short_answer is distinct from 'برسم كافة الأيقونات على شبكة قياسية موحدة (مثل 24x24px)، مع توحيد سمك الخط (Stroke Weight)، وزوايا الاستدارة، وضبط المحاذاة البصرية (Optical Alignment) بدلاً من المحاذاة الهندسية الرياضية الجامدة.' or l.explanation is distinct from 'الأشكال الهندسية المختلفة لا تملك نفس الوزن البصري؛ فالدائرة أو المثلث بحجم 24x24px يبدو أصغر حجماً للعين البشرية من المربع الكامل 24x24px. لذا توفر شبكات الأيقونات الاحترافية خطوط إرشاد داخلية (Keyline Shapes) تسمح بزيادة أبعاد الدائرة والمثلث قليلاً لتعادل مساحتها كتلة المربع. الاتساق في اتجاه الإضاءة ومستوى التفاصيل يمنع ظهور أيقونة كأنها نشاز مأخوذ من مكتبة غريبة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["خلط أيقونات مفرغة (Outlined) وأيقونات ممتلئة (Filled) في نفس شريط الملاحة دون دلالة على الحالة النشطة.","استخدام أيقونات بأوزان خطوط مختلفة وتفاصيل غير متجانسة في شاشة واحدة."]'::jsonb or l.follow_up_questions is distinct from '["متى يجب أن تكون الأيقونة مصحوبة بنص توضيحي (Text Label) ومتى تستطيع الوقوف وحدها؟","كيف يؤثر تصدير الأيقونات بصيغة SVG ذات كود نظيف على سرعة تحميل واجهة الويب والتطبيقات؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Iconography System and Keyline Shapes","url":"https://material.io/design/iconography/system-icons.html"}]'::jsonb)) then raise exception 'Question uxvd-007 ar content changed; create a new revision before seeding'; end if; end $$;
