insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxvd-008', 'evolution-of-ui-styles-skeuomorphism-to-glassmorphism', 'ui-ux', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxvd-008', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تطورت لغات التصميم البصري من Skeuomorphism إلى Flat Design وصولاً إلى Glassmorphism و Modern Depth؟', 'تطورت من محاكاة مواد العالم الواقعي لتعليم المستخدمين الأوائل تفاعل اللمس، ثم التسطيح المفرط لتقليص الشوائب وسرعة التحميل، ثم عودة العمق المحسوب والطبقات الزجاجية التفاعلية بفضل قوة بطاقات الرسوم الحديثة.', 'الـ Skeuomorphism (محاكاة الجلد والخشب والأزرار البلاستيكية اللامعة) كان ضرورياً عند إطلاق الهواتف الذكية لمساعدة الناس على فهم أن الأزرار قابلة للضغط. في 2013 تحول العالم نحو Flat Design لتنظيف الشاشات ورفع الكفاءة، لكنه أفرط في التسطيح ومحا الدلالات البصرية (Affordances). اليوم نعيش مرحلة Modern Functional Depth والـ Glassmorphism: أسطح بلورية نصف شفافة مع خلفيات مموهة (Background Blur) تعبر بذكاء عن تراكب الطبقات وعمق بنية التطبيق دون فوضى شكلية.', null, '["استخدام مؤثرات الزجاج والظلال الملونة في كل تفاصيل الواجهة مما يثقل تجربة المستخدم ويضعف المقروئية.","التضحية بالدلالات الوظيفية للأزرار والمكونات تفضيلاً لاتباع صيحات الموضة البصرية المؤقتة."]'::jsonb, '["كيف تؤثر المؤثرات البصرية الثقيلة كـ Backdrop Filter على أداء هواتف الفئات المتوسطة واستهلاك البطارية؟","ما هي معايير Apple في توظيف الخامات الشفافة (Vibrancy & Materials) في نظام iOS و macOS؟"]'::jsonb, '[{"title":"Apple Developer — Materials and Vibrancy in Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تطورت لغات التصميم البصري من Skeuomorphism إلى Flat Design وصولاً إلى Glassmorphism و Modern Depth؟' or l.short_answer is distinct from 'تطورت من محاكاة مواد العالم الواقعي لتعليم المستخدمين الأوائل تفاعل اللمس، ثم التسطيح المفرط لتقليص الشوائب وسرعة التحميل، ثم عودة العمق المحسوب والطبقات الزجاجية التفاعلية بفضل قوة بطاقات الرسوم الحديثة.' or l.explanation is distinct from 'الـ Skeuomorphism (محاكاة الجلد والخشب والأزرار البلاستيكية اللامعة) كان ضرورياً عند إطلاق الهواتف الذكية لمساعدة الناس على فهم أن الأزرار قابلة للضغط. في 2013 تحول العالم نحو Flat Design لتنظيف الشاشات ورفع الكفاءة، لكنه أفرط في التسطيح ومحا الدلالات البصرية (Affordances). اليوم نعيش مرحلة Modern Functional Depth والـ Glassmorphism: أسطح بلورية نصف شفافة مع خلفيات مموهة (Background Blur) تعبر بذكاء عن تراكب الطبقات وعمق بنية التطبيق دون فوضى شكلية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام مؤثرات الزجاج والظلال الملونة في كل تفاصيل الواجهة مما يثقل تجربة المستخدم ويضعف المقروئية.","التضحية بالدلالات الوظيفية للأزرار والمكونات تفضيلاً لاتباع صيحات الموضة البصرية المؤقتة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تؤثر المؤثرات البصرية الثقيلة كـ Backdrop Filter على أداء هواتف الفئات المتوسطة واستهلاك البطارية؟","ما هي معايير Apple في توظيف الخامات الشفافة (Vibrancy & Materials) في نظام iOS و macOS؟"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Materials and Vibrancy in Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxvd-008 ar content changed; create a new revision before seeding'; end if; end $$;
