insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تعتبر المساحة البيضاء (White Space / Negative Space) عنصراً تصميمياً فعالاً وليست مساحة مهدرة؟', 'لأن المساحة البيضاء هي التي تمنح العين مساحة للتنفس، وتفصل بين الكتل المعرفية، وتبرز العناصر ذات القيمة العالية، وتمنح التطبيق شعوراً بالفخامة والوضوح والاحترافية.', 'العملاء غير المتخصصين غالباً ما يطالبون بملء كل مليمتر فارغ بإعلانات أو معلومات خوفاً من ''إهدار الشاشة''. الحقيقة المثبتة في علم النفس الإدراكي هي أن تكديس العناصر يرفع الحمل المعرفي ويقلل من قدرة المستخدم على الاستيعاب بنسبة تزيد عن 30%. المساحة الفارغة تعمل كإطار يوجه التركيز نحو زر الشراء أو الرسالة الجوهرية، وتمثل علامة فارقة بين المنتجات الممتازة والمنتجات الرديئة.', null, '["ضغط المسافات وتكديس الأزرار والنصوص بحجة تقليل الحاجة لتمرير الصفحة (Scroll).","استخدام مساحات بيضاء غير منتظمة ولا تخضع لنظام شبكي موحد مما يعطي انطباعاً بالفوضى أو فراغ الصفحات الخاطئ."]'::jsonb, '["ما الفرق بين المساحات البيضاء الدقيقة (Micro White Space) والمساحات الكبرى (Macro White Space)؟","كيف ترتبط المساحات البيضاء بتصور المستخدمين لمستوى فخامة وجودة الخدمة المقدمة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — The Power of White Space in UI","url":"https://www.nngroup.com/articles/principles-visual-design/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxvd-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxvd-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تعتبر المساحة البيضاء (White Space / Negative Space) عنصراً تصميمياً فعالاً وليست مساحة مهدرة؟' or l.short_answer is distinct from 'لأن المساحة البيضاء هي التي تمنح العين مساحة للتنفس، وتفصل بين الكتل المعرفية، وتبرز العناصر ذات القيمة العالية، وتمنح التطبيق شعوراً بالفخامة والوضوح والاحترافية.' or l.explanation is distinct from 'العملاء غير المتخصصين غالباً ما يطالبون بملء كل مليمتر فارغ بإعلانات أو معلومات خوفاً من ''إهدار الشاشة''. الحقيقة المثبتة في علم النفس الإدراكي هي أن تكديس العناصر يرفع الحمل المعرفي ويقلل من قدرة المستخدم على الاستيعاب بنسبة تزيد عن 30%. المساحة الفارغة تعمل كإطار يوجه التركيز نحو زر الشراء أو الرسالة الجوهرية، وتمثل علامة فارقة بين المنتجات الممتازة والمنتجات الرديئة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ضغط المسافات وتكديس الأزرار والنصوص بحجة تقليل الحاجة لتمرير الصفحة (Scroll).","استخدام مساحات بيضاء غير منتظمة ولا تخضع لنظام شبكي موحد مما يعطي انطباعاً بالفوضى أو فراغ الصفحات الخاطئ."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين المساحات البيضاء الدقيقة (Micro White Space) والمساحات الكبرى (Macro White Space)؟","كيف ترتبط المساحات البيضاء بتصور المستخدمين لمستوى فخامة وجودة الخدمة المقدمة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — The Power of White Space in UI","url":"https://www.nngroup.com/articles/principles-visual-design/"}]'::jsonb)) then raise exception 'Question uxvd-010 ar content changed; create a new revision before seeding'; end if; end $$;
