insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الغرض الوظيفي للتحريك (Motion Design) في تجربة المستخدم ومتى يتحول إلى مصدر إزعاج؟', 'الغرض الوظيفي هو توضيح العلاقات المكانية بين الشاشات، وتقديم تغذية راجعة فورية للأفعال، وتوجيه الانتباه؛ ويتحول إلى إزعاج عندما يكون بطيئاً أو استعراضياً مفرطاً يعطل سرعة إنجاز المهام.', 'التحريك الممتاز في الـ UX يبدو طبيعياً وغير ملحوظ لذاته، مثل تحرك البطاقة لتملأ الشاشة مما يوضح للمستخدم مصدر المحتوى وأين سيعود عند الإغلاق. في المقابل، التحريك الزائد الذي يفرض على المستخدم الانتظار ثانية كاملة لظهور كل عنصر في القائمة يصيب المستخدم بالإحباط ويدمر كفاءة الاستخدام.', null, '["استخدام حركات بهلوانية استعراضية طويلة تؤخر إمكانية النقر على أزرار الواجهة.","غياب الحركة تماماً في الانتقالات المفاجئة (Jump Cuts) مما يفقد المستخدم إحساسه بموقعه داخل التطبيق."]'::jsonb, '["كيف تساهم الحركة في بناء التوجيه المكاني (Spatial Awareness) في تطبيقات الجوال؟","ما هي القواعد التي تفصل بين الحركة الوظيفية الهادفة والحركة الجمالية الثانوية؟"]'::jsonb, '[{"title":"Material Design — Understanding Motion Principles","url":"https://material.io/design/motion/understanding-motion.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الغرض الوظيفي للتحريك (Motion Design) في تجربة المستخدم ومتى يتحول إلى مصدر إزعاج؟' or l.short_answer is distinct from 'الغرض الوظيفي هو توضيح العلاقات المكانية بين الشاشات، وتقديم تغذية راجعة فورية للأفعال، وتوجيه الانتباه؛ ويتحول إلى إزعاج عندما يكون بطيئاً أو استعراضياً مفرطاً يعطل سرعة إنجاز المهام.' or l.explanation is distinct from 'التحريك الممتاز في الـ UX يبدو طبيعياً وغير ملحوظ لذاته، مثل تحرك البطاقة لتملأ الشاشة مما يوضح للمستخدم مصدر المحتوى وأين سيعود عند الإغلاق. في المقابل، التحريك الزائد الذي يفرض على المستخدم الانتظار ثانية كاملة لظهور كل عنصر في القائمة يصيب المستخدم بالإحباط ويدمر كفاءة الاستخدام.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام حركات بهلوانية استعراضية طويلة تؤخر إمكانية النقر على أزرار الواجهة.","غياب الحركة تماماً في الانتقالات المفاجئة (Jump Cuts) مما يفقد المستخدم إحساسه بموقعه داخل التطبيق."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم الحركة في بناء التوجيه المكاني (Spatial Awareness) في تطبيقات الجوال؟","ما هي القواعد التي تفصل بين الحركة الوظيفية الهادفة والحركة الجمالية الثانوية؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Understanding Motion Principles","url":"https://material.io/design/motion/understanding-motion.html"}]'::jsonb)) then raise exception 'Question uxim-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Purpose Of Motion In Ux Design?', 'This question checks the core Purpose Of Motion In Ux Design concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Purpose Of Motion In Ux Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Purpose Of Motion In Ux Design (point 1).","Missing the key trade-off in Purpose Of Motion In Ux Design (point 2)."]'::jsonb, '["How would you apply Purpose Of Motion In Ux Design in a production Product Design app (follow-up 1)?","How would you apply Purpose Of Motion In Ux Design in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Understanding Motion Principles","url":"https://material.io/design/motion/understanding-motion.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-001' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Purpose Of Motion In Ux Design?' or l.short_answer is distinct from 'This question checks the core Purpose Of Motion In Ux Design concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Purpose Of Motion In Ux Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Purpose Of Motion In Ux Design (point 1).","Missing the key trade-off in Purpose Of Motion In Ux Design (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Purpose Of Motion In Ux Design in a production Product Design app (follow-up 1)?","How would you apply Purpose Of Motion In Ux Design in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Understanding Motion Principles","url":"https://material.io/design/motion/understanding-motion.html"}]'::jsonb)) then raise exception 'Question uxim-001 en content changed; create a new revision before seeding'; end if; end $$;
