insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين منحنيات التسارع (Easing Curves: Linear, Ease-In, Ease-Out) والفيزياء الزنبركية (Spring Physics)؟', 'الحركة الخطية (Linear) تبدو صناعية وروبوتية قاسية، بينما Ease-Out يبدأ سريعاً ويتباطأ عند الوصول (مثالي لدخول العناصر للشاشة)، و Ease-In يتسارع (مثالي لخروج العناصر)، والفيزياء الزنبركية تحاكي العالم الحقيقي بكتلة وارتداد طبيعي.', 'في العالم الواقعي، لا يبدأ أي جسم حركته أو يتوقف فجأة دون تسارع واحتكاك. في الواجهات، العناصر القادمة من خارج الشاشة يجب أن تدخل بـ Deceleration (Ease-Out) حتى يستوعبها المستخدم بسرعة وتستقر بسلاسة. الأجسام التي تخرج من الشاشة تستخدم Acceleration (Ease-In) لتختفي بأقصى سرعة دون تعطيل المستخدم. Spring Physics تضيف شعوراً بالاستجابة اللمسية الحية عبر تفاعلات السحب والإفلات.', null, '["استخدام Linear Motion في تحريك القوائم والنوافذ المنبثقة مما يجعلها تبدو جامدة ومزعجة بصرياً.","استخدام ارتداد زنبركي مبالغ فيه (Over-bouncing) يجعل الواجهة تهتز طويلاً وتتأخر عن استقرارها."]'::jsonb, '["ما هي معاملات الـ Spring Physics (Damping, Stiffness, Mass) وكيف تؤثر على الشعور بالحركة؟","كيف تترجم منحنيات Bezier المنطقية (Cubic-bezier) إلى كود CSS أو Flutter؟"]'::jsonb, '[{"title":"Material Design — The Motion System: Speed and Easing","url":"https://material.io/design/motion/speed.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين منحنيات التسارع (Easing Curves: Linear, Ease-In, Ease-Out) والفيزياء الزنبركية (Spring Physics)؟' or l.short_answer is distinct from 'الحركة الخطية (Linear) تبدو صناعية وروبوتية قاسية، بينما Ease-Out يبدأ سريعاً ويتباطأ عند الوصول (مثالي لدخول العناصر للشاشة)، و Ease-In يتسارع (مثالي لخروج العناصر)، والفيزياء الزنبركية تحاكي العالم الحقيقي بكتلة وارتداد طبيعي.' or l.explanation is distinct from 'في العالم الواقعي، لا يبدأ أي جسم حركته أو يتوقف فجأة دون تسارع واحتكاك. في الواجهات، العناصر القادمة من خارج الشاشة يجب أن تدخل بـ Deceleration (Ease-Out) حتى يستوعبها المستخدم بسرعة وتستقر بسلاسة. الأجسام التي تخرج من الشاشة تستخدم Acceleration (Ease-In) لتختفي بأقصى سرعة دون تعطيل المستخدم. Spring Physics تضيف شعوراً بالاستجابة اللمسية الحية عبر تفاعلات السحب والإفلات.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام Linear Motion في تحريك القوائم والنوافذ المنبثقة مما يجعلها تبدو جامدة ومزعجة بصرياً.","استخدام ارتداد زنبركي مبالغ فيه (Over-bouncing) يجعل الواجهة تهتز طويلاً وتتأخر عن استقرارها."]'::jsonb or l.follow_up_questions is distinct from '["ما هي معاملات الـ Spring Physics (Damping, Stiffness, Mass) وكيف تؤثر على الشعور بالحركة؟","كيف تترجم منحنيات Bezier المنطقية (Cubic-bezier) إلى كود CSS أو Flutter؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — The Motion System: Speed and Easing","url":"https://material.io/design/motion/speed.html"}]'::jsonb)) then raise exception 'Question uxim-002 ar content changed; create a new revision before seeding'; end if; end $$;
