insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxim-003', 'motion-duration-guidelines-and-performance', 'ui-ux', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxim-003', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المدد الزمنية المعيارية للحركات التفاعلية (Duration Guidelines) في واجهات المستخدم؟', 'تتراوح الحركات الدقيقة وتغييرات الحالة بين 100 إلى 200 مللي ثانية، وانتقالات النوافذ والعناصر المتوسطة بين 200 إلى 300 مللي ثانية، بينما الانتقالات الكبرى للشاشات الكاملة لا ينبغي أن تتجاوز 400 إلى 500 مللي ثانية.', 'أي حركة تقل مدتها عن 100ms تصبح غير مرئية للعين وتتحول لومضة مزعجة. وأي حركة تزيد مدتها عن 500ms تجعل الواجهة تبدو بطيئة وثقيلة الاستجابة. في الشاشات الكبيرة (أجهزة سطح المكتب واللوحيات)، تزداد المسافات المقطوعة لذا يمكن زيادة المدة قليلاً، بينما في شاشات الهواتف الصغيرة يجب أن تكون الحركة خاطفة ومباشرة.', null, '["ضبط مدة فتح القائمة أو الإشعار على ثانية كاملة (1000ms) مما يضيع وقت المستخدم الثمين.","تطبيق نفس المدة الزمنية لحركة زر صغير وحركة ملء شاشة كاملة دون مراعاة المسافة."]'::jsonb, '["كيف تؤثر سرعة الإطارات (60fps و 120Hz ProMotion) على انسيابية الحركة والشعور بالاستجابة؟","ما هي أسباب الـ Animation Jank وكيف يتفاداه مصممو الـ UX بالتعاون مع المطورين؟"]'::jsonb, '[{"title":"Material Design — Motion Speed and Duration","url":"https://material.io/design/motion/speed.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المدد الزمنية المعيارية للحركات التفاعلية (Duration Guidelines) في واجهات المستخدم؟' or l.short_answer is distinct from 'تتراوح الحركات الدقيقة وتغييرات الحالة بين 100 إلى 200 مللي ثانية، وانتقالات النوافذ والعناصر المتوسطة بين 200 إلى 300 مللي ثانية، بينما الانتقالات الكبرى للشاشات الكاملة لا ينبغي أن تتجاوز 400 إلى 500 مللي ثانية.' or l.explanation is distinct from 'أي حركة تقل مدتها عن 100ms تصبح غير مرئية للعين وتتحول لومضة مزعجة. وأي حركة تزيد مدتها عن 500ms تجعل الواجهة تبدو بطيئة وثقيلة الاستجابة. في الشاشات الكبيرة (أجهزة سطح المكتب واللوحيات)، تزداد المسافات المقطوعة لذا يمكن زيادة المدة قليلاً، بينما في شاشات الهواتف الصغيرة يجب أن تكون الحركة خاطفة ومباشرة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ضبط مدة فتح القائمة أو الإشعار على ثانية كاملة (1000ms) مما يضيع وقت المستخدم الثمين.","تطبيق نفس المدة الزمنية لحركة زر صغير وحركة ملء شاشة كاملة دون مراعاة المسافة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تؤثر سرعة الإطارات (60fps و 120Hz ProMotion) على انسيابية الحركة والشعور بالاستجابة؟","ما هي أسباب الـ Animation Jank وكيف يتفاداه مصممو الـ UX بالتعاون مع المطورين؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Motion Speed and Duration","url":"https://material.io/design/motion/speed.html"}]'::jsonb)) then raise exception 'Question uxim-003 ar content changed; create a new revision before seeding'; end if; end $$;
