insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو التحريك المتتابع (Staggered Animation) وكيف تصمم سيناريو حركي متناغم (Choreography) للقوائم والبطاقات؟', 'هو تأخير زمني طفيف ومتسلسل (غالباً بين 20 إلى 50 مللي ثانية) بين ظهور العناصر المتتالية في القائمة لإنشاء تدفق بصري طبيعي يوجه عين المستخدم دون فوضى متزامنة.', 'إذا ظهرت 20 بطاقة في نفس اللحظة فجأة، تعجز العين عن التركيز على نقطة بداية. عبر الـ Staggering، تظهر البطاقة الأولى تليها الثانية بفارق زمني خاطف، مما يقود انتباه المستخدم من أعلى الصفحة لأسفلها وفق اتجاه القراءة. القاعدة الأساسية هي ألا يتجاوز إجمالي وقت ظهور كافة عناصر القائمة مجتمعة حاجز الـ 400ms لتفادي الملل.', null, '["وضع تأخير زمني كبير (100ms لكل عنصر) مما يجعل قائمة من 10 عناصر تستغرق أكثر من ثانية للظهور.","تطبيق تحريك متتابع عشوائي يتحرك في اتجاهات متضاربة يربك مسار القراءة الطبيعي."]'::jsonb, '["كيف تحدد اتجاه الحركة المتتابعة بناءً على لغة الواجهة (RTL للعربية و LTR للإنجليزية)؟","كيف تستخدم الحركة المتتالية لتأكيد التغييرات الناتجة عن تصفية أو فرز عناصر القائمة؟"]'::jsonb, '[{"title":"Material Design — Choreographing Motion","url":"https://material.io/design/motion/choreography.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو التحريك المتتابع (Staggered Animation) وكيف تصمم سيناريو حركي متناغم (Choreography) للقوائم والبطاقات؟' or l.short_answer is distinct from 'هو تأخير زمني طفيف ومتسلسل (غالباً بين 20 إلى 50 مللي ثانية) بين ظهور العناصر المتتالية في القائمة لإنشاء تدفق بصري طبيعي يوجه عين المستخدم دون فوضى متزامنة.' or l.explanation is distinct from 'إذا ظهرت 20 بطاقة في نفس اللحظة فجأة، تعجز العين عن التركيز على نقطة بداية. عبر الـ Staggering، تظهر البطاقة الأولى تليها الثانية بفارق زمني خاطف، مما يقود انتباه المستخدم من أعلى الصفحة لأسفلها وفق اتجاه القراءة. القاعدة الأساسية هي ألا يتجاوز إجمالي وقت ظهور كافة عناصر القائمة مجتمعة حاجز الـ 400ms لتفادي الملل.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع تأخير زمني كبير (100ms لكل عنصر) مما يجعل قائمة من 10 عناصر تستغرق أكثر من ثانية للظهور.","تطبيق تحريك متتابع عشوائي يتحرك في اتجاهات متضاربة يربك مسار القراءة الطبيعي."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحدد اتجاه الحركة المتتابعة بناءً على لغة الواجهة (RTL للعربية و LTR للإنجليزية)؟","كيف تستخدم الحركة المتتالية لتأكيد التغييرات الناتجة عن تصفية أو فرز عناصر القائمة؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Choreographing Motion","url":"https://material.io/design/motion/choreography.html"}]'::jsonb)) then raise exception 'Question uxim-004 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Staggered Animations And Choreography?', 'This question checks the core Staggered Animations And Choreography concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Staggered Animations And Choreography with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Staggered Animations And Choreography (point 1).","Missing the key trade-off in Staggered Animations And Choreography (point 2)."]'::jsonb, '["How would you apply Staggered Animations And Choreography in a production Product Design app (follow-up 1)?","How would you apply Staggered Animations And Choreography in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Choreographing Motion","url":"https://material.io/design/motion/choreography.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-004' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Staggered Animations And Choreography?' or l.short_answer is distinct from 'This question checks the core Staggered Animations And Choreography concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Staggered Animations And Choreography with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Staggered Animations And Choreography (point 1).","Missing the key trade-off in Staggered Animations And Choreography (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Staggered Animations And Choreography in a production Product Design app (follow-up 1)?","How would you apply Staggered Animations And Choreography in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Choreographing Motion","url":"https://material.io/design/motion/choreography.html"}]'::jsonb)) then raise exception 'Question uxim-004 en content changed; create a new revision before seeding'; end if; end $$;
