insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxim-005', 'haptic-feedback-and-multimodal-interactions', 'ui-ux', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
