insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف توظف ردود الفعل اللمسية الاهتزازية (Haptic Feedback) لتعزيز الثقة في المعاملات الحساسة؟', 'باستخدام اهتزازات ميكانيكية دقيقة ومحسوبة بالمللي ثانية (مثل Apple Taptic Engine) تتزامن مع التغذية البصرية والصوتية لتأكيد حدوث الأفعال المهمة وإشعار المستخدم بنجاحها أو فشلها فيزيائياً.', 'ردود الفعل اللمسية تخلق بعداً حسياً إضافياً يربط الزجاج الافتراضي بالواقع الملموس. في تطبيقات الدفع المالي (Fintech)، تزامن صوت النغمة الخافتة مع حركة علامة الصح الخضراء واهتزاز هابتي خفيف ومطمئن يمنح المستخدم ثقة ويقيناً بنجاح تحويل الأموال. كما تُستخدم الهابتكس التحذيرية المزدوجة لتنبيه المستخدم عند محاولة حذف ملف مصيري.', null, '["الإفراط في استخدام الاهتزازات مع كل نقرة زر عادية مما يستنزف البطارية ويزعج يد المستخدم.","استخدام نمط اهتزاز مجهول الشدة دون التمييز بين حالات النجاح البسيطة والأخطاء الجسيمة."]'::jsonb, '["ما هي فئات الـ Haptic Feedback القياسية في نظام iOS (Impact, Notification, Selection)؟","كيف تضمن مراعاة إمكانية الوصول للمستخدمين ذوي الإعاقات السمعية أو البصرية عبر الهابتكس؟"]'::jsonb, '[{"title":"Apple Developer — Playing Haptics in Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف توظف ردود الفعل اللمسية الاهتزازية (Haptic Feedback) لتعزيز الثقة في المعاملات الحساسة؟' or l.short_answer is distinct from 'باستخدام اهتزازات ميكانيكية دقيقة ومحسوبة بالمللي ثانية (مثل Apple Taptic Engine) تتزامن مع التغذية البصرية والصوتية لتأكيد حدوث الأفعال المهمة وإشعار المستخدم بنجاحها أو فشلها فيزيائياً.' or l.explanation is distinct from 'ردود الفعل اللمسية تخلق بعداً حسياً إضافياً يربط الزجاج الافتراضي بالواقع الملموس. في تطبيقات الدفع المالي (Fintech)، تزامن صوت النغمة الخافتة مع حركة علامة الصح الخضراء واهتزاز هابتي خفيف ومطمئن يمنح المستخدم ثقة ويقيناً بنجاح تحويل الأموال. كما تُستخدم الهابتكس التحذيرية المزدوجة لتنبيه المستخدم عند محاولة حذف ملف مصيري.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الإفراط في استخدام الاهتزازات مع كل نقرة زر عادية مما يستنزف البطارية ويزعج يد المستخدم.","استخدام نمط اهتزاز مجهول الشدة دون التمييز بين حالات النجاح البسيطة والأخطاء الجسيمة."]'::jsonb or l.follow_up_questions is distinct from '["ما هي فئات الـ Haptic Feedback القياسية في نظام iOS (Impact, Notification, Selection)؟","كيف تضمن مراعاة إمكانية الوصول للمستخدمين ذوي الإعاقات السمعية أو البصرية عبر الهابتكس؟"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Playing Haptics in Human Interface Guidelines","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxim-005 ar content changed; create a new revision before seeding'; end if; end $$;
