insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي تحديات تصميم الواجهات القائمة على الإيماءات (Gestures) وكيف تضمن سهولة اكتشافها وفهمها؟', 'التحدي الأكبر هو أن الإيماءات اللمسية غير مرئية بطبيعتها وتفتقر للإتاحة البصرية المباشرة؛ والحل هو توفير تلميحات بصرية متحركة، ودعم الإيماءات بأزرار بديلة صريحة دائماً.', 'إيماءة مثل ''السحب لليسار للأرشفة'' (Swipe to Archive) رائعة وسريعة للمستخدم المتقدم، لكن المستخدم الجديد لا يستطيع تخمين وجودها دون إشارة. تشمل استراتيجيات الاكتشاف: ارتداد العنصر قليلاً عند أول استخدام ليكشف ما تحته (Peek / Bounce Animation)، أو عرض جولة إرشادية مختصرة في أول مرة، وتوفير خيار الأرشفة دائماً كزر واضح داخل القائمة التقليدية للمستخدمين الأقل دراية.', null, '["جعل الإيماءات المعقدة هي الطريقة الوحيدة الحصرية لإنجاز مهام أساسية ومصيرية في التطبيق.","تطبيق إيماءات تخالف إيماءات النظام التشغيلي الافتراضية (مثل تعارض سحب الصفحة مع سحب الـ Back في النظام)."]'::jsonb, '["ما هي معايير WCAG 2.5.1 و 2.5.4 الخاصة بإلغاء وإتاحة بدائل للإيماءات المعقدة والمتزامنة؟","كيف تصمم حالات السحب غير المكتمل (Cancelled Swipe) وتأكيد الإلغاء بسلاسة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Gestural Interfaces: A Step Backwards in Usability","url":"https://www.nngroup.com/articles/gestural-interfaces-usability/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي تحديات تصميم الواجهات القائمة على الإيماءات (Gestures) وكيف تضمن سهولة اكتشافها وفهمها؟' or l.short_answer is distinct from 'التحدي الأكبر هو أن الإيماءات اللمسية غير مرئية بطبيعتها وتفتقر للإتاحة البصرية المباشرة؛ والحل هو توفير تلميحات بصرية متحركة، ودعم الإيماءات بأزرار بديلة صريحة دائماً.' or l.explanation is distinct from 'إيماءة مثل ''السحب لليسار للأرشفة'' (Swipe to Archive) رائعة وسريعة للمستخدم المتقدم، لكن المستخدم الجديد لا يستطيع تخمين وجودها دون إشارة. تشمل استراتيجيات الاكتشاف: ارتداد العنصر قليلاً عند أول استخدام ليكشف ما تحته (Peek / Bounce Animation)، أو عرض جولة إرشادية مختصرة في أول مرة، وتوفير خيار الأرشفة دائماً كزر واضح داخل القائمة التقليدية للمستخدمين الأقل دراية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["جعل الإيماءات المعقدة هي الطريقة الوحيدة الحصرية لإنجاز مهام أساسية ومصيرية في التطبيق.","تطبيق إيماءات تخالف إيماءات النظام التشغيلي الافتراضية (مثل تعارض سحب الصفحة مع سحب الـ Back في النظام)."]'::jsonb or l.follow_up_questions is distinct from '["ما هي معايير WCAG 2.5.1 و 2.5.4 الخاصة بإلغاء وإتاحة بدائل للإيماءات المعقدة والمتزامنة؟","كيف تصمم حالات السحب غير المكتمل (Cancelled Swipe) وتأكيد الإلغاء بسلاسة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Gestural Interfaces: A Step Backwards in Usability","url":"https://www.nngroup.com/articles/gestural-interfaces-usability/"}]'::jsonb)) then raise exception 'Question uxim-006 ar content changed; create a new revision before seeding'; end if; end $$;
