insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxim-007', 'skeleton-screens-vs-spinners-perceived-speed', 'ui-ux', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxim-007', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تتفوق شاشات الهيكل العظمي (Skeleton Screens) على دوائر التحميل الدوارة (Spinners)؟', 'لأنها تقدم هيكلاً بصرياً تدريجياً يوحي بأن المحتوى يكتمل ويقترب من الجاهزية، مما يقلل من الوقت المدرك للانتظار (Perceived Wait Time) ويمنع قفزات التخطيط الفجائية.', 'دوائر التحميل الدوارة (Spinners) تحصر تركيز المستخدم على نقطة واحدة تدور في الفراغ وتذكره باستمرار بأنه عالق ينتظر. في المقابل، الشاشات الهيكلية ترسم أشكالاً رمادية باهتة تطابق موضع العناوين والبطاقات القادمة، مع لمعان حركي هادئ (Shimmer Animation) من اليسار إلى اليمين. هذا يجعل المستخدم يشعر بأن التطبيق فوري الاستجابة ويعرف أين سينظر فور اكتمال جلب البيانات.', null, '["تصميم شاشات هيكلية بأبعاد تختلف تماماً عن البطاقات الحقيقية مما يسبب قفزة تخطيطية مفاجئة (Layout Shift).","استخدام الشاشات الهيكلية لعمليات سريعة جداً تقل عن 300ms مما يظهر كفلاش رمادي مزعج."]'::jsonb, '["متى يكون استخدام Spinner الصغير أفضل من Skeleton Screen (مثل داخل زر الإرسال)؟","كيف تؤثر شاشات الهيكل العظمي على تحسين مقياس Cumulative Layout Shift (CLS) في تجربة الويب؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Skeleton Screens 101","url":"https://www.nngroup.com/articles/skeleton-screens/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تتفوق شاشات الهيكل العظمي (Skeleton Screens) على دوائر التحميل الدوارة (Spinners)؟' or l.short_answer is distinct from 'لأنها تقدم هيكلاً بصرياً تدريجياً يوحي بأن المحتوى يكتمل ويقترب من الجاهزية، مما يقلل من الوقت المدرك للانتظار (Perceived Wait Time) ويمنع قفزات التخطيط الفجائية.' or l.explanation is distinct from 'دوائر التحميل الدوارة (Spinners) تحصر تركيز المستخدم على نقطة واحدة تدور في الفراغ وتذكره باستمرار بأنه عالق ينتظر. في المقابل، الشاشات الهيكلية ترسم أشكالاً رمادية باهتة تطابق موضع العناوين والبطاقات القادمة، مع لمعان حركي هادئ (Shimmer Animation) من اليسار إلى اليمين. هذا يجعل المستخدم يشعر بأن التطبيق فوري الاستجابة ويعرف أين سينظر فور اكتمال جلب البيانات.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تصميم شاشات هيكلية بأبعاد تختلف تماماً عن البطاقات الحقيقية مما يسبب قفزة تخطيطية مفاجئة (Layout Shift).","استخدام الشاشات الهيكلية لعمليات سريعة جداً تقل عن 300ms مما يظهر كفلاش رمادي مزعج."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون استخدام Spinner الصغير أفضل من Skeleton Screen (مثل داخل زر الإرسال)؟","كيف تؤثر شاشات الهيكل العظمي على تحسين مقياس Cumulative Layout Shift (CLS) في تجربة الويب؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Skeleton Screens 101","url":"https://www.nngroup.com/articles/skeleton-screens/"}]'::jsonb)) then raise exception 'Question uxim-007 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Skeleton Screens Vs Spinners Perceived Speed?', 'This question checks the core Skeleton Screens Vs Spinners Perceived Speed concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Skeleton Screens Vs Spinners Perceived Speed with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Skeleton Screens Vs Spinners Perceived Speed (point 1).","Missing the key trade-off in Skeleton Screens Vs Spinners Perceived Speed (point 2)."]'::jsonb, '["How would you apply Skeleton Screens Vs Spinners Perceived Speed in a production Product Design app (follow-up 1)?","How would you apply Skeleton Screens Vs Spinners Perceived Speed in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Skeleton Screens 101","url":"https://www.nngroup.com/articles/skeleton-screens/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
