insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم الحركات مع مراعاة المستخدمين الذين يعانون من اضطرابات الجهاز الدهليزي (Vestibular Disorders) وخاصية Prefers-Reduced-Motion؟', 'بتوفير بدائل حركية هادئة (كالتلاشي التدريجي Fade بدلاً من التكبير والقفز المفاجئ والبارالاكس)، واحترام تفضيل النظام لتقليص الحركة (prefers-reduced-motion) برمجياً.', 'التحريكات الكبيرة السريعة وتأثيرات اختلاف المنظر (Parallax Scrolling) والتكبير والتصغير المباغت قد تسبب للمصابين باضطرابات التوازن الدهليزي والصرع دواراً وصداعاً وغثياناً حاداً. احترام معيار إمكانية الوصول يقتضي: 1) فحص خيار تقليل الحركة على مستوى النظام. 2) استبدال حركات الإزاحة بحركات ظهور ناعمة فورية. 3) توفير زر مباشر لإيقاف أي حركة أو فيديو تلقائي التشغيل في المنصة.', null, '["تجاهل إعدادات تقليل الحركة على نظام التشغيل وإجبار جميع المستخدمين على مشاهدة حركات انتقالية صاخبة.","تصميم خلفيات فيديو متحركة أو تأثيرات Parallax معقدة دون إمكانية إيقافها مؤقتاً."]'::jsonb, '["ما هي معايير WCAG 2.3.3 الخاصة بالحركات الناتجة عن التفاعل (Animation from Interactions)؟","كيف تبرمج استعلام @media (prefers-reduced-motion) في تصميمات الواجهات التفاعلية؟"]'::jsonb, '[{"title":"W3C — Understanding WCAG: Animation from Interactions","url":"https://www.w3.org/WAI/WCAG21/Understanding/animation-from-interactions.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم الحركات مع مراعاة المستخدمين الذين يعانون من اضطرابات الجهاز الدهليزي (Vestibular Disorders) وخاصية Prefers-Reduced-Motion؟' or l.short_answer is distinct from 'بتوفير بدائل حركية هادئة (كالتلاشي التدريجي Fade بدلاً من التكبير والقفز المفاجئ والبارالاكس)، واحترام تفضيل النظام لتقليص الحركة (prefers-reduced-motion) برمجياً.' or l.explanation is distinct from 'التحريكات الكبيرة السريعة وتأثيرات اختلاف المنظر (Parallax Scrolling) والتكبير والتصغير المباغت قد تسبب للمصابين باضطرابات التوازن الدهليزي والصرع دواراً وصداعاً وغثياناً حاداً. احترام معيار إمكانية الوصول يقتضي: 1) فحص خيار تقليل الحركة على مستوى النظام. 2) استبدال حركات الإزاحة بحركات ظهور ناعمة فورية. 3) توفير زر مباشر لإيقاف أي حركة أو فيديو تلقائي التشغيل في المنصة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تجاهل إعدادات تقليل الحركة على نظام التشغيل وإجبار جميع المستخدمين على مشاهدة حركات انتقالية صاخبة.","تصميم خلفيات فيديو متحركة أو تأثيرات Parallax معقدة دون إمكانية إيقافها مؤقتاً."]'::jsonb or l.follow_up_questions is distinct from '["ما هي معايير WCAG 2.3.3 الخاصة بالحركات الناتجة عن التفاعل (Animation from Interactions)؟","كيف تبرمج استعلام @media (prefers-reduced-motion) في تصميمات الواجهات التفاعلية؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Understanding WCAG: Animation from Interactions","url":"https://www.w3.org/WAI/WCAG21/Understanding/animation-from-interactions.html"}]'::jsonb)) then raise exception 'Question uxim-008 ar content changed; create a new revision before seeding'; end if; end $$;
