insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تساهم الحركات الدقيقة في مساعدة المستخدم على إدراك الخطأ ومعالجته (Error Recovery Micro-animations)؟', 'بتوجيه انتباه المستخدم بطريقة بديهية إلى موضع الخلل بدقة (مثل حركة الاهتزاز الخفيفة لحقل كلمة المرور غير الصحيحة)، مما يعبر عن الرفض الحركي الإنساني المألوف دون كلمات تقنية جافة.', 'حركة الاهتزاز الأفقي اللطيف (Horizontal Shake) مأخوذة من إيماءة هز الرأس الإنسانية للتعبير عن الرفض؛ عند إدخال رمز خطأ أو كلمة سر خاطئة، اهتزاز الحقل يلفت النظر فوراً للسبب دون الحاجة لقراءة رسالة طويلة. كما تشمل الحركات الفعالة: التمرير التلقائي السلس نحو أول حقل خاطئ في النماذج الطويلة لتجنيب المستخدم البحث عن سبب فشل الإرسال.', null, '["استخدام اهتزاز عنيف أو مؤثرات حمراء وامضة مزعجة تصيب المستخدم بالتوتر والارتباك.","الاكتفاء بالحركة دون توفير نص توضيحي مساند يشرح ما الذي يجب على المستخدم فعله لإصلاح الخطأ."]'::jsonb, '["كيف تمنع اهتزاز الحقول من أن يبدو كأنه عطل برمجي في استقرار الصفحة؟","ما هي أفضل ممارسات توقيت ظهور نصوص التحذير المتزامنة مع الحركة؟"]'::jsonb, '[{"title":"Material Design — Motion and Error Communication","url":"https://material.io/design/communication/confirmation-acknowledgement.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تساهم الحركات الدقيقة في مساعدة المستخدم على إدراك الخطأ ومعالجته (Error Recovery Micro-animations)؟' or l.short_answer is distinct from 'بتوجيه انتباه المستخدم بطريقة بديهية إلى موضع الخلل بدقة (مثل حركة الاهتزاز الخفيفة لحقل كلمة المرور غير الصحيحة)، مما يعبر عن الرفض الحركي الإنساني المألوف دون كلمات تقنية جافة.' or l.explanation is distinct from 'حركة الاهتزاز الأفقي اللطيف (Horizontal Shake) مأخوذة من إيماءة هز الرأس الإنسانية للتعبير عن الرفض؛ عند إدخال رمز خطأ أو كلمة سر خاطئة، اهتزاز الحقل يلفت النظر فوراً للسبب دون الحاجة لقراءة رسالة طويلة. كما تشمل الحركات الفعالة: التمرير التلقائي السلس نحو أول حقل خاطئ في النماذج الطويلة لتجنيب المستخدم البحث عن سبب فشل الإرسال.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام اهتزاز عنيف أو مؤثرات حمراء وامضة مزعجة تصيب المستخدم بالتوتر والارتباك.","الاكتفاء بالحركة دون توفير نص توضيحي مساند يشرح ما الذي يجب على المستخدم فعله لإصلاح الخطأ."]'::jsonb or l.follow_up_questions is distinct from '["كيف تمنع اهتزاز الحقول من أن يبدو كأنه عطل برمجي في استقرار الصفحة؟","ما هي أفضل ممارسات توقيت ظهور نصوص التحذير المتزامنة مع الحركة؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Motion and Error Communication","url":"https://material.io/design/communication/confirmation-acknowledgement.html"}]'::jsonb)) then raise exception 'Question uxim-009 ar content changed; create a new revision before seeding'; end if; end $$;
