insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين المعالجة المباشرة (Direct Manipulation) والمعالجة غير المباشرة (Indirect Manipulation) في تفاعل الشاشات؟', 'المعالجة المباشرة تتيح للمستخدم التفاعل مع العنصر نفسه مباشرة فيزيائياً بأصابعه أو مؤشره (كالضغط على الصورة وتكبيرها بالإصبعين وسحبها)، بينما غير المباشرة تستخدم وسطاء تحكم خارجيين (كالضغط على منزلق أو كتابة أرقام في حقل لتغيير الحجم).', 'المعالجة المباشرة (المصطلح الذي صاغه بن شنايدرمان) تمثل قمة التفاعل الطبيعي والبديهي: 1) تمثيل مستمر للعنصر المراد التحكم به. 2) أفعال فيزيائية مباشرة بدلاً من كتابة أوامر. 3) نتائج فورية مرئية وقابلة للتراجع السريع. في المقابل، تظل المعالجة غير المباشرة مفيدة في المهام الدقيقة جداً (مثل إدخال زوايا دوران بالدرجة في برامج الهندسة المعمارية حيث يتعذر الضبط الدقيق بالأصابع).', null, '["إجبار المستخدم على استخدام عناصر تحكم معقدة ومخفية لمهام بديهية يمكن إنجازها بسحب العنصر مباشرة.","تأخر استجابة العنصر لحركة الإصبع (Touch Latency) مما يفقد تجربة المعالجة المباشرة سحرها الطبيعي."]'::jsonb, '["كيف يؤثر الـ Physics-based Manipulation على شعور المستخدم بالتحكم والملكية في الواجهات ثلاثية الأبعاد؟","ما هي حدود المعالجة المباشرة في واجهات الهواتف ذات الشاشات المحدودة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Direct Manipulation in User Interfaces","url":"https://www.nngroup.com/articles/direct-manipulation/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxim-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxim-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين المعالجة المباشرة (Direct Manipulation) والمعالجة غير المباشرة (Indirect Manipulation) في تفاعل الشاشات؟' or l.short_answer is distinct from 'المعالجة المباشرة تتيح للمستخدم التفاعل مع العنصر نفسه مباشرة فيزيائياً بأصابعه أو مؤشره (كالضغط على الصورة وتكبيرها بالإصبعين وسحبها)، بينما غير المباشرة تستخدم وسطاء تحكم خارجيين (كالضغط على منزلق أو كتابة أرقام في حقل لتغيير الحجم).' or l.explanation is distinct from 'المعالجة المباشرة (المصطلح الذي صاغه بن شنايدرمان) تمثل قمة التفاعل الطبيعي والبديهي: 1) تمثيل مستمر للعنصر المراد التحكم به. 2) أفعال فيزيائية مباشرة بدلاً من كتابة أوامر. 3) نتائج فورية مرئية وقابلة للتراجع السريع. في المقابل، تظل المعالجة غير المباشرة مفيدة في المهام الدقيقة جداً (مثل إدخال زوايا دوران بالدرجة في برامج الهندسة المعمارية حيث يتعذر الضبط الدقيق بالأصابع).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إجبار المستخدم على استخدام عناصر تحكم معقدة ومخفية لمهام بديهية يمكن إنجازها بسحب العنصر مباشرة.","تأخر استجابة العنصر لحركة الإصبع (Touch Latency) مما يفقد تجربة المعالجة المباشرة سحرها الطبيعي."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر الـ Physics-based Manipulation على شعور المستخدم بالتحكم والملكية في الواجهات ثلاثية الأبعاد؟","ما هي حدود المعالجة المباشرة في واجهات الهواتف ذات الشاشات المحدودة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Direct Manipulation in User Interfaces","url":"https://www.nngroup.com/articles/direct-manipulation/"}]'::jsonb)) then raise exception 'Question uxim-010 ar content changed; create a new revision before seeding'; end if; end $$;
