insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المبادئ الأربعة لإمكانية الوصول وفق إرشادات (WCAG POUR Principles)؟', 'المبادئ الأربعة هي: 1) الإدراك (Perceivable). 2) القابلية للتشغيل (Operable). 3) الفهم (Understandable). 4) المتانة والاستقرار (Robust).', 'مبدأ الإدراك يعني ألا تعتمد الواجهة على حاسة واحدة فقط؛ فإذا كان هناك صوت يجب توفير نص مرئي، وإذا كانت هناك صورة يجب توفير وصف نصي بديل لقارئ الشاشة. مبدأ القابلية للتشغيل يضمن إمكانية التنقل والتحكم عبر لوحة المفاتيح وحدها أو بالأوامر الصوتية. مبدأ الفهم يضمن وضوح اللغة وبساطة التفاعل وتوقع السلوك ومنع الأخطاء. ومبدأ المتانة يضمن توافق الموقع مع مختلف المتصفحات والتقنيات المساعدة (Assistive Technologies) الحالية والمستقبلية.', null, '["حصر مفهوم إمكانية الوصول في دعم المكفوفين فقط وإهمال ذوي الإعاقات الحركية والسمعية والإدراكية.","تطبيق نصوص مساندة عشوائية لا توضح سياق العنصر لبرامج قراءة الشاشة."]'::jsonb, '["كيف تترجم مبادئ POUR إلى معايير قبول (Acceptance Criteria) في تذاكر التصميم والتطوير؟","ما هي الإعاقات المؤقتة والظرفية (Situational Disabilities) وكيف يعالجها مبدأ الإدراك؟"]'::jsonb, '[{"title":"W3C — Accessibility Principles (POUR)","url":"https://www.w3.org/WAI/fundamentals/accessibility-principles/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المبادئ الأربعة لإمكانية الوصول وفق إرشادات (WCAG POUR Principles)؟' or l.short_answer is distinct from 'المبادئ الأربعة هي: 1) الإدراك (Perceivable). 2) القابلية للتشغيل (Operable). 3) الفهم (Understandable). 4) المتانة والاستقرار (Robust).' or l.explanation is distinct from 'مبدأ الإدراك يعني ألا تعتمد الواجهة على حاسة واحدة فقط؛ فإذا كان هناك صوت يجب توفير نص مرئي، وإذا كانت هناك صورة يجب توفير وصف نصي بديل لقارئ الشاشة. مبدأ القابلية للتشغيل يضمن إمكانية التنقل والتحكم عبر لوحة المفاتيح وحدها أو بالأوامر الصوتية. مبدأ الفهم يضمن وضوح اللغة وبساطة التفاعل وتوقع السلوك ومنع الأخطاء. ومبدأ المتانة يضمن توافق الموقع مع مختلف المتصفحات والتقنيات المساعدة (Assistive Technologies) الحالية والمستقبلية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["حصر مفهوم إمكانية الوصول في دعم المكفوفين فقط وإهمال ذوي الإعاقات الحركية والسمعية والإدراكية.","تطبيق نصوص مساندة عشوائية لا توضح سياق العنصر لبرامج قراءة الشاشة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم مبادئ POUR إلى معايير قبول (Acceptance Criteria) في تذاكر التصميم والتطوير؟","ما هي الإعاقات المؤقتة والظرفية (Situational Disabilities) وكيف يعالجها مبدأ الإدراك؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Accessibility Principles (POUR)","url":"https://www.w3.org/WAI/fundamentals/accessibility-principles/"}]'::jsonb)) then raise exception 'Question uxac-001 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Wcag Pour Principles Explained?', 'This question checks the core Wcag Pour Principles Explained concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Wcag Pour Principles Explained with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Wcag Pour Principles Explained (point 1).","Missing the key trade-off in Wcag Pour Principles Explained (point 2)."]'::jsonb, '["How would you apply Wcag Pour Principles Explained in a production Product Design app (follow-up 1)?","How would you apply Wcag Pour Principles Explained in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"W3C — Accessibility Principles (POUR)","url":"https://www.w3.org/WAI/fundamentals/accessibility-principles/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
