insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxac-002', 'wcag-conformance-levels-a-aa-aaa', 'ui-ux', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxac-002', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق بين مستويات الامتثال لمعايير الوصول (WCAG Levels: A, AA, AAA) وما هو المعيار القانوني العالمي؟', 'المستوى A يمثل الحد الأدنى المطلق لمنع الحجب التام للوصول، والمستوى AA هو المعيار الذهبي والقانوني العالمي المطلوب تجارياً وحكومياً، بينما المستوى AAA هو الأرقى والأكثر صرامة ومخصص لبيئات استثنائية متخصصة.', 'معظم القوانين الدولية مثل قانون الأمريكيين ذوي الإعاقة (ADA) وقانون إمكانية الوصول الأوروبي (EAA) تشترط الامتثال للمستوى AA من WCAG 2.1/2.2. يتطلب هذا المستوى: تباين لوني 4.5:1 على الأقل للنصوص، دعم كامل للوحة المفاتيح دون فخاخ (No Keyboard Trap)، تسميات توضيحية للفيديو، وتوافق مع قارئات الشاشة. المستوى AAA يصعب تحقيقه في كافة الصفحات العامة (مثل اشتراط تباين 7:1 وتوفير ترجمة بلغة الإشارة لكل صوت).', null, '["الاستهانة بالمعايير القانونية مما يعرض الشركات العالمية لغرامات مالية ودعاوى قضائية باهظة.","محاولة تطبيق معايير المستوى AAA على كل أجزاء الموقع مما يعقد تصميم العلامة التجارية دون مبرر وظيفي."]'::jsonb, '["ما هي أبرز التحديثات التي أدخلها معيار WCAG 2.2 في مجالات أهداف اللمس والمساعدة المتسقة؟","كيف تؤثر الشهادة الطوعية لإمكانية الوصول للمنتج (VPAT Report) على مبيعات البرمجيات المؤسسية (B2B)؟"]'::jsonb, '[{"title":"W3C — WCAG 2 Overview and Conformance Levels","url":"https://www.w3.org/WAI/standards-guidelines/wcag/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين مستويات الامتثال لمعايير الوصول (WCAG Levels: A, AA, AAA) وما هو المعيار القانوني العالمي؟' or l.short_answer is distinct from 'المستوى A يمثل الحد الأدنى المطلق لمنع الحجب التام للوصول، والمستوى AA هو المعيار الذهبي والقانوني العالمي المطلوب تجارياً وحكومياً، بينما المستوى AAA هو الأرقى والأكثر صرامة ومخصص لبيئات استثنائية متخصصة.' or l.explanation is distinct from 'معظم القوانين الدولية مثل قانون الأمريكيين ذوي الإعاقة (ADA) وقانون إمكانية الوصول الأوروبي (EAA) تشترط الامتثال للمستوى AA من WCAG 2.1/2.2. يتطلب هذا المستوى: تباين لوني 4.5:1 على الأقل للنصوص، دعم كامل للوحة المفاتيح دون فخاخ (No Keyboard Trap)، تسميات توضيحية للفيديو، وتوافق مع قارئات الشاشة. المستوى AAA يصعب تحقيقه في كافة الصفحات العامة (مثل اشتراط تباين 7:1 وتوفير ترجمة بلغة الإشارة لكل صوت).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاستهانة بالمعايير القانونية مما يعرض الشركات العالمية لغرامات مالية ودعاوى قضائية باهظة.","محاولة تطبيق معايير المستوى AAA على كل أجزاء الموقع مما يعقد تصميم العلامة التجارية دون مبرر وظيفي."]'::jsonb or l.follow_up_questions is distinct from '["ما هي أبرز التحديثات التي أدخلها معيار WCAG 2.2 في مجالات أهداف اللمس والمساعدة المتسقة؟","كيف تؤثر الشهادة الطوعية لإمكانية الوصول للمنتج (VPAT Report) على مبيعات البرمجيات المؤسسية (B2B)؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — WCAG 2 Overview and Conformance Levels","url":"https://www.w3.org/WAI/standards-guidelines/wcag/"}]'::jsonb)) then raise exception 'Question uxac-002 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Wcag Conformance Levels A Aa Aaa?', 'This question checks the core Wcag Conformance Levels A Aa Aaa concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Wcag Conformance Levels A Aa Aaa with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Wcag Conformance Levels A Aa Aaa (point 1).","Missing the key trade-off in Wcag Conformance Levels A Aa Aaa (point 2)."]'::jsonb, '["How would you apply Wcag Conformance Levels A Aa Aaa in a production Product Design app (follow-up 1)?","How would you apply Wcag Conformance Levels A Aa Aaa in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"W3C — WCAG 2 Overview and Conformance Levels","url":"https://www.w3.org/WAI/standards-guidelines/wcag/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-002' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Wcag Conformance Levels A Aa Aaa?' or l.short_answer is distinct from 'This question checks the core Wcag Conformance Levels A Aa Aaa concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Wcag Conformance Levels A Aa Aaa with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Wcag Conformance Levels A Aa Aaa (point 1).","Missing the key trade-off in Wcag Conformance Levels A Aa Aaa (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Wcag Conformance Levels A Aa Aaa in a production Product Design app (follow-up 1)?","How would you apply Wcag Conformance Levels A Aa Aaa in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"W3C — WCAG 2 Overview and Conformance Levels","url":"https://www.w3.org/WAI/standards-guidelines/wcag/"}]'::jsonb)) then raise exception 'Question uxac-002 en content changed; create a new revision before seeding'; end if; end $$;
