insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم واجهات متوافقة مع قارئات الشاشة (Screen Readers) وكيف تصيغ النصوص البديلة (Alt Text) باحتراف؟', 'بضمان ترتيب قراءة منطقي ومتسق (DOM Order)، وتسمية كل عنصر تفاعلي بوضوح (Accessible Name)، وكتابة نصوص بديلة تصف الغرض الوظيفي والمعنى السياقي للصورة بدلاً من تفاصيلها الشكلية السطحية.', 'قارئ الشاشة (مثل VoiceOver و TalkBack) يقرأ الشاشة خطياً. إذا كانت الصورة زخرفية بحتة لا تحمل معلومة جديدة، يجب تعليمها كـ Decorative (alt='''') ليتجاهلها القارئ ولا يعطل المستخدم. وإذا كانت الصورة رسماً بيانياً أو زراً تفاعلياً، يجب أن يصف النص البديل الخلاصة أو الوظيفة (مثلاً: ''زر إغلاق النافذة'' بدلاً من ''أيقونة علامة X رمادية'').', null, '["كتابة نصوص بديلة تبدأ بعبارة ''صورة لـ...''؛ فقارئ الشاشة يعلن تلقائياً للمستخدم أنها صورة.","ترك الأزرار المعتمدة على أيقونات مجردة بدون تسمية نصية مخفية (Aria-label) فيقرأها البرنامج كزر غامض مجهول الهوية."]'::jsonb, '["كيف يؤثر ترتيب المحتوى في شجرة المكونات (Focus Order) على فهم مستخدم قارئ الشاشة؟","ما هي أدوار ARIA (Accessible Rich Internet Applications) ومتى تكون غير ضرورية؟"]'::jsonb, '[{"title":"W3C — Images Concepts: An alt Decision Tree","url":"https://www.w3.org/WAI/tutorials/images/decision-tree/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم واجهات متوافقة مع قارئات الشاشة (Screen Readers) وكيف تصيغ النصوص البديلة (Alt Text) باحتراف؟' or l.short_answer is distinct from 'بضمان ترتيب قراءة منطقي ومتسق (DOM Order)، وتسمية كل عنصر تفاعلي بوضوح (Accessible Name)، وكتابة نصوص بديلة تصف الغرض الوظيفي والمعنى السياقي للصورة بدلاً من تفاصيلها الشكلية السطحية.' or l.explanation is distinct from 'قارئ الشاشة (مثل VoiceOver و TalkBack) يقرأ الشاشة خطياً. إذا كانت الصورة زخرفية بحتة لا تحمل معلومة جديدة، يجب تعليمها كـ Decorative (alt='''') ليتجاهلها القارئ ولا يعطل المستخدم. وإذا كانت الصورة رسماً بيانياً أو زراً تفاعلياً، يجب أن يصف النص البديل الخلاصة أو الوظيفة (مثلاً: ''زر إغلاق النافذة'' بدلاً من ''أيقونة علامة X رمادية'').' or l.code_example is distinct from null or l.common_mistakes is distinct from '["كتابة نصوص بديلة تبدأ بعبارة ''صورة لـ...''؛ فقارئ الشاشة يعلن تلقائياً للمستخدم أنها صورة.","ترك الأزرار المعتمدة على أيقونات مجردة بدون تسمية نصية مخفية (Aria-label) فيقرأها البرنامج كزر غامض مجهول الهوية."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر ترتيب المحتوى في شجرة المكونات (Focus Order) على فهم مستخدم قارئ الشاشة؟","ما هي أدوار ARIA (Accessible Rich Internet Applications) ومتى تكون غير ضرورية؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Images Concepts: An alt Decision Tree","url":"https://www.w3.org/WAI/tutorials/images/decision-tree/"}]'::jsonb)) then raise exception 'Question uxac-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Designing For Screen Readers And Alt Text?', 'This question checks the core Designing For Screen Readers And Alt Text concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Designing For Screen Readers And Alt Text with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Designing For Screen Readers And Alt Text (point 1).","Missing the key trade-off in Designing For Screen Readers And Alt Text (point 2)."]'::jsonb, '["How would you apply Designing For Screen Readers And Alt Text in a production Product Design app (follow-up 1)?","How would you apply Designing For Screen Readers And Alt Text in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"W3C — Images Concepts: An alt Decision Tree","url":"https://www.w3.org/WAI/tutorials/images/decision-tree/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
