insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا يحظر الاعتماد على اللون وحده لتوصيل المعلومات وكيف تدعم المصابين بعمى الألوان (Color Blindness)؟', 'لأن حوالي 8% من الرجال و 0.5% من النساء يعانون من أشكال مختلفة من عمى الألوان؛ والاعتماد على اللون وحده يجعلهم عاجزين عن التمييز بين حالات النظام المختلفة (كالنجاح والفشل).', 'الأنواع الشائعة لعمى الألوان تشمل عدم تمييز الأحمر والأخضر (Deuteranopia و Protanopia) وعدم تمييز الأزرق والأصفر (Tritanopia). الحل التصميمي المعتمد هو ''الاستقلال اللوني'' (Color Independence): إقران اللون دائماً بعنصر بصري مساند؛ مثل إضافة أيقونة صح (✓) بجانب اللون الأخضر، وأيقونة تعجب (!) بجانب اللون الأحمر، وخط سفلي للروابط النصية لتمييزها عن النص العادي.', null, '["تصميم حقول الإدخال الخاطئة بإطار أحمر فقط دون أيقونة تنبيهية أو نص خطأ يشرح المشكلة.","تصميم الرسوم البيانية الدائرية معتمدة على درجات متقاربة من الأخضر والأحمر لتمثيل الأرباح والخسائر."]'::jsonb, '["كيف تستخدم أدوات محاكاة عمى الألوان (Color Blindness Simulators) في Figma لفحص شاشاتك؟","كيف تصمم مؤشرات التبديل (Toggles / Switches) لتوضح حالتي التشغيل والإيقاف بدون الاعتماد على اللون فقط؟"]'::jsonb, '[{"title":"W3C — Use of Color: Understanding SC 1.4.1","url":"https://www.w3.org/WAI/WCAG21/Understanding/use-of-color.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا يحظر الاعتماد على اللون وحده لتوصيل المعلومات وكيف تدعم المصابين بعمى الألوان (Color Blindness)؟' or l.short_answer is distinct from 'لأن حوالي 8% من الرجال و 0.5% من النساء يعانون من أشكال مختلفة من عمى الألوان؛ والاعتماد على اللون وحده يجعلهم عاجزين عن التمييز بين حالات النظام المختلفة (كالنجاح والفشل).' or l.explanation is distinct from 'الأنواع الشائعة لعمى الألوان تشمل عدم تمييز الأحمر والأخضر (Deuteranopia و Protanopia) وعدم تمييز الأزرق والأصفر (Tritanopia). الحل التصميمي المعتمد هو ''الاستقلال اللوني'' (Color Independence): إقران اللون دائماً بعنصر بصري مساند؛ مثل إضافة أيقونة صح (✓) بجانب اللون الأخضر، وأيقونة تعجب (!) بجانب اللون الأحمر، وخط سفلي للروابط النصية لتمييزها عن النص العادي.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تصميم حقول الإدخال الخاطئة بإطار أحمر فقط دون أيقونة تنبيهية أو نص خطأ يشرح المشكلة.","تصميم الرسوم البيانية الدائرية معتمدة على درجات متقاربة من الأخضر والأحمر لتمثيل الأرباح والخسائر."]'::jsonb or l.follow_up_questions is distinct from '["كيف تستخدم أدوات محاكاة عمى الألوان (Color Blindness Simulators) في Figma لفحص شاشاتك؟","كيف تصمم مؤشرات التبديل (Toggles / Switches) لتوضح حالتي التشغيل والإيقاف بدون الاعتماد على اللون فقط؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Use of Color: Understanding SC 1.4.1","url":"https://www.w3.org/WAI/WCAG21/Understanding/use-of-color.html"}]'::jsonb)) then raise exception 'Question uxac-004 ar content changed; create a new revision before seeding'; end if; end $$;
