insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxac-005', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المعايير القياسية لأبعاد أهداف اللمس (Touch Target Sizes) عبر المنصات المختلفة؟', 'الحد الأدنى لمساحة اللمس هو 48x48dp في نظام أندرويد (Material Design)، و 44x44pt في نظام آبل (iOS HIG)، و 24x24px كحد أدنى في معيار WCAG 2.2.', 'في الهواتف، الأصابع البشرية ليست كالسهم المدبب للفأرة؛ مساحة تلامس وسادة الإصبع مع الزجاج تتراوح بين 9 إلى 11 مليمتر. إذا كانت الأزرار متقاربة وأصغر من 48dp، يرتكب المستخدمون أخطاء نقر متكررة ومحبطة. يمكن أن يكون الرمز البصري للأيقونة صغيراً (مثلاً 20x20px) ولكن يجب أن تكون مساحة النقر المحيطة به (Padding / Target Area) واسعة ومطابقة للحد الأدنى.', null, '["تصميم روابط نصية متراصة في سطرين دون مسافة رأسية كافية مما يجعل النقر على الرابط الصحيح مهمة شاقة.","وضع أزرار الحذف بجوار أزرار التعديل مباشرة بمساحات نقر بالغة الصغر."]'::jsonb, '["ما هي استثناءات معيار أهداف اللمس في WCAG 2.2 (مثل الروابط المضمنة في فقرات النصوص)؟","كيف يؤثر التباعد بين أهداف اللمس (Touch Target Spacing) على خفض نسبة الأخطاء اللمسية؟"]'::jsonb, '[{"title":"Material Design — Accessibility: Touch Target Sizes and Spacing","url":"https://material.io/design/usability/accessibility.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المعايير القياسية لأبعاد أهداف اللمس (Touch Target Sizes) عبر المنصات المختلفة؟' or l.short_answer is distinct from 'الحد الأدنى لمساحة اللمس هو 48x48dp في نظام أندرويد (Material Design)، و 44x44pt في نظام آبل (iOS HIG)، و 24x24px كحد أدنى في معيار WCAG 2.2.' or l.explanation is distinct from 'في الهواتف، الأصابع البشرية ليست كالسهم المدبب للفأرة؛ مساحة تلامس وسادة الإصبع مع الزجاج تتراوح بين 9 إلى 11 مليمتر. إذا كانت الأزرار متقاربة وأصغر من 48dp، يرتكب المستخدمون أخطاء نقر متكررة ومحبطة. يمكن أن يكون الرمز البصري للأيقونة صغيراً (مثلاً 20x20px) ولكن يجب أن تكون مساحة النقر المحيطة به (Padding / Target Area) واسعة ومطابقة للحد الأدنى.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تصميم روابط نصية متراصة في سطرين دون مسافة رأسية كافية مما يجعل النقر على الرابط الصحيح مهمة شاقة.","وضع أزرار الحذف بجوار أزرار التعديل مباشرة بمساحات نقر بالغة الصغر."]'::jsonb or l.follow_up_questions is distinct from '["ما هي استثناءات معيار أهداف اللمس في WCAG 2.2 (مثل الروابط المضمنة في فقرات النصوص)؟","كيف يؤثر التباعد بين أهداف اللمس (Touch Target Spacing) على خفض نسبة الأخطاء اللمسية؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Accessibility: Touch Target Sizes and Spacing","url":"https://material.io/design/usability/accessibility.html"}]'::jsonb)) then raise exception 'Question uxac-005 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Touch Target Sizes Mobile Ergonomics?', 'This question checks the core Touch Target Sizes Mobile Ergonomics concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Touch Target Sizes Mobile Ergonomics with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Touch Target Sizes Mobile Ergonomics (point 1).","Missing the key trade-off in Touch Target Sizes Mobile Ergonomics (point 2)."]'::jsonb, '["How would you apply Touch Target Sizes Mobile Ergonomics in a production Product Design app (follow-up 1)?","How would you apply Touch Target Sizes Mobile Ergonomics in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Accessibility: Touch Target Sizes and Spacing","url":"https://material.io/design/usability/accessibility.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-005' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Touch Target Sizes Mobile Ergonomics?' or l.short_answer is distinct from 'This question checks the core Touch Target Sizes Mobile Ergonomics concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Touch Target Sizes Mobile Ergonomics with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Touch Target Sizes Mobile Ergonomics (point 1).","Missing the key trade-off in Touch Target Sizes Mobile Ergonomics (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Touch Target Sizes Mobile Ergonomics in a production Product Design app (follow-up 1)?","How would you apply Touch Target Sizes Mobile Ergonomics in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Accessibility: Touch Target Sizes and Spacing","url":"https://material.io/design/usability/accessibility.html"}]'::jsonb)) then raise exception 'Question uxac-005 en content changed; create a new revision before seeding'; end if; end $$;
