insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'لماذا تعد حالات التركيز (Focus States) ومؤشرات لوحة المفاتيح ضرورة قصوى وما هي مواصفاتها المثلى؟', 'لأن المستخدمين الذين يعتمدون على لوحة المفاتيح للتنقل (بسبب إعاقات حركية أو تفضيل الكفاءة) يعتمدون كلياً على مؤشر التركيز لمعرفة العنصر المحدد حالياً قبل الضغط على Enter أو Space.', 'إلغاء حلقة التركيز في الكود (مثل كتابة outline: none بدون بديل) يعد جريمة في قابلية الاستخدام لأنه يجعل المستخدم يتنقل في الظلام. مؤشر التركيز المثالي يجب أن يكون: 1) مرئياً بوضوح شديد. 2) متبايناً لونياً بنسبة 3:1 على الأقل مع الخلفية والعنصر نفسه. 3) ذو سمك لا يقل عن 2px ومحيط بالعنصر أو مزاح قليلاً عنه (Offset Focus Ring) لتجنب اختفائه خلف حدود العنصر.', null, '["إزالة حدود التركيز الافتراضية للمتصفح دون استبدالها بتصميم بصري مخصص وواضح.","تصميم ترتيب انتقال غير منطقي (Broken Tab Order) يقفز بين زوايا الشاشة عشوائياً بدلاً من الترتيب البصري."]'::jsonb, '["ما هو معيار WCAG 2.4.7 الخاص بظهور التركيز ومعيار WCAG 2.4.11 الجديد لعدم حجب التركيز؟","كيف تبرمج ميزة ''تخطي إلى المحتوى الرئيسي'' (Skip to Main Content Link) لمستخدمي لوحة المفاتيح؟"]'::jsonb, '[{"title":"W3C — Focus Visible: Understanding Success Criterion 2.4.7","url":"https://www.w3.org/WAI/WCAG21/Understanding/focus-visible.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'لماذا تعد حالات التركيز (Focus States) ومؤشرات لوحة المفاتيح ضرورة قصوى وما هي مواصفاتها المثلى؟' or l.short_answer is distinct from 'لأن المستخدمين الذين يعتمدون على لوحة المفاتيح للتنقل (بسبب إعاقات حركية أو تفضيل الكفاءة) يعتمدون كلياً على مؤشر التركيز لمعرفة العنصر المحدد حالياً قبل الضغط على Enter أو Space.' or l.explanation is distinct from 'إلغاء حلقة التركيز في الكود (مثل كتابة outline: none بدون بديل) يعد جريمة في قابلية الاستخدام لأنه يجعل المستخدم يتنقل في الظلام. مؤشر التركيز المثالي يجب أن يكون: 1) مرئياً بوضوح شديد. 2) متبايناً لونياً بنسبة 3:1 على الأقل مع الخلفية والعنصر نفسه. 3) ذو سمك لا يقل عن 2px ومحيط بالعنصر أو مزاح قليلاً عنه (Offset Focus Ring) لتجنب اختفائه خلف حدود العنصر.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إزالة حدود التركيز الافتراضية للمتصفح دون استبدالها بتصميم بصري مخصص وواضح.","تصميم ترتيب انتقال غير منطقي (Broken Tab Order) يقفز بين زوايا الشاشة عشوائياً بدلاً من الترتيب البصري."]'::jsonb or l.follow_up_questions is distinct from '["ما هو معيار WCAG 2.4.7 الخاص بظهور التركيز ومعيار WCAG 2.4.11 الجديد لعدم حجب التركيز؟","كيف تبرمج ميزة ''تخطي إلى المحتوى الرئيسي'' (Skip to Main Content Link) لمستخدمي لوحة المفاتيح؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Focus Visible: Understanding Success Criterion 2.4.7","url":"https://www.w3.org/WAI/WCAG21/Understanding/focus-visible.html"}]'::jsonb)) then raise exception 'Question uxac-006 ar content changed; create a new revision before seeding'; end if; end $$;
