insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي إمكانية الوصول الإدراكي (Cognitive Accessibility) وكيف تجعل الواجهات سهلة الفهم للجميع؟', 'هي ممارسة تصميمية تراعي المستخدمين ذوي صعوبات التعلم وعسر القراءة وتشتت الانتباه وكبار السن، عبر تبسيط اللغة وهيكلة الواجهات وجعل السلوكيات متوقعة وثابتة.', 'تشمل إمكانية الوصول الإدراكي: 1) استخدام لغة مبسطة ومباشرة (Plain Language) وتجنب المصطلحات التقنية المعقدة. 2) إعطاء المستخدم وقتاً كافياً أو خيار إيقاف المؤقتات الزمنية للجلسات. 3) تقليل المشتتات والرسوم المتحركة التلقائية. 4) توفير خطوات تراجع وإلغاء واضحة للمهام الحساسة. 5) تقسيم المهام الطويلة إلى خطوات إرشادية تدريجية.', null, '["وضع عدادات وقت تنازلية صارمة في استمارات التقديم تطرد المستخدم فجأة دون سابق إنذار.","كتابة نصوص إرشادية مطولة بلغة قانونية معقدة يصعب على القارئ العادي استيعابها."]'::jsonb, '["كيف تساهم مقاييس مقروئية النصوص (مثل Flesch-Kincaid Grade Level) في تقييم محتوى الواجهات؟","ما هي أفضل ممارسات تصميم الخطوط والمسافات لمساعدة المصابين بعسر القراءة (Dyslexia)؟"]'::jsonb, '[{"title":"W3C — Cognitive Accessibility Guidance","url":"https://www.w3.org/WAI/cognitive/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي إمكانية الوصول الإدراكي (Cognitive Accessibility) وكيف تجعل الواجهات سهلة الفهم للجميع؟' or l.short_answer is distinct from 'هي ممارسة تصميمية تراعي المستخدمين ذوي صعوبات التعلم وعسر القراءة وتشتت الانتباه وكبار السن، عبر تبسيط اللغة وهيكلة الواجهات وجعل السلوكيات متوقعة وثابتة.' or l.explanation is distinct from 'تشمل إمكانية الوصول الإدراكي: 1) استخدام لغة مبسطة ومباشرة (Plain Language) وتجنب المصطلحات التقنية المعقدة. 2) إعطاء المستخدم وقتاً كافياً أو خيار إيقاف المؤقتات الزمنية للجلسات. 3) تقليل المشتتات والرسوم المتحركة التلقائية. 4) توفير خطوات تراجع وإلغاء واضحة للمهام الحساسة. 5) تقسيم المهام الطويلة إلى خطوات إرشادية تدريجية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع عدادات وقت تنازلية صارمة في استمارات التقديم تطرد المستخدم فجأة دون سابق إنذار.","كتابة نصوص إرشادية مطولة بلغة قانونية معقدة يصعب على القارئ العادي استيعابها."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم مقاييس مقروئية النصوص (مثل Flesch-Kincaid Grade Level) في تقييم محتوى الواجهات؟","ما هي أفضل ممارسات تصميم الخطوط والمسافات لمساعدة المصابين بعسر القراءة (Dyslexia)؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Cognitive Accessibility Guidance","url":"https://www.w3.org/WAI/cognitive/"}]'::jsonb)) then raise exception 'Question uxac-007 ar content changed; create a new revision before seeding'; end if; end $$;
