insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين التصميم الشامل (Inclusive Design) والتصميم العالمي (Universal Design) والتصميم القابل للنفاذ (Accessible Design)؟', 'التصميم القابل للنفاذ يركز على الامتثال التقني للمعايير واللوائح لذوي الإعاقة، والتصميم العالمي يسعى لإنشاء حل وحيد يناسب الجميع، بينما التصميم الشامل منهجية تشرك الفئات المهمشة وتصمم حلولاً متنوعة تناسب احتياجات بشرية مختلفة.', 'التصميم الشامل (الذي روجت له Microsoft Design) يقوم على مبدأ ''حل لفئة واحدة ويمتد النفع للجميع'' (Solve for one, extend to many). على سبيل المثال: تصميم تسميات توضيحية للفيديو موجه أساساً لفاقدي السمع (إعاقة دائمة)، ولكنه يفيد الراكب في قطار مزدحم بدون سماعات (إعاقة ظرفية)، أو الأم التي تحمل طفلاً نائماً (إعاقة مؤقتة). إنه يرى الإعاقة كتفاوت بين قدرات الإنسان والبيئة المصممة وليست نقصاً شخصياً.', null, '["التعامل مع إمكانية الوصول كقائمة فحص تقنية في نهاية المشروع بدلاً من تبني الشمولية كعقلية في التفكير.","افتراض وجود مستخدم ''عادي ومتوسط'' وتصميم كل شيء وفق هذا الوهم الإحصائي."]'::jsonb, '["ما هي بطاقات الشخصيات الشاملة (Persona Spectrums) وكيف تكشف الإعاقات الدائمة والمؤقتة والظرفية؟","كيف تنظم جلسات Co-design تشاركية يشارك فيها ذوو الإعاقة في مراحل التخطيط الأولى؟"]'::jsonb, '[{"title":"Microsoft Design — Inclusive Design Principles","url":"https://www.microsoft.com/design/inclusive/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين التصميم الشامل (Inclusive Design) والتصميم العالمي (Universal Design) والتصميم القابل للنفاذ (Accessible Design)؟' or l.short_answer is distinct from 'التصميم القابل للنفاذ يركز على الامتثال التقني للمعايير واللوائح لذوي الإعاقة، والتصميم العالمي يسعى لإنشاء حل وحيد يناسب الجميع، بينما التصميم الشامل منهجية تشرك الفئات المهمشة وتصمم حلولاً متنوعة تناسب احتياجات بشرية مختلفة.' or l.explanation is distinct from 'التصميم الشامل (الذي روجت له Microsoft Design) يقوم على مبدأ ''حل لفئة واحدة ويمتد النفع للجميع'' (Solve for one, extend to many). على سبيل المثال: تصميم تسميات توضيحية للفيديو موجه أساساً لفاقدي السمع (إعاقة دائمة)، ولكنه يفيد الراكب في قطار مزدحم بدون سماعات (إعاقة ظرفية)، أو الأم التي تحمل طفلاً نائماً (إعاقة مؤقتة). إنه يرى الإعاقة كتفاوت بين قدرات الإنسان والبيئة المصممة وليست نقصاً شخصياً.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["التعامل مع إمكانية الوصول كقائمة فحص تقنية في نهاية المشروع بدلاً من تبني الشمولية كعقلية في التفكير.","افتراض وجود مستخدم ''عادي ومتوسط'' وتصميم كل شيء وفق هذا الوهم الإحصائي."]'::jsonb or l.follow_up_questions is distinct from '["ما هي بطاقات الشخصيات الشاملة (Persona Spectrums) وكيف تكشف الإعاقات الدائمة والمؤقتة والظرفية؟","كيف تنظم جلسات Co-design تشاركية يشارك فيها ذوو الإعاقة في مراحل التخطيط الأولى؟"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Design — Inclusive Design Principles","url":"https://www.microsoft.com/design/inclusive/"}]'::jsonb)) then raise exception 'Question uxac-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Inclusive Design Vs Universal Design Vs Accessible Design?', 'This question checks the core Inclusive Design Vs Universal Design Vs Accessible Design concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Inclusive Design Vs Universal Design Vs Accessible Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Inclusive Design Vs Universal Design Vs Accessible Design (point 1).","Missing the key trade-off in Inclusive Design Vs Universal Design Vs Accessible Design (point 2)."]'::jsonb, '["How would you apply Inclusive Design Vs Universal Design Vs Accessible Design in a production Product Design app (follow-up 1)?","How would you apply Inclusive Design Vs Universal Design Vs Accessible Design in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Microsoft Design — Inclusive Design Principles","url":"https://www.microsoft.com/design/inclusive/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-008' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Inclusive Design Vs Universal Design Vs Accessible Design?' or l.short_answer is distinct from 'This question checks the core Inclusive Design Vs Universal Design Vs Accessible Design concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Inclusive Design Vs Universal Design Vs Accessible Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Inclusive Design Vs Universal Design Vs Accessible Design (point 1).","Missing the key trade-off in Inclusive Design Vs Universal Design Vs Accessible Design (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Inclusive Design Vs Universal Design Vs Accessible Design in a production Product Design app (follow-up 1)?","How would you apply Inclusive Design Vs Universal Design Vs Accessible Design in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Microsoft Design — Inclusive Design Principles","url":"https://www.microsoft.com/design/inclusive/"}]'::jsonb)) then raise exception 'Question uxac-008 en content changed; create a new revision before seeding'; end if; end $$;
