insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم استمارات ونماذج إدخال (Forms) متوافقة تماماً مع إمكانية الوصول وتمنع الأخطاء مسبقاً؟', 'بإبقاء التسميات (Labels) ظاهرة وثابتة دائماً، واستخدام نصوص مساعدة واضحة، وتوضيح الأخطاء في مكانها (Inline Validation) فور الإدخال مع رسائل تصحيحية واضحة.', 'من أكبر أخطاء النماذج استخدام النصوص البديلة داخل الحقل (Placeholder as Label)؛ لأنها تختفي بمجرد بدء الكتابة وتفتقر للتباين الكافي وتضلل قارئات الشاشة. النموذج الذي يراعي الوصول يوفر: 1) وسماً نصياً ثابتاً فوق الحقل. 2) إشارة واضحة للحقول الإلزامية نصياً وليس بلون النجمة فقط. 3) اقتراحات استباقية لمعالجة الأخطاء قبل إرسال النموذج. 4) شاشة مراجعة نهائية قبل العمليات المالية لتأكيد الرغبة ومنع الخطأ.', null, '["الاعتماد على Placeholders كبديل وحيد لعناوين الحقول لتوفير المساحة الشكلية.","عرض أخطاء الإدخال بعد الضغط على الإرسال في أعلى الصفحة فقط دون ربطها بالحقول المعنية."]'::jsonb, '["كيف تربط رسائل الخطأ بالحقل المقابل برمجياً عبر خاصية aria-describedby؟","ما هي متطلبات الملء التلقائي (Autocomplete Attributes) في معيار WCAG 1.3.5 لتسهيل الإدخال؟"]'::jsonb, '[{"title":"W3C — Forms Concepts: Labeling Controls","url":"https://www.w3.org/WAI/tutorials/forms/labels/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم استمارات ونماذج إدخال (Forms) متوافقة تماماً مع إمكانية الوصول وتمنع الأخطاء مسبقاً؟' or l.short_answer is distinct from 'بإبقاء التسميات (Labels) ظاهرة وثابتة دائماً، واستخدام نصوص مساعدة واضحة، وتوضيح الأخطاء في مكانها (Inline Validation) فور الإدخال مع رسائل تصحيحية واضحة.' or l.explanation is distinct from 'من أكبر أخطاء النماذج استخدام النصوص البديلة داخل الحقل (Placeholder as Label)؛ لأنها تختفي بمجرد بدء الكتابة وتفتقر للتباين الكافي وتضلل قارئات الشاشة. النموذج الذي يراعي الوصول يوفر: 1) وسماً نصياً ثابتاً فوق الحقل. 2) إشارة واضحة للحقول الإلزامية نصياً وليس بلون النجمة فقط. 3) اقتراحات استباقية لمعالجة الأخطاء قبل إرسال النموذج. 4) شاشة مراجعة نهائية قبل العمليات المالية لتأكيد الرغبة ومنع الخطأ.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاعتماد على Placeholders كبديل وحيد لعناوين الحقول لتوفير المساحة الشكلية.","عرض أخطاء الإدخال بعد الضغط على الإرسال في أعلى الصفحة فقط دون ربطها بالحقول المعنية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تربط رسائل الخطأ بالحقل المقابل برمجياً عبر خاصية aria-describedby؟","ما هي متطلبات الملء التلقائي (Autocomplete Attributes) في معيار WCAG 1.3.5 لتسهيل الإدخال؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Forms Concepts: Labeling Controls","url":"https://www.w3.org/WAI/tutorials/forms/labels/"}]'::jsonb)) then raise exception 'Question uxac-009 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Accessible Form Design And Error Prevention?', 'This question checks the core Accessible Form Design And Error Prevention concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Accessible Form Design And Error Prevention with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Accessible Form Design And Error Prevention (point 1).","Missing the key trade-off in Accessible Form Design And Error Prevention (point 2)."]'::jsonb, '["How would you apply Accessible Form Design And Error Prevention in a production Product Design app (follow-up 1)?","How would you apply Accessible Form Design And Error Prevention in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"W3C — Forms Concepts: Labeling Controls","url":"https://www.w3.org/WAI/tutorials/forms/labels/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
