insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي المتطلبات الصارمة لإمكانية وصول الوسائط المتعددة (فيديو وصوت) وفق معايير الويب الدولية؟', 'توفير ترجمات نصية دقيقة متزامنة (Captions)، ونصوص مفرغة كاملة (Transcripts)، ووصف صوتي للأحداث البصرية الصامتة (Audio Description)، مع منع التشغيل التلقائي للصوتيات تماماً.', 'الترجمات النصية المغلقة (Closed Captions) لا تكتفي بنقل كلمات الحوار فقط، بل تصف المؤثرات الصوتية المعبرة (مثل [موسيقى حزينة]، [صوت تصفيق حاد]). النص المفرغ الكامل يسمح للمكفوفين بقراءة الفيديو بأجهزة برايل أو بالبحث السريع داخل النص. وأي وسائط تفاعلية يجب أن تمنح المستخدم تحكماً كاملاً في مستوى الصوت والتقديم والتأخير دون أي مفاجآت.', null, '["تشغيل مقاطع الفيديو أو الإعلانات الترويجية بالصوت تلقائياً فور فتح الموقع مما يزعج مستخدمي قارئات الشاشة.","الاعتماد على الترجمات التلقائية الآلية دون مراجعة بشرية للتدقيق اللغوي والمصطلحات."]'::jsonb, '["ما الفرق بين Closed Captions (CC) و Open Captions (Hardcoded) في المرونة والتخصيص؟","ما هي شروط تجنب ومضات الضوء السريعة (Three Flashes Rule) لمنع نوبات الصرع البصري؟"]'::jsonb, '[{"title":"W3C — Making Audio and Video Media Accessible","url":"https://www.w3.org/WAI/media/av/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxac-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي المتطلبات الصارمة لإمكانية وصول الوسائط المتعددة (فيديو وصوت) وفق معايير الويب الدولية؟' or l.short_answer is distinct from 'توفير ترجمات نصية دقيقة متزامنة (Captions)، ونصوص مفرغة كاملة (Transcripts)، ووصف صوتي للأحداث البصرية الصامتة (Audio Description)، مع منع التشغيل التلقائي للصوتيات تماماً.' or l.explanation is distinct from 'الترجمات النصية المغلقة (Closed Captions) لا تكتفي بنقل كلمات الحوار فقط، بل تصف المؤثرات الصوتية المعبرة (مثل [موسيقى حزينة]، [صوت تصفيق حاد]). النص المفرغ الكامل يسمح للمكفوفين بقراءة الفيديو بأجهزة برايل أو بالبحث السريع داخل النص. وأي وسائط تفاعلية يجب أن تمنح المستخدم تحكماً كاملاً في مستوى الصوت والتقديم والتأخير دون أي مفاجآت.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تشغيل مقاطع الفيديو أو الإعلانات الترويجية بالصوت تلقائياً فور فتح الموقع مما يزعج مستخدمي قارئات الشاشة.","الاعتماد على الترجمات التلقائية الآلية دون مراجعة بشرية للتدقيق اللغوي والمصطلحات."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين Closed Captions (CC) و Open Captions (Hardcoded) في المرونة والتخصيص؟","ما هي شروط تجنب ومضات الضوء السريعة (Three Flashes Rule) لمنع نوبات الصرع البصري؟"]'::jsonb or l.sources is distinct from '[{"title":"W3C — Making Audio and Video Media Accessible","url":"https://www.w3.org/WAI/media/av/"}]'::jsonb)) then raise exception 'Question uxac-010 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Media Accessibility Captions Transcripts And Audio Descriptions?', 'This question checks the core Media Accessibility Captions Transcripts And Audio Descriptions concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Media Accessibility Captions Transcripts And Audio Descriptions with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Media Accessibility Captions Transcripts And Audio Descriptions (point 1).","Missing the key trade-off in Media Accessibility Captions Transcripts And Audio Descriptions (point 2)."]'::jsonb, '["How would you apply Media Accessibility Captions Transcripts And Audio Descriptions in a production Product Design app (follow-up 1)?","How would you apply Media Accessibility Captions Transcripts And Audio Descriptions in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"W3C — Making Audio and Video Media Accessible","url":"https://www.w3.org/WAI/media/av/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxac-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
