insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو إطار عمل HEART من Google وكيف تحول أهداف تجربة المستخدم إلى مقاييس رقمية دقيقة؟', 'هو إطار يقيس تجربة المستخدم عبر 5 أبعاد: السعادة (Happiness)، التفاعل (Engagement)، التبني (Adoption)، الاحتفاظ (Retention)، ونجاح المهام (Task Success)، باستخدام مصفوفة الأهداف والإشارات والمقاييس (Goals - Signals - Metrics).', 'الميزة الكبرى لـ HEART هي جدول (GSM Matrix): تبدأ بتحديد ''الهدف'' السامي على مستوى التجربة (مثل: مساعدة المستخدم في العثور على ما يريد بسهولة)، ثم تبحث عن ''الإشارة'' السلوكية التي تدل على تحقيق الهدف (مثل: النقر على النتيجة الأولى دون تعديل البحث)، ثم تضع ''المقياس'' الرقمي القابل للرصد في التحليلات (مثل: نسبة النقرات الناجحة من المحاولة الأولى). هذا يمنع الغرق في مقاييس سطحية مضللة.', null, '["جمع مقاييس عامة عشوائية دون تحديد الهدف الإنساني والتجاري وراء قياسها مسبقاً.","التركيز الحصري على التفاعل (Engagement) حتى لو كان ناتجاً عن تخبط المستخدم واحتياجه لوقت أطول لإيجاد الزر."]'::jsonb, '["كيف تفرق بين التبني (Adoption) لميزة جديدة والاحتفاظ بها (Retention) على المدى الطويل؟","ما هي مقاييس السعادة (Happiness) وكيف تُجمع عبر استطلاعات الرأي داخل المنتج (In-app Surveys)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Google''s HEART Framework for Measuring UX","url":"https://www.nngroup.com/articles/heart-framework/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو إطار عمل HEART من Google وكيف تحول أهداف تجربة المستخدم إلى مقاييس رقمية دقيقة؟' or l.short_answer is distinct from 'هو إطار يقيس تجربة المستخدم عبر 5 أبعاد: السعادة (Happiness)، التفاعل (Engagement)، التبني (Adoption)، الاحتفاظ (Retention)، ونجاح المهام (Task Success)، باستخدام مصفوفة الأهداف والإشارات والمقاييس (Goals - Signals - Metrics).' or l.explanation is distinct from 'الميزة الكبرى لـ HEART هي جدول (GSM Matrix): تبدأ بتحديد ''الهدف'' السامي على مستوى التجربة (مثل: مساعدة المستخدم في العثور على ما يريد بسهولة)، ثم تبحث عن ''الإشارة'' السلوكية التي تدل على تحقيق الهدف (مثل: النقر على النتيجة الأولى دون تعديل البحث)، ثم تضع ''المقياس'' الرقمي القابل للرصد في التحليلات (مثل: نسبة النقرات الناجحة من المحاولة الأولى). هذا يمنع الغرق في مقاييس سطحية مضللة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["جمع مقاييس عامة عشوائية دون تحديد الهدف الإنساني والتجاري وراء قياسها مسبقاً.","التركيز الحصري على التفاعل (Engagement) حتى لو كان ناتجاً عن تخبط المستخدم واحتياجه لوقت أطول لإيجاد الزر."]'::jsonb or l.follow_up_questions is distinct from '["كيف تفرق بين التبني (Adoption) لميزة جديدة والاحتفاظ بها (Retention) على المدى الطويل؟","ما هي مقاييس السعادة (Happiness) وكيف تُجمع عبر استطلاعات الرأي داخل المنتج (In-app Surveys)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Google''s HEART Framework for Measuring UX","url":"https://www.nngroup.com/articles/heart-framework/"}]'::jsonb)) then raise exception 'Question uxpm-001 ar content changed; create a new revision before seeding'; end if; end $$;
