insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو مقياس قابلية استخدام النظام (System Usability Scale - SUS) وكيف تحسب درجته وتفسرها؟', 'هو استبيان معياري سريع مكون من 10 أسئلة متناوبة بين الإيجابية والسلبية يقيس قابلية استخدام المنتج برقم إجمالي يتراوح بين 0 إلى 100 نقطة.', 'للأسئلة الفردية (الإيجابية)، يُطرح 1 من تقييم المستخدم. وللأسئلة الزوجية (السلبية)، يُطرح تقييم المستخدم من 5. تُجمع النقاط وتُضرب في 2.5 للحصول على الدرجة النهائية. المتوسط المعياري العالمي لمقياس SUS هو 68 نقطة؛ أي درجة أعلى من 68 تعني قابلية استخدام مقبولة وجيدة (درجة C فأعلى)، ودرجة 80 فأعلى تعني منتجاً استثنائياً وسهل الاستخدام جداً (درجة A).', null, '["اعتبار درجة SUS نسبة مئوية مباشرة؛ فالدرجة 68 ليست 68% بل تمثل أداءً متوسطاً يقع عند الشريحة المئينية 50th Percentile.","تعديل نصوص الأسئلة العشرة المعيارية مما يفقد النتائج مصداقيتها الإحصائية ومقارنتها العالمية."]'::jsonb, '["ما الفرق بين قابلية الاستخدام المدركة عبر SUS والسهولة اللحظية للمهمة عبر مقياس SEQ (Single Ease Question)؟","كم عدد العينات المطلوبة إحصائياً للحصول على نتيجة SUS ذات دلالة موثوقة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Measuring Usability with the System Usability Scale (SUS)","url":"https://www.nngroup.com/articles/measuring-usability/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو مقياس قابلية استخدام النظام (System Usability Scale - SUS) وكيف تحسب درجته وتفسرها؟' or l.short_answer is distinct from 'هو استبيان معياري سريع مكون من 10 أسئلة متناوبة بين الإيجابية والسلبية يقيس قابلية استخدام المنتج برقم إجمالي يتراوح بين 0 إلى 100 نقطة.' or l.explanation is distinct from 'للأسئلة الفردية (الإيجابية)، يُطرح 1 من تقييم المستخدم. وللأسئلة الزوجية (السلبية)، يُطرح تقييم المستخدم من 5. تُجمع النقاط وتُضرب في 2.5 للحصول على الدرجة النهائية. المتوسط المعياري العالمي لمقياس SUS هو 68 نقطة؛ أي درجة أعلى من 68 تعني قابلية استخدام مقبولة وجيدة (درجة C فأعلى)، ودرجة 80 فأعلى تعني منتجاً استثنائياً وسهل الاستخدام جداً (درجة A).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار درجة SUS نسبة مئوية مباشرة؛ فالدرجة 68 ليست 68% بل تمثل أداءً متوسطاً يقع عند الشريحة المئينية 50th Percentile.","تعديل نصوص الأسئلة العشرة المعيارية مما يفقد النتائج مصداقيتها الإحصائية ومقارنتها العالمية."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين قابلية الاستخدام المدركة عبر SUS والسهولة اللحظية للمهمة عبر مقياس SEQ (Single Ease Question)؟","كم عدد العينات المطلوبة إحصائياً للحصول على نتيجة SUS ذات دلالة موثوقة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Measuring Usability with the System Usability Scale (SUS)","url":"https://www.nngroup.com/articles/measuring-usability/"}]'::jsonb)) then raise exception 'Question uxpm-002 ar content changed; create a new revision before seeding'; end if; end $$;
