insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين صافي نقاط الترويج (NPS) ورضا العملاء (CSAT) ونقاط جهد العميل (Customer Effort Score - CES)؟', 'الـ NPS يقيس ولاء العميل واستعداده للتوصية بالمنتج، والـ CSAT يقيس الرضا اللحظي عن تجربة أو خدمة محددة، بينما CES يقيس مدى سهولة أو صعوبة إنجاز المعاملة من وجهة نظر العميل.', 'الـ NPS يسأل: ''ما مدى احتمالية ترشيحك لمنصتنا لصديق؟'' ويقسم المستخدمين لمروجين ومحايدين ومنتقدين. الـ CSAT يسأل: ''ما مدى رضاك عن هذه الميزة؟'' بمقياس من 1 إلى 5. الـ CES يسأل: ''ما مدى سهولة إنجاز هذه المعاملة؟'' وهو المقياس الأكثر ارتباطاً بقابلية الاستخدام وتوقع ولاء العملاء مستقبلاً، لأن تقليل المجهود هو جوهر التجربة الناجحة.', null, '["الاعتماد على NPS كمقياس وحيد لقابلية استخدام الواجهات؛ فالولاء يتأثر بالسعر والدعاية وليس بالواجهة فقط.","إرسال استطلاعات CSAT في أوقات غير مناسبة تشتت المستخدم أثناء انهماكه في إتمام مهمة حرجة."]'::jsonb, '["لماذا يعتبر خفض نقاط الجهد (Customer Effort Score) أكثر تأثيراً في منع التسرب من محاولات إبهار العميل؟","كيف تحلل التعليقات النصية المصاحبة لدرجات الاستطلاعات لفهم الأسباب الحقيقية وراء الأرقام؟"]'::jsonb, '[{"title":"Nielsen Norman Group — NPS and Other Loyalty Metrics in UX","url":"https://www.nngroup.com/articles/nps-ux/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين صافي نقاط الترويج (NPS) ورضا العملاء (CSAT) ونقاط جهد العميل (Customer Effort Score - CES)؟' or l.short_answer is distinct from 'الـ NPS يقيس ولاء العميل واستعداده للتوصية بالمنتج، والـ CSAT يقيس الرضا اللحظي عن تجربة أو خدمة محددة، بينما CES يقيس مدى سهولة أو صعوبة إنجاز المعاملة من وجهة نظر العميل.' or l.explanation is distinct from 'الـ NPS يسأل: ''ما مدى احتمالية ترشيحك لمنصتنا لصديق؟'' ويقسم المستخدمين لمروجين ومحايدين ومنتقدين. الـ CSAT يسأل: ''ما مدى رضاك عن هذه الميزة؟'' بمقياس من 1 إلى 5. الـ CES يسأل: ''ما مدى سهولة إنجاز هذه المعاملة؟'' وهو المقياس الأكثر ارتباطاً بقابلية الاستخدام وتوقع ولاء العملاء مستقبلاً، لأن تقليل المجهود هو جوهر التجربة الناجحة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاعتماد على NPS كمقياس وحيد لقابلية استخدام الواجهات؛ فالولاء يتأثر بالسعر والدعاية وليس بالواجهة فقط.","إرسال استطلاعات CSAT في أوقات غير مناسبة تشتت المستخدم أثناء انهماكه في إتمام مهمة حرجة."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يعتبر خفض نقاط الجهد (Customer Effort Score) أكثر تأثيراً في منع التسرب من محاولات إبهار العميل؟","كيف تحلل التعليقات النصية المصاحبة لدرجات الاستطلاعات لفهم الأسباب الحقيقية وراء الأرقام؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — NPS and Other Loyalty Metrics in UX","url":"https://www.nngroup.com/articles/nps-ux/"}]'::jsonb)) then raise exception 'Question uxpm-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Nps Vs Csat Vs Ces User Satisfaction?', 'This question checks the core Nps Vs Csat Vs Ces User Satisfaction concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Nps Vs Csat Vs Ces User Satisfaction with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Nps Vs Csat Vs Ces User Satisfaction (point 1).","Missing the key trade-off in Nps Vs Csat Vs Ces User Satisfaction (point 2)."]'::jsonb, '["How would you apply Nps Vs Csat Vs Ces User Satisfaction in a production Product Design app (follow-up 1)?","How would you apply Nps Vs Csat Vs Ces User Satisfaction in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — NPS and Other Loyalty Metrics in UX","url":"https://www.nngroup.com/articles/nps-ux/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
