insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تقيس معدل إتمام المهمة (Task Completion Rate) والوقت المستغرق (Time on Task) وما دلالتهما؟', 'معدل إتمام المهمة يقيس الفعالية (Effectiveness: نسبة المستخدمين الذين أكملوا الهدف بنجاح)، بينما الوقت المستغرق يقيس الكفاءة (Efficiency: كم دقيقة استغرقوها للإنجاز).', 'إذا كان معدل إتمام مهمة تسجيل الحساب 60% فقط، فهذا يعني وجود خلل جسيم في التصميم يدفع 40% للاستسلام والفشل. في الوقت المستغرق، القاعدة ليست دائماً ''الوقت الأقصر أفضل'': في مهام المعاملات (كالتحويل البنكي وشراء تذكرة)، السرعة تعني كفاءة ونجاح؛ أما في مهام الاستكشاف وقراءة المقالات والتعلم، فالوقت الأطول يعني تفاعلاً واهتماماً أعلى من المستخدم.', null, '["اعتبار المستخدم الذي وصل للشاشة النهائية ناجحاً دون فحص ما إذا كانت البيانات المدخلة صحيحة.","تفسير قضاء وقت طويل داخل صفحة الدفع على أنه تفاعل إيجابي بدلاً من كونه دليلاً على الارتباك والتردد."]'::jsonb, '["كيف يؤثر معدل الخطأ لكل مهمة (Task Error Rate) على الوقت المستغرق للإنجاز؟","ما هي طريقة حساب النطاق التقديري للمتوسط (Confidence Intervals) لمعدلات الإتمام؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Task Completion Rate: The Fundamental UX Metric","url":"https://www.nngroup.com/articles/task-completion-rate/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تقيس معدل إتمام المهمة (Task Completion Rate) والوقت المستغرق (Time on Task) وما دلالتهما؟' or l.short_answer is distinct from 'معدل إتمام المهمة يقيس الفعالية (Effectiveness: نسبة المستخدمين الذين أكملوا الهدف بنجاح)، بينما الوقت المستغرق يقيس الكفاءة (Efficiency: كم دقيقة استغرقوها للإنجاز).' or l.explanation is distinct from 'إذا كان معدل إتمام مهمة تسجيل الحساب 60% فقط، فهذا يعني وجود خلل جسيم في التصميم يدفع 40% للاستسلام والفشل. في الوقت المستغرق، القاعدة ليست دائماً ''الوقت الأقصر أفضل'': في مهام المعاملات (كالتحويل البنكي وشراء تذكرة)، السرعة تعني كفاءة ونجاح؛ أما في مهام الاستكشاف وقراءة المقالات والتعلم، فالوقت الأطول يعني تفاعلاً واهتماماً أعلى من المستخدم.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار المستخدم الذي وصل للشاشة النهائية ناجحاً دون فحص ما إذا كانت البيانات المدخلة صحيحة.","تفسير قضاء وقت طويل داخل صفحة الدفع على أنه تفاعل إيجابي بدلاً من كونه دليلاً على الارتباك والتردد."]'::jsonb or l.follow_up_questions is distinct from '["كيف يؤثر معدل الخطأ لكل مهمة (Task Error Rate) على الوقت المستغرق للإنجاز؟","ما هي طريقة حساب النطاق التقديري للمتوسط (Confidence Intervals) لمعدلات الإتمام؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Task Completion Rate: The Fundamental UX Metric","url":"https://www.nngroup.com/articles/task-completion-rate/"}]'::jsonb)) then raise exception 'Question uxpm-004 ar content changed; create a new revision before seeding'; end if; end $$;
