insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تحلل مسارات التحويل (Conversion Funnels) واكتشاف نقاط التسرب (Drop-offs) في الواجهات؟', 'بتتبع خطوات الرحلة بالتسلسل من نقطة البداية حتى الهدف النهائي، وتحديد الخطوة التي تشهد أعلى نسبة خروج وتوقف للمستخدمين للتركيز على فحص واجهتها وعلاج مشاكلها.', 'في متجر إلكتروني، يبدأ المسار بـ: مشاهدة السلة -> إدخال العنوان -> خيارات الشحن -> إدخال الدفع -> الشاشة النهائية. إذا أظهرت التحليلات أن 70% من المستخدمين يتسربون عند شاشة الشحن، فهذا يوجه المصممين فوراً للتحقيق: هل تكاليف الشحن غير واضحة ومفاجئة؟ هل الحقول معقدة؟ هل خيارات الدفع المحلية غير متوفرة؟ التحليل يحدد ''أين'' تحدث المشكلة، بينما أبحاث المستخدمين تكشف ''لماذا''.', null, '["تعديل الواجهة بناءً على تخمينات شخصية بدلاً من الاستعانة ببيانات مسارات التحويل في تحديد موضع الخلل.","تجاهل تتبع المستخدمين عبر الأجهزة المتعددة (Cross-device Funnels) عند حساب نسب التسرب."]'::jsonb, '["كيف تساهم الخرائط الحرارية (Heatmaps) وتسجيلات الجلسات (Session Replays) في تفسير أسباب التسرب؟","ما هو مفهوم التكلفة غير المحسوبة في عملية الدفع (Friction Audit) وكيف تقلصها؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Conversion Rates and UX","url":"https://www.nngroup.com/articles/conversion-rates/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تحلل مسارات التحويل (Conversion Funnels) واكتشاف نقاط التسرب (Drop-offs) في الواجهات؟' or l.short_answer is distinct from 'بتتبع خطوات الرحلة بالتسلسل من نقطة البداية حتى الهدف النهائي، وتحديد الخطوة التي تشهد أعلى نسبة خروج وتوقف للمستخدمين للتركيز على فحص واجهتها وعلاج مشاكلها.' or l.explanation is distinct from 'في متجر إلكتروني، يبدأ المسار بـ: مشاهدة السلة -> إدخال العنوان -> خيارات الشحن -> إدخال الدفع -> الشاشة النهائية. إذا أظهرت التحليلات أن 70% من المستخدمين يتسربون عند شاشة الشحن، فهذا يوجه المصممين فوراً للتحقيق: هل تكاليف الشحن غير واضحة ومفاجئة؟ هل الحقول معقدة؟ هل خيارات الدفع المحلية غير متوفرة؟ التحليل يحدد ''أين'' تحدث المشكلة، بينما أبحاث المستخدمين تكشف ''لماذا''.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تعديل الواجهة بناءً على تخمينات شخصية بدلاً من الاستعانة ببيانات مسارات التحويل في تحديد موضع الخلل.","تجاهل تتبع المستخدمين عبر الأجهزة المتعددة (Cross-device Funnels) عند حساب نسب التسرب."]'::jsonb or l.follow_up_questions is distinct from '["كيف تساهم الخرائط الحرارية (Heatmaps) وتسجيلات الجلسات (Session Replays) في تفسير أسباب التسرب؟","ما هو مفهوم التكلفة غير المحسوبة في عملية الدفع (Friction Audit) وكيف تقلصها؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Conversion Rates and UX","url":"https://www.nngroup.com/articles/conversion-rates/"}]'::jsonb)) then raise exception 'Question uxpm-005 ar content changed; create a new revision before seeding'; end if; end $$;
