insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الشروط المنهجية لإجراء اختبارات أ/ب (A/B Testing) وما معنى الدلالة الإحصائية (p-value < 0.05)؟', 'يتطلب إجراء الاختبار وجود فرضية محددة وعينة مستخدمين كافية وتوزيعاً عشوائياً موحداً واختبار متغير واحد فقط في كل مرة، وتأكيد الدلالة الإحصائية لضمان أن النتيجة ليست وليدة الصدفة.', 'قيمة P-value أقل من 0.05 تعني أن هناك ثقة بنسبة 95% بأن الفارق في معدل التحويل بين التصميم (A) والتصميم (B) ناتج عن التغيير التصميمي وليس تقلبات عشوائية في حركة الزوار. التسرع في إيقاف الاختبار بعد يومين بمجرد تقدم نسخة معينة هو خطأ علمي شهير (Peeking Problem)؛ يجب تشغيل الاختبار لدورات أسبوعية كاملة لتمثيل تقلبات سلوك المستخدمين بين أيام العمل وعطلات نهاية الأسبوع.', null, '["تغيير 10 عناصر مختلفة في النسخة (B) معاً مما يجعل من المستحيل معرفة أي عنصر كان سبباً في تغيير النتيجة.","إيقاف الاختبار قبل الوصول لحجم العينة المحسوب إحصائياً مما يؤدي لنتائج إيجابية كاذبة (False Positives)."]'::jsonb, '["متى يكون اختبار المتغيرات المتعددة (Multivariate Testing - MVT) أفضل من A/B Testing البسيط؟","كيف يؤثر التغيير الجديد على المدى الطويل ضد تأثير الحداثة المؤقت (Novelty Effect)؟"]'::jsonb, '[{"title":"Nielsen Norman Group — A/B Testing 101","url":"https://www.nngroup.com/articles/ab-testing/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الشروط المنهجية لإجراء اختبارات أ/ب (A/B Testing) وما معنى الدلالة الإحصائية (p-value < 0.05)؟' or l.short_answer is distinct from 'يتطلب إجراء الاختبار وجود فرضية محددة وعينة مستخدمين كافية وتوزيعاً عشوائياً موحداً واختبار متغير واحد فقط في كل مرة، وتأكيد الدلالة الإحصائية لضمان أن النتيجة ليست وليدة الصدفة.' or l.explanation is distinct from 'قيمة P-value أقل من 0.05 تعني أن هناك ثقة بنسبة 95% بأن الفارق في معدل التحويل بين التصميم (A) والتصميم (B) ناتج عن التغيير التصميمي وليس تقلبات عشوائية في حركة الزوار. التسرع في إيقاف الاختبار بعد يومين بمجرد تقدم نسخة معينة هو خطأ علمي شهير (Peeking Problem)؛ يجب تشغيل الاختبار لدورات أسبوعية كاملة لتمثيل تقلبات سلوك المستخدمين بين أيام العمل وعطلات نهاية الأسبوع.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تغيير 10 عناصر مختلفة في النسخة (B) معاً مما يجعل من المستحيل معرفة أي عنصر كان سبباً في تغيير النتيجة.","إيقاف الاختبار قبل الوصول لحجم العينة المحسوب إحصائياً مما يؤدي لنتائج إيجابية كاذبة (False Positives)."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون اختبار المتغيرات المتعددة (Multivariate Testing - MVT) أفضل من A/B Testing البسيط؟","كيف يؤثر التغيير الجديد على المدى الطويل ضد تأثير الحداثة المؤقت (Novelty Effect)؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — A/B Testing 101","url":"https://www.nngroup.com/articles/ab-testing/"}]'::jsonb)) then raise exception 'Question uxpm-006 ar content changed; create a new revision before seeding'; end if; end $$;
