insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي منهجية الاكتشاف المستمر (Continuous Discovery Habits) وكيف تضمن تدفق الملاحظات دورياً؟', 'هي ممارسة يقوم فيها فريق المنتج (المصمم ومدير المنتج والمهندس الرئيسي) بإجراء أبحاث ومقابلات أسبوعية منتظمة ومباشرة مع المستخدمين لتوجيه القرارات باستمرار بدلاً من الأبحاث المتقطعة الموسمية.', 'المنهجية التقليدية كانت تقوم على إجراء بحث ضخم لمدة شهر في بداية السنة ثم إيقاف التحدث للمستخدمين والانكفاء على البرمجة لشهور. الاكتشاف المستمر (وفق تيريزا توريس Teresa Torres) يفرض قاعدة ذهبية: مقابلة مستخدم حقيقي واحد على الأقل كل أسبوع. هذا يمنح الفريق نبضاً حياً عن تطور الاحتياجات ويحول شجرة الفرص والحلول (Opportunity Solution Tree) إلى بوصلة يومية توجه تطوير المنتج.', null, '["الاعتماد على التقارير السنوية أو بحوث السوق النظرية المتقادمة في اتخاذ قرارات الميزات الأسبوعية.","حصر المقابلات في إظهار النماذج والتحقق من التصميم بدلاً من الاستماع المفتوح للمشاكل اليومية للمستخدم."]'::jsonb, '["كيف تبني قنوات مؤتمتة تجذب مشاركين مؤهلين للمقابلات الأسبوعية بدون جهد لوجستي معطل؟","كيف تترجم مخرجات جلسات الاكتشاف الأسبوعية إلى Opportunity Solution Tree واضحة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Continuous User Research Strategies","url":"https://www.nngroup.com/articles/user-interviews/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي منهجية الاكتشاف المستمر (Continuous Discovery Habits) وكيف تضمن تدفق الملاحظات دورياً؟' or l.short_answer is distinct from 'هي ممارسة يقوم فيها فريق المنتج (المصمم ومدير المنتج والمهندس الرئيسي) بإجراء أبحاث ومقابلات أسبوعية منتظمة ومباشرة مع المستخدمين لتوجيه القرارات باستمرار بدلاً من الأبحاث المتقطعة الموسمية.' or l.explanation is distinct from 'المنهجية التقليدية كانت تقوم على إجراء بحث ضخم لمدة شهر في بداية السنة ثم إيقاف التحدث للمستخدمين والانكفاء على البرمجة لشهور. الاكتشاف المستمر (وفق تيريزا توريس Teresa Torres) يفرض قاعدة ذهبية: مقابلة مستخدم حقيقي واحد على الأقل كل أسبوع. هذا يمنح الفريق نبضاً حياً عن تطور الاحتياجات ويحول شجرة الفرص والحلول (Opportunity Solution Tree) إلى بوصلة يومية توجه تطوير المنتج.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["الاعتماد على التقارير السنوية أو بحوث السوق النظرية المتقادمة في اتخاذ قرارات الميزات الأسبوعية.","حصر المقابلات في إظهار النماذج والتحقق من التصميم بدلاً من الاستماع المفتوح للمشاكل اليومية للمستخدم."]'::jsonb or l.follow_up_questions is distinct from '["كيف تبني قنوات مؤتمتة تجذب مشاركين مؤهلين للمقابلات الأسبوعية بدون جهد لوجستي معطل؟","كيف تترجم مخرجات جلسات الاكتشاف الأسبوعية إلى Opportunity Solution Tree واضحة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Continuous User Research Strategies","url":"https://www.nngroup.com/articles/user-interviews/"}]'::jsonb)) then raise exception 'Question uxpm-007 ar content changed; create a new revision before seeding'; end if; end $$;
