insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هو الدين التصميمي (Design Debt) وما هي تكلفته غير المرئية على المنتج وسرعة الفريق؟', 'هو التراكم التدريجي للمكونات غير المتناسقة، والأنماط التفاعلية المتباينة، والحلول المؤقتة السريعة التي تضاف للمنتج مع مرور الوقت دون تنقيح، مما يثقل تجربة المستخدم ويبطئ التطوير.', 'مثلما يدفع المبرمجون ثمن الدين التقني، يعاني المستخدم من الدين التصميمي: وجود 14 درجة مختلفة من اللون الأزرق، و 6 أنماط للأزرار، ورسائل خطأ متباينة في كل قسم. تكلفته تظهر في: 1) إرباك المستخدم وتراجع ثقته في احترافية المنصة. 2) إهدار وقت المصممين والمطورين في نقاش تفاصيل مكررة. 3) صعوبة تبني ميزات جديدة. الحل يكمن في تنظيم جلسات دورية لتنظيف الدين التصميمي (Design Debt Sprint).', null, '["تجاهل توثيق القرارات التصميمية المرتجلة والمستعجلة وتركها تتراكم لسنوات حتى تصبح المنصة غير متجانسة.","افتراض أن إعادة التصميم الكاملة الجذرية من الصفر هي الحل الوحيد لتنظيف الدين التصميمي."]'::jsonb, '["كيف تجري جرد ومراجعة بصرية (Design Debt Audit) لحصر التناقضات بالأرقام وعرضها على الإدارة؟","كيف ترتب أولويات معالجة الدين التصميمي بناءً على مسار القيمة الأكثر تأثيراً على العملاء؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Design Debt and How to Manage It","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هو الدين التصميمي (Design Debt) وما هي تكلفته غير المرئية على المنتج وسرعة الفريق؟' or l.short_answer is distinct from 'هو التراكم التدريجي للمكونات غير المتناسقة، والأنماط التفاعلية المتباينة، والحلول المؤقتة السريعة التي تضاف للمنتج مع مرور الوقت دون تنقيح، مما يثقل تجربة المستخدم ويبطئ التطوير.' or l.explanation is distinct from 'مثلما يدفع المبرمجون ثمن الدين التقني، يعاني المستخدم من الدين التصميمي: وجود 14 درجة مختلفة من اللون الأزرق، و 6 أنماط للأزرار، ورسائل خطأ متباينة في كل قسم. تكلفته تظهر في: 1) إرباك المستخدم وتراجع ثقته في احترافية المنصة. 2) إهدار وقت المصممين والمطورين في نقاش تفاصيل مكررة. 3) صعوبة تبني ميزات جديدة. الحل يكمن في تنظيم جلسات دورية لتنظيف الدين التصميمي (Design Debt Sprint).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تجاهل توثيق القرارات التصميمية المرتجلة والمستعجلة وتركها تتراكم لسنوات حتى تصبح المنصة غير متجانسة.","افتراض أن إعادة التصميم الكاملة الجذرية من الصفر هي الحل الوحيد لتنظيف الدين التصميمي."]'::jsonb or l.follow_up_questions is distinct from '["كيف تجري جرد ومراجعة بصرية (Design Debt Audit) لحصر التناقضات بالأرقام وعرضها على الإدارة؟","كيف ترتب أولويات معالجة الدين التصميمي بناءً على مسار القيمة الأكثر تأثيراً على العملاء؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Design Debt and How to Manage It","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxpm-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Measuring And Managing Design Debt?', 'This question checks the core Measuring And Managing Design Debt concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Measuring And Managing Design Debt with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Measuring And Managing Design Debt (point 1).","Missing the key trade-off in Measuring And Managing Design Debt (point 2)."]'::jsonb, '["How would you apply Measuring And Managing Design Debt in a production Product Design app (follow-up 1)?","How would you apply Measuring And Managing Design Debt in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Design Debt and How to Manage It","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-008' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Measuring And Managing Design Debt?' or l.short_answer is distinct from 'This question checks the core Measuring And Managing Design Debt concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Measuring And Managing Design Debt with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Measuring And Managing Design Debt (point 1).","Missing the key trade-off in Measuring And Managing Design Debt (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Measuring And Managing Design Debt in a production Product Design app (follow-up 1)?","How would you apply Measuring And Managing Design Debt in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Design Debt and How to Manage It","url":"https://www.nngroup.com/articles/design-systems-101/"}]'::jsonb)) then raise exception 'Question uxpm-008 en content changed; create a new revision before seeding'; end if; end $$;
