insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم تجربة إيقاف وإلغاء الاشتراك (Offboarding) باحترام وتتجنب الأنماط المظلمة (Dark Patterns)؟', 'بجعل زر إلغاء الحساب واضحاً وسهل الوصول ومباشراً بخطوات قليلة ومحترمة، وسؤال المستخدم عن سبب المغادرة بلطف، دون استخدام حيل الإخفاء أو الخداع النفسي (Roach Motel).', 'الأنماط المظلمة مثل إجبار المستخدم على الاتصال برقم هاتفي لإلغاء الاشتراك أو إخفاء رابط الإلغاء بلون باهت في تذييل الصفحة وتمريره عبر 10 صفحات تأكيد معقدة (Confirmshaming) قد تؤخر التسرب مؤقتاً، لكنها تدمر سمعة الشركة وتضمن عدم عودة المستخدم للأبد. التجربة الراقية تتيح الإلغاء بسهولة بضغطة زر، وتوفر خيارات مرنة كإيقاف الاشتراك مؤقتاً (Pause)، وتقدم تجربة وداع راقية تترك الباب مفتوحاً لعودته مستقبلاً.', null, '["استخدام صياغات محرجة وابتزازية عاطفياً في أزرار الإلغاء (مثل: ''نعم، أنا لا أحب توفير المال'').","حجب زر الإلغاء تماماً من التطبيق وإجبار المستخدم على التحدث مع موظف دعم مبيعات متمرس لمنعه."]'::jsonb, '["كيف تحلل أسباب التسرب النوعية وتستخدمها لتحسين ميزات المنتج الأساسية؟","ما هي القوانين الدولية الصارمة (مثل مبادرة Click-to-Cancel الفيدرالية وقوانين الاتحاد الأوروبي) ضد تعقيد الإلغاء؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Dark Patterns in UX and Deceptive Design","url":"https://www.nngroup.com/articles/deceptive-design/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم تجربة إيقاف وإلغاء الاشتراك (Offboarding) باحترام وتتجنب الأنماط المظلمة (Dark Patterns)؟' or l.short_answer is distinct from 'بجعل زر إلغاء الحساب واضحاً وسهل الوصول ومباشراً بخطوات قليلة ومحترمة، وسؤال المستخدم عن سبب المغادرة بلطف، دون استخدام حيل الإخفاء أو الخداع النفسي (Roach Motel).' or l.explanation is distinct from 'الأنماط المظلمة مثل إجبار المستخدم على الاتصال برقم هاتفي لإلغاء الاشتراك أو إخفاء رابط الإلغاء بلون باهت في تذييل الصفحة وتمريره عبر 10 صفحات تأكيد معقدة (Confirmshaming) قد تؤخر التسرب مؤقتاً، لكنها تدمر سمعة الشركة وتضمن عدم عودة المستخدم للأبد. التجربة الراقية تتيح الإلغاء بسهولة بضغطة زر، وتوفر خيارات مرنة كإيقاف الاشتراك مؤقتاً (Pause)، وتقدم تجربة وداع راقية تترك الباب مفتوحاً لعودته مستقبلاً.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام صياغات محرجة وابتزازية عاطفياً في أزرار الإلغاء (مثل: ''نعم، أنا لا أحب توفير المال'').","حجب زر الإلغاء تماماً من التطبيق وإجبار المستخدم على التحدث مع موظف دعم مبيعات متمرس لمنعه."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحلل أسباب التسرب النوعية وتستخدمها لتحسين ميزات المنتج الأساسية؟","ما هي القوانين الدولية الصارمة (مثل مبادرة Click-to-Cancel الفيدرالية وقوانين الاتحاد الأوروبي) ضد تعقيد الإلغاء؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Dark Patterns in UX and Deceptive Design","url":"https://www.nngroup.com/articles/deceptive-design/"}]'::jsonb)) then raise exception 'Question uxpm-009 ar content changed; create a new revision before seeding'; end if; end $$;
