insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما الفرق الجوهري بين التصميم الموجه بالبيانات (Data-Driven) والتصميم المستنير بالبيانات (Data-Informed)؟', 'التصميم الموجه بالبيانات يجعل الأرقام المجردة هي صانع القرار الوحيد والمطلق، بينما التصميم المستنير بالبيانات يعتبر الأرقام مدخلاً مهماً يُدمج مع التعاطف الإنساني وخبرة التصميم وسياق الاستخدام لاتخاذ القرار النهائي.', 'الانصياع الأعمى للبيانات (Data-driven) قد يقود المصمم لجعل زر الموقع أحمر وامضاً وضخماً لأنه حقق أعلى نسبة نقر في تجربة A/B، متجاهلاً أنه أفسد تجربة القراءة ودمر مصداقية العلامة التجارية على المدى البعيد. المصمم المستنير بالبيانات (Data-informed) ينظر للأرقام كإشارات تدل على أين يبحث، ولكنه يستخدم حكمه الإنساني والأخلاقي وأبحاث المستخدمين النوعية لتفسير تلك الأرقام وتطوير حلول مستدامة تخدم البشر والعمل معاً.', null, '["استبدال التفكير الإبداعي والتعاطف مع مشاكل المستخدمين بأرقام لوحات التحكم والتحليلات الآلية فقط.","تجاهل البيانات والإحصائيات تماماً وتصميم الواجهات بناءً على الذوق الشخصي والحدس الفردي البحت."]'::jsonb, '["كيف تتفادى الوقوع في فخ التحسين المحلي الضيق (Local Maximum) على حساب الرؤية الكبرى للمنتج؟","كيف تتواصل مع فرق البيانات ومديري المنتجات لترجمة الأرقام الجافة إلى قرارات إنسانية حكيمة؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Analytics and UX: Better Together","url":"https://www.nngroup.com/articles/analytics-user-experience/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxpm-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxpm-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق الجوهري بين التصميم الموجه بالبيانات (Data-Driven) والتصميم المستنير بالبيانات (Data-Informed)؟' or l.short_answer is distinct from 'التصميم الموجه بالبيانات يجعل الأرقام المجردة هي صانع القرار الوحيد والمطلق، بينما التصميم المستنير بالبيانات يعتبر الأرقام مدخلاً مهماً يُدمج مع التعاطف الإنساني وخبرة التصميم وسياق الاستخدام لاتخاذ القرار النهائي.' or l.explanation is distinct from 'الانصياع الأعمى للبيانات (Data-driven) قد يقود المصمم لجعل زر الموقع أحمر وامضاً وضخماً لأنه حقق أعلى نسبة نقر في تجربة A/B، متجاهلاً أنه أفسد تجربة القراءة ودمر مصداقية العلامة التجارية على المدى البعيد. المصمم المستنير بالبيانات (Data-informed) ينظر للأرقام كإشارات تدل على أين يبحث، ولكنه يستخدم حكمه الإنساني والأخلاقي وأبحاث المستخدمين النوعية لتفسير تلك الأرقام وتطوير حلول مستدامة تخدم البشر والعمل معاً.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استبدال التفكير الإبداعي والتعاطف مع مشاكل المستخدمين بأرقام لوحات التحكم والتحليلات الآلية فقط.","تجاهل البيانات والإحصائيات تماماً وتصميم الواجهات بناءً على الذوق الشخصي والحدس الفردي البحت."]'::jsonb or l.follow_up_questions is distinct from '["كيف تتفادى الوقوع في فخ التحسين المحلي الضيق (Local Maximum) على حساب الرؤية الكبرى للمنتج؟","كيف تتواصل مع فرق البيانات ومديري المنتجات لترجمة الأرقام الجافة إلى قرارات إنسانية حكيمة؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Analytics and UX: Better Together","url":"https://www.nngroup.com/articles/analytics-user-experience/"}]'::jsonb)) then raise exception 'Question uxpm-010 ar content changed; create a new revision before seeding'; end if; end $$;
