insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين الفلسفة الجوهرية لإرشادات آبل (Apple HIG) وإرشادات جوجل (Material Design 3 - Material You)؟', 'تركز Apple HIG على الوضوح وتراجع الواجهة لمصلحة المحتوى والعمق المستند إلى الخامات الفيزيائية (Materials & Vibrancy)، بينما Material Design 3 تركز على التعبير الشخصي والألوان الديناميكية المستخرجة من خلفية المستخدم (Color Extraction) والأسطح المرتفعة الصريحة.', 'فلسفة Apple تقوم على: 1) الوضوح (Clarity): النص مقروء في كل الأحجام والأيقونات دقيقة. 2) التقدير (Deference): واجهة النظام لا تنافس محتوى المستخدم بل تبرزه. 3) العمق (Depth): طبقات زجاجية تعبر عن التسلسل الهرمي. بالمقابل، Material Design 3 أحدثت ثورة عبر نظام الألوان الديناميكية (Dynamic Color) حيث تتكيف كل أزرار وعناصر التطبيق تلقائياً مع لوحة ألوان خلفية شاشة المستخدم، مع أشكال أزرار بيضاوية ضخمة واستخدام جريء للمساحات.', null, '["نسخ واجهة مستخدم مصممة لـ iOS وتصديرها لتطبيق أندرويد بحذافيرها والعكس، مما يربك المستخدمين.","تجاهل معايير خطوط النظام الافتراضية (San Francisco في آبل و Roboto في جوجل) دون بديل عالي التوافق."]'::jsonb, '["كيف تترجم الهوية البصرية لعلامتك التجارية لتعيش بانسجام داخل بيئتي iOS و Android دون أن تفقد طابعها؟","ما هي الفروق في تصميم شريط العناوين العلوي (Top App Bar vs Navigation Bar) بين المنصتين؟"]'::jsonb, '[{"title":"Apple Developer — Human Interface Guidelines Overview","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين الفلسفة الجوهرية لإرشادات آبل (Apple HIG) وإرشادات جوجل (Material Design 3 - Material You)؟' or l.short_answer is distinct from 'تركز Apple HIG على الوضوح وتراجع الواجهة لمصلحة المحتوى والعمق المستند إلى الخامات الفيزيائية (Materials & Vibrancy)، بينما Material Design 3 تركز على التعبير الشخصي والألوان الديناميكية المستخرجة من خلفية المستخدم (Color Extraction) والأسطح المرتفعة الصريحة.' or l.explanation is distinct from 'فلسفة Apple تقوم على: 1) الوضوح (Clarity): النص مقروء في كل الأحجام والأيقونات دقيقة. 2) التقدير (Deference): واجهة النظام لا تنافس محتوى المستخدم بل تبرزه. 3) العمق (Depth): طبقات زجاجية تعبر عن التسلسل الهرمي. بالمقابل، Material Design 3 أحدثت ثورة عبر نظام الألوان الديناميكية (Dynamic Color) حيث تتكيف كل أزرار وعناصر التطبيق تلقائياً مع لوحة ألوان خلفية شاشة المستخدم، مع أشكال أزرار بيضاوية ضخمة واستخدام جريء للمساحات.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["نسخ واجهة مستخدم مصممة لـ iOS وتصديرها لتطبيق أندرويد بحذافيرها والعكس، مما يربك المستخدمين.","تجاهل معايير خطوط النظام الافتراضية (San Francisco في آبل و Roboto في جوجل) دون بديل عالي التوافق."]'::jsonb or l.follow_up_questions is distinct from '["كيف تترجم الهوية البصرية لعلامتك التجارية لتعيش بانسجام داخل بيئتي iOS و Android دون أن تفقد طابعها؟","ما هي الفروق في تصميم شريط العناوين العلوي (Top App Bar vs Navigation Bar) بين المنصتين؟"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Human Interface Guidelines Overview","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxmg-001 ar content changed; create a new revision before seeding'; end if; end $$;
