insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي منطقة الإبهام (Thumb Zone) وكيف تصمم واجهات هواتف مريحة للاستخدام بيد واحدة؟', 'هي النطاق الطبيعي الذي يمكن لإبهام المستخدم الوصول إليه على شاشة الهاتف بسهولة ودون الحاجة لتغيير قبضة يده أو استخدام اليد الأخرى؛ وتقسم إلى: منطقة سهلة (Natural)، ومنطقة مجهدة (Stretch)، ومنطقة صعبة الوصول (Hard).', 'أبحاث ستيفن هوبر (Steven Hoober) أثبتت أن أكثر من 49% من الأشخاص يمسكون هواتفهم بيد واحدة ويعتمدون كلياً على الإبهام للتفاعل. مع زيادة أحجام الهواتف الحديثة، أصبحت الزوايا العلوية للشاشة مناطق خطرة تتطلب جهداً كبيراً. التصميم المريح يضع أزرار الإجراءات الأساسية، وحقول البحث، وأشرطة الملاحة، والقوائم السفلية في النصف السفلي من الشاشة (المنطقة الطبيعية السهلة).', null, '["وضع زر الحفظ أو المتابعة الأساسي في أقصى الزاوية العلوية اليمنى أو اليسرى للهاتف.","إجبار المستخدم على التمدد بأصابعه للأعلى في كل شاشة لإتمام إجراءات روتينية متكررة."]'::jsonb, '["كيف تطبق شركات مثل Samsung (One UI) مفهوم ''مساحة المشاهدة في الأعلى ومساحة التفاعل في الأسفل''؟","كيف يؤثر اختلاف المستخدمين في استخدام اليد اليمنى مقابل اليد اليسرى على تصميم مناطق اللمس؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Mobile Thumb Zone and One-Handed Ergonomics","url":"https://www.nngroup.com/articles/mobile-navigation-patterns/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي منطقة الإبهام (Thumb Zone) وكيف تصمم واجهات هواتف مريحة للاستخدام بيد واحدة؟' or l.short_answer is distinct from 'هي النطاق الطبيعي الذي يمكن لإبهام المستخدم الوصول إليه على شاشة الهاتف بسهولة ودون الحاجة لتغيير قبضة يده أو استخدام اليد الأخرى؛ وتقسم إلى: منطقة سهلة (Natural)، ومنطقة مجهدة (Stretch)، ومنطقة صعبة الوصول (Hard).' or l.explanation is distinct from 'أبحاث ستيفن هوبر (Steven Hoober) أثبتت أن أكثر من 49% من الأشخاص يمسكون هواتفهم بيد واحدة ويعتمدون كلياً على الإبهام للتفاعل. مع زيادة أحجام الهواتف الحديثة، أصبحت الزوايا العلوية للشاشة مناطق خطرة تتطلب جهداً كبيراً. التصميم المريح يضع أزرار الإجراءات الأساسية، وحقول البحث، وأشرطة الملاحة، والقوائم السفلية في النصف السفلي من الشاشة (المنطقة الطبيعية السهلة).' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع زر الحفظ أو المتابعة الأساسي في أقصى الزاوية العلوية اليمنى أو اليسرى للهاتف.","إجبار المستخدم على التمدد بأصابعه للأعلى في كل شاشة لإتمام إجراءات روتينية متكررة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تطبق شركات مثل Samsung (One UI) مفهوم ''مساحة المشاهدة في الأعلى ومساحة التفاعل في الأسفل''؟","كيف يؤثر اختلاف المستخدمين في استخدام اليد اليمنى مقابل اليد اليسرى على تصميم مناطق اللمس؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Mobile Thumb Zone and One-Handed Ergonomics","url":"https://www.nngroup.com/articles/mobile-navigation-patterns/"}]'::jsonb)) then raise exception 'Question uxmg-002 ar content changed; create a new revision before seeding'; end if; end $$;
