insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم واجهات تحترم مساحات الأمان (Safe Area Insets) والجزيرة التفاعلية (Dynamic Island) وحواف الشاشات؟', 'بفصل خلفية الشاشة (التي يجب أن تمتد بحرية إلى الحواف المطلقة للشاشة Edge-to-Edge) عن العناصر التفاعلية والنصوص التي يجب حصرها داخل حدود منطقة الأمان (Safe Area) لمنع حجبها بواسطة النتوءات وزوايا الشاشات الدائرية وشريط التنقل السفلي للنظام.', 'الهواتف الحديثة تخلت عن الحواف المستقيمة وأصبحت تحتوي على زوايا دائرية، شريط إيماءات العودة للشاشة الرئيسية في الأسفل (Home Indicator)، والجزيرة التفاعلية (Dynamic Island) أو ثقب الكاميرا في الأعلى. يجب أن تتمدد ألوان الخلفيات والصور لتملأ كامل الشاشة، بينما تبقى الأزرار والنصوص داخل الهوامش الآمنة حتى لا تتداخل مع مؤشرات النظام أو تصبح عصية على النقر.', null, '["وضع أزرار النقر قريبة جداً من شريط Home Bar السفلي في الآيفون مما يؤدي لخروج المستخدم من التطبيق بالخطأ عند محاولة الضغط عليها.","قص المحتوى الهام أو الشعارات خلف فتحة الكاميرا الأمامية أو النتوء العلوي (Notch)."]'::jsonb, '["كيف تصمم أنشطة حية (Live Activities) تتكامل بانسيابية مع الـ Dynamic Island في iOS؟","ما هي معايير Android 14 و 15 الصارمة لفرض تجربة الشاشة الكاملة الحقيقية (Edge-to-Edge by default)؟"]'::jsonb, '[{"title":"Apple Developer — Designing for the Safe Area and Dynamic Island","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم واجهات تحترم مساحات الأمان (Safe Area Insets) والجزيرة التفاعلية (Dynamic Island) وحواف الشاشات؟' or l.short_answer is distinct from 'بفصل خلفية الشاشة (التي يجب أن تمتد بحرية إلى الحواف المطلقة للشاشة Edge-to-Edge) عن العناصر التفاعلية والنصوص التي يجب حصرها داخل حدود منطقة الأمان (Safe Area) لمنع حجبها بواسطة النتوءات وزوايا الشاشات الدائرية وشريط التنقل السفلي للنظام.' or l.explanation is distinct from 'الهواتف الحديثة تخلت عن الحواف المستقيمة وأصبحت تحتوي على زوايا دائرية، شريط إيماءات العودة للشاشة الرئيسية في الأسفل (Home Indicator)، والجزيرة التفاعلية (Dynamic Island) أو ثقب الكاميرا في الأعلى. يجب أن تتمدد ألوان الخلفيات والصور لتملأ كامل الشاشة، بينما تبقى الأزرار والنصوص داخل الهوامش الآمنة حتى لا تتداخل مع مؤشرات النظام أو تصبح عصية على النقر.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع أزرار النقر قريبة جداً من شريط Home Bar السفلي في الآيفون مما يؤدي لخروج المستخدم من التطبيق بالخطأ عند محاولة الضغط عليها.","قص المحتوى الهام أو الشعارات خلف فتحة الكاميرا الأمامية أو النتوء العلوي (Notch)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم أنشطة حية (Live Activities) تتكامل بانسيابية مع الـ Dynamic Island في iOS؟","ما هي معايير Android 14 و 15 الصارمة لفرض تجربة الشاشة الكاملة الحقيقية (Edge-to-Edge by default)؟"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Designing for the Safe Area and Dynamic Island","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxmg-003 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Safe Area Insets And Dynamic Island Design?', 'This question checks the core Safe Area Insets And Dynamic Island Design concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Safe Area Insets And Dynamic Island Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Safe Area Insets And Dynamic Island Design (point 1).","Missing the key trade-off in Safe Area Insets And Dynamic Island Design (point 2)."]'::jsonb, '["How would you apply Safe Area Insets And Dynamic Island Design in a production Product Design app (follow-up 1)?","How would you apply Safe Area Insets And Dynamic Island Design in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Apple Developer — Designing for the Safe Area and Dynamic Island","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-003' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Safe Area Insets And Dynamic Island Design?' or l.short_answer is distinct from 'This question checks the core Safe Area Insets And Dynamic Island Design concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Safe Area Insets And Dynamic Island Design with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Safe Area Insets And Dynamic Island Design (point 1).","Missing the key trade-off in Safe Area Insets And Dynamic Island Design (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Safe Area Insets And Dynamic Island Design in a production Product Design app (follow-up 1)?","How would you apply Safe Area Insets And Dynamic Island Design in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Designing for the Safe Area and Dynamic Island","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxmg-003 en content changed; create a new revision before seeding'; end if; end $$;
