insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'قارن بين سلوك الرجوع في iOS (Swipe from edge) وسلوك الرجوع التنبؤي في أندرويد (Predictive Back Gesture)؟', 'في iOS يتم الرجوع بالسحب من الحافة اليسرى للشاشة ويكشف الشاشة السابقة تفاعلياً، بينما في Android الحديث يتيح السحب من أي من الحافتين مع ميزة المعاينة التنبؤية (Predictive Back) التي توضح للمستخدم وجهته قبل أن يحرر إصبعه.', 'الرجوع التنبؤي في Android يحل مشكلة تاريخية شائعة: هل سيؤدي الرجوع إلى إغلاق التطبيق والعودة للشاشة الرئيسية أم العودة للصفحة السابقة؟ بفضل المعاينة الحركية، تنكمش الشاشة الحالية لتكشف ما وراءها، فإذا رأى المستخدم شاشة الهاتف الرئيسية وأراد البقاء في التطبيق، يمكنه ببساطة إلغاء السحب دون مغادرة التطبيق. يجب على المصممين تجنب وضع عناصر تمرير أفقية عند حواف الشاشة تتعارض مع إيماءة الرجوع.', null, '["وضع معرض صور أفقي (Carousel) يلتصق بحافة الشاشة تماماً مما يجعل سحب الصور يتداخل مع إيماءة الرجوع للنظام.","تعطيل إيماءة الرجوع بالسحب في شاشات iOS وإجبار المستخدم على النقر على سهم الرجوع العلوي الصغير فقط."]'::jsonb, '["كيف تصمم تنبيهاً لتأكيد الخروج عندما يحتوي النموذج الحالي على بيانات غير محفوظة أثناء إيماءة الرجوع؟","ما هي المعايير الخاصة بتسلسل التنقل الهرمي (Hierarchical) مقابل التنقل التاريخي (Historical) في تطبيقات الجوال؟"]'::jsonb, '[{"title":"Material Design — Predictive Back Design and Navigation","url":"https://material.io/design/navigation/understanding-navigation.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'قارن بين سلوك الرجوع في iOS (Swipe from edge) وسلوك الرجوع التنبؤي في أندرويد (Predictive Back Gesture)؟' or l.short_answer is distinct from 'في iOS يتم الرجوع بالسحب من الحافة اليسرى للشاشة ويكشف الشاشة السابقة تفاعلياً، بينما في Android الحديث يتيح السحب من أي من الحافتين مع ميزة المعاينة التنبؤية (Predictive Back) التي توضح للمستخدم وجهته قبل أن يحرر إصبعه.' or l.explanation is distinct from 'الرجوع التنبؤي في Android يحل مشكلة تاريخية شائعة: هل سيؤدي الرجوع إلى إغلاق التطبيق والعودة للشاشة الرئيسية أم العودة للصفحة السابقة؟ بفضل المعاينة الحركية، تنكمش الشاشة الحالية لتكشف ما وراءها، فإذا رأى المستخدم شاشة الهاتف الرئيسية وأراد البقاء في التطبيق، يمكنه ببساطة إلغاء السحب دون مغادرة التطبيق. يجب على المصممين تجنب وضع عناصر تمرير أفقية عند حواف الشاشة تتعارض مع إيماءة الرجوع.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع معرض صور أفقي (Carousel) يلتصق بحافة الشاشة تماماً مما يجعل سحب الصور يتداخل مع إيماءة الرجوع للنظام.","تعطيل إيماءة الرجوع بالسحب في شاشات iOS وإجبار المستخدم على النقر على سهم الرجوع العلوي الصغير فقط."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم تنبيهاً لتأكيد الخروج عندما يحتوي النموذج الحالي على بيانات غير محفوظة أثناء إيماءة الرجوع؟","ما هي المعايير الخاصة بتسلسل التنقل الهرمي (Hierarchical) مقابل التنقل التاريخي (Historical) في تطبيقات الجوال؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Predictive Back Design and Navigation","url":"https://material.io/design/navigation/understanding-navigation.html"}]'::jsonb)) then raise exception 'Question uxmg-004 ar content changed; create a new revision before seeding'; end if; end $$;
