insert into public.interview_questions (id, slug, track_id, difficulty) values ('uxmg-005', 'bottom-sheets-modal-vs-persistent-vs-expandable', 'ui-ux', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('uxmg-005', 1, 'draft', '2026-09-07') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي اللوحات السفلية (Bottom Sheets) وما الفرق بين اللوحة المؤقتة (Modal) والثابتة (Persistent)؟', 'اللوحة السفلية المؤقتة (Modal Bottom Sheet) تنبثق فوق المحتوى مع تعتيم الخلفية لإنجاز مهمة فورية وتمنع التفاعل مع باقي الشاشة، بينما اللوحة الثابتة (Persistent / Standard) تظل ظاهرة ومتكاملة مع الشاشة وتسمح بالتفاعل المتزامن مع المحتوى خلفها.', 'الـ Modal Bottom Sheet مثالية للقوائم السريعة، وخيارات المشاركة، وتأكيد الإجراءات؛ لأنها تظهر في نطاق الإبهام وتغلق بسهولة بالسحب لأسفل. أما اللوحة الثابتة أو القابلة للتمدد (مثل مشغل الموسيقى المصغر في Spotify أو بطاقة مسار الرحلة في Google Maps) فتسمح للمستخدم برؤية الخريطة والتنقل فيها بينما تظل اللوحة السفلية قابلة للسحب لأعلى لمعرفة تفاصيل المسار الكاملة دون حجب التجربة.', null, '["استخدام Bottom Sheet لعمليات طويلة ومعقدة تتطلب نماذج إدخال متفرعة يسهل إغلاقها بالخطأ وفقدان البيانات.","إهمال إضافة مقبض سحب بصري (Drag Handle) في أعلى اللوحة لإرشاد المستخدم بإمكانية سحبها وإغلاقها."]'::jsonb, '["كيف تمنع التعارض بين التمرير الداخلي لمحتوى اللوحة وإيماءة سحب اللوحة لإغلاقها؟","ما هي نقاط التوقف (Detents: Large, Medium, Custom) المعتمدة في تصميم اللوحات السفلية على iOS؟"]'::jsonb, '[{"title":"Material Design — Bottom Sheets: Types and Interactions","url":"https://material.io/components/bottom-sheets"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي اللوحات السفلية (Bottom Sheets) وما الفرق بين اللوحة المؤقتة (Modal) والثابتة (Persistent)؟' or l.short_answer is distinct from 'اللوحة السفلية المؤقتة (Modal Bottom Sheet) تنبثق فوق المحتوى مع تعتيم الخلفية لإنجاز مهمة فورية وتمنع التفاعل مع باقي الشاشة، بينما اللوحة الثابتة (Persistent / Standard) تظل ظاهرة ومتكاملة مع الشاشة وتسمح بالتفاعل المتزامن مع المحتوى خلفها.' or l.explanation is distinct from 'الـ Modal Bottom Sheet مثالية للقوائم السريعة، وخيارات المشاركة، وتأكيد الإجراءات؛ لأنها تظهر في نطاق الإبهام وتغلق بسهولة بالسحب لأسفل. أما اللوحة الثابتة أو القابلة للتمدد (مثل مشغل الموسيقى المصغر في Spotify أو بطاقة مسار الرحلة في Google Maps) فتسمح للمستخدم برؤية الخريطة والتنقل فيها بينما تظل اللوحة السفلية قابلة للسحب لأعلى لمعرفة تفاصيل المسار الكاملة دون حجب التجربة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام Bottom Sheet لعمليات طويلة ومعقدة تتطلب نماذج إدخال متفرعة يسهل إغلاقها بالخطأ وفقدان البيانات.","إهمال إضافة مقبض سحب بصري (Drag Handle) في أعلى اللوحة لإرشاد المستخدم بإمكانية سحبها وإغلاقها."]'::jsonb or l.follow_up_questions is distinct from '["كيف تمنع التعارض بين التمرير الداخلي لمحتوى اللوحة وإيماءة سحب اللوحة لإغلاقها؟","ما هي نقاط التوقف (Detents: Large, Medium, Custom) المعتمدة في تصميم اللوحات السفلية على iOS؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Bottom Sheets: Types and Interactions","url":"https://material.io/components/bottom-sheets"}]'::jsonb)) then raise exception 'Question uxmg-005 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Bottom Sheets Modal Vs Persistent Vs Expandable?', 'This question checks the core Bottom Sheets Modal Vs Persistent Vs Expandable concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Bottom Sheets Modal Vs Persistent Vs Expandable with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Bottom Sheets Modal Vs Persistent Vs Expandable (point 1).","Missing the key trade-off in Bottom Sheets Modal Vs Persistent Vs Expandable (point 2)."]'::jsonb, '["How would you apply Bottom Sheets Modal Vs Persistent Vs Expandable in a production Product Design app (follow-up 1)?","How would you apply Bottom Sheets Modal Vs Persistent Vs Expandable in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Bottom Sheets: Types and Interactions","url":"https://material.io/components/bottom-sheets"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
