insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما هي الفروق الجوهرية في توقعات تجربة المستخدم بين موقع الويب المتجاوب (Responsive Web) والتطبيق الأصيل (Native App)؟', 'يتوقع المستخدم من التطبيق الأصيل استجابة لمسية فورية (60/120fps)، ودعماً للإيماءات السلسة، وعملاً دون اتصال بالإنترنت، واندماجاً مع عتاد الهاتف (الكاميرا، الحساسات، المحفظة الرقمية)، بينما يقبل من موقع الويب وتيرة أهدأ وتركيزاً على الاستهلاك السريع للمعلومات دون تنزيل.', 'تطبيقات الويب تعاني غالباً من تأخير طفيف في استجابة اللمس وتفتقر للتكامل مع إيماءات النظام العميقة. التطبيق الأصيل يملك وصولاً مباشراً للإشعارات الفورية الغنية، والبيومترية الفورية، والملاحة المستقرة بلا إعادة تحميل للصفحات. تصميم التطبيق الأصيل يتطلب احترام عادات المنصة (HIG و Material)، بينما الويب يتيح مساحة أكبر لفرض لغة العلامة التجارية الموحدة عبر كافة المتصفحات.', null, '["تصميم تطبيق أصيل كأنه مجرد Webview يعرض صفحات ويب بطيئة تفتقر للحس الحركي واللمسي للتطبيقات الحقيقية.","مطالبة زوار موقع الويب بتحميل التطبيق فور فتح أول صفحة بحجب الشاشة بلافتات إجبارية مزعجة."]'::jsonb, '["ما هي تطبيقات الويب التقدمية (PWA) وأين تقف بين الويب والتطبيقات الأصيلة في تجربة المستخدم؟","كيف توازن بين تكلفة تطوير تطبيقين أصيلين مستقلين وبين إطلاق تطبيق هجين متعدد المنصات؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Mobile: Native Apps vs. Responsive Web","url":"https://www.nngroup.com/articles/mobile-native-apps/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما هي الفروق الجوهرية في توقعات تجربة المستخدم بين موقع الويب المتجاوب (Responsive Web) والتطبيق الأصيل (Native App)؟' or l.short_answer is distinct from 'يتوقع المستخدم من التطبيق الأصيل استجابة لمسية فورية (60/120fps)، ودعماً للإيماءات السلسة، وعملاً دون اتصال بالإنترنت، واندماجاً مع عتاد الهاتف (الكاميرا، الحساسات، المحفظة الرقمية)، بينما يقبل من موقع الويب وتيرة أهدأ وتركيزاً على الاستهلاك السريع للمعلومات دون تنزيل.' or l.explanation is distinct from 'تطبيقات الويب تعاني غالباً من تأخير طفيف في استجابة اللمس وتفتقر للتكامل مع إيماءات النظام العميقة. التطبيق الأصيل يملك وصولاً مباشراً للإشعارات الفورية الغنية، والبيومترية الفورية، والملاحة المستقرة بلا إعادة تحميل للصفحات. تصميم التطبيق الأصيل يتطلب احترام عادات المنصة (HIG و Material)، بينما الويب يتيح مساحة أكبر لفرض لغة العلامة التجارية الموحدة عبر كافة المتصفحات.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تصميم تطبيق أصيل كأنه مجرد Webview يعرض صفحات ويب بطيئة تفتقر للحس الحركي واللمسي للتطبيقات الحقيقية.","مطالبة زوار موقع الويب بتحميل التطبيق فور فتح أول صفحة بحجب الشاشة بلافتات إجبارية مزعجة."]'::jsonb or l.follow_up_questions is distinct from '["ما هي تطبيقات الويب التقدمية (PWA) وأين تقف بين الويب والتطبيقات الأصيلة في تجربة المستخدم؟","كيف توازن بين تكلفة تطوير تطبيقين أصيلين مستقلين وبين إطلاق تطبيق هجين متعدد المنصات؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Mobile: Native Apps vs. Responsive Web","url":"https://www.nngroup.com/articles/mobile-native-apps/"}]'::jsonb)) then raise exception 'Question uxmg-006 ar content changed; create a new revision before seeding'; end if; end $$;
