insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم تجربة طلب صلاحيات الإشعارات (Push Notifications) لتفادي الرفض الفوري الصارم؟', 'باستخدام استراتيجية ''التهيئة المسبقة'' (Permission Priming): عرض شاشة حوار داخلية من التطبيق تشرح القيمة والمزايا الملموسة التي سيجنيها المستخدم أولاً، ولا تطلب إذن النظام الرسمي إلا بعد أن يبدي المستخدم موافقته المبدئية وفي اللحظة السياقية المناسبة.', 'إذا طلبت إذن إرسال الإشعارات عبر نافذة النظام فور أول ثانية لفتح التطبيق، سيرفض أكثر من 70% من المستخدمين الطلب فوراً خوفاً من الإعلانات المزعجة. بمجرد أن يرفض المستخدم إذن النظام الرسمي، يستحيل إظهار النافذة مرة أخرى برمجياً ويجب عليه الذهاب للإعدادات المعقدة يدوياً. الحل هو تأجيل الطلب حتى يحجز المستخدم طلباً ويحتاج لمتابعة وصوله، وتوضيح القيمة: ''سنرسل لك إشعاراً فقط عندما يقترب السائق من منزلك''.', null, '["إطلاق نافذة إذن الإشعارات الرسمية فور ظهور شاشة البداية (Splash Screen) قبل أن يتعرف المستخدم على التطبيق.","إرسال إشعارات تسويقية غير مخصصة في أوقات نوم المستخدمين دون توفير خيارات لتخصيص التفضيلات."]'::jsonb, '["كيف تصمم مركز تفضيلات الإشعارات (Notification Settings Center) داخل التطبيق لمنح المستخدم تحكماً كاملاً؟","ما هي الإشعارات التفاعلية المؤقتة (Time-Sensitive Notifications) وما هي شروط استخدامها في iOS؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Asking for Permission in Mobile Apps","url":"https://www.nngroup.com/articles/permission-requests/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم تجربة طلب صلاحيات الإشعارات (Push Notifications) لتفادي الرفض الفوري الصارم؟' or l.short_answer is distinct from 'باستخدام استراتيجية ''التهيئة المسبقة'' (Permission Priming): عرض شاشة حوار داخلية من التطبيق تشرح القيمة والمزايا الملموسة التي سيجنيها المستخدم أولاً، ولا تطلب إذن النظام الرسمي إلا بعد أن يبدي المستخدم موافقته المبدئية وفي اللحظة السياقية المناسبة.' or l.explanation is distinct from 'إذا طلبت إذن إرسال الإشعارات عبر نافذة النظام فور أول ثانية لفتح التطبيق، سيرفض أكثر من 70% من المستخدمين الطلب فوراً خوفاً من الإعلانات المزعجة. بمجرد أن يرفض المستخدم إذن النظام الرسمي، يستحيل إظهار النافذة مرة أخرى برمجياً ويجب عليه الذهاب للإعدادات المعقدة يدوياً. الحل هو تأجيل الطلب حتى يحجز المستخدم طلباً ويحتاج لمتابعة وصوله، وتوضيح القيمة: ''سنرسل لك إشعاراً فقط عندما يقترب السائق من منزلك''.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إطلاق نافذة إذن الإشعارات الرسمية فور ظهور شاشة البداية (Splash Screen) قبل أن يتعرف المستخدم على التطبيق.","إرسال إشعارات تسويقية غير مخصصة في أوقات نوم المستخدمين دون توفير خيارات لتخصيص التفضيلات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم مركز تفضيلات الإشعارات (Notification Settings Center) داخل التطبيق لمنح المستخدم تحكماً كاملاً؟","ما هي الإشعارات التفاعلية المؤقتة (Time-Sensitive Notifications) وما هي شروط استخدامها في iOS؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Asking for Permission in Mobile Apps","url":"https://www.nngroup.com/articles/permission-requests/"}]'::jsonb)) then raise exception 'Question uxmg-007 ar content changed; create a new revision before seeding'; end if; end $$;
