insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم واجهات تكيفية متقدمة (Adaptive Layouts) تدعم الأجهزة اللوحية والشاشات القابلة للطي (Foldables)؟', 'بتصميم واجهات تنتقل بذكاء من العرض أحادي العمود في وضع الهاتف المطوي إلى التخطيط متعدد الأعمدة (List-Detail / Master-Detail Split View) عند فتح الشاشة الكبيرة، بدلاً من مجرد مد وتكبير عناصر الهاتف لتملأ الفراغ.', 'الشاشات الكبيرة كالأجهزة اللوحية والهواتف القابلة للطي (Foldables) توفر مساحة عرض تفاعلية رحبة. إذا قمت بتكبير بطاقة الهاتف لتمتد بعرض 12 بوصة، ستبدو مروعة ومشتتة. التصميم التكيفي الحقيقي يعرض قائمة العناصر في العمود الأيمن والتفاصيل الكاملة فوراً في العمود الأيسر، مستفيداً من الشاشتين في آن واحد، ومراعياً خط الطي المادي (Hinge Position) لضمان عدم وقوع النصوص أو الأزرار فوق المفصلة الفيزيائية.', null, '["مد عناصر الهاتف الصغيرة وأزراره عبر شاشات الآيباد الكبيرة مما يخلق مساحات فارغة قبيحة وغير مريحة للنقر.","تجاهل اختبار التطبيق أثناء عملية فتح وقفل الشاشة الحية (Fold / Unfold Transitions) مما يسبب إعادة تشغيل الصفحة وفقدان البيانات."]'::jsonb, '["ما هي نقاط التوقف التكيفية (Window Size Classes: Compact, Medium, Expanded) في معايير Material Design؟","كيف تصمم تجارب تعدد المهام وتقسيم الشاشة المتزامن (Split Screen Multi-tasking) باحتراف؟"]'::jsonb, '[{"title":"Material Design — Layout: Window Size Classes and Large Screens","url":"https://material.io/design/layout/responsive-layout-grid.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم واجهات تكيفية متقدمة (Adaptive Layouts) تدعم الأجهزة اللوحية والشاشات القابلة للطي (Foldables)؟' or l.short_answer is distinct from 'بتصميم واجهات تنتقل بذكاء من العرض أحادي العمود في وضع الهاتف المطوي إلى التخطيط متعدد الأعمدة (List-Detail / Master-Detail Split View) عند فتح الشاشة الكبيرة، بدلاً من مجرد مد وتكبير عناصر الهاتف لتملأ الفراغ.' or l.explanation is distinct from 'الشاشات الكبيرة كالأجهزة اللوحية والهواتف القابلة للطي (Foldables) توفر مساحة عرض تفاعلية رحبة. إذا قمت بتكبير بطاقة الهاتف لتمتد بعرض 12 بوصة، ستبدو مروعة ومشتتة. التصميم التكيفي الحقيقي يعرض قائمة العناصر في العمود الأيمن والتفاصيل الكاملة فوراً في العمود الأيسر، مستفيداً من الشاشتين في آن واحد، ومراعياً خط الطي المادي (Hinge Position) لضمان عدم وقوع النصوص أو الأزرار فوق المفصلة الفيزيائية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["مد عناصر الهاتف الصغيرة وأزراره عبر شاشات الآيباد الكبيرة مما يخلق مساحات فارغة قبيحة وغير مريحة للنقر.","تجاهل اختبار التطبيق أثناء عملية فتح وقفل الشاشة الحية (Fold / Unfold Transitions) مما يسبب إعادة تشغيل الصفحة وفقدان البيانات."]'::jsonb or l.follow_up_questions is distinct from '["ما هي نقاط التوقف التكيفية (Window Size Classes: Compact, Medium, Expanded) في معايير Material Design؟","كيف تصمم تجارب تعدد المهام وتقسيم الشاشة المتزامن (Split Screen Multi-tasking) باحتراف؟"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Layout: Window Size Classes and Large Screens","url":"https://material.io/design/layout/responsive-layout-grid.html"}]'::jsonb)) then raise exception 'Question uxmg-008 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Adaptive Layouts Tablets Foldables And Split Views?', 'This question checks the core Adaptive Layouts Tablets Foldables And Split Views concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Adaptive Layouts Tablets Foldables And Split Views with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Adaptive Layouts Tablets Foldables And Split Views (point 1).","Missing the key trade-off in Adaptive Layouts Tablets Foldables And Split Views (point 2)."]'::jsonb, '["How would you apply Adaptive Layouts Tablets Foldables And Split Views in a production Product Design app (follow-up 1)?","How would you apply Adaptive Layouts Tablets Foldables And Split Views in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Material Design — Layout: Window Size Classes and Large Screens","url":"https://material.io/design/layout/responsive-layout-grid.html"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-008' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a UI/UX developer know about Adaptive Layouts Tablets Foldables And Split Views?' or l.short_answer is distinct from 'This question checks the core Adaptive Layouts Tablets Foldables And Split Views concept and how to use it safely in UI/UX design, user research, and design systems.' or l.explanation is distinct from 'Explain Adaptive Layouts Tablets Foldables And Split Views with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["Missing the key trade-off in Adaptive Layouts Tablets Foldables And Split Views (point 1).","Missing the key trade-off in Adaptive Layouts Tablets Foldables And Split Views (point 2)."]'::jsonb or l.follow_up_questions is distinct from '["How would you apply Adaptive Layouts Tablets Foldables And Split Views in a production Product Design app (follow-up 1)?","How would you apply Adaptive Layouts Tablets Foldables And Split Views in a production Product Design app (follow-up 2)?"]'::jsonb or l.sources is distinct from '[{"title":"Material Design — Layout: Window Size Classes and Large Screens","url":"https://material.io/design/layout/responsive-layout-grid.html"}]'::jsonb)) then raise exception 'Question uxmg-008 en content changed; create a new revision before seeding'; end if; end $$;
