insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم تجربة المصادقة البيومترية (Face ID / Fingerprint) وتدير مسارات التراجع والبدائل بأمان؟', 'بجعل المصادقة البيومترية خيار تسريع اختياري للمستخدم وليس بديلاً مطلقاً عن كلمة المرور، مع توفير زر تراجع بديهي وسريع لإدخال رمز المرور (PIN/Password) فور فشل التعرف على الوجه أو البصمة.', 'البيومترية تفشل في مواقف كثيرة واقعية: ارتداء قناع، الإضاءة الخافتة، الأيدي المبللة، أو استخدام الهاتف بزاوية مائلة على المكتب. التصميم السلس يجب أن يقدم محاولة التعرف تلقائياً مع زر فوري: ''إدخال رمز المرور''. عند تفعيل ميزة حساسة (مثل أول تحويل مالي بعد تغيير الهاتف)، يجب طلب رمز المرور الأساسي لتعزيز الأمان والتأكد من هوية صاحب الحساب.', null, '["حظر المستخدم أو قفل الحساب فور محاولة بيومترية فاشلة واحدة دون إتاحة إدخال كلمة السر فوراً.","تفعيل المصادقة بالبصمة أو الوجه تلقائياً دون استئذان المستخدم أو شرح كيفية تعطيلها من الإعدادات."]'::jsonb, '["كيف تسهم مفاتيح المرور الرقمية (Passkeys) في إعادة تشكيل تجربة تسجيل الدخول عبر المنصات؟","ما هي أفضل ممارسات تصميم شاشات التحقق بخطوتين (2FA) وتعبئة رموز الرسائل تلقائياً؟"]'::jsonb, '[{"title":"Apple Developer — Authenticating with Face ID and Touch ID","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم تجربة المصادقة البيومترية (Face ID / Fingerprint) وتدير مسارات التراجع والبدائل بأمان؟' or l.short_answer is distinct from 'بجعل المصادقة البيومترية خيار تسريع اختياري للمستخدم وليس بديلاً مطلقاً عن كلمة المرور، مع توفير زر تراجع بديهي وسريع لإدخال رمز المرور (PIN/Password) فور فشل التعرف على الوجه أو البصمة.' or l.explanation is distinct from 'البيومترية تفشل في مواقف كثيرة واقعية: ارتداء قناع، الإضاءة الخافتة، الأيدي المبللة، أو استخدام الهاتف بزاوية مائلة على المكتب. التصميم السلس يجب أن يقدم محاولة التعرف تلقائياً مع زر فوري: ''إدخال رمز المرور''. عند تفعيل ميزة حساسة (مثل أول تحويل مالي بعد تغيير الهاتف)، يجب طلب رمز المرور الأساسي لتعزيز الأمان والتأكد من هوية صاحب الحساب.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["حظر المستخدم أو قفل الحساب فور محاولة بيومترية فاشلة واحدة دون إتاحة إدخال كلمة السر فوراً.","تفعيل المصادقة بالبصمة أو الوجه تلقائياً دون استئذان المستخدم أو شرح كيفية تعطيلها من الإعدادات."]'::jsonb or l.follow_up_questions is distinct from '["كيف تسهم مفاتيح المرور الرقمية (Passkeys) في إعادة تشكيل تجربة تسجيل الدخول عبر المنصات؟","ما هي أفضل ممارسات تصميم شاشات التحقق بخطوتين (2FA) وتعبئة رموز الرسائل تلقائياً؟"]'::jsonb or l.sources is distinct from '[{"title":"Apple Developer — Authenticating with Face ID and Touch ID","url":"https://developer.apple.com/design/human-interface-guidelines/"}]'::jsonb)) then raise exception 'Question uxmg-009 ar content changed; create a new revision before seeding'; end if; end $$;
