insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تصمم تجربة مستخدم تعمل في وضع عدم الاتصال أولاً (Offline-First UX) وتوضح حالات المزامنة؟', 'بتمكين المستخدم من تصفح البيانات المخزنة محلياً بالكامل وإجراء التعديلات والإنشاء في وضع عدم الاتصال عبر واجهة تفاؤلية (Optimistic UI)، مع إظهار مؤشر مزامنة هادئ يوضح حالة حفظ البيانات ومزامنتها عند عودة الإنترنت.', 'في الهواتف، انقطاع الإنترنت ليس حدثاً استثنائياً، بل هو واقع يومي في المصاعد ومحطات المترو وأثناء السفر. التطبيق المحترف لا يعرض شاشة حظر خطأ حمراء تطرد المستخدم؛ بل يسمح له بكتابة رسالته أو إعداد مشروعه وتخزينه في قائمة الانتظار المحلية (Local Outbox)، مع إشارة لطيفة: ''تم الحفظ محلياً - ستتم المزامنة فور الاتصال''. هذا يمنح المستخدم شعوراً بالأمان والإنتاجية غير المنقطعة.', null, '["تعطيل إمكانية فتح التطبيق أو تصفح المحتوى الذي تم تنزيله مسبقاً لمجرد فقدان الاتصال بالشبكة.","مسح التعديلات التي قام بها المستخدم أثناء عدم الاتصال أو الكتابة فوقها دون إشعار واضح لحل النزاع (Conflict Resolution)."]'::jsonb, '["كيف تصمم واجهات حل نزاع تعديل البيانات (Merge Conflict Resolution) عندما تتصادم التعديلات المحلية مع السيرفر؟","ما هي أفضل ممارسات إشعار المستخدم بالانتقال التلقائي بين شبكة Wi-Fi وبيانات الهاتف المحمول؟"]'::jsonb, '[{"title":"Nielsen Norman Group — Mobile UX in Offline Mode","url":"https://www.nngroup.com/articles/mobile-navigation-patterns/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'uxmg-010' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف تصمم تجربة مستخدم تعمل في وضع عدم الاتصال أولاً (Offline-First UX) وتوضح حالات المزامنة؟' or l.short_answer is distinct from 'بتمكين المستخدم من تصفح البيانات المخزنة محلياً بالكامل وإجراء التعديلات والإنشاء في وضع عدم الاتصال عبر واجهة تفاؤلية (Optimistic UI)، مع إظهار مؤشر مزامنة هادئ يوضح حالة حفظ البيانات ومزامنتها عند عودة الإنترنت.' or l.explanation is distinct from 'في الهواتف، انقطاع الإنترنت ليس حدثاً استثنائياً، بل هو واقع يومي في المصاعد ومحطات المترو وأثناء السفر. التطبيق المحترف لا يعرض شاشة حظر خطأ حمراء تطرد المستخدم؛ بل يسمح له بكتابة رسالته أو إعداد مشروعه وتخزينه في قائمة الانتظار المحلية (Local Outbox)، مع إشارة لطيفة: ''تم الحفظ محلياً - ستتم المزامنة فور الاتصال''. هذا يمنح المستخدم شعوراً بالأمان والإنتاجية غير المنقطعة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تعطيل إمكانية فتح التطبيق أو تصفح المحتوى الذي تم تنزيله مسبقاً لمجرد فقدان الاتصال بالشبكة.","مسح التعديلات التي قام بها المستخدم أثناء عدم الاتصال أو الكتابة فوقها دون إشعار واضح لحل النزاع (Conflict Resolution)."]'::jsonb or l.follow_up_questions is distinct from '["كيف تصمم واجهات حل نزاع تعديل البيانات (Merge Conflict Resolution) عندما تتصادم التعديلات المحلية مع السيرفر؟","ما هي أفضل ممارسات إشعار المستخدم بالانتقال التلقائي بين شبكة Wi-Fi وبيانات الهاتف المحمول؟"]'::jsonb or l.sources is distinct from '[{"title":"Nielsen Norman Group — Mobile UX in Offline Mode","url":"https://www.nngroup.com/articles/mobile-navigation-patterns/"}]'::jsonb)) then raise exception 'Question uxmg-010 ar content changed; create a new revision before seeding'; end if; end $$;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'en', 'What should a UI/UX developer know about Offline First Mobile Ux And Sync Indicators?', 'This question checks the core Offline First Mobile Ux And Sync Indicators concept and how to use it safely in UI/UX design, user research, and design systems.', 'Explain Offline First Mobile Ux And Sync Indicators with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.', null, '["Missing the key trade-off in Offline First Mobile Ux And Sync Indicators (point 1).","Missing the key trade-off in Offline First Mobile Ux And Sync Indicators (point 2)."]'::jsonb, '["How would you apply Offline First Mobile Ux And Sync Indicators in a production Product Design app (follow-up 1)?","How would you apply Offline First Mobile Ux And Sync Indicators in a production Product Design app (follow-up 2)?"]'::jsonb, '[{"title":"Nielsen Norman Group — Mobile UX in Offline Mode","url":"https://www.nngroup.com/articles/mobile-navigation-patterns/"}]'::jsonb from public.question_revisions r where r.question_id = 'uxmg-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
